
CREATE TABLE juegos_detalle (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL,
  plataforma TEXT,
  nombre TEXT NOT NULL,
  anio INTEGER,
  genero TEXT,
  desarrollador TEXT,
  jugadores INTEGER,
  estilo TEXT,
  gameplay TEXT,
  objetivo TEXT,
  descripcion_corta TEXT,
  descripcion_larga TEXT
);

