INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '89 Dennou Kyuusei Uranai (Japan)', '1989', NaN, 'Sofel', '1', NaN, 'Menu-based fortune telling and astrology simulation.', 'To receive personal divinations and compatibility readings based on user input.', 'A fortune-telling simulator based on Japanese astrology and numerology.', 'This Japan-exclusive title allows players to input their birth date and other personal data to receive astrological predictions. It features various divination methods, including tarot-style readings and personality analysis through a digital interface.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '[Aladdin] Dizzy the Adventurer (USA) (Unl)', '1993', NaN, 'Codemasters', '1-2', NaN, 'Inventory-based adventure platformer with puzzle-solving elements.', 'Rescue Prince Mylo from the evil wizard Zaks'' castle.', 'A handheld-style adventure featuring the egg-shaped hero Dizzy in a magical world.', 'Originally released for the Aladdin Deck Enhancer, this game follows Dizzy as he navigates a fairy-tale land. Players must collect items and use them in the correct locations to overcome obstacles and solve environmental puzzles to progress through the story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '[Aladdin] Fantastic Adventures of Dizzy, The (USA) (Unl)', '1993', NaN, 'Codemasters', '1-2', NaN, 'Open-world adventure platformer featuring item management and puzzles.', 'Rescue Daisy and the rest of the Yolkfolk from the evil wizard Zaks.', 'An expansive adventure game where Dizzy must explore a vast kingdom to save his friends.', 'Considered one of the most complex entries in the series, players guide Dizzy through a large interconnected world. The game requires careful inventory management, as Dizzy can only carry three items at a time, forcing players to prioritize objects needed to solve local puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '[Aladdin] Micro Machines (USA) (Unl)', '1991', NaN, 'Codemasters', '1-2', NaN, 'Top-down miniature vehicular racing with high-speed handling.', 'Finish in the top positions across various household-themed tracks.', 'A fast-paced racing game featuring tiny vehicles in everyday environments.', 'Players control miniature cars, boats, and tanks through tracks set on kitchen tables, desks, and gardens. The game is famous for its off-screen elimination mechanic in multiplayer and its challenging AI that requires precise steering and memorization of shortcuts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '10-Yard Fight (Japan)', '1983', NaN, 'Irem', '1-2', NaN, 'American football simulation with basic offensive and defensive plays.', 'Outscore the opponent to progress through five levels of difficulty.', 'A foundational American football title focusing on arcade-style sports action.', 'Players choose between offensive plays (running or passing) and defensive maneuvers. The game progresses through various ranks from High School to Pro, with the difficulty increasing as the player advances through the season.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '10-Yard Fight (USA, Europe)', '1984', NaN, 'Irem', '1-2', NaN, 'American football simulation with basic offensive and defensive plays.', 'Outscore the opponent to progress through five levels of difficulty.', 'The localized version of the classic arcade-style American football game.', 'Identical to the Japanese release in mechanics, players control a team through various divisions. It features a simplified view of the sport, emphasizing timing and lane positioning rather than complex strategic management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '100 Man Dollar Kid - Maboroshi no Teiou Hen (Japan)', '1989', NaN, 'TOSE', '1', NaN, 'Board game simulation with gambling and trading mechanics.', 'Accumulate a fortune of 100 million dollars through various games of chance.', 'A digital board game focused on high-stakes gambling and financial success.', 'Players navigate a board to participate in different gambling activities and mini-games. The ultimate goal is to become a Mister Dollar by outsmarting opponents and managing luck to reach the titular financial milestone.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '1942 (Japan, USA)', '1985', NaN, 'Capcom', '1-2', NaN, 'Vertical scrolling shoot ''em up with loop-de-loop mechanics.', 'Navigate through enemy-filled skies to reach the end of the stage.', 'A classic WWII-themed shooter where players pilot a P-38 Lightning.', 'Set in the Pacific Theater, players must shoot down waves of enemy aircraft and avoid incoming fire. The game introduced the roll mechanic, allowing the player to temporarily become invincible while performing a loop to evade danger.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '1943 - The Battle of Midway (Japan) (Beta)', '1988', NaN, 'Capcom', '1-2', NaN, 'Vertical scrolling shoot ''em up with energy management and upgrades.', 'Defeat the Japanese naval fleet in the Battle of Midway.', 'A refined WWII shooter featuring a health bar and weapon upgrades.', 'This version represents a pre-release or alternate build of the sequel. It maintains the core vertical shooting action but introduces a Fuel meter that acts as both health and super-weapon energy, requiring players to balance aggression with survival.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '1943 - The Battle of Midway (USA)', '1988', NaN, 'Capcom', '1-2', NaN, 'Vertical scrolling shoot ''em up with energy management and upgrades.', 'Sink the enemy fleet and defeat the massive boss ships.', 'The final US release of the classic WWII naval-aerial combat game.', 'Players fly a P-38 through 16 stages of intense combat. Unlike the first game, players can upgrade their weapons (Auto, 3-Way, Shell) and must manage their energy bar carefully to survive the bullet-filled boss encounters at the end of each mission.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '1943 - The Battle of Valhalla (Japan)', '1991', NaN, 'Capcom', '1-2', NaN, 'Vertical scrolling shoot ''em up with energy-based health system.', 'Destroy the enemy fleet and bosses across various historical stages.', 'The Japanese version of the classic WWII shooter 1943.', 'Known in Japan as 1943: Midway Kai, this version features updated music, colors, and modified level layouts compared to the original arcade port, offering a fresh take on the P-38 Lightning combat experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '1944 (1943 Hack)', '1988', NaN, 'Capcom', '1-2', NaN, 'Vertical scrolling shoot ''em up (Romhack of 1943).', 'Advance through modified levels to defeat enemy forces.', 'A fan-made modification of 1943 intended to simulate a sequel.', 'This is a modified version of 1943 - The Battle of Midway. It typically features palette swaps and altered level designs to create the illusion of a new game in the 19XX series on the NES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '1999 - Hore, Mitakotoka! Seikimatsu (Japan)', 'Hack', NaN, 'Unknown', '1', NaN, 'Board game/Sugoroku style simulation with mini-games.', 'Navigate the board to survive and succeed during the end of the century.', 'A quirky Japanese board game themed around the turn of the millennium.', 'Based on end-of-the-world prophecies popular in the late 90s, players move across a board facing various life events, financial challenges, and mini-games to see who can come out on top by the year 1999.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '2 in 1 Lightgun Game - Tough Cop + Super Tough Cop (Asia) (Unl)', '1999', NaN, 'Unknown', '1', NaN, 'Lightgun-based shooting (Zapper) from a first-person perspective.', 'Apprehend criminals and survive shootouts as a police officer.', 'A compilation of two unlicensed Tough Cop lightgun shooters.', 'These games utilize the NES Zapper. Players take the role of a police officer in urban environments, shooting at criminals who appear on screen while avoiding civilians to clear stages and maintain order.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '3 in 1 Supergun (Asia) (Unl)', '1990', NaN, 'Unlicensed', '1-2', NaN, 'Multi-cart containing three distinct shooting/action games.', 'Complete various challenges across three different titles.', 'An unlicensed compilation of action games designed for lightgun or controller.', 'This Supergun multi-cart typically includes simplified arcade-style games. Like many unlicensed Asian titles, these games focus on high-score chasing and repetitive but challenging gameplay loops.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '3-D Battles of World Runner, The (USA)', '1990', NaN, 'Unlicensed', '1-2', NaN, 'Behind-the-back forward-scrolling action platformer.', 'Run and jump through eight worlds to save Princess DoReMi.', 'A 3D-perspective platformer similar to Space Harrier.', 'Players control Jack the WorldRunner as he runs constantly into the screen. The game features an optional 3D mode (using red/blue glasses) and requires precise jumping over bottomless pits and dodging alien enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '3-D Block (Asia) (Unl) (Hwang Shinwei)', '1987', NaN, 'Square', '1', 3, 'Falling block puzzle game (Tetris clone) with a 3D perspective.', 'Clear lines of blocks to prevent the screen from filling up.', 'An unlicensed 3D-style interpretation of the Tetris formula.', 'Developed by Hwang Shinwei, this game tilts the Tetris playfield to create a pseudo-3D look. Players must rotate and place falling pieces to create solid lines, featuring the typical escalating difficulty of the genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '3-D Block (Asia) (Unl) (RCM Group)', '1990', NaN, 'Unlicensed', '1', 3, 'Falling block puzzle game with modified visuals.', 'Strategically place blocks to clear lines and gain points.', 'Another unlicensed variation of the 3D block puzzle concept.', 'Similar to other 3D Block versions but with slight variations in graphics and sound depending on the RCM Group''s publishing. It offers a unique visual perspective on the traditional brick-stacking gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '4 Nin Uchi Mahjong (Japan)', '1990', NaN, 'Unlicensed', '1', 3, 'Four-player Mahjong simulation based on standard Japanese rules.', 'Win hands to take points from opponents and finish with the highest score.', 'One of the earliest 4-player Mahjong games for the Famicom.', 'This title brought the traditional Japanese tabletop game to the console. It features AI opponents with different playstyles and focuses on the Riichi Mahjong ruleset, emphasizing strategy and tile counting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '4 Nin Uchi Mahjong (Japan) (Rev A)', '1984', NaN, 'Namco', '1', NaN, 'Four-player Mahjong simulation (Revised Version).', 'Defeat three AI opponents in a series of Mahjong matches.', 'An updated version of the classic 4-player Mahjong game.', 'This Revision A version contains minor bug fixes and potential adjustments to the AI or scoring logic from the original 1984 release, providing a more stable gambling simulation experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '64-in-1 Classic Player', '1984', NaN, 'Namco', '1', NaN, 'Side-scrolling platformer (Graphic hack of The Flintstones).', 'Reach the end of the levels while defeating enemies with a club.', 'A famous bootleg modification of The Flintstones: Rescue of Dino & Hoppy.', 'This notorious pirate hack replaces Fred Flintstone''s head with a modified Mario head. It became an internet meme but retains the solid platforming mechanics and level design of the original official title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '7 Grand Dad', 'Unknown', NaN, 'Unlicensed', '1', NaN, 'Isometric skateboarding with time-limit based navigation.', 'Earn enough tickets to enter the Skate Park and perform stunts.', 'An arcade-style skateboarding game set in a suburban neighborhood.', 'Players must navigate a skate city to reach four different parks (Downhill, Jump, Slalom, and Ramp) before time runs out. The game is known for its unique control scheme and the infamous Skate or Die! warning when time expires.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '720 (USA)', 'Bootleg', NaN, 'Bootleg', '1', NaN, 'Action-adventure platformer with a controllable bird companion.', 'Defeat the eight dukes and recover the eight power gems.', 'A post-apocalyptic action game often compared to Castlevania.', 'Set in a future where the world has been rebuilt after nuclear war, players control Orin and his falcon, Cutrus. The game allows for two-player co-op where one player controls the bird to flip switches and attack enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '8 Eyes (Japan)', '1988', NaN, 'Atari Games', '1-2', NaN, 'Action-adventure platformer with a controllable bird companion.', 'Recover the Great Jewels of the eight power centers to save the world.', 'The North American localized version of the challenging action title.', 'Similar to the Japanese version but with rebalanced difficulty and localized text. Players must choose the order in which they tackle the eight mansions, each representing a different country and containing a unique boss.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', '8 Eyes (USA)', '1988', NaN, 'Sage''s Creation', '1', NaN, 'Platformer/Minigame collection (Bootleg).', 'Complete various Christmas-themed levels and challenges.', 'An unlicensed holiday-themed game featuring festive sprites.', 'This bootleg title is often a modification of existing games or a collection of simple assets. It uses Christmas imagery, such as Santa Claus and snowy environments, to provide a seasonal, albeit unpolished, experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'A bootleg Christmas', '1988', NaN, 'Sage''s Creation', '1', NaN, 'Train-themed business simulation and city building.', 'Build a successful railway network and manage urban development.', 'A strategic railway management game (part of the A-Train series).', 'Players act as a railway tycoon, laying tracks, managing train schedules, and developing the surrounding land. Success depends on balancing the budget while growing the city''s population through efficient transport links.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'A Ressha de Ikou (Japan)', 'Bootleg', NaN, 'Bootleg', '1', NaN, 'Side-scrolling action platformer.', 'Guide Garfield through a week of chores and obstacles to find Odie.', 'An unreleased prototype version of the Garfield licensed game.', 'Players control the famous cat as he kicks enemies like mice and spiders. This prototype version shows the early development stages of the game, which is notorious for its high difficulty and small character sprites.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'A Week of Garfield (Prototype)', '1989', NaN, 'Artdink', '1', NaN, 'Life simulation and baseball management hybrid.', 'Navigate a player''s life from childhood to professional baseball success.', 'A unique Life of Baseball simulation game.', 'Combining board game elements with sports management, players make life choices that affect their character''s stats. The goal is to balance training, personal life, and career milestones to become a legendary baseball star.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aa Yakyuu Jinsei Icchokusen (Japan)', 'Prototype', NaN, 'Unknown', '1', NaN, 'Side-scrolling and vertical-scrolling shoot ''em up.', 'Navigate the innards of a giant alien to rescue Princess Maria.', 'A grotesque, biological-themed shooter known for its difficulty.', 'In this Inner-Body shooter, players fly through organic environments filled with guts and bones. The game is famous for its high level of gore for the era and a punishing difficulty curve where one hit results in death.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Abadox (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Side-scrolling and vertical-scrolling shoot ''em up.', 'Enter the alien entity Abadox and destroy it from the inside.', 'The North American release of the biological sci-fi shooter.', 'Identical in gameplay to the Japanese version, players must master power-up management to survive. It features a mix of horizontal and vertical scrolling stages, concluding in a battle against the alien''s core.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Abadox (USA)', '1989', NaN, 'Natsume', '1', NaN, 'Side-scrolling platformer based on the movie Aladdin.', 'Navigate through Agrabah to find Princess Jasmine and defeat Jafar.', 'A bootleg platformer featuring characters from Disney''s Aladdin.', 'This is an unlicensed title often found on multi-carts. Players control Aladdin through various levels inspired by the film, collecting items and jumping across rooftops. It is known for its unpolished physics and repurposed assets from other games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Abarenbou Tengu (Japan)', '1989', NaN, 'Natsume', '1', NaN, 'Flight combat simulation from a first-person cockpit view.', 'Complete various aerial missions and shoot down enemy aircraft.', 'A military flight simulator based on the Iron Eagle III movie.', 'Players pilot a fighter jet through several missions involving dogfights and bombing runs. The game focuses on managing radar, altitude, and weapon systems to intercept enemy targets while following a storyline tied to the film.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Abu Travels in Agrabah', '1990', NaN, 'Melody', '1', NaN, 'Multigame compilation featuring 52 different simple games.', 'Try out 52 different titles, ranging from shooters to platformers.', 'A notorious unlicensed collection of 52 low-quality games.', 'Famous for its high retail price and poor quality, this cart contains 52 original games (like Cheetahmen). Most suffer from bugs, unfinished levels, and repetitive gameplay, making it a legendary piece of gaming history for the wrong reasons.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aces - Iron Eagle 3 (Japan)', '1992', NaN, 'Konami', '1', NaN, 'Multigame compilation featuring 52 different games (Revised).', 'Navigate through a library of 52 games with minor bug fixes.', 'An updated version of the infamous Action 52 multicart.', 'This Rev A version attempted to fix some of the game-breaking bugs found in the initial release. While it remains largely the same collection of low-budget titles, some games that previously crashed or were unplayable were slightly improved.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Action 52 (USA) (Unl)', '1989', NaN, 'Sanritsu', '1', NaN, 'Side-scrolling shoot ''em up with futuristic vehicles.', 'Defeat an alien invasion to protect the city of New York.', 'The European version of the shooter known as SCAT: Special Cybernetic Attack Team.', 'Players control a human soldier equipped with a jetpack and two orbiting bits that provide extra firepower. The game features intense action, challenging bosses, and the ability to change the direction of your fire while moving.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Action 52 (USA) (Unl) (Rev A)', '1991', NaN, 'Active Enterprises', '1', NaN, 'Side-scrolling platformer with puzzle elements.', 'Search the Addams mansion to find hidden items for a scavenger hunt.', 'A prototype/beta version of Pugsley''s adventure in the Addams house.', 'In this European beta, players control Pugsley as he explores the non-linear mansion. The game is based on the animated series and requires finding specific objects while avoiding surreal enemies and hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Action in New York (Europe)', '1991', NaN, 'Active Enterprises', '1', NaN, 'Side-scrolling platformer with puzzle elements.', 'Explore the mansion and find your family members'' hidden items.', 'The North American release of Pugsley''s Scavenger Hunt.', 'Based on The Addams Family animated series, this game puts Pugsley in the lead. He must navigate various themed rooms in the mansion (like the attic and laboratory), jumping on enemies and uncovering secret passages to complete his task.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Addams Family, The - Pugsley''s Scavenger Hunt (Europe) (Beta)', '1989', NaN, 'Jaleco', '1', NaN, 'Top-down action-adventure with exploration and shooting.', 'Find and destroy the alien mother ship hidden under the city.', 'A challenging adventure game starring Uncle Fester.', 'Unlike other Addams Family games, this is a top-down shooter. Fester must navigate the streets and sewers, upgrade his lightning gun, and find items to help him enter the alien craft. It is known for its high difficulty and lack of a save system in the original version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Addams Family, The - Pugsley''s Scavenger Hunt (USA)', '1992', NaN, 'Ocean', '1', NaN, 'Top-down action-adventure with exploration and shooting.', 'Repel an alien invasion by locating their hidden base.', 'The North American version of Fester''s Quest.', 'Players guide Uncle Fester through a large, interconnected world. The game combines shooting mechanics with overhead exploration and first-person maze sections inside buildings. It features cameos from other family members who provide helpful power-ups.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Addams Family, The - Uncle Fester''s Quest (Europe)', '1992', NaN, 'Ocean', '1', NaN, 'Side-scrolling platformer with a large interconnected world.', 'Rescue the Addams family members from the mansion''s vaults.', 'A platformer based on the 1991 Addams Family movie.', 'Players control Gomez as he searches his mansion and grounds for kidnapped family members. The game is known for its non-linear exploration, hidden secrets, and the need to collect a specific amount of money to progress to the final boss.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Addams Family, The - Uncle Fester''s Quest (USA)', '1991', NaN, 'Sunsoft', '1', NaN, 'First-person dragon combat flight simulator.', 'Complete various aerial missions to defeat the evil dragon armies of Takhisis.', 'A unique dragon-riding flight simulator set in the Dragonlance world.', 'Players choose from three types of dragons (Gold, Silver, or Bronze) and fly through 27 missions. The gameplay involves aerial dogfights, avoiding ground fire, and using dragon breath or physical attacks to destroy enemy targets in a 3D-scrolling environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Addams Family, The (Europe) (En,Fr,De)', '1991', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action-adventure with party management.', 'Retrieve the Disks of Mishakal from the ruined city of Pax Tharkas.', 'An action-oriented RPG based on the first Dragonlance novel.', 'Players control a party of ten heroes, switching between them to utilize different skills. The game focuses on combat and exploration in a side-scrolling perspective, requiring players to manage character health and magic to survive the dangerous ruins.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Addams Family, The (USA)', '1992', NaN, 'Ocean', '1', NaN, 'Side-scrolling action-adventure with party management (English Translation).', 'Recover the Disks of Mishakal to bring back the knowledge of the true gods.', 'A fan-translated version of the Japanese Dragonlance RPG.', 'This version provides a complete English translation of the Japanese release. It allows players to experience the challenging party-based combat and story with all menus and dialogues translated, making the complex D&D mechanics accessible to English speakers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Advanced Dungeons & Dragons - Dragon Strike (USA)', '1992', NaN, 'Ocean', '1', NaN, 'Side-scrolling action-platformer with a large party of characters.', 'Venture into the pits of Xak Tsaroth to retrieve the Disks of Mishakal.', 'A challenging action RPG based on the legendary Dragonlance campaign.', 'Players lead a group of eight heroes through a dangerous dungeon. The game is known for its high difficulty and the need to swap characters constantly, as each hero has specific strengths, such as Tanis''s sword or Raistlin''s magic, essential for survival.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Advanced Dungeons & Dragons - Dragons of Flame (Japan)', '1989', NaN, 'Ocean', '1', NaN, 'Side-scrolling action-platformer with a large party of characters.', 'Explore the ruins of Xak Tsaroth and recover the ancient Disks of Mishakal.', 'The North American release of the first Dragonlance title for NES.', 'Identical to the Japanese version, this port brings the tabletop experience to the console. It features a unique control scheme where players manage a line of heroes, navigating traps and fighting dragons in a quest to restore faith to the world of Krynn.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Advanced Dungeons & Dragons - Dragons of Flame (Japan) [En by DvD v1.03]', '1989', NaN, 'Ocean', '1', NaN, 'Compilation of diverse mini-games and RPG exploration.', 'Complete various tasks and trials in the city of Hillsfar to earn gold and fame.', 'A multi-genre RPG focused on mini-games and character building.', 'Unlike traditional RPGs, gameplay consists of traveling between locations via a horseback riding mini-game and completing challenges like lock-picking, arena fighting, and archery. It serves as a side-story where players can transfer characters to other D&D titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Advanced Dungeons & Dragons - Heroes of the Lance (Japan)', '1992', NaN, 'Westwood Studios', '1', NaN, 'Compilation of diverse mini-games and RPG exploration.', 'Master the trials of Hillsfar and build a powerful character.', 'The localized US version of the unique multi-genre D&D adventure.', 'This version features the same mix of mini-games and exploration. Players must navigate the city, interact with NPCs, and succeed in skill-based challenges to progress. It is noted for its departure from standard turn-based D&D combat in favor of arcade-style segments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Advanced Dungeons & Dragons - Heroes of the Lance (USA)', '1990', NaN, 'U.S. Gold', '1', NaN, 'Turn-based tactical RPG with first-person exploration.', 'Defeat the evil boss Tyranthraxus and liberate the city of Phlan.', 'A faithful console adaptation of the classic Gold Box PC RPG.', 'Players create a custom party of six characters and explore a grid-based world. Combat shifts to a tactical top-down view where positioning and spell management are key. It is one of the most complex and deep RPG experiences available on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Advanced Dungeons & Dragons - Hillsfar (Japan)', '1990', NaN, 'U.S. Gold', '1', NaN, 'Turn-based tactical RPG with first-person exploration.', 'Reclaim the city of Phlan from the forces of evil.', 'The North American release of the iconic Gold Box RPG.', 'This version brings the full D&D experience to the NES, including character creation, experience leveling, and complex tactical combat. Players must clear various sectors of the city and complete quests to restore Phlan to its former glory.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Advanced Dungeons & Dragons - Hillsfar (USA)', '1988', NaN, 'U.S. Gold', '1', NaN, 'Collection of mini-games based on Disney park attractions.', 'Find six silver keys to open the castle gate for the big parade.', 'A Disney-themed adventure featuring various arcade-style levels.', 'Players explore the park and enter attractions to play mini-games: a racing game (Autopia), a space shooter (Space Mountain), a boat ride (Pirates of the Caribbean), and more. It also includes trivia questions from Disney characters to earn the final keys.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Advanced Dungeons & Dragons - Pool of Radiance (Japan)', '1988', NaN, 'U.S. Gold', '1', NaN, 'Multi-genre action: beat ''em up, lightgun shooting, and driving.', 'Rescue Billy''s girlfriend, Annabelle, from the gang boss Gordon.', 'A diverse action game set in the Louisiana swamplands.', 'Players experience three distinct gameplay styles: side-scrolling fighting, first-person rail shooting (compatible with the Zapper), and top-down driving. The European version is known for being slightly more balanced in difficulty than the US release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Advanced Dungeons & Dragons - Pool of Radiance (USA)', '1989', NaN, 'Westwood Studios', '1', NaN, 'Multi-genre action: beat ''em up, lightgun shooting, and driving.', 'Fight through the bayou and the city to save Annabelle.', 'A notoriously difficult multi-genre action title by Konami.', 'This version is famous for its extreme difficulty level. Players must master hand-to-hand combat against crocodiles and thugs, precise shooting in first-person stages, and high-speed driving to reach the final showdown at Gordon''s mansion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures in the Magic Kingdom (Europe)', '1989', NaN, 'Westwood Studios', '1', NaN, 'Side-scrolling exploration platformer.', 'Recover three stolen treasures from the planet Omsoc.', 'A console port of the classic PC Metroidvania-lite adventure.', 'Players control Captain Comic through various interconnected environments. The game focuses on finding power-ups like the Blastola Cola to enhance weapons and items like boots or lanterns to access new areas in a non-linear fashion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures in the Magic Kingdom (USA)', '1989', NaN, 'Capcom', '1', NaN, 'Vertical scrolling shooter/platformer hybrid.', 'Navigate through prehistoric lands to defeat the Great Spirit.', 'An overhead action game where a caveman shoots projectiles.', 'Despite the top-down perspective, players must jump over pits while shooting enemies. Dino Riki can upgrade his weapon from rocks to axes, boomerangs, and torches. The game is known for its fast pace and challenging environmental hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Bayou Billy, The (Europe)', '1988', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Collect scattered body parts to reassemble Franken''s girlfriend.', 'A prototype of a platformer based on the Frankenstein mythos.', 'Players control Franky, a trendy version of the monster, searching through a large castle and worldwide locations. Since it is a prototype, some mechanics may feel unpolished, but it features puzzle-solving and combat against various supernatural foes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Bayou Billy, The (USA)', '1988', NaN, 'Konami', '1', NaN, 'Top-down action-adventure with a companion AI.', 'Find the other castaways and escape the island before it''s too late.', 'An adventure game based on the classic 1960s TV sitcom.', 'Players control the Skipper, followed by Gilligan (who is controlled by AI). You must complete tasks, avoid traps, and manage Gilligan''s behavior to solve puzzles across several episodes, each mimicking the structure of a TV show.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Captain Comic, The (USA) (Unl)', '1992', NaN, 'New Breed Software', '1', NaN, 'Grid-based logic and environmental puzzle-solving.', 'Clear each room of Heart Framers to open the chest and progress.', 'A classic puzzle game starring the round blue hero, Lolo.', 'Players must move blocks, trap enemies in eggs, and use limited power-ups to collect all hearts in a room. It requires deep strategy and planning to avoid being trapped or killed by enemies like Medusas and Don Medusas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Dino Riki, The (USA)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Grid-based logic and environmental puzzle-solving.', 'Rescue Princess Lala from the clutches of the King of Darkness.', 'The Japanese entry in the Eggerland/Lolo puzzle series.', 'Known in Japan as part of the Eggerland franchise, it features a series of increasingly difficult rooms. The core mechanic involves using the environment and enemy behaviors to clear a path to the exit in a top-down, tile-based world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Dr. Franken, The (USA) (Proto)', 'Prototype', NaN, 'Unknown', '1', NaN, 'Grid-based logic and environmental puzzle-solving.', 'Solve 50 complex rooms to save Princess Lala.', 'The first official Western release of the beloved puzzle series.', 'This game introduced North American players to Lolo''s strategic puzzles. It features 50 levels of logic-based gameplay, where the player must figure out the exact sequence of moves to collect items and reach the exit without getting stuck.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Gilligan''s Island, The (USA)', '1990', NaN, 'Hudson Soft', '1', NaN, 'Grid-based logic and environmental puzzle-solving (Romhack).', 'Complete a series of custom, high-difficulty puzzle rooms.', 'A fan-made modification designed for expert Lolo players.', 'Created by Sivak Drac, this hack replaces the original levels with brand-new, much more difficult puzzles. It is intended for those who have already mastered the mechanics of the original game and are looking for a significant logical challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo (Europe)', '1989', NaN, 'HAL Laboratory', '1', NaN, 'Grid-based logic and environmental puzzle-solving.', 'Scale the tower and defeat the King of Darkness to save Lala.', 'The Japanese sequel to the popular Eggerland puzzle series.', 'Known as Eggerland: Meikyuu no Fukkatsu in Japan, this sequel introduces more complex room layouts and new enemy behaviors. Players must use their wits to manipulate blocks and enemies to collect all Heart Framers and reach the exit of each floor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo (Japan)', '1989', NaN, 'HAL Laboratory', '1', NaN, 'Grid-based logic and environmental puzzle-solving.', 'Advance through 50 rooms and the final tower to rescue Princess Lala.', 'The second Western installment of the iconic puzzle franchise.', 'Lolo returns with more challenging levels. This version includes Pro levels for advanced players and introduces more intricate puzzles involving the placement of bridges and the strategic use of enemy eggs to cross water or block line-of-sight attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo (USA)', '1989', NaN, 'HAL Laboratory', '1', NaN, 'Grid-based logic and environmental puzzle-solving (Romhack).', 'Solve custom, extremely difficult puzzles designed for experts.', 'A high-difficulty fan-made hack of the second Lolo game.', 'Created by Sivak Drac, this modification replaces the original 50 levels with much more punishing puzzles. It is designed specifically for veterans who have mastered every mechanic and enemy pattern of the official series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo (USA) [Hack by Sivak Drac v1.0] (~Challenging Lolo)', 'Hack', NaN, 'HAL Laboratory', '1', NaN, 'Grid-based logic and environmental puzzle-solving.', 'Rescue Lolo, Lala, and the inhabitants of the kingdom from the King of Darkness.', 'The third and largest entry in the Lolo puzzle trilogy.', 'This title features 110 different levels and allows players to switch between Lolo and Lala. It introduces an overworld map where players can choose which levels to tackle first, as well as massive boss fights at the end of each world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo 2 (Europe)', '1990', NaN, 'HAL Laboratory', '1', NaN, 'Grid-based logic and environmental puzzle-solving.', 'Stop the King of Darkness by solving puzzles across various lands.', 'The final official NES chapter of the Lolo series in North America.', 'Considered the peak of the series, Lolo 3 offers a massive variety of puzzles. The ability to play as either Lolo or Lala is purely cosmetic, but the level design reaches its most creative point, requiring precise timing and complex logical deduction.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo 2 (Japan)', '1990', NaN, 'HAL Laboratory', '1', NaN, 'Side-scrolling action platformer with gravity-defying mechanics.', 'Travel between planets to reactivate the communication satellites.', 'A quirky sci-fi adventure featuring planet-hopping gameplay.', 'Players control Rad Gravity as he visits multiple planets, each with its own unique gravity and environmental theme. The game is known for its humor, non-linear exploration, and the way it forces players to adapt to changing physics in every world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo 2 (USA)', '1990', NaN, 'HAL Laboratory', '1', NaN, 'Side-scrolling action platformer with gravity-defying mechanics.', 'Find the hidden Compuminds on different planets to save the galaxy.', 'The North American release of the planet-hopping platformer.', 'This version features the same exploration-based gameplay. Rad must find items and interact with strange aliens to progress. It stands out for its creative level design, such as a planet where everything is upside down and another made entirely of trash.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo 2 (USA) [Hack by Sivak Drac v1.0] (~Challenging Lolo 2)', 'Hack', NaN, 'HAL Laboratory', '1', NaN, 'Side-scrolling platformer with various mini-games.', 'Collect the lost pieces of the Louse-e-um artifacts.', 'A licensed title based on the classic cartoon series.', 'Players control Rocky the Flying Squirrel and Bullwinkle the Moose. The gameplay alternates between standard platforming and mini-games like football or training exercises. It captures the humor of the show but is known for its high and sometimes frustrating difficulty.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo 3 (Europe)', '1991', NaN, 'HAL Laboratory', '1', NaN, 'Side-scrolling action platformer based on the classic novel.', 'Rescue Becky Thatcher and defeat Injun Joe in a dream world.', 'A Japanese-developed platformer starring the famous literary character.', 'In this adaptation, Tom Sawyer dreams of a fantastic adventure. He travels through various levels (forests, rivers, and haunted houses) using rocks as projectiles. The game features cameos from other characters like Huckleberry Finn and Jim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Lolo 3 (USA)', '1991', NaN, 'HAL Laboratory', '1', NaN, 'Homebrew side-scrolling platformer.', 'Navigate through levels to reach the end of the quest.', 'A modern homebrew game created for the NES hardware.', 'Developed by Bob Rost as part of a university project/homebrew initiative, this title serves as an example of modern coding for vintage hardware. It features basic platforming mechanics and serves as a tribute to the 8-bit era''s design philosophy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Rad Gravity, The (Europe)', '1990', NaN, 'Interplay Productions', '1', NaN, 'Fast-paced behind-the-back flight combat.', 'Shoot down waves of enemy jets and survive the gauntlet.', 'A port of Sega''s high-speed arcade flight action game.', 'As the pilot of an F-14 Tomcat, players must dodge incoming missiles and use machine guns and lock-on missiles to destroy enemy formations. It is known for its intense speed and scaled sprite effects that attempt to mimic the arcade original.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Rad Gravity, The (USA)', '1990', NaN, 'Interplay Productions', '1', NaN, 'Menu-based astrology and personality simulation.', 'Discover your fortune and personality traits through questions.', 'A virtual astrology guide featuring Ai Sensei.', 'This title is a digital fortune-telling tool. Players input personal information like birth dates and blood types, and the character Ai Sensei provides horoscopes, compatibility checks, and advice based on Japanese pop-astrology.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Rocky and Bullwinkle and Friends, The (USA)', '1992', NaN, 'Rare', '1', NaN, 'Side-scrolling action-adventure with puzzle-solving.', 'Explore the ruins of Balubalouk to find the King''s treasure.', 'A challenging hybrid of platforming and exploration.', 'Players control an explorer in a vast underground world. The game requires careful navigation of traps and the use of bombs to reveal hidden paths. It is known for its non-linear structure and high level of difficulty regarding jump physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Tom Sawyer (USA)', '1989', NaN, 'SETa', '1', NaN, 'Hybrid of horizontal shoot ''em up and side-scrolling action.', 'Infiltrate and destroy eight floating space fortresses.', 'A two-phase sci-fi action game involving flight and exploration.', 'Each level starts with a flight phase in a jet to reach the fortress. Once inside, the player exits the ship and explores the maze-like interior on foot with a jetpack, managing limited energy while searching for the core to destroy it.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Adventures of Tomley Kleene by Bob Rost', 'Homebrew', NaN, 'Bob Rost', '1', NaN, 'Hybrid of horizontal shoot ''em up and side-scrolling action.', 'Neutralize the alien threat by destroying their sky bases.', 'The Japanese version of the sci-fi hybrid Air Fortress.', 'Identical to the international releases in mechanics, players must master the fuel management system. The Action phase inside the fortresses is particularly tense, as the player must find the exit quickly after the reactor is destroyed before it explodes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'After Burner (USA) (Unl)', '1987', NaN, 'Dempa Shinbunsha', '1', NaN, 'Hybrid of horizontal shoot ''em up and side-scrolling action.', 'Navigate through space and destroy the cores of eight fortresses.', 'The North American release of the cult classic Air Fortress.', 'This version features the same unique blend of genres. The strategic element of saving energy during the flying stages to ensure survival during the interior exploration stages makes it a standout title for fans of tactical shooters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'After Burner II (Japan)', '1990', NaN, 'Sega', '1', NaN, 'Isometric 3D navigation and puzzle-solving.', 'Navigate a manor to find the spell that turns you back into a human.', 'A prototype of the isometric adventure where you play as a ball.', 'In this unreleased port, players control a ball that is constantly losing air. You must find air pumps to stay inflated while navigating rooms filled with spikes and obstacles. This version represents an earlier state of development.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ai Sensei no Oshiete - Watashi no Hoshi (Japan)', '1989', NaN, 'Nintendo', '1', NaN, 'Isometric 3D navigation and puzzle-solving.', 'Explore the complex map and survive while managing air levels.', 'A more polished prototype of the isometric puzzle game Airball.', 'This second prototype features updated graphics and physics compared to the first. The gameplay remains focused on careful movement in a pseudo-3D environment, requiring precise jumps and item management to solve environmental puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aigiina no Yogen - From The Legend of Balubalouk (Japan)', '1988', NaN, 'Vic Tokai', '1', NaN, 'Side-scrolling flight action based on the TV series.', 'Complete various rescue and infiltration missions with the Airwolf chopper.', 'A European mission-based helicopter combat game.', 'Different from the US version, this release focuses on navigating tight corridors and destroying specific targets. Players must manage fuel and ammo while rescuing hostages and avoiding surface-to-air missiles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Air Fortress (Europe)', '1989', NaN, 'HAL Laboratory', '1', NaN, 'Side-scrolling flight action with a focus on shooting.', 'Shoot down enemy planes and progress through multiple stages.', 'A Kyugo-developed flight shooter based on the Airwolf license.', 'Unlike the Acclaim version, this Japanese release is a more straightforward horizontal shooter. Players control the high-tech helicopter, upgrading weapons and engaging in dogfights against fleets of enemy aircraft across various landscapes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Air Fortress (Japan)', '1989', NaN, 'HAL Laboratory', '1', NaN, 'Side-scrolling helicopter combat with mission-based objectives.', 'Complete top-secret missions and rescue prisoners of war.', 'An action game based on the hit 80s TV show Airwolf.', 'Players pilot the high-tech helicopter through various side-scrolling stages. The gameplay involves a mix of aerial combat and landing at specific bases to rescue hostages. It is known for its high difficulty and the need to manage limited missiles and fuel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Air Fortress (USA)', '1989', NaN, 'HAL Laboratory', '1', NaN, 'Menu-based point-and-click adventure/mystery.', 'Solve a series of mysterious disappearances linked to a ghost train.', 'A classic Japanese mystery adventure game by Jirou Akagawa.', 'Players take on the role of a detective investigating a rural town. The game uses a command-style interface to talk to witnesses, examine scenes, and gather clues to solve the supernatural mystery of the Ghost Train.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Airball (Proto1)', 'Prototype', NaN, 'Unknown', '1', NaN, 'Menu-based interactive narrative/Adventure (English Translation).', 'Navigate the neo-Tokyo underworld and uncover the Akira project.', 'A fan-translated version of the adventure game based on the Akira movie.', 'This version allows English speakers to experience the branching narrative of the Akira game. Players make choices that follow the film''s plot, interacting with characters like Kaneda and Tetsuo through detailed pixel-art scenes and dialogue menus.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Airball (Proto2)', 'Prototype', NaN, 'Unknown', '1', NaN, 'Menu-based interactive narrative/Adventure.', 'Follow Kaneda''s journey through Neo-Tokyo to find Tetsuo.', 'The original Japanese adventure game based on the legendary manga and film.', 'The game plays like a visual novel or digital comic. Players select commands like Look, Talk, or Move to progress through the story. It is highly regarded for its impressive graphics and faithful recreation of the movie''s atmosphere.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Airwolf (Europe)', '1987', NaN, 'Elite Systems', '1', NaN, 'First-person point-and-click horror adventure.', 'Escape a haunted mansion filled with traps and demons.', 'A horror-themed adventure game, part of the MacVenture series.', 'Known in the West as Shadowgate, this Japanese version features the same punishing gameplay where every wrong move can lead to a gruesome death. Players must solve environmental puzzles and manage their torch light to survive the cursed castle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Airwolf (Japan)', '1987', NaN, 'Elite Systems', '1', NaN, 'Turn-based RPG with exploration and party management.', 'Prevent a demon invasion by uniting the human and demon worlds.', 'An RPG based on the classic manga series by Shigeru Mizuki.', 'Players control Akuma-kun, navigating a world map and engaging in turn-based battles. The game features a unique system where you can summon different demons to join your party, each with specific elemental spells and abilities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Airwolf (Japan) [En by Vice v1.0]', 'Hack', NaN, 'Elite Systems', '1', NaN, 'Side-scrolling action platformer with multiple paths and characters.', 'Defeat Count Dracula and his army of darkness in the year 1476.', 'The legendary Japanese version of Castlevania III: Dracula''s Curse.', 'This version is famous for its VRC6 enhancement chip, which provides superior music and sound effects compared to the US release. Players can play as Trevor Belmont and eventually recruit Alucard, Sypha, or Grant to help them through branching stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Airwolf (USA)', '1987', NaN, 'Elite Systems', '1', NaN, 'Side-scrolling action platformer (English Translation).', 'Journey to the heart of the Demon Castle to slay Dracula.', 'A fan-translated version of the superior VRC6-equipped Japanese title.', 'This hack translates the menus and dialogue of the Japanese Akumajou Densetsu into English. It allows Western players to enjoy the definitive version of the third Castlevania, including the original unedited music and higher difficulty balance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akagawa Jirou no Yuurei Ressha (Japan)', '1989', NaN, 'King Records', '1', NaN, 'Side-scrolling action platformer.', 'Use the Vampire Killer whip to destroy Dracula in his castle.', 'The Japanese Famicom Disk System version of the original Castlevania.', 'Originally released for the Disk System, this version features a save function not present in the international cartridge release. The gameplay remains the foundation of the series: platforming, sub-weapons, and intense boss battles against classic movie monsters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akira (English - Translated)', 'Hack', NaN, 'Taito', '1', NaN, 'Action platformer with a humorous and lighthearted tone.', 'Defeat the self-proclaimed demon king Galamoth.', 'A cute-em-up spinoff of the Castlevania series starring Kid Dracula.', 'Known in the West as Kid Dracula, this game parodies the tropes of the main series. Players control a young version of Dracula who can charge up fireballs, turn into a bat, and walk on ceilings through colorful, creative levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akira (Japan)', '1988', NaN, 'Taito', '1', NaN, 'Formula-style racing with simulation and arcade elements.', 'Win the season championship by placing first in various global tracks.', 'A high-speed racing game endorsed by the famous IndyCar driver.', 'Players can customize their car''s settings and compete in a full season or a single race. It features a unique Turbo mechanic for overtaking and a pit stop system, offering a more technical experience than many other 8-bit racers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akuma no Shoutaijou (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer based on the Disney movie.', 'Navigate through Agrabah to find Princess Jasmine and defeat Jafar.', 'The official European release developed by Virgin Interactive.', 'Unlike the unlicensed versions, this official port features fluid animations and levels that closely follow the film''s plot. Players use apples as projectiles and a scimitar for close combat, traversing the Cave of Wonders and the Sultan''s Palace.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akuma-kun - Makai no Wana (Japan)', '1989', NaN, 'TOSE', '1', NaN, 'Side-scrolling platformer (Unlicensed).', 'Complete levels inspired by the Aladdin story.', 'A common unlicensed/pirate version of the Aladdin game.', 'Often developed by companies like Hummer Team or Super Game, these unlicensed versions vary in quality. They typically adapt levels from the Genesis or SNES versions of Aladdin, featuring simplified graphics and physics for the NES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akumajou Densetsu (Japan)', '1989', NaN, 'Konami', '1', NaN, 'Side-scrolling platformer (Unlicensed).', 'Defeat enemies and bosses to progress through the story.', 'A pirate version of Aladdin, often featuring modified assets.', 'Released in 1995, this version is part of the Aladdin 4 series of bootlegs. It is known for reusing sprites from other games and having hit-or-miss controls, but it attempted to bring the 16-bit experience to the 8-bit NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akumajou Densetsu (Japan) [En by Vice v1.0] (~Legend of Demon Castle - Castlevania III)', 'Hack', NaN, 'Konami', '1', NaN, 'Side-scrolling platformer (Unlicensed).', 'Reach the end of each stage while avoiding traps and enemies.', 'An updated 1996 bootleg version of the Aladdin series.', 'Similar to the 1995 version but often with minor color changes or bug fixes. These Aladdin 4 titles were widely distributed on multi-carts and represent the era of unlicensed Asian development for the Famicom/NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akumajou Dracula (Japan)', '1986', NaN, 'Konami', '1', NaN, 'Side-scrolling platformer (Unlicensed/Mod).', 'Navigate enhanced levels with smoother performance.', 'A refined version of the Aladdin bootleg by Hummer Team.', 'This specific version is a Deluxe mod of the original Hummer Team pirate game. It aims to fix technical issues, improve sprite animations, and provide a more playable experience than the standard unlicensed releases.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akumajou Special - Boku Dracula-kun (Japan)', '1990', NaN, 'Konami', '1', NaN, 'Side-scrolling platformer (Unlicensed).', 'Journey through the desert and palaces to save the princess.', 'Another distinct unlicensed sequel/version of the Aladdin story.', 'Labeled as Aladdin II, this bootleg often features entirely different level layouts and music than the Aladdin 4 series, though it still relies on assets inspired by the 16-bit Disney games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Akumajou Special - Boku Dracula-kun (Japan) [En by Vice v1.04] (~I''m Kid Dracula!!)', 'Hack', NaN, 'Konami', '1', NaN, 'Side-scrolling platformer with puzzle and flight elements.', 'Find and hatch all the balloons in each level to proceed.', 'A quirky platformer starring a brave chicken.', 'Players control Alfred as he pecks enemies and uses his dive bomb move. The game is known for its bright graphics and the unique goal of popping balloons to open the exit, requiring a mix of platforming skill and exploration.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Al Unser Jr. Turbo Racing (USA)', '1988', NaN, 'Data East', '1', NaN, 'Side-scrolling platformer with puzzle and flight elements.', 'Navigate through the levels to rescue your feathered friends.', 'The North American release of the Alfred Chicken platformer.', 'Identical to the European version, it features challenging levels filled with secret areas and power-ups. Alfred must find his way through various themed worlds, including a toy factory and a haunted house.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aladdin (Europe)', '1993', NaN, 'Capcom', '1', NaN, 'Side-scrolling action with exploration and time limits.', 'Rescue prisoners and reach the exit before the timer expires.', 'A tense action game based on the sci-fi horror movie.', 'Players control Ripley as she navigates the Fiorina 161 prison colony. Armed with a pulse rifle, flamethrower, and grenades, you must track down trapped prisoners using a motion tracker while fighting off waves of Aliens.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aladdin (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Top-down run and gun shooter.', 'Rescue all hostages and reach the exit before the bomb explodes.', 'A port of Sega''s arcade classic featuring alien-infested ships.', 'Players move through maze-like spaceships to rescue trapped crew members. After collecting everyone, a boss room opens. The game features various power-ups like lasers and fireballs to combat the grotesque alien biological forms.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aladdin 4 (1995) (Unl)', '1995', NaN, 'Unlicensed', '1', NaN, 'Top-down run and gun shooter (Unlicensed).', 'Clear each deck of aliens and save your teammates.', 'The North American unlicensed version by Tengen.', 'While Sega produced the original, Tengen released this version in the US without Nintendo''s license. It maintains the intense arcade gameplay and the iconic boss battles, featuring a distinct graphic style adapted for the NES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aladdin 4 (1996) (Unl)', '1996', NaN, 'Unlicensed', '1', NaN, 'Side-scrolling beat ''em up (Bootleg).', 'Defeat waves of enemies using Predator''s combat skills.', 'An unlicensed action game based on the famous sci-fi crossover.', 'This is a pirate title, often based on other games like Kyuu Kyoku Tiger or Spartan X. It features the Predator character fighting through levels filled with human and alien enemies, though it lacks the polish of official licensed products.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aladdin Hummer Team Deluxe v2.1', 'Unlicensed', NaN, 'Hummer Team', '1', NaN, 'Side-scrolling basketball with a full-court perspective.', 'Outscore the opposing team across a full 82-game season.', 'A sports simulation focusing on 5-on-5 basketball action.', 'The game features a unique perspective where the court scrolls horizontally. Players can choose from different fictional teams, manage substitutions, and execute slam dunks and long-range shots in a quest for the championship.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aladdin II (Unl)', 'Unlicensed', NaN, 'Hummer Team', '1', NaN, 'Vertical scrolling shoot ''em up with armor upgrades.', 'Defeat the invading alien fleet using the SYD spaceship.', 'A classic vertical shooter featuring a complex power-up system.', 'Players collect S and P tiles to enhance their ship. The most notable mechanic is the Armor system, which allows the ship to transform into different combat modes with varying weapon types to suit the enemy patterns.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Alfred Chicken (Europe)', '1993', NaN, 'Twilight Games', '1', NaN, 'Vertical scrolling shoot ''em up with armor upgrades.', 'Destroy the boss at the end of each space stage.', 'The North American version of the shooter known as ASO.', 'Known for its high difficulty, this version requires players to memorize power-up locations. Managing the energy levels for your special armor is crucial for survival, especially during the bullet-heavy boss encounters in later levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Alfred Chicken (USA)', '1993', NaN, 'Twilight Games', '1', NaN, 'Side-scrolling action platformer.', 'Transform into a giant to defeat the monsters of the island.', 'A challenging platformer starring an explorer named Amagon.', 'Amagon starts as a weak human with a rifle, but can transform into Megagon, a powerful giant who punches enemies. The game is infamous for its high difficulty and the need to manage points to maintain the transformation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Alien 3 (Europe)', '1992', NaN, 'Probe Software', '1', NaN, 'Political simulation and strategy.', 'Navigate the US political landscape to win the Presidential election.', 'A Japanese-made simulation of the United States presidential race.', 'Players manage campaign funds, travel to different states, and participate in debates to gain popular and electoral votes. It is a rare example of a political strategy game on the Famicom, focused on the 1988 election.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Alien 3 (USA)', '1992', NaN, 'Probe Software', '1', NaN, 'Quiz show simulation and board game.', 'Answer trivia questions correctly to win a trip across America.', 'A digital version of the popular Japanese TV quiz show.', 'Based on the Ultra Quiz format, players compete in trivia rounds and mini-games while traveling across various US cities. The goal is to avoid elimination and reach the final round at the Statue of Liberty.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Alien Syndrome (Japan)', '1987', NaN, 'Sega', '1', NaN, 'Gambling and slot machine simulation.', 'Build a fortune by winning at various casino games.', 'A casino-themed simulation focused on slot machines and luck.', 'Set in a fictional Las Vegas, players navigate menus to play different types of slot machines. The game tracks your winnings as you try to hit the jackpot and live the American Dream of becoming a casino millionaire.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Alien Syndrome (USA) (Unl)', '1987', NaN, 'Sega', '1', NaN, 'Action multi-game based on the TV show events.', 'Compete in various athletic challenges to earn points for the final round.', 'A sports-action collection based on the hit 90s TV competition.', 'Players participate in events like Joust, Wall, Powerball, and Assault against the Gladiators. Success leads to the Eliminator, a final obstacle course. Each event requires different skills, from button-mashing to precise timing and aiming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Alien VS Predator (C)', 'Homebrew', NaN, 'Unknown', '1', NaN, 'Physics-based projectile puzzle (Unlicensed).', 'Use a slingshot to launch birds and destroy all green pigs on the map.', 'A modern bootleg port of the famous mobile game for the NES.', 'This is an unlicensed adaptation of the mobile hit. Players must calculate the trajectory and power of the slingshot to topple structures and eliminate pigs. Despite the hardware limits, it replicates the core angry birds mechanic with 8-bit graphics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'All-Pro Basketball (USA)', '1989', NaN, 'Acony', '1-2', NaN, 'Text-based adventure with RPG elements.', 'Investigate ancient myths and stop a dark god from being resurrected.', 'A dark, mythological adventure game based on a manga series.', 'Based on the work of Daijiro Morohoshi, players explore various locations via menus and commands. It combines Japanese folklore with a cosmic horror atmosphere, requiring players to solve puzzles and engage in occasional turn-based battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Alpha Mission (Europe)', '1987', NaN, 'SNK', '1', NaN, 'Digital board game and Pictionary style quiz.', 'Be the first to collect one card from each of the four categories.', 'Nintendo''s first video board game focused on social play.', 'Players or AI compete to identify a drawing as it is being sketched on the screen. The faster you guess, the more spaces you move. It features several difficulty levels and categories like Leisure, Science, and Whatchamacallit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Alpha Mission (USA)', '1987', NaN, 'SNK', '1', NaN, 'Digital board game and Pictionary style quiz.', 'Identify drawings as they are sketched to win cards and move.', 'The North American release of the puzzle-board game hybrid.', 'Identical to the European version, it supports up to four players using controllers. The game is known for its catchy but repetitive soundtrack and the increasing difficulty of the drawings as players progress through the levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Amagon (USA)', '1988', NaN, 'Nihon Bussan', '1', NaN, 'Grand strategy and historical simulation.', 'Conquer the known world by managing a vast empire and its military.', 'A deep strategy game from Koei''s Historical Simulation series.', 'Known in the West as Genghis Khan II, this title tasks players with managing resources, diplomacy, and turn-based tactical battles. Players must balance the needs of their citizens while expanding their territory through Eurasia.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'America Daitouryou Senkyo (Japan)', '1990', NaN, 'Koei', '1', NaN, 'Grand strategy and historical simulation.', 'Unite the Mongol tribes and expand your empire across the world.', 'The first entry in Koei''s Genghis Khan strategy series.', 'Set in the 12th century, players take the role of Temujin. The game is divided into two phases: uniting the Mongol tribes and then conquering the rest of the world. It features complex systems for labor, food, and military drafting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'America Oudan Ultra Quiz - Shijou Saidai no Tatakai (Japan)', '1991', NaN, 'Taito', '1', NaN, 'Action-RPG with turn-based combat sections.', 'Save the princess and defeat the demon king to restore peace to Arabia.', 'A unique Middle Eastern-themed RPG known as The Magic of Scheherazade.', 'The game blends real-time overworld exploration with turn-based party combat. Players can travel through time, hire mercenaries, and use Team Magic to defeat enemies. It is praised for its unique setting and genre-blending mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'American Dream (Japan)', '1989', NaN, 'TOSE', '1', NaN, '2-on-2 arcade basketball with no fouls rules.', 'Outscore the opponent by any means necessary, including punching.', 'A violent and humorous take on arcade basketball.', 'This is Basket Brawl where players can punch opponents to steal the ball. It features a simplified control scheme focusing on dunks, shots, and combat. The European version maintains the fast-paced, irreverent spirit of the arcade original.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'American Dream (Japan) [En by Pale Dim v1.0]', 'Hack', NaN, 'TOSE', '1', NaN, '2-on-2 arcade basketball with no fouls rules.', 'Win the game by punching, stealing, and scoring baskets.', 'The North American release of Midway''s arcade basketball hit.', 'Famous for the tagline A Basket Brawl, players choose from several characters with unique personalities. The game ignores traditional rules, allowing players to knock down rivals and even pull down their shorts to win the match.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'American Gladiators (USA)', '1992', NaN, 'Imagineering', '1-2', NaN, 'Puzzle and strategy with ball physics.', 'Navigate a ball through a maze-like grid to reach the goal.', 'A unique spatial puzzle game with a cold, minimalist aesthetic.', 'Players must move a ball across a tiled grid, interacting with various blocks and mirrors to change direction. The challenge lies in planning the path carefully to reach the exit within the time limit while avoiding falling off the edges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Angry Birds', 'Homebrew', NaN, 'Rovio', '1', NaN, 'Top-down action-adventure with ice-sliding physics.', 'Rescue the penguin''s friends while avoiding seals and obstacles.', 'An unlicensed adventure game featuring slippery movement.', 'This is a port of the MSX game, featuring a penguin that must navigate icy levels. The key mechanic is the momentum-based movement on ice, which makes avoiding enemies like seals and polar bears a challenge of precision and timing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ankoku Shinwa - Yamato Takeru Densetsu (Japan)', '1989', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer with a grappling weapon.', 'Defeat the evil Ligar and restore peace to the land of Argool.', 'The Japanese version of the classic known as Rygar.', 'Players control a warrior armed with the Diskarmor, a shield on a chain. Unlike the arcade version, this NES/Famicom port features an interconnected world with RPG elements, where players must find five Indora gods to gain power-ups.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Anticipation (Europe)', '1988', NaN, 'Rare', '1', NaN, 'Vertical scrolling shoot ''em up with ground and air attacks.', 'Destroy the enemy mechanical base at the end of each stage.', 'A classic vertical shooter featuring a landing mechanic.', 'Players pilot a futuristic jet that can fire at air targets and drop bombs on ground enemies. A unique feature of this game is the ability to land on specific platforms to upgrade weapons and recover energy, adding a layer of strategy to the shooting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Anticipation (USA)', '1988', NaN, 'Rare', '1', NaN, 'Paddle-based block-breaking action.', 'Clear all the bricks on the screen to advance to the next level.', 'The Japanese version of the iconic arcade brick-breaker.', 'Players control the Vaus paddle to bounce a ball and destroy various colored bricks. It features power-ups that drop from destroyed blocks, such as lasers, multiple balls, and a widened paddle, culminating in a boss fight against Doh.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aoki Ookami to Shiroki Mejika - Genchou Hishi (Japan)', '1989', NaN, 'Koei', '1', NaN, 'Paddle-based block-breaking action.', 'Navigate through 33 rounds and defeat the final boss, Doh.', 'The North American release of the legendary Arkanoid.', 'This version is identical to the Japanese one in mechanics but was famous for being sold with a special Vaus controller for more precise movement. It set the standard for the brick-breaking genre on home consoles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aoki Ookami to Shiroki Mejika - Genghis Khan (Japan)', '1989', NaN, 'Koei', '1', NaN, 'Paddle-based block-breaking action (Romhack).', 'Complete a series of brand-new, highly challenging levels.', 'A comprehensive level-hack of the original Arkanoid.', 'Titled Dimension of Doh, this fan-made modification replaces all the original stages with custom, much more difficult designs. It is intended for players who have already mastered the official levels and want a new challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arabian Dream Scheherazade (Japan)', '1989', NaN, 'Culture Brain', '1', NaN, 'Paddle-based block-breaking action with level editor.', 'Clear refined levels and utilize new power-ups and enemy types.', 'The Japan-exclusive sequel to the original Arkanoid.', 'Known as Arkanoid: Revenge of Doh, this sequel introduces new brick types, multiple paths between levels, and more complex boss encounters. It also famously included a built-in level editor for players to create their own stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arch Rivals - A Basket Brawl! (Europe)', '1989', NaN, 'Midway', '1-2', NaN, 'Top-down action-adventure with exploration.', 'Recover the stolen Elven ring from the Shogun of Darkness.', 'A fast-paced overhead adventure starring a female warrior.', 'Players control Arkista through 125 stages of action. The gameplay focuses on using a bow and arrow to defeat enemies and finding power-ups like armor and fire-wands. It is known for its arcade-like speed and high number of levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arch Rivals - A Basket Brawl! (USA)', '1989', NaN, 'Midway', '1-2', NaN, 'Side-scrolling platformer with a rolling mechanic.', 'Navigate various themed worlds to rescue your kidnapped girlfriend.', 'A creative platformer where the hero can curl into a ball.', 'Players control an armadillo that can roll to move faster and defeat enemies, a mechanic often compared to Sonic the Hedgehog. The game features an overworld map and diverse stages ranging from deserts to space-themed levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Archon (USA)', '1989', NaN, 'Free Fall Associates', '1', NaN, 'First-person space exploration and turn-based combat.', 'Travel through the Artelius dimension to defeat the King of Darkness.', 'A unique hybrid of space flight simulation and traditional RPG.', 'Players navigate through space in a first-person perspective, visiting planets and space stations. The game features a complex plot involving black holes and alternate dimensions, with a combat system that shifts to a menu-based RPG style when encountering enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arctic (Japan)', '1987', NaN, 'Pony Canyon', '1', NaN, 'Side-scrolling platformer with mini-games.', 'Collect all the puzzle pieces in each world to progress.', 'A colorful and cute platformer starring the Asmik mascot.', 'Players control Asmik-kun as he explores vibrant worlds. The game is known for its non-violent approach, where players often solve puzzles or play mini-games to advance, rather than just fighting enemies. It features a cheerful art style typical of late-era Famicom games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arctic Adventure - The Penguin & Seal (Australia) (Unl)', '1989', NaN, 'Unlicensed', '1', NaN, 'Vertical scrolling shoot ''em up with armor mechanics.', 'Collect armor parts to build powerful combat suits.', 'The Japanese original of the shooter known as Alpha Mission.', 'This game is famous for its tactical depth. Players collect Armor letters that, when combined, grant the ship massive firepower or defensive shields. Success depends on knowing which armor to deploy for specific boss patterns and stage hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Argos no Senshi (Japan)', '1987', NaN, 'Tecmo', '1', NaN, 'Side-scrolling action platformer.', 'Rescue Obelix and defeat the Roman legions across Europe.', 'A multi-language licensed game starring the famous Gauls.', 'Based on the beloved comic series, players control Asterix as he travels through various countries occupied by the Romans. The game features high-quality graphics for the NES and focuses on jumping, punching, and using magic potions to clear stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Argus (Japan)', '1986', NaN, 'Toaplan', '1', NaN, 'Post-apocalyptic vehicular combat and racing.', 'Drive across a wasteland to find the legendary Astro Fang.', 'A high-speed action game featuring a transforming car.', 'In a desert world similar to Mad Max, players drive a car equipped with missiles. The gameplay involves high-speed racing while shooting down enemy vehicles and jumping over obstacles. You must manage your fuel and ammo to reach the end of the long highway stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arkanoid (Japan)', '1986', NaN, 'Taito', '1', NaN, 'Post-apocalyptic vehicular combat (English Translation).', 'Navigate the wasteland to find the legendary Super Machine.', 'A fan-translated version of the car-combat title Astro Fang.', 'This version provides a complete English translation of the menus and story. It allows players to follow the narrative of the lone driver in a desolate future, making the upgrade system and mission objectives clear to Western players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arkanoid (USA)', '1986', NaN, 'Taito', '1', NaN, 'Physics-based side-scrolling shooter.', 'Collect energy capsules while managing momentum and gravity.', 'A unique shooter where recoil and weight affect movement.', 'Players control Sasa, a boy with a jetpack. The core mechanic is that every shot fired creates recoil that pushes the player in the opposite direction. This makes movement a constant puzzle of physics, as you must balance shooting enemies with staying airborne.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arkanoid (USA) [Hack by Dragon Eye Studios v1.0] (~Arkanoid - Dimension of Doh)', 'Hack', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer with magic systems.', 'Destroy the evil wizard Blackhorn and rescue Princess Rosebud.', 'A dark fantasy action game featuring a massive axe weapon.', 'Players control Astyanax as he fights through a dream world. The game features a power meter that grows when you don''t swing your weapon, allowing for devastating charged attacks. It is well-known for its impressive cinematic cutscenes and large boss sprites.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arkanoid II (Japan)', '1988', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer with magic systems.', 'Traverse the world of Remlia to defeat the dark forces.', 'The North American release of the cinematic fantasy action game.', 'Identical to the European version, it offers challenging platforming and a variety of magic spells. The player is accompanied by a small fairy named Cutie, who provides support and story context during the adventure''s high-quality interstitial scenes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Arkista''s Ring (USA)', '1990', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer with RPG elements.', 'Escaped from the castle and defeat the four guardians of Dante.', 'A challenging adventure game based on the SNK arcade classic.', 'Players control Athena through diverse worlds (Forest, Sea, Sky). As she defeats enemies, she can collect various weapons and armor pieces that change her appearance and abilities. The game is notorious for its high difficulty and cryptic power-up system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Armadillo (Japan)', '1991', NaN, 'Irem', '1', NaN, 'Fitness-oriented sports simulation using the Power Pad.', 'Complete all five athletic events to improve your fitness score.', 'An early exercise game designed for the NES Power Pad floor mat.', 'Players participate in events like hurdles, animal chase, and dark tunnel. The game requires physical movement on the mat to control the character on screen. It features different modes (Training and University) to test the player''s agility and speed.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Armadillo (Japan) [En by Vice v1.01]', 'Hack', NaN, 'Irem', '1', NaN, 'Fitness-oriented sports simulation using the Power Pad.', 'Finish the athletic circuit and reach the highest rank.', 'The North American version of the Power Pad fitness title.', 'Similar to the European release, this version was part of the Family Fun Fitness series. It focuses on physical activity, challenging players to run and jump in real life to navigate obstacles in the game, making it one of the first exer-games for consoles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Artelius (Japan)', '1987', NaN, 'Nihon Bussan', '1', NaN, 'Side-scrolling action platformer (Touhou Project Fan-game).', 'Navigate through levels while defeating enemies with magic.', 'A modern homebrew/hack that brings Touhou characters to the NES.', 'This is a fan-made title featuring Cirno from the Touhou Project. It uses the mechanics of Atlantis no Nazo but with updated sprites and music. It’s a crossover that blends classic 8-bit frustration with modern doujin culture.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Asmik-kun Land (Japan)', '1991', NaN, 'Asmik', '1', NaN, 'Non-linear side-scrolling action platformer.', 'Explore 100 mysterious zones to find and rescue your master.', 'A notoriously difficult and cryptic exploration game.', 'Players control Wynn as he searches for his master in the lost city of Atlantis. The game is famous for its suicidal difficulty, hidden warps, and the fact that many zones can only be reached by performing specific, often counter-intuitive, actions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'ASO - Armored Scrum Object (Japan)', '1985', NaN, 'SNK', '1', NaN, 'Non-linear side-scrolling action platformer (Early version).', 'Navigate the zones of Atlantis in this pre-release build.', 'A beta version of the classic and difficult Atlantis no Nazo.', 'This version contains minor differences in level layouts and enemy placement compared to the final retail release. It offers a glimpse into the development process of one of the Famicom''s most mysterious and challenging titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Asterix (Europe) (En,Fr,De,Es,It)', '1992', NaN, 'Infogrames', '1', NaN, 'Behind-the-back 3D rail shooter.', 'Fly through surreal school-themed levels to defeat waves of enemies.', 'A fast-paced shooter similar to Space Harrier with a schoolgirl protagonist.', 'Players control Nokko, a girl who flies through various environments (like space and forests) shooting at bizarre creatures. The game features a 3D mode (using goggles) and is known for its colorful graphics and high-speed action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Astro Fang - Super Machine (Japan)', '1988', NaN, 'A-Wave', '1', NaN, 'Behind-the-back 3D rail shooter (English Translation).', 'Help Nokko clear the Academy''s stages of strange monsters.', 'A fan-translated version of the quirky 3D shooter.', 'This patch translates the menus and ending of Attack Animal Gakuen. It makes the game''s lighthearted story and upgrade systems understandable for English-speaking players while retaining the frantic into-the-screen shooting gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Astro Fang - Super Machine (Japan) [En by Caution v20010704]', 'Hack', NaN, 'A-Wave', '1', NaN, 'Side-scrolling action platformer.', 'Stop the evil Dr. Gangrene and his army of mutated tomatoes.', 'A licensed platformer based on the animated series.', 'Players control Chad Finletter as he jumps through city streets and sewers. Chad can shrink to fit into small spaces and must use his jumping ability to squash tomatoes. The European version features the same quirky humor as the show.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Astro Robo Sasa (Japan)', '1987', NaN, 'Asmik', '1', NaN, 'Side-scrolling action platformer.', 'Navigate through San Francisco to stop the tomato invasion.', 'The North American release based on the Killer Tomatoes cartoon.', 'This version pits the player against various types of mutated vegetables. While the graphics are simple, the game focuses on precise platforming and finding secret areas to gather items needed to progress toward Dr. Gangrene''s base.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Astyanax (Europe)', '1989', NaN, 'Jaleco', '1', NaN, 'Australian Rules Football simulation.', 'Win the grand final by outscoring opponents in this unique sport.', 'A sports game dedicated to the specific rules of AFL.', 'This title features the unique mechanics of Australian Football, including kicking for goals, handballs, and marks. It allows for up to four players (with a multitap) and includes several fictional teams based on real-world Australian locations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Astyanax (USA)', '1989', NaN, 'Jaleco', '1', NaN, 'Mahjong simulation with adult-themed rewards.', 'Win Mahjong hands to unlock hidden images.', 'An unlicensed, adult-themed Mahjong game for the Famicom.', 'This title features standard Riichi Mahjong rules against female AI opponents. Being an unlicensed AV (Adult Video) title, the primary draw for players at the time was the reveal of digitized adult images as a reward for winning matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Athena (Japan)', '1986', NaN, 'SNK', '1', NaN, 'Hanafuda card game with adult-themed rewards.', 'Defeat opponents in the traditional card game of Koi-Koi.', 'An unlicensed adult version of the classic Japanese Hanafuda card game.', 'Players engage in the traditional flower card game against computer opponents. Success in the card matches leads to the display of adult-oriented graphics, a common trope for unlicensed cartridges found in the Asian market during the 90s.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Athena (USA)', '1986', NaN, 'SNK', '1', NaN, 'Mahjong simulation with updated graphics and adult content.', 'Win rounds of Mahjong to progress through the AV gallery.', 'The sequel to the unlicensed adult Mahjong simulation.', 'This version features improved menus and a different set of opponents compared to the first game. The gameplay remains a straightforward implementation of Mahjong, serving primarily as a vehicle for the adult-themed reward system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Athletic World (Europe)', '1986', NaN, 'Bandai', '1', NaN, 'Mahjong simulation with adult-themed visuals.', 'Outplay AI opponents in Mahjong to clear stages.', 'An unlicensed Japanese adult mahjong club simulation.', 'Developed for the Famicom without Nintendo''s approval, this game targets an adult audience. It features various club settings where players must manage their tiles effectively to win and see the hidden reward graphics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Athletic World (USA)', '1986', NaN, 'Bandai', '1', NaN, 'Pachi-Slot (Japanese slot machine) simulation.', 'Accumulate virtual credits by winning on the slot machines.', 'An unlicensed adult-themed slot machine simulator.', 'This game mimics the mechanics of Japanese Pachi-Slot parlors. Players manage their medals and try to hit Big Bonus cycles. Between sessions, adult images are displayed as part of the game''s reward structure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Atlan Cirno Nazo', 'Homebrew', NaN, 'Unknown', '1', NaN, 'Video Poker simulation with adult-themed rewards.', 'Win hands of poker to increase your score and unlock images.', 'An unlicensed adult video poker game.', 'A simple implementation of five-card draw video poker. The player bets credits to win hands (pairs, flushes, etc.), and reaching certain scoring milestones triggers the display of adult-oriented digital art.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Atlantis no Nazo (Japan)', '1986', NaN, 'Sunsoft', '1', NaN, 'Simplified soccer simulation with adult imagery.', 'Win soccer matches against opposing teams.', 'An unlicensed adult-themed sports game focusing on soccer.', 'A very basic soccer game where the player controls a team in a simplified match. Unlike standard sports games, the motivation for winning is the AV reward system integrated between matches or at the end of the game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Atlantis no Nazo (Japan) (Beta)', '1986', NaN, 'Sunsoft', '1', NaN, 'Vertical scrolling shoot ''em up with a wing-attachment system.', 'Navigate through 45 stages and destroy the Goblin boss.', 'A classic shooter famous for its 26 different wing power-ups.', 'Players pilot a ship that can attach various Wings found at the start of levels. These wings grant different abilities, such as wide shots, hammers, or shields. The game is known for its high difficulty and the strategic depth of choosing the right wing for each environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Attack Animal Gakuen (Japan)', '1987', NaN, 'Jaleco', '1', NaN, 'Puzzle-platformer with a focus on block manipulation.', 'Rearrange blocks to reach the exit of each of the 64 floors.', 'A challenging logic-based puzzle game set in the Tower of Babel.', 'Players control an archeologist who must move and stack blocks to create stairs and paths. The game features complex physics where blocks can fall or be used to crush enemies. It is highly regarded for its deep logic and satisfying eureka moments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Attack Animal Gakuen (Japan) [En by PentarouZero v1.0] (~Attack Animal Academy)', 'Hack', NaN, 'Jaleco', '1', NaN, 'Lightgun (Zapper) shooter with protective gameplay.', 'Shoot hazards and enemies to keep the baby safe as he crawls.', 'An unlicensed Zapper game where you protect a crawling baby.', 'Developed by Color Dreams, players must shoot birds, pits, and falling objects to ensure a baby reaches the end of the stage safely. It is unique for its escort style lightgun gameplay and its colorful, albeit unpolished, unlicensed aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Attack of the Killer Tomatoes (Europe)', '1990', NaN, 'Imagineering', '1', NaN, 'Side-scrolling adventure with puzzle-solving and time travel.', 'Travel between 1955, 1985, and 2015 to find items and fix the timeline.', 'A multi-era adventure based on the second and third movies.', 'Players control Marty McFly across three time periods. The game requires collecting specific items and returning them to their rightful places in time. It features a password system and various mini-games, though it''s known for its cryptic puzzles and difficult navigation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Attack of the Killer Tomatoes (USA)', '1990', NaN, 'Imagineering', '1', NaN, 'Side-scrolling beat ''em up with two-plane movement.', 'Rescue President Ronnie from the evil Dragon Ninja clan.', 'A classic arcade port of the Bad Dudes street brawler.', 'As Blade or Striker, players fight through city streets, trucks, and caves. The game features a power-up system for stronger punches and the iconic I''m bad! catchphrase. It is a quintessential 8-bit action title where you fight ninjas to save the president.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Aussie Rules Footy (Australia)', '1991', NaN, 'Beam Software', '1-2', NaN, 'Side-scrolling beat ''em up with two-plane movement.', 'Defeat the Dragon Ninja and his army to save the kidnapped president.', 'The European release of the arcade hit Bad Dudes.', 'Identical in gameplay to the US version, this port brings the intense arcade action to the NES. Players must use jumps, kicks, and collected weapons like nunchucks to defeat waves of enemies and large boss characters at the end of each stage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Auto-Upturn (Asia) (Unl) (NES)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Baseball simulation with arcade-style animations.', 'Win the league championship and defeat the All-Star team.', 'A fun and polished baseball game with humorous animations.', 'Known in Japan as Gekitou Stadium, this game is famous for its charming graphics and girls'' team mode. It features standard baseball mechanics but adds personality with funny player reactions to home runs, strikeouts, and collisions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'AV Dragon Mahjang (Asia) (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Side-scrolling beat ''em up with a variety of martial arts moves.', 'Defeat thugs and punks across the city to clear the streets.', 'A unique brawler with a focus on special combat techniques.', 'Originally part of the Power Glove line of games, players control Duke Davis. You must learn and execute different moves like the trip or headbutt to progress. The game is known for its quirky character designs and the specific moves required for different enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'AV Hanafuda Club (Asia) (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Horse racing simulation and betting strategy.', 'Manage your funds and place winning bets on horse races.', 'A realistic horse racing and gambling simulation.', 'This title focuses on the statistical side of horse racing. Players analyze horse stats, track conditions, and odds to place bets. It aims to provide an authentic Gate In experience for fans of the sport and the betting culture in Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'AV Kyuukyoku Mahjong 2 (Asia) (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Variety/Minigame collection based on celebrity impressions.', 'Compete in various challenges to become the best celebrity impersonator.', 'A wacky collection of mini-games themed around Japanese pop culture.', 'Based on a popular TV show concept, players engage in rhythm and timing games to mimic famous Japanese celebrities. It captures the Star Monomane (impressionist) craze of the early 90s with exaggerated 8-bit caricatures and humor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'AV Mahjong Club (Japan) (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Life simulation and board game with a focus on romance.', 'Navigate the theater of love to find a partner and succeed in life.', 'A quirky life-sim board game focused on relationships.', 'Players move across a board representing different stages of life, specifically focusing on dating, marriage, and family. It uses humor and random events to simulate the ups and downs of romantic life in a satirical way.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'AV Pachi Slot (Japan) (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Digital board game and life simulation.', 'Live through a virtual life and finish with the most wealth and happiness.', 'The first entry in the famous Bakushou!! Jinsei Gekijou series.', 'Similar to the Game of Life, players roll dice to move through childhood, school, and career paths. Random events can change your stats (like Intelligence or Strength), affecting your job prospects and final score in this lighthearted social simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'AV Poker (Japan) (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Digital board game and life simulation with enhanced features.', 'Succeed in life by making better choices than your opponents.', 'The sequel to the popular Famicom life-simulation board game.', 'This version improves upon the original with more detailed events, better graphics, and expanded career paths. It remains a staple of the party game genre on the Famicom, designed for multiple players to enjoy the chaotic randomness of life together.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'AV Soccer (Japan) (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Tile-matching puzzle with a gravity mechanic.', 'Clear the board by matching identical tiles in pairs.', 'An unlicensed Chinese puzzle game with a ball-themed aesthetic.', 'This title is a variation of Shisen-sho or Mahjong solitaire. Players must select matching tiles that can be connected by a line with no more than two turns. It features various layouts and a simplified visual style typical of unlicensed 8-bit puzzle collections.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'B-Wings (Japan)', '1986', NaN, 'Nintendo', '1', NaN, 'First-person futuristic sports simulation.', 'Score more goals than the opponent by blasting the Plasmorb into the goal.', 'A high-speed, 3D-perspective sci-fi sports game.', 'Developed by Lucasfilm Games, players pilot a Rotofoil craft on a checkered grid. The game features a split-screen view and focuses on rapid movement and quick turns to capture the ball. It is known for its smooth scrolling and early attempt at 3D gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Babel no Tou (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Single-screen action with physics-based flight.', 'Pop the balloons of all enemy Oicho to clear the stage.', 'A legendary arcade-style game where you fly by flapping your arms.', 'Players control a character with two balloons. By tapping the button, you flap to stay airborne. You must collide with enemies from above to pop their balloons while avoiding lightning, giant fish, and other hazards across various phases and a bonus round.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baby Boomer (USA) (Unl)', '1989', NaN, 'Color Dreams', '1', NaN, 'Single-screen action with physics-based flight.', 'Defeat waves of enemies and survive the Balloon Trip mode.', 'The original Japanese Famicom version of the iconic flight game.', 'This version established the addictive gameplay loop of flap and pop. Beyond the 2-player battle/co-op mode, it features the Balloon Trip mode, a side-scrolling endurance test where players must navigate a sea of sparks to achieve a high score.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Back to the Future (USA)', '1989', NaN, 'Beam Software', '1', NaN, 'Single-screen action with physics-based flight.', 'Eliminate all enemies in the arena to advance to the next phase.', 'The North American release of Nintendo''s classic arcade flyer.', 'Identical to the international versions, this game is celebrated for its tight controls and momentum-based physics. It served as the foundation for the flight mechanics later seen in games like Joust and Super Mario Bros. Deluxe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Back to the Future Part II & III (USA)', '1990', NaN, 'Beam Software', '1', NaN, 'Single-screen action (Pang/Buster Bros clone).', 'Destroy all bouncing bubbles by shooting them with a vertical wire.', 'An unlicensed port of the popular Pang arcade gameplay.', 'Players move horizontally at the bottom of the screen, firing a vertical harpoon. Large bubbles split into smaller ones when hit until they disappear. It is a simple but faithful clone of the arcade classic, requiring quick reflexes and spatial awareness.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bad Dudes (USA)', '1988', NaN, 'Data East', '1', NaN, 'Side-scrolling shoot ''em up with exploration elements.', 'Fly through space stages to find and destroy the enemy mothership.', 'A sci-fi shooter featuring a unique energy-management system.', 'Players control a ship that can fly in all directions while the screen scrolls. The game is known for its high difficulty and the need to collect energy items to keep your ship functional. It features diverse planetary surfaces and underground tunnel sections.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bad Dudes vs. Dragon Ninja (Europe)', '1988', NaN, 'Data East', '1', NaN, 'Grid-based puzzle with digging and item collection.', 'Collect all the snacks and find the exit in each stage.', 'A simple but addictive puzzle game where you play as a mole.', 'Players must navigate a screen filled with dirt, rocks, and food. Digging under rocks causes them to fall, which can be used to crush enemies or block paths. The goal is to collect all items while avoiding being trapped or killed by falling debris.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bad News Baseball (USA)', '1989', NaN, 'Tecmo', '1-2', NaN, 'Side-scrolling action platformer with RPG elements.', 'Travel to the Vegetable Kingdom to recover the stolen treasures.', 'A high-quality, quirky platformer with a food-themed world.', 'Players control the Banana Prince, who uses a shrinking/growing vine to reach high places and attack. The game features shops to upgrade equipment and a quiz-show mechanic. This German version is highly sought after as it was one of the few official releases in the West.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bad Street Brawler (USA)', '1989', NaN, 'Mattel', '1', NaN, 'Side-scrolling action platformer (English Translation).', 'Help the Banana Prince save his kingdom from the Great Pepper.', 'A fan-translated version of the rare German/Japanese platformer.', 'This translation allows English speakers to enjoy the witty dialogue and the quiz-game sections of this hidden gem. It fully localizes the menus, item names, and the humorous storyline involving the hero''s quest to restore his land''s stolen artifacts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baken Hisshou Gaku - Gate In (Japan)', '1991', NaN, 'Koei', '1', NaN, 'Golf simulation with swing meter and club selection.', 'Complete the 18 holes of the Pebble Beach course with the lowest score possible.', 'A realistic golf game featuring the world-famous Pebble Beach course.', 'Players must account for wind speed, direction, and terrain elevation. The game features a split-screen view showing both the character''s stance and the overhead map of the hole, allowing for strategic planning of every drive and putt.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bakushou! Star Monomane Shitennou (Japan)', '1990', NaN, 'Takara', '1', NaN, 'Turn-based grand strategy and tactical combat.', 'Overthrow the corrupt Gao Qiu and unite the outlaw bands of China.', 'A deep Koei strategy game based on the classic novel Water Margin.', 'Players manage resources, recruit heroes, and engage in hex-based tactical battles. The game is known for its high level of complexity, requiring the player to balance the popularity of their heroes with the strength of their military forces.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bakushou!! Ai no Gekijou (Japan)', '1989', NaN, 'Takara', '1', NaN, 'Side-scrolling platformer with puzzle elements.', 'Help Barbie navigate through her dreams to reach the party.', 'A colorful platformer where Barbie travels through fantasy dream worlds.', 'Players control Barbie through themed stages like Mermaid Land and Soda Shop. She can throw Z bubbles to interact with objects and ask animal friends for help. The game focuses on lighthearted exploration and simple environmental puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bakushou!! Jinsei Gekijou (Japan)', '1989', NaN, 'Takara', '1', NaN, 'Side-scrolling platformer with puzzle elements.', 'Explore dream worlds and find the perfect outfit for the big dance.', 'The North American release of the Barbie platforming adventure.', 'This version features the same gameplay as the European release. Barbie must collect items and avoid obstacles in diverse dreamscapes. It is noted for its high-quality 8-bit graphics and its appeal to the franchise''s younger fan base.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bakushou!! Jinsei Gekijou 2 (Japan)', '1990', NaN, 'Takara', '1', NaN, 'Side-scrolling platformer (Revised Version).', 'Navigate the dream worlds to prepare for Barbie''s big event.', 'An updated version of the Barbie NES game with minor bug fixes.', 'This Rev A version contains small internal code corrections to improve stability and performance compared to the initial release, while maintaining the same core gameplay mechanics and story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bakushou!! Jinsei Gekijou 3 (Japan)', '1991', NaN, 'Takara', '1', NaN, 'Barcode-scanning battle RPG (requires peripheral).', 'Scan real-world barcodes to generate characters and fight battles.', 'A unique RPG that uses a Barcode Battler device to create heroes.', 'Players use the Barcode Battler II connected to the NES to scan household items. These barcodes are converted into stats for characters and items. The game features a traditional turn-based combat system where your success depends on the power of the barcodes you find.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ball Story - Jong Yuk Chuen Suet Fa Jong II (China) (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'First-person dungeon-crawling RPG.', 'Recover the seven pieces of the Destiny Wand to save the realm.', 'A deep, party-based sequel to the classic Bard''s Tale series.', 'Featuring an improved interface for the Famicom, players manage a party of six adventurers. The game introduces larger outdoor areas and more complex dungeons, requiring careful map-making and strategic use of a wide array of spells and combat classes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ballblazer (Japan)', '1988', NaN, 'Lucasfilm Games', '1', NaN, 'First-person dungeon-crawling RPG.', 'Assemble a team of heroes to defeat the evil wizard Mangar.', 'The Japanese adaptation of the legendary PC RPG series.', 'This version features updated graphics and a more console-friendly menu system compared to the Western original. It remains a hardcore RPG experience where party management and resource conservation in deep dungeons are key to survival.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Balloon Fight (Europe)', '1984', NaN, 'Nintendo', '1', NaN, 'First-person dungeon-crawling RPG.', 'Defeat Mangar the Dark and free the city of Skara Brae.', 'The official North American console port of the PC classic.', 'A faithful adaptation of the game that helped define the dungeon-crawler genre. Players explore the city and its underworld in a first-person grid view, engaging in turn-based combat and solving cryptic riddles to progress through the story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Balloon Fight (Japan)', '1984', NaN, 'Nintendo', '1', NaN, 'Lightgun (Zapper) target shooting.', 'Hit all targets in each circus-themed act to move to the next level.', 'A colorful and fun Zapper game based on classic carnival tricks.', 'Players must shoot plates, balloons, and other objects launched by Barker Bill. The game features several modes with increasing speed and difficulty, requiring sharp reflexes and accuracy. It is known for its upbeat music and cameos from other Nintendo characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Balloon Fight (USA)', '1984', NaN, 'Nintendo', '1', NaN, 'Single-screen action with physics-based flight.', 'Eliminate all enemies in the arena to advance to the next phase.', 'The North American release of Nintendo''s classic arcade flyer.', 'Identical to the international versions, this game is celebrated for its tight controls and momentum-based physics. It served as the foundation for the flight mechanics later seen in games like Joust and Super Mario Bros. Deluxe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Balloon Monster (Unl)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Single-screen action (Pang/Buster Bros clone).', 'Destroy all bouncing bubbles by shooting them with a vertical wire.', 'An unlicensed port of the popular Pang arcade gameplay.', 'Players move horizontally at the bottom of the screen, firing a vertical harpoon. Large bubbles split into smaller ones when hit until they disappear. It is a simple but faithful clone of the arcade classic, requiring quick reflexes and spatial awareness.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baltron (Japan)', '1987', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling shoot ''em up with exploration elements.', 'Fly through space stages to find and destroy the enemy mothership.', 'A sci-fi shooter featuring a unique energy-management system.', 'Players control a ship that can fly in all directions while the screen scrolls. The game is known for its high difficulty and the need to collect energy items to keep your ship functional. It features diverse planetary surfaces and underground tunnel sections.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Banana (Japan)', '1986', NaN, 'VAP', '1', NaN, 'Grid-based puzzle with digging and item collection.', 'Collect all the snacks and find the exit in each stage.', 'A simple but addictive puzzle game where you play as a mole.', 'Players must navigate a screen filled with dirt, rocks, and food. Digging under rocks causes them to fall, which can be used to crush enemies or block paths. The goal is to collect all items while avoiding being trapped or killed by falling debris.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Banana Prince (Germany)', '1990', NaN, 'Thalion Software', '1', NaN, 'Side-scrolling action platformer with RPG elements.', 'Travel to the Vegetable Kingdom to recover the stolen treasures.', 'A high-quality, quirky platformer with a food-themed world.', 'Players control the Banana Prince, who uses a shrinking/growing vine to reach high places and attack. The game features shops to upgrade equipment and a quiz-show mechanic. This German version is highly sought after as it was one of the few official releases in the West.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Banana Prince (Germany) [En by KingMike v1.1a]', 'Hack', NaN, 'Thalion Software', '1', NaN, 'Side-scrolling action platformer (English Translation).', 'Help the Banana Prince save his kingdom from the Great Pepper.', 'A fan-translated version of the rare German/Japanese platformer.', 'This translation allows English speakers to enjoy the witty dialogue and the quiz-game sections of this hidden gem. It fully localizes the menus, item names, and the humorous storyline involving the hero''s quest to restore his land''s stolen artifacts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bananan Ouji no Daibouken (Japan)', '1986', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling action platformer with RPG elements.', 'Recover the three sacred treasures of the Vegetable Kingdom.', 'The Japanese version of the platformer known as Banana Prince.', 'This is the original Japanese release. While the core gameplay remains the same as the German version, it features different quiz questions and some minor graphical variations. It is highly regarded for its tight controls and creative level design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bandai Golf - Challenge Pebble Beach (USA)', '1988', NaN, 'Nintendo', '1', NaN, 'Golf simulation with swing meter and club selection.', 'Complete the 18 holes of the Pebble Beach course with the lowest score possible.', 'A realistic golf game featuring the world-famous Pebble Beach course.', 'Players must account for wind speed, direction, and terrain elevation. The game features a split-screen view showing both the character''s stance and the overhead map of the hole, allowing for strategic planning of every drive and putt.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bandit Kings of Ancient China (USA)', '1989', NaN, 'Koei', '1', NaN, 'Turn-based grand strategy and tactical combat.', 'Overthrow the corrupt Gao Qiu and unite the outlaw bands of China.', 'A deep Koei strategy game based on the classic novel Water Margin.', 'Players manage resources, recruit heroes, and engage in hex-based tactical battles. The game is known for its high level of complexity, requiring the player to balance the popularity of their heroes with the strength of their military forces.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Barbie (Europe)', '1991', NaN, 'Ocean', '1', NaN, 'Side-scrolling platformer with puzzle elements.', 'Help Barbie navigate through her dreams to reach the party.', 'A colorful platformer where Barbie travels through fantasy dream worlds.', 'Players control Barbie through themed stages like Mermaid Land and Soda Shop. She can throw Z bubbles to interact with objects and ask animal friends for help. The game focuses on lighthearted exploration and simple environmental puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Barbie (USA)', '1991', NaN, 'Ocean', '1', NaN, 'Side-scrolling platformer with puzzle elements.', 'Explore dream worlds and find the perfect outfit for the big dance.', 'The North American release of the Barbie platforming adventure.', 'Barbie travels through various dreamscapes like Mermaid Land and a 50s-style soda shop. Players use Z bubbles to wake up items and solve environmental puzzles. It is noted for its high-quality 8-bit graphics and charm.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Barbie (USA) (Rev A)', '1991', NaN, 'Ocean', '1', NaN, 'Side-scrolling platformer (Revised Version).', 'Navigate the dream worlds to prepare for Barbie''s big event.', 'An updated version of the Barbie NES game with minor bug fixes.', 'This Rev A version contains small internal code corrections to improve stability and performance compared to the initial release, while maintaining the same core gameplay mechanics and story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Barcode World (Japan)', '1991', NaN, 'Bandai', '1', NaN, 'Barcode-scanning battle RPG (requires peripheral).', 'Scan real-world barcodes to generate characters and fight battles.', 'A unique RPG that uses a Barcode Battler device to create heroes.', 'Players use the Barcode Battler II connected to the Famicom to scan household items. These barcodes are converted into stats for characters. The game features a traditional turn-based combat system where your success depends on the power of the barcodes you find.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bard''s Tale II, The - The Destiny Knight (Japan)', '1990', NaN, 'Interplay Productions', '1', NaN, 'First-person dungeon-crawling RPG.', 'Recover the seven pieces of the Destiny Wand to save the realm.', 'A deep, party-based sequel to the classic Bard''s Tale series.', 'Featuring an improved interface for the Famicom, players manage a party of six adventurers. The game introduces larger outdoor areas and more complex dungeons, requiring careful map-making and strategic use of spells.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bard''s Tale, The - Tales of the Unknown (Japan)', '1988', NaN, 'Interplay Productions', '1', NaN, 'First-person dungeon-crawling RPG.', 'Assemble a team of heroes to defeat the evil wizard Mangar.', 'The Japanese adaptation of the legendary PC RPG series.', 'This version features updated graphics and a more console-friendly menu system compared to the Western original. It remains a hardcore RPG experience where resource conservation in deep dungeons is key to survival.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bard''s Tale, The - Tales of the Unknown (USA)', '1988', NaN, 'Interplay Productions', '1', NaN, 'First-person dungeon-crawling RPG.', 'Defeat Mangar the Dark and free the city of Skara Brae.', 'The official North American console port of the PC classic.', 'A faithful adaptation of the game that helped define the dungeon-crawler genre. Players explore the city in a first-person grid view, engaging in turn-based combat and solving cryptic riddles to progress through the story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Barker Bill''s Trick Shooting (Europe)', '1990', NaN, 'Nintendo', '1-2', NaN, 'Lightgun (Zapper) target shooting.', 'Hit all targets in each circus-themed act to move to the next level.', 'A colorful and fun Zapper game based on classic carnival tricks.', 'Players must shoot plates, balloons, and other objects launched by Barker Bill. The game features several modes with increasing speed and difficulty, requiring sharp reflexes. It includes cameos from other Nintendo characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Barker Bill''s Trick Shooting (USA)', '1990', NaN, 'Nintendo', '1-2', NaN, 'Lightgun (Zapper) target shooting.', 'Score enough points to progress through the circus acts.', 'The North American release of Barker Bill''s Zapper game.', 'Identical to the European version, it offers four different types of target shooting mini-games. It is one of the few games that truly utilizes the Zapper''s accuracy for fast-paced, arcade-style shooting galleries.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Base Wars - Cyber Stadium Series (USA)', '1991', NaN, 'Konami', '1-2', NaN, 'Combat-heavy baseball simulation with robots.', 'Win the Cyber Stadium championship by outscoring or outfighting rivals.', 'A unique sports game where robots play baseball and fight.', 'Players control teams of robots. If a play is close, a fighting mini-game occurs; destroying the opponent''s robot counts as an out. Players can buy parts to upgrade their robots'' armor, speed, and weaponry.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baseball (Japan)', '1983', NaN, 'Nintendo', '1-2', NaN, 'Sports simulation focusing on fundamental baseball.', 'Outscore the AI or a second player in a 9-inning game.', 'The earliest baseball title for the Famicom/NES.', 'Part of the original Sports Series, it features simple pitching and batting mechanics. While basic by modern standards, it set the foundation for the genre on consoles, allowing for 2-player competitive matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baseball (USA, Europe)', '1983', NaN, 'Nintendo', '1-2', NaN, 'Fundamental sports simulation.', 'Outscore the opponent over nine innings of play.', 'The international release of Nintendo''s classic launch-title baseball game.', 'Featuring simple controls and iconic 8-bit sprites, this version focuses on the core mechanics of pitching, batting, and base running. It is a faithful port of the Japanese original and one of the best-selling early sports titles for the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baseball Fighter (Japan)', '1991', NaN, 'Irem', '1-2', NaN, 'Arcade-style baseball simulation.', 'Win the league championship and develop your team''s skills.', 'A high-energy baseball game with unique character designs.', 'Known for its fast-paced gameplay and vibrant graphics, this title emphasizes the competitive spirit of Japanese professional baseball. It features a variety of teams and allows players to manage rosters to a limited degree during the season.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baseball Simulator 1.000 (USA)', '1989', NaN, 'Culture Brain', '1-2', NaN, 'Baseball simulation with deep customization and Ultra moves.', 'Create a custom team and win the World Series.', 'A comprehensive baseball sim known for its Ultra Plays and stat tracking.', 'Known in Japan as Choujin Ultra Baseball, this game allows players to use supernatural powers like exploding pitches or meteor hits. It also features a deep editing mode where players can create teams, edit names, and track full-season statistics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baseball Star - Mezase Sankanou!! (Japan)', '1989', NaN, 'SNK', '1-2', NaN, 'Baseball simulation with RPG elements.', 'Guide your team from the bottom to the top of the league.', 'The Japanese precursor to the famous Baseball Stars series.', 'Developed by SNK, this game introduced the ability to earn money from games to hire better players or upgrade existing ones. It blends sports action with a sense of progression usually found in RPGs, making it highly addictive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baseball Stars (USA)', '1989', NaN, 'SNK', '1-2', NaN, 'Baseball simulation with RPG-style team management.', 'Build a powerhouse team by winning games and hiring stars.', 'A revolutionary sports title featuring battery backup for saving stats.', 'This game is legendary for being one of the first to allow players to create their own teams and players. As you win games, you earn money to upgrade player attributes, making it one of the deepest and most beloved sports games on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Baseball Stars II (USA)', '1992', NaN, 'SNK', '1-2', NaN, 'Arcade-style baseball with high-quality animations.', 'Lead your chosen team to the championship in a competitive league.', 'The sequel to the SNK classic, focusing on refined graphics and speed.', 'While it removed the team creation feature of the first game, it greatly improved the visual presentation and animations. The gameplay is faster, the sprites are larger, and it offers a more arcade-perfect feel compared to its predecessor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bases Loaded (USA) (Rev A)', '1988', NaN, 'Jaleco', '1-2', NaN, 'Realistic baseball simulation with a TV-style perspective.', 'Win the pennant by defeating all other teams in the league.', 'A popular sports game known for its unique behind-the-pitcher camera.', 'This Rev A version fixed minor bugs from the initial release. It was famous for using real-life player stats (though not licensed names) and a perspective that mimicked a television broadcast, providing a more immersive experience for fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bases Loaded 3 (USA)', '1990', NaN, 'Jaleco', '1-2', NaN, 'Baseball simulation with a focus on perfection and skill.', 'Defeat the perfect team to prove your mastery.', 'The third installment in the Bases Loaded series by Jaleco.', 'This entry shifted focus toward a rating system where players are graded on their performance. To beat the game, you don''t just have to win; you have to play a perfect game against a highly skilled computer-controlled team.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bases Loaded 4 (USA)', '1993', NaN, 'Jaleco', '1-2', NaN, 'Traditional baseball simulation with updated rosters.', 'Win the league championship against increasingly difficult AI.', 'The final entry of the Bases Loaded series on the NES.', 'Released late in the console''s life, it features the most refined graphics and AI of the series. It returned to a more traditional season structure while maintaining the signature behind-the-pitcher viewpoint and detailed player stats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bases Loaded II - Second Season (USA)', '1988', NaN, 'Jaleco', '1-2', NaN, 'Multi-team baseball simulation with expanded stats.', 'Navigate a full 132-game season to win the championship.', 'The direct sequel to the original Bases Loaded hit.', 'Often considered one of the best in the series, it introduced a faster game speed and a more detailed biorhythm system that affects player performance based on the day. It features 12 teams divided into two Western-style divisions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bashi Bazook - Morphoid Masher (USA) (Proto)', 'Prototype', NaN, 'Unknown', '1', NaN, 'Side-scrolling action platformer.', 'Defeat alien Morphoids and clear each stage within the time limit.', 'An unreleased prototype featuring a shape-shifting protagonist.', 'Players control a character who can transform into different forms to overcome obstacles and enemies. As a prototype, it shows a unique concept that was never officially published, featuring fast-paced action and experimental level designs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman - Return of the Joker (Europe)', '1991', NaN, 'Sunsoft', '1', NaN, 'Run and gun action platformer.', 'Pursue and defeat the Joker to prevent him from destroying Gotham.', 'The European version of the visually stunning Batman sequel.', 'Known for pushing the NES hardware to its limits, this game features massive sprites and detailed backgrounds. Batman uses his Sonic Neutralizer to fire various projectile types (Power, Blitz, Twin, etc.) in a more shooting-oriented style than the first game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman - Return of the Joker (USA)', '1991', NaN, 'Sunsoft', '1', NaN, 'Run and gun action platformer.', 'Track down the Joker and his high-tech army across industrial stages.', 'The North American release of Return of the Joker.', 'Often praised for its 16-bit quality graphics on 8-bit hardware, it features complex boss fights and a weapon upgrade system. Players must manage their energy to fire powerful charged shots and navigate through side-scrolling and flying stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman - The Video Game (Europe)', '1989', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action platformer with wall-jumping.', 'Fight through the streets of Gotham to face the Joker at the Cathedral.', 'The official European release based on the 1989 Tim Burton film.', 'Widely considered one of the best NES games, it features tight controls and a distinctive wall-jump mechanic. Batman uses punches and three sub-weapons (Batarang, Dirks, and Bat-Disk) to navigate stages inspired by the movie''s dark aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman - The Video Game (USA)', '1989', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action platformer with wall-jumping.', 'Navigate 5 stages to stop the Joker''s plot in Gotham City.', 'The legendary Sunsoft action game based on the Batman movie.', 'Renowned for its atmospheric music and cinematic cutscenes, this version follows Batman through iconic locations like the Axis Chemical Factory. The game is famous for its high difficulty, particularly the final climb to the Joker.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman - The Video Game (USA) (Beta)', '1989', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action platformer (Early version).', 'Test the levels and mechanics of the Caped Crusader''s adventure.', 'A beta build of the first Batman game by Sunsoft.', 'This version contains minor differences in enemy placement and level assets compared to the final release. It offers a fascinating look at the development process and balancing of what would become a classic 8-bit title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman - The Video Game (USA) [Hack by Deespence2929 v1.0] (~Batman - Easy)', 'Hack', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action platformer (Romhack).', 'Experience the classic Batman game with reduced difficulty.', 'A fan-made hack designed to make the game more accessible.', 'This modification typically increases Batman''s health, provides more sub-weapon ammunition, or reduces enemy damage. It is intended for players who find the original Sunsoft difficulty curve too steep but want to experience the story and levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman (Japan)', '1986', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action platformer with wall-jumping.', 'Defeat the criminals of Gotham and stop the Joker.', 'The Japanese Famicom version of the Sunsoft Batman classic.', 'While identical in gameplay to the US/EU versions, it features the original Japanese text and slightly different branding. It remains a showcase of Sunsoft''s technical mastery of the Famicom''s sound and graphics chips.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman Bros. Co-Op 1.2', 'Homebrew', NaN, 'Homebrew', '2', NaN, 'Side-scrolling action platformer (Modern Hack/Mod).', 'Play with a friend in a custom co-op mode.', 'A modern romhack that adds 2-player simultaneous play to Batman.', 'This impressive technical feat allows two players to control Batman and a partner (often recolored) simultaneously through the original levels. It adjusts the mechanics to ensure both players can navigate the screen together.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman Returns (Europe)', '1992', NaN, 'Konami', '1', NaN, 'Side-scrolling beat ''em up and driving.', 'Stop the Penguin and Catwoman from taking over Gotham City.', 'A late-release brawler based on the second Batman movie.', 'Developed by Konami, this game features large, detailed sprites and focus on hand-to-hand combat. It includes both traditional side-scrolling fighting stages and vehicle-based levels featuring the Batmobile, making it a diverse action experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batman Returns (USA)', '1992', NaN, 'Konami', '1', NaN, 'Side-scrolling beat ''em up and driving.', 'Defeat the Penguin and Catwoman to save Gotham''s Christmas.', 'The North American release of Konami''s Batman sequel.', 'Unlike the Sunsoft games, this is a pure brawler. Batman can grab and throw enemies against walls or each other. It features impressive graphics and sound for the NES, and includes iconic stages like the Batmobile chase and the showdown at the Arctic World.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Batsu & Terry (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer with character swapping.', 'Defeat rival gang members across various urban stages.', 'An action game based on a popular Japanese high school baseball manga.', 'Players can switch between the two protagonists, Batsu and Terry. Although based on a baseball manga, it’s an action game where they use baseball-themed attacks (like hitting balls) to fight enemies. It features branching paths and a unique map system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle Baseball (Japan)', '1991', NaN, 'Banpresto', '1-2', NaN, 'Sports simulation with SD (Super Deformed) characters.', 'Win the tournament using a team of robots and anime-style heroes.', 'A wacky baseball game featuring Banpresto''s crossover characters.', 'This title features iconic characters from Gundam, Ultraman, and Kamen Rider playing baseball. Each team has special super moves and stats, making it a Compati Hero sports spin-off that focuses more on fun and fanservice than realism.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle Chess (USA)', '1988', NaN, 'Interplay Productions', '1', NaN, 'Turn-based strategy and chess simulation.', 'Checkmate the opponent''s King in a fantasy-themed chess game.', 'A version of chess where the pieces come to life and fight.', 'Based on the famous computer game, the chess pieces are animated characters. When a capture occurs, the game shows a brief battle animation. It includes various AI difficulty levels and the option for 2-player matches with a unique fantasy aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle City (Japan)', '1985', NaN, 'Namco', '1', NaN, 'Top-down multi-directional tank shooter.', 'Protect your eagle base and destroy all 20 enemy tanks per stage.', 'Namco''s classic tank combat game, a staple of Famicom bootlegs.', 'Players control a tank on a grid of bricks, bushes, and water. You can shoot through walls and collect power-ups like shovels (to reinforce the base) or stars (to upgrade your tank''s fire rate and armor). It is famous for its Construction Mode level editor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle City (Japan) [Hack by AnS v0.999] (~Binary City)', 'Hack', NaN, 'Namco', '1', NaN, 'Top-down multi-directional tank shooter (Romhack).', 'Navigate complex new levels in this technical modification.', 'An advanced hack of Battle City with modified physics and levels.', 'Also known as Binary City, this hack introduces new level designs and sometimes alters the enemy AI or projectile speed. It is aimed at fans of the original who want a fresh, more difficult challenge using the classic engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle City 4 Players Hack (v1.3)', 'Hack', NaN, 'Namco', '4', NaN, 'Top-down multi-directional tank shooter (Romhack).', 'Defend the base with up to three friends simultaneously.', 'A modern technical hack that enables 4-player gameplay.', 'This impressive mod allows four players to play at once (using a Four-Score or similar adapter). The levels are often adjusted to accommodate more tanks on screen, turning the classic defensive shooter into a chaotic multiplayer experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle Fleet (Japan)', '1988', NaN, 'Namco', '1', NaN, 'Naval turn-based strategy and simulation.', 'Command a fleet to win naval battles through tactical positioning.', 'A strategy game focused on Pacific-style naval warfare.', 'Players manage a fleet of ships, including carriers and battleships. The game requires careful planning of movement and firing arcs. It features a split-screen view for combat animations and is one of the more technical military sims on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle Formula (Japan)', '1991', NaN, 'Konami', '1', NaN, 'Top-down high-speed vehicular combat.', 'Race through futuristic highways while shooting down enemy vehicles.', 'One of the most technically impressive racers/shooters on the system.', 'Known in the West as 8 Eyes (erroneously) or more correctly related to Super Spy Hunter, it features incredible scrolling and parallax effects. Players drive a transforming car-boat-plane, using missiles and shields to survive a relentless mechanical army.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle of Olympus, The (Europe)', '1989', NaN, 'Infinity', '1', NaN, 'Side-scrolling action-RPG with exploration.', 'Travel across ancient Greece to rescue your lover, Helena, from Hades.', 'A deep, Greek mythology-themed adventure similar to Zelda II.', 'Players visit famous cities like Athens and Crete, gaining weapons and items from Olympian gods. It features a non-linear world, a password system, and challenging combat. It is highly praised for its atmosphere, music, and faithful mythological references.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle of Olympus, The (USA)', '1989', NaN, 'Infinity', '1', NaN, 'Side-scrolling action-RPG with exploration.', 'Rescue your beloved Helene from the clutches of Hades.', 'The North American release of the epic Greek mythology adventure.', 'Identical to the European version, players explore ancient Greece in a non-linear fashion. By gathering items like the Harp of Apollo or the Sandals of Hermes, you gain access to new areas. It is widely considered a hidden gem for its depth and atmosphere.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle Stadium - Senbatsu Pro Yakyuu (Japan)', '1990', NaN, 'Namco', '1-2', NaN, 'Sports simulation with SD (Super Deformed) characters.', 'Win the Koshien-style tournament with your chosen baseball team.', 'A quirky, arcade-style baseball game featuring cute characters.', 'This title focuses on the high school baseball tournament craze in Japan. It features fast-paced pitching and batting with a focus on fun, featuring specialized animations for home runs and strikeouts with a distinct chibi art style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battle Storm (Japan)', '1991', NaN, 'HAL Laboratory', '1', NaN, 'Top-down tactical tank combat.', 'Destroy the enemy''s headquarters while defending your own.', 'A strategic tank shooter with a focus on base defense.', 'Unlike the arcade style of Battle City, this game leans more into tactical movement. Players must manage their units across a map, utilizing terrain and power-ups to outmaneuver the enemy AI in a series of increasingly difficult missions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battleship (Europe) (En,Fr,De,Es)', '1989', NaN, 'Beam Software', '1', NaN, 'Turn-based grid strategy (Board Game).', 'Sink all of the opponent''s hidden ships before they sink yours.', 'A digital adaptation of the classic Milton Bradley board game.', 'This version includes a Super mode where players can use special weapons and different types of radar. The European release features multiple languages and detailed animations of the missiles firing and ships exploding in a cinematic split-screen.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battleship (USA)', '1990', NaN, 'Beam Software', '1', NaN, 'Turn-based grid strategy (Board Game).', 'Guess the coordinates of the enemy fleet to achieve total victory.', 'The North American release of the strategic naval combat game.', 'It brings the classic hit or miss gameplay to the NES. It features both a traditional mode that mimics the board game and an action-oriented mode with power-ups and varied mission objectives, providing more depth than the physical version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battletank (USA)', '1990', NaN, 'Namco', '1', NaN, 'First-person tank simulation.', 'Complete 10 dangerous missions in a futuristic war zone.', 'A cockpit-view tank shooter focused on mission objectives.', 'Players pilot the Battletank from a first-person perspective. The gameplay involves using a radar to track enemies and switching between different weapon types (shells, missiles, and machine guns) to destroy tanks, helicopters, and bunkers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battletoads (Europe)', '1991', NaN, 'Rare', '1', NaN, 'Side-scrolling beat ''em up and multi-genre action.', 'Rescue Pimple and Princess Angelica from the Dark Queen.', 'The European version of the notoriously difficult action classic.', 'Developed by Rare, this game is a technical marvel. It features Turbo Tunnel speeder bike levels, rappelling down pits, and traditional brawling. It is famous for its punishing difficulty and high-quality animations and music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battletoads (Japan)', '1991', NaN, 'Rare', '1', NaN, 'Side-scrolling beat ''em up and multi-genre action.', 'Defeat the Dark Queen''s forces across 12 diverse stages.', 'The Japanese Famicom version of the legendary Battletoads.', 'While the gameplay remains largely the same, this version is notable for being slightly easier than the US release (specifically in the speeder bike and Volkmire''s Inferno levels) to better suit the Japanese market''s preference at the time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battletoads (USA)', '1991', NaN, 'Rare', '1', NaN, 'Side-scrolling beat ''em up and multi-genre action.', 'Survive the ultimate challenge and defeat the Dark Queen.', 'The North American release of the iconic and brutal Battletoads.', 'Known for its intense difficulty and creative level design, it pushes the NES hardware with pseudo-3D effects and massive boss sprites. It remains a staple of 8-bit gaming history, testing the reflexes and patience of even the best players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battletoads & Double Dragon - on Ragnarok', 'Homebrew', NaN, 'Rare', '1', NaN, 'Side-scrolling beat ''em up (Crossover).', 'Stop the alliance between the Dark Queen and the Shadow Boss.', 'An epic crossover between the Battletoads and Double Dragon series.', 'Players can choose from three Toads or two Dragons (Billy and Jimmy Lee). The game combines the mechanics of both franchises, allowing for 2-player simultaneous play. It features space-shooter stages and intense brawling across the spaceship Ratship.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battletoads & Double Dragon - The Ultimate Team (Europe)', '1993', NaN, 'Rare', '1', NaN, 'Side-scrolling beat ''em up (Crossover).', 'Defeat the alliance of the Dark Queen and the Shadow Warriors.', 'The European release of the ultimate 8-bit action crossover.', 'Featuring characters from both franchises, players choose between the Toads or the Lee brothers. The game is famous for its large sprites, improved 2-player cooperative mechanics, and a variety of stages including brawling, space shooting, and 3D-perspective climbing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battletoads & Double Dragon - The Ultimate Team (USA)', '1993', NaN, 'Rare', '1', NaN, 'Side-scrolling beat ''em up (Crossover).', 'Journey to the Colossus spaceship to stop the ultimate evil team.', 'The North American version of the Toads and Dragons team-up.', 'This version is identical to the European one, providing a slightly more balanced difficulty curve than the original Battletoads. It is highly regarded for its catchy soundtrack and the fun of using Battletoads'' smash attacks on Double Dragon''s classic enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Battletoads changed colors', '1993', NaN, 'Rare', '1', NaN, 'Side-scrolling beat ''em up (Romhack).', 'Complete the game with modified character palettes.', 'A visual modification of the original Battletoads.', 'This is a simple cosmetic hack that alters the colors of the protagonist Toads (Rash, Zitz, and Pimple). While the core gameplay and extreme difficulty remain unchanged, it offers a fresh aesthetic for long-time fans of the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'BB Car (Unl)', 'Hack', NaN, 'Rare', '1', NaN, 'Top-down vehicular combat and maze navigation.', 'Collect all items in the maze while avoiding or crashing into enemy cars.', 'An unlicensed car combat game similar to Rally-X.', 'Players control a small car in a large maze, trying to clear stages by collecting points. The game features simple graphics and was commonly found on multi-carts in the 90s. It focuses on quick turns and using smoke or projectiles to stop pursuing vehicles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Be-Bop-Highschool - Koukousei Gokuraku Densetsu (Japan)', '1989', NaN, 'Data East', '1', NaN, 'Menu-based adventure and RPG.', 'Navigate the tough life of a high school delinquent to gain respect.', 'An adventure game based on the popular manga and anime.', 'Players control the duo Hiroshi and Toru through a series of dialogue choices and exploration. The game captures the 80s Japanese delinquent culture, featuring school rivalries, street fights (in RPG style), and humorous interactions with various characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Beauty and the Beast (Europe)', '1992', NaN, 'Probe Software', '1', NaN, 'Side-scrolling action platformer.', 'Guide the Beast through the castle and forest to break the curse.', 'A European-exclusive Disney license with high-quality visuals.', 'Based on the animated classic, players control the Beast. He can punch, jump, and climb walls. The game is surprisingly dark and difficult, requiring precise platforming to protect the castle from Belle''s villagers and Gaston''s final assault.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bee 52 (USA) (Unl)', '1991', NaN, 'Color Dreams', '1', NaN, 'Side-scrolling fly-and-collect action.', 'Collect nectar from flowers and return it to the hive.', 'A unique unlicensed game starring a bee with big eyes.', 'Developed by Codemasters, players control Bee 52 through garden environments. You must sting enemies and navigate spider webs to collect enough nectar. It features a distinct visual style and physics-based flying that makes it stand out from typical shooters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Beetlejuice (USA)', '1989', NaN, 'Rare', '1', NaN, 'Side-scrolling action platformer with puzzle elements.', 'Help Beetlejuice scare the Deetzes out of their new home.', 'A platformer based on the Beetlejuice animated series.', 'Players control the Ghost with the Most through various spooky levels. You can buy scares (power-ups) from a shop and must use specific tricks to defeat bosses. It is known for its strange physics and high difficulty in the later levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Best Keiba - Derby Stallion (Japan)', '1991', NaN, 'Koei', '1', NaN, 'Horse racing management and breeding simulation.', 'Breed and train a champion horse to win the Japan Derby.', 'The first entry in the long-running Derby Stallion franchise.', 'This game focuses heavily on the simulation aspect of horse racing. Players manage stables, choose bloodlines for breeding, and decide on training regimens. It was a massive hit in Japan, starting a craze for statistical sports simulations on consoles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Best Keiba - Derby Stallion (Japan) (Rev A)', '1991', NaN, 'Koei', '1', NaN, 'Horse racing management (Revised Version).', 'Manage your stable and win prestigious races in Japan.', 'An updated version of the original Derby Stallion with bug fixes.', 'This Rev A version contains minor technical improvements and potentially rebalanced horse stats from the initial release. The core gameplay remains the same deep, menu-driven management experience that rewards patience and strategic planning.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Best of the Best - Championship Karate (Europe)', '1993', NaN, 'Loriciels', '1', NaN, 'One-on-one martial arts simulation.', 'Train your fighter and win the Kumite world championship.', 'A realistic kickboxing/karate simulator with deep customization.', 'Players can customize their fighter''s moveset from a variety of kicks and punches. The game focuses on technical combat, requiring precise timing for blocks and counters. It features a training mode to build stats before entering the main tournament.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Best of the Best - Championship Karate (USA)', '1993', NaN, 'Loriciels', '1', NaN, 'One-on-one martial arts simulation.', 'Rise through the ranks of the international karate circuit.', 'The North American release of the technical fighter Best of the Best.', 'Identical to the European version, it is known for its fluid character animations (for the era) and a focus on realism over arcade action. Players must manage their stamina and health carefully during the grueling 3-round matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Best Play Pro Yakyuu ''90 (Japan)', '1990', NaN, 'Namco', '1', NaN, 'Baseball management simulation.', 'Manage a professional team to win the 1990 season championship.', 'A data-heavy baseball sim focused on coaching and management.', 'This update to the series features the full 1990 Japanese league rosters. Players do not control the athletes directly during games; instead, you act as the manager, making tactical substitutions and strategic calls based on detailed player statistics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Best Play Pro Yakyuu (Japan)', '1988', NaN, 'Namco', '1', NaN, 'Baseball management simulation.', 'Lead your team to victory through strategic roster management.', 'The first entry in the acclaimed Best Play Pro Yakyuu series.', 'A pioneer in the manager-only sports genre on the Famicom. It emphasizes simulation over action, allowing players to edit teams and track extensive stats throughout a full season. It was highly successful in Japan for its strategic depth.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Best Play Pro Yakyuu (Japan) (Rev A)', '1988', NaN, 'Namco', '1', NaN, 'Baseball management simulation (Revised).', 'Guide your team to the pennant with updated management tools.', 'An updated version of the original baseball management sim.', 'This Rev A version contains minor technical refinements and bug fixes over the initial release, ensuring more stable simulation results and smoother menu navigation for the player-manager.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Best Play Pro Yakyuu II (Japan)', '1992', NaN, 'Namco', '1', NaN, 'Baseball management simulation.', 'Outsmart rival managers to win the league title.', 'The second major installment in the management-focused series.', 'This sequel expanded on the original''s formula with improved AI and more detailed player data. It allowed for deeper customization of team strategies, such as setting specific player tendencies for batting and pitching.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Best Play Pro Yakyuu Special (Japan)', '1993', NaN, 'Namco', '1', NaN, 'Baseball management simulation.', 'Compete in a specialized league with advanced stat tracking.', 'A special edition of the series with refined simulation engines.', 'This Special version features enhanced data management and potentially new team configurations. It remains focused on the armchair manager experience, where victory is earned in the dugout through spreadsheets and tactical decisions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bible Adventures (USA) (Unl)', '1991', NaN, 'Wisdom Tree', '1', NaN, 'Side-scrolling action platformer (Unlicensed).', 'Complete three stories: Noah''s Ark, Baby Moses, and David and Goliath.', 'A well-known religious-themed multi-game by Wisdom Tree.', 'Players pick one of three adventures. The gameplay mostly involves picking up and carrying objects (or animals) to a goal. It is famous for its unique stacking mechanic where Noah can carry multiple animals at once to his ark.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bible Adventures (USA) (Unl) (v1.1)', '1991', NaN, 'Wisdom Tree', '1', NaN, 'Side-scrolling action platformer (v1.1).', 'Navigate biblical challenges to complete the missions.', 'An updated version of the unlicensed Bible Adventures.', 'This version features minor graphical tweaks and bug fixes from the initial release. The gameplay remains the same, focusing on non-violent tasks like rescuing animals or protecting baby Moses from Egyptian guards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bible Adventures (USA) (Unl) (v1.2)', '1991', NaN, 'Wisdom Tree', '1', NaN, 'Side-scrolling action platformer (v1.2).', 'Carry out divine tasks across three different game modes.', 'The final refined version of the Wisdom Tree classic.', 'Version 1.2 is the most stable release of the game, fixing several glitches found in the early unlicensed cartridges. It retains the signature gameplay of lifting and throwing objects to solve simple environmental puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bible Adventures (USA) (Unl) (v1.3)', '1991', NaN, 'Wisdom Tree', '1', NaN, 'Side-scrolling action platformer (v1.3).', 'Complete the three biblical quests: Noah, Moses, and David.', 'The final technical revision of the religious multi-game.', 'This unlicensed version 1.3 is the most polished iteration by Wisdom Tree. It features the same lifting and carrying mechanics across three different stories, with further minor bug fixes to ensure the game doesn''t crash on newer NES clones.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bible Buffet (USA) (Unl) (v6.0)', '1993', NaN, 'Wisdom Tree', '1', NaN, 'Digital board game with mini-games (v6.0).', 'Navigate a food-themed board to reach the end of the buffet.', 'A quirky, unlicensed party game based on food and health.', 'Players roll dice to move across a board. Landing on certain spaces triggers top-down action mini-games where you must collect good food and avoid junk food. Version 6.0 is the standard stable release for this unique, non-violent title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Big Nose and the Witchdoctor (USA) (Unl) (Beta)', 'Prototype', NaN, 'Codemasters', '1', NaN, 'Side-scrolling action platformer (Beta).', 'Rescue your tribe and defeat the evil Witchdoctor.', 'An unreleased prototype of the second Big Nose adventure.', 'This prototype shows an early version of the prehistoric platformer. Players control Big Nose as he jumps through islands and uses stones to defeat enemies. It features different level layouts and music compared to the final Freaks Out release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Big Nose Freaks Out (USA) (Unl)', '1992', NaN, 'Codemasters', '1', NaN, 'Side-scrolling action platformer with skateboarding.', 'Recover your stolen gold from the prehistoric thief.', 'A fast-paced unlicensed sequel featuring a caveman on a board.', 'Big Nose now moves on a primitive skateboard, adding a momentum-based feel to the platforming. The game is known for its high speed, colorful graphics, and the ability to use a club and stones to defeat enemies while navigating large levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Big Nose the Caveman (USA) (Unl)', '1991', NaN, 'Codemasters', '1', NaN, 'Side-scrolling action platformer with exploration.', 'Find your dinner by chasing a pterodactyl across several islands.', 'A prehistoric adventure featuring a hungry caveman.', 'Big Nose travels through four islands (Paradise, Monster, etc.). Players can collect bones to buy power-ups in shops. It is a solid platformer for the NES, despite being an unlicensed release by the company Camerica.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bigfoot (Europe)', '1991', NaN, 'Codemasters', '1', NaN, 'Monster truck racing and car-crushing events.', 'Win the truck championship by completing races and challenges.', 'A licensed monster truck game featuring the famous Bigfoot.', 'Players compete in side-scrolling races against rival trucks and participate in car crushing events. Between levels, you must manage your budget to repair and upgrade the truck''s engine, tires, and suspension.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bigfoot (USA)', '1989', NaN, 'Beam Software', '1-2', NaN, 'Monster truck racing and car-crushing events.', 'Defeat the Blackbeard truck and win the Bigfoot trophy.', 'The North American release of the monster truck simulation.', 'Identical to the European version, it offers a mix of arcade racing and light management. It features a unique cockpit view during certain segments and requires careful driving to avoid flipping the truck on rough terrain.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bikkuri Nekketsu Shin Kiroku! - Harukanaru Kin Medal (Japan)', '1989', NaN, 'Beam Software', '1-2', NaN, 'Sports/Athletic competition with combat elements.', 'Win the gold medal in five unique and violent Olympic events.', 'A wacky sports entry in the Nekketsu (Kunio-kun) series.', 'Known in the West as Crash ''n'' the Boys: Street Challenge, this game features bizarre events like Hammer Throw Golf and Building Pole Vault. Players can use physical attacks to hinder opponents, staying true to the Nekketsu spirit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bikkuriman World - Gekitou Sei Senshi (Japan)', '1992', NaN, 'Technōs Japan', '1-2', NaN, 'Turn-based RPG with card-battle elements.', 'Help the Bikkuriman heroes defeat the devil forces.', 'An RPG based on the popular Japanese sticker and anime franchise.', 'Players explore a top-down world and engage in battles that use a card-based system for attacks and defenses. It features many characters from the Bikkuriman universe and is known for its bright, anime-accurate 8-bit art style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bill & Ted''s Excellent Video Game Adventure (USA)', '1987', NaN, 'Taito', '1', NaN, 'Adventure with mini-games and time travel.', 'Find the historical figures and return them to the future.', 'A non-linear adventure based on the cult classic movie.', 'Players control Bill and Ted as they travel to different time periods (Western, Medieval, etc.). You must talk to NPCs, find specific items, and avoid historical hazards to progress. It is known for its confusing navigation and top-down exploration.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bill Elliott''s NASCAR Challenge (USA)', '1991', NaN, 'LJN', '1', NaN, 'First-person perspective racing simulation.', 'Win the NASCAR championship by placing first in high-speed oval races.', 'An early NASCAR racing sim endorsed by champion Bill Elliott.', 'Players can customize their car''s spoiler, tires, and gear ratios. The game features a cockpit view and focuses on the strategy of drafting and managing pit stops during long races on authentic tracks like Daytona and Talladega.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Binary Land (Japan)', '1991', NaN, 'Konami', '1-2', NaN, 'Single-screen mirror-movement puzzle.', 'Guide two penguins to meet at the top-center heart simultaneously.', 'A charming puzzle game where you control two characters at once.', 'Players control Gurin and Malon. The catch is that they move in mirror-image to each other; when you press left, one moves left and the other moves right. You must navigate spider webs and enemies to make them meet at the exit at the exact same time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bing Guo 75 (Asia) (Unl) (Famicom)', '1985', NaN, 'Namco', '1', NaN, 'Bingo gambling simulation.', 'Match the numbers on your card to win virtual credits.', 'An unlicensed Bingo game released for the Asian Famicom market.', 'A straightforward implementation of the 75-ball bingo game. Players manage multiple cards and watch as numbers are drawn randomly. It features basic graphics and was typically found on gambling-focused multi-carts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bingo 75 (Asia) (Unl) (NES)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Bingo gambling simulation.', 'Complete a line or pattern on your bingo card to win.', 'The NES-pin version of the unlicensed Bingo 75 game.', 'Identical in gameplay to the Famicom version, this title provides a digital bingo experience. It is designed for quick sessions of luck-based play, featuring automated number marking and a simple interface.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bio Force Ape (US Prototype)', 'Unlicensed', NaN, 'Unlicensed', '1', NaN, 'Fast-paced side-scrolling action platformer.', 'Use professional wrestling moves to defeat a terrorist organization.', 'A legendary lost prototype featuring a genetically enhanced ape.', 'Long considered vaporware, this prototype was eventually found. It features an ape with incredible speed and agility who can perform wrestling slams on enemies. It is known for its frantic pace and bizarre, high-energy cutscenes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bio Miracle Bokutte Upa (Japan)', 'Prototype', NaN, 'Nintendo', '1', NaN, 'Side-scrolling action platformer.', 'Save the kingdom from the demon Zauras using a magical rattle.', 'A unique Konami platformer starring a heroic baby.', 'Players control Upa, a prince who can inflate enemies with his rattle, turning them into floating platforms. The game features creative levels (like a world made of cake) and the signature high-quality music and polish associated with Konami''s 8-bit era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bio Miracle Bokutte Upa (Japan) [En by Vice v1.0] (~Bio Miracle Baby Upa!!)', '1988', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer (English Translation).', 'Defeat the demon Zauras and restore peace to the Baby Kingdom.', 'A fan-translated version of Konami''s charming baby-themed platformer.', 'This translation makes the story and menus accessible to English speakers. It retains all the original gameplay mechanics, including Upa’s ability to dig through certain materials and use inflated enemies to reach secret areas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bio Senshi Dan - Increaser Tono Tatakai (Japan)', 'Hack', NaN, 'Konami', '1', NaN, 'Side-scrolling action-adventure with exploration.', 'Destroy the Increasers before they take over the Earth.', 'A dark sci-fi action game with a focus on biological threats.', 'Players control Dan, a warrior who must navigate mazes and destroy alien organisms. The game features a unique timer system where enemies grow stronger as time passes, requiring a balance between careful exploration and speed.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bio Senshi Dan - Increaser Tono Tatakai (Japan) [En by Abstract Crouton v1.5] (~Bio-Warrior Dan - The Inkliezar Battle)', '1988', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action-adventure (English Translation).', 'Eradicate the Increaser menace in this sci-fi adventure.', 'A fan-translated version of the biological-horror action title.', 'This localization allows players to understand the mission objectives and the Increaser growth mechanics. The game is praised for its atmosphere, boss designs, and the urgency created by the evolving enemy threat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bionic Commando (Europe)', 'Hack', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action platformer with a grappling hook.', 'Infiltrate the Imperial army''s base to stop the Albatross project.', 'A classic action game that replaces jumping with a bionic arm.', 'Players control Ladd Spencer, who uses a grappling hook to swing across pits and climb platforms. This unique mechanic defines the gameplay, as the player cannot jump. It is famous for its complex level design, catchy music, and iconic ending.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bionic Commando (USA)', '1988', NaN, 'Capcom', '1', NaN, 'Side-scrolling action platformer with grappling hook.', 'Rescue Super Joe and stop the Badds'' secret Albatross weapon.', 'The North American version of the iconic swinging action game.', 'Known for its lack of a jump button, players must master the bionic arm to swing and climb. This version famously changed the original Japanese Nazi references to Badds and Generalissimo Kill, though it retained the iconic and graphic ending sequence.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bionic Commando (USA) [Hack by Chris Covell v0.99] (Uncensored Edition)', '1988', NaN, 'Capcom', '1', NaN, 'Side-scrolling action platformer (Uncensored Hack).', 'Defeat the Neo-Nazis and stop the resurrection of Adolf Hitler.', 'A fan-restoration that brings back the original Japanese content.', 'This hack reverts the localization changes made by Nintendo of America. It restores Swastikas, the Imperial Army name, and the original identity of the final boss, allowing players to experience the game as it was originally intended in Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bird Week (Japan)', 'Hack', NaN, 'Capcom', '1', NaN, 'Single-screen nature simulation/action.', 'Feed your chicks enough butterflies to help them grow and migrate.', 'A simple and unique game where you play as a mother bird.', 'Players control a bird flying through a forest, catching insects to feed hungry chicks in a nest. You must avoid predators like hawks and cats. The game is divided into seasons, with different environmental challenges in each level.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Black Bass 2, The (Japan)', '1986', NaN, 'Taito', '1', NaN, 'Fishing simulation with career and tournament modes.', 'Catch the biggest bass in various lakes to win the tournament.', 'The second entry in the popular Famicom fishing series.', 'This sequel improved the graphics and added more depth to the lure selection and fish behavior. It features a top-down view for navigating the lake and a side-view underwater perspective once a fish is hooked, requiring careful line tension management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Black Bass USA, The (USA)', '1993', NaN, 'Hot-B', '1', NaN, 'Fishing simulation with RPG elements.', 'Rise through the ranks of the professional bass fishing circuit.', 'The localized North American version of the Black Bass series.', 'Players choose their equipment, time of day, and location on the lake. It is praised for its realistic (for the time) simulation of bass behavior, where factors like water temperature and lure type determine your success in catching The Big One.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Black Bass, The (Japan)', '1989', NaN, 'Hot-B', '1', NaN, 'Fishing simulation with tournament play.', 'Win the local fishing tournament by catching the heaviest total weight.', 'The first official Black Bass title for the Famicom.', 'This game established the series'' formula: selecting a spot on a map, choosing a lure, and engaging in a battle with the fish once it bites. It was one of the first games to make fishing a competitive and strategic experience on consoles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blackjack (USA) (Unl)', '1987', NaN, 'Hot-B', '1', NaN, 'Casino card game simulation (Unlicensed).', 'Beat the dealer''s hand without exceeding 21 to win credits.', 'An unlicensed Blackjack game developed by SEI.', 'A straightforward implementation of the classic casino game. Players can split, double down, and take insurance. Like many unlicensed titles, it features a simple interface and was often part of gambling-themed multicarts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blades of Steel (Europe)', '1990', NaN, 'Unlicensed', '1', NaN, 'Arcade-style ice hockey with fighting mechanics.', 'Outscore the opposing team to win the tournament.', 'The European release of Konami''s classic hockey title.', 'Known for its fast gameplay and the ability to engage in fistfights between players. If a fight occurs, the loser is sent to the penalty box. It features a distinctive voice-synthesized Blades of Steel! at the title screen and a fun mini-game during intermission.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blades of Steel (USA)', '1988', NaN, 'Konami', '1-2', NaN, 'Arcade-style ice hockey with fighting mechanics.', 'Lead your team to victory in the Cup tournament.', 'The North American version of Konami''s hit hockey game.', 'Identical to the international versions, it remains one of the most beloved sports games on the NES. It features smooth scrolling, responsive controls, and the iconic face-off mechanic, offering a perfect blend of sports simulation and arcade fun.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blaster Master (Europe)', '1988', NaN, 'Konami', '1-2', NaN, 'Side-scrolling and top-down action-adventure hybrid.', 'Explore the underworld and destroy the Plutonium Boss.', 'A technical masterpiece featuring a jumping combat tank.', 'Players control Jason and his tank, SOPHIA, in side-scrolling stages. Jason can exit the tank to explore interiors in a top-down perspective. This version is known for its incredible music and the grenade glitch that helped players defeat difficult bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blaster Master (USA)', '1988', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling and top-down action-adventure hybrid.', 'Rescue your pet frog Fred and defeat the radioactive mutants.', 'The North American release of the iconic tank-adventure game.', 'As Jason, you pilot the SOPHIA III tank through 8 massive, interconnected areas. The game seamlessly transitions from vehicle platforming to top-down dungeon exploration when Jason exits the tank. It is legendary for its tight controls, epic boss fights, and incredible soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blodia Land - Puzzle Quest (Japan)', '1988', NaN, 'Sunsoft', '1', NaN, 'Grid-based sliding tile puzzle.', 'Slide tiles to create a path for a ball or character to reach the exit.', 'A puzzle game based on the Blodia (Timegate) mechanics.', 'Similar to games like Pipe Dream, you must quickly rearrange floor tiles to guide a moving object. It features various themed worlds and increasing speed, requiring fast thinking and spatial awareness to avoid crashing into dead ends.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bloody Warriors - Shan-Go no Gyakushuu (Japan)', '1990', NaN, 'Namco', '1', NaN, 'Turn-based RPG with an oriental fantasy theme.', 'Defeat the evil god Shan-Go and his army of warriors.', 'A post-apocalyptic RPG set in a world inspired by Asian mythology.', 'Published by Toei Animation, this game features a traditional party-based structure. It stands out for its dark, gritty atmosphere and a combat system that includes a variety of special techniques and spells, reflecting the classic hardcore Famicom RPG era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bloop''s Adventure', '1990', NaN, 'Culture Brain', '1', NaN, 'Side-scrolling action platformer.', 'Navigate through levels to reach the end of the quest.', 'A simple, unlicensed platformer featuring a blue blob.', 'Players control Bloop, a small blue creature that must jump over obstacles and avoid enemies. Like many unlicensed titles, it has basic physics and repetitive level design, often appearing on budget multi-carts in the late 90s.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blue Marlin, The (Japan)', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Deep-sea sport fishing simulation.', 'Catch record-breaking Marlin and win the tournament.', 'A realistic sea-fishing sim that focuses on large ocean prey.', 'This game focuses on Big Game fishing. Players must manage boat movement, fuel, and line tension while battling massive fish. It features an overhead view for tracking and a specialized battle view when a Marlin is on the hook.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blue Marlin, The (USA)', '1990', NaN, 'Taito', '1', NaN, 'Deep-sea sport fishing simulation.', 'Win the Florida fishing tournament by catching the heaviest Marlin.', 'The North American release of the realistic sea-fishing title.', 'Identical to the Japanese version, it offers a surprisingly deep simulation. You can select different lures and locations based on weather conditions. The fight with the fish is a strategic tug-of-war that can last several minutes of game time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blue Shadow (Europe)', '1985', NaN, 'Data East', '1', NaN, 'Side-scrolling action-platformer.', 'Infiltrate a futuristic New York to defeat the Emperor Garuda.', 'The European version of the acclaimed Shadow of the Ninja.', 'Often called the cousin of Ninja Gaiden, this game features 2-player simultaneous co-op. Players use katanas, kusarigamas, and bombs. It is praised for its exceptional graphics, fluid animation, and some of the best music on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blues Brothers, The (Europe)', '1985', NaN, 'Data East', '1', NaN, 'Side-scrolling platformer based on the movie.', 'Collect the missing records to perform the big show.', 'A musical adventure starring Jake and Elwood Blues.', 'Players can choose either brother to navigate stages like a prison, a mall, and a construction site. The gameplay focuses on picking up and throwing crates at enemies. It is known for its faithful 8-bit renditions of blues and soul classics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Blues Brothers, The (USA)', '1991', NaN, 'Hect', '1', NaN, 'Side-scrolling platformer based on the movie.', 'Dodge the police and reach the concert hall in time.', 'The North American release of the Blues Brothers platformer.', 'This version maintains the same levels and challenge as the European release. It captures the frantic energy of the film, requiring precise jumping and item management while the iconic Peter Gunn Theme or Everybody Needs Somebody plays in the background.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bo Jackson Baseball (USA)', 'Prototype', NaN, 'Unlicensed', '1', NaN, 'Baseball simulation with a multi-sport star.', 'Win the championship using Bo Jackson''s athletic prowess.', 'A sports sim endorsed by the legendary MLB and NFL star.', 'The game features Bo Jackson as the main star and allows for exhibition or season play. It is notable for its digitized voice of Bo Jackson and a more arcade-style approach to pitching and batting compared to the more serious Bases Loaded series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bokosuka Wars (Japan)', '1989', NaN, 'Tad Corporation', '1', NaN, 'Real-time strategy and action hybrid.', 'Lead your army across the screen to defeat the evil King Kingder.', 'A unique and early tactical game where you move an entire army.', 'Players start with only a King and must touch tiles to recruit soldiers. All characters move simultaneously when you press a direction. It is considered one of the earliest examples of the strategy-RPG genre, known for its iconic Bokosuka chant music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bomber King (Japan)', '1990', NaN, 'Capcom', '1', NaN, 'Action-adventure with bomb mechanics.', 'Navigate through enemy-filled stages to destroy the final boss.', 'A spin-off of the Bomberman series with more adventure elements.', 'Known in the West as RoboWarrior, players control a robot that uses bombs to clear paths and fight. Unlike Bomberman, it features a life bar, various weapon upgrades, and an energy meter that constantly depletes, requiring the player to find fuel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bomber Remilia', 'Hack', NaN, 'Capcom', '1', NaN, 'Single-screen action (Touhou Project Fan-game).', 'Use bombs to clear enemies and stages in a Bomberman-style world.', 'A modern homebrew hack featuring characters from the Touhou Project.', 'This is a fan-made modification (hack) of the original Bomberman. It replaces the classic protagonist with Remilia Scarlet from the Touhou series, featuring new sprites and potentially modified music while keeping the classic place bombs and run gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bomberman (Japan)', '1992', NaN, 'Rebellion Developments', '1', NaN, 'Grid-based action puzzle.', 'Destroy all enemies in each stage and find the exit hidden under a brick.', 'The Famicom original that launched the legendary explosive franchise.', 'Players control a robot trying to become human. By placing bombs to destroy walls and enemies, you find power-ups like Fire (range) and Bombs (quantity). It is a simple but incredibly addictive game that defined the maze-action genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bomberman (USA)', '1987', NaN, 'Epyx', '1-2', NaN, 'Grid-based action puzzle.', 'Complete 50 levels of explosive action to become human.', 'The North American release of the iconic Bomberman.', 'Identical to the Japanese version, it tells the story of a bomb-making robot who escapes a factory. It is praised for its perfect difficulty curve and strategic depth, where one misplaced bomb can lead to the player''s own demise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bomberman II (Japan)', '1987', NaN, 'Epyx', '1-2', NaN, 'Grid-based action with multiplayer focus.', 'Escape from prison by clearing stages with bombs.', 'The Japanese sequel known as Bomberman II.', 'This version introduced a much-needed 3-player battle mode (using a multitap) and improved the single-player campaign with more diverse environments and enemy types. It set the standard for the multiplayer chaos the series is now famous for.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bomberman II (USA)', 'Prototype', NaN, 'Capcom', '1', NaN, 'Grid-based action with multiplayer focus.', 'Clear your name by escaping prison and defeating the fake Bomberman.', 'The North American release of the second Bomberman title.', 'Featuring a story mode where Bomberman is framed for a crime, this game is highly sought after by collectors. It significantly improved the graphics over the original and refined the power-up system, making the gameplay faster and more fluid.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bomberman, Starring Pretty Bomber', 'Prototype', NaN, 'Capcom', '1', NaN, 'Grid-based action (Romhack/Mod).', 'Defeat enemies using the female Pretty Bomber character.', 'A cosmetic hack of Bomberman featuring the series'' female rival.', 'This modification replaces the standard white Bomberman with Pretty Bomber (Lady Bomber). The core mechanics of placing bombs and collecting power-ups remain the same, providing a fun visual alternative for fans of the character.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bonk''s Adventure (USA)', '1991', NaN, 'Caltron', '1', NaN, 'Side-scrolling action platformer.', 'Use your head to bash enemies and rescue Princess Za.', 'A rare NES port of the famous TurboGrafx-16 mascot game.', 'Players control Bonk, a caveman who attacks by headbutting or diving head-first. By eating meat, Bonk can transform into more powerful versions. Despite the hardware downgrade, this version captures the charm and creative level design of the original.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Booby Kids (Japan)', '1992', NaN, 'Capcom', '1', NaN, 'Top-down action-puzzle with digging mechanics.', 'Collect all items in the stage and reach the exit before time runs out.', 'A prehistoric puzzle game where you trap enemies in holes.', 'Players control a Booby Kid who can dig holes to trap pursuing enemies, similar to Lode Runner or Heiankyo Alien. You must navigate maze-like levels, collect treasures, and use strategic digging to survive various prehistoric hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Boogerman (Unl)', '1991', NaN, 'Data East', '1', NaN, 'Side-scrolling platformer (Unlicensed).', 'Defeat enemies using gross-out powers to reach the end of the stage.', 'An 8-bit bootleg port of the 16-bit gross-out hero game.', 'Developed by Hummer Team, this is an unlicensed adaptation of the SEGA/SNES game. Players use burps and flickers to fight enemies. Despite being a pirate game, it features surprisingly decent animations and music for the NES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Boogerman II (Unl)', '1991', NaN, 'Data East', '1', NaN, 'Side-scrolling platformer (Unlicensed).', 'Navigate new gross levels and defeat the Boogerman rivals.', 'An unlicensed sequel/hack of the first 8-bit Boogerman.', 'Often based on the same engine as the first unlicensed port, this version features modified level layouts and sometimes different enemy colors. It remains a curiosity of the pirate game market, focusing on the same scatological humor as the original.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Boulder Dash (Europe)', '1988', NaN, 'Nichibutsu', '1', NaN, 'Action-puzzle with falling physics.', 'Collect a set number of diamonds and reach the exit before time runs out.', 'The European version of the classic dig and collect puzzle game.', 'As Rockford, players must dig through dirt while avoiding falling rocks and enemies. The game is famous for its emergent physics: one wrong move can cause a rock-slide that traps the player or crushes vital diamonds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Boulder Dash (Japan)', '1991', NaN, 'Mindscape', '1', NaN, 'Action-puzzle with falling physics.', 'Navigate caves and avoid being crushed by falling boulders.', 'The Japanese Famicom version of the iconic puzzle series.', 'Published by Data East in Japan, this version features the same addictive logic-based gameplay. Players must solve increasingly complex spatial puzzles, managing the movement of boulders to clear paths or eliminate underground creatures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Boulder Dash (USA)', '1991', NaN, 'Mindscape', '1', NaN, 'Action-puzzle with falling physics.', 'Master the caves and collect enough jewels to open the escape portal.', 'The North American release of the legendary Boulder Dash.', 'This version established Rockford as a household name for puzzle fans. It features dozens of levels (caves) that require a perfect mix of quick reflexes and long-term planning to avoid getting stuck in a dead-end.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Boulder Dash (USA) [Hack by Dragon Eye Studios v0.80] (~Boulder Dash Greed)', '1992', NaN, 'Mitsui & Co.', '1', NaN, 'Action-puzzle (Romhack).', 'Collect diamonds in high-difficulty custom caves.', 'A fan-made hack titled Boulder Dash Greed with new levels.', 'This modification replaces the original 1990 levels with much more punishing and complex designs. It is intended for veterans of the series who have mastered the physics of falling rocks and want a fresh, logical challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bowsette 2 - Red', '1988', NaN, 'Nichibutsu', '1', NaN, 'Side-scrolling platformer (Romhack/Mod).', 'Navigate levels as a fan-made Bowsette character.', 'A visual mod of a classic platformer (usually SMB2) featuring Bowsette.', 'Part of a series of Bowsette themed hacks, the Red version typically features a specific color palette and sprite set. The gameplay follows the standard platforming rules of the base game it modifies, but with the internet-famous character.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bowsette 2 - Yellow', '1988', NaN, 'Nichibutsu', '1', NaN, 'Side-scrolling platformer (Romhack/Mod).', 'Complete stages with the Yellow-themed Bowsette sprite.', 'Another color variant of the Bowsette character modification.', 'Similar to the Red version, this is a cosmetic hack. It serves as a visual alternative for fans of the character, often featuring minor tweaks to the difficulty or item placements depending on the specific patch version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Boy and His Blob, A - Trouble on Blobolonia (Europe) (Rev A)', '1989', NaN, 'Rare', '1', NaN, 'Puzzle-platformer with a companion AI.', 'Feed your blob jellybeans to transform him and solve puzzles.', 'An innovative adventure by David Crane (creator of Pitfall!).', 'Players control a boy who is accompanied by a shape-shifting blob. By feeding him different flavors of jellybeans, the blob turns into a ladder, a bridge, a hole, etc. The European Rev A version includes minor technical bug fixes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Boy and His Blob, A - Trouble on Blobolonia (USA)', '1989', NaN, 'Rare', '1', NaN, 'Puzzle-platformer with a companion AI.', 'Travel to the planet Blobolonia to defeat the evil Vitamin King.', 'The North American release of the unique blob adventure.', 'A cult classic known for its experimental gameplay. There is no jump button; instead, you must strategically use the blob''s transformations to navigate the environment. It requires a lot of trial-and-error and creative thinking to progress.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bram Stoker''s Dracula (Europe)', '1988', NaN, 'Tecmo', '1-2', NaN, 'Side-scrolling action platformer.', 'Defeat the vampire Lucy, the brides, and eventually Count Dracula.', 'A movie-licensed action game with a dark, gothic atmosphere.', 'Based on the 1992 film, players control Jonathan Harker. The game features a day/night cycle that affects difficulty. You fight through forests and castles using a knife and various secondary weapons. It is noted for its impressive graphics and somber music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bram Stoker''s Dracula (USA)', 'Hack', NaN, 'Tecmo', '1-2', NaN, 'Side-scrolling action platformer.', 'Pursue the Count across Europe to save Mina and end the curse.', 'The North American release of the Bram Stoker movie tie-in.', 'Identical to the European version, it offers a challenging platforming experience. Each level is divided into daytime (easier) and nighttime (harder) sections. The boss fights are a highlight, featuring various forms of Dracula’s minions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Break Time - The National Pool Tour (USA)', '1990', NaN, 'Tecmo', '1-2', NaN, 'Top-down pool/billiards simulation.', 'Win the national tour by defeating professional pool players.', 'A realistic pool game with physics-based gameplay.', 'Players can compete in several modes, including 8-ball, 9-ball, and rotation. It features a power meter and the ability to add English (spin) to the ball. The game includes a tour mode where you travel to different cities to compete for prize money.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'BreakThru (USA)', 'Hack', NaN, 'Tecmo', '1-2', NaN, 'Side-scrolling vehicular combat/shooter.', 'Drive through enemy territory to rescue a captured fighter jet.', 'A fast-paced action game where you control an armored buggy.', 'Developed by Data East, your vehicle can jump over obstacles and shoot in multiple directions. The game is known for its speed and the Breakthru mechanic where you must literally crash through enemy lines to reach the boss at the end of each stage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Brush Roller (Asia) (Unl)', '1990', NaN, 'Namco', '1', NaN, 'Top-down maze/painting puzzle.', 'Paint all the paths in the maze while avoiding pursuing monsters.', 'An unlicensed clone of the arcade classic Make Trax (Crush Roller).', 'Players control a brush that leaves a trail of color. You must paint the entire floor of the maze to advance. It features rollers that can be used to crush enemies, and like many unlicensed Asian titles, it has simple graphics but addictive arcade-style gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bubble Bath Babes (USA) (Unl)', '1989', NaN, 'Sofel', '1', NaN, 'Single-screen puzzle (Adult/Unlicensed).', 'Clear the bubbles to reveal a hidden image of a woman.', 'A rare and controversial adult-themed puzzle game.', 'Published by Panesian, this is a Bubble Buster style game. While the gameplay is a standard tile-matching puzzle, it is infamous for its adult content shown between levels. It is one of the most sought-after and expensive unlicensed cartridges for collectors.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bubble Bobble (Europe)', '1991', NaN, 'Sofel', '1', NaN, 'Single-screen action platformer.', 'Trap all enemies in bubbles and pop them to clear the stage.', 'The European release of Taito''s legendary arcade masterpiece.', 'Players control Bub or Bob (dragons). The game is famous for its 100 levels, cooperative 2-player mode, and catchy music. To get the True Ending, players must complete the game in 2-player mode, emphasizing teamwork and strategy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bubble Bobble (USA)', '1989', NaN, 'Taito', '1', NaN, 'Single-screen action platformer.', 'Defeat Baron Von Blubba and rescue the dragons'' girlfriends.', 'The North American release of the classic Bubble Bobble.', 'This version brought the perfect arcade loop to Western homes. It features a deep scoring system involving fruit, items, and secret EXTEND bubbles. It remains one of the most beloved and replayable titles in the entire NES library.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bubble Bobble (USA) [Hack by Dragon Eye Studios v1.0] (~Bubble Bobble Madness)', '1989', NaN, 'Taito', '1', NaN, 'Single-screen action platformer (Romhack).', 'Survive extreme new levels in Bubble Bobble Madness.', 'A high-difficulty modification of the original game.', 'Created by Dragon Eye Studios, this hack replaces all 100 original levels with brand-new, much more difficult layouts. It is designed for experts who can navigate tight spaces and manage enemy patterns with perfect precision.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bubble Bobble 2 (Japan)', '1986', NaN, 'Taito', '1', NaN, 'Single-screen action platformer.', 'Journey through new worlds to save the village from evil.', 'The rare and highly polished sequel to Bubble Bobble.', 'Released late in the Famicom''s life, this sequel features vastly improved graphics and new abilities, such as the power to float by holding the jump button. It is a technical showcase for the system and one of the most expensive original cartridges today.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bubble Bobble Part 2 (USA)', '1990', NaN, 'American Sammy', '1', NaN, 'Single-screen action platformer.', 'Rescue your friend and defeat the evil skull monster.', 'The extremely rare and polished North American sequel.', 'Released late in the NES lifecycle, this sequel features much larger sprites and more detailed backgrounds than the original. It introduces new mechanics like the ability to float and updated boss patterns. It is one of the most valuable licensed titles for collectors today.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bubble Bobble Part 2 (USA) [Hack by Dragon Eye Studios v0.15] (~Bubble Bobble Madness 2)', '1989', NaN, 'Namco', '1', NaN, 'Single-screen action platformer (Romhack).', 'Challenge yourself with redesigned, high-difficulty stages.', 'A technical hack that overhauls the levels of Bubble Bobble Part 2.', 'Following the Madness series by Dragon Eye Studios, this modification replaces the original stages with complex, trap-filled layouts. It is designed for players who have mastered the physics of the second game and seek a professional-level challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bucky O''Hare (Europe)', '1989', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer.', 'Rescue your crew members and stop the Toad Empire.', 'A high-quality Konami action game based on the cult cartoon.', 'Players travel to different planets (Green, Red, Blue, etc.) to save crewmates like Blinky and Jenny. Once rescued, you can switch between characters at any time, each with unique abilities required to overcome specific platforming obstacles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bucky O''Hare (Japan)', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling action platformer.', 'Save the galaxy from the Toad Air Marshall.', 'The Japanese Famicom version of the Bucky O''Hare adventure.', 'Identical in its excellent gameplay to the Western versions, this release showcases Konami''s VRC chip capabilities with fluid animations and a pulse-pounding soundtrack that is often cited as some of the best music on the 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bucky O''Hare (USA)', '1987', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Liberate the planets from Toad control and rescue the Righteous Indignation crew.', 'The North American release of the acclaimed Bucky O''Hare.', 'Regarded as a hidden gem, it combines Mega Man-style level selection with tight platforming and character-swapping mechanics. It is notoriously difficult but highly rewarding, featuring some of the most creative level designs on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Buggy Popper (Japan)', '1987', NaN, 'Konami', '1', NaN, 'Top-down/Behind-the-car racing and combat.', 'Reach the goal while jumping over obstacles and destroying enemies.', 'An arcade-style racer known in the West as Bump ''n'' Jump.', 'Players drive a car that can jump into the air to land on top of enemies or cross large gaps in the road. It’s a fast-paced game where you must manage your speed and timing to survive the chaotic highway traffic and water hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bugs Bunny Birthday Blowout, The (USA)', '1987', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Reach Bugs Bunny''s 50th birthday party while dodging classic rivals.', 'A colorful platformer celebrating the iconic Looney Tunes character.', 'Known in Japan as Happy Birthday Bugs, players use a mallet to defeat enemies like Elmer Fudd and Yosemite Sam. The game features various bonus stages and a lucky draw system to earn extra lives and power-ups at the end of each level.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bugs Bunny Blowout, The (Europe)', 'Hack', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Navigate through Looney Tunes-themed levels to reach the celebration.', 'The European release of the Bugs Bunny birthday adventure.', 'Aside from the slight title change, the gameplay remains a standard but charming platformer. It focuses on collecting carrots and avoiding traps, with a lighthearted tone and music that fits the whimsical nature of the cartoons.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bugs Bunny Crazy Castle, The (USA)', 'Hack', NaN, 'Konami', '1', NaN, 'Non-scrolling puzzle platformer.', 'Collect all the carrots in each level to open the exit door.', 'A strategy-focused game set in a multi-level castle.', 'Unlike other Bugs Bunny games, there is no jumping. Players must use stairs, ladders, and pipes to outmaneuver enemies. It requires careful planning to use items like boxing gloves and weights to trap rivals while clearing the stage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bugs Bunny Crazy Castle, The (USA) [Hack by Frank Maggiore v1.2] (~2nd Ultimate Bugs Bunny Crazy Castle, The)', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Non-scrolling puzzle platformer (Romhack).', 'Solve even more complex puzzles in this custom level pack.', 'A fan-made expansion with brand-new, challenging castle levels.', 'This modification takes the core mechanics of Crazy Castle and introduces much more intricate level designs. It tests the player''s ability to manipulate enemy AI and manage limited resources across dozens of new rooms.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bugs Bunny Crazy Castle, The (USA) [Hack by Frank Maggiore v1.2] (~Ultimate Bugs Bunny Crazy Castle, The)', '1988', NaN, 'Konami', '1', NaN, NULL, NULL, NULL, NULL, NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bugs Bunny Fun House (USA) (Beta)', '1988', NaN, 'Konami', '1', NaN, 'Non-scrolling puzzle platformer (Romhack)', 'Collect every carrot in the castle while outsmarting classic cartoon enemies.', 'A significant level overhaul of the original puzzle game.', 'This hack replaces all the original stages with much more difficult and complex designs. It requires perfect timing and expert knowledge of the enemy AI patterns to navigate through the traps and collect the items needed to clear each room.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Bump''n''Jump (USA)', 'Hack', NaN, 'Konami', '1', NaN, 'Non-scrolling puzzle platformer (Beta)', 'Navigate through various rooms to find the exit and progress.', 'An unreleased prototype version of the Bugs Bunny puzzle series.', 'This version provides a look at the game''s development before its final release. While the core gameplay of collecting items to open doors remains the same, it features slight differences in level layouts and assets compared to the retail version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Burai Fighter (Europe)', 'Hack', NaN, 'Konami', '1', NaN, 'Top-down racing and combat', 'Reach the finish line by jumping over obstacles and crashing into rivals.', 'A port of the high-speed arcade classic Buggy Popper.', 'Players drive a car that has the unique ability to jump into the air. This mechanic is used to dodge water hazards, leap over large gaps, and land on top of enemy vehicles to destroy them. It is a fast-paced game of reflexes and timing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Burai Fighter (Japan)', '1989', NaN, 'Konami', '1', NaN, 'Scrolling multi-directional shooter', 'Travel through multiple bases to eliminate the Burai super-beings.', 'A technically impressive shooter with 8-way scrolling action.', 'Developed by Taxan, the game allows players to fire in eight different directions while the screen scrolls in various ways. It features complex level designs and a variety of weapon power-ups like lasers and missiles to tackle large bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Burai Fighter (USA)', '1989', NaN, 'Rare', '1', NaN, 'Scrolling multi-directional shooter', 'Eradicate the alien threat across different planetary bases.', 'The Japanese version of the sci-fi shooter known for its difficulty.', 'This version offers the same intense shooting action as its Western counterparts. Players must manage their movement carefully as the scrolling changes direction, requiring mastery of the 8-way firing system to survive the onslaught of enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Burger Time (Japan)', '1984', NaN, 'Data East', '1', NaN, 'Scrolling multi-directional shooter', 'Destroy the Burai Empire using an array of advanced weaponry.', 'The North American release of the acclaimed multi-directional shmup.', 'It is highly regarded for its smooth scrolling and challenging gameplay. The game includes several difficulty levels, including a hidden Eagle mode that is considered one of the toughest challenges on the NES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Burger Time (USA)', '1984', NaN, 'Data East', '1', NaN, 'Single-screen action puzzle', 'Assemble all the hamburgers by walking over the ingredients.', 'The Famicom port of Data East''s legendary arcade hit.', 'As Peter Pepper the chef, you must drop buns, patties, and lettuce onto plates below. You are pursued by personified food enemies like Mr. Hot Dog and Mr. Egg, whom you can stun with limited pepper or crush with falling ingredients.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Business Wars (Japan)', '1991', NaN, 'Hect', '1', NaN, 'Single-screen action puzzle', 'Finish making every burger in the stage while avoiding enemies.', 'The North American version of the iconic arcade puzzle game.', 'This port captures the addictive cat and mouse gameplay of the original. Success depends on strategic movement to group enemies together under falling food items to earn high scores and clear the stage faster.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Buzz & Waldog (USA) (Unl) (Proto)', 'Prototype', NaN, 'Unlicensed', '1', NaN, 'Board game / Business simulation', 'Outperform rival companies to dominate the Japanese corporate market.', 'A strategy-heavy business simulation focused on economics.', 'Players compete on a board to buy properties, manage stocks, and grow their corporate empire. It features a deep menu system and requires careful financial planning to defeat the computer-controlled business rivals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cabal (USA)', '1989', NaN, 'Tad Corporation', '1', NaN, 'Side-scrolling action platformer (Unlicensed Proto)', 'Help the duo save their world from a massive alien invasion.', 'A highly polished unreleased prototype from industry veterans.', 'Created by former Konami staff, this game features exceptional animations and tight controls. It follows Buzz and his dog Waldog through vibrant levels, showcasing the quality of a retail game that unfortunately never saw a commercial release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cadillac (Japan)', '1990', NaN, 'Capcom', '1', NaN, 'Behind-the-back gallery shooter', 'Destroy all enemy soldiers and structures in each combat zone.', 'A faithful port of the intense arcade shooting-gallery game.', 'Players control a soldier who can move horizontally and dodge-roll to avoid fire while aiming a crosshair at targets. The environment is highly destructible, and clearing a stage is rewarded with the character''s signature victory dance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cadillac (Japan) [En by Gil Galad+Steve Martin v1.0]', 'Hack', NaN, 'Capcom', '1', NaN, 'Board game / Strategy with RPG elements', 'Use cards and strategy to win the tournament and advance.', 'A Famicom board game featuring card-based combat.', 'Based on a digital board game format, players move across a map and engage in events determined by card draws. It requires a balance of luck and tactical thinking to manage resources and overcome the challenges presented by the board.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Caesars Palace (USA)', '1992', NaN, 'Rebellion Developments', '1', NaN, 'Casino simulation', 'Win big at various casino games to increase your bankroll.', 'An officially licensed simulation of the famous Las Vegas casino.', 'Featuring games like Blackjack, Roulette, Slot Machines, and Video Poker, this title aims for a realistic gambling experience. It includes a high-stakes area for players who accumulate enough wealth, following strict casino rules and odds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'California Games (Europe)', '1987', NaN, 'Epyx', '1-2', NaN, 'Sports / Variety', 'Master various extreme sports to earn high scores and medals.', 'A multi-event sports game celebrating California subculture.', 'Players compete in events such as Skateboarding, Footbag, Surfing, Roller Skating, BMX, and Flying Disc. Each event has unique controls and physics, requiring different skills to master the quintessential West Coast athletic experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'California Games (USA)', '1987', NaN, 'Epyx', '1-2', NaN, 'Sports / Variety', 'Compete in six different California-themed summer sports.', 'The North American release of the Epyx multi-event classic.', 'Identical to the European version, it is beloved for its colorful graphics and competitive multiplayer. Players can represent different sponsors and must balance risk and reward to pull off stunts without wiping out.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'California Raisins - The Grape Escape (USA) (Proto1)', 'Prototype', NaN, 'Capcom', '1', NaN, 'Side-scrolling platformer (Proto)', 'Rescue your bandmates and retrieve the stolen musical notes.', 'An unreleased prototype featuring the famous claymation mascots.', 'This early build shows the core mechanics of the raisins'' adventure. It features a mix of platforming and shooting (using musical notes) with diverse level themes, though it contains bugs and unfinished assets typical of an early prototype.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'California Raisins - The Grape Escape (USA) (Proto2)', 'Prototype', NaN, 'Capcom', '1', NaN, 'Side-scrolling platformer (Proto)', 'Stop the villainous Maestro and save the California Raisins.', 'A more polished, near-complete version of the cancelled game.', 'This second prototype is significantly more stable and features complete levels, boss fights, and cinematic interludes. It showcases impressive character animation and a creative use of the license that was sadly never officially released.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Caltron - 6 in 1 (USA) (Unl)', '1991', NaN, 'Caltron', '1', NaN, 'Multi-game compilation (Unlicensed)', 'Play through six different titles included on a single cartridge.', 'A rare unlicensed multicart containing six original games.', 'Includes Cosmic Fighter, Adam & Eve, Magic Carpet 1001, Balloon Monster, Porter, and Bookyman. These games vary in genre from shooters to puzzles, though they are generally simpler in design than official Nintendo releases.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Capcom Barcelona ''92 (Japan)', '1992', NaN, 'Capcom', '1', NaN, 'Sports / Olympic simulation', 'Lead your athlete to victory in various Olympic events.', 'A sports title released to coincide with the 1992 Summer Olympics.', 'Known in the West as Gold Medal Challenge ''92. It features 18 different events across athletics, swimming, and gymnastics. It supports up to eight players and focuses on rhythmic button-mashing and precise timing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain America and the Avengers (Australia)', '1991', NaN, 'Data East', '1', NaN, 'Side-scrolling action platformer', 'Defeat the Red Skull and the Masters of Evil to save the world.', 'A port of the Data East arcade brawler starring Marvel heroes.', 'You can play as Captain America or Hawkeye. The game combines traditional beat ''em up combat with platforming elements and features appearances from other Avengers like Iron Man and Vision as assist characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain America and the Avengers (USA)', '1991', NaN, 'Data East', '1', NaN, 'Side-scrolling action platformer', 'Stop the Red Skull''s plan to destroy the Avengers.', 'The North American release of the Marvel superhero title.', 'This version features the same challenging levels and comic-book style presentation as the Australian release. It is known for its high difficulty and the need to collect power-ups to improve the heroes'' ranged attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Ed (Japan)', '1988', NaN, 'Nichibutsu', '1', NaN, 'Vertical scrolling shooter', 'Navigate a surreal world to destroy enemy bases.', 'A quirky and obscure Japanese shooter with an odd theme.', 'Players control a character in a flying machine. The game is known for its strange enemy designs and a point system that allows you to buy upgrades. It has a very distinct, almost psychedelic aesthetic compared to other shooters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Planet and the Planeteers (Europe)', '1991', NaN, 'Mindscape', '1', NaN, 'Side-scrolling action', 'Use the powers of the elements to stop eco-villains.', 'A platformer based on the popular environmentalist cartoon.', 'Players control the Planeteers and Captain Planet himself. The gameplay is split between levels where you use elemental rings (Earth, Fire, Wind, Water, Heart) and sections where Captain Planet must navigate hazardous industrial zones.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Planet and the Planeteers (USA)', '1991', NaN, 'Mindscape', '1', NaN, 'Side-scrolling action', 'Protect the Earth from pollution and greedy villains.', 'The North American release of the Captain Planet game.', 'This version features the same levels as the European release. It is notoriously difficult, particularly the sections where Captain Planet loses power upon touching almost any obstacle, requiring perfect navigation through narrow corridors.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Saver (Japan)', '1992', NaN, 'Mitsui & Co.', '1', NaN, 'Side-scrolling beat ''em up and action platformer.', 'Defeat a criminal organization and rescue kidnapped civilians.', 'A high-energy action platformer where a masked hero battles through urban landscapes.', 'Captain Saver is a cult classic NES action game featuring fluid combat and impressive 8-bit animations. Players take control of a powerful protagonist to thwart a criminal syndicate, blending traditional platforming with deep beat ''em up mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Silver (Japan)', '1988', NaN, 'Nichibutsu', '1', NaN, 'Side-scrolling action-adventure with sword combat.', 'Navigate islands and defeat bosses to find the legendary pirate treasure.', 'An epic pirate-themed adventure filled with platforming challenges and boss fights.', 'Step into the boots of a brave sailor in Captain Silver. This title captures the spirit of high-seas adventure, challenging players to master swordplay while avoiding traps across diverse environments, from haunted shipyards to jungle islands.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Skyhawk (Europe)', '1988', NaN, 'Nichibutsu', '1', NaN, 'Pseudo-3D scrolling shooter with aerial combat.', 'Destroy alien bases, rescue scientists, and prevent a global invasion.', 'An intense aerial combat simulator featuring impressive 3D-style landscapes and dogfights.', 'Captain Skyhawk is a technical marvel on the NES, utilizing isometric perspectives to create a sense of depth. Players must balance aggressive dogfighting with precision landing and refueling missions to stop a looming extraterrestrial threat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Skyhawk (USA)', '1989', NaN, 'Rare', '1', NaN, 'Pseudo-3D scrolling shooter with aerial combat.', 'Destroy alien bases, rescue scientists, and prevent a global invasion.', 'An intense aerial combat simulator featuring impressive 3D-style landscapes and dogfights.', 'Captain Skyhawk is a technical marvel on the NES, utilizing isometric perspectives to create a sense of depth. Players must balance aggressive dogfighting with precision landing and refueling missions to stop a looming extraterrestrial threat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Tsubasa (Japan)', '1989', NaN, 'Rare', '1', NaN, 'Cinematic sports-RPG hybrid with menu commands.', 'Lead Tsubasa Ozora and his team to win the national soccer championship.', 'A unique blend of soccer strategy and RPG progression based on the hit anime series.', 'Unlike traditional sports games, Captain Tsubasa focuses on dramatic storytelling and strategic decision-making. Players use stamina to trigger spectacular special shots, perfectly recreating the over-the-top energy of the original manga.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Tsubasa (Japan) [En by KnighTeen87 v1.5]', '1988', NaN, 'Tecmo', '1-2', NaN, 'Cinematic sports-RPG hybrid with menu commands.', 'Lead Tsubasa Ozora and his team to win the national soccer championship.', 'A unique blend of soccer strategy and RPG progression based on the hit anime series.', 'Unlike traditional sports games, Captain Tsubasa focuses on dramatic storytelling and strategic decision-making. Players use stamina to trigger spectacular special shots, perfectly recreating the over-the-top energy of the original manga.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Tsubasa Vol. II - Super Striker (Japan)', 'Hack', NaN, 'Tecmo', '1-2', NaN, 'Advanced Cinematic Soccer-RPG with tactical depth.', 'Rise through the international ranks to win the World Youth Cup.', 'The definitive 8-bit soccer RPG experience featuring iconic special moves and deep strategy.', 'Building on its predecessor, Super Striker introduces a complex storyline and refined mechanics. It is widely considered one of the best strategy-sports games on the NES, famous for its challenging difficulty and legendary special shots.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Captain Tsubasa Vol. II - Super Striker (Japan) [En by Hayabusakun v1.0]', '1990', NaN, 'Tecmo', '1-2', NaN, 'Advanced Cinematic Soccer-RPG with tactical depth.', 'Rise through the international ranks to win the World Youth Cup.', 'The definitive 8-bit soccer RPG experience featuring iconic special moves and deep strategy.', 'Building on its predecessor, Super Striker introduces a complex storyline and refined mechanics. It is widely considered one of the best strategy-sports games on the NES, famous for its challenging difficulty and legendary special shots.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Casino Derby (Japan)', 'Hack', NaN, 'Tecmo', '1-2', NaN, 'Horse racing simulation and gambling mechanics.', 'Bet on winning horses and manage your bankroll to become a gambling mogul.', 'A strategic horse racing and betting simulator with a classic casino atmosphere.', 'Casino Derby brings the excitement of the racetrack to the NES. Players must analyze horse stats, place strategic bets, and try their luck in various casino minigames to grow their fortune in this niche Japanese classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Casino Kid (USA)', '1990', NaN, 'Namco', '1', NaN, 'First-person casino exploration and card strategy.', 'Defeat the top gamblers in Lost Vegas to challenge the Evil King.', 'A high-stakes gambling adventure where you must outsmart opponents to become the champion.', 'Casino Kid combines RPG-style progression with classic gambling. Set in Lost Vegas, players must navigate the casino floor and master Blackjack and Poker to win enough money to take down the ultimate gambling boss.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Casino Kid 2 (USA)', '1989', NaN, 'Sofel', '1', NaN, 'Card game simulation with world-map travel.', 'Defeat professional gamblers across the world in Poker and Blackjack.', 'A high-stakes gambling sequel that takes the card-playing action to a global scale.', 'Casino Kid 2 expands on the original by sending the player on a world tour. To prove you are the best, you must travel to different countries and master various casino games in a quest for gambling supremacy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castelian (Europe)', '1991', NaN, 'Sofel', '1', NaN, 'Tower-climbing action platformer with puzzle elements.', 'Rotate and climb complex cylindrical towers to reach the top.', 'A unique 8-bit platformer focused on navigating rotating 3D-style towers.', 'Known for its impressive rotating tower effect, Castelian challenges players to find the correct path to the summit while avoiding enemies and obstacles in a race against the clock.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castelian (USA)', '1989', NaN, 'Taito', '1', NaN, 'Tower-climbing action platformer with puzzle elements.', 'Rotate and climb complex cylindrical towers to reach the top.', 'A unique 8-bit platformer focused on navigating rotating 3D-style towers.', 'Known for its impressive rotating tower effect, Castelian challenges players to find the correct path to the summit while avoiding enemies and obstacles in a race against the clock.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castle Excellent (Japan)', '1989', NaN, 'Taito', '1', NaN, 'Grid-based puzzle-adventure with platforming.', 'Navigate a massive 100-room castle to rescue a captured princess.', 'A challenging logic-based adventure that rewards patience and precise problem-solving.', 'Castle Excellent is a deep puzzle-platformer where every room is a brain-teaser. Players must manage different colored keys and avoid traps to navigate a labyrinthine fortress.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castle of Deceit (USA) (Unl)', '1986', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer (Unlicensed).', 'Navigate through a magical castle to destroy a dark curse.', 'A rare and challenging unlicensed platformer featuring a wizard protagonist.', 'Developed by Bunch Games, Castle of Deceit puts players in the role of a wizard. It is known for its high difficulty level and unique status as an unlicensed title in the NES library.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castle of Dragon (USA)', '1990', NaN, 'American Sammy', '1', NaN, 'Side-scrolling hack-and-slash action game.', 'Journey through enemy-filled levels to slay the final dragon.', 'A classic dark fantasy action game featuring knights and intense combat.', 'Castle of Dragon is an arcade-style action game where players fight through various stages using shields and weapons to defeat mythical creatures and reclaim their kingdom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castle Quest (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Strategy-board game hybrid with card combat.', 'Outmaneuver the opponent''s King on a map to win the war.', 'A unique blend of chess-like strategy and card battles in a fantasy setting.', 'Castle Quest combines board game movement with card battle mechanics. Players must strategically move units across the board, using special cards to gain the upper hand.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlequest (USA)', '1989', NaN, 'Namco', '1', NaN, 'Grid-based puzzle-adventure with platforming.', 'Navigate a massive 100-room castle to rescue a captured princess.', 'A challenging logic-based adventure that rewards patience and precise problem-solving.', 'This is the Western release of Castle Excellent, featuring the same deep puzzle-platforming mechanics where players must collect keys to navigate a deadly fortress.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania - Sonia Belmont Edition', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Action platformer with whip-based combat.', 'Traverse Dracula''s castle to defeat the Lord of Darkness.', 'A gothic horror platformer featuring the legendary vampire-hunting Belmont clan.', 'This edition focuses on Sonia Belmont''s journey through Dracula''s lair. Players must master whip combat and use sub-weapons to survive hordes of undead and classic horror bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania (Europe)', '1987', NaN, 'Konami', '1', NaN, 'Action platformer with whip-based combat.', 'Traverse Dracula''s castle to defeat the Lord of Darkness.', 'A gothic horror platformer featuring the legendary vampire-hunting Belmont clan.', 'The definitive 8-bit horror experience, Castlevania puts players in control of Simon Belmont. It is renowned for its challenging gameplay, iconic soundtrack, and dark atmosphere.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania (USA)', '1987', NaN, 'Konami', '1', NaN, 'Action platformer with whip-based combat.', 'Traverse Dracula''s castle to defeat the Lord of Darkness.', 'A gothic horror platformer featuring the legendary vampire-hunting Belmont clan.', 'The definitive 8-bit horror experience, Castlevania puts players in control of Simon Belmont. It is renowned for its challenging gameplay, iconic soundtrack, and dark atmosphere.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania (USA) (Rev A)', '1987', NaN, 'Konami', '1', NaN, 'Action platformer with whip-based combat.', 'Traverse Dracula''s castle to defeat the Lord of Darkness.', 'A gothic horror platformer featuring the legendary vampire-hunting Belmont clan.', 'The revised version of the original NES classic, offering the same intense action and platforming as Simon Belmont battles through Dracula''s demonic fortress.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania (USA) (Rev A) [Hack by Dragonsbrethren v2.0] (~Castlevania Retold)', 'Hack', NaN, 'Konami', '1', NaN, 'Enhanced action platformer with redesigned levels.', 'Experience a reimagined version of Simon''s journey through the castle.', 'A creative overhaul of the original Castlevania with new challenges and layouts.', 'Castlevania Retold is a comprehensive hack that refreshes the classic experience by modifying level designs and difficulty, providing a new challenge for veteran players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania (USA) (Rev A) [Hack by Redrum v1.0] (~Castlevania - Blood Moon)', 'Hack', NaN, 'Konami', '1', NaN, 'Action platformer with new graphics and levels.', 'Explore a completely new quest set within the Castlevania universe.', 'A total conversion hack featuring new environments, enemies, and a fresh story.', 'Blood Moon transforms the original game into a brand-new adventure, featuring a red-tinted aesthetic, redesigned stages, and a higher difficulty curve for hardcore fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania Death Counter', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Action platformer with a built-in death tracker.', 'Complete the original game while monitoring every life lost.', 'The classic Castlevania experience with an added HUD element to track deaths.', 'This version provides the standard Castlevania gameplay but adds a Death Counter on screen, making it popular for speedrunners and no-death challenge attempts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania II - Simon''s Quest (Europe)', '1988', NaN, 'Konami', '1', NaN, 'Action-RPG with exploration and day/night cycles.', 'Collect Dracula’s body parts to lift a curse and defeat the Count.', 'An ambitious adventure sequel blending platforming with RPG exploration.', 'Simon''s Quest introduces a non-linear world where players must talk to villagers, buy equipment, and solve cryptic puzzles to progress through the Transylvanian countryside.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania II - Simon''s Quest (USA)', '1988', NaN, 'Konami', '1', NaN, 'Action-RPG with exploration and day/night cycles.', 'Collect Dracula’s body parts to lift a curse and defeat the Count.', 'An ambitious adventure sequel blending platforming with RPG exploration.', 'Simon''s Quest introduces a non-linear world where players must talk to villagers, buy equipment, and solve cryptic puzzles to progress through the Transylvanian countryside.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania II - Simon''s Redaction', 'Hack', NaN, 'Konami', '1', NaN, 'Refined Action-RPG with improved dialogue.', 'Collect Dracula’s body parts while enjoying a more logical game flow.', 'An optimized version of Simon''s Quest with better hints and faster transitions.', 'This Redaction version fixes many of the original game''s flaws, such as the slow text boxes and confusing hints, making the RPG elements much more enjoyable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania II English Re-translation (+Map)', 'Hack', NaN, 'Konami', '1', NaN, 'Action-RPG with accurate text and map support.', 'Lift the curse of Dracula with the help of a clearer, more accurate script.', 'A fan-translation fix that clarifies the game''s famous cryptic puzzles.', 'This version replaces the confusing original translation with a faithful script and often includes an in-game map, greatly improving the navigation of Transylvania.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania III - Dracula''s Curse (Europe)', '1989', NaN, 'Konami', '1', NaN, 'Multi-path action platformer with swappable heroes.', 'Reach the top of Dracula’s castle with the help of legendary allies.', 'An epic 8-bit masterpiece featuring branching paths and multiple characters.', 'Dracula''s Curse is a pinnacle of NES gaming, allowing Trevor Belmont to team up with Alucard, Sypha, or Grant, offering incredible replayability through different routes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania III - Dracula''s Curse (USA)', '1990', NaN, 'Konami', '1', NaN, 'Multi-path action platformer with swappable heroes.', 'Reach the top of Dracula’s castle with the help of legendary allies.', 'An epic 8-bit masterpiece featuring branching paths and multiple characters.', 'Dracula''s Curse is a pinnacle of NES gaming, allowing Trevor Belmont to team up with Alucard, Sypha, or Grant, offering incredible replayability through different routes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania III - Dracula''s Curse (USA) [Graphic Hack by Dragonsbrethren v1.0] (Uncensored Edition)', 'Hack', NaN, 'Konami', '1', NaN, 'Multi-path action platformer with restored graphics.', 'Experience the dark gothic adventure with its original, intended visuals.', 'The North American game with restored religious icons and adult themes.', 'This Uncensored edition restores the crosses and architectural details that were removed in the original US release to meet strict censorship guidelines.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania III - Dracula''s Curse (USA) [Hack by Dragonsbrethren v1.0] (All Bug Fixes)', 'Hack', NaN, 'Konami', '1', NaN, 'Optimized multi-path action platformer.', 'Complete the quest with improved performance and no technical glitches.', 'The classic Dracula''s Curse experience with all original programming bugs fixed.', 'This version focuses on stability, correcting sprites and gameplay bugs that were present in the 1990 release, providing the smoothest possible experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Castlevania III - Sawako''s Curse', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Action platformer with character swaps.', 'Complete the difficult journey with a unique character modification.', 'A creative mod of Castlevania III featuring aesthetic and character changes.', 'This hack modifies the classic adventure to feature new character sprites and minor gameplay adjustments, offering a fresh visual take on the Belmont legacy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cat Ninden Teyandee (Japan)', '1991', NaN, 'Konami', '1', NaN, 'Fast-paced action platformer with character swapping.', 'Protect Little Tokyo from the evil Emperor Dragon by switching between cats.', 'A colorful action game based on the Samurai Pizza Cats anime series.', 'Known for its high quality, this game allows players to swap between different cat heroes, each with unique abilities used to navigate stages and fight bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cat Ninden Teyandee (Japan) [En by D v0.45] (~Samurai Pizza Cats) (Incomplete)', 'Hack', NaN, 'Konami', '1', NaN, 'Fast-paced action platformer with character swapping.', 'Protect Little Tokyo from the evil Emperor Dragon by switching between cats.', 'The English-translated version of the hit Samurai Pizza Cats action game.', 'This version translates the humorous dialogue and story of the Japanese original, allowing fans to fully enjoy the antics of the Pizza Cats on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Caveman Games (USA)', '1991', NaN, 'Data East', '1-2', NaN, 'Sports-themed mini-game collection.', 'Compete in prehistoric events like Dino-racing and Fire-making to win.', 'A wacky and humorous take on the Olympics set in the Stone Age.', 'Caveman Games features several competitive events for 1-4 players, including Clubbing and Mate-tossing, all rendered with funny 8-bit animations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chack ''n Pop (Japan)', '1985', NaN, 'Taito', '1', NaN, 'Single-screen arcade platform-puzzler.', 'Rescue hearts from cages and escape before the bombs explode.', 'A classic Taito arcade port featuring the precursor to the Bubble Bobble style.', 'Players control Chack, a small yellow creature, who must use bombs to defeat enemies and navigate platforms in this early, challenging arcade puzzle game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Challenge of the Dragon (Asia) (Unl) (Sachen) (NES)', '1989', NaN, 'Sachen', '1', NaN, 'Side-scrolling beat ''em up (Unlicensed).', 'Fight through waves of martial artists to defeat the grand master.', 'A rare martial arts brawler developed by the prolific developer Sachen.', 'This unlicensed title features traditional beat ''em up mechanics where the player uses kicks and punches to clear stages in a quest for martial arts glory.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Challenge of the Dragon (USA) (Unl) (Color Dreams)', '1989', NaN, 'Color Dreams', '1', NaN, 'Side-scrolling action platformer (Unlicensed).', 'Use magic and combat skills to defeat the evil dragon and save the land.', 'A fantasy action game known for its high difficulty and unlicensed origins.', 'Published by Color Dreams, this game puts players in the role of a hero fighting through a fantasy world filled with monsters, traps, and difficult boss encounters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Challenger (Japan)', '1985', NaN, 'Hudson Soft', '1', NaN, 'Multi-genre action game with diverse stages.', 'Rescue a princess by navigating train scenes and top-down exploration.', 'A unique 8-bit adventure that mixes different gameplay styles and perspectives.', 'Challenger is famous for its first level set on a moving train, followed by a top-down search for the princess, blending action, platforming, and exploration.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Championship Bowling (Japan)', '1989', NaN, 'Athena', '1', NaN, 'Sports simulation with physics-based mechanics.', 'Achieve the highest score possible by knocking down pins across ten frames.', 'A realistic 8-bit bowling simulation with multiple oil patterns and ball choices.', 'Championship Bowling offers a technical take on the sport, allowing players to adjust their stance, aim, and power to master the lanes in both tournament and practice modes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Championship Bowling (USA)', '1989', NaN, 'Athena', '1', NaN, 'Sports simulation with physics-based mechanics.', 'Achieve the highest score possible by knocking down pins across ten frames.', 'A realistic 8-bit bowling simulation with multiple oil patterns and ball choices.', 'Championship Bowling offers a technical take on the sport, allowing players to adjust their stance, aim, and power to master the lanes in both tournament and practice modes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Championship Lode Runner (Japan)', '1985', NaN, 'Hudson Soft', '1', NaN, 'Screen-based puzzle platformer.', 'Collect all the gold in each level while avoiding guards and digging traps.', 'An advanced and much more difficult version of the classic Lode Runner puzzle game.', 'Designed for experts, Championship Lode Runner features complex level layouts that require precise timing and strategic digging to outsmart enemies and collect every treasure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Championship Pool (USA)', '1990', NaN, 'Bitmasters', '1', NaN, 'Billiards simulation with multiple game modes.', 'Master various pool games like 8-ball and 9-ball to win the championship.', 'A comprehensive pool simulator featuring realistic ball physics and tournament play.', 'Championship Pool provides a variety of modes, including speed pool and trick shots, offering a deep experience for fans of billiards looking for a competitive 8-bit challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Championship Rally (Europe)', '1991', NaN, 'Hudson Soft', '1', NaN, 'Top-down racing game with various terrains.', 'Complete each race track in the fastest time possible to win the rally circuit.', 'A high-speed top-down racer featuring diverse weather conditions and tracks.', 'Championship Rally focuses on precision driving and car handling. Players must navigate tight corners and different surfaces, from mud to snow, to claim the top spot.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chaos World (Japan)', '1991', NaN, 'Natsume', '1', NaN, 'Turn-based RPG with automated combat elements.', 'Assemble a party of heroes to defeat the Dark King and save the kingdom.', 'A unique NES RPG featuring a job system and fast-paced auto-battle mechanics.', 'Chaos World is a deep RPG where players manage a guild, hire companions, and explore a vast fantasy world. It stands out for its day/night cycle and tactical character progression.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chaos World (Japan) [En by Aeon Genesis v0.98F]', 'Hack', NaN, 'Natsume', '1', NaN, 'Turn-based RPG with automated combat elements.', 'Assemble a party of heroes to defeat the Dark King and save the kingdom.', 'An English-translated fantasy RPG with deep party customization and auto-battles.', 'This fan-translated version allows English speakers to enjoy the complex guild systems and storyline of Chaos World, one of the more technically advanced RPGs on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chaos World (Japan) [En by Aeon Genesis v0.98F] (Bug Fix)', 'Hack', NaN, 'Natsume', '1', NaN, 'Turn-based RPG with automated combat elements.', 'Assemble a party of heroes to defeat the Dark King and save the kingdom.', 'The English version of Chaos World with technical glitches and bugs fixed.', 'This edition provides the complete Chaos World experience in English, with additional patches to ensure smooth gameplay and correct original programming errors.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cheetahmen II (USA) (Unl)', '1992', NaN, 'Active Enterprises', '1', NaN, 'Side-scrolling action platformer (Unlicensed).', 'Control the Cheetahmen to stop Dr. Morbis and his genetically altered monsters.', 'The infamous unfinished sequel to the Cheetahmen saga, known for its cult status.', 'Cheetahmen II is a rare unlicensed title featuring the titular feline heroes. It is famous in the retro community for its music and its history as an unreleased prototype.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chess Academy (Asia) (Unl) (Famicom)', '1985', NaN, 'Unlicensed', '1', NaN, 'Strategic board game simulation.', 'Checkmate the opponent''s king using traditional chess rules and tactics.', 'An educational chess game designed to teach and challenge players of all levels.', 'Chess Academy offers various difficulty settings and a clean interface, aimed at players looking to improve their chess skills through 8-bit computer matches.', NULL);
