INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chessmaster, The (USA)', '1989', NaN, 'U.S. Gold', '1', NaN, 'Strategic board game simulation.', 'Defeat the computer or a human opponent in a formal game of chess.', 'One of the most famous chess engines adapted for the NES platform.', 'The Chessmaster provides a powerful AI and multiple visual perspectives, making it a staple for chess enthusiasts who want a portable and challenging opponent.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chester Field - Ankoku Shin heno Chousen (Japan)', '1987', NaN, 'Vic Tokai', '1', NaN, 'Action-RPG with side-scrolling and top-down phases.', 'Journey through a dark world to defeat the god of darkness.', 'A challenging hybrid RPG that blends action platforming with world exploration.', 'Chester Field is known for its difficulty and dark atmosphere. Players must explore dungeons, upgrade weapons, and defeat massive bosses to save the kingdom from an ancient evil.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chester Field - Ankoku Shin heno Chousen (Japan) (Beta)', '1987', NaN, 'Vic Tokai', '1', NaN, 'Action-RPG with side-scrolling and top-down phases.', 'Journey through a dark world to defeat the god of darkness.', 'An early prototype version of Chester Field with potential gameplay differences.', 'This beta version offers a look into the development of Chester Field, featuring the same dark fantasy elements with minor variations in level layout or balance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chester Field - Ankoku Shin heno Chousen (Japan) [En by Aeon Genesis v1.00b]', 'Hack', NaN, 'Vic Tokai', '1', NaN, 'Action-RPG with side-scrolling and top-down phases.', 'Journey through a dark world to defeat the god of darkness.', 'The English translation of the dark and difficult action-RPG, Chester Field.', 'This version translates the complex story and menus of Chester Field, making the challenging journey of the hero accessible to an English-speaking audience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chevaliers du Zodiaque, Les - La Legende d''Or (France)', '1988', NaN, 'Bandai', '1', NaN, 'Turn-based RPG and action hybrid.', 'Relive the Golden Legend by defeating the Gold Saints in the Sanctuary.', 'A French-language RPG based on the iconic Saint Seiya anime series.', 'Players take control of Seiya and the Bronze Saints, using Cosmo to unleash special attacks in a mix of side-scrolling levels and cinematic turn-based battles.', NULL);
