INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chibi Maruko-Chan - Uki Uki Shopping (Japan)', '1990', NaN, 'Namco', '1', NaN, 'Board game style simulation and mini-games.', 'Navigate the board and complete shopping tasks to win the game.', 'A charming and colorful game based on the popular Chibi Maruko-Chan anime.', 'Chibi Maruko-Chan focuses on shopping and daily life activities in a board game format, featuring various mini-games and interactions with the show''s cast.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chiisana Obake - Acchi Socchi Kocchi (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer.', 'Navigate through levels as a cute ghost to reach the goal.', 'A family-friendly platformer featuring adorable characters and light puzzles.', 'Based on a children''s book series, this game challenges players to use ghostly abilities to bypass obstacles and enemies in a bright and cheerful world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chiisana Obake - Acchi Socchi Kocchi (Japan) [En by KingMike v1.0] (~Little Ghosts)', 'Hack', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer.', 'Navigate through levels as a cute ghost to reach the goal.', 'The English translation of the charming platformer Chiisana Obake.', 'This fan translation makes the story and mechanics of the Little Ghosts adventure clear for English players, maintaining the game''s lighthearted and fun tone.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chik Bik Ji Jin - Saam Gwok Ji (Asia) (Unl)', '1989', NaN, 'Unlicensed', '1', NaN, 'Turn-based strategy RPG.', 'Command armies during the Three Kingdoms era to unify China.', 'A tactical RPG based on the historical Three Kingdoms period.', 'This unlicensed title features complex strategy and resource management, allowing players to recruit famous generals and lead troops in massive 8-bit battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chiki Chiki Machine Mou Race (Japan)', '1984', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer.', 'Race through levels as Muttley to sabotage opponents and win.', 'A fun action game based on the Wacky Races cartoon series.', 'Players control Muttley in a quest to assist Dick Dastardly. The game features creative level design and various power-ups inspired by the classic Hanna-Barbera show.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chiller (Australia) (Unl)', '1986', NaN, 'Action Graphics', '1', NaN, 'Light gun shooter (unlicensed).', 'Shoot targets and interact with various torture devices in a haunted setting.', 'A controversial and gory light gun shooter set in a series of horror chambers.', 'Chiller is known as one of the most violent games on the NES. Players must shoot specific body parts and mechanisms to progress through macabre levels before time runs out.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chiller (USA) (Unl)', '1986', NaN, 'Action Graphics', '1', NaN, 'Light gun shooter (unlicensed).', 'Shoot targets and interact with various torture devices in a haunted setting.', 'A controversial and gory light gun shooter set in a series of horror chambers.', 'Chiller is known as one of the most violent games on the NES. Players must shoot specific body parts and mechanisms to progress through macabre levels before time runs out.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chinese Checkers (Asia) (Unl) (Famicom)', '1985', NaN, 'Unlicensed', '2', NaN, 'Strategy board game.', 'Move all your pieces across the board to the opposite corner before your opponent.', 'A faithful 8-bit adaptation of the classic strategy board game.', 'This unlicensed version of Chinese Checkers allows players to compete against the computer or friends in a tactical race to move pegs across a star-shaped board.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chinese Checkers (Asia) (Unl) (NES)', '1985', NaN, 'Unlicensed', '2', NaN, 'Strategy board game.', 'Move all your pieces across the board to the opposite corner before your opponent.', 'A faithful 8-bit adaptation of the classic strategy board game.', 'This unlicensed version of Chinese Checkers allows players to compete against the computer or friends in a tactical race to move pegs across a star-shaped board.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chinese KungFu (Asia) (Unl)', '1987', NaN, 'Unlicensed', '1', NaN, 'Side-scrolling martial arts beat ''em up.', 'Defeat various masters and enemies to prove your Kung Fu skills.', 'A classic martial arts action game featuring traditional 8-bit combat mechanics.', 'This unlicensed title challenges players to master martial arts techniques across several stages, fighting waves of opponents and unique bosses in a quest for combat supremacy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale - Rescue Rangers 2 (USA) (Beta)', '1993', NaN, 'Capcom', '1', NaN, 'Cooperative action platformer.', 'Thwart Fat Cat''s evil plans and recover the stolen Urn of Pharaoh.', 'An early prototype of the beloved Disney sequel featuring iconic duo Chip and Dale.', 'This beta version offers a glimpse into the development of the sequel, featuring the same high-quality platforming where players throw objects to defeat enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale 2 - Boss-Only Hack', 'Hack', NaN, 'Capcom', '1', NaN, 'Boss rush action game.', 'Defeat all the major bosses of the game in rapid succession.', 'A specialized hack that removes standard levels to focus purely on boss battles.', 'This modification skips the platforming sections, challenging players to master the patterns of Fat Cat''s henchmen in a continuous, high-intensity gauntlet.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale Lomax Attacks v.1.2', 'Hack', NaN, 'Capcom', '1', NaN, 'Enhanced action platformer.', 'Complete redesigned levels with increased difficulty and new layouts.', 'A fan-made overhaul of the original game featuring new challenges for veterans.', 'Lomax Attacks modifies the classic Rescue Rangers experience with fresh level designs and enemy placements, providing a second quest feel for long-time fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale Rescue Rangers (Europe)', '1990', NaN, 'Capcom', '1', NaN, 'Cooperative action platformer.', 'Find the lost kitten and eventually defeat the villainous Fat Cat.', 'A legendary Disney platformer known for its fun co-op mechanics and tight controls.', 'Players control Chip and Dale in a vibrant world where they must pick up and throw crates, apples, and other objects to defeat enemies and navigate urban environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale Rescue Rangers (USA)', '1990', NaN, 'Capcom', '1', NaN, 'Cooperative action platformer.', 'Find the lost kitten and eventually defeat the villainous Fat Cat.', 'A legendary Disney platformer known for its fun co-op mechanics and tight controls.', 'Players control Chip and Dale in a vibrant world where they must pick up and throw crates, apples, and other objects to defeat enemies and navigate urban environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale Rescue Rangers 2 (Basketball Hack)', 'Hack', NaN, 'Capcom', '1', NaN, 'Sports-themed action modification.', 'Score points or defeat enemies using basketball-themed sprites and objects.', 'A quirky visual hack that turns the Rescue Rangers sequel into a basketball adventure.', 'This creative mod replaces standard throwing objects with basketballs and modifies character sprites to give the classic platformer a unique sports-inspired aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale Rescue Rangers 2 (Europe)', '1993', NaN, 'Capcom', '1', NaN, 'Cooperative action platformer.', 'Stop Fat Cat from using the Urn of Pharaoh to release an ancient evil.', 'The polished sequel to the original hit, featuring improved graphics and new moves.', 'Chip and Dale return in this high-quality Capcom title, offering better co-op interactions and larger boss fights as they travel through amusement parks and sewers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale Rescue Rangers 2 (USA)', '1993', NaN, 'Capcom', '1', NaN, 'Cooperative action platformer.', 'Stop Fat Cat from using the Urn of Pharaoh to release an ancient evil.', 'The polished sequel to the original hit, featuring improved graphics and new moves.', 'Chip and Dale return in this high-quality Capcom title, offering better co-op interactions and larger boss fights as they travel through amusement parks and sewers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale Rescue Rangers 2 Hardcore Edition', 'Hack', NaN, 'Capcom', '1', NaN, 'High-difficulty action platformer.', 'Survive extremely difficult level layouts to defeat Fat Cat once more.', 'A Kaizo-style modification designed to test the skills of the most expert players.', 'This version ramps up the difficulty significantly, featuring tighter jumps, more enemies, and less room for error compared to the original Capcom release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip ''n Dale: Rescue Rangers 4', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Action platformer (Pirate/Hack).', 'Navigate new or modified stages to complete the rescue mission.', 'An unlicensed or bootleg entry in the series, often featuring assets from other games.', 'Frequently found on multicarts, this title is usually a hack of another game (like Felix the Cat) with Chip ''n Dale sprites inserted to capitalize on the series'' popularity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip & Dale: Tale Spin Levels', 'Hack', NaN, 'Capcom', '1', NaN, 'Action platformer crossover.', 'Complete stages inspired by the Tale Spin universe using Rescue Rangers mechanics.', 'A creative level-swap hack that brings Chip and Dale into the world of Tale Spin.', 'This mod takes the gameplay of Rescue Rangers and applies it to the environments and level layouts of Capcom''s Tale Spin, creating a unique hybrid experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip and Dale Alternative', 'Hack', NaN, 'Capcom', '1', NaN, 'Action platformer with modified mechanics.', 'Complete the game with altered physics or character stats.', 'A gameplay-focused hack that changes how the squirrels move and interact.', 'This Alternative version provides a fresh take on the classic game by tweaking movement speeds, jump heights, or enemy behavior for a different feel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip and Dale Rescue Rangers (U) Roketv2', '1990', NaN, 'Capcom', '1', NaN, 'Action platformer modification.', 'Navigate the game with special rocket or speed-based enhancements.', 'A fun modification that alters the movement capabilities of the protagonists.', 'This version features customized gameplay tweaks (often referred to as ''Roket'') that change the pace of the original Rescue Rangers adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip to Dale no Daisakusen (Japan)', '1989', NaN, 'Capcom', '1', NaN, 'Cooperative action platformer.', 'Find the lost kitten and eventually defeat the villainous Fat Cat.', 'The Japanese version of the classic Disney/Capcom platforming hit.', 'Known as Great Mission, this is the original Famicom release featuring the same iconic crate-throwing gameplay and memorable 8-bit soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip to Dale no Daisakusen 2 (Japan)', '1993', NaN, 'Capcom', '1', NaN, 'Cooperative action platformer.', 'Stop Fat Cat from using the Urn of Pharaoh to release an ancient evil.', 'The Japanese Famicom release of the polished Rescue Rangers sequel.', 'This version features the same high-end 8-bit graphics and cooperative mechanics that made the sequel a favorite among NES collectors and Disney fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chip''s Challenge (Proto)', '1992', NaN, 'Epyx', '1', NaN, 'Grid-based puzzle-adventure.', 'Collect all the chips in each level to open the exit and progress.', 'An unreleased NES port of the famous tile-based puzzle game.', 'Originally a hit on the Atari Lynx and PC, this NES prototype shows how the complex puzzles and logic-gate mechanics would have functioned on Nintendo''s hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chitei Senkuu Vazolder (Japan)', '1988', NaN, 'Nichibutsu', '1', NaN, 'Side-scrolling shooter and vehicle exploration.', 'Pilot the Vazolder drill-tank through subterranean levels to stop an invasion.', 'A unique underground shooter where you navigate a powerful drilling machine.', 'Known as Wurm: Journey to the Center of the Earth in the US, this game blends high-speed shooting with RPG elements and first-person boss battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chiyonofuji no Ooichou (Japan)', '1987', NaN, 'Taito', '1', NaN, 'Sumo wrestling simulation.', 'Rise through the ranks of professional sumo to reach the Yokozuna title.', 'A sports simulation featuring one of the most famous sumo wrestlers in history.', 'This Famicom title focuses on the career of Chiyonofuji, allowing players to manage training and compete in traditional sumo tournaments with strategic button presses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Choplifter (Japan)', '1985', NaN, 'Brotech', '1', NaN, 'Side-scrolling helicopter rescue-action.', 'Fly behind enemy lines to rescue hostages and return them to the base.', 'A faithful port of the classic arcade and PC game about aerial rescues.', 'Players must balance attacking enemy tanks and planes with the delicate task of landing to pick up survivors in this challenging 8-bit flight mission.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chou-Wakusei Senki - MetaFight (Japan)', '1989', NaN, 'Sunsoft', '1', NaN, 'Action-platformer and top-down shooter hybrid.', 'Explore a vast planet in a tank and on foot to destroy the alien overlord.', 'The original Japanese version of the cult classic Blaster Master.', 'MetaFight features an incredible soundtrack and dual-gameplay styles, switching from side-scrolling tank combat to top-down exploration inside caves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Choujikuu Yousai - Macross (Japan)', '1985', NaN, 'Namco', '1', NaN, 'Side-scrolling space shooter.', 'Destroy the Zentraedi fleet by switching between three fighter modes.', 'An early Famicom shooter based on the legendary Macross anime series.', 'Players control a Valkyrie fighter that can transform between jet, gerwalk, and battloid modes, each offering different tactical advantages during the mission.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Choujin - Ultra Baseball (Japan)', '1989', NaN, 'Culture Brain', '1', NaN, 'Sports simulation with arcade power-ups.', 'Win baseball games using ultra special moves and superhuman skills.', 'A high-energy baseball game where players use spectacular special abilities.', 'Known in the West as Base Wars, this Japanese version features professional teams and the ability to trigger Ultra plays that defy the laws of physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Choujin Ookami Senki - Warwolf (Japan)', '1988', NaN, 'Datam Polystar', '1', NaN, 'Side-scrolling action platformer.', 'Battle through futuristic stages and transform into a powerful wolf-man.', 'The Japanese version of Werewolf: The Last Warrior featuring intense action.', 'Players fight through a post-apocalyptic world, collecting items to trigger a transformation that increases their speed, strength, and leaping ability.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Choujin Sentai - Jetman (Japan)', '1991', NaN, 'Bandai', '1', NaN, 'Side-scrolling action platformer and giant robot battles.', 'Stop the Vyram organization and defeat giant monsters with the Great Icarus.', 'A high-quality action game based on the popular Super Sentai TV series.', 'Jetman allows players to choose between five heroes, each with different weapons, and culminates in massive first-person robot battles against kaiju.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Choujin Sentai - Jetman (Japan) [En by Mog House v1.0]', 'Hack', NaN, 'Bandai', '1', NaN, 'Side-scrolling action platformer.', 'Defeat the Vyram forces and protect Earth with the Jetman team.', 'The English translation of the high-quality Super Sentai action game.', 'This version allows players to experience the Jetman storyline in English. Choose from five different rangers and engage in side-scrolling combat followed by epic giant robot boss battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chrono Trigger (C)', 'Hack', NaN, 'Square', '1', NaN, 'Turn-based RPG (Pirate/Port).', 'Travel through time to prevent a global apocalypse.', 'A notorious 8-bit demake or pirate port of the legendary SNES RPG.', 'This unlicensed port attempts to bring the massive Chrono Trigger experience to the NES. While simplified, it features the iconic characters and time-traveling plot of the original masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chubby Cherub (USA)', '1986', NaN, 'Nintendo', '1', NaN, 'Side-scrolling flying action game.', 'Fly through levels and eat snacks to stay powered up while rescuing friends.', 'A quirky and colorful action game featuring a flying cherub.', 'Originally a Bakabon licensed game in Japan, Chubby Cherub tasks players with managing a stamina meter by eating food as they navigate obstacles and enemies in a cheerful 8-bit world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chuugoku Janshi Story - Tonpuu (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Mahjong simulation with RPG elements.', 'Defeat opponents in Mahjong matches to progress through the story.', 'A unique blend of traditional Mahjong gameplay and adventure storytelling.', 'This Famicom title takes the classic game of Mahjong and adds a narrative layer, where players travel and interact with characters while mastering the tiles to advance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chuugoku Senseijutsu (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Astrology and fortune-telling simulation.', 'Input personal data to receive astrological readings and predictions.', 'A specialized Chinese astrology and divination program for the Famicom.', 'Not a traditional game, this software uses traditional Chinese star-charting methods to provide users with horoscopes and lifestyle advice based on their birth dates.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chuuka Taisen (Japan)', '1988', NaN, 'Taito', '1', NaN, 'Side-scrolling shooter (Shoot ''em up).', 'Fly through mythological landscapes to defeat the dark forces of the sky.', 'A vibrant mythological shooter known for its charming graphics and difficulty.', 'Known as Cloud Master, players control a young boy on a flying cloud. The game features various power-ups and creative bosses inspired by Chinese folklore and legends.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Chuuka Taisen (Japan) [En by Ice v1.0] (~Cloud Master)', 'Hack', NaN, 'Taito', '1', NaN, 'Side-scrolling shooter (Shoot ''em up).', 'Fly through mythological landscapes to defeat the dark forces of the sky.', 'The English version of the classic mythological shooter Chuuka Taisen.', 'Navigate a young hero on a magic cloud through beautiful 8-bit stages. This version brings the challenging shooting action and unique power-up system to an English-speaking audience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Circus Caper (USA)', '1989', NaN, 'Capcom', '1', NaN, 'Side-scrolling action and mini-game hybrid.', 'Explore a sinister circus and complete challenges to rescue your sister.', 'A varied action-adventure game set in a mysterious and dangerous circus.', 'Circus Caper mixes traditional platforming with unique circus-themed mini-games. Players must navigate through the carnival grounds and defeat themed bosses to save the protagonist''s sibling.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Circus Charlie (Japan)', '1986', NaN, 'Taito', '1', NaN, 'Arcade-style action and stunt simulation.', 'Complete various circus performances like lion riding and tightrope walking.', 'A classic arcade port featuring high-score challenges and iconic circus stunts.', 'Circus Charlie is a beloved early Famicom title where timing is everything. Players must master multiple disciplines, including jumping through fire hoops and swinging on trapezes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'City Adventure Touch - Mystery of Triangle (Japan)', '1985', NaN, 'Jaleco', '1', NaN, 'Action-adventure with exploration.', 'Explore a vast city to find items and progress through the story.', 'A non-linear adventure game based on the popular Touch manga and anime.', 'Featuring the characters from the hit baseball series, this title focuses on exploration and combat in a top-down and side-scrolling urban environment filled with secrets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'City Connection (Europe)', '1985', NaN, 'Jaleco', '1', NaN, 'Arcade-style driving and platforming.', 'Paint every road section while avoiding police cars and obstacles.', 'A unique high-speed platformer where you drive a car across world cities.', 'Players control a small car that paints the road as it moves. The goal is to cover every inch of the multi-tiered levels while using oil cans to stop the police.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'City Connection (Japan)', '1985', NaN, 'Jaleco', '1', NaN, 'Arcade-style driving and platforming.', 'Paint every road section while avoiding police cars and obstacles.', 'A unique high-speed platformer where you drive a car across world cities.', 'Players control a small car that paints the road as it moves. The goal is to cover every inch of the multi-tiered levels while using oil cans to stop the police.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'City Connection (USA)', '1989', NaN, 'Vic Tokai', '1', NaN, 'Arcade-style driving and platforming.', 'Paint every road section while avoiding police cars and obstacles.', 'A unique high-speed platformer where you drive a car across world cities.', 'Players control a small car that paints the road as it moves. The goal is to cover every inch of the multi-tiered levels while using oil cans to stop the police.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Clash at Demonhead (USA)', '1988', NaN, 'GameTek', '1', NaN, 'Non-linear action-adventure platformer.', 'Explore a massive interconnected map to rescue Professor Plum and stop a bomb.', 'A cult classic adventure known for its anime style and open-ended exploration.', 'Featuring a shop system and multiple routes, Clash at Demonhead allows players to choose their path as they acquire new suits and gadgets to survive the dangerous island.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Classic Concentration (USA)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Puzzle and memory board game.', 'Solve the hidden rebus puzzle by matching cards on a grid.', 'An 8-bit adaptation of the popular TV game show featuring memory challenges.', 'Players must compete against an opponent or the computer to match pairs and reveal pieces of a puzzle, using logic and memory to win the game''s grand prize.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cliffhanger (USA)', '1984', NaN, 'Nintendo', '1', NaN, 'Side-scrolling beat ''em up and action game.', 'Scale mountains and fight through enemies to stop a group of thieves.', 'An action-packed movie tie-in featuring climbing and combat mechanics.', 'Based on the Sylvester Stallone film, Cliffhanger tasks players with surviving the cold wilderness while engaging in hand-to-hand combat and dangerous mountain navigation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Clu Clu Land (World)', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Single-screen action-puzzle game.', 'Swing around pegs to reveal a hidden image on the screen.', 'A unique Nintendo classic focused on momentum and pattern recognition.', 'Playing as Bubbles, players must use pegs to turn and maneuver, uncovering gold bars that form a specific shape while avoiding the dangerous Unira creatures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'CnD2-4pl: Chip n Dale 2 - 4 players', '1988', NaN, 'Data East', '1', NaN, 'Multiplayer action platformer (Hack).', 'Team up with three other players to complete the Rescue Rangers mission.', 'A groundbreaking hack that expands the classic sequel to support 4 players.', 'This modification allows four players to control Chip, Dale, and other characters simultaneously, creating a chaotic and fun cooperative experience unlike anything in the original.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cobra Command (Japan)', '1988', NaN, 'Data East', '1', NaN, 'Side-scrolling helicopter shooter.', 'Fly through enemy territory to destroy bases and rescue hostages.', 'An intense 8-bit flight shooter featuring mission-based helicopter combat.', 'Similar to Choplifter but with more focus on combat, players must navigate a powerful gunship through heavily defended zones to complete high-stakes military objectives.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cobra Command (USA)', '1988', NaN, 'Unlicensed', '1', NaN, 'Side-scrolling helicopter shooter.', 'Fly through enemy territory to destroy bases and rescue hostages.', 'An intense 8-bit flight shooter featuring mission-based helicopter combat.', 'Similar to Choplifter but with more focus on combat, players must navigate a powerful gunship through heavily defended zones to complete high-stakes military objectives.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cobra Mission (Asia) (Unl)', '1989', NaN, 'Nintendo', '1', NaN, 'Top-down action-RPG.', 'Explore islands and complete missions to stop a criminal organization.', 'A rare unlicensed action game featuring exploration and combat.', 'This title features open exploration and various weapons. Players must navigate through towns and hostile areas to gather information and complete their undercover mission.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cobra Triangle (Europe)', '1989', NaN, 'Nintendo', '1', NaN, 'Isometric vehicle action and racing.', 'Complete various objectives in a weaponized speedboat.', 'A fast-paced boat racer with combat, bombs, and monster encounters.', 'Developed by Rare, Cobra Triangle is a technical showcase for the NES, featuring intense racing, mine disposal missions, and giant sea monster boss fights.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cobra Triangle (USA)', '1989', NaN, 'Nintendo', '1', NaN, 'Isometric vehicle action and racing.', 'Complete various objectives in a weaponized speedboat.', 'A fast-paced boat racer with combat, bombs, and monster encounters.', 'Developed by Rare, Cobra Triangle is a technical showcase for the NES, featuring intense racing, mine disposal missions, and giant sea monster boss fights.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cocoron (Japan)', '1990', NaN, 'Vic Tokai', '1', NaN, 'Customizable action platformer.', 'Create your own hero and rescue the Princess from the world of dreams.', 'A legendary Famicom game featuring deep character customization.', 'Created by the director of Mega Man, Cocoron allows players to build their character from various heads, bodies, and weapons, affecting how they move and fight through dream-like stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cocoron (Japan) [En by Magic Destiny v1.0]', '1992', NaN, 'Vic Tokai', '1', NaN, 'Customizable action platformer.', 'Create your own hero and rescue the Princess from the world of dreams.', 'The English translation of the highly creative character-building platformer.', 'This version translates the complex character creation menus and story of Cocoron, making this hidden Famicom masterpiece fully playable for English audiences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Code Name - Viper (USA)', '1989', NaN, 'Taito', '1', NaN, 'Side-scrolling action-platformer.', 'Infiltrate drug cartels and rescue hostages in the South American jungle.', 'A gritty, high-octane action game similar to the Rolling Thunder style.', 'Players control a special agent using cover mechanics and precision shooting. The game is known for its challenging difficulty and cinematic mission-based storytelling.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Color a Dinosaur (USA)', '1989', NaN, 'Taito', '1', NaN, 'Educational / Creative simulation.', 'Select colors and patterns to fill in various dinosaur drawings.', 'A simple and colorful digital coloring book designed for young children.', 'Color a Dinosaur is an early educational title for the NES that allows kids to experiment with a palette of colors and textures, applying them to different prehistoric scenes in a stress-free environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Colorful Dragon (Asia) (Unl) (NES)', 'Hack', NaN, 'Taito', '1', NaN, 'Tile-matching puzzle game.', 'Match and clear colored blocks to progress through increasingly difficult levels.', 'A rare unlicensed puzzle game featuring vibrant colors and addictive mechanics.', 'Developed by Sachen, this title challenges players with strategic block placement. It features traditional puzzle elements where quick thinking and pattern recognition are key to achieving high scores.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Columbus - Ougon no Yoake (Japan)', '1986', NaN, 'Capcom', '1', NaN, 'Turn-based RPG and exploration.', 'Command the fleet of Christopher Columbus to discover the New World.', 'A historical RPG that blends high-seas exploration with traditional fantasy combat.', 'Known as Golden Dawn, this RPG tasks players with managing resources and a crew while exploring uncharted territories, blending historical figures with supernatural fantasy elements.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Columbus - Ougon no Yoake (Japan) [En by Aishsha v1.02] (~Columbus - Golden Dawn)', 'Hack', NaN, 'Capcom', '1', NaN, 'Turn-based RPG and exploration.', 'Command the fleet of Christopher Columbus to discover the New World.', 'The English translation of the unique historical fantasy RPG Golden Dawn.', 'This fan translation allows players to follow the complex story and dialogue of Columbus''s journey, making the strategic naval exploration and RPG systems accessible in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Commando (USA)', '1985', NaN, 'Capcom', '1', NaN, 'Vertical-scrolling run and gun shooter.', 'Infiltrate enemy territory alone to rescue hostages and destroy the base.', 'A legendary arcade port featuring intense 8-bit military shooting action.', 'As Super Joe, players must fight through waves of soldiers using a machine gun and grenades. It is a classic example of the high-difficulty lone wolf shooter genre on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Communist Mario 3', 'Hack', NaN, 'Homebrew', '1', NaN, 'Side-scrolling platformer (Visual Hack).', 'Complete the levels of Mario 3 under a themed satirical aesthetic.', 'A popular visual modification of Super Mario Bros. 3 with a humorous political theme.', 'This hack replaces the original sprites and palettes with Communist-themed visuals. While the core gameplay remains the masterpiece of SMB3, the aesthetic provides a unique and funny twist.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Conan (USA)', '1991', NaN, 'Mindscape', '1', NaN, 'Side-scrolling action platformer.', 'Battle through mystical lands to defeat the wizard Volta and his minions.', 'A dark fantasy action game based on the legendary Conan the Barbarian.', 'Players control Conan as he uses his sword and various sub-weapons to navigate treacherous environments, featuring challenging combat and classic 8-bit platforming levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Conflict (Japan)', '1989', NaN, 'Vic Tokai', '1', NaN, 'Hex-based military strategy.', 'Outmaneuver and destroy the enemy commander’s forces on the battlefield.', 'A deep tactical war simulator focused on modern military combat.', 'Conflict offers a sophisticated turn-based strategy experience where players manage different types of tanks, helicopters, and infantry across various terrain types to gain the upper hand.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Conflict (USA)', '1989', NaN, 'Vic Tokai', '1', NaN, 'Hex-based military strategy.', 'Outmaneuver and destroy the enemy commander’s forces on the battlefield.', 'A deep tactical war simulator focused on modern military combat.', 'Conflict offers a sophisticated turn-based strategy experience where players manage different types of tanks, helicopters, and infantry across various terrain types to gain the upper hand.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Conquest of the Crystal Palace (USA)', '1990', NaN, 'Quest', '1', NaN, 'Side-scrolling action platformer.', 'Journey to the Crystal Palace to defeat the evil Zaras and reclaim the throne.', 'A high-quality action game featuring a hero and his loyal dog companion.', 'Developed by Quest, this game features fast-paced combat and a unique shop system. Players can call upon their dog, Kim, to help defeat enemies in a vibrant mythological world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Contra (USA)', '1988', NaN, 'Konami', '2', NaN, 'Side-scrolling and 3D-style run and gun.', 'Fight through alien-infested islands to destroy the Red Falcon organization.', 'The ultimate 8-bit action game, famous for its intense difficulty and co-op play.', 'Contra is a cornerstone of the NES library, featuring legendary power-ups like the Spread Gun and iconic boss battles, setting the gold standard for the run-and-gun genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Contra (USA) Secondary Weapon Slot and Remote Barrier', 'Hack', NaN, 'Konami', '2', NaN, 'Enhanced run and gun shooter (Hack).', 'Defeat the alien threat using a newly added strategic weapon-switching system.', 'A modern gameplay hack that allows players to carry and swap two weapons.', 'This modification significantly changes the strategy of Contra by allowing players to store a secondary weapon and switch on the fly, similar to later entries in the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Contra Force (USA)', '1992', NaN, 'Konami', '2', NaN, 'Isometric and side-scrolling action.', 'Stop a terrorist organization in Neo City using a team of elite commandos.', 'A tactical spin-off of the Contra series featuring four swappable characters.', 'Contra Force introduces a unique character-switching mechanic, where each hero has a different weapon set and special abilities, focused on urban combat and destructible environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Contra Hardest Mode', 'Hack', NaN, 'Konami', '2', NaN, 'Extreme difficulty run and gun (Hack).', 'Survive a brutally difficult version of the original alien invasion.', 'A Kaizo-level challenge for expert players who find the original Contra too easy.', 'This hack increases enemy density, speed, and projectile frequency, testing the reflexes and memorization of even the most seasoned Contra veterans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Contra Spirits (1996) (Unl)', '1996', NaN, 'Unlicensed', '2', NaN, 'Side-scrolling run and gun (Pirate Port).', 'Battle through modified stages inspired by the SNES classic Contra III.', 'A curious unlicensed 8-bit demake of the legendary Super Nintendo title.', 'This bootleg attempts to replicate the levels and bosses of Contra III: The Alien Wars on NES hardware, resulting in a unique and technically interesting piece of history.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Contra Spirits ending fixed', 'Hack', NaN, 'Unlicensed', '2', NaN, 'Side-scrolling run and gun (Pirate Port).', 'Complete the 8-bit demake and view the properly restored ending sequence.', 'An optimized version of the Contra Spirits pirate port with technical fixes.', 'This version corrects the crashes and glitches found in the original unlicensed port, ensuring the game can be played from start to finish with a working ending.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Contra: Easy Mode', 'Hack', NaN, 'Konami', '2', NaN, 'Accessible run and gun shooter (Hack).', 'Experience the classic action of Contra with lowered difficulty settings.', 'A beginner-friendly version of Contra featuring more lives or stronger weapons.', 'This modification is designed for players who want to enjoy the story and levels of Contra without the extreme frustration of the original''s one-hit-kill difficulty.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cool World (USA)', '1992', NaN, 'Ocean', '1', NaN, 'Side-scrolling action-adventure.', 'Travel between the real world and the doodle world to stop a villainess.', 'A movie-based platformer featuring a mix of cartoon and realistic aesthetics.', 'Based on the film starring Brad Pitt, this game challenges players to collect doodles and avoid traps in a surreal landscape, blending unique 8-bit visuals with platforming puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Corvette ZR-1 Challenge (Europe)', '1990', NaN, 'Imagitec', '1', NaN, 'Behind-the-car racing simulator.', 'Compete in various races to prove your skills as a Corvette driver.', 'A licensed racing game focused on the speed and handling of the iconic ZR-1.', 'Featuring impressive scrolling and different perspectives, this title challenges players to master various tracks while managing the high-performance stats of the Chevrolet Corvette.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmic Epsilon (Japan)', '1989', NaN, 'Asmik', '1', NaN, 'Behind-the-back pseudo-3D shooter.', 'Pilot a high-tech combat suit to defend the galaxy from an alien fleet.', 'A visually stunning 3D-style shooter that pushes the NES hardware.', 'Cosmic Epsilon features fast-paced action similar to Space Harrier, with impressive scaling effects and a variety of planetary environments to fly through.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmic Epsilon (Japan) [En by Stardust Crusaders v1.0]', '1989', NaN, 'Asmik', '1', NaN, 'Behind-the-back pseudo-3D shooter.', 'Pilot a high-tech combat suit to defend the galaxy from an alien fleet.', 'The English translation of the fast-paced 3D-style shooter Cosmic Epsilon.', 'This version translates the menus and mission briefings of the original Famicom release, allowing players to fully understand the story behind the intense aerial combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmic Spacehead (Europe) (En,Fr,De,Es) (Unl)', '1991', NaN, 'Codemasters', '1', NaN, 'Adventure and platformer hybrid.', 'Explore planets to gather evidence of Earth''s existence and win a contest.', 'A unique blend of point-and-click adventure and 8-bit platforming action.', 'Cosmic Spacehead follows a quirky alien protagonist. The game switches between puzzle-solving exploration and traditional side-scrolling levels, all presented in a distinct cartoon style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmic Wars (Japan)', '1988', NaN, 'Namco', '1', NaN, 'Turn-based space strategy.', 'Conquer the galaxy by managing fleets and engaging in tactical battles.', 'A deep and strategic space opera set in the Gradius universe.', 'This turn-based strategy game allows players to build ships and expand their empire across the stars, featuring characters and lore from the iconic Gradius shooting series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmic Wars (Japan) [En by TransBRC v0.993]', '1988', NaN, 'Namco', '1', NaN, 'Turn-based space strategy.', 'Conquer the galaxy by managing fleets and engaging in tactical battles.', 'The English translation of the strategic Gradius spin-off, Cosmic Wars.', 'This fan translation makes the complex strategy menus and galactic narrative of Cosmic Wars accessible, allowing players to master 8-bit space fleet command.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmo Genesis (Japan)', '1989', NaN, 'Asmik', '1', NaN, 'First-person space combat simulator.', 'Destroy enemy fleets and protect your mothership across different sectors.', 'An immersive first-person shooter set in the depths of space.', 'Known as Star Voyager in the USA, this title features open-ended exploration and strategic combat, where players must manage fuel and resources while battling in the cockpit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmo Genesis (Japan) [En by Aeon Genesis v1.1]', '1989', NaN, 'Asmik', '1', NaN, 'First-person space combat simulator.', 'Navigate the galaxy and destroy enemy fleets to save your home planet.', 'The English translation of the immersive 8-bit space cockpit simulator.', 'This fan-translated version of Star Voyager (Japan) allows players to fully understand the strategic mission briefings and resource management required to survive in deep space.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmo Police Galivan (Japan)', '1989', NaN, 'Nichibutsu', '1', NaN, 'Action platformer and RPG hybrid.', 'Battle through robotic enemies to recover your suit and stop the Mado organization.', 'A unique blend of side-scrolling combat and RPG-style character progression.', 'Cosmo Police Galivan features a transformation mechanic where players start vulnerable and gain power through upgrades, exploring non-linear levels filled with cybernetic threats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmo Police Galivan (Japan) [En by Jair v1.0]', '1989', NaN, 'Nichibutsu', '1', NaN, 'Action platformer and RPG hybrid.', 'Battle through robotic enemies to recover your suit and stop the Mado organization.', 'The English version of the classic sci-fi action-RPG Cosmo Police Galivan.', 'This version brings the complex Metroidvania style exploration and upgrade systems of Galivan to English-speaking fans of 8-bit science fiction adventures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cosmos Cop (Asia) (Unl)', '1991', NaN, 'Nichibutsu', '1', NaN, 'Behind-the-back pseudo-3D shooter.', 'Pilot a combat craft through futuristic corridors to eliminate enemy forces.', 'A rare unlicensed 3D-style shooter featuring fast-paced aerial combat.', 'Similar to Space Harrier, Cosmos Cop challenges players with high-speed dodging and shooting as they navigate through colorful, scrolling environments on the NES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cowboy Kid (USA)', '1991', NaN, 'Nichibutsu', '1', NaN, 'Action-adventure and RPG hybrid.', 'Travel through the Old West to defeat outlaws and save the town.', 'A charming and open-ended Western adventure with co-op support.', 'Cowboy Kid (Western Kids in Japan) is a cult classic that combines town exploration, mini-games, and side-scrolling combat, all set in a vibrant cartoon version of the American frontier.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crackout (Europe)', '1991', NaN, 'Unlicensed', '1', NaN, 'Arcade brick-breaking action.', 'Clear all blocks on the screen using a paddle and a bouncing ball.', 'A polished and colorful 8-bit evolution of the classic Breakout genre.', 'Crackout adds unique twists to the genre, including enemies that interfere with the ball and various power-ups that change the paddle''s size or firepower across dozens of levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crackout (USA) (Proto)', '1991', NaN, 'Unlicensed', '1', NaN, 'Arcade brick-breaking action.', 'Clear all blocks on the screen using a paddle and a bouncing ball.', 'An unreleased prototype of the brick-breaking classic for the North American market.', 'This prototype offers a look at the planned but canceled US release, featuring the same addictive mechanics and challenging block layouts as the European version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crash ''n the Boys - Street Challenge (USA)', '1989', NaN, 'Rare', '1', NaN, 'Sports-themed mini-game competition.', 'Compete in various street events to earn medals and defeat rival teams.', 'A wacky and aggressive take on track and field from the Kunio-kun series.', 'Part of the River City Ransom universe, this game features events like Roof Top Jumping and Fighting Swimming, emphasizing combat and dirty tricks to win the gold.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crayon Shin-Chan - Ora to Poi Poi (Japan)', '1987', NaN, 'Jaleco', '1', NaN, 'Tile-matching puzzle game.', 'Match objects and clear the board to help Shin-Chan in various mini-games.', 'A colorful and humorous puzzle game based on the hit Crayon Shin-Chan anime.', 'Featuring the iconic art style of the show, this title offers several puzzle modes and comedic intermissions, perfect for fans of the series and competitive tile-matching.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crazy Climber (Japan)', '1987', NaN, 'Jaleco', '1', NaN, 'Vertical climbing arcade simulation.', 'Scale massive skyscrapers while avoiding falling objects and obstacles.', 'A unique arcade port where you must navigate the outside of high-rise buildings.', 'Using a specialized control scheme, players must time their movements to avoid closing windows, angry birds, and falling debris to reach the rooftop of each level.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crazy Otto - NES Edition', '1992', NaN, 'Technos Japan', '2', NaN, 'Maze-based arcade action.', 'Eat all the dots in the maze while avoiding colorful ghosts.', 'A homebrew tribute to the original Crazy Otto (the precursor to Ms. Pac-Man).', 'This NES edition brings the legendary maze gameplay to life with vibrant 8-bit colors and the classic high-score chasing mechanics that defined the early arcade era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Creatom (Unl)', '1993', NaN, 'Bandai', '1', NaN, 'Puzzle and logic game.', 'Manipulate atoms and molecules to solve complex chemistry-based puzzles.', 'A rare unlicensed educational puzzle game focused on logic and science.', 'Creatom challenges players to think several steps ahead, moving pieces on a grid to match specific molecular structures in this unique and difficult 8-bit brain teaser.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crime Busters (Unl)', '1980', NaN, 'Nichibutsu', '1', NaN, 'Light gun shooter.', 'Take down criminals and clear the city of gang activity using your Zapper.', 'A fast-paced unlicensed light gun game featuring urban crime themes.', 'Similar to Hogan''s Alley, Crime Busters puts your reflexes to the test as you shoot targets while avoiding innocent civilians across various gritty 8-bit backdrops.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crisis Force (Japan)', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Vertical-scrolling shoot ''em up.', 'Pilot a transforming starship to destroy an ancient evil fleet.', 'A technical masterpiece and one of the best-looking shooters on the Famicom.', 'Developed by Konami, Crisis Force features high-speed action, amazing parallax scrolling, and a unique mechanic that allows players to change ship formations for different fire patterns.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crisis Force (Japan) [En by Stardust Crusaders v1.0]', 'Unk', NaN, 'Unlicensed', '1', NaN, 'Vertical-scrolling shoot ''em up.', 'Pilot a transforming starship to destroy an ancient evil fleet.', 'The English translation of Konami''s legendary 8-bit shooter Crisis Force.', 'This translation makes the story and options menus accessible, allowing players to fully enjoy one of the most technologically advanced shooters ever made for the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cross Fire (Japan)', 'Unk', NaN, 'Unlicensed', '1', NaN, 'Side-scrolling run and gun action.', 'Infiltrate enemy bases and destroy the ultimate weapon to save the world.', 'A gritty military action game with intense platforming and combat.', 'Known for its difficulty and cinematic cutscenes, Cross Fire puts players in the role of a special forces soldier using multiple weapons to clear enemy-filled levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cross Fire (Japan) [Text Hack by Stardust Crusaders v1.0] (English Fix)', '1991', NaN, 'Konami', '1', NaN, 'Side-scrolling run and gun action.', 'Infiltrate enemy bases and destroy the ultimate weapon to save the world.', 'An English-patched version of the Japanese action classic Cross Fire.', 'This version fixes text errors and translates the mission briefings, providing a smoother narrative experience for this challenging 8-bit military shooter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cross Fire (USA) (Proto)', '1991', NaN, 'Konami', '1', NaN, 'Side-scrolling run and gun action.', 'Infiltrate enemy bases and destroy the ultimate weapon to save the world.', 'An unreleased US prototype of the military action game Cross Fire.', 'This version showcases the localized version that was never officially released, featuring the same high-intensity combat and challenging 8-bit level design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crystal Mines (USA) (Unl)', '1990', NaN, 'Konami', '1', NaN, 'Grid-based puzzle and mining game.', 'Collect crystals and find the exit while managing rocks and explosives.', 'A strategic puzzle game where mining meets 8-bit logic and reflexes.', 'Similar to Boulder Dash, Crystal Mines tasks players with navigating hazardous underground caves, using bombs strategically to clear paths without getting trapped.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crystalis (USA)', '1990', NaN, 'Konami', '1', NaN, 'Action-RPG with exploration and magic.', 'Gather four elemental swords to defeat the Draygonian Empire and save the world.', 'One of the most beloved and deepest Action-RPGs in the NES library.', 'Set in a post-apocalyptic world, Crystalis features fluid real-time combat, a deep magic system, and a sprawling world to explore, often compared favorably to the Zelda series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Crystalis (USA) (Beta)', '1990', NaN, 'Konami', '1', NaN, 'Action-RPG with exploration and magic.', 'Gather four elemental swords to defeat the Draygonian Empire and save the world.', 'An early prototype of the masterpiece Crystalis with minor gameplay differences.', 'This beta offers a look at the game''s development process, featuring the same epic story and mechanics with slight variations in text or item placement.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cutman''s Bad Scizzors Day', '1990', NaN, 'Nintendo', '1', NaN, 'Side-scrolling action platformer (Hack).', 'Navigate difficult levels as Cutman to defeat the other Robot Masters.', 'A creative Mega Man hack where you play as the iconic boss, Cutman.', 'This total conversion changes the protagonist and level layouts, offering a fresh and much more difficult challenge for fans of the original Mega Man series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cyberball (USA)', '1990', NaN, 'Nintendo', '1', NaN, 'Futuristic sports simulation.', 'Win high-stakes football games using robotic players and explosive balls.', 'A unique 8-bit take on American football with robots and strategic depth.', 'In Cyberball, the ball heats up and can explode if not moved quickly. Players must manage their robot team''s durability and choose the right plays to outscore the opposition.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cybernoid - The Fighting Machine (USA)', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling space exploration and shooter.', 'Navigate a complex ship through hazardous tunnels to recover stolen treasure.', 'A highly difficult and strategic shooter known for its puzzle-like level design.', 'Cybernoid requires precision flying and careful use of limited sub-weapons. Each screen is a deadly trap filled with enemies and environmental hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Cycle Race - Road Man (Japan)', '1990', NaN, 'Tengen', '2', NaN, 'Sports-themed bicycle racing simulation.', 'Manage your stamina and speed to win the ultimate road bike championship.', 'A unique and realistic take on competitive cycling for the Famicom.', 'Players must balance the physical output of their racer with strategic positioning in the pack, managing energy levels across various long-distance stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dai Meiro - Meikyuu no Tatsujin (Japan)', '1988', NaN, 'Hewson', '1', NaN, 'First-person dungeon crawler / maze.', 'Navigate through complex 3D labyrinths to find the exit before time runs out.', 'A challenging first-person maze exploration game that tests your sense of direction.', 'Dai Meiro (Great Maze) puts players in a 3D perspective, tasking them with mapping out intricate corridors and avoiding traps to master the labyrinth in this unique 8-bit experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dai Meiro - Meikyuu no Tatsujin (Japan) [En by Filler+KingMike v1.0] (~Great Maze - Master of the Maze)', '1989', NaN, 'Hewson', '1', NaN, 'First-person dungeon crawler / maze.', 'Navigate through complex 3D labyrinths to find the exit before time runs out.', 'The English translation of the 3D dungeon exploration game Dai Meiro.', 'This fan translation makes the menus and navigation cues of Great Maze accessible, allowing players to fully enjoy the strategic challenge of solving these 8-bit first-person labyrinths.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dai-2-Ji - Super Robot Taisen (Japan)', '1988', NaN, 'Irem', '1', NaN, 'Tactical Turn-based RPG.', 'Command a team of iconic mechs to defeat enemy forces in strategic combat.', 'The legendary second entry in the Super Robot Wars series featuring famous anime mechs.', 'This title laid the groundwork for the franchise, combining tactical grid-based movement with cinematic battle animations featuring robots from Gundam, Mazinger Z, and more.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Daikaijuu Deburas (Japan)', '1986', NaN, 'Konami', '1', NaN, 'Turn-based strategy / Monster sim.', 'Defend the city from giant monsters (Kaiju) using military units and tactics.', 'A unique 8-bit strategy game focused on giant monster battles and city defense.', 'Players must strategically deploy tanks, jets, and specialized weapons to halt the path of destruction caused by massive Kaiju, blending military simulation with classic monster movie vibes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Daikoukai Jidai (Japan)', '1986', NaN, 'Konami', '1', NaN, 'Naval exploration and trading RPG.', 'Build a fleet, discover new lands, and amass wealth through global trade.', 'The original Famicom version of the epic seafaring adventure, Uncharted Waters.', 'Set during the Age of Discovery, this game offers a massive open world where players must manage crew morale, ship supplies, and market prices to become the king of the seas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Daiku no Gen San (Japan)', '1991', NaN, 'Banpresto', '1', NaN, 'Side-scrolling action platformer.', 'Use your hammer to defeat construction rivals and save the neighborhood.', 'A high-energy action game starring the famous Hammerin'' Harry.', 'Players control Gen-san, a heroic carpenter, in a quest to stop a corrupt construction company. The game is known for its fast-paced combat and creative use of hammer power-ups.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Daiku no Gen San 2 - Akage no Dan no Gyakushuu (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer.', 'Defeat Dan and his gang using your powerful hammer skills.', 'The vibrant sequel to Hammerin'' Harry with more levels and improved graphics.', 'Gen-san returns for more 8-bit action, featuring smoother animations and larger bosses. Players must master timing and hammer strikes to clear through challenging urban environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Daisenryaku (Japan)', '1988', NaN, 'SystemSoft', '1', NaN, 'Hex-based military strategy.', 'Outmaneuver enemy armies and capture bases in modern warfare scenarios.', 'A deep and realistic turn-based war simulator for strategy enthusiasts.', 'Daisenryaku is a cornerstone of the strategy genre, offering complex unit management (tanks, planes, infantry) across varied terrain to achieve military dominance on the map.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Daisenryaku (Japan) [En by Aeon Genesis v1.0]', '1988', NaN, 'SystemSoft', '1', NaN, 'Hex-based military strategy.', 'Outmaneuver enemy armies and capture bases in modern warfare scenarios.', 'The English translation of the legendary military strategy game Daisenryaku.', 'This version translates the deep tactical menus and unit stats of Daisenryaku, making one of the most complex Famicom strategy titles playable for English speakers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Daiva - Imperial of Nirsartia (Japan)', '1991', NaN, 'Telenet Japan', '1', NaN, 'Action and strategy hybrid.', 'Conquer planetary systems through fleet management and side-scrolling combat.', 'An ambitious sci-fi epic that blends space strategy with 8-bit action levels.', 'Daiva features a dual-gameplay loop: players manage ship deployments on a galactic map and then pilot a mech in side-scrolling segments to secure planetary targets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dance Aerobics (USA)', '1989', NaN, 'Human Entertainment', '2', NaN, 'Rhythm and fitness simulation.', 'Follow the instructor''s moves on the Power Pad to complete aerobic routines.', 'An early fitness game that utilizes the NES Power Pad for a full-body workout.', 'Using the Power Pad peripheral, players must step on the correct buttons in rhythm with the music, mimicking the movements of an on-screen instructor in this retro fitness classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Danny Sullivan''s Indy Heat (USA)', '1992', NaN, 'Leland', '2', NaN, 'Top-down arcade racing.', 'Win Indy-style races to earn money and upgrade your car''s performance.', 'A fast-paced arcade racer featuring pit stops and high-speed competition.', 'Known for its tight controls and four-player support, Indy Heat challenges players to manage fuel and tire wear in a series of intense, high-speed tracks across the globe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dark Lord (Japan)', '1991', NaN, 'Data East', '1', NaN, 'Tactical RPG / Dungeon crawler.', 'Assemble a party of heroes to defeat ancient evils and explore dark dungeons.', 'A sophisticated late-release Famicom RPG with high-quality 8-bit graphics.', 'Dark Lord features a non-linear quest structure and a deep tactical combat system, allowing players to customize their party and choose their path through a dark fantasy world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dark Lord (Japan) [En by Aeon Genesis v1.0]', '1991', NaN, 'Data East', '1', NaN, 'Tactical RPG / Dungeon crawler.', 'Assemble a party of heroes to defeat ancient evils and explore dark dungeons.', 'The English translation of the deep and dark fantasy RPG, Dark Lord.', 'This fan translation opens up the complex world-building and strategic combat of Dark Lord, making it a must-play for fans of 8-bit tactical role-playing games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Darkman (USA)', '1991', NaN, 'Ocean', '1', NaN, 'Side-scrolling action / platformer.', 'Use disguises and combat skills to take revenge on the crime syndicate.', 'A gritty movie-based action game featuring a unique mask mechanic.', 'Based on the Sam Raimi film, players control Peyton Westlake, battling through levels and taking photos of enemies to create masks that allow them to infiltrate various stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Darkwing Duck (Europe)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action platformer.', 'Stop the organization F.O.W.L. and defeat the evil Steelbeak.', 'A top-tier Capcom platformer featuring the iconic Terror that flaps in the night.', 'Using the Mega Man engine, Darkwing Duck offers precise shooting and platforming. Players use a gas gun with different ammo types to clear levels inspired by the hit Disney show.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Darkwing Duck (Germany)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action platformer.', 'Stop the organization F.O.W.L. and defeat the evil Steelbeak.', 'A top-tier Capcom platformer featuring the iconic Terror that flaps in the night.', 'Using the Mega Man engine, Darkwing Duck offers precise shooting and platforming. Players use a gas gun with different ammo types to clear levels inspired by the hit Disney show.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Darkwing Duck (USA)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action platformer.', 'Stop the organization F.O.W.L. and defeat the evil Steelbeak.', 'A top-tier Capcom platformer featuring the iconic Terror that flaps in the night.', 'Using the Mega Man engine, Darkwing Duck offers precise shooting and platforming. Players use a gas gun with different ammo types to clear levels inspired by the hit Disney show.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Darkwing Duck (USA) (Beta)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action platformer.', 'Stop the organization F.O.W.L. and defeat the evil Steelbeak.', 'A prototype version of the Capcom classic with minor differences in levels.', 'This beta offers a look at the game''s development, featuring the same high-quality Disney platforming action with potential variations in enemy placement or items.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Darkwing Duck 2 (U) Beta', '1993', NaN, 'Capcom', '1', NaN, 'Side-scrolling action platformer.', 'Explore unreleased content in this mysterious prototype sequel.', 'A rare beta version often associated with unlicensed or unreleased follow-ups.', 'This title is a curiosity in the NES library, often a hack or a very early prototype that attempts to expand on the legendary Capcom platforming mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Darkwing Duck Advance', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling action platformer (Hack).', 'Navigate enhanced or modified levels as the caped mallard.', 'A gameplay-focused hack designed to modernize the original Darkwing Duck.', 'This version often features tweaked physics or modified level layouts, intended to give the classic 8-bit game a more modern or Advanced difficulty feel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dash Galaxy in the Alien Asylum (USA)', '1989', NaN, 'Beam Software', '1', NaN, 'Puzzle-platformer / Action.', 'Navigate a series of hazardous rooms in an alien asylum to find the exit.', 'A challenging blend of top-down exploration and side-scrolling platforming.', 'As Dash Galaxy, players must solve environmental puzzles and avoid deadly alien traps across numerous floors in this sci-fi adventure that rewards careful planning.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dash Yarou (Japan)', '1991', NaN, 'Visco', '1', NaN, 'Top-down arcade racing.', 'Race through various tracks and avoid obstacles to reach the finish line.', 'An early Famicom racer with simple controls and addictive high-speed action.', 'Known as Deadly Towers in some circles (incorrectly), Dash Yarou is a pure racing game that focuses on lane-changing and speed management to beat the clock.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Datach - Battle Rush - Build Up Robot Tournament (Japan)', '1992', NaN, 'Bandai', '2', NaN, 'Robot combat / Tournament.', 'Customize and battle robots in a tournament using the Datach peripheral.', 'A unique 8-bit robot fighter designed for the barcode-reading Datach system.', 'Part of the Datach series, this game allowed players to scan barcodes to generate robot stats, battling them in a competitive 8-bit arena.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Datach - Crayon Shin Chan - Ora to Poi Poi (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Puzzle / Mini-games.', 'Complete various Shin-Chan themed challenges using the Datach reader.', 'A barcode-integrated puzzle game based on the Crayon Shin-Chan series.', 'This version of Shin-Chan uses the specialized Datach hardware to unlock content or characters via barcodes, adding a physical collectible element to the 8-bit gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Datach - Dragon Ball Z - Gekitou Tenkaichi Budou Kai (Japan)', '1992', NaN, 'Bandai', '2', NaN, '2D Fighting game with barcode integration.', 'Win the World Martial Arts Tournament using scanned character stats.', 'A unique Dragon Ball Z fighter where barcodes determine your power levels.', 'Part of the Datach system, this title lets fans scan barcodes to summon fighters. It features iconic DBZ characters and fast-paced 8-bit combat centered around the legendary Tenkaichi Budou Kai tournament.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Datach - J League Super Top Players (Japan)', '1992', NaN, 'Bandai', '2', NaN, 'Soccer simulation and card management.', 'Lead your J-League team to the championship using scanned player data.', 'A barcode-driven soccer game featuring real Japanese league players.', 'This sports title utilizes the Datach joint to scan real-world cards, allowing players to build a custom roster of J-League stars and compete in strategic 11-on-11 soccer matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Datach - SD Gundam - Gundam Wars (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Tactical strategy and robot combat.', 'Command a squad of SD Gundams to defeat enemy forces in space and land.', 'A strategic Gundam war game where units are unlocked via barcode scanning.', 'Gundam Wars combines tactical map movement with individual 8-bit combat encounters. Players use the Datach reader to strengthen their fleet and deploy iconic mobile suits from the Gundam universe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Datach - Ultraman Club - Supokon Fight! (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Sports-themed action / Mini-games.', 'Compete in various physical challenges to prove Ultraman''s strength.', 'A competitive sports collection featuring the legendary Ultraman characters.', 'This Datach entry focuses on Supokon (sports spirit), where players scan codes to improve their stats in various athletic mini-games, blending Tokusatsu action with competitive sports mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Datach - Yuu Yuu Hakusho - Bakutou Ankoku Bujutsu Kai (Japan)', '1992', NaN, 'Bandai', '2', NaN, '2D Fighting game with RPG elements.', 'Defeat the demons of the Dark Tournament through strategic combat.', 'A cinematic fighter based on the hit Yuu Yuu Hakusho anime series.', 'Players use the Datach reader to influence the battle power of Yusuke and his friends. The game recreates the intense Dark Tournament arc with large sprites and anime-inspired special moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Datsugoku (Japan)', '1985', NaN, 'Data East', '1', NaN, 'Side-scrolling beat ''em up.', 'Escape from a high-security prison by fighting waves of guards and soldiers.', 'A gritty 8-bit brawler known in the West as POW: Prisoners of War.', 'Control a soldier fighting his way out of enemy territory. The game features various weapons like knives and guns, offering a tough military combat experience with a dark, urban aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Day Dreamin'' Davey (USA)', '1992', NaN, 'Rare', '1', NaN, 'Action-adventure with multiple time periods.', 'Navigate through Davey''s daydreams to defeat historical and fantasy bosses.', 'A unique adventure where a boy''s imagination takes him to different eras.', 'As Davey, players explore ancient Greece, the Middle Ages, and the Wild West. Each dream features different weapons and mechanics, blending top-down exploration with side-scrolling action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Days of Thunder (Europe)', '1990', NaN, 'Mindscape', '1', NaN, 'Behind-the-car racing simulation.', 'Master the oval tracks to win the NASCAR championship.', 'A high-speed racing game based on the Tom Cruise movie.', 'Days of Thunder focuses on strategy and pit management. Players must manage fuel, tire wear, and car damage while competing at high speeds against a full pack of aggressive stock car racers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Days of Thunder (USA)', '1990', NaN, 'Mindscape', '1', NaN, 'Behind-the-car racing simulation.', 'Master the oval tracks to win the NASCAR championship.', 'A high-speed racing game based on the Tom Cruise movie.', 'Days of Thunder focuses on strategy and pit management. Players must manage fuel, tire wear, and car damage while competing at high speeds against a full pack of aggressive stock car racers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deadly Towers (USA)', '1987', NaN, 'Irem', '1', NaN, 'Top-down action RPG / Dungeon crawler.', 'Explore seven towers to find and destroy the bells of evil.', 'A notoriously difficult and sprawling 8-bit fantasy adventure.', 'As Prince Myer, players must navigate a massive world filled with hidden portals and difficult enemies. It is known for its steep challenge curve and non-linear exploration of a dark fantasy kingdom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deadpool', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling action platformer (Hack/Homebrew).', 'Fight through levels as the Merc with a Mouth to defeat various villains.', 'A modern fan-made hack featuring the popular Marvel character Deadpool.', 'This modification of Ninja Gaiden (or similar) replaces the protagonist with Deadpool, adding his signature look and weapons to create a fast-paced, high-difficulty superhero experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Death Race (USA) (Unl)', '1983', NaN, 'Exidy', '1', NaN, 'Top-down vehicular combat and racing.', 'Drive through post-apocalyptic tracks and destroy rivals to win the race.', 'A violent and gritty unlicensed racer inspired by the cult classic movie.', 'Published by American Video Entertainment, Death Race challenges players to race through dangerous circuits while using car-mounted weapons to take down opponents and obstacles in a race for survival.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deathbots (USA) (Unl)', '1990', NaN, 'Homebrew', '1', NaN, 'Isometric action shooter.', 'Infiltrate a robotic facility and destroy the central computer core.', 'A futuristic shooter featuring maze-like levels and robotic enemies.', 'Control a powerful combat droid as you navigate through complex floors filled with traps and hostile bots. The game requires careful movement and precise shooting to survive the mechanical gauntlet.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deathbots (USA) (Unl) (v1)', '1990', NaN, 'Homebrew', '1', NaN, 'Isometric action shooter.', 'Infiltrate a robotic facility and destroy the central computer core.', 'A futuristic shooter featuring maze-like levels and robotic enemies.', 'This initial version of the unlicensed title offers the same challenging isometric combat as the player fights through a sci-fi fortress to disable a rogue AI.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deblock (Japan)', '1991', NaN, 'Athena', '1', NaN, 'Falling-block puzzle game.', 'Match shapes and clear lines to prevent the screen from filling up.', 'A unique 8-bit puzzle game that tests spatial awareness and speed.', 'Deblock offers a fresh take on the puzzle genre, requiring players to manipulate blocks in a way that differs from Tetris, focusing on completing specific patterns to advance stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Decathlon (Asia) (Unl)', '1988', NaN, 'Unlicensed', '1', NaN, 'Sports simulation / Button masher.', 'Compete in ten different track and field events to win the gold medal.', 'An unlicensed take on the classic Olympic decathlon experience.', 'Featuring events like the 100m dash, long jump, and javelin throw, this game requires rapid button pressing and precise timing to break world records and achieve the highest total score.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deep Dungeon 3 - Yuushi heno Tabi (Japan)', '1990', NaN, 'HummingBird Soft', '1', NaN, 'First-person dungeon crawler RPG.', 'Navigate deep labyrinths to defeat an ancient evil and find treasure.', 'A classic 3D-style dungeon RPG with turn-based combat and exploration.', 'As the third entry in the series, it refines the first-person exploration of hazardous caves and dungeons, featuring a party system and challenging 8-bit monster encounters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deep Dungeon 4 - Kuro no Youjutsushi (Japan)', '1992', NaN, 'HummingBird Soft', '1', NaN, 'First-person dungeon crawler RPG.', 'Stop the black sorcerer by exploring a massive 3D labyrinth.', 'The final Famicom entry in the legendary Deep Dungeon series.', 'Featuring improved graphics and deeper RPG mechanics, players must manage a group of adventurers as they map out a complex world filled with traps, puzzles, and powerful magic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deep Dungeon 4 - Kuro no Youjutsushi (Japan) [En by Dragoon-X v1.0] [Mapper Fix by Spinner 8] (~Deep Dungeon 4 - The Black Sorcerer)', '1992', NaN, 'HummingBird Soft', '1', NaN, 'First-person dungeon crawler RPG.', 'Stop the black sorcerer by exploring a massive 3D labyrinth.', 'The fan-translated English version of the deep RPG The Black Sorcerer.', 'This translation opens up the complex narrative and spell systems of the final Deep Dungeon title, making this classic first-person dungeon crawler accessible to English speakers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Defender II (USA)', '1989', NaN, 'Atari Games', '1', NaN, 'Side-scrolling space shooter.', 'Protect human survivors from alien abductors in a high-speed starship.', 'A classic arcade sequel featuring intense shooting and Stargate warping.', 'Also known as Stargate, this game requires players to manage a radar and fly at high speeds to rescue humans before they are transformed into mutants by the alien invasion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Defender of the Crown (Europe)', '1988', NaN, 'Cinemaware', '1', NaN, 'Medieval strategy and action hybrid.', 'Unify England by conquering territories and winning tournaments.', 'A visually stunning strategy game set in the age of knights and castles.', 'Players choose a Saxon lord and engage in a mix of army management, jousting mini-games, and castle sieges to drive out the Normans and claim the throne.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Defender of the Crown (France)', '1988', NaN, 'Cinemaware', '1', NaN, 'Medieval strategy and action hybrid.', 'Unify England by conquering territories and winning tournaments.', 'La version française du jeu de stratégie médiévale classique.', 'This French localized version offers the same deep strategic experience, allowing players to manage land and compete in tournaments in their native language.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Defender of the Crown (USA)', '1989', NaN, 'Cinemaware', '1', NaN, 'Medieval strategy and action hybrid.', 'Unify England by conquering territories and winning tournaments.', 'A visually stunning strategy game set in the age of knights and castles.', 'Players choose a Saxon lord and engage in a mix of army management, jousting mini-games, and castle sieges to drive out the Normans and claim the throne.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Defenders of Dynatron City (USA)', '1992', NaN, 'LucasArts', '1', NaN, 'Side-scrolling action platformer.', 'Use a team of quirky superheroes to save the city from Dr. Mayhem.', 'A unique superhero game featuring a cast of bizarre characters.', 'Based on an animated pilot, players can switch between heroes like Jet Girl and Monkey-Man, each with distinct powers, to fight through urban stages and stop a mutant invasion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deja Vu (Japan)', '1988', NaN, 'Icom Simulations', '1', NaN, 'Point-and-click adventure.', 'Solve a murder mystery and clear your name before the police catch you.', 'A classic film noir mystery where you play a detective with amnesia.', 'Set in 1941, Deja Vu is a pioneering adventure game. Players must search for clues, manage an inventory, and interact with the environment to piece together their forgotten past in a dangerous city.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deja Vu (Sweden)', '1988', NaN, 'Icom Simulations', '1', NaN, 'Point-and-click adventure.', 'Solve a murder mystery and clear your name before the police catch you.', 'En svensk version av det klassiska detektivspelet i noir-stil.', 'This Swedish localized version brings the intense 8-bit detective experience to Scandinavia, featuring the same deep puzzle-solving and atmospheric storytelling as the original release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Deja Vu (USA)', '1988', NaN, 'Icom Simulations', '1', NaN, 'Point-and-click adventure.', 'Solve a murder mystery and clear your name before the police catch you.', 'A classic film noir mystery where you play a detective with amnesia.', 'Set in 1941, Deja Vu is a pioneering adventure game. Players must search for clues, manage an inventory, and interact with the environment to piece together their forgotten past in a dangerous city.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Demon Sword - Release the Power (USA)', '1989', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer.', 'Rebuild a powerful magical sword to defeat the dark forces of the underworld.', 'A fast-paced fantasy action game featuring massive jumps and sword combat.', 'Players control a warrior on a quest to recover blade fragments. The game is known for its high-flying acrobatics, impressive boss battles, and power-ups that increase the sword''s length and power.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dengeki - Big Bang! (Japan)', '1990', NaN, 'Kaneko', '1', NaN, 'Side-scrolling action platformer.', 'Use your energy blasts to navigate levels and defeat a robotic army.', 'A visually striking action game known in the West as Clash at Demonhead.', 'This original Japanese version features the same non-linear exploration and quirky anime style, where players use different suits and gadgets to progress through a massive interconnected map.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Densetsu no Kishi - Elrond (Japan)', '1990', NaN, 'TOSE', '1', NaN, 'Side-scrolling action RPG.', 'Journey through a fantasy world to defeat the evil sorcerer and save the land.', 'An early Famicom RPG-lite experience known in the West as Wizards & Warriors.', 'Players control Kuros, a knight who explores forests and caves, collecting gems and upgrades. It features iconic 8-bit platforming and challenging boss encounters in a dark fantasy setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Derby Stallion - Zenkoku Ban (Japan)', '1991', NaN, 'ASCII', '1', NaN, 'Horse racing and breeding simulation.', 'Breed, train, and race horses to become the top stable owner in Japan.', 'A deep and realistic horse racing management simulator for the Famicom.', 'Derby Stallion focuses on the strategic side of racing. Players must manage bloodlines, training schedules, and betting strategies to build a winning legacy in the competitive world of horse racing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Desert Commander (USA)', '1988', NaN, 'Kemco', '1', NaN, 'Turn-based military strategy.', 'Deploy tanks, planes, and infantry to capture the enemy''s headquarters.', 'A tactical desert warfare simulator with a focus on unit management.', 'Set in North Africa during WWII, Desert Commander provides a grid-based strategy experience where terrain, fuel, and unit strengths must be carefully balanced to achieve military victory.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Destination Earthstar (USA)', '1990', NaN, 'Jaleco', '1', NaN, 'First-person space combat and side-scrolling.', 'Pilot a starship through enemy territory to reach Earth and stop an invasion.', 'A dual-genre sci-fi adventure blending cockpit combat with platforming.', 'Destination Earthstar switches between first-person space flight and side-scrolling planetary missions, requiring players to master both flight simulation and traditional 8-bit action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Destiny of an Emperor (USA)', '1989', NaN, 'Capcom', '1', NaN, 'Turn-based RPG with tactical elements.', 'Recruit generals and lead an army to unify ancient China.', 'An epic historical RPG based on the Three Kingdoms era and the Tenchi wo Kurau manga.', 'Unlike traditional RPGs, this game focuses on large-scale army battles where HP is represented by the number of soldiers. Players can recruit over 150 unique generals in their quest for conquest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Devil Man (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Side-scrolling action-adventure.', 'Battle demons and protect humanity by transforming into the powerful Devilman.', 'A dark and gritty action game based on Go Nagai''s legendary manga series.', 'Devil Man blends exploration and combat, staying faithful to the series'' violent and tragic tone. Players must navigate urban and demonic realms to stop the coming apocalypse.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Devil Man (Japan) [En by Snark v1.0]', '1989', NaN, 'Namco', '1', NaN, 'Side-scrolling action-adventure.', 'Battle demons and protect humanity by transforming into the powerful Devilman.', 'The English translation of the dark and intense Devilman action game.', 'This version allows English speakers to experience the story of Akira Fudo. The translation clarifies the game''s objectives and dialogue, making this cult classic fully accessible.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Devil World (Europe)', '1984', NaN, 'Nintendo', '2', NaN, 'Single-screen maze puzzle.', 'Collect items and move crosses to defeat the Devil while the screen scrolls.', 'A unique Nintendo-developed puzzle game produced by Shigeru Miyamoto.', 'Playing as Tamagon, players must navigate mazes while the Devil moves the screen in different directions. It is famous for its creative mechanics and religious-themed imagery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Devil World (Japan)', '1984', NaN, 'Nintendo', '2', NaN, 'Single-screen maze puzzle.', 'Collect items and move crosses to defeat the Devil while the screen scrolls.', 'A unique Nintendo-developed puzzle game produced by Shigeru Miyamoto.', 'Playing as Tamagon, players must navigate mazes while the Devil moves the screen in different directions. It is famous for its creative mechanics and religious-themed imagery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Devil World (Japan) (Rev A)', '1984', NaN, 'Nintendo', '2', NaN, 'Single-screen maze puzzle.', 'Collect items and move crosses to defeat the Devil while the screen scrolls.', 'A revised version of the classic Miyamoto-produced puzzle game.', 'This revision offers the same addictive maze gameplay as the original, featuring small technical tweaks to ensure smooth performance on the Famicom hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dezaemon (Japan)', '1991', NaN, 'Hudson Soft', '1', NaN, 'Shoot ''em up (Shmup) and game creator.', 'Design your own levels, enemies, and music, or play the built-in shooter.', 'A revolutionary shooter construction kit for the 8-bit Famicom.', 'Dezaemon allows players to unleash their creativity by building a complete shoot ''em up from scratch. It features a robust suite of editing tools for graphics, patterns, and sound.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dezaemon (Japan) [En by Aeon Genesis v1.1]', '1991', NaN, 'Hudson Soft', '1', NaN, 'Shoot ''em up (Shmup) and game creator.', 'Design your own levels, enemies, and music, or play the built-in shooter.', 'The English translation of the groundbreaking Dezaemon game creator.', 'This translation is essential for using the complex editing tools, allowing English-speaking creators to design and share their own 8-bit shooting masterpieces.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Diablo (C)', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Action RPG (Pirate/Port).', 'Descend into the cathedral to defeat Diablo, the Lord of Terror.', 'A notorious 8-bit unlicensed port of the legendary Blizzard PC game.', 'This impressive bootleg attempts to replicate the dark atmosphere and isometric RPG mechanics of Diablo on the NES, featuring simplified looting and combat systems.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dick Tracy (USA)', '1990', NaN, 'Capcom', '1', NaN, 'Action-adventure with side-scrolling and driving.', 'Solve crimes and arrest notorious gangsters to clean up the city.', 'A detective action game based on the iconic comic strip and film.', 'Players must search for clues, engage in shootouts, and drive through the city streets. The game emphasizes police work, requiring players to gather enough evidence before making an arrest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Die Hard (Europe)', '1989', NaN, 'Activision', '1', NaN, 'Top-down action-adventure.', 'Rescue hostages and defeat terrorists in the Nakatomi Plaza.', 'A high-stakes action game based on the legendary Bruce Willis movie.', 'Die Hard features a unique real-time countdown and a top-down perspective. Players must explore the building''s floors, manage health, and take down Gruber''s men before time runs out.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Die Hard (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Top-down action-adventure.', 'Rescue hostages and defeat terrorists in the Nakatomi Plaza.', 'A high-stakes action game based on the legendary Bruce Willis movie.', 'Die Hard features a unique real-time countdown and a top-down perspective. Players must explore the building''s floors, manage health, and take down Gruber''s men before time runs out.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Die Hard (USA)', '1989', NaN, 'Activision', '1', NaN, 'Top-down action-adventure.', 'Rescue hostages and defeat terrorists in the Nakatomi Plaza.', 'A high-stakes action game based on the legendary Bruce Willis movie.', 'Die Hard features a unique real-time countdown and a top-down perspective. Players must explore the building''s floors, manage health, and take down Gruber''s men before time runs out.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dig Dug (Japan)', '1985', NaN, 'Namco', '2', NaN, 'Single-screen maze / Action.', 'Eliminate all underground monsters by inflating them or dropping rocks.', 'A classic arcade hit where you dig tunnels and defeat enemies underground.', 'Dig Dug is a legendary Namco title. Players must navigate through soil, strategicially avoiding the Pookas and Fygars while using their pump to inflate enemies until they pop, or dropping rocks to crush them for extra points.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dig Dug II - Trouble in Paradise (USA)', '1989', NaN, 'Namco', '2', NaN, 'Top-down action / Puzzle.', 'Destroy all enemies by inflating them or sinking parts of the island.', 'A unique sequel that moves the digging action from underground to island surfaces.', 'Unlike the first game, Dig Dug II takes place on islands. Players can use a jackhammer to create faults in the ground, causing entire sections of the land (and the enemies on them) to sink into the ocean.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dig Dug II (Japan)', '1989', NaN, 'Namco', '2', NaN, 'Top-down action / Puzzle.', 'Destroy all enemies by inflating them or sinking parts of the island.', 'The Japanese Famicom version of the strategic island-sinking sequel.', 'Known as Dig Dug II: Old Island in Japan, this version features the same addictive gameplay where positioning and environmental destruction are key to clearing each stage of monsters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Digger T. Rock - The Legend of the Lost City (Europe)', '1990', NaN, 'Milton Bradley', '1', NaN, 'Side-scrolling exploration / Platformer.', 'Navigate through deep caves to find the legendary Lost City before the exit closes.', 'A challenging underground adventure focused on exploration and survival.', 'Developed by Rare, Digger T. Rock tasks players with using shovels, ladders, and explosives to traverse hazardous caverns. It requires careful resource management and quick reflexes to find the exit of each level.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Digger T. Rock - The Legend of the Lost City (USA)', '1990', NaN, 'Milton Bradley', '1', NaN, 'Side-scrolling exploration / Platformer.', 'Navigate through deep caves to find the legendary Lost City before the exit closes.', 'A challenging underground adventure focused on exploration and survival.', 'Developed by Rare, Digger T. Rock tasks players with using shovels, ladders, and explosives to traverse hazardous caverns. It requires careful resource management and quick reflexes to find the exit of each level.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Digital Devil Story - Megami Tensei (Japan)', '1987', NaN, 'Atlus', '1', NaN, 'First-person dungeon crawler RPG.', 'Explore the labyrinth of Galgalim to defeat Lucifer and his demon army.', 'The first entry in the legendary Megami Tensei franchise, blending occult themes and RPG.', 'Based on a sci-fi novel, this game introduced the demon recruitment and fusion system. Players navigate 3D-style corridors, negotiating with monsters to build a powerful party to save humanity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Digital Devil Story - Megami Tensei II (Japan)', '1990', NaN, 'Atlus', '1', NaN, 'First-person dungeon crawler RPG.', 'Navigate a post-apocalyptic Tokyo to defeat demonic forces and survive.', 'A massive 8-bit RPG sequel featuring a dark story and deep demon fusion mechanics.', 'Megami Tensei II expanded the scope of the original with a top-down world map and even more complex demon interactions. It is highly regarded for its mature storytelling and challenging strategic combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Digital Devil Story: Megami Tensei (English)', '1987', NaN, 'Atlus', '1', NaN, 'First-person dungeon crawler RPG.', 'Explore the labyrinth of Galgalim to defeat Lucifer and his demon army.', 'The fan-translated English version of the first Megami Tensei game.', 'This translation allows English-speaking players to experience the birth of the Shin Megami Tensei legacy, making the complex menus and demon negotiations fully understandable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dirty Harry (USA)', '1990', NaN, 'Homebrew', '1', NaN, 'Side-scrolling action / Adventure.', 'Stop the crime wave in San Francisco and take down The Scorpio killer.', 'A gritty action game based on the iconic Clint Eastwood film character.', 'As Inspector Harry Callahan, players must investigate buildings, engage in shootouts, and manage their health across the city. The game features various weapons and the protagonist''s famous .44 Magnum.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doki Doki SMB1 Club - Monika', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling platformer (Hack).', 'Rescue the other club members across the Mushroom Kingdom as Monika.', 'A creative crossover hack of Super Mario Bros. featuring Monika from DDLC.', 'This modification replaces Mario''s sprites and palettes with Monika''s aesthetic. The gameplay remains the classic platformer experience but with a unique visual twist for fans of the visual novel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doki Doki SMB1 Club - Natsuki', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling platformer (Hack).', 'Navigate the classic Super Mario levels using Natsuki''s character sprites.', 'A visual character-swap hack featuring Natsuki in the original Super Mario Bros.', 'Natsuki enters the 8-bit world of Mario in this hack. It features customized colors and character art, bringing the world of Doki Doki Literature Club to a retro platforming setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doki Doki SMB1 Club - Sayori', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling platformer (Hack).', 'Complete the original Mario adventure playing as the cheerful Sayori.', 'A fun visual modification that puts Sayori into the classic NES Mario game.', 'Sayori takes center stage in this character-swap hack. While the level design is the original SMB1, the visual assets are updated to reflect Sayori''s personality and character design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doki Doki SMB1 Club - Yuri', '1989', NaN, 'Namco', '1', NaN, 'Side-scrolling platformer (Hack).', 'Traverse the Mushroom Kingdom as Yuri to save the literature club.', 'A character-swap hack featuring Yuri from DDLC in a classic 8-bit adventure.', 'This version features Yuri as the main protagonist. The hack focuses on visual consistency, using Yuri''s color palette and sprites to replace the traditional Mario assets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doki! Doki! Yuuenchi (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer.', 'Navigate an amusement park and use your soccer ball to defeat enemies and save your girlfriend.', 'A colorful and fun action game set in a dangerous amusement park.', 'Known in the West as The Trolls in Crazyland, this original version stars a young boy. The gameplay revolves around using a ball as a projectile and managing a unique health system that changes as you take damage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doki! Doki! Yuuenchi (Japan) [En by No Talent v1.1] (~Doki! Doki! Amusement Park)', '1987', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer.', 'Navigate an amusement park and use your soccer ball to defeat enemies and save your girlfriend.', 'The English translation of the vibrant Famicom platformer Doki! Doki! Yuuenchi.', 'This fan translation allows players to enjoy the story and mechanics of this hidden Famicom gem, which features impressive graphics and creative level designs based on theme park attractions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dokuganryuu Masamune (Japan)', '1990', NaN, 'Taito', '1', NaN, 'Turn-based strategy / War sim.', 'Unify the northern provinces of Japan during the Sengoku period.', 'A deep historical strategy game focused on the life of Date Masamune.', 'Developed by Namco, this title blends tactical army management with RPG elements. Players must manage resources, negotiate with rivals, and win large-scale 8-bit battles to build their empire.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Don Doko Don (Japan)', '1992', NaN, 'Taito', '1', NaN, 'Single-screen platform-action.', 'Use your hammer to turn enemies into projectiles and clear each stage.', 'A charming and fast-paced arcade port featuring two dwarf carpenters.', 'Very similar in feel to Bubble Bobble, Don Doko Don features Bob and Jim. They must stun enemies with their hammers and throw them into others to clear the screen and reach the boss of each world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Don Doko Don 2 (Japan)', '1988', NaN, 'Sega', '1', NaN, 'Side-scrolling action platformer.', 'Journey through a fantasy kingdom to save the King and Queen.', 'A beautiful and refined platforming sequel with larger, scrolling levels.', 'Unlike the first game, the sequel features scrolling stages and more complex platforming. It is highly praised for its high-quality 8-bit graphics, boss fights, and polished gameplay mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donald Duck (Japan)', '1988', NaN, 'Sega', '1', NaN, 'Side-scrolling action platformer.', 'Explore various levels to rescue Huey, Dewey, and Louie.', 'The Japanese Famicom version of the Disney classic Snoopy''s Silly Sports Spectacular (Visual swap).', 'In Japan, this game used the Donald Duck license. It features various mini-games and platforming sections where players must navigate obstacles in a bright Disney-themed world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donald Land (Japan)', '1983', NaN, 'Nintendo', '2', NaN, 'Side-scrolling action platformer.', 'Rescue Ronald McDonald''s friends from the evil Gumon using explosive apples.', 'A McDonald''s-themed adventure featuring Ronald and his colorful world.', 'Players control Ronald McDonald (Donald in Japan) through several levels based on McDonaldland. The primary mechanic involves throwing bombs to clear enemies and overcome environmental hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong (Japan)', '1983', NaN, 'Nintendo', '2', NaN, 'Single-screen arcade platformer.', 'Climb the construction site to rescue Pauline from the giant ape.', 'A faithful port of the legendary arcade game that introduced Mario.', 'This early Famicom title captures the essence of the original masterpiece. Players must jump over barrels and climb ladders across iconic stages to reach the top and save the damsel in distress.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong (World) (Rev A)', '1984', NaN, 'Nintendo', '2', NaN, 'Single-screen arcade platformer.', 'Climb the construction site to rescue Pauline from the giant ape.', 'The definitive revised version of the classic Donkey Kong arcade port.', 'This revision ensures the most stable performance and accurate 8-bit recreation of the arcade original, featuring the classic three-stage loop that defined the platforming genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong 3 (World)', 'Homebrew', NaN, 'Homebrew', '2', NaN, 'Fixed-screen shooter / platformer.', 'Shoot bug spray at Donkey Kong to push him up while defending your garden.', 'A unique departure from the original series, featuring Stanley the Bugman.', 'Donkey Kong 3 shifts the action to a greenhouse. Players must spray DK to keep him at bay while avoiding swarms of bees and other insects in this fast-paced arcade shooter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong 3 40th Anniversary', 'Homebrew', NaN, 'Homebrew', '2', NaN, 'Fixed-screen shooter (Enhanced).', 'Defend the garden and push DK to the top with improved visuals.', 'A celebratory modern hack of DK3 featuring updated palettes and fixes.', 'This 40th Anniversary edition refreshes the classic gameplay with vibrant colors and technical adjustments to celebrate four decades of Nintendo''s arcade legacy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong 4', '1988', NaN, 'Nintendo', '2', NaN, 'Side-scrolling platformer (Pirate).', 'Navigate difficult levels to rescue the captured Kong family.', 'A notorious unlicensed demake or pirate sequel of the DK series.', 'Often found on multi-carts, this pirate title attempts to create a new adventure using assets from various NES games, offering a curious and challenging unofficial sequel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong 40th Anniversary', 'Homebrew', NaN, 'Homebrew', '2', NaN, 'Single-screen platformer (Enhanced).', 'Climb the girders and rescue Pauline with modernized 8-bit visuals.', 'An anniversary tribute hack of the original DK with restored colors.', 'This version provides a more arcade-accurate experience on the NES, updating the graphics and colors to celebrate the 40th anniversary of the game''s release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong Classics (USA, Europe)', 'Homebrew', NaN, 'Homebrew', '2', NaN, 'Arcade platformer compilation.', 'Master the levels of both Donkey Kong and Donkey Kong Jr.', 'A two-in-one cartridge featuring Nintendo''s most iconic early arcade hits.', 'Donkey Kong Classics brings together the two foundational games of the franchise, allowing players to experience the rise of Mario and the rescue of DK in one package.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong Country 4 (Unl)', '1983', NaN, 'Nintendo', '2', NaN, 'Side-scrolling platformer (Pirate).', 'Journey through the island to recover the banana hoard.', 'An impressive unlicensed NES demake of the SNES classic DKC.', 'This bootleg attempts to replicate the pre-rendered look and feel of the Super Nintendo game on 8-bit hardware, featuring Donkey and Diddy Kong in original levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong Country v1.5', '1983', NaN, 'Nintendo', '2', NaN, 'Side-scrolling platformer (Unl Hack).', 'Complete a refined version of the unlicensed DKC NES port.', 'An optimized and improved version of the unlicensed Donkey Kong Country.', 'This version (v1.5) fixes many of the glitches and physics issues found in the original bootleg, making it a much more playable and impressive 8-bit tribute.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong Jr. (Japan)', '1983', NaN, 'Nintendo', '2', NaN, 'Single-screen platformer.', 'Use vines and chains to reach the key and rescue your father.', 'A classic sequel where players control Junior to save Donkey Kong from Mario.', 'In a rare twist, Mario is the antagonist. Players must climb through jungle-themed levels, dropping fruit on enemies to reach the cage at the top of the screen.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong Jr. (World) (Rev A)', 'Homebrew', NaN, 'Homebrew', '2', NaN, 'Single-screen platformer.', 'Use vines and chains to reach the key and rescue your father.', 'The definitive revised version of the classic arcade port of DK Jr.', 'This revision offers the most accurate 8-bit reproduction of the arcade sequel, featuring the iconic four-stage loop and polished climbing mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong Jr. + Jr. Lesson (Japan)', '1983', NaN, 'Nintendo', '1', NaN, 'Educational platformer bundle.', 'Solve math problems and complete platforming stages.', 'A rare Japanese bundle combining the classic game with a math lesson.', 'This Jr. Lesson edition was designed to be educational, using the DK Jr. mechanics to help children learn basic arithmetic through 8-bit gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong Jr. 40th Anniversary', '1983', NaN, 'Nintendo', '1', NaN, 'Single-screen platformer (Enhanced).', 'Rescue Donkey Kong with updated graphics and smoother animations.', 'A modern anniversary hack that enhances the visual fidelity of DK Jr.', 'Celebrating 40 years of the character, this hack updates the color palette to more closely match the arcade cabinet, providing a fresh look for the NES port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong Jr. Math (USA, Europe)', '1988', NaN, 'Daewon Media', '1', NaN, 'Educational puzzle platformer.', 'Solve math equations by collecting numbers and symbols on vines.', 'A unique educational title that uses DK Jr. mechanics to teach math.', 'Part of Nintendo''s Education Series, this game challenges players to reach a target number by climbing and collecting digits, either solo or in a competitive mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Donkey Kong Jr. no Sansuu Asobi (Japan)', '1983', NaN, 'Nintendo', '1', NaN, 'Educational puzzle platformer.', 'Solve math equations by collecting numbers and symbols on vines.', 'The original Japanese Famicom version of Donkey Kong Jr. Math.', 'This version features the same educational gameplay as the Western release, focusing on addition, subtraction, and multiplication within the jungle setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dooly Bravo Land', '1988', NaN, 'Daewon Media', '1', NaN, 'Side-scrolling action platformer.', 'Navigate through a fantasy world as the dinosaur Dooly to save the land.', 'A South Korean action game based on the popular Dooly the Little Dinosaur.', 'This title features the iconic cartoon character in a vibrant world, using various powers to defeat enemies and overcome platforming challenges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Door Door (Japan)', '1983', NaN, 'Enix', '1', NaN, 'Single-screen puzzle action.', 'Lure enemies into doors and shut them to clear the stage.', 'An early Enix-developed puzzle game with simple but addictive mechanics.', 'Players control Chun, who must strategically open and close doors to trap various types of creatures, requiring careful timing and planning across many levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doraemon - Giga Zombie no Gyakushuu (Japan)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Turn-based RPG.', 'Travel through time with Doraemon to stop Giga Zombie''s evil plans.', 'A deep and high-quality RPG based on the iconic Doraemon franchise.', 'This RPG features Doraemon and his friends exploring different historical eras. It includes a party system, turn-based combat, and many of Doraemon''s famous gadgets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doraemon - Giga Zombie no Gyakushuu (Japan) [En by WakdHacks v1.0] (~Doraemon - The Revenge of Giga Zombie)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Turn-based RPG.', 'Travel through time with Doraemon to stop Giga Zombie''s evil plans.', 'The English translation of the epic RPG The Revenge of Giga Zombie.', 'This fan translation allows players to enjoy the full story and dialogue of one of the best licensed RPGs on the Famicom, making the gadgets and combat clear.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doraemon (Ch)', '1986', NaN, 'Hudson Soft', '1', NaN, 'Action / Mini-game collection (Pirate).', 'Complete various tasks and levels as the robotic cat Doraemon.', 'A Chinese-localized or unlicensed Doraemon title featuring various mini-games.', 'This version often includes modified assets and simplified gameplay, aimed at fans of the series in the Chinese-speaking market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doraemon (Japan)', '1986', NaN, 'Hudson Soft', '1', NaN, 'Multi-genre action / shooter.', 'Clear different stages based on the movies to find Doraemon''s friends.', 'A diverse and challenging game that switches between shooting and action.', 'Developed by Hudson Soft, this title features three distinct worlds: a shooter, a top-down adventure, and an underwater level, each with unique mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doraemon (Japan) (Mapper 15 Hack) [En by Neokid v1.1]', '1986', NaN, 'Hudson Soft', '1', NaN, 'Multi-genre action / shooter.', 'Clear different stages based on the movies to find Doraemon''s friends.', 'An English-translated version of the Hudson Soft Doraemon classic.', 'This hack translates the text and fixes mapper issues, allowing players to navigate the difficult multi-genre stages of this 8-bit classic in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Doraemon (Japan) (Rev A)', '1986', NaN, 'Hudson Soft', '1', NaN, 'Multi-genre action / shooter.', 'Clear different stages based on the movies to find Doraemon''s friends.', 'A revised version of the classic Hudson Soft Famicom title.', 'This revision includes minor technical fixes to ensure the game runs smoothly across all Famicom hardware revisions while maintaining its high difficulty.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dare (USA)', '1986', NaN, 'GameTek', '2', NaN, 'Game show / Mini-game collection.', 'Answer trivia questions and complete physical challenges to win.', 'An 8-bit adaptation of the popular Nickelodeon game show.', 'Just like the TV show, players must compete in messy physical challenges and obstacle courses, using quick reflexes and trivia knowledge to beat the clock.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon (Europe)', '1987', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up / RPG.', 'Fight through gangs to rescue Marian from the Black Warriors.', 'The legendary brawler that defined the genre on the NES.', 'Unlike the arcade, the NES version features an XP system to unlock moves. Players control Billy Lee in a gritty urban setting filled with iconic 8-bit enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon (Japan)', '1987', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up / RPG.', 'Fight through gangs to rescue Marian from the Black Warriors.', 'The original Famicom release of the foundational urban brawler.', 'Known for its challenging platforming and intense combat, this version introduced the leveling system that would make the NES port a cult classic in its own right.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon (Japan) (Beta)', '1987', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up / RPG.', 'Fight through gangs to rescue Marian from the Black Warriors.', 'An early prototype of Double Dragon with minor gameplay differences.', 'This beta offers a look at the game''s development, featuring variations in enemy behavior, sound, or level layouts compared to the final retail release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon (USA)', '1987', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up / RPG.', 'Fight through gangs to rescue Marian from the Black Warriors.', 'The legendary brawler that defined the genre on the NES.', 'Players must master punches, kicks, and environmental weapons. The NES version is famous for its unique level design and the final showdown for the title of Dragon.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon (USA) [Hack by Hiro1112 v1.1] (Arcade Mix)', '1987', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up (Hack).', 'Rescue Marian in a version of the game that mimics the arcade''s colors.', 'A visual hack designed to make the NES port look more like the arcade original.', 'This Arcade Mix updates the color palettes and sprites to provide a more visually faithful experience to the 1987 arcade cabinet while keeping the NES mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon II - The Revenge (Europe)', '1989', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up.', 'Avenge Marian''s death by defeating the mysterious Shadow Warrior leader.', 'Widely considered the best entry in the NES trilogy, featuring 2-player co-op.', 'This sequel introduces the directional attack system and iconic special moves like the Cyclone Kick. Players battle through nine stages of gritty urban and industrial landscapes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon II - The Revenge (Japan)', '1989', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up.', 'Avenge Marian''s death by defeating the mysterious Shadow Warrior leader.', 'The original Famicom release of the legendary beat ''em up sequel.', 'Known as The Revenge, this version features cinematic cutscenes between levels that tell a tragic story of loss and vengeance, setting a high bar for 8-bit storytelling.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon II - The Revenge (Japan) (Beta)', '1989', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up.', 'Avenge Marian''s death by defeating the mysterious Shadow Warrior leader.', 'An early prototype of the sequel with potential differences in sound and balance.', 'This beta version offers a technical look at the development of Double Dragon II, featuring the same core combat but with minor variations from the final retail release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon II - The Revenge (USA)', '1989', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up.', 'Avenge Marian''s death by defeating the mysterious Shadow Warrior leader.', 'The definitive 8-bit co-op brawler featuring intense combat and platforming.', 'As Billy and Jimmy Lee, players must master the timing of jumps and special attacks to survive the trap-filled hideout of the Shadow Warriors.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon II - The Revenge (USA) (Rev A)', '1989', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up.', 'Avenge Marian''s death by defeating the mysterious Shadow Warrior leader.', 'A revised version of the US release with minor technical improvements.', 'This revision ensures the best performance on NES hardware, maintaining the tight controls and memorable soundtrack that made the sequel a massive success.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon III - The Rosetta Stone (Japan)', '1990', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up with RPG elements.', 'Travel the world to find the Rosetta Stones and stop an ancient evil.', 'The challenging third entry featuring swappable characters and a shop system.', 'Known as The Rosetta Stone, this version features a unique shop mechanic and allows players to recruit defeated bosses like Chin and Ranzou to their team.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon III - The Sacred Stones (Europe)', '1990', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up with RPG elements.', 'Travel the world to find the Rosetta Stones and stop an ancient evil.', 'An international quest for justice featuring legendary martial arts combat.', 'The third installment takes the Lee brothers to the USA, China, Japan, Italy, and Egypt. It is known for its high difficulty and technical character-switching mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon III - The Sacred Stones (USA)', '1990', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up with RPG elements.', 'Travel the world to find the Rosetta Stones and stop an ancient evil.', 'The final chapter of the original NES trilogy, focusing on global exploration.', 'In the Sacred Stones, players must manage their limited lives across multiple world locations, using team-up attacks and specialized weapons to survive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dragon III - The Sacred Stones (USA) [Hack by Jedi QuestMaster v1.0] (Difficulty Fix)', '1990', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up (Hack).', 'Travel the world and defeat enemies with a more balanced difficulty curve.', 'A gameplay hack that adjusts the infamously high difficulty of the third game.', 'This version modifies enemy health and damage output, making the game more accessible and enjoyable for players who found the original release too punishing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dribble (Europe)', '1990', NaN, 'Technos Japan', '2', NaN, 'Basketball sports simulation.', 'Outscore the opposing team across four quarters of intense basketball.', 'A classic Konami sports title famous for its cinematic slam dunk shots.', 'Double Dribble was a pioneer in 8-bit sports, featuring digitized speech and close-up animations for dunks that brought an arcade feel to the home console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dribble (USA)', '1986', NaN, 'Konami', '2', NaN, 'Basketball sports simulation.', 'Outscore the opposing team across four quarters of intense basketball.', 'A classic Konami sports title famous for its cinematic slam dunk shots.', 'Double Dribble was a pioneer in 8-bit sports, featuring digitized speech and close-up animations for dunks that brought an arcade feel to the home console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Dribble (USA) (Rev A)', '1986', NaN, 'Konami', '2', NaN, 'Basketball sports simulation.', 'Outscore the opposing team across four quarters of intense basketball.', 'A revised version of the popular 8-bit basketball simulation.', 'This revision includes minor bug fixes to ensure smooth performance during the fast-paced gameplay and iconic cinematic dunk sequences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Moon Densetsu (Japan)', '1986', NaN, 'Konami', '2', NaN, 'Turn-based RPG.', 'Journey through a fantasy world to save the kingdom from ancient monsters.', 'A late-era Famicom RPG with high-quality graphics and a deep storyline.', 'Legend of the Double Moon features a traditional party system and turn-based combat, set in a beautifully rendered world that showcases the limits of 8-bit RPG design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Strike - Aerial Attack Force (USA) (Unl) (v1.0)', '1987', NaN, 'NCS', '1', NaN, 'Side-scrolling shooter (Unlicensed).', 'Pilot a combat jet to eliminate terrorist threats and destroy enemy bases.', 'An intense unlicensed flight shooter with a military theme.', 'Published by American Video Entertainment, this game challenges players to navigate hazardous airspaces while managing fuel and ammunition across multiple missions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Double Strike - Aerial Attack Force (USA) (Unl) (v1.1)', '1991', NaN, 'Color Dreams', '1', NaN, 'Side-scrolling shooter (Unlicensed).', 'Pilot a combat jet to eliminate terrorist threats and destroy enemy bases.', 'A revised version of the unlicensed shooter with improved performance.', 'Version 1.1 of Double Strike offers the same high-octane aerial combat as the original, with technical refinements to the game''s scrolling and hit detection.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dough Boy (Japan)', '1991', NaN, 'Color Dreams', '1', NaN, 'Strategic action / Puzzle.', 'Infiltrate enemy lines and plant explosives to destroy the base.', 'A unique war-themed puzzle game where you play as a demolition expert.', 'As Dough Boy, players must carefully navigate mines, trenches, and enemy fire to deliver a bomb to the target, requiring a mix of stealth and quick thinking.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Downtown - Nekketsu Koushin Kyoku - Soreyuke Daiundoukai (Japan)', '1985', NaN, 'Namco', '1', NaN, 'Sports / Fighting hybrid.', 'Compete in a chaotic city-wide athletic tournament with no rules.', 'The legendary Kunio-kun sports game featuring cross-country and fighting.', 'Players choose a school team and compete in races that involve jumping over buildings and fighting rivals in the streets, blending athletics with 8-bit brawling.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Downtown - Nekketsu Koushin Kyoku - Soreyuke Daiundoukai (Japan) [En by Disconnected v0.15] (Technos Cross-Country) (Incomplete)', '1990', NaN, 'Technos Japan', '4', NaN, 'Sports / Fighting hybrid.', 'Compete in a chaotic city-wide athletic tournament with no rules.', 'An English fan translation of the classic Kunio-kun athletic brawler.', 'This version makes the team stats and menus of the chaotic tournament accessible, allowing players to fully enjoy the over-the-top violence of the school competitions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Downtown - Nekketsu Monogatari (Japan)', '1990', NaN, 'Technos Japan', '4', NaN, 'Side-scrolling beat ''em up / RPG hybrid.', 'Rescue Ricki''s girlfriend and defeat the rival gangs of River City.', 'The original Japanese version of the cult classic River City Ransom.', 'This game revolutionized the genre by adding RPG elements, allowing players to buy food and books to upgrade their stats while fighting through non-linear urban stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Downtown Special - Kunio-kun no Jidaigeki Dayo Zenin Shuugou! (Japan)', '1989', NaN, 'Technos Japan', '2', NaN, 'Open-world beat ''em up / RPG hybrid.', 'Travel across ancient Japan to unite the provinces and defeat rivals.', 'An ambitious Kunio-kun spin-off set in the historical Edo period.', 'Known as Jidaigeki, this title features a massive world to explore, companion recruitment, and deep stat customization, all set in a humorous 8-bit version of samurai history.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Downtown Special - Kunio-kun no Jidaigeki Dayo Zenin Shuugou! (Japan) [En by TSamurai v1.0] (Technos Samurai)', '1991', NaN, 'Technos Japan', '2', NaN, 'Open-world beat ''em up / RPG.', 'Journey through ancient Japan to restore peace and defeat rival clans.', 'The English translation of the historical Kunio-kun adventure, Jidaigeki.', 'This fan translation makes the deep RPG systems and historical dialogue of the Kunio-kun samurai spin-off accessible, featuring stat building and world exploration in 8-bit Edo Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dr. Chaos (USA)', '1991', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling action and first-person exploration.', 'Explore a haunted mansion to find your brother and defeat interdimensional monsters.', 'A unique hybrid of action platforming and point-and-click adventure.', 'Dr. Chaos challenges players to explore a massive house, switching from side-scrolling hallways to first-person room searches to find items and warp zones in this sci-fi horror title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dr. Garfield', '1989', NaN, 'FCEUX / Homebrew', '1', NaN, 'Falling-block puzzle (Hack).', 'Match medical icons or items to clear the screen and score points.', 'A creative visual hack of Dr. Mario featuring the famous cat, Garfield.', 'This modification replaces the classic Dr. Mario assets with Garfield-themed graphics, offering the same addictive puzzle gameplay with a fresh aesthetic for fans of the lasagna-loving cat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dr. Jekyll and Mr. Hyde (USA)', '1989', NaN, 'FCEUX / Homebrew', '1', NaN, 'Side-scrolling action / Platformer.', 'Reach the church for your wedding while managing your stress level.', 'A notoriously difficult and surreal game based on the classic gothic novella.', 'Players must navigate a hostile town as Jekyll. If the stress meter fills, they transform into Hyde in a dark dream world. The game is famous for its high difficulty and unique dual-character mechanic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Drac''s Night Out (USA) (Proto)', '1990', NaN, 'Marionette', '1', NaN, 'Side-scrolling action platformer.', 'Guide Dracula through the town to reach his girlfriend while avoiding angry mobs.', 'An unreleased NES prototype featuring a humorous take on the vampire legend.', 'Originally planned as a Reebok-sponsored title, this game features Dracula using magic and stealth to navigate levels, offering a rare look at a canceled 8-bit project.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball - Dai Maou Fukkatsu (Japan)', '1988', NaN, 'Toho', '1', NaN, 'Board game / Card-based RPG.', 'Defeat King Piccolo and his minions to save the world.', 'The first card-battle RPG in the Dragon Ball Famicom series.', 'Using a board game movement system and cards for combat, this title covers the King Piccolo saga, blending strategic decision-making with iconic 8-bit anime cutscenes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball - Le Secret du Dragon (France)', '1988', NaN, 'Toho', '1', NaN, 'Top-down action adventure.', 'Collect the seven Dragon Balls and defeat the Rabbit Gang and Emperor Pilaf.', 'The French version of the first Dragon Ball game, based on the early series.', 'This action game features Goku using his Power Pole. It is known for its high difficulty and for being one of the few official Dragon Ball releases in the West during the 8-bit era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball - Le Secret du Dragon (France) (Rev A)', '1986', NaN, 'Toho', '1', NaN, 'Top-down action adventure.', 'Collect the seven Dragon Balls and defeat the Rabbit Gang and Emperor Pilaf.', 'A revised French version of the first Dragon Ball action game.', 'This revision includes minor technical fixes to ensure better performance on European NES consoles while maintaining the classic Goku adventure gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball - Shen Long no Nazo (Japan)', '1986', NaN, 'Toho', '1', NaN, 'Top-down action adventure.', 'Collect the seven Dragon Balls and defeat the Rabbit Gang and Emperor Pilaf.', 'The original Japanese version of Goku''s first Famicom adventure.', 'Featuring the early Dragon Ball story, this game combines top-down combat with side-scrolling boss fights, setting the stage for the franchise''s massive success on Nintendo hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball - Shen Long no Nazo (Japan) (Mapper 34 Hack) [En by TransBRC v1.11] (~Dragon Ball - Dragon Mystery)', '1986', NaN, 'Toho', '1', NaN, 'Top-down action adventure.', 'Collect the seven Dragon Balls and defeat the Rabbit Gang and Emperor Pilaf.', 'The English translation of Goku''s first Famicom action game.', 'This fan translation brings the original Shen Long no Nazo to English speakers, restoring the story and dialogue that were heavily altered in the US version (Dragon Power).', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball 3 - Gokuu Den (Japan)', '1989', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Relive Goku''s journey from the start of the series to the fight with Piccolo Junior.', 'A comprehensive RPG covering the majority of the original Dragon Ball story.', 'This title refined the card-battle system and featured impressive 8-bit cinematic battles, allowing players to grow Goku from a child to a powerful young man.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z - Kyoushuu! Saiya Jin (Japan)', '1990', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Defeat the invading Saiyans, Nappa and Vegeta, to protect Earth.', 'The first Dragon Ball Z game on Famicom, introducing the Raditz and Vegeta sagas.', 'This game moved the series into the Z era, featuring strategic card combat where the stars on the card determine attack and defense power in cinematic 8-bit battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z - Kyoushuu! Saiya Jin (Japan) [En by Twilight v1.01] (~Dragon Ball Z - Assault of the Saiyans)', '1990', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Defeat the invading Saiyans, Nappa and Vegeta, to protect Earth.', 'The English translation of the first DBZ card-battle RPG.', 'This version allows fans to experience the start of the Z saga in English, making the complex card mechanics and character stats fully understandable for the first time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z 5', 'Homebrew', NaN, 'Homebrew', '1', NaN, '2D Fighting game (Pirate).', 'Fight as various Z-warriors in a tournament-style combat game.', 'A notorious unlicensed fighting game featuring Dragon Ball Z characters.', 'Often found on multi-carts, this bootleg attempts to bring a Street Fighter-style experience to the NES using DBZ sprites, offering a fast-paced but unpolished fighting experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z Gaiden - Saiya Jin Zetsumetsu Keikaku (Japan)', '1993', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Stop the Hatchiyack and the Destron Gas from destroying Earth.', 'A unique DBZ game featuring an original story not found in the manga.', 'Known as Plan to Eliminate the Saiyans, this game features high-quality 8-bit graphics and a complex card system where players combine symbols to perform special moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z Gaiden - Saiya Jin Zetsumetsu Keikaku (Japan) [En by Twilight v1.0] (~Dragon Ball Z Gaiden - Plan to Eliminate the Saiyans) (Vegeta Control)', '1993', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Stop the Hatchiyack and defeat the enemies with manual control over Vegeta.', 'An English-translated version of DBZ Gaiden with a gameplay modification.', 'This specific hack allows players to have more control over Vegeta''s actions during the card battles, adding a new layer of strategy to this fan-translated original story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z II - Gekishin Freeza!! (Japan) (Rev 1)', '1991', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Travel to Namek and defeat the tyrant Frieza and his Ginyu Force.', 'The epic sequel to the Saiyan saga, covering the Namek and Frieza arcs.', 'Considered one of the best in the series, it features a massive world map and intense cinematic battles as the Z-warriors race to find the Namekian Dragon Balls.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z II - Gekishin Freeza!! (Japan) (Rev 1) [En by Saiya v0.70] (~Dragon Ball Z II - Evil Freeza!) (Incomplete)', '1991', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Travel to Namek and defeat the tyrant Frieza and his Ginyu Force.', 'An English translation of the legendary Frieza saga RPG.', 'This version makes the deep strategy and iconic storyline of the Frieza arc accessible in English, though some versions are noted as incomplete in their translation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z II - Gekishin Freeza!! (Japan) [En by Saiya v0.70] (~Dragon Ball Z II - Evil Freeza!) (Incomplete)', '1991', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Travel to Namek and defeat the tyrant Frieza and his Ginyu Force.', 'An English-translated version of the Namek saga card-battle RPG.', 'This entry ensures that players can follow the mission objectives and card systems while reliving the most famous arc in Dragon Ball Z history on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z III - Ressen Jinzou Ningen (Japan)', '1992', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Defeat the Androids and the bio-android Cell to save the future.', 'The third DBZ RPG, covering the Android and Cell sagas.', 'This title introduced more fluid combat animations and faster-paced gameplay, focusing on the high-stakes battles against Dr. Gero''s creations and the ultimate lifeform, Cell.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ball Z III - Ressen Jinzou Ningen (Japan) [En by Twilight v1.0] (~Dragon Ball Z III - Killer Androids)', '1992', NaN, 'Toei Animation', '1', NaN, 'Card-based RPG.', 'Defeat the Androids and the bio-android Cell to save the future.', 'The English translation of the Famicom''s Android and Cell saga RPG.', 'This fan translation opens up the final main-series card-battle RPG on the Famicom, allowing fans to play through the Cell Games with full English text.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Buster (Japan)', '1985', NaN, 'Namco', '1', NaN, 'Side-scrolling action / Dungeon crawler.', 'Navigate a world map and explore dungeons to rescue a princess from a dragon.', 'A classic Namco arcade port blending action and RPG exploration.', 'Dragon Buster features a non-linear map and vertical dungeon exploration. It is known for its double jump mechanic and the need to find specific items to survive the dragon''s lair.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Buster II - Yami no Fuuin (Japan)', '1986', NaN, 'Namco', '1', NaN, 'Top-down action adventure.', 'Use your bow and arrow to clear dungeons and seal the darkness.', 'A departure from the original''s side-scrolling, now featuring a top-down view.', 'Dragon Buster II: Seal of Darkness shifts the perspective to overhead exploration. Players navigate complex maze-like dungeons, using strategic archery to defeat enemies and find the exit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Buster II - Yami no Fuuin (Japan) [En by PentarouZero v1.0] (~Dragon Buster II - Seal of Darkness)', '1986', NaN, 'Namco', '1', NaN, 'Top-down action adventure.', 'Use your bow and arrow to clear dungeons and seal the darkness.', 'The English translation of the top-down sequel Seal of Darkness.', 'This fan translation makes the story and item names clear, allowing players to fully experience this dungeon-crawling sequel that differs significantly from the first entry.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Fighter (Japan)', '1990', NaN, 'Natsume', '1', NaN, 'Side-scrolling action platformer.', 'Fight through stages and transform into a powerful dragon to defeat bosses.', 'A high-quality action game featuring a unique human-to-dragon transformation.', 'Players control a warrior who builds an energy meter to transform into a flying dragon. The game features diverse environments and a challenging difficulty curve typical of late-NES titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Fighter (USA)', '1990', NaN, 'Natsume', '1', NaN, 'Side-scrolling action platformer.', 'Fight through stages and transform into a powerful dragon to defeat bosses.', 'A high-quality action game featuring a unique human-to-dragon transformation.', 'Players control a warrior who builds an energy meter to transform into a flying dragon. The game features diverse environments and a challenging difficulty curve typical of late-NES titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Ninja (Japan)', '1988', NaN, 'Technos Japan', '2', NaN, 'Side-scrolling beat ''em up.', 'Rescue President Ronnie from a group of evil ninjas.', 'The Japanese Famicom version of the arcade hit Bad Dudes.', 'Known for its iconic Are you a bad enough dude? premise, this version features tight brawling action across city streets and moving trucks, fighting endless waves of ninjas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Power (USA)', '1988', NaN, 'Technos Japan', '2', NaN, 'Top-down action adventure.', 'Collect crystal balls and defeat the master of the castle.', 'A localized and heavily censored version of the first Dragon Ball game.', 'To avoid licensing issues, Goku was turned into a generic martial artist. While the gameplay remains the same as Shen Long no Nazo, the story and graphics were significantly altered.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Quest (Japan)', '1986', NaN, 'Chunsoft', '1', NaN, 'Turn-based RPG.', 'Defeat the Dragonlord and recover the stolen Sphere of Light.', 'The game that defined the JRPG genre on home consoles.', 'Dragon Quest features a solo hero embarking on an epic quest. It introduced the core mechanics of leveling up, buying equipment, and turn-based combat that would inspire countless titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Quest II - Akuryou no Kamigami (Japan)', '1987', NaN, 'Chunsoft', '1', NaN, 'Turn-based RPG.', 'Assemble a party of three descendants of Erdrick to defeat Hargon.', 'A massive sequel that introduced the party-based combat system.', 'Expanding on the original, DQII features a much larger world, sea travel, and more complex dungeons, challenging players with some of the toughest balancing in the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Quest III - Soshite Densetsu e... (Japan) (Rev 0A)', '1988', NaN, 'Chunsoft', '1', NaN, 'Turn-based RPG.', 'Defeat the archfiend Baramos and uncover your father''s legacy.', 'A masterpiece of the 8-bit era featuring a deep class/job system.', 'DQIII allows players to create their own party members at the tavern. It features a day/night cycle and a dual-world twist that solidified its status as a legend in Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Quest III - Soshite Densetsu e... (Japan) (Rev B)', '1988', NaN, 'Chunsoft', '1', NaN, 'Turn-based RPG.', 'Defeat the archfiend Baramos and uncover your father''s legacy.', 'A revised version of the legendary RPG with minor bug fixes.', 'This revision addresses technical issues found in earlier copies, providing the most stable version of the Famicom''s most ambitious and successful role-playing game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Quest IV - Michibikareshi Monotachi (Japan) (Rev A)', '1990', NaN, 'Chunsoft', '1', NaN, 'Turn-based RPG.', 'Unify five chosen heroes to stop the resurrection of Estark.', 'A unique chapter-based RPG that tells a grand, interconnected story.', 'DQIV is divided into five chapters, each focusing on different characters before they all meet in the final act. It introduced AI-controlled party members and deep character development.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Scroll - Yomigaerishi Maryuu (Japan)', '1987', NaN, 'Kemco', '1', NaN, 'Action RPG with exploration.', 'Find the eight scrolls of magic to defeat the resurrected demon dragon.', 'A non-linear adventure game similar to the Zelda style of exploration.', 'Developed by Konami, Dragon Scroll requires players to gather information from NPCs and solve environmental puzzles to progress, featuring a mix of magic and sword combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Scroll - Yomigaerishi Maryuu (Japan) [En by KingMike v1.0] (~Dragon Scroll - Resurrection of the Demon Dragon)', '1987', NaN, 'Kemco', '1', NaN, 'Action RPG with exploration.', 'Find the eight scrolls of magic to defeat the resurrected demon dragon.', 'The English translation of Konami''s ambitious adventure Dragon Scroll.', 'This version translates the vital NPC dialogue and clues needed to solve the game''s many puzzles, making this hidden Konami gem playable for English audiences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Slayer 4 - Drasle Family (Japan)', '1987', NaN, 'Taito', '1', NaN, 'Action RPG / Platformer.', 'Use the unique abilities of each family member to recover the Dragon Slayer sword.', 'Known in the West as Legacy of the Wizard, a deep and difficult dungeon crawler.', 'Players control the Drasle family (and their dog). Each member has specific items they can use, requiring the player to switch characters strategically to navigate a massive, single dungeon.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Spirit - Aratanaru Densetsu (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Vertical-scrolling shoot ''em up.', 'Pilot a powerful dragon to destroy the serpent demon Zawell.', 'A unique shooter where you control a mythical beast instead of a spaceship.', 'Dragon Spirit features a health system and the ability to grow more heads to increase firepower. The Japanese version is known for its high difficulty and impressive mythological art style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Spirit - The New Legend (USA)', '1989', NaN, 'Namco', '1', NaN, 'Vertical-scrolling shoot ''em up.', 'Pilot a powerful dragon to destroy the serpent demon Zawell.', 'An enhanced NES sequel to the arcade original, featuring a new storyline.', 'This version includes a prologue level that determines your starting power. It features beautiful 8-bit cutscenes and a smoother difficulty curve than the Japanese arcade port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Unit (Japan)', '1990', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer.', 'Fight through mythical stages to rescue the princess and kill the dragon.', 'An 8-bit port of the arcade game Castle of Dragon.', 'Dragon Unit features a variety of weapons and shields. It is a straightforward action game where players must master boss patterns and navigate hazardous castle environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior - Part II (USA)', '1989', NaN, 'Enix', '1', NaN, 'Turn-based RPG.', 'Assemble a party of three descendants of Erdrick to defeat Hargon.', 'The North American version of Dragon Quest II, featuring improved graphics.', 'This version updated the sprites of the Japanese original to include walking directions and added a battery-backed save system, making the epic quest more accessible.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior (USA)', '1986', NaN, 'Enix', '1', NaN, 'Turn-based RPG.', 'Defeat the Dragonlord and recover the stolen Sphere of Light.', 'The localized version of the first Dragon Quest, featuring modernized sprites.', 'Published by Nintendo, this version replaced the password system with battery saves and updated the character graphics to look more detailed than the original 1986 Japanese release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior (USA) (Rev A)', '1989', NaN, 'Enix', '1', NaN, 'Turn-based RPG.', 'Defeat the Dragonlord and recover the stolen Sphere of Light.', 'A revised US release of the classic RPG with technical refinements.', 'This revision ensures the best performance for the localized NES version, maintaining the Thou hast style of dialogue and the foundational 8-bit quest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior (USA) (Rev A) [Graphic Hack by Interordi v0.33] (~Dragon Warrior Plus)', '1989', NaN, 'Enix', '1', NaN, 'Turn-based RPG (Graphic Hack).', 'Defeat the Dragonlord with updated visuals inspired by the SNES remakes.', 'A visual overhaul of Dragon Warrior that modernizes the 8-bit graphics.', 'This hack replaces the original NES sprites and tiles with high-quality versions, giving the classic 1989 North American release a much more polished and colorful look.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior (USA) (Rev A) [Hack by Sliver X v1.0Final] (~Dragoon X)', '1990', NaN, 'Enix', '1', NaN, 'Turn-based RPG (Total Hack).', 'Navigate a new sci-fi world to defeat an alien threat.', 'A total conversion of Dragon Warrior that turns it into a sci-fi RPG.', 'Dragoon X completely changes the setting, story, and graphics of the original game, replacing fantasy elements with lasers, spaceships, and futuristic landscapes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior (USA) [Graphic Hack by Interordi v0.33] (~Dragon Warrior Plus)', '1987', NaN, 'Koei', '1', NaN, 'Turn-based RPG (Graphic Hack).', 'Defeat the Dragonlord with updated visuals inspired by the SNES remakes.', 'Another entry for the visual overhaul of Dragon Warrior with polished assets.', '(Same as the previous entry for database consistency), this hack provides a refreshed aesthetic for the first entry in the legendary series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior (USA) [Hack by Sliver X v1.0Final] (~Dragoon X)', '1987', NaN, 'Koei', '1', NaN, 'Turn-based RPG (Total Hack).', 'Navigate a new sci-fi world to defeat an alien threat.', 'A total conversion of Dragon Warrior that turns it into a sci-fi RPG.', '(Same as the previous entry for database consistency), this hack showcases the versatility of the NES engine in creating entirely new 8-bit adventures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior (USA) [Hack by Sliver X v2.0f] (~Dragoon X Omega)', '1987', NaN, 'Square', '1', NaN, 'Turn-based RPG (Total Hack).', 'Survive a post-apocalyptic quest in this ultimate sci-fi modification.', 'The definitive version of the Dragoon X series, featuring deep modifications.', 'This Omega version includes refined gameplay balance, new enemies, and an expanded story, representing one of the most complete overhauls of the Dragon Warrior engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior III (USA)', '1987', NaN, 'Namco', '1', NaN, 'Turn-based RPG with class system.', 'Defeat the archfiend Baramos and save the world from eternal darkness.', 'Often called the best NES RPG, featuring a deep party-customization system.', 'This massive quest allows players to create their own party members at the tavern. It features a day/night cycle, a huge world map, and a legendary twist that connects it to the previous games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Warrior IV (USA)', '1989', NaN, 'Namco', '1', NaN, 'Turn-based RPG with chapters.', 'Unify the chosen heroes to stop the resurrection of the Lord of Underworld.', 'A unique 8-bit epic told through five distinct character-driven chapters.', 'Each chapter focuses on a different hero (like Torneko the merchant or Alena the princess) before they all join forces in the final act. It introduced tactical AI-controlled combat for allies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Wars (Japan)', '1990', NaN, 'Athena', '1', NaN, 'First-person dungeon crawler RPG.', 'Lead a party of adventurers to escape the city of Purgatory and defeat Dilmun.', 'A dark and complex RPG featuring deep character customization and lore.', 'Originally a PC title, this Famicom port offers strategic turn-based combat and a heavy emphasis on exploration and skill checks, set in a world where magic has been outlawed.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon Wars (USA) (Proto)', '1989', NaN, 'Enix', '1', NaN, 'First-person dungeon crawler RPG.', 'Lead a party of adventurers to escape the city of Purgatory and defeat Dilmun.', 'An unreleased North American prototype of the complex fantasy RPG.', 'This prototype showcases the localized English text and interface for the NES port, which unfortunately never saw an official retail release in the United States.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon''s Lair (Europe)', '1986', NaN, 'Enix', '1', NaN, 'Side-scrolling action platformer.', 'Guide Dirk the Daring through Singe''s castle to rescue Princess Daphne.', 'A notoriously difficult and cinematic 8-bit action game based on the laserdisc hit.', 'Unlike the arcade, this is a traditional platformer. It is known for its high difficulty, slow movement, and elaborate animations that require extreme precision to avoid instant-death traps.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon''s Lair (Japan)', '1986', NaN, 'Enix', '1', NaN, 'Side-scrolling action platformer.', 'Guide Dirk the Daring through Singe''s castle to rescue Princess Daphne.', 'The Famicom version of the challenging fantasy action adventure.', 'This version features the same trial-and-error gameplay as the Western releases, tasking players with memorizing enemy patterns and environmental hazards to survive the castle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dragon''s Lair (USA)', '1986', NaN, 'Enix', '1', NaN, 'Side-scrolling action platformer.', 'Guide Dirk the Daring through Singe''s castle to rescue Princess Daphne.', 'A notoriously difficult and cinematic 8-bit action game based on the laserdisc hit.', 'Unlike the arcade, this is a traditional platformer. It is known for its high difficulty, slow movement, and elaborate animations that require extreme precision to avoid instant-death traps.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dream Master (Japan)', '1986', NaN, 'Enix', '1', NaN, 'Top-down puzzle adventure.', 'Enter the dreams of seven people to rescue them from a nightmare demon.', 'A creative Namco adventure game focused on exploration and puzzle-solving.', 'As the Dream Master, players navigate surreal top-down environments, interacting with objects and solving logic puzzles to clear each stage and free the trapped souls.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dropzone (Europe)', '1986', NaN, 'Enix', '1', NaN, 'Side-scrolling defender-style shooter.', 'Defend a planetary base and rescue scientists from invading aliens.', 'A fast-paced and technical horizontal shooter inspired by the arcade hit Defender.', 'Dropzone requires high-speed maneuvers and precise shooting as you manage a radar to locate enemies and carry survivors to safety in a high-intensity sci-fi setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Hunt (World)', '1986', NaN, 'Enix', '1', NaN, 'Light gun shooter.', 'Shoot the ducks or clay pigeons to earn points and avoid the dog''s mockery.', 'The legendary NES Zapper game that became a global cultural icon.', 'A core part of the NES experience, featuring three modes: single duck, double duck, and clay pigeon shooting. It remains the gold standard for 8-bit light gun games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Maze (Australia) (Unl)', '1986', NaN, 'Enix', '1', NaN, 'Top-down puzzle action.', 'Guide a duck through maze-like levels to collect items and reach the exit.', 'A rare unlicensed puzzle game featuring simple but challenging 8-bit logic.', 'Released by Home Entertainment Suppliers, this title tasks players with navigating tight corridors and avoiding hazards in a series of increasingly complex mazes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Tales (Europe)', '1989', NaN, 'Enix', '1', NaN, 'Side-scrolling action platformer.', 'Travel the world to find five legendary treasures and become the richest duck.', 'A Capcom masterpiece known for its incredible music and pogo-stick gameplay.', 'As Scrooge McDuck, players use his cane as a pogo stick to bounce on enemies and reach high platforms. It is widely considered one of the best licensed games ever made.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Tales (USA)', '1992', NaN, 'Enix', '1', NaN, 'Side-scrolling action platformer.', 'Travel the world to find five legendary treasures and become the richest duck.', 'A Capcom masterpiece known for its incredible music and pogo-stick gameplay.', 'As Scrooge McDuck, players use his cane as a pogo stick to bounce on enemies and reach high platforms. It is widely considered one of the best licensed games ever made.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Tales (USA) (Beta)', '1989', NaN, 'Interplay', '1', NaN, 'Side-scrolling action platformer.', 'Travel the world to find five legendary treasures and become the richest duck.', 'An early prototype of the Capcom hit with minor gameplay variations.', 'This beta version allows a glimpse into the development of the game, featuring potential differences in level layout, enemy placement, or the famous Moon theme music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Tales 2 (Europe)', '1989', NaN, 'Interplay', '1', NaN, 'Side-scrolling action platformer.', 'Recover the lost map pieces of Fergus McDuck to find a hidden treasure.', 'A polished sequel that improves on the original with new moves and upgrades.', 'Scrooge returns with new cane abilities, such as pulling objects and swinging. The game features even more secrets, multiple endings, and high-quality 8-bit animation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Tales 2 (Europe) (Beta)', '1991', NaN, 'Software Projects', '1', NaN, 'Side-scrolling action platformer.', 'Recover the lost map pieces of Fergus McDuck to find a hidden treasure.', 'A prototype of the sequel featuring early versions of the refined levels.', 'This version offers a technical look at the sequel''s production, showcasing the transition from the first game''s mechanics to the more advanced systems of the second.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Tales 2 (France)', '1991', NaN, 'Software Projects', '1', NaN, 'Side-scrolling action platformer.', 'Retrouvez les fragments de la carte au trésor de Fergus McDuck.', 'The French localized version of the high-quality Disney platformer sequel.', 'This edition brings the adventures of Balthazar Picsou (Scrooge) to French audiences, featuring the same tight controls and hidden secrets as the international release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Tales 2 (Germany)', '1991', NaN, 'Software Projects', '1', NaN, 'Side-scrolling action platformer.', 'Finden Sie die Kartenteile von Fergus McDuck, um den Schatz zu bergen.', 'The German localized version of the acclaimed Capcom sequel.', 'Known as DuckTales 2, this version allows German fans to experience Scrooge''s global treasure hunt with localized packaging and instructions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Tales 2 (Japan)', '1992', NaN, 'Athena', '1', NaN, 'Side-scrolling action platformer.', 'Recover the lost map pieces of Fergus McDuck to find a hidden treasure.', 'The original Famicom release of the polished Disney sequel.', 'Known as DuckTales 2, this version represents the pinnacle of 8-bit Capcom design, with colorful graphics and some of the most memorable music on the hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Duck Tales 2 (USA)', '1987', NaN, 'U.S. Gold', '1', NaN, 'Side-scrolling action platformer.', 'Recover the lost map pieces of Fergus McDuck to find a hidden treasure.', 'A polished sequel that improves on the original with new moves and upgrades.', 'Scrooge returns with new cane abilities, such as pulling objects and swinging. The game features even more secrets, multiple endings, and high-quality 8-bit animation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'DuckTales - S3K music', '1984', NaN, 'Nintendo', '2', NaN, 'Side-scrolling action platformer (Hack).', 'Find the legendary treasures while enjoying a modern 16-bit sound swap.', 'A fun audio hack that replaces the DuckTales soundtrack with Sonic 3 & Knuckles music.', 'This modification blends two iconic franchises, giving the classic 8-bit platforming of DuckTales a high-energy Genesis-style vibe with a customized soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dudes With Attitude (USA) (Unl)', '1990', NaN, 'Homebrew', '1', NaN, 'Top-down puzzle game.', 'Navigate a grid to collect treasures while avoiding hazards and monsters.', 'A rare unlicensed puzzle game from American Video Entertainment.', 'This title focuses on logic and timing as players move their Dude through various stages, collecting power-ups and solving environmental puzzles to advance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dungeon & Magic - Swords of Element (Japan)', '1989', NaN, 'Capcom', '1', NaN, 'First-person RPG with real-time combat.', 'Explore a vast fantasy world and clear dungeons to stop an ancient evil.', 'A unique 3D-perspective RPG featuring real-time sword swinging mechanics.', 'Known as Dungeon Magic in the West, this game features an immersive first-person view where players must manually time their attacks and blocks during combat encounters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dungeon Kid (Japan)', '1989', NaN, 'Capcom', '1', NaN, 'Grid-based puzzle / Game maker.', 'Design your own dungeons or complete pre-made levels to find the exit.', 'A creative dungeon construction game that lets you build your own adventures.', 'Dungeon Kid provides a robust editor to place tiles, enemies, and items, as well as a main quest mode that showcases what can be created with the 8-bit toolset.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dungeon Magic - Sword of the Elements (USA)', '1989', NaN, 'Capcom', '1', NaN, 'First-person RPG with real-time combat.', 'Explore a vast fantasy world and clear dungeons to stop an ancient evil.', 'A unique 3D-perspective RPG featuring real-time sword swinging mechanics.', 'Known as Dungeon Magic in the West, this game features an immersive first-person view where players must manually time their attacks and blocks during combat encounters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dusty Diamond''s All-Star Softball (USA)', '1993', NaN, 'Capcom', '1', NaN, 'Sports / Softball simulation.', 'Win a series of softball games by selecting the best park and team.', 'A unique and highly customizable 8-bit softball game with street rules.', 'This cult classic allows players to draft teams from various quirky characters and play in diverse locations like backyards or parks, each with its own special rules and environmental hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dynablaster (Europe)', '1993', NaN, 'Capcom', '1', NaN, 'Action / Maze puzzle.', 'Place bombs strategically to destroy enemies and find the exit.', 'The European version of the classic Bomberman featuring strategic grid-based action.', 'Known for its addictive multiplayer and challenging single-player campaign, players must blast through walls and power up their explosive range to clear stages of monsters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dynamite Batman (Japan)', '1993', NaN, 'Capcom', '1', NaN, 'Side-scrolling action platformer.', 'Defeat the Joker and his high-tech army in a futuristic Gotham City.', 'The Japanese version of Batman: Return of the Joker, featuring incredible 8-bit graphics.', 'Known for pushing the NES hardware to its limits, this title features large, detailed sprites and a variety of weapon power-ups as Batman battles through visually stunning stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dynamite Bowl (Japan)', '1993', NaN, 'Capcom', '1', NaN, 'Sports / Bowling simulation.', 'Compete in bowling matches to achieve a perfect score of 300.', 'A straightforward and polished 8-bit bowling simulator for the Famicom.', 'Featuring simple controls for power and spin, Dynamite Bowl allows players to experience the precision of competitive bowling with charming retro visuals and sound.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Dynowarz - Destruction of Spondylus (USA)', '1989', NaN, 'Jaleco', '1', NaN, 'Side-scrolling and platform action.', 'Pilot a massive Robosaur to protect the Spondylus system from a viral threat.', 'A unique hybrid of human-scale platforming and giant mech-dinosaur combat.', 'Players switch between controlling Cyboras on foot to infiltrate bases and piloting the Cynosaur to battle other giant mechanical dinosaurs across various planetary environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Earthbound (USA) (Proto)', '1994', NaN, 'APE / HAL Laboratory', '1', NaN, 'Turn-based RPG.', 'Help Ninten and his friends stop an alien invasion using psychic powers.', 'The unreleased English version of Mother, later released as Earthbound Beginnings.', 'A modern-day RPG set in 1980s America. It features a unique PSI magic system, a quirky sense of humor, and a deep emotional story that inspired a massive cult following.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Earthbound (USA) (Proto) [Hack by Starmen.Net v1.0] (~EarthBound - Easy)', '1994', NaN, 'APE / HAL Laboratory', '1', NaN, 'Turn-based RPG (Hack).', 'Experience the story of Mother 1 with increased XP and reduced grind.', 'A gameplay-balanced version of the Earthbound prototype for a smoother experience.', 'This Easy hack adjusts the difficulty by increasing the experience points and money gained from battles, allowing players to focus more on the narrative and exploration.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'EarthWorm Jim 3 (Unl)', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling action platformer.', 'Guide Jim through surreal levels to defeat wacky villains.', 'A notorious unlicensed NES port of the famous 16-bit run-and-gun platformer.', 'This bootleg attempts to bring the high-energy animation and gameplay of Earthworm Jim to the 8-bit hardware, featuring the iconic character and his eccentric sense of humor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Earthworm Jim 3 Improvement', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling action platformer (Hack).', 'Navigate a much more playable and stable version of the Jim 3 pirate port.', 'A technical improvement hack that fixes glitches and physics in the bootleg port.', 'This modification addresses the poor controls and graphical issues of the original unlicensed release, making the 8-bit version of Jim''s adventure much more enjoyable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Eevee Bros.', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling platformer (Hack).', 'Complete levels using various Eevee evolutions and their special powers.', 'A creative Pokémon-themed hack of Super Mario Bros. 2 (USA).', 'This total conversion replaces the Mario cast with Eeveelutions, modifying the graphics and abilities to match the Pokémon universe within the classic platforming engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Eggerland - Meikyuu no Fukkatsu (Japan)', '1987', NaN, 'HAL Laboratory', '1', NaN, 'Grid-based puzzle action.', 'Solve room-based puzzles by moving blocks and outsmarting enemies.', 'A deep and challenging puzzle game featuring the hero Lolo.', 'Part of the series that became Adventures of Lolo in the West, this Famicom title features over 100 complex rooms that require precise logic and timing to clear.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Eggerland - Meikyuu no Fukkatsu (Japan) [En by Kapow v0.90] (~Eggerland - Revival of the Labyrinth)', '1987', NaN, 'HAL Laboratory', '1', NaN, 'Grid-based puzzle action.', 'Solve room-based puzzles by moving blocks and outsmarting enemies.', 'The English translation of the expansive Famicom puzzle classic Eggerland.', 'This fan translation opens up the level names and clues, allowing English speakers to fully master the intricate block-pushing puzzles of the Labyrinth.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Egypt (Japan)', '1985', NaN, 'Human Entertainment', '1', NaN, 'Top-down logic puzzle.', 'Slide jewels and blocks to create matches and clear the ancient board.', 'A specialized puzzle game set in an Egyptian-themed 8-bit world.', 'Players must use spatial reasoning to rearrange icons in as few moves as possible, progressing through multiple stages of increasing difficulty and complexity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Egypt (Japan) [En by Dodgy v1.01]', '1985', NaN, 'Human Entertainment', '1', NaN, 'Top-down logic puzzle.', 'Slide jewels and blocks to create matches and clear the ancient board.', 'The English version of the strategic Famicom puzzle game Egypt.', 'This translation makes the menus and instructions clear, ensuring that players can focus on the challenging jewel-sliding puzzles without a language barrier.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Elevator Action (Japan)', '1985', NaN, 'Taito', '2', NaN, 'Action / Platformer.', 'Infiltrate a building, collect secret documents, and escape via the basement.', 'A classic arcade port where timing elevators and shooting enemies is key.', 'Players control Agent 17 (Otto) as he moves down a massive skyscraper. The game focuses on strategic movement using elevators and stairs while engaging in gunfights with enemy spies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Elevator Action (USA)', '1985', NaN, 'Taito', '2', NaN, 'Action / Platformer.', 'Infiltrate a building, collect secret documents, and escape via the basement.', 'A classic arcade port where timing elevators and shooting enemies is key.', 'Players control Agent 17 (Otto) as he moves down a massive skyscraper. The game focuses on strategic movement using elevators and stairs while engaging in gunfights with enemy spies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Elf Legend', 'Homebrew', NaN, 'Homebrew', '1', NaN, 'Side-scrolling action adventure.', 'Explore a fantasy world to rescue the elf princess and defeat the darkness.', 'A rare unlicensed action game featuring fantasy themes and exploration.', 'This title combines traditional platforming with adventure elements, where the player must gather items and defeat mythological bosses to progress through the story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Eliminator Boat Duel (Europe)', '1991', NaN, 'Electronic Arts', '2', NaN, 'Racing and combat.', 'Win high-stakes powerboat races to earn money and upgrade your vessel.', 'A fast-paced boat racer featuring both overhead and behind-the-view perspectives.', 'Players compete in intense 1v1 races that include jumps, obstacles, and the ability to knock rivals into the water, all to win the championship and big cash prizes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Eliminator Boat Duel (USA)', '1991', NaN, 'Electronic Arts', '2', NaN, 'Racing and combat.', 'Win high-stakes powerboat races to earn money and upgrade your vessel.', 'A fast-paced boat racer featuring both overhead and behind-the-view perspectives.', 'Players compete in intense 1v1 races that include jumps, obstacles, and the ability to knock rivals into the water, all to win the championship and big cash prizes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Elite (Europe) (En,Fr,De)', '1991', NaN, 'Firebird', '1', NaN, 'Space trading and combat simulation.', 'Trade goods and engage in space battles to reach the rank of Elite.', 'A groundbreaking open-ended space simulator with impressive 3D wireframe graphics.', 'One of the most technically advanced NES games, Elite allows players to explore a massive galaxy, customize their ship, and choose their path as a trader, pirate, or bounty hunter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Elite (NTSC Demo)', '1991', NaN, 'Firebird', '1', NaN, 'Space trading and combat simulation.', 'Explore the galaxy in this technical demonstration for NTSC consoles.', 'A rare demo version of the ambitious space simulator for North American systems.', 'This version showcases the impressive 3D wireframe engine and basic flight mechanics of Elite, adapted for the NTSC television standard.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Elysion (Japan)', '1991', NaN, 'Towachiki', '1', NaN, 'Side-scrolling action RPG.', 'Journey through a mythological world to gather artifacts and save the land.', 'A complex Famicom adventure that blends platforming with RPG elements.', 'Set in a world of ancient legends, Elysion requires players to explore vast maps, talk to NPCs, and manage an inventory of magical items to defeat powerful bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Elysion (Japan) [En by Tenshigami v0.91]', '1991', NaN, 'Towachiki', '1', NaN, 'Side-scrolling action RPG.', 'Journey through a mythological world to gather artifacts and save the land.', 'The fan-translated version of the mythological action-adventure Elysion.', 'This translation is essential for understanding the game''s clues and narrative, making the non-linear exploration and character progression much clearer for English players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Elysion (Japan) [En by Tenshigami v0.91] (SRAM Saving)', '1991', NaN, 'Towachiki', '1', NaN, 'Side-scrolling action RPG.', 'Journey through the land and save your progress with an added battery fix.', 'An enhanced version of the Elysion translation that allows for easier saving.', 'This specific version adds the ability to save the game directly to the memory (SRAM), replacing the cumbersome password system of the original Famicom release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Emoyan no 10 Bai Pro Yakyuu (Japan)', '1988', NaN, 'Capcom', '2', NaN, 'Sports / Baseball simulation.', 'Lead your team to victory in the professional Japanese baseball league.', 'A quirky baseball game featuring exaggerated plays and deep management.', 'Endorsed by pitcher Suguru Egawa (Emoyan), this title offers a blend of realistic sports management and over-the-top 8-bit baseball action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Empereur, L'' (Japan)', '1989', NaN, 'Koei', '1', NaN, 'Turn-based strategy / Simulation.', 'Lead Napoleon Bonaparte to conquer Europe and establish an empire.', 'A deep and historically accurate grand strategy game by Koei.', 'Set during the Napoleonic Wars, players manage diplomacy, economy, and military tactics across a massive map of Europe, featuring the complex political landscape of the late 18th century.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Empereur, L'' (USA)', '1989', NaN, 'Koei', '1', NaN, 'Turn-based strategy / Simulation.', 'Lead Napoleon Bonaparte to conquer Europe and establish an empire.', 'A deep and historically accurate grand strategy game by Koei.', 'Set during the Napoleonic Wars, players manage diplomacy, economy, and military tactics across a massive map of Europe, featuring the complex political landscape of the late 18th century.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Eric Cantona Football Challenge - Goal! 2 (Europe)', '1994', NaN, 'Krisalis Software', '2', NaN, 'Sports / Soccer simulation.', 'Win the international cup by mastering the field with your soccer team.', 'A licensed European soccer game featuring the legendary Eric Cantona.', 'Known as Goal! 2 in the US, this version carries the endorsement of the French star, offering fast-paced 8-bit football with various team formations and tournament modes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Erika to Satoru no Yume Bouken (Japan)', '1988', NaN, 'Towachiki', '1', NaN, 'Point-and-click adventure.', 'Guide two children through a fairy tale world to return home safely.', 'A charming and colorful Japanese adventure game with a dual-protagonist system.', 'Players interact with various characters and solve environmental puzzles. It is famous for a hidden secret ending message that became a legendary piece of Famicom trivia.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Erunaaku no Zaihou (Japan)', '1987', NaN, 'Towachiki', '1', NaN, 'Side-scrolling action adventure.', 'Explore a mystical island to find hidden treasures and defeat guardians.', 'A challenging adventure game that blends platforming with cryptic secrets.', 'Known as The Treasure of Ernaaku, this title requires players to navigate complex stages and manage limited resources while fighting 8-bit mythological creatures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Escape from Atlantis, The (USA) (Unl) (Proto1)', '1995', NaN, 'Color Dreams', '1', NaN, 'Side-scrolling action platformer.', 'Escape the sinking city of Atlantis by navigating through dangerous ruins.', 'A rare unreleased prototype of an underwater-themed adventure.', 'This first prototype shows the early stages of development, featuring basic level design and mechanics focused on escaping environmental hazards and traps.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Escape from Atlantis, The (USA) (Unl) (Proto2)', '1995', NaN, 'Color Dreams', '1', NaN, 'Side-scrolling action platformer.', 'Escape the sinking city of Atlantis by navigating through dangerous ruins.', 'A more refined prototype of the unreleased Atlantis action game.', 'The second prototype features updated graphics and enemy placements, giving a clearer picture of what this unlicensed Color Dreams title would have been.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Esper Bouken Tai (Japan)', '1987', NaN, 'Jaleco', '1', NaN, 'Action platformer.', 'Use your psychic powers to clear stages of ghosts and find the exit.', 'A quirky Jaleco platformer where psychic abilities are the key to survival.', 'Players control a character who can jump high and use esper powers to defeat supernatural enemies in a series of increasingly difficult 8-bit haunted levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Esper Dream 2 - Aratanaru Tatakai (Japan)', '1992', NaN, 'Kotobuki Systems', '1', NaN, 'Action RPG with exploration.', 'Protect the world of books from an evil force using psychic magic.', 'A beautiful Konami sequel that blends real-time combat with RPG depth.', 'Featuring the VRC6 chip for enhanced music, Esper Dream 2 tasks players with entering different book-worlds, upgrading their esper gear, and fighting bosses in strategic arenas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Esper Dream 2 - Aratanaru Tatakai (Japan) [En by Aeon Genesis v1.0]', '1992', NaN, 'Kotobuki Systems', '1', NaN, 'Action RPG with exploration.', 'Protect the world of books from an evil force using psychic magic.', 'The English translation of Konami''s high-quality sequel, Esper Dream 2.', 'This translation makes the heartwarming story and complex magic systems accessible, allowing players to fully enjoy one of the Famicom''s most polished action-RPGs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Excitebike (Europe)', '1984', NaN, 'Nintendo', '2', NaN, 'Motocross racing.', 'Race against the clock and other riders to qualify for the championship.', 'A foundational Nintendo classic featuring iconic jumps and a track editor.', 'Players must manage the bike''s engine temperature while navigating obstacles. It is famous for being one of the first home console games to allow players to design their own tracks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Excitebike (Japan, USA)', '1984', NaN, 'Nintendo', '2', NaN, 'Motocross racing.', 'Race against the clock and other riders to qualify for the championship.', 'A foundational Nintendo classic featuring iconic jumps and a track editor.', 'Players must manage the bike''s engine temperature while navigating obstacles. It is famous for being one of the first home console games to allow players to design their own tracks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Exciting Boxing (Japan)', '1987', NaN, 'Konami', '2', NaN, 'Sports / Boxing simulation.', 'Rise through the ranks of the boxing world to become the world champion.', 'A unique boxing game designed for use with an inflatable peripheral.', 'Developed by Konami, this title was intended to be played with a physical punching bag controller, offering an early and experimental motion control 8-bit experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Exciting Rally - World Rally Championship (Japan)', '1991', NaN, 'Konami', '1', NaN, 'Racing / Rally simulation.', 'Compete in international rally stages and achieve the fastest time.', 'A challenging top-down rally racer with official WRC-style themes.', 'Players must listen to co-driver cues and manage car damage across various terrains, making it one of the more realistic racing simulations on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Exciting Rally - World Rally Championship (Japan) [En by Klepto v1.0]', '1991', NaN, 'Konami', '1', NaN, 'Racing / Rally simulation.', 'Compete in international rally stages and achieve the fastest time.', 'The English translation of the technical rally simulator, Exciting Rally.', 'This version translates the navigator''s instructions and car tuning menus, making the strategic depth of this 8-bit racer clear for international fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Exed Exes (Japan)', '1985', NaN, 'Capcom', '1', NaN, 'Vertical-scrolling shoot ''em up.', 'Fly through insect-themed stages and destroy the alien swarm.', 'A classic Capcom arcade port featuring intense shooting and bug enemies.', 'Known for its high enemy density and fruit point bonuses, Exed Exes challenges players to survive waves of mechanical insects in a relentless 8-bit space battle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Exerion (Japan)', '1985', NaN, 'Jaleco', '1', NaN, 'Fixed-screen shooter.', 'Defend against waves of alien ships while managing the inertia of your craft.', 'An early arcade port famous for its unique momentum-based movement.', 'Unlike other shooters, the ship in Exerion has weight and slides, requiring players to master the physics to accurately target enemies over a 3D-effect background.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F-1 Race (Japan)', '1984', NaN, 'Nintendo', '2', NaN, 'Behind-the-car racing.', 'Compete in high-speed Formula 1 races and reach the finish line.', 'An early and fast-paced 8-bit take on professional open-wheel racing.', 'Developed by HAL Laboratory, this title focuses on pure speed and cornering, featuring multiple tracks and a challenging AI that tests the player''s 8-bit driving skills.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F-1 Sensation (Japan)', '1990', NaN, 'Sunsoft', '1', NaN, 'Behind-the-car racing simulation.', 'Master professional racing circuits to win the F1 World Championship.', 'One of the most technically advanced racing games on the Famicom.', 'Also known as Formula 1 Sensation, it features real-world tracks, car customization, and impressive scaling graphics that provide a sense of high-speed immersion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F-15 Strike Eagle (Europe)', '1992', NaN, 'MicroProse', '1', NaN, 'Flight combat simulation.', 'Complete various modern air combat missions across the globe.', 'A complex and realistic flight simulator based on the famous fighter jet.', 'Players must manage radar, multiple weapon systems, and flight controls in a first-person cockpit view, engaging in dogfights and bombing runs in several theaters of war.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F-15 Strike Eagle (France) (En,Fr,Nl)', '1992', NaN, 'MicroProse', '1', NaN, 'Flight combat simulation.', 'Complete various modern air combat missions across the globe.', 'La version française du simulateur de combat aérien F-15 Strike Eagle.', 'This localized version allows French-speaking players to navigate the complex cockpit controls and mission objectives of this 8-bit military simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F-15 Strike Eagle (Italy)', '1992', NaN, 'MicroProse', '1', NaN, 'Flight combat simulation.', 'Complete various modern air combat missions across the globe.', 'La versione italiana del simulatore di volo militare F-15 Strike Eagle.', 'This Italian edition brings the intense aerial combat and strategic mission planning of the F-15 to the local NES market with translated materials.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F-15 Strike Eagle (Sweden) (Sv,Da,Fi)', '1992', NaN, 'MicroProse', '1', NaN, 'Flight combat simulation.', 'Complete various modern air combat missions across the globe.', 'Den svenska versionen av den avancerade flygsimulatorn F-15 Strike Eagle.', 'Localized for the Scandinavian market, this version offers the same deep military simulation and cockpit-based action for fans of 8-bit flight games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F-15 Strike Eagle (USA)', '1992', NaN, 'MicroProse', '1', NaN, 'Flight combat simulation.', 'Complete various modern air combat missions across the globe.', 'A complex and realistic flight simulator based on the famous fighter jet.', 'Players must manage radar, multiple weapon systems, and flight controls in a first-person cockpit view, engaging in dogfights and bombing runs in several theaters of war.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F1 Circus (Japan)', '1990', NaN, 'Nichibutsu', '2', NaN, 'Top-down racing.', 'Master the Formula 1 circuits and win the world championship.', 'A fast-paced top-down racer known for its sense of speed and technical tracks.', 'F1 Circus offers a professional racing experience with car tuning and realistic pit stops, challenging players to master cornering in various weather conditions on the 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F15 City War (USA) (Unl) (v1.0)', '1992', NaN, 'Color Dreams', '1', NaN, 'Behind-the-car shooter.', 'Fly through city streets and destroy enemy tanks and planes.', 'An unlicensed pseudo-3D flight shooter with intense action.', 'Published by AVE, this game features fast-paced combat where you pilot an F15 through urban landscapes, dodging buildings while locking onto targets in a relentless arcade-style battle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'F15 City War (USA) (Unl) (v1.1)', '1992', NaN, 'Color Dreams', '1', NaN, 'Behind-the-car shooter.', 'Fly through city streets and destroy enemy tanks and planes.', 'A revised version of the unlicensed 3D-style aerial shooter.', 'This updated version fixes minor graphical glitches and improves the game''s stability, offering the same high-octane city-based flight combat for the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Doubutsu Seitai Zukan! - Katte ni Shirokuma - Mori wo Sukue no Maki! (Japan)', '1995', NaN, 'Nintendo', '1', NaN, 'Adventure / Mini-games.', 'Help the polar bear Shirokuma save the forest through various tasks.', 'A quirky adventure based on a popular Japanese manga series.', 'Featuring a unique art style, players must guide Shirokuma through several levels filled with humor and mini-games to protect his animal friends and their environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Igo Nyuumon (Japan)', '1985', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Learn the rules of Igo (Go) and defeat various opponents.', 'An introductory simulation of the classic oriental board game Go.', 'This title acts as a digital tutor for the complex game of Go, featuring tutorials for beginners and a computer AI to practice strategic stone placement.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Jump - Eiyuu Retsuden (Japan)', '1989', NaN, 'Bandai', '1', NaN, 'Action RPG crossover.', 'Unify the heroes of Shonen Jump to defeat an alliance of villains.', 'An epic crossover featuring Goku, Kenshiro, Pegasus Seiya, and more.', 'To celebrate the magazine''s anniversary, this game blends top-down exploration with action segments, allowing players to control 16 different legendary manga protagonists.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Jump II - Saikyou no 7 Nin (Japan)', '1991', NaN, 'Bandai', '1', NaN, 'Turn-based RPG crossover.', 'Lead 7 chosen heroes to save the world from an ancient evil force.', 'A more traditional RPG sequel featuring iconic manga characters.', 'Developed by Chunsoft, this sequel features Goku, Jotaro Kujo, and others in a strategic grid-based combat system with a deep story and improved 8-bit graphics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Meijin Sen (Japan)', '1986', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Climb the ranks of professional Igo to reach the Meijin title.', 'A competitive and deep simulation of the board game Go.', 'Targeted at experienced players, this title features advanced AI and official tournament rules, allowing fans to test their 8-bit strategy against a digital grandmaster.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Meijin Sen (Japan) (Rev A)', '1986', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Climb the ranks of professional Igo to reach the Meijin title.', 'A revised version of the professional Go simulation game.', 'This revision includes minor bug fixes and logic improvements to the AI, ensuring a more stable and fair competitive experience for Go enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Shougi - Ryuuousen (Japan)', '1985', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Defeat opponents in Japanese chess to win the Ryuuousen title.', 'A faithful simulation of Shougi, the complex Japanese chess variant.', 'Players can choose different difficulty levels and practice their openings and endgames in this traditional 8-bit strategy experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Top Management (Japan)', '1988', NaN, 'Koei', '1', NaN, 'Business simulation.', 'Manage a Japanese electronics company to become a market leader.', 'A deep and complex corporate management simulator.', 'Players must handle R&D, advertising, and financial reports to grow their business, offering a unique and serious take on economic strategy on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Wars (English)', '1988', NaN, 'Nintendo', '2', NaN, 'Turn-based strategy.', 'Outmaneuver the enemy army and capture their headquarters.', 'The English translation of the game that started the Wars franchise.', 'This translation makes the tactical menus and unit stats accessible, allowing fans to play the precursor to Advance Wars with full understanding of the mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Wars (Japan) (Rev 0B)', '1988', NaN, 'Nintendo', '2', NaN, 'Turn-based strategy.', 'Outmaneuver the enemy army and capture their headquarters.', 'The legendary first entry in Nintendo''s premier strategy series.', 'Featuring two warring nations (Red Star and Blue Moon), players manage land, sea, and air units on hex-based maps to achieve military dominance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Wars (Japan) (Rev 0B) [En by Aka v1.11]', '1988', NaN, 'Nintendo', '2', NaN, 'Turn-based strategy.', 'Outmaneuver the enemy army and capture their headquarters.', 'An updated English version of the classic tactical war game.', 'This version features further refinements to the translation and fixes minor bugs, providing the smoothest English experience for this 8-bit strategy masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famicom Yakyuu Ban (Japan)', '1986', NaN, 'Nintendo', '2', NaN, 'Sports / Baseball.', 'Win the professional baseball league using your team''s stats.', 'A classic baseball game featuring real Japanese team inspirations.', 'Focused on the Yakyuu Ban board game style, it offers simple yet addictive baseball mechanics that emphasize timing and pitch selection.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Block (Japan)', '1987', NaN, 'Namco', '2', NaN, 'Brick-breaking action.', 'Clear all blocks using a paddle and ball across various stages.', 'Namco''s unique take on the Arkanoid or Breakout genre.', 'Family Block features creative level designs and various power-ups, challenging players to master the physics of the bouncing ball to reach high scores.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Boxing (Japan)', '1987', NaN, 'Namco', '2', NaN, 'Sports / Boxing.', 'Win the heavyweight title by knocking out all your opponents.', 'A fast-paced 8-bit boxing game with a focus on stamina.', 'Known as Ring King in the West, this title features intense boxing action where players must manage their energy and time their punches to win the belt.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Circuit ''91 (Japan)', '1991', NaN, 'Namco', '2', NaN, 'Top-down racing.', 'Compete in professional racing circuits and win the championship.', 'A polished sequel to Namco''s popular top-down racing series.', 'Featuring improved car customization and a variety of real-world tracks, this 1991 release offers one of the most complete racing experiences on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Circuit (Japan)', '1987', NaN, 'Namco', '2', NaN, 'Top-down racing.', 'Compete in professional racing circuits and win the championship.', 'The foundational title of Namco''s acclaimed 8-bit racing series.', 'Focused on car setups and precision driving, Family Circuit established the mechanics that would define many future top-down racers in the 8-bit era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Computer Othello (Japan)', '1986', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Flip the opponent''s pieces to have the most colors on the board.', 'A clean and simple digital version of the classic board game Othello.', 'Featuring multiple difficulty levels, this game is a perfect 8-bit recreation of the Reversi rules, offering quick and challenging strategic matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Feud (USA)', '1991', NaN, 'Ludotek', '2', NaN, 'Game show / Trivia.', 'Guess the most popular survey answers to win the prize money.', 'An 8-bit adaptation of the famous American television game show.', 'Players compete as a family, answering humorous and general knowledge survey questions to reach the Fast Money round in this faithful TV recreation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Jockey (Japan)', '1986', NaN, 'Namco', '1', NaN, 'Sports / Horse racing.', 'Bet on or race horses to become the top jockey in the circuit.', 'Namco''s charming and colorful take on horse racing simulation.', 'Blending betting strategy with arcade-style control over the horse, Family Jockey features various tracks, obstacles, and horse stats to manage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Mahjong (Japan)', '1987', NaN, 'Namco', '2', NaN, 'Board game / Strategy.', 'Win hands of Mahjong against various computer-controlled opponents.', 'A traditional Japanese Mahjong simulation for the Famicom.', 'Featuring the standard Riichi Mahjong rules, this title allows players to practice their skills against digital rivals in a clean 8-bit interface.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Mahjong (Japan) (Rev A)', '1987', NaN, 'Namco', '2', NaN, 'Board game / Strategy.', 'Win hands of Mahjong against various computer-controlled opponents.', 'A revised version of Namco''s initial Mahjong simulation.', 'This revision includes minor adjustments to the AI''s logic and hand scoring to ensure a more accurate representation of the traditional game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Mahjong II - Shanghai heno Michi (Japan) (Rev A)', '1990', NaN, 'Namco', '2', NaN, 'Board game / Strategy.', 'Win Mahjong tournaments across various cities in the Shanghai mode.', 'An expanded sequel featuring more modes and better animations.', 'Family Mahjong II introduces a travel mode where the player competes in different regions, adding a sense of progression to the classic tile-based strategy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Pinball (Japan)', '1987', NaN, 'Namco', '2', NaN, 'Pinball simulation.', 'Get the highest score across themed tables based on Namco characters.', 'A vibrant pinball game featuring Pac-Man and other Namco icons.', 'Also known as Rock ''n'' Ball in the West, this title offers several unique tables with different physics and bonus stages, bringing a polished arcade pinball experience to the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Quiz (Japan)', '1987', NaN, 'Namco', '2', NaN, 'Trivia / Game Show.', 'Answer questions correctly to defeat opponents in a digital quiz show.', 'A multi-genre trivia game designed for Japanese Famicom fans.', 'Players choose characters and compete in various quiz categories. It’s a great example of the social gaming trend on the 8-bit hardware, focusing on general knowledge and quick thinking.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family School (Japan)', '1988', NaN, 'Namco', '1', NaN, 'Educational / Mini-games.', 'Complete various academic and logic challenges to graduate.', 'An educational title designed to help children learn through 8-bit gaming.', 'This game features several mini-games focused on math, language, and logic, using the Family series'' charming aesthetic to make learning interactive and fun.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Tennis (Japan)', '1987', NaN, 'Namco', '2', NaN, 'Sports / Tennis.', 'Win the tournament by defeating professional-style 8-bit opponents.', 'A fast and responsive tennis simulation, known in the West as World Court.', 'Family Tennis offers tight controls and multiple court surfaces. It features a colorful cast of players and was highly praised for its realistic (for the era) ball physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer - Aerobics Studio (Japan)', '1987', NaN, 'Bandai', '1', NaN, 'Fitness / Rhythm.', 'Follow the instructor''s aerobic routines using the Power Pad.', 'A health-focused rhythm game that uses the Famicom''s floor mat controller.', 'Known as Dance Aerobics in the US, players must step on the mat in time with the music to stay fit, offering a unique full-body workout experience on the 8-bit console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer - Daiundoukai (Japan)', '1987', NaN, 'Bandai', '1', NaN, 'Sports / Athletics.', 'Compete in a series of athletic events using the Power Pad mat.', 'A competitive track and field game that requires physical movement.', 'Players use their feet to run and jump in various school-style sports events, making it a staple of the Family Trainer series and its physical interaction.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer - Jogging Race (Japan)', '1987', NaN, 'Bandai', '1', NaN, 'Fitness / Racing.', 'Jog through city streets and parks to finish the course using the mat.', 'A physical jogging simulator that turns the Power Pad into a treadmill.', 'This game encourages players to jog in place on the mat to move their character through scenic routes, focusing on stamina and physical activity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer - Manhattan Police (Japan)', '1987', NaN, 'Bandai', '1', NaN, 'Action / Simulation.', 'Chase down criminals through the streets of New York using the mat.', 'A physical action game where you run through the city to catch crooks.', 'Known in the US as Street Cop, players must step on the Power Pad to move and arrest suspects, blending traditional 8-bit action with physical exercise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer - Meiro Daisakusen (Japan)', '1987', NaN, 'Bandai', '1', NaN, 'Puzzle / Exploration.', 'Navigate through complex 3D-style mazes using the Power Pad.', 'A first-person maze game that requires physical steps to move.', 'Players must explore labyrinths by stepping on the mat, combining spatial puzzle-solving with physical movement in a unique 8-bit hybrid.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer - Rairai Kyonsees (Japan)', '1987', NaN, 'Bandai', '1', NaN, 'Action / Adventure.', 'Defeat the Jiangshi (hopping ghosts) using movement and items.', 'A physical action game based on the Chinese vampire (Kyonsee) myth.', 'Players use the Power Pad to navigate and fight off supernatural enemies in various themed stages, blending folklore with the unique mat-based controls.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer - Rairai Kyonsees (Japan) (Beta)', '1987', NaN, 'Bandai', '1', NaN, 'Action / Adventure.', 'Defeat the Jiangshi using movement and items.', 'A rare prototype version of the ghost-hunting Power Pad game.', 'This beta offers a look at the game''s development, with potential differences in enemy hitboxes or music before the final Japanese release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer - Running Stadium (Japan)', '1987', NaN, 'Bandai', '1', NaN, 'Sports / Athletics.', 'Win gold medals in various track events using the Power Pad.', 'The foundational Power Pad athletics game, known as World Class Track Meet.', 'Famous for its 100m dash and hurdles, this title became a global hit as players literally ran in place to beat their 8-bit rivals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer - Totsugeki! Fuuun Takeshi Jou (Japan)', '1986', NaN, 'Bandai', '1', NaN, 'Action / Variety.', 'Survive the crazy obstacles of the Takeshi''s Castle game show.', 'A physical challenge game based on the legendary Takeshi''s Castle.', 'Players must use the Power Pad to survive the chaotic and humorous mini-games of the hit TV show, requiring both timing and physical effort.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer 1 - Athletic World (Japan)', '1986', NaN, 'Bandai', '1', NaN, 'Sports / Variety.', 'Complete five different physical training courses to become a master.', 'The first entry in the Family Trainer series, focusing on diverse physical tasks.', 'Athletic World features various challenges like animal hurdles and dark tunnels, designed to introduce players to the fun of the Power Pad peripheral.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Family Trainer 9 - Fuuun! Takeshi Jou 2 (Japan)', '1987', NaN, 'Bandai', '1', NaN, 'Action / Variety.', 'Face even crazier challenges in the sequel to the Takeshi''s Castle game.', 'An expanded sequel with more mini-games based on the famous TV show.', 'This version features even more creative and difficult obstacles that require players to jump, run, and step to progress through the castle''s defenses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famista ''89 - Kaimaku Ban!! (Japan)', '1989', NaN, 'Namco', '2', NaN, 'Sports / Baseball.', 'Lead your team to the pennant in the 1989 Japanese league.', 'A refined entry in the legendary Family Stadium baseball series.', 'Featuring updated rosters and smoother animations, this ''89 edition solidified Namco''s dominance in the 8-bit baseball market in Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famista ''90 (Japan) (Rev 0A)', '1990', NaN, 'Namco', '2', NaN, 'Sports / Baseball.', 'Win the championship with updated 1990 team rosters.', 'The first Famista of the 90s, featuring improved player logic.', 'Known for its accessible yet deep gameplay, Famista ''90 continued the tradition of providing the most popular baseball simulation on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famista ''91 (Japan)', '1991', NaN, 'Namco', '2', NaN, 'Sports / Baseball.', 'Compete in the 1991 season with new players and team stats.', 'A polished 8-bit baseball title with improved graphics and faster play.', 'This version added more detail to the stadiums and players, keeping the series fresh for the millions of baseball fans in Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famista ''92 (Japan)', '1992', NaN, 'Namco', '2', NaN, 'Sports / Baseball.', 'Lead your favorite team to victory in the 1992 pro baseball season.', 'A high-quality baseball sim featuring real-world player inspirations.', 'By ''92, the Famista engine was incredibly polished, offering the best balance of arcade fun and sports simulation for the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famista ''93 (Japan)', '1993', NaN, 'Namco', '2', NaN, 'Sports / Baseball.', 'Win the league with the most accurate 1993 team data.', 'One of the final and most complete 8-bit baseball games on the system.', 'Featuring advanced AI and a wide variety of teams, this title represents the peak of the Famista series on the 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Famista ''94 (Japan)', '1994', NaN, 'Namco', '2', NaN, 'Sports / Baseball.', 'Compete in the final 8-bit Famicom baseball season of 1994.', 'The ultimate and final entry of the Famista series for the Famicom.', 'Released at the very end of the console''s life, it features the most refined graphics and the most complete rosters ever seen in an 8-bit Famista game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fan Kong Jing Ying (China) (Unl)', 'Unlicensed', NaN, 'Unknown', '2', NaN, 'Side-scrolling run and gun.', 'Infiltrate enemy bases and eliminate terrorist threats.', 'An unlicensed Chinese action game featuring Counter-Strike themes.', 'This bootleg title attempts to capture the tactical feel of modern shooters in a side-scrolling format, featuring varied weapons and intense combat segments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fantastic Adventures of Dizzy, The (USA) (Unl)', '1991', NaN, 'Codemasters', '1', NaN, 'Side-scrolling adventure / Puzzle.', 'Explore the kingdom of Zakeria to rescue Daisy and defeat the evil Zaks.', 'A massive, non-linear adventure featuring the famous Egg hero, Dizzy.', 'Published by Camerica, this unlicensed gem features a huge interconnected world. Players must collect items and solve inventory-based puzzles while navigating platforming challenges and various mini-games like bubble-riding and minecart races.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fantasy Zone (Japan)', '1986', NaN, 'Sega', '1', NaN, 'Side-scrolling shooter.', 'Destroy all enemy bases in each zone to face the final boss.', 'A colorful cute ''em up featuring the sentient ship, Opa-Opa.', 'Unlike traditional shooters, players can fly both left and right. Collecting coins from defeated enemies allows players to buy weapon and engine upgrades in a mid-stage shop.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fantasy Zone (USA) (Unl)', '1986', NaN, 'Sega', '1', NaN, 'Side-scrolling shooter.', 'Travel through warp holes to destroy bases in different sub-levels.', 'An expansive sequel to the vibrant arcade hit with more complex levels.', 'This sequel introduces a world-warping mechanic where players must clear bases in multiple dimensions (Bright Side and Dark Side) to progress to the area''s guardian.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fantasy Zone 2 - Opa-Opa no Namida (Japan)', '1987', NaN, 'Sega', '1', NaN, 'Action RPG with exploration.', 'Rescue the kidnapped princess and uncover the truth behind the King''s curse.', 'A unique Famicom RPG that blends overhead travel with side-scrolling combat.', 'Faria is known for its steep difficulty and interesting world. Players must manage inventory, talk to villagers for clues, and master real-time combat in both top-down and action perspectives.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Faria - A World of Mystery & Danger! (USA)', '1991', NaN, 'GameTek', '1', NaN, 'Side-scrolling action RPG.', 'Journey to the top of the World Tree to save the Elves from the Dwarves.', 'A gritty and atmospheric spin-off of the Dragon Slayer series.', 'Featuring a unique brown-toned aesthetic and deep lore, players buy equipment and spells to navigate the massive branches and roots of the World Tree in a non-linear quest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Faria (Japan)', '1991', NaN, 'GameTek', '1', NaN, 'Side-scrolling action platformer.', 'Rescue Felix''s girlfriend, Kitty, from the Professor''s mechanical island.', 'A visually stunning platformer where Felix uses his Magic Bag of Tricks.', 'Felix can transform into various vehicles (tanks, planes, submarines) by collecting hearts. It is highly praised for its smooth controls and high-quality 8-bit animations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Faxanadu (Europe)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Behind-the-car racing.', 'Master the Formula 1 season and lead the Ferrari team to victory.', 'An officially licensed racing simulator focused on the Ferrari brand.', 'Developed by Pony Canyon, this title features real tracks and car tuning options, challenging players to manage tires and fuel while competing against professional 8-bit AI drivers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Faxanadu (Japan)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling adventure (Proto).', 'Navigate through Chicago to enjoy your day off without getting caught.', 'A rare, unreleased prototype based on the classic 80s movie.', 'This unreleased title shows an early attempt to bring the movie''s charm to the NES, featuring level exploration and mini-games inspired by Ferris''s adventures in the city.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Faxanadu (USA)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Top-down strategy / Shooter.', 'Capture enemy units and use them to help you infiltrate the base.', 'A unique tactical shooter where you turn enemies into allies.', 'Players control a ship that can suck up enemy soldiers and vehicles, allowing them to be redeployed as friendly units to create a strategic advantage on the battlefield.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Faxanadu (USA) (Rev A)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Sports / Soccer simulation.', 'Win the world tournament with your favorite international team.', 'An unlicensed 8-bit port of the famous isometric soccer franchise.', 'This bootleg attempts to replicate the 16-bit FIFA experience on the NES, featuring a simplified isometric view and basic tournament modes for soccer fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Faxanadu (USA) (Rev A) [Graphic Hack by Safaribans v20070422] (Uncensored Edition)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Sports / Golf simulation.', 'Master several professional courses to win the world tournament.', 'An early SNK golf game featuring professional player Lee Trevino.', 'Known for its precision controls and various terrain types, Fighting Golf allows players to choose between different golfers, each with unique power and accuracy stats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Faxanadu (USA) [Graphic Hack by Safaribans v20070422] (Uncensored Edition)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Vertical-scrolling shooter.', 'Fly your combat jet through enemy lines to destroy their fortress.', 'A fast-paced unlicensed military shooter with intense bullet patterns.', 'Published by Sachen, this title challenges players with relentless waves of aircraft and ground turrets, requiring quick reflexes and power-up management to survive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Faxanadu (USA) [Hack by Ice Ranger v1.0] (~Faxanadu Facelift) (Uncensored+Color Edit)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Turn-based RPG.', 'Lead the four Warriors of Light to restore the crystals and save the world.', 'The foundational epic that launched one of gaming''s biggest franchises.', 'Final Fantasy introduced the concept of choosing a party of different classes (Warrior, Mage, etc.) and traveling across a massive world map with airships and sailing boats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'FC Genjin - Freakthoropus Computerus (Japan)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Turn-based RPG compilation.', 'Experience the first two epic journeys of the Warriors of Light.', 'A two-in-one Famicom cartridge featuring the series'' origins.', 'This rare late-era Famicom release includes both games on a single high-capacity mapper, featuring minor bug fixes over the original stand-alone releases.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Felix The Cat (Dragon Co.) (Unl)', '1992', NaN, 'Shimada Kikaku', '1', NaN, 'Turn-based RPG.', 'Lead a rebellion against the Palamecian Empire and stop the Emperor.', 'A bold sequel that introduced a unique stat-growth leveling system.', 'Instead of traditional XP, characters improve their skills by using them. It features a more character-driven story and the first appearance of the iconic Chocobos.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Felix the Cat (Europe)', '1992', NaN, 'Shimada Kikaku', '1', NaN, 'Turn-based RPG.', 'Explore a floating continent and save the world from the cloud of darkness.', 'The most advanced 8-bit Final Fantasy, featuring the first Job System.', 'Players can switch their characters'' classes at any time to adapt to different dungeons. It is famous for its massive scope, multiple world maps, and summoning magic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Felix the Cat (USA)', '1992', NaN, 'Shimada Kikaku', '1', NaN, 'Behind-the-car racing.', 'Compete in high-speed Formula 1 races across several world tracks.', 'A faithful Namco port of the popular arcade racing hit.', 'Final Lap focuses on high-speed drifting and drafting. It was one of the first NES games to allow for 2-player split-screen racing via the link feature on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Feng Shen Bang (Asia) (Unl)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Action / Snake variant.', 'Navigate through mazes and grow your dragon by eating items.', 'An unlicensed Chinese game featuring classic Snake mechanics.', 'This title features colorful 8-bit graphics and multiple levels where the player must avoid their own tail and environmental hazards while growing their fire dragon.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ferrari - Grand Prix Challenge (Europe)', '1992', NaN, 'Sega', '1', NaN, 'Tactical turn-based RPG.', 'Lead Prince Marth and his army to reclaim the kingdom of Altea.', 'The legendary first entry in the premier tactical RPG series.', 'Fire Emblem combined RPG stat growth with grid-based strategy. It is famous for permanent death, where losing a character in battle means they are gone for good.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ferrari - Grand Prix Challenge (Japan)', '1992', NaN, 'Sega', '1', NaN, 'Tactical turn-based RPG.', 'Follow Alm and Celica as they fight to end the war on Valentia.', 'A unique sequel that added exploration and removed some restrictions.', 'Gaiden (Side-story) introduced third-person town exploration and simplified item management, while maintaining the deep tactical combat and permanent death the series is known for.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ferrari - Grand Prix Challenge (USA)', '1992', NaN, 'Sega', '1', NaN, 'Grid-based puzzle platformer.', 'Use ice blocks to extinguish all the flames in each room.', 'A polished prequel to Solomon''s Key focused on pure logic.', 'Known as Solomon''s Key 2 in Europe, this game challenges players to create and destroy ice blocks to navigate levels and solve increasingly complex spatial puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Field Combat (Japan)', '1985', NaN, 'Jaleco', '1', NaN, 'Top-down strategy / Shooter.', 'Capture enemy units and use them to help you infiltrate the base.', 'A unique tactical shooter where you turn enemies into allies.', 'Players control a ship that can suck up enemy units, allowing them to be redeployed as friendly forces. It requires strategic management of your captured army to overcome the enemy''s defenses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fighting Golf (Japan)', '1988', NaN, 'SNK', '1', NaN, 'Sports / Golf simulation.', 'Master several professional courses to win the world tournament.', 'An early SNK golf game featuring professional player Lee Trevino.', 'Known for its precision controls and various terrain types, Fighting Golf allows players to choose between different golfers, each with unique power and accuracy stats in a realistic 8-bit environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fighting Hero (Asia) (Unl)', 'Unlicensed', NaN, 'Unknown', '2', NaN, '2D Fighting game.', 'Defeat a series of martial arts experts to prove your strength.', 'An unlicensed fighting game for the Asian market featuring 8-bit combat.', 'This bootleg title attempts to bring the arcade fighting experience to the Famicom, featuring various characters with unique special moves and a traditional versus-style progression.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fighting Hero III (Asia) (Unl)', 'Unlicensed', NaN, 'Unknown', '2', NaN, '2D Fighting game.', 'Win the international martial arts tournament against tough rivals.', 'An unlicensed sequel with improved sprites and combat mechanics.', 'This third entry in the Fighting Hero series features more refined controls and larger character sprites, aiming to replicate the feel of 16-bit fighters on 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fighting Road (Japan)', '1988', NaN, 'Kid', '1', NaN, 'Side-scrolling beat ''em up / Fighting.', 'Fight through city streets to reach and win the final tournament.', 'A combat-heavy action game that blends brawling with one-on-one duels.', 'Players navigate through side-scrolling stages fighting thugs before entering professional fighting rings, requiring mastery of various martial arts techniques and timing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Combat (Asia) (Unl) (Famicom)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Vertical-scrolling shooter.', 'Fly your combat jet through enemy lines to destroy their fortress.', 'A fast-paced unlicensed military shooter with intense bullet patterns.', 'Released for the Famicom by Sachen, this title challenges players with relentless waves of aircraft and ground turrets, requiring quick reflexes and power-up management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Combat (Asia) (Unl) (NES)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Vertical-scrolling shooter.', 'Fly your combat jet through enemy lines to destroy their fortress.', 'The NES version of the unlicensed military shooter by Sachen.', 'Identical in gameplay to the Famicom version, this title provides high-intensity aerial combat and challenging boss fights for the Western NES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (Japan) (Rev 0A)', '1987', NaN, 'Square', '1', NaN, 'Turn-based RPG.', 'Lead the four Warriors of Light to restore the crystals and save the world.', 'The foundational epic that launched one of gaming''s biggest franchises.', 'Final Fantasy introduced the concept of choosing a party of different classes and traveling across a massive world map with airships, defining the future of the genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (Japan) (Rev B)', '1987', NaN, 'Square', '1', NaN, 'Turn-based RPG.', 'Lead the four Warriors of Light to restore the crystals and save the world.', 'A revised Japanese release of the original RPG with minor bug fixes.', 'This revision addresses small technical issues from the first print, ensuring a more stable experience for players embarking on the quest of the four crystals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (USA)', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG.', 'Lead the four Warriors of Light to restore the crystals and save the world.', 'The localized North American version of the legendary Square RPG.', 'Published by Nintendo, this version allowed Western players to experience the deep story and strategic combat that made the series a global phenomenon.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (USA) [Bug Fix by Karatorian v0.80] (Black Belt-Master Level Up Fix)', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG (Hack).', 'Save the world while using a fixed version of the Black Belt class.', 'A technical hack that fixes the famous level-up bug for the Black Belt.', 'In the original game, the Black Belt''s armor stat would reset under certain conditions. This fix ensures the class gains power correctly as it levels up, as originally intended.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (USA) [Hack by Goongyae v1.3] (Final Facelift)', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG (Hack).', 'Experience the classic quest with modernized 8-bit graphics and UI.', 'A visual overhaul hack that updates the sprites and menus of FF1.', 'This hack replaces the original character sprites and tiles with high-quality versions inspired by later entries, making the game more visually appealing for modern players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (USA) [Hack by Grond v1.1] (Balance+Bug Fixes)', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG (Hack).', 'Play a more polished version of the game with hundreds of bug fixes.', 'A comprehensive patch that fixes broken spells and gameplay glitches.', 'This hack fixes iconic issues like non-working spells (TMPR, SABR) and critical hit bugs, providing the most functional version of the original game''s mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (USA) [Hack by Grond v1.2] (~Final Fantasy Plus Plus - World of Chaos)', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG (Total Hack).', 'Navigate a vastly more difficult and altered version of the FF1 world.', 'A high-difficulty hack with new enemies and rearranged dungeons.', 'Part of the Plus Plus series, this version is designed for veterans, offering a punishing challenge with reworked stats and a more chaotic world layout.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (USA) [Hack by Grond v1.5] (~Final Fantasy Plus Plus)', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG (Total Hack).', 'Enjoy an expanded and refined version of the original adventure.', 'An extensive gameplay overhaul with new classes, items, and features.', 'This mod adds significant content to the original engine, including new character classes and rebalanced gameplay, making it feel like a modern director''s cut of the 8-bit classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (USA) [Hack by Kabucho v1.0] (~Quadruple Dragons)', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG (Hack).', 'Complete the quest with a party specifically modified for this hack.', 'A themed character hack that changes the party dynamics and visuals.', 'This modification replaces the standard Warriors of Light with unique dragon-themed sprites and adjustments, offering a fresh aesthetic for another playthrough.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy (USA) [Hack by Sliver X+Thaddeus v2.0Final] (~Dragoon X Omega II)', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG (Total Hack).', 'Survive a sci-fi epic built on the Final Fantasy engine.', 'A massive total conversion that turns FF1 into a space-age RPG.', 'Using the FF1 engine, this game features entirely new graphics, story, and world-building, proving the incredible flexibility of the 8-bit Final Fantasy framework.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy I & II (Japan)', '1994', NaN, 'Square', '1', NaN, 'Turn-based RPG compilation.', 'Experience the first two epic journeys of the Warriors of Light.', 'A two-in-one Famicom cartridge featuring the series'' origins.', 'This late-era release includes both games on a single high-capacity cartridge, allowing players to play the first two legendary quests in one package.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy I & II (Japan) [En by Demiforce v1.0]', '1994', NaN, 'Square', '1', NaN, 'Turn-based RPG compilation.', 'Experience the first two epic journeys in English.', 'The English fan translation of the Famicom-exclusive dual cartridge.', 'Translated by Demiforce, this version allows English speakers to play both games with a consistent translation style on the original Famicom engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy I & II (Japan) [En by Demiforce v1.0] [Hack by Grond v1.0] (Unofficial Update)', '1994', NaN, 'Square', '1', NaN, 'Turn-based RPG compilation.', 'Experience the first two epic journeys with refined English text.', 'An updated version of the fan translation with improved bug fixes.', 'This unofficial update to the Demiforce translation fixes minor text overflows and technical glitches, providing a smoother experience for the English bundle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy II (Japan)', '1988', NaN, 'Square', '1', NaN, 'Turn-based RPG.', 'Lead a rebellion against the Palamecian Empire and stop the Emperor.', 'A bold sequel that introduced a unique stat-growth leveling system.', 'Instead of traditional XP, characters improve their skills by using them. It features a more character-driven story and the first appearance of Chocobos.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy II (Japan) [En by Demiforce v1.03] [Bug+Title Fixes by Parasyte v1.0] (Weapon-Magic Exploit Fix)', '1988', NaN, 'Square', '1', NaN, 'Turn-based RPG (Hack).', 'Play the rebellion story without the famous select-cancel bug.', 'A fan-translated version of FF2 that removes the infinite stat glitch.', 'This version fixes the exploit where players could rapidly level up weapons by selecting and canceling attacks, forcing a more natural and balanced progression.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy II (Japan) [En by Demiforce v1.03] [Hack by Lenophis+King Lettuce v1.0] [Title Fix by Parasyte v1.0] (Demonic Pandemonium)', '1988', NaN, 'Square', '1', NaN, 'Turn-based RPG (Hack).', 'Survive a much more difficult and dark version of the FF2 quest.', 'A difficulty-enhancement hack for the translated version of FF2.', 'This hack increases enemy power and modifies encounters to provide a Hard Mode experience for those who have already mastered the original Palamecian rebellion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy II (Japan) [En by Demiforce v1.03] [Title Fix by Parasyte v1.0]', '1988', NaN, 'Square', '1', NaN, 'Turn-based RPG.', 'Lead the rebellion with a polished English translation and title screen.', 'The standard English fan translation of FF2 with corrected title graphics.', 'Featuring the work of Demiforce and Parasyte, this is the classic way to experience the second entry of the series in English with a professional look.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy II (USA) (Proto)', '1988', NaN, 'Square', '1', NaN, 'Turn-based RPG.', 'Lead a rebellion against the Palamecian Empire.', 'An unreleased official English prototype of the second entry.', 'This prototype represents the cancelled 1991 North American release. It features the unique stat-growth system where characters improve skills through usage rather than XP.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy II (USA) (Proto) [Bug Fix by Parasyte v1.0] (Weapon-Magic Exploit Fix)', 'Unreleased', NaN, 'Square', '1', NaN, 'Turn-based RPG (Hack).', 'Defeat the Empire with a fixed, balanced progression system.', 'A patched version of the FFII prototype that removes the select-cancel exploit.', 'This version fixes the famous bug that allowed players to level up weapon and magic skills instantly, offering the intended tactical challenge of the rebellion story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy III (Japan)', 'Unreleased', NaN, 'Square', '1', NaN, 'Turn-based RPG with Job System.', 'Save the world from the Cloud of Darkness by mastering 22 character jobs.', 'The most advanced 8-bit FF, featuring the debut of the legendary Job System.', 'Final Fantasy III allows players to change character classes at any time. It features a massive world, summoning magic, and incredible technical achievements for the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy III (Japan) [En by A.W.Jackson+Neill Corlett+SoM2Freak v1.1]', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG with Job System.', 'Save the world from the Cloud of Darkness with full English text.', 'The definitive fan translation of the Famicom''s most ambitious RPG.', 'This translation by Neill Corlett and others allows English speakers to experience the deep story and complex mechanics of the original FF3 for the first time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy VII (C)', '1990', NaN, 'Square', '1', NaN, 'Turn-based RPG (Pirate).', 'Join Cloud and AVALANCHE to stop Shinra and Sephiroth.', 'An infamous unlicensed demake of the PlayStation classic for the NES.', 'Developed by Shenzhen Nanjing, this title attempts to port the entire PS1 story to 8-bit, featuring a unique combat system and MIDI-style recreations of the iconic soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Fantasy VII (China) (Unl) [En by Xaronyr EnCardier v0.97]', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Turn-based RPG (Pirate).', 'Join Cloud and AVALANCHE to stop Shinra and Sephiroth in English.', 'An English-translated version of the Chinese FFVII demake.', 'This fan translation makes the dialogue and menus of the ambitious bootleg accessible, allowing fans to play through the 8-bit version of Cloud''s journey.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Lap (Japan)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Behind-the-car racing.', 'Outpace rivals in high-speed Formula 1 circuits.', 'A faithful Namco port of the popular arcade racing hit.', 'Final Lap focuses on high-speed drifting and drafting. It was one of the first NES games to support split-screen racing via the Famicom''s expansion port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Mission (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Side-scrolling run and gun.', 'Fight through futuristic war zones to stop an alien invasion.', 'The original Japanese version of what became S.C.A.T. in the West.', 'Featuring jetpack-based movement and orbiting satellite orbs, Final Mission is known for its intense action, great co-op mode, and impressive industrial visual design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Mission (Japan) [En by Stardust Crusaders v1.0]', '1989', NaN, 'NMK', '1', NaN, 'Side-scrolling run and gun.', 'Fight through futuristic war zones with translated story elements.', 'An English fan translation that preserves the original Japanese difficulty.', 'This version keeps the harder difficulty and original cutscenes of Final Mission while making the narrative accessible to English-speaking players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Final Strikyu', '1989', NaN, 'NMK', '1', NaN, 'Sports / Baseball (Pirate).', 'Win the baseball championship using specialized 8-bit teams.', 'An unlicensed Chinese baseball game with simplified arcade mechanics.', 'Featuring fast-paced pitching and batting, this bootleg title offers a quick baseball experience for those looking for an alternative to the mainstream sports titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire ''n Ice (USA)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Grid-based puzzle platformer.', 'Use ice blocks to extinguish all the flames in each room.', 'A polished prequel to Solomon''s Key focused on pure logic.', 'Players must create and destroy ice blocks to navigate levels and solve increasingly complex spatial puzzles across several colorful and themed 8-bit worlds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire Dragon (Unl)', '1993', NaN, 'Technos', '2', NaN, 'Action / Maze puzzle.', 'Grow your dragon and avoid obstacles in a variety of mazes.', 'An unlicensed Chinese Snake variant with colorful graphics.', 'This title features multiple levels and power-ups, challenging players to collect items and grow their fire dragon without crashing into walls or their own tail.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire Emblem - Ankoku Ryuu to Hikari no Tsurugi (English)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Tactical turn-based RPG.', 'Lead Prince Marth to reclaim Altea and defeat the Shadow Dragon.', 'The first English translation of the legendary strategy-RPG debut.', 'This version brings the foundational tactical combat and permanent death mechanics of the Fire Emblem series to English-speaking strategy fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire Emblem - Ankoku Ryuu to Hikari no Tsurugi (Japan)', '1990', NaN, 'Nintendo', '1', NaN, 'Tactical turn-based RPG.', 'Lead Prince Marth to reclaim Altea and defeat the Shadow Dragon.', 'The legendary first entry in the premier tactical RPG series.', 'Fire Emblem combined RPG stat growth with grid-based strategy, setting the standard for the genre with its deep story and high-stakes combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire Emblem (Japan)', '1990', NaN, 'Nintendo', '1', NaN, 'Tactical turn-based RPG.', 'Lead Prince Marth to reclaim Altea and defeat the Shadow Dragon.', 'A revised Japanese release with minor technical fixes.', 'This revision ensures smoother performance and addresses small bugs in the original 1990 release of Prince Marth''s iconic tactical adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire Emblem (Japan) [En by Gaijin v0.10] (Incomplete)', '1990', NaN, 'Nintendo', '1', NaN, 'Tactical turn-based RPG.', 'Lead Prince Marth to reclaim Altea and defeat the Shadow Dragon.', 'An early, partially translated version of the first Fire Emblem.', 'This version serves as a historical look at the fan-translation scene, offering a look at the early efforts to bring Marth''s story to the West.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire Emblem [En by Quirino]', '1990', NaN, 'Nintendo', '1', NaN, 'Tactical turn-based RPG.', 'Lead Prince Marth to reclaim Altea and defeat the Shadow Dragon.', 'A high-quality and complete English translation of the first FE title.', 'This polished translation allows players to fully understand the intricate plot and tactical nuances of the Famicom''s most influential strategy game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire Emblem Gaiden (Japan)', '1992', NaN, 'Nintendo', '1', NaN, 'Tactical turn-based RPG.', 'Follow Alm and Celica as they fight to end the war on Valentia.', 'A unique sequel that added exploration and removed some restrictions.', 'Gaiden introduced third-person town exploration and simplified item management, while maintaining the deep tactical combat and permanent death mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire Emblem Gaiden (Japan) [En by J2e v0.97b2] [Fix by Starwolfs]', '1992', NaN, 'Nintendo', '1', NaN, 'Tactical turn-based RPG.', 'Follow Alm and Celica with a fully translated and bug-fixed script.', 'A highly refined English translation of the second Fire Emblem.', 'This version fixes text glitches and ensures a smooth narrative experience, making the non-traditional mechanics of Gaiden easy to enjoy in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fire Hawk (USA) (Unl)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Vertical-scrolling shooter.', 'Pilot a combat helicopter to destroy enemy targets and rescue allies.', 'An intense unlicensed helicopter shooter by Codemasters.', 'Featuring impressive scrolling and a variety of weapon upgrades, Fire Hawk challenges players to navigate through hostile territory while managing fuel and ammo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fisher-Price - Firehouse Rescue (USA)', '1991', NaN, 'Fisher-Price', '1', NaN, 'Educational / Action.', 'Drive the fire truck and rescue kittens from trees or people from fires.', 'A simple and fun educational game for young children.', 'Designed for a younger audience, this title uses basic controls and clear visuals to teach problem-solving and navigation through firehouse-themed missions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fisher-Price - I Can Remember (USA)', '1990', NaN, 'Fisher-Price', '1', NaN, 'Educational / Memory.', 'Match pairs of cards to reveal pictures and earn points.', 'A digital Concentration style memory game for kids.', 'Featuring colorful icons and simple 8-bit melodies, this game helps children develop memory skills by finding matching pairs within a grid of cards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fisher-Price - Perfect Fit (USA)', '1990', NaN, 'Fisher-Price', '1', NaN, 'Educational / Puzzle.', 'Match shapes and objects into their correct slots to clear the screen.', 'A shape-recognition puzzle game designed for early childhood learning.', 'This title focuses on visual matching and spatial reasoning, offering a friendly and non-competitive environment for children to learn basic geometric concepts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fist of the North Star (USA)', '1989', NaN, 'Atlus', '1', NaN, 'Side-scrolling beat ''em up.', 'Defeat the gangs of the wasteland and confront your rival, Shin.', 'A martial arts action game based on the legendary Hokuto no Ken anime.', 'As Kenshiro, players punch and kick through levels, causing enemies to explode. It is known for its high difficulty and iconic 8-bit martial arts action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flappy (Japan)', '1984', NaN, 'D.B. Soft', '1', NaN, 'Top-down puzzle.', 'Push the blue stone onto the yellow platform to clear each level.', 'A challenging 8-bit logic game featuring 200 levels of block-pushing fun.', 'Players must navigate obstacles and enemies while strategically moving stones. It requires careful planning to avoid getting trapped, offering a pure test of 8-bit spatial reasoning.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fleet Commander (Japan)', '1991', NaN, 'Namco', '1', NaN, 'Naval strategy / Simulation.', 'Lead your fleet to victory in tactical sea battles across various scenarios.', 'A deep and technical naval warfare simulator for the Famicom.', 'Developed by ASCII, this game focuses on fleet positioning, radar management, and strategic strikes, providing a serious military simulation experience on the hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flight of the Intruder (USA)', '1990', NaN, 'Spectrum HoloByte', '1', NaN, 'Flight combat simulation.', 'Complete dangerous bombing missions during the Vietnam War.', 'A realistic military flight simulator based on the famous novel and film.', 'Players control both the A-6 Intruder and the F-4 Phantom, managing cockpit instruments, radar, and carrier landings across multiple historical mission profiles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flintstones, The - The Rescue of Dino & Hoppy (Europe)', '1991', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer.', 'Find the scattered pieces of the time machine to rescue Dino and Hoppy.', 'A high-quality platformer featuring Fred Flintstone and his Bedrock world.', 'Developed by Taito, this game is praised for its colorful graphics and clever mechanics, such as Fred''s ability to grab ledges and use various Stone Age gadgets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flintstones, The - The Rescue of Dino & Hoppy (Japan)', '1991', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer.', 'Find the scattered pieces of the time machine to rescue Dino and Hoppy.', 'The original Japanese release of the polished Flintstones adventure.', 'Featuring the same high-tier production values as the Western versions, this Famicom title captures the charm of the cartoon with great 8-bit animations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flintstones, The - The Rescue of Dino & Hoppy (USA)', '1991', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer.', 'Find the scattered pieces of the time machine to rescue Dino and Hoppy.', 'A high-quality platformer featuring Fred Flintstone and his Bedrock world.', 'Developed by Taito, this game is praised for its colorful graphics and clever mechanics, such as Fred''s ability to grab ledges and use various Stone Age gadgets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flintstones, The - The Surprise at Dinosaur Peak! (Europe)', '1994', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer.', 'Stop a futuristic developer from turning Bedrock into a resort.', 'The second Flintstones NES title, featuring even more polished gameplay.', 'Known for its high rarity, this late-release allows players to switch between Fred and Barney, each with unique abilities needed to solve environmental puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flintstones, The - The Surprise at Dinosaur Peak! (USA)', '1994', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer.', 'Stop a futuristic developer from turning Bedrock into a resort.', 'One of the rarest and most expensive official NES titles ever released.', 'This version features top-notch graphics and the dual-character switching mechanic, representing the peak of 8-bit licensed platforming by Taito.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flipull - An Exciting Cube Game (Japan)', '1990', NaN, 'Taito', '1', NaN, 'Tile-matching puzzle.', 'Clear the required number of blocks by matching identical patterns.', 'An addictive and fast-paced puzzle game known as Plotting in the West.', 'Players throw blocks at a moving wall of tiles. It requires quick thinking and geometric strategy to create chains and clear the screen before time runs out.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flying Dragon - The Secret Scroll (USA)', '1989', NaN, 'Culture Brain', '1', NaN, '2D Fighting game / Action.', 'Master the Hiryu-no-Ken style to win the world martial arts tournament.', 'A hybrid action game that blends platforming with one-on-one combat.', 'Known as Hiryu no Ken in Japan, the game features a unique mark system in battles, where players must strike specific points on the opponent to deal damage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flying Hero (Japan)', '1989', NaN, 'Advance Communication Company', '1', NaN, 'Vertical-scrolling shoot ''em up.', 'Fly through fantasy stages to rescue the princess from the evil king.', 'A bright and colorful cute ''em up with a medieval fantasy theme.', 'Developed by Sting, players control a flying hero on a quest, collecting diverse power-ups and fighting giant, whimsical bosses in a fast-paced aerial battle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Flying Warriors (USA)', '1989', NaN, 'Culture Brain', '1', NaN, '2D Fighting game / Action.', 'Use your mystical powers to defeat the Dark Demon and his minions.', 'An evolved entry in the Culture Brain Hiryu no Ken fighting series.', 'This version features a superhero theme and enhanced combat mechanics, combining side-scrolling exploration with intense, mark-based martial arts duels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Formation Z (Japan)', '1985', NaN, 'Jaleco', '1', NaN, 'Side-scrolling shooter.', 'Transform between a robot and a jet to navigate through enemy lines.', 'An early Jaleco arcade port featuring a transforming protagonist.', 'Players must carefully manage their energy levels while switching forms to adapt to ground and air combat, fighting through a futuristic world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Formula 1 Sensation (Europe)', '1992', NaN, 'Sega', '1', NaN, 'Behind-the-car racing.', 'Master professional racing circuits to win the F1 World Championship.', 'One of the most technically advanced racing games on the NES.', 'Featuring real-world tracks, car customization, and impressive scaling graphics, it provides a sense of high-speed immersion that was rare on 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Formula One - Built to Win (USA)', '1990', NaN, 'SETA', '1', NaN, 'Behind-the-car racing / RPG.', 'Start as a rookie and earn your way to the Formula One world title.', 'A unique racing career simulator featuring RPG-style progression.', 'Players win races to earn money, buy parts, and upgrade through different car classes, from mini-cars to high-powered F1 machines across the USA.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Foton - The Ultimate Game on Planet Earth (Japan)', '1988', NaN, 'Pax Softnica', '1', NaN, '3D Wireframe shooter.', 'Navigate a first-person space environment to destroy enemy drones.', 'A technical feat for the Famicom, featuring early 3D wireframe visuals.', 'Based on a Japanese sci-fi franchise, Foton tasks players with navigating a vector-style space combat zone, requiring precision aiming and navigation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Foton - The Ultimate Game on Planet Earth (Japan) [En by KingMike v1.0Beta] (~Soldier of Light Photon)', '1988', NaN, 'Pax Softnica', '1', NaN, '3D Wireframe shooter.', 'Navigate a first-person space environment to destroy enemy drones.', 'The English fan translation of the technical space shooter Foton.', 'This translation makes the menus and mission briefings of the complex 3D shooter accessible, allowing players to master the vector-based combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Four Players'' Tennis (Europe)', '1989', NaN, 'Nintendo', '4', NaN, 'Sports / Tennis.', 'Win the grand slam tournament either solo or with up to four players.', 'A technical tennis simulation that supports the NES Four Score.', 'Known as Top Player''s Tennis in the US, it emphasizes realistic positioning and shot types, featuring endorsements from Chris Evert and Ivan Lendl.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Frankenstein - The Monster Returns (USA)', '1991', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer.', 'Traverse the village and castle to stop the monster''s creator.', 'A dark action-adventure game based on the gothic horror legend.', 'Players control a hero armed with a sword and magic, navigating through atmospheric environments filled with traps and undead enemies to confront the monster.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Freddy VS Jason', '1991', NaN, 'Taito', '1', NaN, 'Side-scrolling action (Hack).', 'Survive the ultimate clash between the two biggest horror icons.', 'A creative horror crossover hack that pits Freddy against Jason.', 'This modification of a classic engine allows fans to experience a dream match-up between the icons of A Nightmare on Elm Street and Friday the 13th in 8-bit form.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Free Fall (USA) (Proto)', 'Unreleased', NaN, 'Nintendo', '1', NaN, 'Falling-block puzzle.', 'Match shapes and clear the screen in this unreleased 8-bit puzzler.', 'An unreleased prototype from Vic Tokai featuring gravity-based physics.', 'This prototype offers a look at a canceled project where pieces fall and interact in unique ways, providing a fresh take on the classic puzzle genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Freedom Force (USA)', '1988', NaN, 'Sunsoft', '1', NaN, 'Light gun shooter.', 'Take down terrorists and defuse bombs to save the city.', 'An intense NES Zapper game focused on precision and speed.', 'Players must shoot enemies while avoiding civilians, with the action moving through various urban environments in a high-stakes counter-terrorism mission.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Friday the 13th (USA)', '1989', NaN, 'Atlus', '1', NaN, 'Survival horror / Action.', 'Protect the campers at Camp Crystal Lake and defeat Jason Voorhees.', 'A unique and atmospheric horror game featuring the iconic slasher.', 'Players switch between six different counselors, exploring cabins and woods in a race against time. It’s known for its suspenseful music and jumpscares.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Front Line (Japan)', '1982', NaN, 'Irem', '1', NaN, 'Top-down run and gun.', 'Infiltrate the enemy base on foot and in tanks to destroy the fort.', 'A classic Taito arcade port of one of the earliest military shooters.', 'Players start as a lone soldier but can find and pilot tanks to increase their firepower as they push through hazardous 8-bit battlefields.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fudou Myouou Den (Japan)', '1987', NaN, 'Natsume', '1', NaN, 'Side-scrolling action.', 'Use 13 different types of weapons to defeat demons and save the land.', 'An expansive and difficult action game by Taito with massive stages.', 'Known for its intense difficulty and huge variety of power-ups, players control a monk who must battle mythological creatures across vast, non-linear levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fudou Myouou Den (Japan) [En by Stardust Crusaders v1.0] (~Acala Legend, The)', '1987', NaN, 'Natsume', '1', NaN, 'Side-scrolling action.', 'Use 13 different types of weapons to defeat demons and save the land.', 'The English fan translation of the epic Fudou Myouou Den.', 'This translation makes the many weapon upgrades and story elements clear, allowing players to tackle one of the Famicom''s most challenging action titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fun Blaster Pak (Australia) (Unl)', 'Unlicensed', NaN, 'Unknown', '2', NaN, 'Multi-game compilation.', 'Choose from several arcade-style mini-games in one package.', 'A collection of unlicensed action and puzzle games by Bunch Games.', 'This Australian-released cartridge features a variety of simple 8-bit experiences, ranging from shooters to logic puzzles, providing multiple games on a single cart.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fun House (USA)', '1991', NaN, 'Hi Tech Expressions', '2', NaN, 'Top-down action.', 'Navigate a maze-like obstacle course to collect prizes and reach the exit.', 'An 8-bit adaptation of the popular kids'' television game show.', 'As Tiny, players must navigate stages filled with balls and obstacles, using a launcher to hit targets and clear the way through the Fun House before time runs out.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fushigi na Blobby - Blobania no Kiki (Japan)', '1987', NaN, 'Jaleco', '1', NaN, 'Side-scrolling puzzle adventure.', 'Feed your blob jellybeans to transform it and navigate obstacles.', 'Known in the West as A Boy and His Blob: Trouble on Blobolonia.', 'This charming game requires strategic thinking as different jellybean flavors turn the blob into ladders, holes, or trampolines to help the boy save the planet.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fushigi no Umi no Nadia (Japan)', '1991', NaN, 'Namco', '1', NaN, 'Adventure / Strategy RPG.', 'Join Nadia and Jean on an epic quest to stop the Neo-Atlanteans.', 'A deep adventure game based on the Nadia: Secret of Blue Water anime.', 'This title combines story-driven dialogue segments with tactical, grid-based combat, staying faithful to the art style and narrative of the classic Gainax series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fushigi no Umi no Nadia (Japan) [En by J2e v1.3] (~Nadia - Secret of the Blue Water)', '1991', NaN, 'Namco', '1', NaN, 'Adventure / Strategy RPG.', 'Join Nadia and Jean on an epic quest with full English text.', 'The English fan translation of the Famicom adventure based on the anime.', 'This translation makes the complex plot and tactical RPG segments accessible, allowing fans to experience the 8-bit retelling of Nadia''s journey in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fuzzical Fighter (Japan)', '1990', NaN, 'Towachiki', '1', NaN, 'Horizontal shoot ''em up / RPG.', 'Fly through stages and use shops to upgrade your ship''s stats and magic.', 'A unique hybrid of traditional shooting and RPG-style progression.', 'Fuzzical Fighter allows players to land at shops mid-level to buy weapons and items, blending fast-paced aerial combat with strategic character building.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Fuzzical Fighter (Japan) [En by WakdHacks v1.00b]', '1990', NaN, 'Towachiki', '1', NaN, 'Horizontal shoot ''em up / RPG.', 'Fly through stages and upgrade your ship with translated menus.', 'The English version of the quirky shooter-RPG hybrid.', 'This translation is crucial for understanding the various ship upgrades, spells, and items available in the shops, making the game''s depth much easier to navigate.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'G.I. Joe - A Real American Hero - The Atlantis Factor (USA)', '1992', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Lead a squad of G.I. Joe members to stop Cobra''s resurrection of Atlantis.', 'The second G.I. Joe NES game, featuring non-linear path selection.', 'Players can choose different characters with unique weapons and upgrade their stats. It features massive levels and impressive boss fights against the Cobra elite.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'G.I. Joe - A Real American Hero - The Atlantis Factor (USA) (Beta)', '1992', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Lead a squad to stop Cobra in this early development version.', 'A prototype of the second G.I. Joe game with potential gameplay differences.', 'This version offers a look at the game''s polish before release, sometimes showing different enemy placements or unrefined character abilities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'G.I. Joe - A Real American Hero (USA)', '1988', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Infiltrate Cobra bases and plant bombs to dismantle the organization.', 'A top-tier action game developed by Taxan with incredible co-op and combat.', 'Players select a team of three Joes, switching between them to utilize different strengths. It''s widely considered one of the best action titles on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gaiapolis (Asia) (Unl)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Action RPG / Beat ''em up.', 'Journey through a fantasy world to find the legendary city of Gaiapolis.', 'An unlicensed 8-bit port of the Konami arcade fantasy brawler.', 'This bootleg attempts to replicate the top-down action of the original, featuring character leveling and cooperative play in a world of magic and machines.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Galactic Crusader (Asia) (Unl) (Sachen) (NES)', 'Unlicensed', NaN, 'Sachen', '1', NaN, 'Vertical-scrolling shooter.', 'Pilot a starship through enemy lines to destroy a cosmic threat.', 'An unlicensed space shooter by Sachen with high-speed action.', 'This version features challenging bullet patterns and multiple power-ups, requiring quick reflexes to navigate through waves of alien spacecraft.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Galactic Crusader (USA) (Unl) (Bunch Games)', 'Unlicensed', NaN, 'Bunch Games', '1', NaN, 'Vertical-scrolling shooter.', 'Pilot a starship through enemy lines to destroy a cosmic threat.', 'The Western unlicensed release of the Sachen space shooter.', 'Released by Bunch Games, it offers the same intense arcade-style shooting, challenging players to achieve high scores in a relentless space battle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Galaga - Demons of Death (USA)', '1988', NaN, 'Namco', '1', NaN, 'Fixed-screen shooter.', 'Destroy waves of insect-like aliens before they dive-bomb your ship.', 'The iconic sequel to Galaxian and a foundational arcade classic.', 'Famous for the Challenge Stage and the ability to have your ship captured and then rescued to create a Dual Fighter for double the firepower.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Galaga (Europe)', '1984', NaN, 'Namco', '1', NaN, 'Fixed-screen shooter.', 'Destroy waves of insect-like aliens before they dive-bomb your ship.', 'The European PAL version of the legendary Namco arcade shooter.', 'A pixel-perfect recreation of the arcade hit, challenging players with increasing waves of enemies and strategic ship management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Galaga (Japan)', '1984', NaN, 'Namco', '1', NaN, 'Fixed-screen shooter.', 'Destroy waves of insect-like aliens before they dive-bomb your ship.', 'The original Famicom release of the hit arcade shooter.', 'This version brought the arcade experience home with perfect accuracy, becoming one of the most played and beloved titles in the Famicom library.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Galaxian (Japan)', '1984', NaN, 'Namco', '1', NaN, 'Fixed-screen shooter.', 'Defend the galaxy from swarms of alien invaders.', 'The classic precursor to Galaga, featuring colorful 8-bit enemies.', 'Galaxian was one of the first games to feature enemies with individual dive-bombing patterns, offering a step up in difficulty from earlier fixed shooters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Galaxy 5000 (Europe)', '1991', NaN, 'Activision', '1', NaN, 'Isometric racing / Combat.', 'Race through intergalactic tracks and use weapons to destroy rivals.', 'A unique 3D-perspective racer with high-speed combat.', 'Players can upgrade their ships with the prize money won. The game features jumping mechanics and a humorous 8-bit digitized voice during races.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Galaxy 5000 (USA)', '1991', NaN, 'Activision', '1', NaN, 'Isometric racing / Combat.', 'Race through intergalactic tracks and use weapons to destroy rivals.', 'A unique 3D-perspective racer with high-speed combat.', 'Players can upgrade their ships with the prize money won. The game features jumping mechanics and a humorous 8-bit digitized voice during races.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Galg (Japan)', '1990', NaN, 'Unknown', '1', NaN, 'Vertical-scrolling shooter.', 'Search through 100 areas to find the pieces of a legendary weapon.', 'A shooter with exploration elements, also known as Zunou Senkan Galg.', 'Unlike standard shooters, the player must choose paths at forks in the road to navigate a massive maze-like environment while fighting enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gambler Jiko Chuushin Ha - Mahjong Game (Japan)', '1988', NaN, 'Nichibutsu', '1', NaN, 'Mahjong / Strategy.', 'Defeat various quirky opponents in high-stakes Mahjong matches.', 'A Mahjong game based on a popular Japanese manga series.', 'It features a variety of characters with unique playstyles and humorous cutscenes, making the traditional tile game more accessible and entertaining.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gambler Jiko Chuushin Ha 2 (Japan)', '1990', NaN, 'Nichibutsu', '1', NaN, 'Mahjong / Strategy.', 'Continue your Mahjong career against even tougher manga rivals.', 'The expanded sequel to the popular manga-based Mahjong game.', 'This version includes more characters, refined AI, and updated graphics, focusing on the social and competitive aspects of Japanese Mahjong.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Game Genie (USA) (Unl)', '1990', NaN, 'Galoob', '1', NaN, 'Cheat utility.', 'Enter codes to modify game parameters like health or lives.', 'The legendary game-modifying peripheral for the NES.', 'While not a game itself, the Game Genie interface allowed players to bypass difficulty or explore hidden features in their favorite 8-bit titles using alphanumeric codes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Game Party (Japan)', '1989', NaN, 'Game Studio', '2', NaN, 'Variety / Mini-games.', 'Compete in various party-style challenges to earn the highest score.', 'A collection of family-oriented mini-games for the Famicom.', 'From sports to logic puzzles, this title was designed for multiple players to enjoy a digital board game experience on the couch.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ganbare Goemon 2 (Japan)', '1991', NaN, 'Konami', '1', NaN, 'Side-scrolling action adventure.', 'Journey across Edo-period Japan to stop a mechanical threat.', 'The second Goemon adventure, introducing Ebisumaru and co-op play.', 'This sequel expanded the world significantly, adding vehicles, massive bosses, and the iconic humorous tone that would define the Konami franchise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ganbare Goemon 2 (Japan) [En by Stardust Crusaders v1.0]', '1991', NaN, 'Konami', '1', NaN, 'Side-scrolling action adventure.', 'Journey across Edo-period Japan with full English dialogue.', 'The English translation of the second Goemon Famicom classic.', 'This translation captures the puns and historical humor of the series, allowing Western fans to enjoy the deep levels and quirky story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ganbare Goemon Gaiden - Kieta Ougon Kiseru (Japan)', '1990', NaN, 'Konami', '1', NaN, 'Turn-based RPG.', 'Solve the mystery of the missing Golden Pipe in a fantasy Japan.', 'A spin-off that turns the Goemon series into a traditional RPG.', 'Featuring a beautiful art style and a classic turn-based combat system, this game takes the Goemon cast on a grand quest through towns and dungeons.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ganbare Goemon Gaiden 2 - Tenka no Zaihou (Japan)', '1992', NaN, 'Konami', '1', NaN, 'Turn-based RPG.', 'Search for the world''s treasures in an epic RPG sequel.', 'The second Goemon RPG, often considered one of the best on the system.', 'This title features even more impressive 8-bit cutscenes, a larger world, and a refined combat system, representing the peak of Famicom RPG design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ganbare Goemon! - Karakuri Douchuu (Japan)', '1986', NaN, 'Konami', '1', NaN, 'Side-scrolling action adventure.', 'Travel through the provinces of Japan to help the poor and fight injustice.', 'The first Famicom entry in the legendary Mystical Ninja series.', 'Players explore vast levels filled with secrets and shops. It established the core gameplay of using a pipe and throwing coins as weapons.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ganbare Goemon! - Karakuri Douchuu (Japan) [En by Dragoon-X v1.02]', '1986', NaN, 'Konami', '1', NaN, 'Action adventure.', 'Travel through the provinces of Japan to help the poor and fight injustice.', 'The English fan translation of the first Famicom Mystical Ninja game.', 'This translation makes the shops, clues, and humorous dialogue accessible, allowing players to fully enjoy Goemon''s debut quest through the colorful Edo period.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ganbare Pennant Race! (Japan)', '1989', NaN, 'Namco', '2', NaN, 'Sports / Baseball.', 'Lead your baseball team to the top of the Japanese league.', 'A polished Konami baseball title known for its high-quality music and animations.', 'This game offers a mix of realistic simulation and arcade fun, featuring detailed player stats and smooth 8-bit graphics that were a hallmark of Konami’s late Famicom era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ganso Saiyuuki - Super Monkey Daibouken (Japan)', '1988', NaN, 'Jaleco', '1', NaN, 'Action RPG / Adventure.', 'Guide Sun Wukong and his companions on their journey to the West.', 'A cult classic based on the Journey to the West legend.', 'Players must manage the party''s health and hunger while navigating top-down maps and side-scrolling action sequences, staying true to the famous mythological source material.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gardman (Asia) (Unl)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling action.', 'Protect the world from robotic invaders using your high-tech armor.', 'An unlicensed action game featuring a futuristic hero in a world of machines.', 'This bootleg title focuses on combat and platforming, challenging players to destroy waves of drones and robotic bosses using a variety of projectile weapons.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Garfield - A Week of Garfield (Japan)', '1989', NaN, 'Towachiki', '1', NaN, 'Side-scrolling action.', 'Survive a full week of Monday-to-Sunday adventures as Garfield.', 'A notoriously difficult Japanese-exclusive platformer featuring the lazy cat.', 'Garfield must kick mice and birds across various domestic and outdoor environments. It is famous for its punishing difficulty and unique take on the comic character.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Garfield - A Week of Garfield Upgrade', 'Unlicensed', NaN, 'Towachiki', '1', NaN, 'Side-scrolling action (Hack).', 'Experience Garfield''s week with improved physics and fair difficulty.', 'A technical hack that balances the original Week of Garfield gameplay.', 'This modification improves Garfield''s movement speed, attack range, and hit detection, making the challenging Japanese classic much more playable and enjoyable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Garfield Kart', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Racing (Hack).', 'Race as Garfield and friends in this 8-bit kart racing conversion.', 'A creative hack of Mickey''s Adventure in Numberland or similar engines.', 'This total conversion replaces characters and assets to create a Garfield-themed racing experience, complete with custom sprites and themed 8-bit tracks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gargoyle''s Quest II - The Demon Darkness (Europe)', '1992', NaN, 'Capcom', '1', NaN, 'Action RPG / Platformer.', 'Embark on a journey as Firebrand to save the Ghoul Realm.', 'A high-quality Capcom prequel featuring unique hovering mechanics.', 'As a gargoyle, players can fly, cling to walls, and breathe fire. The game blends top-down RPG exploration with intense side-scrolling action stages and incredible music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gargoyle''s Quest II - The Demon Darkness (USA)', '1992', NaN, 'Capcom', '1', NaN, 'Action RPG / Platformer.', 'Embark on a journey as Firebrand to save the Ghoul Realm.', 'A high-quality Capcom prequel featuring unique hovering mechanics.', 'As a gargoyle, players can fly, cling to walls, and breathe fire. The game blends top-down RPG exploration with intense side-scrolling action stages and incredible music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gauntlet (USA)', '1988', NaN, 'Atari Games', '4', NaN, 'Top-down dungeon crawler.', 'Navigate endless mazes to find the exit while fighting off hordes of monsters.', 'The official Tengen port of the legendary co-op arcade hit.', 'Players choose between the Warrior, Valkyrie, Wizard, or Elf. The game is famous for the narrator''s voice (Wizard needs food, badly!) and its relentless enemy spawners.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gauntlet (USA) (Unl)', 'Unlicensed', NaN, 'Atari Games', '4', NaN, 'Top-down dungeon crawler.', 'Navigate endless mazes to find the exit while fighting off hordes of monsters.', 'The unlicensed version of the arcade classic, released by Tengen.', 'Due to legal disputes with Nintendo, this version was released in a black cartridge, featuring the same intense four-player-inspired dungeon-crawling action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gauntlet II (Europe)', '1990', NaN, 'Atari Games', '4', NaN, 'Top-down dungeon crawler.', 'Survive deeper and more complex dungeons with up to four players.', 'An improved sequel that allows four-player simultaneous play.', 'Using the NES Four Score, players can team up to tackle even more enemies, featuring voice synthesis and the ability for multiple players to choose the same class.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gauntlet II (USA)', '1990', NaN, 'Atari Games', '4', NaN, 'Top-down dungeon crawler.', 'Survive deeper and more complex dungeons with up to four players.', 'An improved sequel that allows four-player simultaneous play.', 'Using the NES Four Score, players can team up to tackle even more enemies, featuring voice synthesis and the ability for multiple players to choose the same class.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gegege no Kitarou - Youkai Dai Makyou (Japan)', '1986', NaN, 'Konami', '1', NaN, 'Side-scrolling action.', 'Use Kitaro''s supernatural powers to defeat evil Yokai across Japan.', 'A popular action game based on the famous spooky manga series.', 'Known in the US as Ninja Kid, the original version features Kitaro using his hair-needles and remote-control sandals to fight traditional Japanese ghosts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gegege no Kitarou - Youkai Dai Makyou (Japan) (Beta)', '1986', NaN, 'Konami', '1', NaN, 'Side-scrolling action.', 'Defeat evil Yokai in this early development version of the game.', 'A rare prototype featuring differences in level layout and enemy design.', 'This beta offers a glimpse into the production of the first Kitaro game, showcasing early sprite work and mechanical adjustments before the retail release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gegege no Kitarou - Youkai Dai Makyou (Japan) [En by Aishsha v1.0] (~Spooky Kitaro in the Yokai World)', '1986', NaN, 'Konami', '1', NaN, 'Side-scrolling action.', 'Defeat the Yokai army with Kitaro''s hair-needles and translated text.', 'The English fan translation of the first Kitaro Famicom title.', 'This version restores the original Japanese cultural context and character names, providing the definitive way to play the first game in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gegege no Kitarou 2 - Youkai Gundan no Chousen (Japan)', '1987', NaN, 'Konami', '1', NaN, 'Turn-based RPG / Adventure.', 'Travel across Japan to stop a massive Yokai invasion.', 'A sequel that shifts the series into a traditional RPG format.', 'Unlike the first game, this entry focuses on turn-based battles and world exploration, featuring many iconic characters from the Shigeru Mizuki universe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gegege no Kitarou 2 - Youkai Gundan no Chousen (Japan) [En by Aishsha+Djinn v1.1] (~Spooky Kitaro 2 - Kitaro Versus Yokai Army)', '1987', NaN, 'Konami', '1', NaN, 'Turn-based RPG / Adventure.', 'Stop the Yokai invasion with translated dialogue and menus.', 'The English fan translation of the expansive Famicom RPG sequel.', 'This translation is essential for understanding the various Yokai abilities and the story-driven quests that take Kitaro all over the map of Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Geimos (Japan)', '1986', NaN, 'Irem', '1', NaN, 'Pseudo-3D shooter.', 'Pilot a starship and destroy the core of the mechanical planet.', 'An early experiment in 3D perspective shooting on the Famicom.', 'Players fly towards the horizon, dodging and shooting enemies in a style similar to Space Harrier, but with a focus on clearing planetary defenses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gekikame Ninja Den (Japan)', '1991', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Defeat the Foot Clan and save Splinter as the Ninja Turtles.', 'The Japanese version of the first TMNT game for the NES.', 'Known for its high difficulty (especially the dam level), players can switch between the four turtles at any time, each with their own health bar and weapon.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gekitotsu Yonku Battle (Japan)', '1989', NaN, 'Taito', '2', NaN, 'Top-down vehicular combat.', 'Smash enemy cars out of the arena to be the last one standing.', 'A chaotic and fun 8-bit demolition derby style game.', 'Players drive 4WD vehicles in various arenas, using speed and environmental hazards to destroy opponents in fast-paced, high-energy rounds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gekitou Pro Wrestling!! - Toukon Densetsu (Japan)', '1989', NaN, 'Technos Japan', '2', NaN, 'Sports / Wrestling.', 'Climb the ranks to become the champion of the Toukon federation.', 'A technical wrestling game featuring the legendary Antonio Inoki.', 'It features a variety of grapples and strikes, requiring precise timing and button sequences to wear down opponents in the 8-bit squared circle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gekitou Stadium!! (Japan)', '1987', NaN, 'Namco', '2', NaN, 'Sports / Baseball.', 'Win the championship in this high-energy baseball simulation.', 'A fast-paced baseball game with a focus on dramatic plays.', 'This title offers a more arcade-like feel than Famista, featuring exaggerated batting animations and a heavy emphasis on timing and power.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gemfire (USA)', '1991', NaN, 'Koei', '1', NaN, 'Turn-based strategy.', 'Unify the island of Ishmeria by reclaiming the 7 wizard gems.', 'A fantasy-themed grand strategy game from the masters at Koei.', 'Players manage units, diplomacy, and resources. The game features a unique system where powerful wizards and monsters can be summoned to turn the tide of tactical grid-based battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Genghis Khan (USA)', '1989', NaN, 'Koei', '1', NaN, 'Turn-based strategy.', 'Conquer the known world as Temujin and build a lasting empire.', 'A deep historical simulation of the Mongol Empire''s rise to power.', 'This complex Koei title requires managing family succession, international trade, and military campaigns across two different world maps (Mongolia and Eurasia).', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Genpei Touma Den - Computer Boardgame (Japan)', '1986', NaN, 'Namco', '2', NaN, 'Board game / Strategy.', 'Defeat the Heike clan in a digital board game based on Japanese lore.', 'A strategic board game adaptation of the famous Namco arcade title.', 'Players move across a map of Japan, engaging in mini-games and tactical battles to weaken the enemy''s influence, all presented with a distinct traditional aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'George Foreman''s KO Boxing (Europe)', '1992', NaN, 'Beam Software', '2', NaN, 'Sports / Boxing.', 'Win the heavyweight championship by knocking out every contender.', 'A punch-heavy boxing game endorsed by the legendary George Foreman.', 'Featuring large character sprites and a focus on power punches, players must manage stamina and timing to climb the professional ranks in this PAL version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'George Foreman''s KO Boxing (USA)', '1992', NaN, 'Beam Software', '2', NaN, 'Sports / Boxing.', 'Win the heavyweight championship by knocking out every contender.', 'A punch-heavy boxing game endorsed by the legendary George Foreman.', 'Featuring large character sprites and a focus on power punches, players must manage stamina and timing to climb the professional ranks on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Getsufuu Maden (Japan)', '1987', NaN, 'Konami', '1', NaN, 'Action / Adventure.', 'Journey through the underworld to defeat the demon Ryukotsuki.', 'A legendary Konami adventure featuring side-scrolling and 3D paths.', 'As Getsu Fuu, players collect three pulse swords across a massive map. It is famous for its 3D dungeon segments and its heavy influence on the Castlevania series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Getsufuu Maden (Japan) [En by RPGe v1.0]', '1987', NaN, 'Konami', '1', NaN, 'Action / Adventure.', 'Journey through the underworld with full English translated lore.', 'The English fan translation of the cult classic Getsufuu Maden.', 'This translation makes the clues, item descriptions, and mythological story accessible, allowing Western fans to enjoy one of Konami''s best Famicom exclusives.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghost''n Goblins (Europe)', '1986', NaN, 'Capcom', '2', NaN, 'Side-scrolling platformer.', 'Rescue Princess Prin-Prin from the demon king as Sir Arthur.', 'The notoriously difficult and iconic Capcom arcade port.', 'Known for its steep challenge, players must guide Arthur through graveyards and caves. You must beat the game twice to see the true ending!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghost''n Goblins (Europe) [Hack by Plimoth Legaue v1.0] (~All Hallows Eve)', '1986', NaN, 'Capcom', '2', NaN, 'Side-scrolling platformer.', 'Experience a spooky Halloween-themed version of the Capcom classic.', 'A total visual overhaul of Ghost''n Goblins with seasonal graphics.', 'This hack replaces tiles and sprites to create a festive Halloween atmosphere, while maintaining the legendary difficulty of the original NES game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghostbusters (Japan)', '1984', NaN, 'Activision', '1', NaN, 'Action / Simulation.', 'Earn enough money to enter the Zuul building and save New York.', 'The Japanese version of the famous movie tie-in by Activision.', 'This version features slightly different graphics and ending screens, but keeps the core gameplay of driving the Ecto-1 and trapping ghosts for cash.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghostbusters (USA)', '1984', NaN, 'Activision', '1', NaN, 'Action / Simulation.', 'Earn enough money to enter the Zuul building and save New York.', 'The famous movie tie-in known for its unique driving and trapping.', 'Players buy equipment, drive through the city, and capture ghosts. It is remembered for its innovative (if frustrating) mechanics and the iconic theme music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghostbusters II (Europe)', '1989', NaN, 'Activision', '1', NaN, 'Side-scrolling action.', 'Stop the flow of pink slime and defeat Vigo the Carpathian.', 'An improved sequel featuring different gameplay styles for each level.', 'Unlike the first game, this version focuses on side-scrolling action and vehicle stages (like the Statue of Liberty), following the plot of the second movie.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghostbusters II (USA)', '1989', NaN, 'Activision', '2', NaN, 'Side-scrolling action.', 'Stop the flow of pink slime and defeat Vigo the Carpathian.', 'An improved sequel featuring different gameplay styles for each level.', 'Unlike the first game, this version focuses on side-scrolling action and vehicle stages (like the Statue of Liberty), following the plot of the second movie.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghostbusters Remastered (The Real)', 'Unlicensed', NaN, 'Unknown', '2', NaN, 'Action / Simulation (Hack).', 'Save NYC with improved graphics and fixed gameplay mechanics.', 'A Real Ghostbusters hack that polishes the original NES game.', 'This remaster fixes bugs, updates colors to match the cartoon, and adjusts the difficulty to make the classic Activision title more enjoyable today.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghosts''n Goblins (USA)', '1986', NaN, 'Capcom', '2', NaN, 'Side-scrolling platformer.', 'Rescue Princess Prin-Prin from the demon king as Sir Arthur.', 'The notoriously difficult and iconic Capcom arcade port.', 'Known for its steep challenge, players must guide Arthur through graveyards and caves. You must beat the game twice to see the true ending!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghosts''N Goblins Easy', 'Unlicensed', NaN, 'Capcom', '2', NaN, 'Side-scrolling platformer.', 'Enjoy the adventure of Sir Arthur with a more forgiving difficulty.', 'A balanced hack that reduces the frustration of the original game.', 'This version modifies enemy spawns and Arthur''s resilience, allowing players to experience the levels without the extreme 8-bit punishment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghosts''N Goblins Very Easy', 'Unlicensed', NaN, 'Capcom', '2', NaN, 'Side-scrolling platformer.', 'Breeze through the demon realm with maximum health and lives.', 'A tourist mode hack for the notoriously hard Capcom classic.', 'Perfect for seeing the game''s art and level design, this version makes Arthur almost invincible, removing the barriers of the original arcade difficulty.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ghoul School (USA)', '1992', NaN, 'Rare', '1', NaN, 'Side-scrolling exploration.', 'Rescue your girlfriend from a high school overrun by demons.', 'A non-linear Metroidvania style action game set in a school.', 'Players explore classrooms and gyms, finding various weapons and items to unlock new areas. It’s known for its unique setting and strange enemy designs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gimmi a Break - Shijou Saikyou no Quiz Ou Ketteisen (Japan)', '1991', NaN, 'Game Studio', '2', NaN, 'Trivia / Game Show.', 'Win the ultimate quiz championship by answering varied questions.', 'A Japanese quiz game featuring a high-energy TV show format.', 'This title tests general knowledge across several categories, requiring quick reflexes and deep cultural knowledge to beat the digital opponents.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gimmi a Break - Shijou Saikyou no Quiz Ou Ketteisen 2 (Japan)', '1992', NaN, 'Game Studio', '2', NaN, 'Trivia / Game Show.', 'Defend your title in the expanded quiz show sequel.', 'A second installment of the popular Famicom trivia series.', 'Featuring updated questions and new mini-games, this sequel offers a refined experience for fans of digital 8-bit board games and trivia.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gimmick! (Japan)', '1992', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling platformer.', 'Journey through a toy world to save your owner from a kidnapping.', 'A technical masterpiece known for its advanced physics and sound.', 'Players use stars to jump and attack. The game features the Sunsoft 5B chip for enhanced music and is legendary for its hidden true final level.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ginga Eiyuu Densetsu (Japan)', '1992', NaN, 'Bothtec', '1', NaN, 'Strategy / Simulation.', 'Choose between the Empire or the Alliance in a galactic war.', 'A strategy game based on the Legend of the Galactic Heroes anime.', 'Players manage fleets and engage in massive space battles, staying faithful to the political and tactical depth of the famous sci-fi series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ginga no Sannin (Japan)', '1987', NaN, 'Namco', '3', NaN, 'Turn-based RPG.', 'Lead a crew to defend Earth from an invading alien force.', 'A sci-fi RPG featuring unique first-person space combat.', 'Known for its atmospheric soundtrack and futuristic setting, players travel between planets to gather information and upgrade their combat mechs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Girl Team to the rescue [v0.2]', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling platformer (Hack).', 'Complete missions with a team of female heroes.', 'A character swap hack that introduces new protagonists to a classic engine.', 'This work-in-progress hack replaces traditional characters with female sprites, offering a fresh aesthetic for 8-bit platforming fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Go! Benny! (Unl)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Action / Puzzle.', 'Clear the field of items while avoiding enemies in this bootleg title.', 'An unlicensed action game featuring a simple, arcade-style loop.', 'This title focuses on high scores and quick reflexes, challenging players to navigate small arenas and outsmart the AI in a series of fast-paced rounds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Goal! (Europe)', '1989', NaN, 'Jaleco', '2', NaN, 'Sports / Soccer.', 'Win the world tournament by mastering the field with your team.', 'A fast and accessible 8-bit soccer game by Jaleco.', 'Featuring multiple formations and tournament modes, Goal! is praised for its smooth controls and the ability to add curve to the ball after a shot.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Goal! (USA)', '1989', NaN, 'Jaleco', '2', NaN, 'Sports / Soccer.', 'Win the world tournament by mastering the field with your team.', 'A fast and accessible 8-bit soccer game by Jaleco.', 'Featuring multiple formations and tournament modes, Goal! is praised for its smooth controls and the ability to add curve to the ball after a shot.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Goal! Two (USA)', '1991', NaN, 'Jaleco', '2', NaN, 'Sports / Soccer.', 'Lead your international team to the cup in this polished sequel.', 'An improved soccer simulation with better graphics and AI.', 'Goal! Two expanded on the original with more teams, better pitch perspectives, and refined controls for headers and bicycle kicks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Goal!! (Japan)', '1989', NaN, 'Jaleco', '2', NaN, 'Sports / Soccer.', 'Win the league or tournament with your favorite soccer team.', 'The original Famicom version of the fast-paced Jaleco soccer game.', 'Known for its smooth scrolling and after-touch mechanic that allows players to curve the ball mid-air, it offers a very accessible 8-bit football experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'God of War', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling action (Pirate).', 'Defeat the gods of Olympus as Kratos in 8-bit form.', 'An unlicensed Chinese demake of the famous PlayStation title.', 'This bootleg attempts to bring the fury of Kratos to the NES, featuring unique sprites, multiple weapons, and simplified versions of the epic boss battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'God of War 2', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling action (Pirate).', 'Continue Kratos''s revenge against the gods in this 8-bit sequel.', 'Another ambitious unlicensed port of the Sony action franchise.', 'Featuring improved graphics over the first bootleg, it focuses on high-intensity combat and platforming through mythological Greek environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'God Slayer - Haruka Tenkuu no Sonata (Japan)', '1994', NaN, 'Telenet Japan', '1', NaN, 'Action RPG.', 'Awaken from cryogenic sleep to save a post-apocalyptic world.', 'The original Japanese version of the cult classic Crystalis.', 'Developed by SNK, this masterpiece features real-time combat, a deep magic system, and an epic story that combines fantasy with sci-fi elements.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Godzilla - Monster of Monsters! (Europe)', '1988', NaN, 'Compile', '1', NaN, 'Strategy / Side-scrolling action.', 'Travel across the solar system to defeat King Ghidorah''s army.', 'A unique hybrid of board game strategy and giant monster combat.', 'Players move Godzilla and Mothra across a grid. When encountering an enemy, the game switches to a side-scrolling battle against iconic Kaiju and mechanical bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Godzilla - Monster of Monsters! (USA)', '1988', NaN, 'Compile', '1', NaN, 'Strategy / Side-scrolling action.', 'Travel across the solar system to defeat King Ghidorah''s army.', 'A unique hybrid of board game strategy and giant monster combat.', 'Players move Godzilla and Mothra across a grid. When encountering an enemy, the game switches to a side-scrolling battle against iconic Kaiju and mechanical bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Godzilla (Japan)', '1987', NaN, 'Toho', '1', NaN, 'Strategy / Side-scrolling action.', 'Defend Earth from invading monsters across the galaxy.', 'The original Famicom release of the strategic Kaiju adventure.', 'Featuring a massive roster of classic monsters, this title is beloved for its atmosphere and the chance to control the King of the Monsters on 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Godzilla 2 - War of the Monsters (USA)', '1992', NaN, 'Toho', '1', NaN, 'Turn-based strategy.', 'Coordinate military forces to stop Godzilla and other invading monsters.', 'A pure tactical simulation where you play as the human defense force.', 'Unlike the first game, you control the army. You must strategically deploy tanks and jets to lure and damage giant monsters attacking major cities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gold Medal Challenge ''92 (Europe)', '1992', NaN, 'Konami', '4', NaN, 'Sports / Athletics.', 'Win gold in various summer Olympic events against world rivals.', 'A massive Capcom sports collection featuring 18 different events.', 'Players compete in track, field, swimming, and gymnastics. It’s known for its varied gameplay mechanics and its great 4-player competitive mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gold Medal Challenge ''92 (USA)', '1992', NaN, 'Konami', '4', NaN, 'Sports / Athletics.', 'Win gold in various summer Olympic events against world rivals.', 'A massive Capcom sports collection featuring 18 different events.', 'Players compete in track, field, swimming, and gymnastics. It’s known for its varied gameplay mechanics and its great 4-player competitive mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golden Sun (C)', 'Unlicensed', NaN, 'Camelot', '1', NaN, 'Turn-based RPG (Pirate).', 'Lead Isaac and his friends on a quest to stop the release of Alchemy.', 'An unlicensed 8-bit demake of the Game Boy Advance classic.', 'This Chinese bootleg recreates the story and world of Golden Sun, featuring a surprisingly complex turn-based battle system for an unlicensed NES title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golf ''92, The (Japan)', '1992', NaN, 'Nintendo', '2', NaN, 'Sports / Golf simulation.', 'Master the professional circuit to win the 1992 championship.', 'A late-era Famicom golf game with refined physics and menus.', 'It offers a more technical approach to golf, with detailed wind and terrain data, catering to fans of serious sports simulations on the 8-bit system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golf (Europe)', '1985', NaN, 'Nintendo', '2', NaN, 'Sports / Golf.', 'Complete 18 holes in the fewest strokes possible.', 'The foundational Nintendo sports title that defined the genre''s controls.', 'Featuring the iconic three-click power meter that is still used today, this classic allows players to select clubs and adjust for wind on a variety of greens.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golf (Japan)', '1984', NaN, 'Nintendo', '2', NaN, 'Sports / Golf.', 'Complete 18 holes in the fewest strokes possible.', 'The foundational Nintendo sports title that defined the genre''s controls.', 'Featuring the iconic three-click power meter that is still used today, this classic allows players to select clubs and adjust for wind on a variety of greens.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golf (USA)', '1985', NaN, 'Nintendo', '2', NaN, 'Sports / Golf.', 'Complete 18 holes in the fewest strokes possible.', 'The foundational Nintendo sports title that defined the genre''s controls.', 'Featuring the iconic three-click power meter that is still used today, this classic allows players to select clubs and adjust for wind on a variety of greens.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golf Club - Birdy Rush (Japan)', '1991', NaN, 'Namco', '2', NaN, 'Sports / Golf.', 'Compete in tournament play and achieve a birdy on every hole.', 'A fast and colorful arcade-style golf game by Data East.', 'Birdy Rush offers a more upbeat and faster experience than Nintendo''s Golf, featuring overhead views and simplified mechanics for quick play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golf Grand Slam (Japan)', '1991', NaN, 'Namco', '2', NaN, 'Sports / Golf.', 'Win all four major tournaments to achieve the Grand Slam.', 'A comprehensive golf simulation with multiple professional modes.', 'This title focuses on the career aspect of golf, challenging players to master different courses and weather conditions to become the world number one.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golf Grand Slam (USA)', '1991', NaN, 'Namco', '2', NaN, 'Sports / Golf.', 'Win all four major tournaments to achieve the Grand Slam.', 'A comprehensive golf simulation with multiple professional modes.', 'This title focuses on the career aspect of golf, challenging players to master different courses and weather conditions to become the world number one.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golf Ko Open (Japan)', '1992', NaN, 'Namco', '2', NaN, 'Sports / Golf.', 'Win the open tournament and set new course records.', 'A specialized golf title featuring unique Japanese courses.', 'Like many Famicom golf games, it emphasizes precision and course management, offering a high-quality 8-bit simulation for golf enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golgo 13 - Dai 1 Shou - Kamigami no Tasogare (Japan)', '1988', NaN, 'Namco', '1', NaN, 'Action / Adventure / Sniper.', 'Complete top-secret missions as the world''s greatest assassin.', 'The original Japanese version of the first Golgo 13 game.', 'A complex hybrid that switches between side-scrolling action, first-person maze exploration, and sniper segments. It is famous for its mature themes and story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golgo 13 - The Mafat Conspiracy (USA)', '1988', NaN, 'Namco', '1', NaN, 'Action / Adventure / Sniper.', 'Stop a global satellite threat in this high-stakes sequel.', 'The second Golgo 13 NES title, featuring improved graphics.', 'Duke Togo returns in this adventure that takes him across the world. It refined the maze exploration and added more cinematic cutscenes to the 8-bit experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golgo 13 - The Riddle of Icarus (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Action / Adventure / Sniper.', 'Uncover the mystery of the Icarus project as Duke Togo.', 'The Japanese version of the high-octane Mafat Conspiracy.', 'Known for its challenging first-person segments and tactical sniper gameplay, this Famicom title is a classic of the espionage genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Golgo 13 - Top Secret Episode (USA)', '1988', NaN, 'Namco', '1', NaN, 'Action / Adventure / Sniper.', 'Complete top-secret missions as the world''s greatest assassin.', 'The North American version of the first Golgo 13 adventure.', 'Despite some censorship, the game remains a unique blend of genres, challenging players to think like a professional hitman in a world of 8-bit international intrigue.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gomoku Narabe (Japan)', '1987', NaN, 'Namco', '2', NaN, 'Board game / Strategy.', 'Connect five stones in a row before your opponent does.', 'A clean and simple digital version of the traditional Go-moku game.', 'Featuring a challenging computer AI, this early Famicom title is a perfect recreation of the classic board game, requiring deep strategic planning.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Goonies II, The - Fratelli Saigo no Chousen (Japan)', '1987', NaN, 'Konami', '1', NaN, 'Adventure / Platformer.', 'Save your fellow Goonies and a mermaid from the Fratelli family.', 'An expansive sequel that blends platforming with first-person puzzles.', 'Players explore a massive interconnected world (hide-and-seek style) using tools like hammers and glasses to find hidden paths and rescue their friends.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Goonies II, The - Fratelli Saigo no Chousen (Japan) (Beta)', '1987', NaN, 'Konami', '1', NaN, 'Adventure / Platformer.', 'Save the Goonies in this early development version of the game.', 'A rare prototype featuring differences in item locations and text.', 'This version offers a look at Konami''s development process, showing minor balance changes and layout adjustments before the final retail release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Goonies II, The (Europe)', '1987', NaN, 'Konami', '1', NaN, 'Adventure / Platformer.', 'Save your fellow Goonies and a mermaid from the Fratelli family.', 'An expansive sequel that blends platforming with first-person puzzles.', 'Players explore a massive interconnected world (hide-and-seek style) using tools like hammers and glasses to find hidden paths and rescue their friends.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Goonies II, The (USA)', '1987', NaN, 'Konami', '1', NaN, 'Adventure / Platformer.', 'Save your fellow Goonies and a mermaid from the Fratelli family.', 'An expansive sequel that blends platforming with first-person puzzles.', 'Players explore a massive interconnected world (hide-and-seek style) using tools like hammers and glasses to find hidden paths and rescue their friends.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Goonies, The (Japan)', '1985', NaN, 'Konami', '2', NaN, 'Side-scrolling platformer.', 'Rescue all the Goonies from the Fratelli hideout to reach the end.', 'The iconic first game, famous for its music and secret-filled levels.', 'Players control Mikey, kicking enemies and placing bombs to open doors. Despite being a huge hit on the Famicom, it only saw a limited release in the West via PlayChoice-10.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gorby no Pipeline Daisakusen (Japan)', '1991', NaN, 'Toshiba EMI', '1', NaN, 'Puzzle.', 'Connect pipe segments to ensure the oil flows across the screen.', 'A unique Tetris-style puzzle game featuring Mikhail Gorbachev.', 'Developed by Compile, players must align pipe pieces falling from the top. It was a rare example of a Japanese game featuring a prominent Soviet political figure as a friendly character.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gorby no Pipeline Daisakusen (Japan) [En by DvD Rev A] (~Gorby''s Pipeline - Great Military Operation)', '1991', NaN, 'Toshiba EMI', '1', NaN, 'Puzzle.', 'Connect pipe segments with full English translated menus.', 'The English version of the quirky Compile puzzle game.', 'This translation clarifies the scoring and mechanics of the pipeline connection, making this fast-paced and unusual puzzle title easy to master for Western fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gorilla Man, The (Japan)', '1987', NaN, 'Nichibutsu', '1', NaN, 'Side-scrolling action.', 'Explore various stages and defeat enemies to progress the story.', 'A quirky action-adventure based on a Japanese manga.', 'Known for its strange humor and unique character designs, players navigate through levels that blend traditional platforming with the surreal tone of the source material.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gotcha! - The Sport! (USA)', '1990', NaN, 'LJN', '2', NaN, 'Light gun shooter.', 'Capture the enemy flag and shoot opponents in a paintball match.', 'A tactical NES Zapper game based on the paintball craze.', 'Using both the Zapper and the controller, players must navigate through various environments (woods, urban zones), aiming accurately to tag opponents while avoiding being hit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gozonji - Yaji Kita Chin Douchuu (Japan)', '1988', NaN, 'Namco', '1', NaN, 'Adventure / Board game.', 'Travel across Edo-period Japan in a comedic journey.', 'A humorous digital board game adventure based on Japanese literature.', 'Players move along a map, encountering various events and mini-games that focus on the comedic mishaps of the two main characters, Yaji and Kita.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gradius - MSX Conversion', '1992', NaN, 'Konami', '2', NaN, 'Horizontal shoot ''em up.', 'Fly the Vic Viper and destroy the Bacterion empire.', 'A fan-made conversion of the MSX version of Gradius for the NES.', 'This version brings specific levels and mechanics from the MSX hardware (like the Bone planet) to the NES, offering a unique alternate take on the classic shooter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gradius (ArchiMENdes Hen) (Japan)', '1987', NaN, 'Konami', '1', NaN, 'Horizontal shoot ''em up.', 'Defeat the Bacterion forces in this promotional special version.', 'A rare promotional edition of Gradius released in Japan.', 'Distributed as a prize by a food company, this version is functionally similar to the original but is highly sought after by collectors for its historical context.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gradius (Europe)', '1987', NaN, 'Konami', '1', NaN, 'Horizontal shoot ''em up.', 'Fly through alien worlds and use the power-up bar to upgrade.', 'The definitive NES port of the legendary Konami arcade shooter.', 'Known for its iconic power-up system (Speed Up, Missile, Laser, Options), it set the standard for the genre and introduced the famous Konami Code.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gradius (Japan)', '1987', NaN, 'Konami', '1', NaN, 'Horizontal shoot ''em up.', 'Fly through alien worlds and use the power-up bar to upgrade.', 'The original Famicom release of the legendary Nemesis series.', 'A pixel-perfect home version that captured the arcade''s intensity, featuring memorable bosses like the Big Core and the iconic Moai heads.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gradius (USA)', '1987', NaN, 'Konami', '1', NaN, 'Horizontal shoot ''em up.', 'Fly through alien worlds and use the power-up bar to upgrade.', 'The definitive NES port of the legendary Konami arcade shooter.', 'Known for its iconic power-up system (Speed Up, Missile, Laser, Options), it set the standard for the genre and introduced the famous Konami Code.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gradius II (Japan)', '1987', NaN, 'Konami', '1', NaN, 'Horizontal shoot ''em up.', 'Lead the Vic Viper through even more dangerous alien zones.', 'A stunning Famicom sequel featuring the custom VRC4 chip.', 'One of the most impressive technical feats on the system, Gradius II features massive bosses, improved graphics, and the ability to choose different power-up loadouts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gradius Resurrection', '1988', NaN, 'Konami', '1', NaN, 'Horizontal shoot ''em up.', 'Survive new waves of enemies in this fan-enhanced edition.', 'A high-quality hack that adds content and fixes to the Gradius engine.', 'This version features new levels and improved color palettes, breathing new life into the classic 8-bit shooter with modern design sensibilities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Grand Master (Japan)', '1988', NaN, 'Konami', '1', NaN, 'Side-scrolling action.', 'Battle through fantasy realms to defeat the dark lord.', 'A fast-paced and visually impressive action game by Varie.', 'Featuring huge sprites and intense boss battles, Grand Master allows players to switch between different weapons and magic to adapt to the challenging fantasy enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Great Battle Cyber (Japan)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling action.', 'Use different SD (Super Deformed) heroes to stop a global threat.', 'A crossover action game featuring Ultraman, Kamen Rider, and Gundam.', 'Players can switch between three iconic Japanese heroes, each with unique abilities, to navigate stages and defeat enemies in this charming 8-bit brawler.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Great Boxing - Rush Up (Japan)', '1991', NaN, 'Taito', '1', NaN, 'Sports / Boxing.', 'Train your boxer and win the professional championship belt.', 'A technical boxing simulation with a heavy focus on training.', 'Developed by Vic Tokai, this title requires players to manage their boxer''s stats through training mini-games before entering the ring for strategic 8-bit bouts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Great Deal (Japan)', '1988', NaN, 'Taito', '1', NaN, 'Puzzle / Card game.', 'Match card values and suits to clear the board and score points.', 'A refined and strategic card-based puzzle game for the Famicom.', 'Blending elements of Poker and Solitaire, it challenges players to think ahead and create winning combinations under time pressure to progress.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Great Tank (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Top-down shooter.', 'Drive your heavy tank through enemy lines to destroy the headquarters.', 'The original Japanese version of the cult classic Iron Tank.', 'Developed by SNK, it features non-linear paths and a wide variety of weapon upgrades, allowing players to choose how they approach the massive warzone.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Great Waldo Search, The (USA)', '1988', NaN, 'Data East', '2', NaN, 'Puzzle / Hidden object.', 'Find Waldo and specific items in crowded, colorful illustrations.', 'An 8-bit adaptation of the famous Where''s Waldo? books.', 'Players move a cursor over large scrolling maps based on different historical or fantasy themes, testing their observation skills against the clock.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Great Wall, The (Asia) (Unl) (NES)', '1988', NaN, 'Data East', '2', NaN, 'Puzzle / Strategy.', 'Match tiles to dismantle the Great Wall in this 8-bit puzzler.', 'An unlicensed puzzle game by Sachen with a Mahjong-style theme.', 'Featuring classic tile-matching mechanics, players must strategically remove pieces from a large wall without getting stuck, aiming for the highest score.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Greg Norman''s Golf Power (USA)', '1987', NaN, 'Data East', '2', NaN, 'Sports / Golf.', 'Master the greens across the USA with the Great White Shark.', 'A technical golf game featuring unique terrain-mapping technology.', 'This title stands out for its TrueView system, allowing players to survey the course from different angles, and for including real-world course data.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gremlin 2 - Shinshu Tanjou (Japan)', '1985', NaN, 'Nintendo', '2', NaN, 'Top-down action platformer.', 'Guide Gizmo through the Clamp Center to stop the Gremlin invasion.', 'A gorgeous Sunsoft production with top-tier music and graphics.', 'Known as one of the best-looking games on the system, it features tight controls and creative gadgets that Gizmo uses to navigate through the hazards of the skyscraper.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gremlins 2 - The New Batch (Europe)', '1989', NaN, 'Hudson Soft', '1', NaN, 'Top-down action platformer.', 'Guide Gizmo through the Clamp Center to stop the Gremlin invasion.', 'A gorgeous Sunsoft production with top-tier music and graphics.', 'Known as one of the best-looking games on the system, it features tight controls and creative gadgets that Gizmo uses to navigate through the hazards of the skyscraper.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gremlins 2 - The New Batch (USA)', '1990', NaN, 'Tecmo', '1', NaN, 'Top-down action platformer.', 'Guide Gizmo through the Clamp Center to stop the Gremlin invasion.', 'A gorgeous Sunsoft production with top-tier music and graphics.', 'Known as one of the best-looking games on the system, it features tight controls and creative gadgets that Gizmo uses to navigate through the hazards of the skyscraper.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gryzor (Japan)', '1990', NaN, 'Tecmo', '1', NaN, 'Run and gun.', 'Infiltrate the alien base and destroy the Red Falcon core.', 'The original Japanese version of the legendary Contra.', 'This version is superior to the US release due to the custom Konami VRC2 chip, which adds animated backgrounds (trees, snow) and story cutscenes between levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gryzor (Japan) [En by MadHacker v1.0] [Fix by g8z et al] (Contra Version)', '1987', NaN, 'Namco', '1', NaN, 'Run and gun.', 'Experience the enhanced Japanese version with full English text.', 'The definitive way to play Contra on the NES in English.', 'This fan translation brings the superior graphics and cutscenes of the Japanese Gryzor to Western players while keeping the iconic Contra title and feel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gryzor (Japan) [En by MadHacker v1.0] [Fix by g8z et al] (Gryzor Version)', '1990', NaN, 'Data East', '2', NaN, 'Run and gun.', 'Experience the enhanced Japanese version with its original title.', 'A fan translation that maintains the Gryzor branding and story.', 'Like the Contra version, it features the animated backgrounds and cutscenes missing from the US release, but keeps the European/Japanese naming convention.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Guardian Legend, The (Europe)', '1987', NaN, 'Capcom', '1', NaN, 'Shooter / Adventure.', 'Explore a massive world to activate ten safety keys and save Earth.', 'A brilliant hybrid of Zelda-style exploration and shmup action.', 'Players control a transformer that explores a world on foot and turns into a starfighter for boss battles. It is highly regarded for its deep upgrades and music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Guardian Legend, The (USA)', '1987', NaN, 'Capcom', '1', NaN, 'Shooter / Adventure.', 'Explore a massive world to activate ten safety keys and save Earth.', 'A brilliant hybrid of Zelda-style exploration and shmup action.', 'Players control a transformer that explores a world on foot and turns into a starfighter for boss battles. It is highly regarded for its deep upgrades and music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Guardic Gaiden (Japan)', '1985', NaN, 'Taito', '1', NaN, 'Shooter / Adventure.', 'Explore a massive world to activate ten safety keys and save Earth.', 'The original Japanese version of The Guardian Legend.', 'Featuring the same incredible mix of exploration and intense vertical shooting, it is a cult classic that showcases the best of 8-bit hybrid design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Guerrilla War (Europe)', '1985', NaN, 'Nintendo', '2', NaN, 'Top-down run and gun.', 'Lead a revolution to overthrow a dictator in a tropical nation.', 'An intense and fast-paced SNK shooter with unlimited continues.', 'Based on the story of Che Guevara and Fidel Castro, the game features non-stop action, tank segments, and a high level of destruction throughout its levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Guerrilla War (USA)', '1984', NaN, 'Konami', '2', NaN, 'Top-down run and gun.', 'Overthrow a cruel dictator and liberate the island nation.', 'An intense and fast-paced SNK shooter with non-stop action.', 'Known for its infinite continues and heavy firepower, players fight through jungles and cities, rescuing hostages and destroying tanks in this classic arcade port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Guevara (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Top-down run and gun.', 'Lead the revolution as Che Guevara to liberate the island.', 'The original Japanese version of Guerrilla War.', 'Unlike the Western version, this one explicitly names the protagonists Che Guevara and Fidel Castro, staying true to its historical (though stylized) revolutionary theme.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gumshoe (USA, Europe)', '1990', NaN, 'Irem', '1', NaN, 'Light gun shooter.', 'Help Mr. Stevenson jump and avoid obstacles by shooting him.', 'A unique NES Zapper game that combines platforming and shooting.', 'Instead of shooting enemies, you shoot the protagonist to make him jump over pits and obstacles, requiring a mix of rhythm and precise aim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gun Hed (Japan)', '1988', NaN, 'Taito', '1', NaN, 'Vertical shoot ''em up.', 'Destroy the enemy fleet and save humanity from a mechanical threat.', 'A fast-paced shooter based on the Japanese sci-fi film.', 'Known for its incredible speed and variety of power-ups, Gun Hed (also known as Blazing Lazers on other systems) is a technical marvel on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gun Nac (Japan)', '1987', NaN, 'Nichibutsu', '2', NaN, 'Vertical shoot ''em up.', 'Defeat the bizarre galactic army of mutated objects.', 'Widely considered the best vertical shooter on the NES/Famicom.', 'Developed by Compile, it features insane weapon variety, shops to buy upgrades, and a level of polish that pushed the NES hardware to its absolute limit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gun Nac (USA)', '1988', NaN, 'Square', '1', NaN, 'Vertical shoot ''em up.', 'Defeat the bizarre galactic army of mutated objects.', 'Widely considered the best vertical shooter on the NES.', 'A masterclass in 8-bit game design, offering lightning-fast action without slowdown, customizable weapons, and some of the most creative boss fights on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gun Sight (Japan)', '1992', NaN, 'Konami', '1', NaN, 'First-person light gun shooter.', 'Infiltrate enemy territory and take down a criminal organization.', 'The original Japanese version of Laser Invasion.', 'Developed by Konami, it supports the Zapper and features first-person shooting segments combined with strategic helicopter flight sequences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gun-Dec (Japan)', '1991', NaN, 'Nintendo', '1', NaN, 'Side-scrolling action.', 'Chase down criminals and uncover a dark conspiracy in the city.', 'The original Japanese version of Vice: Project Doom.', 'An incredible hybrid game that features high-speed driving levels, first-person shooting, and top-tier ninja-style platforming action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gun.Smoke (Europe)', '1989', NaN, 'Lucasfilm Games', '2', NaN, 'Vertical-scrolling shooter.', 'Collect bounties by defeating the most dangerous outlaws in the West.', 'A brilliant Capcom arcade port set in the Wild West.', 'Unique for its control scheme where you use three buttons to shoot in different directions, players must upgrade their horse and weapons to survive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gun.Smoke (USA)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Vertical-scrolling shooter.', 'Collect bounties by defeating the most dangerous outlaws in the West.', 'A brilliant Capcom arcade port set in the Wild West.', 'Players control Billy Bob through desert towns and canyons, fighting through waves of bandits to confront legendary bosses in high-stakes duels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gyrodine (Japan)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Vertical shoot ''em up.', 'Pilot an advanced helicopter and destroy enemy sea and air forces.', 'An early Taito shooter focusing on tactical helicopter combat.', 'Players must manage two types of fire: forward-facing cannons for air targets and a movable crosshair for ground and sea installations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gyromite (World)', 'Unlicensed', NaN, 'Natsume', '1', NaN, 'Puzzle / Platformer.', 'Help Professor Hector collect dynamite while avoiding Smicks.', 'One of the two games designed for use with the R.O.B. robot.', 'Players (or the robot) must press buttons to move red and blue pillars, creating paths for the Professor in this slow-paced but strategic puzzle game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Gyruss (USA)', '1990', NaN, 'Nintendo', '2', NaN, 'Tube-style shooter.', 'Travel through the solar system to reach Earth while destroying aliens.', 'A unique 360-degree shooter that blends Galaga and Tempest.', 'Developed by Konami, this NES version adds power-ups and epic boss battles at each planet, all set to an iconic 8-bit Bach-inspired soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Haja no Fuuin (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Turn-based RPG.', 'Travel the land to find the four heroes and defeat the demon king.', 'An early and complex RPG with an emphasis on exploration.', 'Known as The Seal of the Dragon, it features a massive world map and a unique combat system where positioning and party management are key to survival.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hammerin'' Harry (Europe)', '1991', NaN, 'Irem', '2', NaN, 'Side-scrolling action.', 'Use your giant hammer to fight through construction sites and cities.', 'A charming and difficult action game by Irem.', 'As Harry, players must smash enemies and projectiles to stop a corrupt construction company. It features great humor, big sprites, and tough boss fights.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hana no Star Kaidou (Japan)', '1987', NaN, 'Victor Musical Industries', '1', NaN, 'Side-scrolling action adventure.', 'Guide a young couple through the music industry to become stars.', 'A quirky and notoriously difficult game about the road to fame.', 'Players control two characters simultaneously, navigating through various stages filled with hazards that represent the struggles of a pop music career.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hanafuda Yuukyou Den - Nagarebana Oryuu (Japan) (Unl)', 'Unlicensed', NaN, 'Nichibutsu', '2', NaN, 'Card game / Strategy.', 'Defeat opponents in the traditional Japanese card game Hanafuda.', 'An unlicensed and more mature take on the classic Hanafuda game.', 'Featuring high-quality 8-bit art, this title offers various modes and opponents to challenge your mastery of the Flower Cards rules.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hanjuku Hero (Japan)', '1988', NaN, 'Square', '1', NaN, 'Real-time strategy.', 'Defend your castle and conquer others using Egg monsters.', 'A humorous and innovative RTS game developed by Square.', 'Players manage a kingdom and summon monsters from eggs to fight battles. It’s famous for its parody of RPG tropes and its slapstick humor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Happy Birthday Bugs (Japan)', '1989', NaN, 'Taito', '1', NaN, 'Side-scrolling action platformer.', 'Collect items and avoid hazards to reach Bugs'' birthday party.', 'Known in the West as The Bugs Bunny Birthday Blowout.', 'Bugs uses a mallet to defeat enemies through colorful levels based on classic Looney Tunes shorts, featuring guest appearances from the whole cast.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hard Drivin'' (Prototype)', '1991', NaN, 'Atari Games', '1', NaN, '3D Driving simulation.', 'Complete the stunt course and beat the clock in 3D perspective.', 'A fascinating prototype of the ambitious 3D arcade racer.', 'This unreleased port attempted to recreate the arcade''s polygons using the NES''s limited hardware, offering a glimpse into early 3D console experimentation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Harlem Globetrotters (USA)', '1989', NaN, 'Konami', '2', NaN, 'Sports / Basketball.', 'Perform tricks and win games in this comedic basketball sim.', 'A licensed game featuring the world-famous trick basketball team.', 'Players can perform signature Globetrotters moves and mini-games, blending traditional basketball gameplay with the team''s iconic entertainment style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Harri''s Legend (Chinese) (Unl)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling action.', 'Navigate through fantasy stages using magical powers.', 'An unlicensed Chinese action game featuring a Harry Potter theme.', 'This bootleg attempts to bring the magic of the boy wizard to the NES, featuring unique sprites and spell-based combat in various themed levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Harri''s Legend (English) (Unl)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling action.', 'Navigate through fantasy stages using magical powers in English.', 'The English-translated version of the Chinese Harry Potter bootleg.', 'This translation makes the menus and simple story of the unlicensed action game accessible to English-speaking collectors and players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Harvest Moon (C)', 'Unlicensed', NaN, 'Natsume', '1', NaN, 'Farming simulation (Pirate).', 'Manage your farm, grow crops, and raise animals in 8-bit form.', 'An unlicensed Chinese demake of the famous farming series.', 'This bootleg attempts to shrink the SNES/Game Boy experience onto the NES, featuring basic farming mechanics and town interaction in a simplified format.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hatris (Japan)', '1990', NaN, 'Nintendo', '2', NaN, 'Falling-block puzzle.', 'Stack five identical hats to clear them from the screen.', 'A quirky puzzle game designed by the creator of Tetris.', 'Instead of blocks, players manage different types of hats (crowns, top hats, etc.). It requires strategic stacking to prevent the piles from reaching the top of the shop.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hatris (USA)', '1990', NaN, 'Nintendo', '2', NaN, 'Falling-block puzzle.', 'Stack five identical hats to clear them from the screen.', 'The Western release of Alexey Pajitnov''s hat-stacking puzzler.', 'Featuring the same addictive gameplay as the Japanese version, it challenges players to master the unique physics and sorting logic of 8-bit millinery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hayauchi Super Igo (Japan)', '1991', NaN, 'HAL Laboratory', '2', NaN, 'Board game / Strategy.', 'Defeat opponents in the traditional game of Go (Igo).', 'A fast-paced digital version of the classic Eastern board game.', 'Featuring a specialized AI for quick decision-making, it allows players to practice and compete in Go matches with various difficulty settings on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Heavy Barrel (Japan)', '1987', NaN, 'Data East', '2', NaN, 'Top-down run and gun.', 'Infiltrate the base and assemble the Heavy Barrel super weapon.', 'An intense Data East arcade port with 360-degree shooting.', 'Players fight through waves of enemies to find keys for red lockers containing pieces of a devastating energy cannon, using it to clear the most difficult bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Heavy Barrel (USA)', '1987', NaN, 'Data East', '2', NaN, 'Top-down run and gun.', 'Infiltrate the base and assemble the Heavy Barrel super weapon.', 'A high-action military shooter known for its powerful upgrades.', 'Similar to Ikari Warriors but with smoother gameplay, it features diverse environments and a heavy emphasis on collecting weapon parts to gain temporary invincibility.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Heavy Shreddin'' (USA)', '1989', NaN, 'Parker Brothers', '1', NaN, 'Sports / Snowboarding.', 'Navigate dangerous downhill slopes and perform tricks to finish.', 'One of the few dedicated snowboarding games on the NES.', 'Players must manage speed and balance across various terrain types, from powdery snow to icy peaks, avoiding obstacles in a race against the clock.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hebereke (Japan)', '1991', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling adventure.', 'Explore a surreal world and find your friends to escape.', 'A cult classic Metroidvania known as Ufouria in the West.', 'Featuring a bizarre and charming art style, players switch between four unique characters (a penguin, a cat-ghost, etc.) to use their specific abilities to reach new areas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hector 87 (Japan)', '1988', NaN, 'Hudson Soft', '1', NaN, 'Vertical/Horizontal shooter.', 'Destroy the biological and mechanical invaders across time.', 'A high-difficulty shooter known in the West as Starship Hector.', 'Developed by Hudson Soft, it alternates between vertical and horizontal scrolling stages, requiring players to master both ground and air-based attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Heisei Tensai Bakabon (Japan)', '1990', NaN, 'Sega', '1', NaN, 'Side-scrolling action.', 'Help Bakabon''s Papa navigate through chaotic and surreal levels.', 'A humorous action game based on the famous comedy manga.', 'Players use an umbrella as a weapon and tool to navigate strange environments, capturing the absurd and slapstick humor of the legendary Fujio Akatsuka series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Heisei Tensai Bakabon (Japan) [En by KingMike v1.0] (~Genius Bakabon, The)', '1992', NaN, 'Sega', '1', NaN, 'Side-scrolling action.', 'Navigate surreal levels with fully translated comedic dialogue.', 'The English fan translation of the wacky Famicom action title.', 'This version makes the absurd jokes and level objectives clear, allowing Western fans to enjoy one of Japan''s most iconic comedy franchises in 8-bit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hell Fighter (Asia) (Unl) (NES)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Vertical-scrolling shooter.', 'Pilot a combat aircraft and destroy waves of demonic enemies.', 'An unlicensed military shooter with a dark, intense theme.', 'Developed by Sachen, it features relentless enemy patterns and a variety of power-ups, challenging players to survive a hellish battlefield from start to finish.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hello Kitty no Ohanabatake (Japan)', '1992', NaN, 'Sanrio', '1', NaN, 'Side-scrolling puzzle.', 'Water all the flowers in each garden while avoiding enemies.', 'A cute and colorful puzzle-platformer featuring Hello Kitty.', 'Kitty must navigate through platforms to reach flower beds, using her watering can and avoiding moles and bees in a family-friendly 8-bit adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hello Kitty no Ohanabatake (Japan) [En by Suicidal v1.0] (~Hello Kitty''s Flower Shop)', '1992', NaN, 'Sanrio', '1', NaN, 'Side-scrolling puzzle.', 'Tend to your flower shop gardens with translated menus.', 'The English fan translation of Kitty''s floral puzzle adventure.', 'This version makes the level instructions and cute story segments accessible, perfect for younger players or Sanrio fans using the original hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hello Kitty World (Japan)', '1992', NaN, 'Sanrio', '1', NaN, 'Side-scrolling action.', 'Navigate through themed worlds using a magical balloon.', 'A Hello Kitty-themed remake of the game Balloon Kid.', 'Players must tap buttons to flap their balloons and stay airborne, navigating through obstacles and collecting items in this charming 8-bit platformer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hello Kitty World (Japan) [En by Flake v1.0]', '1992', NaN, 'Sanrio', '1', NaN, 'Side-scrolling action.', 'Navigate themed worlds with translated English text.', 'An English fan translation for the balloon-based adventure.', 'This patch replaces the Japanese text, making the world names and simple story accessible to English-speaking fans of the Sanrio mascot.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hello Kitty World (Japan) [En by HK Kicks Ass v1.0]', '1992', NaN, 'Sanrio', '1', NaN, 'Side-scrolling action.', 'Navigate themed worlds with a more edgy fan translation.', 'An alternative English translation with a humorous/rough tone.', 'A community-made translation that adds a bit of 90s-style attitude to the text of the otherwise innocent Hello Kitty game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Herakles no Eikou - Toujin Makyou Den (Japan)', '1987', NaN, 'Data East', '1', NaN, 'Turn-based RPG.', 'Journey across ancient Greece to defeat the God of Hades.', 'The first entry in the Glory of Heracles mythological series.', 'Inspired by Dragon Quest, it features a heavy focus on Greek myths, challenging players to gather legendary items and talk to gods to complete their quest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Herakles no Eikou 2 - Titan no Metsubou (Japan)', '1989', NaN, 'Data East', '1', NaN, 'Turn-based RPG.', 'Stop the resurrection of the Titans and save the world.', 'A vastly improved sequel with deeper mechanics and story.', 'Featuring a more advanced combat system and a moving narrative, it is considered one of the most underrated RPG gems on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Herakles no Eikou 2 - Titan no Metsubou (Japan) [En by Spoony Bard v1.31] (~Glory of Heracles 2, The - Titans'' Downfall)', '1989', NaN, 'Data East', '1', NaN, 'Turn-based RPG.', 'Stop the Titans with full English translated lore and menus.', 'The high-quality fan translation of the second Herakles title.', 'This translation allows Western players to fully enjoy the epic mythological story and the improved 8-bit RPG mechanics of the Data East classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hero Quest (USA) (Proto)', '1990', NaN, 'Milton Bradley', '1', NaN, 'Isometric strategy / RPG.', 'Complete various dungeon quests to defeat the evil Morcar.', 'An unreleased prototype based on the famous board game.', 'A fascinating 8-bit adaptation that captures the turn-based movement and combat of the original tabletop game, featuring several different hero classes and quests.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hidden Chinese Chess - An Qi (Asia) (Unl)', 'Unlicensed', NaN, 'Unknown', '2', NaN, 'Board game / Strategy.', 'Defeat your opponent in the Dark version of Chinese Chess.', 'An unlicensed digital version of An Qi (Hidden Chess).', 'Played on a half-board with face-down pieces, this game focuses on luck and strategy as pieces are revealed and captured in a unique tactical loop.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Higemaru Makaijima - Nanatsu no Shima Daibouken (Japan)', '1987', NaN, 'Capcom', '1', NaN, 'Top-down action adventure.', 'Explore seven islands to find the hidden treasure of the pirates.', 'An expansive adventure based on the Higemaru arcade game.', 'Developed by Capcom, players throw barrels at enemies to clear paths. It features a non-linear map where players must sail between islands to find keys and bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Higemaru Makaijima - Nanatsu no Shima Daibouken (Japan) [En by Snark v1.0] (~Seven Islands Adventure)', '1987', NaN, 'Capcom', '1', NaN, 'Top-down action adventure.', 'Explore the islands and find pirate treasure in English.', 'The English fan translation of Capcom''s high-seas adventure.', 'This translation makes the clues given by NPCs and the names of the islands clear, which is essential for solving the game''s many navigational puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'High Speed (Europe)', '1988', NaN, 'Kotobuki Systems', '1', NaN, 'Pinball simulation.', 'Achieve the highest score and trigger the multi-ball police chase.', 'A faithful port of the classic Williams arcade pinball machine.', 'Known for its fast-paced action and car-chase theme, the NES version includes bonus mini-games and accurate table physics for 8-bit pinball fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'High Speed (USA)', '1988', NaN, 'Kotobuki Systems', '1', NaN, 'Pinball simulation.', 'Achieve the highest score and trigger the multi-ball police chase.', 'A faithful port of the classic Williams arcade pinball machine.', 'Known for its fast-paced action and car-chase theme, the NES version includes bonus mini-games and accurate table physics for 8-bit pinball fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Highway Star (Japan)', '1987', NaN, 'Taito', '1', NaN, 'Behind-the-car racing.', 'Race against the clock through various stages to reach the finish line.', 'A high-speed racing game by Square, known as Rad Racer in the West.', 'Featuring impressive 3D-style scaling and a selectable soundtrack, it was one of the first games to offer a 3D mode using specialized anaglyph glasses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hinotori - Houou Hen - Gaou no Bouken (Japan)', '1987', NaN, 'Konami', '1', NaN, 'Side-scrolling action.', 'Collect phoenix feathers to rebuild the legendary firebird.', 'A Konami classic based on Osamu Tezuka''s famous Phoenix manga.', 'Players control Gaou, who can create tiles to use as platforms. It features a unique branching path system and massive bosses across different historical eras.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hirake! Ponkikki (Japan)', '1987', NaN, 'Unknown', '1', NaN, 'Educational / Mini-games.', 'Complete various learning activities with the show''s mascots.', 'An educational title based on a popular Japanese children''s TV show.', 'Gachapin and Mukku guide children through simple logic, math, and word puzzles, designed with the colorful and friendly aesthetic of the 8-bit era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hirake! Ponkikki (Japan) [En by Gil Galad v1.01]', '1987', NaN, 'Unknown', '1', NaN, 'Educational / Mini-games.', 'Complete learning activities with translated instructions.', 'The English fan translation of the Ponkikki children''s game.', 'This version makes the educational mini-games accessible to English speakers, allowing children to enjoy the 8-bit lessons without the language barrier.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hirake! Ponkikki (Japan) [En by Unknown v1.0] (~Open! Ponkikki)', '1987', NaN, 'Unknown', '1', NaN, 'Educational / Mini-games.', 'Complete learning activities with translated instructions.', 'An alternative English translation of the Ponkikki educational title.', 'Similar to other versions, it translates the menus and prompts, providing a clear path through the various 8-bit learning challenges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hiryuu no Ken - Ougi no Sho (Japan)', '1987', NaN, 'Culture Brain', '2', NaN, 'Fighting / Action.', 'Master the dragon arts to win the world martial arts tournament.', 'The first entry in the series known in the West as Flying Dragon.', 'It blends side-scrolling exploration with a unique mark system in one-on-one combat, where players must strike specific points on an opponent.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hiryuu no Ken II - Dragon no Tsubasa (Japan)', '1989', NaN, 'Culture Brain', '2', NaN, 'Fighting / Action.', 'Defeat the Dark Wizard and his army using mystical dragon powers.', 'An expanded sequel with improved combat and cinematic cutscenes.', 'This entry introduces more specialized moves and a deeper story, following the Flying Warriors as they battle supernatural threats across the globe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hiryuu no Ken III - 5 Nin no Ryuu Senshi (Japan)', '1990', NaN, 'Culture Brain', '2', NaN, 'Fighting / Action.', 'Lead five dragon warriors to stop the ultimate evil from rising.', 'A multi-protagonist sequel featuring different martial arts styles.', 'Players can choose between five different characters, each with their own unique attacks and special skills, adding variety to the series'' tactical combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hiryuu no Ken Special - Fighting Wars (Japan)', '1990', NaN, 'Culture Brain', '2', NaN, '2D Fighting game.', 'Compete in a dedicated world tournament with refined mechanics.', 'A special edition focusing primarily on the one-on-one fighting mode.', 'This version polishes the combat engine and provides a streamlined tournament experience for fans of the Hiryu no Ken mark-based fighting system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hissatsu Doujou Yaburi (Japan)', '1988', NaN, 'Taito', '1', NaN, 'Fighting / Simulation.', 'Challenge and defeat the masters of various rival dojos.', 'A martial arts strategy and fighting game for the Famicom.', 'Players must train their character and then travel to different schools, using a mix of tactical decision-making and real-time combat to prove their strength.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hissatsu Shigoto Nin (Japan)', '1989', NaN, 'Taito', '1', NaN, 'Adventure / Action.', 'Take on contracts to eliminate corrupt officials in Edo Japan.', 'A stealth-based action game based on a popular period drama.', 'Players control different executioners who use unique tools to navigate levels and assassinate targets, blending story adventure with strategic combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hit Marmot (Asia) (Unl)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Whack-a-mole action.', 'Hit as many marmots as possible before the time runs out.', 'An unlicensed 8-bit recreation of the classic Whack-a-Mole arcade game.', 'Simple and fast-paced, it tests the player''s reflexes as they try to clear the screen of moles while avoiding penalties in this colorful bootleg.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hit the Ice - VHL the Video Hockey League (USA) (Proto)', '1991', NaN, 'Taito', '2', NaN, 'Sports / Hockey.', 'Win the VHL championship in this aggressive arcade-style hockey game.', 'An unreleased NES prototype of the famous comedic hockey hit.', 'Known for its large sprites and violent power shots, this version offers a look at how the arcade''s slapstick hockey was being ported to the 8-bit system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hitler no Fukkatsu - Top Secret (Japan)', '1989', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Rescue Super Joe and stop the resurrection of an ancient leader.', 'The uncensored Japanese version of Bionic Commando.', 'Unlike the Western release, this version contains Nazi imagery and explicit references, featuring the famous grappling hook mechanic and non-linear level choice.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hogan''s Alley (World)', '1984', NaN, 'Nintendo', '2', NaN, 'Light gun shooter.', 'Distinguish between gangsters and civilians in a shooting range.', 'A classic NES Zapper game that tests speed and judgment.', 'Players must shoot target cutouts of criminals while sparing innocent bystanders, featuring several modes including a trick shot game involving tin cans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hokkaidou Rensa Satsujin - Okhotsk ni Kiyu (Japan)', '1987', NaN, 'Login Soft', '1', NaN, 'Adventure / Murder Mystery.', 'Solve a series of linked murders across the Hokkaido region.', 'A pioneering menu-driven detective adventure by Yuji Horii.', 'As a police detective, you must investigate crime scenes and interview suspects. It is famous for its mature story and for being a precursor to the visual novel genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hokuto no Ken (Japan)', '1986', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling beat ''em up.', 'Navigate the wasteland and defeat Shin to rescue Yuria.', 'The Japanese version of the first Fist of the North Star game.', 'As Kenshiro, players use deadly pressure-point attacks to make enemies explode, featuring challenging platforming and iconic 8-bit martial arts action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hokuto no Ken (Japan) [En by Stardust Crusaders v1.0] (~Fist of the North Star)', '1986', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling beat ''em up.', 'Navigate the wasteland with fully translated dialogue and menus.', 'An English fan translation that restores the original anime context.', 'This version uses the original Japanese names and lore, providing a more authentic experience for fans of the legendary anime and manga series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hokuto no Ken 2 - Seikimatsu Kyuuseishu Densetsu (Japan)', '1989', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling beat ''em up.', 'Continue Kenshiro''s journey against the celestial emperor''s forces.', 'A sequel featuring larger sprites and more intense combat.', 'Based on the second half of the series, players fight through waves of enemies using upgraded techniques and power-ups to face the strongest rivals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hokuto no Ken 2 - Seikimatsu Kyuuseishu Densetsu (Japan) [En by Extreme Fun v0.50] (~Fist of the North Star 2) (Incomplete)', '1989', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling beat ''em up.', 'Continue Kenshiro''s journey with partially translated text.', 'An English fan translation for the second Hokuto no Ken title.', 'While incomplete, it makes the basic menus and story beats accessible for those wanting to play the 8-bit sequel to the Fist of the North Star.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hokuto no Ken 3 - Shin Seiki Souzou Seiken Restuden (Japan)', '1990', NaN, 'Toei Animation', '1', NaN, 'Turn-based RPG.', 'Experience the entire Hokuto no Ken saga in a massive RPG quest.', 'A deep RPG that covers the story from the beginning of the series.', 'Unlike the previous action games, this entry features turn-based combat and party management, staying extremely faithful to the original manga''s epic plot.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hokuto no Ken 4 - Shichisei Haken Den - Hokuto Shinken no Kanata he (Japan)', '1991', NaN, 'GameTek', '2', NaN, 'Turn-based RPG.', 'Lead a new generation of warriors in an original Hokuto story.', 'The final Famicom entry, featuring an original plot set after the series.', 'It features improved 8-bit graphics and a refined combat system, allowing players to create their own legacy in the post-apocalyptic world of the North Star.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hollywood Squares (USA)', '1989', NaN, 'Irem', '1', NaN, 'Quiz / Game Show.', 'Get three symbols in a row by agreeing or disagreeing with celebrities.', 'A digital version of the popular Tic-Tac-Toe themed game show.', 'Players must judge if the celebrities in the squares are telling the truth or lying, testing both their general knowledge and their sense of human psychology.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Holy Diver (Japan)', '1989', NaN, 'Irem', '1', NaN, 'Side-scrolling action platformer.', 'Defeat the black slayer and reclaim the royal family''s power.', 'A cult classic known for its Heavy Metal aesthetic and high difficulty.', 'Playing as Ronnie, you use magic spells to fight through gothic levels. It is famous for its intricate sprite work and for being a love letter to 80s rock icons.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Holy Diver (Japan) [En by Monaco v1.0]', '1991', NaN, 'Bethesda Softworks', '1', NaN, 'Side-scrolling action platformer.', 'Defeat the black slayer with fully translated story and menus.', 'An English fan translation of the Heavy Metal-themed action gem.', 'This version allows players to follow the dark fantasy plot while navigating the game''s brutal platforming challenges and boss encounters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Home Alone (USA)', '1991', NaN, 'Bethesda Softworks', '1', NaN, 'Survival / Action.', 'Hide and set traps to avoid being caught by the Wet Bandits for 20 minutes.', 'A game of cat and mouse based on the hit Christmas movie.', 'Players control Kevin McCallister, running through the mansion to collect valuables and drop traps like lightbulbs and toys to stall Harry and Marv until the police arrive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Home Alone (USA) (Rev A)', '1991', NaN, 'Bethesda Softworks', '1', NaN, 'Survival / Action.', 'Hide and set traps to avoid being caught by the Wet Bandits for 20 minutes.', 'A revised version of the movie tie-in with minor bug fixes.', 'This revision addresses small glitches in character movement and trap interaction, providing a more stable experience of Kevin''s solo defense of his home.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Home Alone 2 - Lost in New York (Europe)', '1991', NaN, 'Bethesda Softworks', '1', NaN, 'Side-scrolling platformer.', 'Evade the Wet Bandits and navigate the hazards of New York City.', 'The PAL version of the sequel, featuring varied city environments.', 'Unlike the first game, this is a more traditional platformer where Kevin uses weapons like a dart gun to fight off enemies in hotels, parks, and construction sites.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Home Alone 2 - Lost in New York (USA)', '1991', NaN, 'Namco', '2', NaN, 'Side-scrolling platformer.', 'Evade the Wet Bandits and navigate the hazards of New York City.', 'A challenging platformer based on Kevin''s big adventure in the city.', 'Players must navigate through iconic movie locations like the Plaza Hotel, using various gadgets to defeat enemies and escape the persistent Harry and Marv.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Home Run Nighter - Pennant League!! (Japan)', '1990', NaN, 'Namco', '2', NaN, 'Sports / Baseball.', 'Lead your team to victory in a full baseball season.', 'A high-energy Famicom baseball title by Data East.', 'Known for its fast gameplay and detailed player stats, this game focuses on the Pennant League experience, offering a deep simulation of Japan''s favorite sport.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Home Run Nighter ''90 - The Pennant League (Japan)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Sports / Baseball.', 'Win the championship in the updated 1990 baseball season.', 'An improved sequel with updated rosters and refined graphics.', 'This version features smoother animations and expanded tactical options for pitching and batting, representing the peak of the 8-bit Nighter series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Honey Peach - Mei Nv Quan (Asia) (Unl)', '1988', NaN, 'Taito', '2', NaN, 'Rock-paper-scissors / Puzzle.', 'Win games of Janken to progress through different stages.', 'An unlicensed mature themed puzzle game from the Asian market.', 'Using simple rock-paper-scissors mechanics, players compete against various opponents. It features high-quality 8-bit character art typical of unlicensed Famicom titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Honoo no Doukyuuji - Dodge Danpei (Japan)', '1988', NaN, 'Taito', '2', NaN, 'Sports / Dodgeball.', 'Lead Danpei''s team to the national dodgeball championship.', 'An intense dodgeball game based on the popular manga and anime.', 'Featuring special super shots and dramatic animations, players must manage their team''s health and positioning to knock out all opponents on the court.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Honoo no Doukyuuji - Dodge Danpei (Japan) [En by TransGen v1.0b] (~Dan''s Dodge Ball)', '1989', NaN, 'Taito', '2', NaN, 'Sports / Dodgeball.', 'Win the dodgeball championship with fully translated menus.', 'The English fan translation of the first Dodge Danpei game.', 'This version makes the team management and special move names accessible, allowing Western fans to enjoy the over-the-top 8-bit sports action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Honoo no Doukyuuji - Dodge Danpei 2 (Japan)', '1989', NaN, 'Taito', '2', NaN, 'Sports / Dodgeball.', 'Conquer the international dodgeball tournament with Danpei.', 'An improved sequel featuring bigger sprites and more special moves.', 'This entry expands the roster and adds more complex team strategies, making the dodgeball matches even more fast-paced and cinematic than the original.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Honoo no Doukyuuji - Dodge Danpei 2 (Japan) [En by TransGen v1.0a] (~Dan''s Dodge Ball 2)', '1986', NaN, 'SCEI', '2', NaN, 'Sports / Dodgeball.', 'Win the international tournament with translated text.', 'The English fan translation of the second Dodge Danpei title.', 'This patch clarifies the updated mechanics and story beats, providing the definitive way to experience Danpei''s second quest for dodgeball glory.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Honshougi - Naitou 9 Dan Shougi Hiden (Japan)', '1991', NaN, 'Sony Imagesoft', '1', NaN, 'Board game / Shogi.', 'Defeat high-ranking AI opponents in traditional Japanese chess.', 'A professional-grade Shogi simulator endorsed by Master Naitou.', 'Featuring deep AI routines and various handicap settings, this title is designed for serious students of Shogi looking for a challenge on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hook (Europe)', '1991', NaN, 'Sony Imagesoft', '1', NaN, 'Side-scrolling platformer.', 'Rescue Peter Pan''s children from the clutches of Captain Hook.', 'A high-quality platformer based on the Spielberg fantasy film.', 'As Peter Pan, players fly, swim, and fight through Neverland. The game is praised for its beautiful 8-bit graphics and faithful recreation of the movie''s atmosphere.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hook (Japan)', '1991', NaN, 'Sony Imagesoft', '1', NaN, 'Side-scrolling platformer.', 'Rescue Peter Pan''s children from the clutches of Captain Hook.', 'The Famicom version of the cinematic Hook adventure.', 'Featuring the same polished gameplay as the Western releases, it showcases some of the best visual effects and animations available on the 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hook (USA)', '1989', NaN, 'Jaleco', '2', NaN, 'Side-scrolling platformer.', 'Rescue Peter Pan''s children from the clutches of Captain Hook.', 'A polished movie-licensed platformer with great music and visuals.', 'Players explore forest and pirate ship levels, using a dagger and magical flight to overcome obstacles and confront the legendary Captain Hook.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hoops (Europe)', '1989', NaN, 'Jaleco', '2', NaN, 'Sports / Basketball.', 'Win the street basketball tournament in 1-on-1 or 2-on-2 matches.', 'A gritty urban basketball game focusing on half-court play.', 'Known as Moero!! Junior Basket in Japan, it features large character sprites and allows for a more aggressive, arcade-style take on the sport.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hoops (USA)', '1993', NaN, 'HAL Laboratory', '1', NaN, 'Sports / Basketball.', 'Win the street basketball tournament in 1-on-1 or 2-on-2 matches.', 'A gritty urban basketball game focusing on half-court play.', 'Players can choose from different fictional neighborhoods and players, each with unique stats, in this fast-paced 8-bit streetball simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hoshi no Kirby - Yume no Izumi no Monogatari (Japan)', '1987', NaN, 'Hot-B', '1', NaN, 'Side-scrolling platformer.', 'Recover the Star Rod and restore dreams to Dream Land.', 'One of the most technically advanced and beloved games on the NES.', 'Known as Kirby''s Adventure, it introduced Kirby''s ability to copy enemy powers. It features incredible graphics, massive levels, and a battery-backed save system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hoshi wo Miru Hito (Japan)', '1987', NaN, 'Hot-B', '1', NaN, 'Turn-based RPG.', 'Lead a group of psychics to uncover the truth about a dying world.', 'A notoriously difficult and surreal post-apocalyptic RPG.', 'Famous for its strange mechanics, lack of guidance, and unique sci-fi atmosphere, it has gained a cult following as one of the most challenging Famicom games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hoshi wo Miru Hito (Japan) [En by KingMike v0.80] (~Stargazers) (Incomplete)', '1987', NaN, 'Hot-B', '1', NaN, 'Turn-based RPG.', 'Lead the psychics through the dying world with translated text.', 'An English fan translation for the cult classic Hoshi wo Miru Hito.', 'While the game remains difficult, this translation helps clarify the cryptic dialogue and menus of this very unusual 8-bit role-playing experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hoshi wo Miru Hito (Japan) [En by KingMike v0.80] (~Stargazers) (SRAM Saving) (Incomplete)', '1990', NaN, 'Infogrames', '1', NaN, 'Turn-based RPG.', 'Lead a group of psychics in a dying world with save support.', 'The fan-translated version of Hoshi wo Miru Hito with a save fix.', 'This version adds SRAM support to the notorious RPG, allowing players to save their progress properly, making the brutal journey through the psychic wasteland more manageable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hostages - The Embassy Mission (Japan)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Strategy / Tactical shooter.', 'Infiltrate the embassy, eliminate terrorists, and rescue the hostages.', 'A tactical simulation known as Rescue: The Embassy Mission.', 'Players control a team of snipers and a dynamic assault squad. It features multiple phases, from positioning snipers to rappelling down walls and clearing rooms in first-person.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hot Slots (Asia) (Unl)', '1988', NaN, 'Koei', '1', NaN, 'Casino / Slots.', 'Win big on various themed slot machines to unlock rewards.', 'An unlicensed adult-themed casino game for the NES.', 'Featuring high-quality 8-bit character art for its time, this game simulates various slot machines with different themes, focusing on the luck of the draw to gain credits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hototogisu (Japan)', '1989', NaN, 'Konami', '1', NaN, 'Turn-based strategy.', 'Unify Japan during the Sengoku period through military conquest.', 'A deep historical war simulation based on a popular manga.', 'Players manage resources, troop placements, and diplomacy. It’s known for its detailed maps and strategic depth, typical of late-Famicom historical sims.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hottarman no Chitei Tanken (Japan)', '1989', NaN, 'Konami', '1', NaN, 'Action / Exploration.', 'Dig through the earth to find lava-cooling items and save the world.', 'A digging adventure game similar to Dig Dug but with more exploration.', 'As Hottarman, you navigate underground mazes, managing your air supply while using drills and bombs to clear paths and defeat subterranean enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hottarman no Chitei Tanken (Japan) [En by Six Feet Under v1.0] (~Hotman)', '1989', NaN, 'Konami', '1', NaN, 'Action / Exploration.', 'Dig through the earth to save the world with translated text.', 'The English fan translation of the digging adventure Hottarman.', 'This translation makes the mission objectives and item descriptions clear, allowing players to focus on the strategic digging and survival mechanics of the game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Houma ga Toki (Japan)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling action.', 'Defeat mythological Japanese demons in a dark fantasy setting.', 'A challenging platformer featuring traditional Japanese Yokai.', 'Players navigate through atmospheric levels based on folklore, using various weapons and magic to cleanse the land of evil spirits and powerful bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Huang Di (Asia) (Unl)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Turn-based RPG.', 'Lead the legendary Yellow Emperor on a quest to unify ancient China.', 'An unlicensed Chinese RPG with a heavy focus on mythology.', 'Featuring large sprites and a complex world map, this bootleg title attempts to bring the scale of 16-bit RPGs to the Famicom hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hudson Hawk (Europe)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling stealth action.', 'Infiltrate high-security buildings to steal three Da Vinci artifacts.', 'A creative action game based on the Bruce Willis film.', 'Players must use stealth, timing, and various gadgets to bypass guards and complex security systems, emphasizing clever movement over brute force.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hudson Hawk (Japan)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling stealth action.', 'Infiltrate high-security buildings to steal three Da Vinci artifacts.', 'The Japanese release of the movie-inspired heist game.', 'Featuring the same polished mechanics as the Western versions, this Famicom title captures the quirky tone and puzzle-like platforming of the Hudson Hawk film.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hudson Hawk (USA)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling stealth action.', 'Infiltrate high-security buildings to steal three Da Vinci artifacts.', 'A creative action game based on the Bruce Willis film.', 'Players must use stealth, timing, and various gadgets to bypass guards and complex security systems, emphasizing clever movement over brute force.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hudson''s Adventure Island - Classic in the Pacific (Europe)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling platformer.', 'Rescue Princess Leilani by surviving various tropical islands.', 'A compilation or specific PAL release of the foundational platformer.', 'Master Higgins must constantly eat fruit to maintain his stamina while riding skateboards and throwing stone axes to defeat island creatures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hudson''s Adventure Island (USA)', '1991', NaN, 'Kemco', '1', NaN, 'Side-scrolling platformer.', 'Rescue Princess Leilani by surviving various tropical islands.', 'The legendary NES port of Wonder Boy, featuring Master Higgins.', 'Known for its catchy music and high difficulty, this game became a staple of the NES library, emphasizing momentum and fast-paced platforming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hudson''s Adventure Island II (USA)', '1991', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling platformer.', 'Save Higgins'' girlfriend from the evil witch doctor.', 'An improved sequel that introduces dinosaur companions.', 'Players can now ride four different dinosaurs, each with unique abilities (fire, flight, etc.), and store items in an inventory between levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hudson''s Adventure Island III (USA)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling platformer.', 'Rescue Higgins'' girlfriend from alien invaders.', 'The most refined entry in the series, featuring expanded dinosaur mechanics.', 'Higgins can now crouch, and the dinosaur roster is expanded. It features a larger world map and a non-linear feel compared to the previous entries.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hudson''s Adventure Island III (USA) [Hack by Aether Knight v1.0] (~Adventure Island 3 - The Lost Isles)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling platformer.', 'Navigate an entirely new set of islands with increased difficulty.', 'A high-quality level-hack that provides new challenges for AI3 veterans.', 'This version features completely redesigned stages and harder enemy placements, breathing fresh life into the Adventure Island III engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hudson''s Adventure Island Part II (Europe)', '1991', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling platformer.', 'Save Higgins'' girlfriend with the help of your dinosaur friends.', 'The European PAL release of the second Adventure Island adventure.', 'Featuring the same dinosaur-riding mechanics and inventory system, it offers a more balanced and accessible experience than the original title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Huge Insect (Asia) (Unl)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Vertical-scrolling shooter.', 'Pilot a starship to destroy swarms of giant mechanical insects.', 'An unlicensed space shooter by Sachen with a bug theme.', 'Players face waves of arthropod-themed enemies and bosses, using a variety of weapon power-ups in a fast-paced arcade-style combat loop.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hunt for Red October, The (Europe)', '1988', NaN, 'Rare', '1', NaN, 'Side-scrolling submarine sim.', 'Guide the Red October to the US while avoiding Soviet forces.', 'A tactical submarine game based on the Tom Clancy novel and film.', 'It blends side-scrolling navigation with tactical combat phases, where players must manage sonar, torpedoes, and evasion tactics to survive the journey.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hunt for Red October, The (USA)', '1988', NaN, 'Rare', '1', NaN, 'Side-scrolling submarine sim.', 'Guide the Red October to the US while avoiding Soviet forces.', 'A tactical submarine game based on the Tom Clancy novel and film.', 'It blends side-scrolling navigation with tactical combat phases, where players must manage sonar, torpedoes, and evasion tactics to survive the journey.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hunt for Red October, The (USA) (Rev A)', '1988', NaN, 'Rare', '1', NaN, 'Side-scrolling submarine sim.', 'Guide the Red October to the US with minor technical fixes.', 'A revised version of the submarine simulation with bug fixes.', 'This revision addresses small glitches in sonar detection and level transitions, ensuring a smoother tactical experience for the player.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hyakkiyakou (Japan)', '1988', NaN, 'Towachiki', '1', NaN, 'Board game / Strategy.', 'Lead a parade of spirits through the night to conquer territory.', 'A unique strategy game based on the Night Parade of One Hundred Demons.', 'Players move Yokai across a map, engaging in tactical battles and random events based on Japanese folklore, all presented with traditional 8-bit art.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hyaku no Sekai no Monogatari - The Tales on a Watery Wilderness (Japan)', '1991', NaN, 'ASCII', '1', NaN, 'Board game / RPG.', 'Journey through a fantasy world and reach the goal first.', 'A charming hybrid of a digital board game and a turn-based RPG.', 'Up to four players can compete, moving across tiles that trigger battles, item finds, or story events, creating a party game RPG experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hyaku no Sekai no Monogatari - The Tales on a Watery Wilderness (Japan) [En by AlanMidas v20070425] (~100 World Story, The)', '1991', NaN, 'ASCII', '1', NaN, 'Board game / RPG.', 'Journey through the fantasy world with full English text.', 'The English fan translation of the unique RPG-board game hybrid.', 'This translation is essential for understanding the many random events, item effects, and humorous dialogue that occur as players race across the world map.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hydlide (USA)', '1989', NaN, 'T&E Soft', '1', NaN, 'Action RPG.', 'Find the three jewels and defeat the demon Varalys to save Fairyland.', 'An early and influential (though controversial) action RPG.', 'Known for its bump combat system, Hydlide requires players to manage health and level up by attacking enemies. It''s a foundational title for the ARPG genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hydlide 3 - Yami Kara no Houmonsha (Japan)', '1991', NaN, 'T&E Soft', '1', NaN, 'Action RPG.', 'Stop the darkness from consuming the land in this advanced sequel.', 'A much more complex RPG featuring a weight system and day/night cycles.', 'Hydlide 3 introduced modern RPG elements like hunger and a morality system, pushing the Famicom hardware with its deep mechanical systems.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hydlide Special (Japan)', '1987', NaN, 'T&E Soft', '1', NaN, 'Action RPG.', 'Save Fairyland in this enhanced Famicom version of the original game.', 'An updated version of Hydlide featuring improved graphics and sound.', 'This version polishes the original 1984 PC-88 release for the Famicom, offering smoother gameplay and a more vibrant visual palette.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hyokkori Hyoutan Jima - Nazo no Kaizokusen (Japan)', '1991', NaN, 'Towachiki', '1', NaN, 'Adventure / Puzzle.', 'Solve the mystery of the pirate ship to protect the floating island.', 'An adventure game based on a famous Japanese puppet show.', 'Players explore the island and talk to quirky characters to gather clues and items, solving spatial puzzles to progress the charming narrative.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hyper Olympic (Genteiban!) (Japan)', '1984', NaN, 'Konami', '4', NaN, 'Sports / Athletics.', 'Win gold in various Olympic events in this limited Prize edition.', 'A rare promotional version of Hyper Olympic for the Famicom.', 'Features the same classic button-mashing gameplay as the original, but holds historical value as a special distribution for Japanese fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hyper Olympic (Japan)', '1984', NaN, 'Konami', '4', NaN, 'Sports / Athletics.', 'Compete in track and field events to achieve world records.', 'The foundational button-mashing sports game (Track & Field).', 'Players must press buttons rapidly to run and time their presses for jumps and throws. It’s the quintessential 8-bit competitive sports experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hyper Sports (Japan)', '1984', NaN, 'Konami', '4', NaN, 'Sports / Athletics.', 'Master new Olympic events like swimming and skeet shooting.', 'The official sequel to Hyper Olympic with more varied events.', 'It expands the roster of sports to include archery, triple jump, and more, requiring different rhythms and timing beyond simple rapid button-mashing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Hyper Sports (Japan) (Rev 1)', '1984', NaN, 'Konami', '4', NaN, 'Sports / Athletics.', 'Master new Olympic events with minor bug fixes.', 'A revised release of the Hyper Sports Famicom sequel.', 'This revision ensures better compatibility and fixes minor scoring glitches in certain events like the pole vault or swimming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'I Love Softball (Japan)', '1989', NaN, 'Tonkin House', '2', NaN, 'Sports / Baseball.', 'Lead your female softball team to the national championship.', 'A unique 8-bit sports title focusing on softball instead of baseball.', 'Featuring distinct physics and a female roster, this game offers a fresh take on the ball-and-bat genre with colorful sprites and fast-paced arcade gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'I Puffi (The Smurfs) (Italy)', '1994', NaN, 'Infogrames', '1', NaN, 'Side-scrolling platformer.', 'Rescue the Smurfs from Gargamel''s castle as a brave Smurf.', 'An Italian-language release of The Smurfs platformer.', 'Based on the Peyo cartoons, it features impressive 8-bit visuals for a late-release title, challenging players to navigate forests and swamps to reach Gargamel''s lair.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ice Climber (Japan)', '1985', NaN, 'Nintendo', '2', NaN, 'Vertical platformer.', 'Scale 32 icy mountains to retrieve stolen vegetables from a giant bird.', 'A foundational Nintendo classic featuring Popo and Nana.', 'Players use hammers to break through layers of ice while avoiding seals and birds. It is famous for its cooperative play and the challenging bonus stage at the peak.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ice Climber (USA, Europe)', '1985', NaN, 'Nintendo', '2', NaN, 'Vertical platformer.', 'Scale 32 icy mountains to retrieve stolen vegetables from a giant bird.', 'A foundational Nintendo classic featuring Popo and Nana.', 'Players use hammers to break through layers of ice while avoiding seals and birds. It is famous for its cooperative play and the challenging bonus stage at the peak.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ice Hockey (Europe)', '1988', NaN, 'Nintendo', '2', NaN, 'Sports / Hockey.', 'Outscore your opponent in a fast-paced international hockey match.', 'A beloved Nintendo sports title featuring customizable team weights.', 'Players can choose between thin, medium, and fat skaters, each with different speed and power stats, creating a deep layer of strategy for an 8-bit sports game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ice Hockey (USA)', '1988', NaN, 'Nintendo', '2', NaN, 'Sports / Hockey.', 'Outscore your opponent in a fast-paced international hockey match.', 'A beloved Nintendo sports title featuring customizable team weights.', 'Players can choose between thin, medium, and fat skaters, each with different speed and power stats, creating a deep layer of strategy for an 8-bit sports game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ide Yousuke Meijin no Jissen Mahjong (Japan) (Rev A)', '1989', NaN, 'Capcom', '2', NaN, 'Mahjong / Strategy.', 'Defeat Mahjong masters using expert techniques and luck.', 'A professional Mahjong simulation endorsed by expert Yousuke Ide.', 'This version features refined AI and updated logic for more realistic tile-drawing, catering to serious fans of the traditional Japanese four-player game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ide Yousuke Meijin no Jissen Mahjong 2 (Japan)', '1990', NaN, 'Capcom', '2', NaN, 'Mahjong / Strategy.', 'Climb the ranks of the Mahjong world in this expanded sequel.', 'An improved simulation featuring better graphics and a career mode.', 'It includes more detailed tutorials and strategic advice from Ide himself, making it one of the most comprehensive Mahjong titles on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Idol Hakkenden (English Patched)', '1990', NaN, 'Towachiki', '1', NaN, 'Adventure / Visual Novel.', 'Help Erika become a pop star to inherit her grandfather''s fortune.', 'An English fan translation of a quirky musical adventure.', 'This translation makes the humorous dialogue and song-based battles accessible, allowing Western fans to enjoy this unique idol-themed story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Idol Hakkenden (Japan)', '1990', NaN, 'Towachiki', '1', NaN, 'Adventure / Visual Novel.', 'Help Erika become a pop star to inherit her grandfather''s fortune.', 'A charming adventure game featuring multiple music-themed endings.', 'As Erika, players travel across Japan to find seven talented companions, blending traditional menu-driven exploration with pop-culture humor and catchy 8-bit tunes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Idol Shisen Mahjong (Japan) (Unl)', 'Unlicensed', NaN, 'Unknown', '2', NaN, 'Puzzle / Mahjong.', 'Clear the board by matching pairs of Mahjong tiles.', 'An unlicensed Shisen-sho style tile-matching puzzle game.', 'Often featuring high-quality idol art as rewards, it challenges the player''s pattern recognition skills in a race against the clock.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Igo - Kyuu Roban Taikyoku (Japan)', '1983', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Master the game of Go on a smaller 9x9 grid.', 'A focused version of Go designed for quick play and beginners.', 'By using a smaller board, the game emphasizes the core tactical maneuvers of Go, providing a faster and more intense experience than the full-sized version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Igo Meikan (Japan)', '1987', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Study famous Go matches and solve complex tactical puzzles.', 'A specialized educational title for Go enthusiasts.', 'This game functions as an 8-bit interactive book, allowing players to recreate historical moves and learn from the masters of the game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Igo Shinan ''91 (Japan)', '1991', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Improve your Go skills with updated 1991 professional tactics.', 'Part of a long-running series of Go instructional games.', 'It features improved AI and new scenarios based on the professional Go circuit of 1991, offering a serious tool for practice and play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Igo Shinan ''92 (Japan)', '1992', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Master the game of Go with refined 1992-era challenges.', 'An updated installment of the popular Go simulation series.', 'Featuring adjusted difficulty levels and more complex endgame scenarios, it continues the series'' tradition of high-quality 8-bit board game strategy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Igo Shinan ''93 (Japan)', '1993', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Conquer new Go opponents with updated 1993 logic.', 'The third annual update to the Famicom''s premier Go series.', 'This version includes a larger library of joseki (standard sequences) and a more aggressive AI, challenging even experienced Go players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Igo Shinan ''94 (Japan)', '1994', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Reach the peak of 8-bit Go mastery in this final annual update.', 'The most advanced entry in the Igo Shinan series for Famicom.', 'Representing the technical peak of Go AI on the hardware, it offers the most challenging and complete 8-bit Go experience available.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Igo Shinan (Japan)', '1983', NaN, 'Nintendo', '2', NaN, 'Board game / Strategy.', 'Learn the fundamentals of Go through interactive lessons.', 'The first entry in the long-running Famicom Go instruction series.', 'It established the menu-driven system and AI routines that would make the series a staple for Japanese board game fans on the console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikari (Japan)', '1985', NaN, 'SNK', '2', NaN, 'Top-down run and gun.', 'Infiltrate enemy territory as Ralf and Clark to stop a coup.', 'The Japanese version of the legendary SNK arcade port.', 'Known for its intense difficulty and the ability to pilot tanks, it set the standard for military-themed top-down shooters on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikari II - Dogosoken (Japan)', '1987', NaN, 'SNK', '2', NaN, 'Top-down action.', 'Battle through mythological realms to defeat the dark gods.', 'The Japanese version of Victory Road, the second Ikari game.', 'This sequel moves the series into a sci-fi/fantasy setting, where the heroes fight aliens and monsters using futuristic weapons and mystical swords.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikari III - The Rescue (USA)', '1991', NaN, 'SNK', '2', NaN, 'Top-down beat ''em up.', 'Infiltrate the enemy base to rescue the kidnapped president''s daughter.', 'The third entry, which shifts the focus to hand-to-hand combat.', 'Unlike the first two games, Ikari III focuses more on punching and kicking through waves of enemies, while still maintaining the top-down perspective.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikari III (Japan)', '1991', NaN, 'SNK', '2', NaN, 'Top-down beat ''em up.', 'Infiltrate the enemy base to rescue the kidnapped president''s daughter.', 'The original Japanese release of the third Ikari title.', 'Featuring larger character sprites and more fluid martial arts animations, it offers a distinct brawler feel compared to the previous shooting-focused entries.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikari Warriors (Europe)', '1986', NaN, 'SNK', '2', NaN, 'Top-down run and gun.', 'Infiltrate enemy territory as Ralf and Clark to stop a coup.', 'The PAL version of the iconic SNK military shooter.', 'Players must manage limited ammunition and fuel while navigating jungles and enemy bases, fighting through waves of soldiers and armored vehicles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikari Warriors (USA)', '1986', NaN, 'SNK', '2', NaN, 'Top-down run and gun.', 'Infiltrate enemy territory as Ralf and Clark to stop a coup.', 'A high-octane 8-bit military shooter famous for its ABBA cheat code.', 'Despite some technical slowdown, it captures the arcade''s spirit, challenging players to coordinate movement and fire in a brutal jungle warzone.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikari Warriors (USA) (Rev A)', '1986', NaN, 'SNK', '2', NaN, 'Top-down run and gun.', 'Infiltrate enemy territory with minor technical fixes.', 'A revised version of the first Ikari Warriors for the NES.', 'This revision addresses specific collision bugs and improves some of the sprite-flicker issues present in the initial North American release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikari Warriors II - Victory Road (USA)', '1988', NaN, 'SNK', '2', NaN, 'Top-down action.', 'Fight through the future to return home and save humanity.', 'The Western release of Victory Road, featuring a heavy metal vibe.', 'Players explore weird alien worlds, collecting power-ups and using both guns and swords to defeat bizarre extra-terrestrial creatures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ike Ike! Nekketsu Hockey Bu - Subette Koronde Dai Rantou (Japan)', '1989', NaN, 'Technos Japan', '4', NaN, 'Sports / Hockey.', 'Lead Kunio-kun''s team to victory in a violent hockey tournament.', 'A legendary comedic hockey game where fighting is encouraged.', 'As part of the Nekketsu series, players can use super-shots, hit opponents with sticks, and engage in chaotic brawls on the ice to win games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ike Ike! Nekketsu Hockey Bu - Subette Koronde Dai Rantou (Japan) [En by Disconnected v0.99] (Technos Ice Hockey)', '1989', NaN, 'Technos Japan', '4', NaN, 'Sports / Hockey.', 'Win the hockey tournament with translated menus and names.', 'An English fan translation that preserves the Technos brand feel.', 'This translation makes the team customization and story modes accessible, allowing fans to enjoy Kunio''s foray into the world of 8-bit ice hockey.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ike Ike! Nekketsu Hockey Bu - Subette Koronde Dai Rantou (Japan) [En by TransBRC v1.1] (Technos Ice Hockey)', '1989', NaN, 'Technos Japan', '4', NaN, 'Sports / Hockey.', 'Win the hockey tournament with a polished English translation.', 'An alternative English version of the Nekketsu Hockey classic.', 'This version focuses on making the dialogue and special move descriptions as clear as possible for a smooth gameplay experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikinari Musician (Japan)', '1990', NaN, 'ASCII', '1', NaN, 'Music / Creativity.', 'Compose and play your own digital music on the Famicom.', 'A music creation tool that turns the console into a synthesizer.', 'It allows players to experiment with different waveforms and instruments, featuring a recording mode to save and playback 8-bit compositions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikinari Musician (Japan) (Beta)', '1990', NaN, 'ASCII', '1', NaN, 'Music / Creativity.', 'Create digital music in this early development version.', 'A rare prototype of the music creation software.', 'This version offers a look at the early UI and sound engine before the final retail release, sometimes featuring different sample sounds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ikki (Japan)', '1985', NaN, 'Sunsoft', '1', NaN, 'Multi-directional shooter.', 'Lead a peasant rebellion to overthrow a greedy landlord.', 'An early Sunsoft arcade port known for its quirky peasant theme.', 'Players throw sickles and collect coins while dodging ninjas and ghosts. It''s famous in Japan for being one of the first Kuso-ge (lovably bad games).', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Image Fight (Japan)', '1989', NaN, 'Irem', '1', NaN, 'Vertical shoot ''em up.', 'Pass the pilot trials to lead an assault against an alien entity.', 'A challenging Irem shooter with unique Pod mechanics.', 'Known for its steep difficulty, players must strategically position orbs (Pods) to shoot in different directions while surviving intense bullet patterns.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Image Fight (USA)', '1989', NaN, 'Irem', '1', NaN, 'Vertical shoot ''em up.', 'Pass the pilot trials to lead an assault against an alien entity.', 'A faithful NES port of the tactical Irem arcade shooter.', 'The US version maintains the high difficulty and the iconic combat training stages that determine your final mission rank.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Immortal, The (USA)', '1990', NaN, 'Electronic Arts', '1', NaN, 'Isometric action / Puzzle.', 'Descend into the labyrinth to rescue your mentor, Mordamir.', 'A dark, atmospheric RPG known for its brutal death animations.', 'Featuring complex puzzles and real-time combat, it stands out for its mature tone, high-quality graphics, and isometric exploration.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Impossible Mission II (USA) (Unl)', 'Unlicensed', NaN, 'Epyx', '1', NaN, 'Action / Platformer.', 'Infiltrate Elvin''s towers and recover the musical passcodes.', 'An unlicensed port of the classic Epyx computer adventure.', 'Players must search furniture and hack terminals while avoiding security robots in a race against the clock to stop a nuclear launch.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Incantation (Asia) (Unl) (Famicom)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling action.', 'Use your magic wand to defeat monsters in a fantasy realm.', 'An unlicensed Famicom action title by Sachen.', 'Players control a young wizard through various levels, collecting power-ups and fighting bosses in a style similar to other 8-bit fantasy platformers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Incredible Crash Dummies, The (Europe)', '1993', NaN, 'Gray Matter', '1', NaN, 'Action / Mini-games.', 'Complete various safety tests to prove you are the best dummy.', 'A colorful game based on the popular safety-themed toy line.', 'It features varied levels like car crashes, tire-rolling races, and platforming, all emphasizing the destruction gimmick of the characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Incredible Crash Dummies, The (USA)', '1993', NaN, 'Gray Matter', '1', NaN, 'Action / Mini-games.', 'Complete various safety tests to prove you are the best dummy.', 'A colorful game based on the popular safety-themed toy line.', 'It features varied levels like car crashes, tire-rolling races, and platforming, all emphasizing the destruction gimmick of the characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Indiana Jones and the Last Crusade (Europe)', '1989', NaN, 'Taito', '1', NaN, 'Side-scrolling action.', 'Find the Holy Grail and rescue Indy''s father from the Nazis.', 'The European version of the cinematic movie adaptation.', 'Following the film''s plot, Indy travels through Venice and castles, using his whip to swing over pits and fight enemies in a balanced platforming quest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Indiana Jones and the Last Crusade (USA) (Taito)', '1989', NaN, 'Taito', '1', NaN, 'Side-scrolling action.', 'Find the Holy Grail and rescue Indy''s father from the Nazis.', 'A polished Taito-developed adventure with great visuals.', 'This version is praised for its detailed sprites and faithful locations. It features multiple paths and puzzles that capture the adventurous spirit of the film.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Indiana Jones and the Last Crusade (USA) (UBI Soft)', '1988', NaN, 'Ubi Soft', '1', NaN, 'Side-scrolling action.', 'Find the Holy Grail and rescue Indy''s father from the Nazis.', 'A different interpretation of the film by UBI Soft.', 'Featuring a focus on combat and exploration, this version offers a distinct level layout and artistic style compared to the Taito release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Indiana Jones and the Temple of Doom (USA)', '1988', NaN, 'Taito', '1', NaN, 'Side-scrolling action.', 'Rescue the village children and recover the Sankara Stones.', 'An action-heavy adaptation of the second Indiana Jones film.', 'Players explore the dark mines of Mola Ram, using the whip to fight cultists and riding mine carts in fast-paced, hazardous sequences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Indiana Jones and the Temple of Doom (USA) (Rev A)', '1988', NaN, 'Ubi Soft', '1', NaN, 'Side-scrolling action.', 'Rescue the children and recover the stones with bug fixes.', 'A revised version of the Mindscape Indiana Jones game.', 'This update addresses minor level design issues and improves the physics of the whip, making the mining levels slightly more manageable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Indiana Jones and the Temple of Doom (USA) (Unl)', '1988', NaN, 'Taito', '1', NaN, 'Side-scrolling action.', 'Rescue the village children and recover the Sankara Stones.', 'The unlicensed black-cartridge version released by Tengen.', 'Identical in gameplay to the licensed release but sold outside Nintendo''s control, featuring the same arcade-style action and mine-cart levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Indora no Hikari (Japan)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Turn-based RPG.', 'Travel through fantasy worlds to restore light to the land.', 'A classic Famicom RPG featuring party-based combat.', 'Known for its colorful graphics and traditional mechanics, players explore towns and dungeons, talking to NPCs to unravel a grand mythological story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Infiltrator (USA)', '1991', NaN, 'Kemco', '1', NaN, 'Flight sim / Action.', 'Fly into enemy territory and complete stealth missions on foot.', 'A hybrid game blending helicopter simulation with top-down action.', 'Players must master the cockpit controls of the Gizmo helicopter before landing to perform sabotage missions in a high-stakes 8-bit spy thriller.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Insector X (Japan)', '1990', NaN, 'Irem', '1', NaN, 'Horizontal shoot ''em up.', 'Fight through the insect kingdom to defeat the mechanical Queen.', 'A quirky shooter featuring an insect-sized hero in a big world.', 'Players use diverse power-ups to shoot through swarms of bees and beetles, featuring impressive parallax scrolling and large, bug-themed bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'International Cricket (Australia)', '1991', NaN, 'Melbourne House', '2', NaN, 'Sports / Cricket.', 'Win the world series in this professional cricket simulation.', 'A rare and detailed cricket game released specifically for Australia.', 'It offers comprehensive control over batting, bowling, and fielding, featuring realistic rules and multiple international teams.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'International Cricket (Australia) (Beta)', '1991', NaN, 'Melbourne House', '2', NaN, 'Sports / Cricket.', 'Win the world series in this early development version.', 'A prototype of the Australian cricket simulator.', 'This version shows early menus and slightly different physics for the ball, providing a look at how the 8-bit cricket logic was refined.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Iron Tank - The Invasion of Normandy (Europe)', '1988', NaN, 'SNK', '2', NaN, 'Top-down shooter.', 'Drive through Normandy and destroy the Nazi secret weapon.', 'An intense SNK tank shooter with branching paths.', 'Known for its high-quality soundtrack and tactical depth, players can choose different routes and upgrade their tank''s weapons to survive the war.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Iron Tank - The Invasion of Normandy (USA)', '1988', NaN, 'SNK', '2', NaN, 'Top-down shooter.', 'Drive through Normandy and destroy the Nazi secret weapon.', 'An intense SNK tank shooter with branching paths.', 'Known for its high-quality soundtrack and tactical depth, players can choose different routes and upgrade their tank''s weapons to survive the war.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ironsword - Wizards & Warriors II (Europe)', '1989', NaN, 'Rare', '1', NaN, 'Action platformer.', 'Collect the elements of the sword to defeat the wizard Malkil.', 'The high-fantasy sequel to Wizards & Warriors.', 'Featuring Fabio on the cover, this game expands on the original with massive levels and more complex magic systems, all with a distinct Acclaim style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ironsword - Wizards & Warriors II (USA)', '1989', NaN, 'Rare', '1', NaN, 'Action platformer.', 'Collect the elements of the sword to defeat the wizard Malkil.', 'The high-fantasy sequel to Wizards & Warriors.', 'Featuring Fabio on the cover, this game expands on the original with massive levels and more complex magic systems, all with a distinct Acclaim style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Isaki Shuugorou no Keiba Hisshou Gaku (Japan)', '1990', NaN, 'KID', '1', NaN, 'Sports / Horse Racing.', 'Place bets and manage horses to win at the digital racetrack.', 'A detailed horse racing simulation with a focus on statistics.', 'Based on the expertise of a famous Japanese racing commentator, it offers deep menus for analyzing horse data and betting strategies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ishin no Arashi (Japan)', '1990', NaN, 'KID', '1', NaN, 'Turn-based strategy.', 'Navigate the political unrest of the Meiji Restoration.', 'A complex Koei historical simulation set in late 19th-century Japan.', 'Players take on the role of historical figures, using diplomacy and military force to influence the fate of the nation during a period of massive change.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Isolated Warrior (Europe)', '1991', NaN, 'ASCII', '1', NaN, 'Isometric shooter.', 'Fight through an alien-invaded world to save humanity.', 'A fast-paced shooter with a unique isometric perspective.', 'Known for its pseudo-3D graphics, it combines running and jumping with intense shooting, featuring great music and a futuristic Mad Max aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Isolated Warrior (USA)', '1989', NaN, 'Rare', '2', NaN, 'Isometric shooter.', 'Fight through an alien-invaded world to save humanity.', 'A fast-paced shooter with a unique isometric perspective.', 'Known for its pseudo-3D graphics, it combines running and jumping with intense shooting, featuring great music and a futuristic Mad Max aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Itadaki Street - Watashi no Mise ni Yottette (Japan)', '1989', NaN, 'Rare', '2', NaN, 'Board game / Strategy.', 'Buy properties and stocks to become the wealthiest player.', 'The first game in the famous Fortune Street digital board game series.', 'Created by Yuji Horii, it blends Monopoly-style property buying with a complex stock market system, making it a deep and addictive multiplayer experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ivan ''Ironman'' Stewart''s Super Off-Road (Europe)', '1993', NaN, 'Konami', '2', NaN, 'Isometric racing.', 'Race on dirt tracks to earn money and upgrade your truck.', 'A high-speed arcade racer featuring Ivan Stewart''s endorsement.', 'Players compete on bumpy, loop-based tracks, using nitrous boosts to gain an edge. The goal is to finish in the top positions to fund better tires and acceleration.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ivan ''Ironman'' Stewart''s Super Off-Road (USA)', '1994', NaN, 'Konami', '2', NaN, 'Isometric racing.', 'Race on dirt tracks to earn money and upgrade your truck.', 'A high-speed arcade racer featuring Ivan Stewart''s endorsement.', 'Players compete on bumpy, loop-based tracks, using nitrous boosts to gain an edge. The goal is to finish in the top positions to fund better tires and acceleration.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'J.League Fighting Soccer - The King of Ace Strikers (Japan)', '1994', NaN, 'Konami', '2', NaN, 'Sports / Soccer.', 'Win the Japanese J.League championship with your chosen team.', 'A fast-paced soccer sim featuring real Japanese clubs and players.', 'It offers a more arcade-like approach to football, with smooth scrolling and simplified controls that focus on high-scoring matches and league progression.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'J.League Winning Goal (Japan)', '1988', NaN, 'Kemco', '1', NaN, 'Sports / Soccer.', 'Lead your club to the top of the Japanese pro league.', 'A polished late-era Famicom soccer game with detailed stats.', 'Featuring better graphics than its predecessors, it includes a management mode and refined pitch perspectives for a more professional 8-bit sports experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'J.League Winning Goal (Japan) [En by Stardust Crusaders v1.0]', '1988', NaN, 'Kemco', '1', NaN, 'Sports / Soccer.', 'Lead your club to the top with fully translated menus and stats.', 'The English fan translation of the advanced J.League sim.', 'This version allows Western players to fully understand the strategic management menus and player statistics of this Japanese-exclusive soccer title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf (Europe)', '1988', NaN, 'Konami', '2', NaN, 'Sports / Golf.', 'Play through the world''s most famous holes with low scores.', 'A technical golf simulation endorsed by the legendary Jack Nicklaus.', 'This game focuses on realism, requiring players to account for wind and terrain on meticulously recreated 8-bit versions of major championship courses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf (USA)', '1987', NaN, 'Hudson Soft', '1', NaN, 'Sports / Golf.', 'Play through the world''s most famous holes with low scores.', 'A technical golf simulation endorsed by the legendary Jack Nicklaus.', 'This game focuses on realism, requiring players to account for wind and terrain on meticulously recreated 8-bit versions of major championship courses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jackal (USA)', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Top-down run and gun.', 'Infiltrate enemy territory with a jeep to rescue POWs.', 'One of the most beloved and intense co-op shooters on the NES.', 'As part of an elite squad, players drive through enemy bases, upgrading their grenades to missiles to destroy tanks and rescue soldiers behind enemy lines.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jackie Chan (Japan)', '1987', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling action.', 'Fight through diverse stages to rescue your twin sister.', 'A vibrant and highly animated martial arts platformer.', 'Known for its charming art style and smooth combat, Jackie uses punches, kicks, and special moves to defeat bosses across a mystical 8-bit China.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jackie Chan stage select hack', 'Unlicensed', NaN, 'Unknown', '1', NaN, 'Side-scrolling action.', 'Play any level of the Jackie Chan adventure from the start.', 'A modified version allowing for immediate level selection.', 'This hack is perfect for players who want to jump straight into their favorite boss fights or test their skills on the more difficult late-game stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jackie Chan''s Action Kung Fu (Europe)', '1988', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action.', 'Fight through diverse stages to rescue your twin sister.', 'A vibrant and highly animated martial arts platformer.', 'Known for its charming art style and smooth combat, Jackie uses punches, kicks, and special moves to defeat bosses across a mystical 8-bit China.', NULL);
