INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jackie Chan''s Hulk Smash (USA)', '1987', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action (Hack).', 'Play as a green-colored Jackie with increased power.', 'A fun character-modifier hack for the Action Kung Fu engine.', 'This version modifies Jackie''s sprites and damage output, giving a superhero feel to the traditional martial arts gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jajamaru Gekimaden - Maboroshi no Kinmajou (Japan)', '1991', NaN, 'Vic Tokai', '1', NaN, 'Action RPG.', 'Journey to the Devil''s Castle to defeat the Phantom Lord.', 'A top-down action adventure from the Ninja Jajamaru-kun series.', 'It blends village exploration with real-time combat in dungeons, featuring a wide variety of items and magic to help Jajamaru on his quest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jajamaru Ninpou Chou (Japan)', '1991', NaN, 'Vic Tokai', '1', NaN, 'Turn-based RPG.', 'Lead Jajamaru and Sakura on a quest to save the princess.', 'The series'' first foray into traditional turn-based role-playing.', 'Unlike the action titles, this game focuses on story progression, character leveling, and strategic battles against mythological Japanese monsters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jajamaru no Daibouken (Japan)', '1988', NaN, 'Namco', '2', NaN, 'Side-scrolling action.', 'Defeat the catfish pirate and his army of Yokai.', 'A classic horizontal platformer starring the red ninja Jajamaru.', 'It features fast-paced combat where Jajamaru throws shurikens and rides a giant frog to clear swarms of enemies across various historical Japanese levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'James Bond Jr (Europe)', '1988', NaN, 'Konami', '1', NaN, 'Side-scrolling action.', 'Stop the evil S.C.U.M. organization as Bond''s talented nephew.', 'A gadget-filled action game based on the 90s animated series.', 'Players must navigate levels filled with traps, using specialized equipment like jetpacks and grenades to complete missions and dismantle global threats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'James Bond Jr (USA)', '1987', NaN, 'Westwood Associates', '1', NaN, 'Side-scrolling action.', 'Stop the evil S.C.U.M. organization as Bond''s talented nephew.', 'A gadget-filled action game based on the 90s animated series.', 'Players must navigate levels filled with traps, using specialized equipment like jetpacks and grenades to complete missions and dismantle global threats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jangou (Japan)', '1991', NaN, 'GameTek', '3', NaN, 'Mahjong / Strategy.', 'Defeat various opponents in the traditional game of Mahjong.', 'A straightforward and polished Mahjong simulation for the Famicom.', 'It focuses on the pure rules of the game, offering a challenging AI for players looking to practice their 8-bit tile-matching and strategic gambling skills.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jarinko Chie - Bakudan Musume no Shiawase Sagashi (Japan)', '1988', NaN, 'Taito', '1', NaN, 'Adventure / Visual Novel.', 'Follow the life of Chie in a series of comedic urban adventures.', 'An adventure game based on the popular manga and anime series.', 'Featuring menu-driven gameplay, players help the young and energetic Chie manage her father''s shop and deal with the eccentric characters of Osaka.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jaws (USA)', '1987', NaN, 'LJN', '1', NaN, 'Action / Hunting.', 'Hunt down the great white shark across the ocean.', 'An LJN-published game where you upgrade your ship to kill Jaws.', 'Players sail a map, engaging in mini-games to collect shells and power-ups, culminating in a first-person harpoon battle against the legendary shark.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jeopardy! (USA)', '1988', NaN, 'GameTek', '2', NaN, 'Quiz / Trivia.', 'Answer questions in the form of a question to win money.', 'An 8-bit adaptation of the world-famous television game show.', 'It features a large database of questions across various categories, challenging players to buzz in first and manage their winnings for Final Jeopardy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jeopardy! (USA) (Rev A)', '1988', NaN, 'GameTek', '2', NaN, 'Quiz / Trivia.', 'Answer questions in the form of a question to win money.', 'A revised version with improved logic for text input.', 'This update polishes the answer-recognition system, making the game more forgiving with spelling and improving the overall flow of the trivia rounds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jeopardy! 25th Anniversary Edition (USA)', '1990', NaN, 'GameTek', '2', NaN, 'Quiz / Trivia.', 'Win the ultimate trivia tournament in this anniversary special.', 'An updated version featuring thousands of new questions.', 'Celebrating 25 years of the show, this edition includes more difficult categories and a refined presentation of the classic Jeopardy! experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jeopardy! Junior Edition (USA)', '1989', NaN, 'GameTek', '2', NaN, 'Quiz / Trivia.', 'Win money in this youth-oriented version of the game show.', 'A version of Jeopardy! featuring easier questions for younger players.', 'While the gameplay remains the same, the categories focus on pop culture, cartoons, and basic school subjects suited for a younger audience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jesus - Kyoufu no Bio Monster (Japan)', '1987', NaN, 'Enix', '1', NaN, 'Adventure / Sci-Fi.', 'Investigate a biological threat on a space station near Halley''s Comet.', 'A cinematic sci-fi adventure with a strong horror atmosphere.', 'Known for its incredible music and detailed cutscenes, players navigate menus to solve puzzles and uncover the mystery of the Jesus monster.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jesus - Kyoufu no Bio Monster (Japan) [En by Niahak v1.1]', '1987', NaN, 'Enix', '1', NaN, 'Adventure / Sci-Fi.', 'Solve the space station mystery with full English translation.', 'The English fan translation of the cult classic sci-fi adventure.', 'This version is vital for Western fans to experience the tension-filled story and complex puzzles of this unique Famicom thriller.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jetsons, The - Cogswell''s Caper! (Europe)', '1992', NaN, 'Taito', '1', NaN, 'Side-scrolling platformer.', 'Stop Cogswell''s environmental plot as George Jetson.', 'A late-release high-quality platformer by Taito.', 'George uses gadgets and switches between gravity-defying shoes to navigate futuristic levels, featuring the whole Jetson family and great 8-bit visuals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jetsons, The - Cogswell''s Caper! (Japan)', '1992', NaN, 'Taito', '1', NaN, 'Side-scrolling platformer.', 'Stop Cogswell''s environmental plot as George Jetson.', 'The Japanese version of the polished Taito platformer.', 'It maintains the excellent level design and music, proving to be one of the best examples of a cartoon-to-game adaptation on the Famicom hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jetsons, The - Cogswell''s Caper! (USA)', '1992', NaN, 'Taito', '1', NaN, 'Side-scrolling platformer.', 'Stop Cogswell''s environmental plot as George Jetson.', 'A late-release high-quality platformer by Taito.', 'George uses gadgets and switches between gravity-defying shoes to navigate futuristic levels, featuring the whole Jetson family and great 8-bit visuals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jigoku Gokuraku Maru (Japan)', '1988', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action.', 'Battle demons across Tokyo to stop a supernatural threat.', 'Known in the West as Kabuki Quantum Fighter.', 'Players control a digital version of a Kabuki actor who uses his long hair as a whip. It features a cool cyberpunk aesthetic and very tight platforming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jikuu Yuuden - Debias (Japan)', '1988', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer with shooting and jumping mechanics', 'Defeat enemies and bosses to progress through stages', 'A futuristic action platformer with intense combat', 'Jikuu Yuuden - Debias is a sci-fi side-scrolling action game where players control a cybernetic warrior fighting through hostile environments. The gameplay focuses on precise jumping, fast shooting, and defeating powerful bosses while uncovering a dark futuristic storyline.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jimmy Connors Tennis (Europe)', '1988', NaN, 'NMS Software', '2', NaN, 'Sports tennis simulation with arcade-style controls', 'Win matches by scoring more points than the opponent', 'A fast-paced tennis game featuring real player branding', 'Jimmy Connors Tennis offers an accessible yet competitive tennis experience on NES. Players compete in singles matches using responsive controls, timing-based shots, and strategic positioning inspired by arcade sports games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jimmy Connors Tennis (USA)', '1988', NaN, 'NMS Software', '2', NaN, 'Sports tennis simulation with arcade-style controls', 'Win matches by scoring more points than the opponent', 'A fast-paced tennis game featuring real player branding', 'Jimmy Connors Tennis delivers classic NES sports gameplay with easy-to-learn mechanics. Players face off in tennis matches emphasizing reflexes, court coverage, and simple but satisfying competitive play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'JJ - Tobidase Daisakusen Part 2 (Japan)', '1991', NaN, 'NCS', '1', NaN, 'Isometric action platformer with jumping challenges', 'Reach the goal by navigating hazardous stages', 'An isometric action game focused on precision jumps', 'JJ - Tobidase Daisakusen Part 2 challenges players with angled perspectives and demanding platforming. The game emphasizes spatial awareness, enemy avoidance, and careful timing across multiple obstacle-filled stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'JJ - Tobidase Daisakusen Part 2 (Japan) [En by DvD v1.0] (~JJ - Jump Out! The Epic War - Part II)', '1991', NaN, 'NCS', '1', NaN, 'Isometric action platformer with jumping challenges', 'Reach the goal by navigating hazardous stages', 'An isometric action game focused on precision jumps', 'This translated version of JJ - Tobidase Daisakusen Part 2 allows English-speaking players to enjoy its unique 3D-like platforming. The game rewards patience, memorization, and mastery of tricky jumps.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'JJ - Tobidase Daisakusen Part 2 (Japan) [En by DvD v1.0] (~JJ - The 3-D Battles of WorldRunner - Part II)', '1991', NaN, 'NCS', '1', NaN, 'Isometric action platformer with jumping challenges', 'Reach the goal by navigating hazardous stages', 'A challenging sequel to an early 3D-style action game', 'Known in English as The 3-D Battles of WorldRunner Part II, this game expands on its predecessor with tougher levels, faster pacing, and demanding precision-based gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Joe & Mac - Caveman Ninja (Europe)', '1991', NaN, 'Data East', '2', NaN, 'Side-scrolling platformer with combat and cooperative play', 'Defeat enemies and rescue caveman allies', 'A colorful prehistoric action platformer', 'Joe & Mac - Caveman Ninja is a vibrant platform game where players battle dinosaurs and rival tribes using clubs and projectiles. The game supports cooperative play and is known for its humor and fast-paced action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Joe & Mac (USA)', '1991', NaN, 'Data East', '2', NaN, 'Side-scrolling platformer with combat and cooperative play', 'Defeat enemies and rescue caveman allies', 'A colorful prehistoric action platformer', 'Joe & Mac brings classic arcade-style platforming to NES, combining tight controls, enemy-filled stages, and charming visuals set in a comedic prehistoric world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'John Elway''s Quarterback (USA)', '1988', NaN, 'Rare', '2', NaN, 'American football sports simulation with play selection', 'Score touchdowns and win football games', 'A strategic football game starring an NFL quarterback', 'John Elway''s Quarterback focuses on play-calling and execution rather than arcade action. Players choose offensive plays and attempt to outscore opponents using timing, positioning, and football strategy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jongbou (Japan)', '1988', NaN, 'ASCII', '2', NaN, 'Traditional mahjong board game simulation', 'Win matches by forming winning tile hands', 'A digital version of classic Japanese mahjong', 'Jongbou is a faithful NES adaptation of Japanese mahjong. The game emphasizes rules knowledge, strategic tile management, and careful decision-making rather than action-based gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jordan vs Bird - One On One (USA)', '1983', NaN, 'Electronic Arts', '2', NaN, 'One-on-one basketball sports game', 'Outscore the opponent in direct matches', 'A basketball game featuring legendary players', 'Jordan vs Bird recreates iconic basketball matchups in a fast-paced one-on-one format. Players control either athlete and rely on shooting accuracy, defense, and positioning to win.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Joshua & the Battle of Jericho (USA) (Unl) (v5.0)', '1992', NaN, 'Unknown', '1', NaN, 'Top-down action adventure with religious themes', 'Complete biblical challenges and defeat enemies', 'A faith-based action game inspired by biblical stories', 'Joshua & the Battle of Jericho is a unique NES title combining action gameplay with biblical storytelling. Players guide Joshua through maze-like stages while overcoming enemies and obstacles rooted in religious themes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Joshua & the Battle of Jericho (USA) (Unl) (v6.0)', '1992', NaN, 'Unknown', '1', NaN, 'Top-down action adventure with religious themes', 'Complete biblical challenges and defeat enemies', 'A faith-based action game inspired by biblical stories', 'Version 6.0 of Joshua & the Battle of Jericho refines gameplay and balance while maintaining its distinctive religious narrative. The game blends arcade action with spiritual themes uncommon on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Journey to Silius (Europe)', '1990', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action platformer with shooting mechanics', 'Defeat enemies and survive futuristic stages', 'A cult-classic sci-fi action platformer', 'Journey to Silius is known for its intense action and acclaimed soundtrack. Players fight through mechanical enemies using advanced weapons in a dark science fiction setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Journey to Silius (USA)', '1990', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action platformer with shooting mechanics', 'Defeat enemies and survive futuristic stages', 'A cult-classic sci-fi action platformer', 'This USA release of Journey to Silius delivers challenging gameplay, smooth controls, and memorable music. The game is praised as one of the finest action titles on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Journey to the West (Asia) (Unl)', '1991', NaN, 'Unknown', '1', NaN, 'Action adventure with platforming and combat', 'Reach the end of the journey inspired by mythology', 'A mythological action game based on Journey to the West', 'Journey to the West draws inspiration from classic Chinese literature. Players navigate stages filled with enemies and traps, blending action, platforming, and fantasy elements.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Joust (Japan)', '1983', NaN, 'Atari', '2', NaN, 'Arcade-style platformer with flying and combat mechanics', 'Defeat enemies and survive increasingly difficult waves', 'A classic arcade action game', 'Joust tasks players with flying atop a bird while battling enemies in floating arenas. The gameplay focuses on altitude control and timing, making it a timeless arcade experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Joust (USA)', '1983', NaN, 'Atari', '2', NaN, 'Arcade-style platformer with flying and combat mechanics', 'Defeat enemies and survive increasingly difficult waves', 'A classic arcade action game', 'This NES version of Joust faithfully recreates the original arcade gameplay, offering fast-paced action and simple yet highly addictive mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jovial Race (Asia) (Unl) (NES)', '1992', NaN, 'Unknown', '2', NaN, 'Top-down racing game with obstacle avoidance', 'Finish races without crashing', 'A simple and colorful arcade racing game', 'Jovial Race is an unlicensed NES racing title featuring straightforward controls and bright visuals. Players navigate tracks while avoiding obstacles and maintaining speed.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jovial Race (Unl)', '1992', NaN, 'Unknown', '2', NaN, 'Top-down racing game with obstacle avoidance', 'Finish races without crashing', 'A simple and colorful arcade racing game', 'This unlicensed version of Jovial Race offers quick arcade-style races with minimal complexity, focusing on reflexes and track memorization.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Joy Mech Fight (Japan)', '1993', NaN, 'Nintendo', '2', NaN, '2D Fighting.', 'Defeat the rogue robots and stop Dr. Walder''s world conquest.', 'A late-release masterpiece featuring fluid, limb-less robot fighters.', 'Using a brilliant animation technique, this game offers the most fluid 1-on-1 fighting experience on the NES, with over 30 playable characters and deep move sets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Joy Mech Fight (Japan) [En by AlanMidas v20001214]', '1993', NaN, 'Nintendo', '2', NaN, '2D Fighting.', 'Stop Dr. Walder with fully translated menus and story.', 'The English fan translation of Nintendo''s premier 8-bit fighter.', 'This version makes the robot upgrades and the humorous story accessible, allowing Western fans to enjoy one of the most technically impressive games on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'JuJu Densetsu (Japan)', '1989', NaN, 'Taito', '1', NaN, 'Run and gun / Platformer.', 'Rescue your girlfriend as a human turned into a powerful ape.', 'The Japanese version of the arcade hit Toki.', 'Players spit rapid-fire projectiles and navigate dangerous jungles. It''s known for its unique protagonist and challenging, deliberate platforming action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jumbo Ozaki no Hole in One Professional (Japan)', '1988', NaN, 'Nintendo', '1', NaN, 'Sports / Golf.', 'Master the professional tour with the help of Jumbo Ozaki.', 'A detailed golf simulation featuring one of Japan''s greatest pros.', 'It offers a realistic approach to the sport, with deep menus for club selection and green reading, providing a high-quality 8-bit golfing experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jumpin'' Kid - Jack to Mame no Ki Monogatari (Japan)', '1989', NaN, 'Asmik', '1', NaN, 'Side-scrolling platformer.', 'Climb the beanstalk to rescue the princess from the giants.', 'A creative 8-bit retelling of Jack and the Beanstalk.', 'Players jump through clouds and castles, using various power-ups to defeat fairy-tale enemies in this colorful and charming Japanese exclusive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jungle Book, The (Europe)', '1994', NaN, 'Virgin Interactive', '1', NaN, 'Side-scrolling action.', 'Help Mowgli navigate the jungle to reach the man-village.', 'A late-era platformer known for its exceptional animation and music.', 'Players collect gems and fruit while swinging on vines and dodging Shere Khan’s minions, showcasing some of the best visual work on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jungle Book, The (USA)', '1994', NaN, 'Virgin Interactive', '1', NaN, 'Side-scrolling action.', 'Help Mowgli navigate the jungle to reach the man-village.', 'A late-era platformer known for its exceptional animation and music.', 'Players collect gems and fruit while swinging on vines and dodging Shere Khan’s minions, showcasing some of the best visual work on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Junkoid', '1992', NaN, 'Unknown', '1', NaN, 'Action / Exploration.', 'Explore a post-apocalyptic world made of scrap to survive.', 'A modern homebrew style action game with a unique aesthetic.', 'Featuring a world built from garbage and mechanical parts, this title challenges players to scavenge and fight through non-linear 8-bit environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jurassic Boy 2 (Asia) (Unl)', '1991', NaN, 'Unknown', '1', NaN, 'Side-scrolling platformer.', 'Guide a young dinosaur through levels filled with hazards.', 'An unlicensed platformer heavily inspired by Sonic the Hedgehog.', 'This Chinese bootleg features fast-paced movement and loop-de-loops, attempting to replicate 16-bit speed platforming on the Famicom hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jurassic Park (Europe)', '1993', NaN, 'Ocean Software', '1', NaN, 'Top-down / Side-scrolling.', 'Rescue the guests and escape the island overrun by dinosaurs.', 'An ambitious movie tie-in featuring various gameplay perspectives.', 'Players must collect eggs and hack computers in a top-down view, occasionally switching to side-scrolling action to survive the prehistoric chaos of Isla Nublar.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Jurassic Park (USA)', '1993', NaN, 'Ocean Software', '1', NaN, 'Top-down / Side-scrolling.', 'Rescue the guests and escape the island overrun by dinosaurs.', 'An ambitious movie tie-in featuring various gameplay perspectives.', 'Players must collect eggs and hack computers in a top-down view, occasionally switching to side-scrolling action to survive the prehistoric chaos of Isla Nublar.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Just Breed (Japan)', '1992', NaN, 'Random House / NCS', '1', NaN, 'Tactical RPG.', 'Lead a large army to protect the world from an ancient evil.', 'One of the most visually stunning strategy RPGs on the Famicom.', 'Utilizing Konami''s MMC5 chip, it features massive battles, detailed sprites, and a beautiful soundtrack, telling an epic story with deep tactical combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Just Breed (Japan) [En by Stealth v1.0]', '1992', NaN, 'Random House / NCS', '1', NaN, 'Tactical RPG.', 'Experience the epic Konami strategy tale in full English.', 'The essential English fan translation of this massive 8-bit RPG.', 'This version allows players to follow the complex plot and manage the many character classes and abilities that make Just Breed a masterpiece of the genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Juuouki (Japan)', '1988', NaN, 'Westone', '1', NaN, 'Side-scrolling beat ''em up.', 'Rise from your grave and transform into beasts to save Athena.', 'The Famicom port of Sega''s legendary Altered Beast.', 'Despite the hardware limitations, this version captures the essence of the arcade, allowing players to power up and transform into wolves, dragons, and bears.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Juuouki (Japan) [En by Aka v1.0] (~Altered Beast)', '1988', NaN, 'Westone', '1', NaN, 'Side-scrolling beat ''em up.', 'Transform into powerful beasts with translated menus.', 'An English fan translation of the Famicom version of Altered Beast.', 'This version provides a nostalgic experience of the Sega classic on Nintendo hardware, featuring fully translated text for the intro and beast power-ups.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Juuryoku Soukou Metal Storm (Japan)', '1991', NaN, 'Irem', '1', NaN, 'Side-scrolling action.', 'Infiltrate the Cytron station and use gravity-shifting powers.', 'A technical marvel famous for its gravity-flipping mechanic.', 'Players control a mech that can flip between the floor and the ceiling instantly. It features incredible parallax scrolling and some of the best level design on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Juvei Quest (Japan)', '1989', NaN, 'Seibu Kaihatsu', '1', NaN, 'Turn-based RPG.', 'Lead the young ninja Juvei on a quest to save the land of Kiba.', 'A large and humorous RPG featuring a wide world to explore.', 'Often compared to Dragon Quest, it features a unique assistant system and many mini-games, wrapped in a story full of traditional Japanese folklore and comedy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kabuki - Quantum Fighter (Europe)', '1990', NaN, 'Human Entertainment', '1', NaN, 'Side-scrolling action.', 'Enter a computer mainframe as a digital Kabuki warrior.', 'A high-octane platformer with a unique hair-whip attack.', 'As Scott O''Connor, you fight through 8-bit cyberpunk levels. The game is praised for its tight controls, cinematic cutscenes, and intense boss battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kabuki - Quantum Fighter (USA)', '1990', NaN, 'Human Entertainment', '1', NaN, 'Side-scrolling action.', 'Enter a computer mainframe as a digital Kabuki warrior.', 'A high-octane platformer with a unique hair-whip attack.', 'As Scott O''Connor, you fight through 8-bit cyberpunk levels. The game is praised for its tight controls, cinematic cutscenes, and intense boss battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kabushiki Doujou (Japan)', '1989', NaN, 'Unknown', '2', NaN, 'Simulation / Strategy.', 'Learn the ropes of the stock market to become a millionaire.', 'A stock market simulation game for the Famicom.', 'Players track charts, follow news, and make trades in a virtual Japanese economy, aiming to master the complexities of 8-bit financial investment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaettekita! Gunjin Shougi - Nanya Sore! (Japan)', '1987', NaN, 'Taito', '1', NaN, 'Board game / Strategy.', 'Outsmart your opponent in a game of military-themed Shogi.', 'A quirky version of the classic Japanese strategy game.', 'It features a more casual and humorous presentation than traditional Shogi titles, making the tactical board game accessible to a wider audience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kage (Japan)', '1986', NaN, 'Taito', '1', NaN, 'Side-scrolling action.', 'Infiltrate futuristic New York and defeat the dictator Garuda.', 'Known in the West as Shadow of the Ninja or Blue Shadow.', 'A masterclass in ninja action, featuring two-player co-op, a grappling hook, and some of the best music and rain effects ever seen on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kage no Densetsu (Japan)', '1989', NaN, 'Unknown', '1', NaN, 'Side-scrolling action.', 'Rescue Princess Kiri from the evil ninja army as Kage.', 'The Famicom version of Taito''s The Legend of Kage.', 'Famous for its high-speed jumping and frantic sword fighting, players leap through forests and scale castle walls in this fast-paced arcade port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kagerou Densetsu (Japan)', '1986', NaN, 'Namco', '1', NaN, 'Adventure / Visual Novel.', 'Solve a series of mysteries in a story-driven supernatural world.', 'A text-based adventure featuring a strong atmosphere and art.', 'Players navigate through dialogue and menus to uncover the secrets of the Mayfly Legend, focusing on character interactions and mystery-solving.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaguya Hime Densetsu (Japan)', '1988', NaN, 'Birthday', '1', NaN, 'Text-based adventure with exploration and decision-making', 'Uncover the story by making correct choices', 'A Japanese folklore text adventure', 'Kaguya Hime Densetsu is a narrative-driven adventure game based on the classic Japanese tale of Princess Kaguya. Players read story text, make decisions, and explore locations to progress through the fairy-tale inspired plot.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaijuu Monogatari (Japan)', '1988', NaN, 'Birthday', '1', NaN, 'Turn-based RPG with exploration and party management', 'Defeat monsters and complete the story', 'A classic Japanese role-playing game', 'Kaijuu Monogatari is a traditional JRPG featuring turn-based battles, overworld exploration, and monster-filled dungeons. Players guide a party through a fantasy world while uncovering a heartfelt story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaijuu Monogatari (Japan) [En by KingMike v1.0Beta2] (~Shell Monsters Story)', '1986', NaN, 'Jaleco', '1', NaN, 'Turn-based RPG with exploration and party management', 'Defeat monsters and complete the story', 'A classic Japanese role-playing game', 'This English-translated version of Kaijuu Monogatari allows wider audiences to experience its charming RPG mechanics, emotional narrative, and strategic turn-based combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaiketsu Yanchamaru (Japan)', '1987', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action platformer with melee combat', 'Defeat enemies and clear stages', 'A fast-paced ninja action game', 'Kaiketsu Yanchamaru is a side-scrolling platformer where players control a young ninja fighting through enemy-filled stages. The gameplay emphasizes quick attacks, precise jumps, and reflex-based combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaiketsu Yanchamaru 2 - Karakuri Land (Japan)', '1987', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action platformer with melee combat', 'Rescue the princess and defeat bosses', 'A colorful ninja platformer sequel', 'Kaiketsu Yanchamaru 2 expands on the original with improved level design and tougher enemies. Players navigate creative stages while battling foes in a lighthearted ninja-themed adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaiketsu Yanchamaru 2 - Karakuri Land (Japan) [En by D v1.2] (~Kid Niki 2 - Karakuri Land)', '1987', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action platformer with melee combat', 'Rescue the princess and defeat bosses', 'A colorful ninja platformer sequel', 'Known in English as Kid Niki 2, this version offers classic NES action platforming with responsive controls, varied stages, and a whimsical presentation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaiketsu Yanchamaru 3 - Taiketsu! Zouringen (Japan)', '1988', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action platformer with melee combat', 'Defeat enemies and complete the final adventure', 'The final entry in the Yanchamaru trilogy', 'Kaiketsu Yanchamaru 3 delivers more challenging levels and refined gameplay. Players face new enemies and obstacles in this concluding ninja action adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaiketsu Yanchamaru 3 - Taiketsu! Zouringen (Japan) [En by Suicidal v1.0] (~Kid Niki 3)', '1988', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action platformer with melee combat', 'Defeat enemies and complete the final adventure', 'The final entry in the Yanchamaru trilogy', 'This English-translated release of Kid Niki 3 allows players to enjoy its fast-paced platforming and colorful ninja action without language barriers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kaizo Vania', '2019', NaN, 'Fan Hack', '1', NaN, 'Side-scrolling action platformer with extreme difficulty', 'Survive brutally hard stages', 'A hardcore Castlevania-style hack', 'Kaizo Vania is a fan-made hack designed for expert players. It features unforgiving enemy placement, precise jumps, and trial-and-error gameplay inspired by kaizo-style level design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kakefu Kun no Jump Tengoku - Speed Jigoku (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Side-scrolling platformer focused on jumping precision', 'Reach the end of each stage', 'A reflex-based action platformer', 'Kakefu Kun no Jump Tengoku challenges players with fast scrolling stages and demanding jumps. The game emphasizes timing, speed, and precision over combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kame no Ongaeshi - Urashima Densetsu (Japan)', '1986', NaN, 'Unknown', '1', NaN, 'Adventure game with exploration and puzzle-solving', 'Experience the folk tale and reach the ending', 'A Japanese folklore adventure', 'Kame no Ongaeshi - Urashima Densetsu retells the story of Urashima Taro through exploration and simple puzzles. The game focuses on narrative progression rather than action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kamen no Ninja - Akakage (Japan)', '1988', NaN, 'Toei', '1', NaN, 'Side-scrolling action game with ninja combat', 'Defeat enemies and complete missions', 'A classic ninja action game', 'Kamen no Ninja - Akakage features side-scrolling combat with ninja-themed enemies and stages. Players rely on quick attacks and careful movement to survive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kamen no Ninja - Hanamaru (Japan)', '1989', NaN, 'Toei', '1', NaN, 'Side-scrolling action game with ninja combat', 'Defeat enemies and complete missions', 'A classic ninja action game', 'Kamen no Ninja - Hanamaru builds upon its predecessor with refined mechanics and tougher challenges, offering fast-paced ninja action on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kamen Rider Club (Japan)', '1988', NaN, 'Riverhillsoft', '1', NaN, 'Side-scrolling action platformer with character switching', 'Defeat enemy riders and complete stages', 'A superhero action game', 'Kamen Rider Club lets players control different Kamen Riders, each with unique abilities. The game combines platforming and combat inspired by the popular tokusatsu series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kamen Rider SD - Granshocker no Yabou (Japan)', '1993', NaN, 'Bandai', '1', NaN, 'Side-scrolling action platformer with beat-em-up elements', 'Stop the evil organization', 'A super-deformed Kamen Rider action game', 'Kamen Rider SD features cute character designs combined with action-heavy gameplay. Players fight waves of enemies while progressing through themed stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kanshakudama Nage Kantarou no Toukaidou Gojuusan Tsugi (Japan)', '1986', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action game with projectile combat', 'Complete stages across Japan', 'A comedic action adventure', 'Kanshakudama Nage Kantarou follows a bomb-throwing hero traveling across Japan. The gameplay blends action platforming with humorous visuals and historical references.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kanshakudama Nage Kantarou no Toukaidou Gojuusan Tsugi (Japan) [En by KingMike v1.0] (~Kantaro the Pyro''s Journey Across the Toukaido)', '1986', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action game with projectile combat', 'Complete stages across Japan', 'A comedic action adventure', 'This English-translated version of Kanshakudama Nage Kantarou makes its quirky humor and action accessible, featuring straightforward controls and stage-based progression.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karakuri Kengou Den - Musashi Road - Karakuri Nin Hashiru! (Japan)', '1987', NaN, 'Namco', '1', NaN, 'Side-scrolling action platformer with sword combat', 'Defeat enemies and clear mechanical stages', 'A mechanical ninja action game', 'Karakuri Kengou Den - Musashi Road combines traditional ninja action with mechanical-themed levels. Players engage in sword combat while navigating fast-paced side-scrolling stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karaoke Studio (Japan)', '1987', NaN, 'Nintendo', '1', NaN, 'Music / Karaoke.', 'Sing along to popular songs and hit the notes to score points.', 'A unique Famicom peripheral that included a microphone.', 'This title turned the console into a karaoke machine, featuring simplified 8-bit versions of Japanese hits and a scoring system based on timing and pitch.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karaoke Studio Senyou Cassette Vol. 1 (Japan)', '1987', NaN, 'Nintendo', '1', NaN, 'Music / Karaoke.', 'Expand your song library with new tracks and challenges.', 'An expansion pack for the Karaoke Studio peripheral.', 'This Sub-Cartridge adds a new selection of pop songs and enka classics, allowing owners of the base station to sing along to a wider variety of 8-bit hits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karaoke Studio Senyou Cassette Vol. 2 (Japan)', '1987', NaN, 'Nintendo', '1', NaN, 'Music / Karaoke.', 'Expand your song library with a second set of hits.', 'The second expansion pack for Karaoke Studio.', 'Continuing the series, this volume added even more contemporary Japanese songs from the late 80s, keeping the home karaoke experience fresh for fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karate Champ (USA)', '1986', NaN, 'Data East', '2', NaN, '2D Fighting.', 'Defeat your opponent in a series of point-based karate matches.', 'A port of the influential Data East arcade fighting game.', 'Players use combinations of the D-pad and buttons to perform specific karate moves. The goal is to land clean hits to earn points and win the championship.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karate Champ (USA) (Rev A)', '1986', NaN, 'Data East', '2', NaN, '2D Fighting.', 'Defeat your opponent in a series of point-based karate matches.', 'A revised version of the NES fighting classic with bug fixes.', 'This revision improves the hit detection and AI behavior, providing a slightly more polished version of the technical arcade brawler.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karate Kid, The (USA)', '1989', NaN, 'LJN', '1', NaN, 'Side-scrolling action.', 'Fight through the movie''s plot and win the All Valley Tournament.', 'An LJN action game based on the iconic martial arts film.', 'Players control Daniel LaRusso through levels based on Okinawa and the US, featuring the famous Crane Kick and various training mini-games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karateka (Japan)', '1985', NaN, 'Jordan Mechner', '1', NaN, 'Side-scrolling fighting.', 'Rescue Princess Mariko from the evil Akuma''s fortress.', 'A Famicom port of Jordan Mechner''s cinematic fighting game.', 'Known for its realistic animations and one-hit kill danger, it requires careful timing and stance-switching to survive guards and Akuma''s eagle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karateka (Japan) (Beta)', '1985', NaN, 'Jordan Mechner', '1', NaN, 'Side-scrolling fighting.', 'Rescue Princess Mariko in this early development version.', 'A rare prototype of the Famicom version of Karateka.', 'This version features slight differences in enemy AI and background colors, offering a look at how the Apple II classic was being adapted for Nintendo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karnov (Japan)', '1987', NaN, 'Data East', '1', NaN, 'Side-scrolling action.', 'Find the lost treasure of Babylon as the fire-breathing strongman.', 'A unique Data East platformer starring the muscular Jinborov Karnovsky.', 'Karnov can breathe fire and use collected items like ladders and wings to navigate levels. It is famous for its strange enemy designs and challenging stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karnov (Japan) [En by Vice v1.1]', '1987', NaN, 'Data East', '1', NaN, 'Side-scrolling action.', 'Find the lost treasure with fully translated English text.', 'The English fan translation of the Japanese Famicom version.', 'While the game was released in the US, this translation of the Famicom version preserves the original balance and Japanese menus for Western players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Karnov (USA)', '1988', NaN, 'Data East', '1', NaN, 'Side-scrolling action.', 'Find the lost treasure of Babylon as the fire-breathing strongman.', 'The North American release of the iconic fire-breathing platformer.', 'Players must manage their inventory of power-ups carefully to survive the surreal landscape and massive bosses of this 8-bit arcade port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kart Fighter (Unl)', '1994', NaN, 'Pirate', '2', NaN, '2D Fighting.', 'Win the fighting tournament using Mario and his racing friends.', 'A famous unlicensed fighting game featuring Mario Kart characters.', 'This Chinese bootleg uses the Street Fighter engine to put Mario, Luigi, Peach, and others in a 1v1 brawl. It is surprisingly playable for an unlicensed title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kart Fighter Improvement', '1994', NaN, 'Pirate', '2', NaN, '2D Fighting.', 'Experience a balanced and fixed version of the bootleg fighter.', 'A fan-made improvement hack for the Kart Fighter bootleg.', 'This hack fixes broken hitboxes, balances damage, and cleans up the graphics, turning the weird bootleg into a much more competent 8-bit fighter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kawa no Nushi Tsuri (Japan)', '1987', NaN, 'Pack-In-Video', '1', NaN, 'Fishing RPG.', 'Travel the world to catch the legendary King of the River.', 'A unique blend of fishing simulation and turn-based RPG.', 'As part of the River King series, players explore maps, talk to NPCs, and engage in RPG-style encounters, but the battles are actually fishing mini-games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Keiba Simulation - Honmei (Japan)', '1987', NaN, 'ASCII', '1', NaN, 'Sports / Horse Racing.', 'Analyze stats and place bets to win big at the horse track.', 'A detailed horse racing simulation for the Famicom.', 'This title focuses on the gambling and statistical side of racing, offering deep menus to track horse performance and breeding across multiple seasons.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kekkyoku Nankyoku Daibouken (Japan)', '1984', NaN, 'Konami', '1', NaN, 'Action / Racing.', 'Race against time to reach the research stations across Antarctica.', 'A classic Konami game starring Penta the penguin.', 'Players must dodge seals and pits while sliding across the ice. It is the first game in the series that eventually led to the Parodius franchise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kekkyoku Nankyoku Daibouken (Japan) [En by DvD v1.0] (~Antarctic Adventure)', '1984', NaN, 'Konami', '1', NaN, 'Action / Racing.', 'Reach the research stations with fully translated English menus.', 'The English fan translation of Konami''s Kekkyoku Nankyoku Daibouken.', 'This version makes the travel distances and station names clear, allowing Western players to enjoy this early 8-bit Konami gem.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kero Kero Keroppi no Daibouken (Japan)', '1991', NaN, 'Character Soft', '1', NaN, 'Puzzle / Platformer.', 'Solve puzzles and rescue your friends in a colorful world.', 'A charming Sanrio-themed game starring the famous frog.', 'Featuring Big Adventure, this game blends platforming with various brain-teasers and logic puzzles, all set in a bright and kid-friendly 8-bit environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kero Kero Keroppi no Daibouken (Japan) [En by Gaijin v1.0] (~Kero Kero Keroppi''s Big Adventure)', '1991', NaN, 'Character Soft', '1', NaN, 'Puzzle / Platformer.', 'Solve puzzles and rescue friends with translated instructions.', 'The English fan translation of the first Keroppi Famicom title.', 'This translation is essential for understanding the puzzle clues and level objectives, making the cute adventure fully playable for English speakers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kero Kero Keroppi no Daibouken 2 - Donuts Ike ha Oosawagi! (Japan)', '1992', NaN, 'Character Soft', '1', NaN, 'Side-scrolling platformer.', 'Recover the stolen donuts and save Donut Pond.', 'An improved sequel focusing more on traditional platforming action.', 'Keroppi jumps through themed levels, using unique items to defeat enemies. It is known for its high-quality sprites and very polished gameplay for a licensed title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Kero Kero Keroppi no Daibouken 2 - Donuts Ike ha Oosawagi! (Japan) [En by Spoony Bard v1.0] (~Kero Kero Keroppi''s Great Big Adventure 2)', '1992', NaN, 'Character Soft', '1', NaN, 'Side-scrolling platformer.', 'Save Donut Pond with fully translated story and menus.', 'The English fan translation of the second Keroppi adventure.', 'This version allows players to follow the charming story and dialogue of the sequel while navigating its polished 8-bit platforming stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Keroppi to Keroriinu no Splash Bomb! (Japan)', '1991', NaN, 'Pack-In-Video', '1', NaN, 'Top-down action game with bomb-based combat', 'Defeat enemies using splash bombs', 'A cute Sanrio-themed action game', 'Keroppi to Keroriinu no Splash Bomb! is a top-down action game where players control Keroppi and Keroriinu, throwing water bombs to defeat enemies across colorful stages inspired by the Sanrio universe.', NULL);
