INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little League Baseball - Championship Series (USA)', '1990', NaN, 'SNK', '1-2', NaN, 'Sports / Baseball.', 'Lead a team of kids to the Little League World Series title.', 'A fan-favorite baseball game known for its accessibility and fun.', 'It features varied team stats and power mechanics, offering a more lighthearted but still strategic take on baseball compared to professional sims.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Magic (Japan)', '1993', NaN, 'Altron', '1', NaN, 'Puzzle / Platformer.', 'Use your magic bubble to push stones and clear the exit.', 'A clever and cute logic-based puzzle game.', 'As a young witch-in-training, you must master the physics of your magical bubbles to move obstacles and navigate increasingly complex single-screen rooms.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Magic (Japan) [En by Gaijin+TransBRC v0.33Alpha] (Incomplete)', '1993', NaN, 'Altron', '1', NaN, 'Puzzle / Platformer.', 'Clear the puzzle rooms with translated menus and hints.', 'An English fan translation of the Famicom puzzle gem.', 'Although incomplete in some areas, this patch makes the level instructions and UI accessible for English-speaking puzzle enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Mermaid - Ningyo Hime (Japan)', '1991', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Defeat Ursula and her minions to save the sea kingdom.', 'The Japanese version of Capcom''s underwater adventure.', 'Players control Ariel, using her tail to trap enemies in bubbles and throw them. It’s known for its beautiful 8-bit colors and high Capcom production value.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Mermaid, The (USA)', '1991', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Defeat Ursula and her minions to save the sea kingdom.', 'A polished Capcom platformer based on the Disney movie.', 'A perfect game for younger players that still offers tight mechanics, featuring creative boss fights and excellent music composed by Capcom''s veteran staff.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Nemo - The Dream Master (Europe)', '1990', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Travel through Slumberland to defeat the Nightmare King.', 'A dreamy Capcom platformer based on the classic comic strip.', 'Nemo uses candy to tame various animals, allowing him to ride them and use their abilities (climbing, flying, swimming) to collect keys and progress.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Nemo - The Dream Master (USA)', '1990', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Travel through Slumberland to defeat the Nightmare King.', 'A dreamy Capcom platformer based on the classic comic strip.', 'Nemo uses candy to tame various animals, allowing him to ride them and use their abilities (climbing, flying, swimming) to collect keys and progress.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Ninja Brothers (Europe)', '1990', NaN, 'Culture Brain', '1-2', NaN, 'Action RPG / Party.', 'Stop the Bluaberry King and save Chinaland.', 'A unique blend of RPG exploration and real-time action.', 'Players control Jack and Ryu in a world filled with humor, featuring top-down exploration and side-scrolling battle segments that can be played cooperatively.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Ninja Brothers (USA)', '1990', NaN, 'Culture Brain', '1-2', NaN, 'Side-scrolling action.', 'Navigate the forest to reach Grandma''s house safely.', 'A notoriously difficult unlicensed game by Sachen.', 'Far from the fairy tale, this game features aggressive enemies and complex level layouts, requiring the collection of fruit and money to survive the journey.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Red Hood - Xiao Hong Mao (Asia) (Unl) (Sachen) (Famicom)', '1989', NaN, 'Sachen', '1', NaN, 'Side-scrolling action.', 'Survive the forest in this Australian unlicensed release.', 'The Australian HES version of the Sachen original.', 'Known for its rarity and frustrating difficulty, it maintains the strange mechanics and surreal 8-bit graphics of the original Chinese development.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Red Hood (Australia) (Unl) (HES)', '1989', NaN, 'Sachen/HES', '1', NaN, 'Side-scrolling platformer.', 'Lead four heroes to stop the prince of darkness, Ta-Keed.', 'A legendary masterpiece of the NES library.', 'Players switch between a boy, a golem, a dragon, and a mouse on the fly. It features some of the best graphics and most creative level design ever seen on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Samson (Europe)', '1992', NaN, 'Takeru', '1', NaN, 'Side-scrolling platformer.', 'Lead four heroes to stop the prince of darkness, Ta-Keed.', 'A legendary masterpiece of the NES library.', 'Players switch between a boy, a golem, a dragon, and a mouse on the fly. It features some of the best graphics and most creative level design ever seen on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Little Samson (USA)', '1992', NaN, 'Takeru', '1', NaN, 'Side-scrolling platformer.', 'Lead four heroes to stop the prince of darkness, Ta-Keed.', 'A legendary masterpiece of the NES library.', 'Players switch between a boy, a golem, a dragon, and a mouse on the fly. It features some of the best graphics and most creative level design ever seen on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Locksmith (Asia) (Unl) (NES)', '1991', NaN, 'Unlicensed', '1', NaN, 'Puzzle.', 'Unlock various locks by matching patterns and symbols.', 'A simple but addictive unlicensed logic game.', 'Testing the player''s memory and speed, it presents a series of safes that must be cracked under a time limit, featuring basic but functional 8-bit visuals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Lode Runner (Japan)', '1984', NaN, 'Broderbund/Hudson Soft', '1', NaN, 'Puzzle / Platformer.', 'Collect all the gold in each level while avoiding guards.', 'A classic and highly addictive puzzle-action port.', 'Players must dig holes to trap enemies and reach platforms. The Famicom version is famous for its large sprites and the included level editor mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Lode Runner (USA)', '1983', NaN, 'Broderbund', '1-2', NaN, 'Puzzle / Platformer.', 'Collect all the gold in each level while avoiding guards.', 'A classic and highly addictive puzzle-action port.', 'Players must dig holes to trap enemies and reach platforms. The Famicom version is famous for its large sprites and the included level editor mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Lone Ranger, The (USA)', '1987', NaN, 'Konami', '1', NaN, 'Action Adventure.', 'Stop the villainous Butch Cavendish in the Wild West.', 'An ambitious Konami title with multiple gameplay styles.', 'It features side-scrolling action, top-down exploration, and even first-person shooting segments (compatible with the Zapper), all wrapped in an epic western story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Loopz (USA)', '1990', NaN, 'Audiogenic', '1-2', NaN, 'Puzzle.', 'Connect pipe pieces to form closed loops and clear the screen.', 'A challenging and unique geometric puzzle game.', 'Pieces appear randomly, and you must place them strategically. It requires fast thinking and spatial awareness to keep the board from filling up.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Lord of King, The (Japan)', '1988', NaN, 'Namco', '1', NaN, 'Side-scrolling action.', 'Defeat the dark wizard and his monsters in a fantasy world.', 'The Japanese version of The Astyanax.', 'As a young hero with a magical axe, you fight through lushly detailed mythical levels, featuring huge bosses and impressive cinematic cutscenes for its time.', NULL);
