INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mach Rider (Europe)', '1985', NaN, 'Nintendo', '1', NaN, 'Motorcycle racing action', 'Win high-speed races', 'A futuristic racing game', 'Mach Rider combines motorcycle racing with combat elements in a post-apocalyptic setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mach Rider (Japan, USA)', '1985', NaN, 'Nintendo', '1', NaN, 'Combat racing.', 'Race through futuristic highways and destroy enemy bikers.', 'A high-speed, post-apocalyptic motorcycle racer by Nintendo.', 'Set in the year 2112, players must dodge obstacles and use machine guns to clear the road. It also features a Design Mode to create custom tracks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mach Rider (Japan, USA) (Rev A)', '1985', NaN, 'Nintendo', '1', NaN, 'Combat racing.', 'Race through futuristic highways with improved stability.', 'A revised version of the classic Nintendo motorcycle racer.', 'This update fixes minor sprite flickering and addresses small bugs in the track editor, providing a smoother experience of the high-speed combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mad City (Japan)', '1987', NaN, 'Capcom', '1', NaN, 'Action hybrid.', 'Rescue your girlfriend Annabelle from the gang leader.', 'The original Japanese version of The Adventures of Bayou Billy.', 'It combines side-scrolling brawling, driving, and Zapper shooting. This version is notably easier and more balanced than its Western counterpart.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mad City (Japan) (Beta)', '1987', NaN, 'Capcom', '1', NaN, 'Action hybrid.', 'Rescue Annabelle in this early development version.', 'A rare prototype of the multi-genre Konami title.', 'This beta shows early level layouts and different difficulty settings, offering a look at how Konami integrated three different gameplay styles into one cart.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mad Max (USA)', '1990', NaN, 'Mindscape', '1', NaN, 'Post-apocalyptic driving.', 'Survive the wasteland and defeat the rival gangs.', 'A vehicle-based combat game based on the movie franchise.', 'Players drive through arena-like stages, scavenging for fuel and water while upgrading their car''s weapons to survive an 8-bit desert dystopia.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic Block (Unl)', '1991', NaN, 'Unlicensed', '1-2', NaN, 'Falling-block puzzle.', 'Align identical symbols to clear blocks from the screen.', 'An unlicensed puzzle game with a magical aesthetic.', 'Similar to Columns, players must arrange falling symbols vertically, horizontally, or diagonally to prevent the screen from filling up in this 8-bit bootleg.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic Candle, The (Japan)', '1991', NaN, 'Nexoft', '1', NaN, 'Turn-based RPG.', 'Find a way to keep the magical candle burning and trap a demon.', 'A Famicom port of the complex Western PC RPG.', 'Known for its non-linear world and party management, players must assign tasks to their companions to solve puzzles and prevent the world''s destruction.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic Carpet 1001 (Unl)', '1991', NaN, 'Unlicensed', '1', NaN, 'Side-scrolling shooter.', 'Fly a magic carpet through the desert and defeat mystical foes.', 'An unlicensed shooter by Caltron / Myriad.', 'Players control a character on a flying carpet, dodging projectiles and shooting enemies in a simple but challenging 8-bit action loop.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic Cube (Asia) (Unl) (NES)', '1990', NaN, 'Unlicensed', '1-2', NaN, 'Puzzle.', 'Solve various cube-based logic and spatial puzzles.', 'An unlicensed 8-bit take on the Rubik''s Cube style of gaming.', 'It challenges the player''s spatial reasoning through several modes, requiring them to manipulate blocks to match specific patterns under a time limit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic Darts (Japan)', '1990', NaN, 'Human Entertainment', '1-4', NaN, 'Sports / Darts.', 'Compete in a professional darts tournament to be the best.', 'A realistic darts simulation featuring diverse characters.', 'Players must manage timing and aim to hit specific targets on the board, offering a surprisingly deep 8-bit representation of the pub sport.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic Darts (USA)', '1990', NaN, 'Romstar', '1-4', NaN, 'Sports / Darts.', 'Compete in a professional darts tournament to be the best.', 'A realistic darts simulation featuring diverse characters.', 'Players must manage timing and aim to hit specific targets on the board, offering a surprisingly deep 8-bit representation of the pub sport.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic Jewelry (Asia) (Unl)', '1990', NaN, 'Hwang Shinwei', '1', NaN, 'Falling-block puzzle.', 'Match three or more identical gems to clear the screen.', 'A very popular unlicensed Columns clone.', 'Known for its relaxing music and addictive gameplay, it was a staple of many 99 in 1 pirate cartridges during the 8-bit era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic Jewelry 2 (Asia) (Unl)', '1991', NaN, 'Hwang Shinwei', '1', NaN, 'Falling-block puzzle.', 'Match jewels with updated graphics and new game modes.', 'An unlicensed sequel to the popular gem-matching puzzler.', 'It adds more variety in tile designs and backgrounds, refining the core gameplay loop for fans of the original bootleg title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic John (Japan)', '1990', NaN, 'Game Freak', '1', NaN, 'Side-scrolling action.', 'Rescue your friends using magical transformation powers.', 'Known in the West as Totally Rad.', 'As John, players can transform into different forms (like a bird or a fish) to navigate levels and use elemental magic to defeat bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic Johnson''s Fast Break (USA)', '1988', NaN, 'Tradewest', '1-2', NaN, 'Sports / Basketball.', 'Win basketball games with fast-paced arcade action.', 'A 2-on-2 basketball game endorsed by the NBA legend.', 'It focuses on high-speed play and dunks, offering a simplified but energetic take on the sport that emphasizes quick transitions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magic of Scheherazade, The (USA)', '1987', NaN, 'Culture Brain', '1', NaN, 'Action RPG / Turn-based.', 'Travel through time to defeat the wizard Sabaron.', 'A unique hybrid of action-adventure and turn-based combat.', 'It blends Zelda-style exploration with traditional RPG battles. Players recruit allies and learn powerful spells across different historical eras.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magical Doropie (Japan)', '1990', NaN, 'Vic Tokai', '1', NaN, 'Side-scrolling action.', 'Stop an evil robot army using various magical shots.', 'A Mega Man style action game featuring a witch.', 'Known in the West as The Krion Conquest, Doropie can select different magic types (fire, ice, etc.) to traverse levels and fight mechanical bosses.', NULL);
