INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magical Mathematics (Asia) (Unl) (NTSC)', '1990', NaN, 'Thin Chen Enterprise', '1', NaN, 'Educational / Puzzle.', 'Solve math problems to progress through magical levels.', 'An unlicensed educational title by Sachen for NTSC systems.', 'It uses a mini-game format to teach basic arithmetic, rewarding correct answers with colorful animations and simple 8-bit puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Magical Mathematics (Asia) (Unl) (PAL)', '1990', NaN, 'Thin Chen Enterprise', '1', NaN, 'Educational / Puzzle.', 'Solve math problems to progress through magical levels.', 'The PAL region version of the unlicensed math game.', 'Identical to the NTSC version but optimized for European TV standards, ensuring the educational math challenges play at the correct speed.', NULL);
