INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mahou no Princess Minky Momo - Remember Dream (Japan)', '1992', NaN, 'Konami', '1', NaN, 'Adventure / Mini-games.', 'Help Minky Momo restore people''s dreams to save Earth.', 'A charming adventure based on the classic magical girl anime.', 'Players complete tasks and mini-games to help the citizens of Earth, featuring bright graphics and a story faithful to the Magical Princess series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maison Ikkoku (Japan)', '1986', NaN, 'Micro Cabin', '1', NaN, 'Adventure / Visual Novel.', 'Navigate the daily life and romance at the Ikkoku boarding house.', 'A text-based adventure based on Rumiko Takahashi''s famous manga.', 'As Yusaku Godai, players must interact with the eccentric tenants and win the heart of Kyoko Otonashi through menu-driven choices and puzzle-solving.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Majaventure - Mahjong Senki (Japan)', '1990', NaN, 'Asmik', '1', NaN, 'Mahjong / RPG.', 'Use Mahjong skills to defeat enemies in a fantasy world.', 'A unique hybrid that blends traditional Mahjong with RPG elements.', 'Instead of physical attacks, battles are decided by Mahjong hands. Players level up and gain items to help them conquer a magical kingdom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Major League (Japan)', '1989', NaN, 'Tose', '1-2', NaN, 'Sports / Baseball.', 'Lead your team to victory in the professional baseball league.', 'A fast-paced baseball game with a focus on arcade action.', 'Known for its smooth controls and detailed (for the time) player statistics, it offers a solid 8-bit representation of Japan''s national sport.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Major League Baseball (USA)', '1988', NaN, 'LJN', '1-2', NaN, 'Sports / Baseball.', 'Outscore your opponent in a full 9-inning game.', 'The first NES game to feature the official MLB license.', 'While it has the real team names, it doesn''t feature real player names. It’s a foundational baseball title with a classic behind-the-batter perspective.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Major League Baseball (USA) (Rev A)', '1988', NaN, 'LJN', '1-2', NaN, 'Sports / Baseball.', 'Outscore your opponent with minor technical improvements.', 'A revised version of the licensed MLB baseball title.', 'This revision fixes minor graphical glitches in the stadiums and improves the logic for fly-ball catching and base running.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Majou Densetsu 2 - Daimashikyou Galious (Japan)', '1987', NaN, 'Konami', '1', NaN, 'Action / Adventure.', 'Explore the castle of Galious to rescue your unborn son.', 'A legendary Konami Metroidvania (The Maze of Galious).', 'Players switch between Popolon and Aphrodite, each with unique skills, to navigate a massive, non-linear castle filled with secrets and giant bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Majou Densetsu 2 - Daimashikyou Galious (Japan) [En by Manipulate v0.31b]', '1987', NaN, 'Konami', '1', NaN, 'Action / Adventure.', 'Explore the castle with fully translated English text.', 'The English fan translation of Konami''s action-adventure classic.', 'This version allows Western players to fully understand the cryptic clues given by NPCs, which are essential for solving the game''s many puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Makai Island (USA) (Proto)', '1987', NaN, 'Capcom', '1', NaN, 'Top-down / Action.', 'Explore seven islands and find the hidden pirate treasure.', 'An unreleased US prototype of Capcom''s Higemaru Makaijima.', 'A fascinating look at what would have been the Western version of Capcom''s high-seas adventure, featuring polished barrel-throwing action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Makai-Mura (Japan)', '1986', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Rescue Princess Prin-Prin from the demon king.', 'The original Japanese Famicom version of Ghosts ''n Goblins.', 'Infamous for its extreme difficulty, players control Sir Arthur through graveyards and caves, fighting zombies and demons to save the kingdom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mali Lugi Super Mari 2', '1997', NaN, 'Unlicensed', '1', NaN, 'Side-scrolling action.', 'Navigate dream worlds in this modified version of Mario.', 'A famous pirated hack of Super Mario Bros. 2.', 'This bootleg modifies the sprites and colors of the original game, creating a surreal and unofficial Mario experience common in the 90s clone market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Man II', '2010', NaN, 'Fan-made', '1', NaN, 'Side-scrolling action.', 'Survive waves of enemies in this unofficial combat game.', 'An unlicensed action title, often found on multi-game carts.', 'Featuring simple mechanics and repetitive levels, it’s a typical example of the 8-bit budget games created for the Asian bootleg market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maniac Mansion (Europe)', '1990', NaN, 'Jaleco', '1', NaN, 'Point-and-click adventure.', 'Infiltrate the Edison mansion to rescue Sandy from the mad doctor.', 'A masterclass in adventure gaming by LucasArts.', 'Players choose a team of three kids, each with unique abilities, to solve puzzles. It features a brilliant point-and-click interface adapted for the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maniac Mansion (France)', '1990', NaN, 'Jaleco', '1', NaN, 'Point-and-click adventure.', 'Rescue Sandy in this fully localized French version.', 'The French-language edition of the classic adventure.', 'This version translates all the witty dialogue and item descriptions, making the complex puzzles accessible to French-speaking players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maniac Mansion (Germany)', '1990', NaN, 'Jaleco', '1', NaN, 'Point-and-click adventure.', 'Rescue Sandy in this fully localized German version.', 'The German-language edition of the classic adventure.', 'All menus and cutscenes are translated, allowing German fans to enjoy the dark humor and multiple endings of the Edison family mystery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maniac Mansion (Italy)', '1990', NaN, 'Jaleco', '1', NaN, 'Point-and-click adventure.', 'Rescue Sandy in this fully localized Italian version.', 'The Italian-language edition of the classic adventure.', 'This version preserves the humor and logic of the original while making the story fully playable for the Italian 8-bit community.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maniac Mansion (Japan)', '1990', NaN, 'Jaleco', '1', NaN, 'Point-and-click adventure.', 'Rescue Sandy in this unique Famicom adaptation.', 'A Japan-only version with completely different graphics.', 'Unlike the Western versions, this one uses more chibi (cute) character designs and simplified backgrounds, though the core puzzles remain largely the same.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maniac Mansion (Spain)', '1990', NaN, 'Jaleco', '1', NaN, 'Point-and-click adventure.', 'Rescue Sandy in this fully localized Spanish version.', 'The Spanish-language edition of the classic adventure.', 'This version is highly regarded for its faithful translation of the game''s iconic 80s humor and complex logic-based puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maniac Mansion (Sweden)', '1990', NaN, 'Jaleco', '1', NaN, 'Point-and-click adventure.', 'Rescue Sandy in this fully localized Swedish version.', 'A rare Swedish-language edition of the LucasArts classic.', 'Translating the entire script, it allowed Swedish players to experience the branching paths and various ways to defeat Dr. Fred.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maniac Mansion (USA)', '1988', NaN, 'Jaleco', '1', NaN, 'Point-and-click adventure.', 'Infiltrate the Edison mansion to rescue Sandy from the mad doctor.', 'The definitive North American release of the adventure hit.', 'Famous for its censored elements (like the hamster incident), it remains one of the most interactive and deep games available on the NES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maniac Mansion (USA) (Beta)', '1988', NaN, 'Jaleco', '1', NaN, 'Point-and-click adventure.', 'Rescue Sandy in this early development build.', 'A prototype featuring uncensored content and early UI.', 'This beta is famous among fans for containing elements that Nintendo later forced LucasArts to remove, providing a look at the game''s original vision.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'MANTLE', '2012', NaN, 'Fan-made', '1', NaN, 'Strategy / Action.', 'Control mechanical units to conquer territory and solve puzzles.', 'A unique and atmospheric strategy-action title.', 'Players manage a specialized vehicle to navigate complex grid-based maps, balancing combat with tactical movement in a futuristic 8-bit setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mappy (Japan)', '1984', NaN, 'Namco', '1-2', NaN, 'Side-scrolling action.', 'Recover stolen goods as a police mouse in a cat-filled house.', 'A classic Namco arcade port with catchy music.', 'Mappy must bounce on trampolines to navigate floors and avoid Meowky the cat, collecting items like TVs and radios to clear each stage.', NULL);
