INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Master Fighter VI''', '1994', NaN, 'Unlicensed', '1-2', NaN, '2D Fighting.', 'Defeat a roster of fighters to become the ultimate master.', 'A famous unlicensed 8-bit Street Fighter clone.', 'This bootleg is surprisingly competent, featuring several iconic characters like Ryu and Chun-Li, with special moves that actually work on Famicom hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Masuzoe Youichi - Asa Made Famicom (Japan)', '1986', NaN, 'Coconuts Japan', '1-4', NaN, 'Simulation / Strategy.', 'Discuss politics and solve national issues through dialogue.', 'A unique political simulation game starring Youichi Masuzoe.', 'Players navigate through text-heavy debates and decision-making scenarios, attempting to influence the future of Japan in this very niche 8-bit title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Matendouji (Japan)', '1990', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling action.', 'Defeat demons across modern-day Japan to save the world.', 'Known in the West as Conquest of the Crystal Palace.', 'A highly polished platformer where you use a sword and a loyal dog companion to fight supernatural foes, featuring branching paths and shops.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Matsumoto Tooru no Kabushiki Hisshou Gaku (Japan)', '1988', NaN, 'Imagineer', '1', NaN, 'Simulation / Finance.', 'Master the stock market and build a fortune through trading.', 'A serious financial simulation by an investment expert.', 'Players follow real-world stock market trends, analyzing graphs and news reports to buy low and sell high in an attempt to get rich on the Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Matsumoto Tooru no Kabushiki Hisshou Gaku 2 (Japan)', '1989', NaN, 'Imagineer', '1', NaN, 'Simulation / Finance.', 'Expand your financial empire in this advanced sequel.', 'A deeper and more complex stock market simulator.', 'Featuring more companies and a refined interface, this sequel provides an even more realistic look at the 8-bit world of professional trading and investment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Max Warrior - Wakusei Kaigenrei (Japan)', '1991', NaN, 'KSS', '1', NaN, 'Isometric shooter.', 'Stop an alien invasion in a futuristic world.', 'The Japanese version of the isometric hit Isolated Warrior.', 'It features incredible pseudo-3D graphics and fast-paced shooting, where the player runs and jumps through visually striking, hazard-filled environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maxi 15 (USA) (Unl)', '1988', NaN, 'AVE', '1', NaN, 'Multi-game.', 'Experience 15 different unlicensed games on one cartridge.', 'A famous multicart by American Video Entertainment (AVE).', 'It contains a mix of puzzles, shooters, and action games like F-15 City War and Krazy Kreatures, showing the diversity of the unlicensed NES market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maxi 15 (USA) (Unl) (Rev 1)', '1988', NaN, 'AVE', '1', NaN, 'Multi-game.', 'Experience 15 different unlicensed games with bug fixes.', 'A revised version of the AVE 15-in-1 multicart.', 'This revision improves the menu system and addresses specific loading issues found in some of the included titles for better hardware compatibility.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Maxi-15 Pack (Australia) (Unl)', '1988', NaN, 'HES', '1', NaN, 'Multi-game.', 'Explore 15 unique games in this Australian release.', 'The Australian HES version of the Maxi 15 multicart.', 'Distributed in the distinctive HES packaging, it offered Australian gamers a wide variety of unlicensed 8-bit experiences in a single purchase.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'McDonaldland (Europe)', '1992', NaN, 'Virgin Interactive', '1', NaN, 'Side-scrolling platformer.', 'Recover Ronald''s bag and explore the world of McDonaldland.', 'A high-quality platformer known as M.C. Kids in the USA.', 'Developed by Virgin, it features creative mechanics like gravity-flipping and complex level design that rivals the best Nintendo-developed titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'McDonaldland (France)', '1992', NaN, 'Virgin Interactive', '1', NaN, 'Side-scrolling platformer.', 'Explore McDonaldland with localized French text.', 'The French version of the polished McDonald''s adventure.', 'It maintains the clever platforming and secret-filled worlds, making the story and tips accessible to French-speaking fans of the brand.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mechanized Attack (USA)', '1989', NaN, 'SNK', '1-2', NaN, 'First-person shooter.', 'Infiltrate a high-tech island and destroy the cyborg army.', 'An arcade port that supports the NES Zapper.', 'Players fight through waves of robotic enemies in a first-person perspective, with the game occasionally switching to side-scrolling light gun action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'MEGA GIANT MARIO BROS.', '2012', NaN, 'Fan-made', '1', NaN, 'Side-scrolling action.', 'Navigate levels as an oversized version of Mario.', 'A famous sprite-modification hack of Super Mario Bros.', 'This hack changes Mario''s size and colors, often increasing his power and changing the physics to create a giant experience in the classic 8-bit world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man (Europe)', '1989', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Defeat the six Robot Masters and stop Dr. Wily.', 'The PAL version of the legendary Capcom debut.', 'This game introduced the weapon-stealing mechanic and the blue bomber''s iconic platforming, setting the stage for one of gaming''s greatest series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man (USA)', '1987', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Defeat the six Robot Masters and stop Dr. Wily.', 'The North American debut of the Blue Bomber.', 'Famous for its unique box art, the game itself is a masterclass in challenge and design, allowing players to choose their own level order.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man (USA) [Graphic Hack by Dragonsbrethren v3.0] (~Protoman - The Red Bomber)', '2012', NaN, 'Fan-made', '1', NaN, 'Side-scrolling action.', 'Play through Mega Man 1 as the mysterious Protoman.', 'A comprehensive graphic hack that replaces the protagonist.', 'This version replaces Mega Man with Protoman, featuring a red color scheme and a shield, giving a fresh look to the original 8-bit challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man (USA) [Hack by Dragon Eye Studios v1.0] (~Megaman Showdown I) (Boss Mode)', '2010', NaN, 'Fan-made', '1', NaN, 'Boss Rush.', 'Fight all the Robot Masters in a continuous gauntlet.', 'A Boss Mode hack designed for pure combat practice.', 'Instead of navigating levels, players jump straight into the boss rooms to test their patterns and reflexes against Dr. Wily''s elite machines.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man (USA) [Hack by Duelists v1.0] (~Bass)', '2011', NaN, 'Fan-made', '1', NaN, 'Side-scrolling action.', 'Play through Mega Man 1 as the rival character, Bass.', 'A character hack replacing Mega Man with his later rival.', 'It updates the sprites to depict Bass, offering fans of the series a chance to see how the anti-hero would look in the original 1987 adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man 2 - Slide and Charge Shot', '2009', NaN, 'Fan-made', '1', NaN, 'Side-scrolling action.', 'Defeat the eight Robot Masters with modern abilities.', 'A technical hack adding late-series moves to Mega Man 2.', 'This version allows Mega Man to slide and use the Mega Buster charge shot in the second game, significantly changing the original game''s balance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man 2 (Europe)', '1989', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Stop Dr. Wily''s eight new Robot Masters.', 'The PAL release of what many consider the best NES game.', 'Featuring an incredible soundtrack and the addition of E-Tanks and passwords, it refined the Mega Man formula to near perfection.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man 2 (USA)', '1988', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Stop Dr. Wily''s eight new Robot Masters.', 'The definitive North American release of the blue bomber''s peak.', 'This version famously included a Normal and Difficult mode, making it more accessible to a wider range of players in the West.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man 2 (USA) [Hack by Blast Hornet v1.0] (~Rockman Exile) (Ja)', '2010', NaN, 'Fan-made', '1', NaN, 'Side-scrolling action.', 'Navigate an entirely new and difficult set of levels.', 'A famous and challenging level-hack for Mega Man 2.', 'It features completely redesigned stages, new graphics, and a higher difficulty curve, intended for veterans who have mastered the original game.', NULL);
