INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man 2 (USA) [Hack by Sivak Drac v1.0] (~Adventures of Bass II, The)', '2012', NaN, 'Fan-made', '1', NaN, 'Action platformer', 'Play as Bass and defeat enemies', 'A character-focused Mega Man hack', 'The Adventures of Bass II reimagines Mega Man 2 by introducing Bass as the main playable character with unique abilities.', NULL);
