INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man 5 (USA)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Stop Proto Man''s rogue army and clear his name.', 'The North American release of the 5th Mega Man title.', 'Players must track down the mysterious Dark Men and uncover the truth behind Proto Man''s sudden turn to the dark side.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mega Man 5: Protoman Edition', '2013', NaN, 'Fan-made', '1', NaN, 'Side-scrolling action.', 'Play through the entire game as Proto Man with his shield.', 'A character hack that makes Proto Man the protagonist.', 'Unlike the original where he is an NPC, here you control him directly, utilizing his iconic shield to deflect bullets and a unique charge shot.', NULL);
