INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Metroid Walljump', '2014', NaN, 'Fan-made', '1', NaN, 'Action / Exploration.', 'Explore Zebes with the new ability to jump off walls.', 'A technical hack for the original Metroid.', 'This modification allows Samus to perform a wall jump, drastically changing how players navigate the planet and opening up new sequence-breaking possibilities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mezase Pachi Pro - Pachio Kun (Japan)', '1990', NaN, 'Coconuts Japan', '1-4', NaN, 'Simulation / Pachinko.', 'Win big at the parlors to help the round-headed Pachio.', 'A charming Pachinko simulation starring a mascot character.', 'Players manage their balls and adjust the strength of their shots across various themed machines in an attempt to hit the jackpot.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mezase Top Pro - Green ni Kakeru Yume (Japan)', '1989', NaN, 'Jaleco', '1', NaN, 'Sports / Golf.', 'Climb the professional rankings to become a golf legend.', 'A realistic and detailed golf sim for the Famicom.', 'Featuring deep mechanics for wind, club selection, and green slope, it aims to provide a professional-level golfing experience on 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Michael Andretti''s World GP (USA)', '1988', NaN, 'American Sammy', '1', NaN, 'Sports / Racing.', 'Win the Formula One World Championship across 16 tracks.', 'A fast-paced F1 racing game endorsed by Michael Andretti.', 'Players can customize their car''s settings and must master manual or automatic shifting to beat international rivals in high-speed circuit racing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mickey Mania 7 (Unl)', '1998', NaN, 'Unlicensed', '1', NaN, 'Side-scrolling action.', 'Help Mickey navigate through levels based on his cartoons.', 'An unlicensed 8-bit demake of the 16-bit Mickey Mania.', 'This bootleg attempts to replicate the visuals and stages of the SNES/Genesis original, featuring surprisingly large sprites for the NES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mickey Mouse - Dream Balloon (USA) (Proto)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Use balloons to navigate levels and rescue friends.', 'An unreleased US prototype of Mickey Mouse 3.', 'A fascinating look at the planned Western release of the third Mickey game, featuring polished platforming and creative balloon-based mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mickey Mouse (Japan)', '1989', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Help Mickey rescue Minnie from the witch''s castle.', 'Known in the West as Mickey Mousecapade.', 'This is the original Japanese release (published by Hudson Soft), featuring Mickey and Minnie navigating together through diverse, puzzle-filled stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mickey Mouse 3 - Yume Fuusen (Japan)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Travel through dreams using magical balloons to find Minnie.', 'The Japanese version of what would become Kid Klown.', 'Mickey uses balloons as weapons and tools in a vibrant, high-quality platformer that was later re-skinned for its Western release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mickey Mousecapade (USA)', '1988', NaN, 'Capcom', '1-2', NaN, 'Side-scrolling action.', 'Lead Mickey and Minnie to safety through dangerous worlds.', 'A classic Capcom-developed Disney adventure for the NES.', 'Players must protect Minnie while fighting enemies. It features unique levels like the Ocean, the Forest, and a giant dollhouse.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mickey''s Adventure in Numberland (USA)', '1994', NaN, 'Hi Tech Expressions', '1', NaN, 'Educational / Puzzle.', 'Collect numbers and solve math problems in a Disney world.', 'A fun educational game designed for younger children.', 'Mickey travels through colorful stages where the goal is to learn basic counting and arithmetic in a friendly, low-stress environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mickey''s Safari in Letterland (USA)', '1993', NaN, 'Hi Tech Expressions', '1', NaN, 'Educational / Puzzle.', 'Explore the world to find letters and learn the alphabet.', 'A Disney educational title focused on literacy skills.', 'Players help Mickey travel via jeep and plane to collect letters, making it an engaging tool for early childhood education.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Micro Machines (USA) (Unl)', '1991', NaN, 'Codemasters', '1-4', NaN, 'Racing.', 'Win races on kitchen tables, desks, and garden paths.', 'A technical masterpiece by Codemasters using miniature cars.', 'Famous for its tiny sprites and incredibly smooth scrolling, it offers high-speed competitive racing in everyday household environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Middle School English - Dong Dong Nao II (Asia) (Unl)', '1991', NaN, 'Unlicensed', '1', NaN, 'Educational.', 'Solve English language puzzles to progress.', 'An unlicensed Asian educational game.', 'Part of the Dong Dong Nao series, it uses simple mini-games to teach English vocabulary and grammar to Famicom users.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'MiG 29 - Soviet Fighter (USA) (Unl)', '1989', NaN, 'Camerica', '1', NaN, 'Combat Flight Sim.', 'Complete dangerous missions flying the Soviet MiG-29.', 'An unlicensed flight simulator by Camerica.', 'Players take a first-person view from the cockpit, engaging in dogfights and bombing runs across multiple high-stakes military scenarios.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Might and Magic - Secret of the Inner Sanctum (USA)', '1990', NaN, 'American Sammy', '1', NaN, 'Turn-based RPG.', 'Explore the world of Varn and uncover its deep secrets.', 'A massive Western RPG ported to the NES.', 'Featuring a first-person dungeon crawling perspective, it offers a huge world, hundreds of items, and deep party customization.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Might and Magic (Japan)', '1991', NaN, 'Tokuma Shoten', '1', NaN, 'Turn-based RPG.', 'Explore the world of Varn with localized text.', 'The Japanese Famicom version of the classic PC RPG.', 'This version features revised graphics and a different musical score compared to the US release, catering to Japanese RPG tastes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mighty Bomb Jack (Europe)', '1987', NaN, 'Tecmo', '1', NaN, 'Side-scrolling action.', 'Collect bombs in the pyramid to rescue the royal family.', 'A fast-paced, high-jumping sequel to the arcade original.', 'Known for its unique physics where Jack can jump incredibly high and float, it requires precise timing to collect all bombs in the correct order.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mighty Bomb Jack (Japan)', '1986', NaN, 'Tecmo', '1', NaN, 'Side-scrolling action.', 'Collect bombs in the pyramid to rescue the royal family.', 'The original Famicom release of the bomb-collecting hit.', 'Featuring many hidden secrets and alternative paths, it is a challenging platformer that rewards exploration and mastery of Jack''s jumping mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mighty Bomb Jack (USA)', '1987', NaN, 'Tecmo', '1', NaN, 'Side-scrolling action.', 'Collect bombs in the pyramid to rescue the royal family.', 'The North American release of the frantic Tecmo platformer.', 'Jack must navigate treacherous rooms filled with enemies, collecting treasure and power-ups to survive the massive 8-bit pyramid.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mighty Final Fight (Europe)', '1993', NaN, 'Capcom', '1-2', NaN, 'Side-scrolling beat ''em up.', 'Rescue Haggar''s daughter Jessica from the Mad Gear Gang.', 'A brilliant 8-bit reimagining of the arcade classic.', 'It features an RPG-like leveling system and a chibi art style, offering one of the most polished brawler experiences on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mighty Final Fight (Japan)', '1993', NaN, 'Capcom', '1-2', NaN, 'Side-scrolling beat ''em up.', 'Rescue Haggar''s daughter Jessica from the Mad Gear Gang.', 'The original Japanese release of the Mighty brawler.', 'Known for its humor and tight combat, players can choose between Cody, Guy, and Haggar, each with unique special moves and leveling paths.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mighty Final Fight (USA)', '1993', NaN, 'Capcom', '1-2', NaN, 'Side-scrolling beat ''em up.', 'Rescue Haggar''s daughter Jessica from the Mad Gear Gang.', 'A brilliant 8-bit reimagining of the arcade classic.', 'It features an RPG-like leveling system and a chibi art style, offering one of the most polished brawler experiences on the NES.', NULL);
