INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mike Tyson''s Punch-Out!! (USA)', '1987', NaN, 'Nintendo', '1', NaN, 'Sports / Boxing.', 'Rise through the ranks to face the champion Mike Tyson.', 'The definitive North American boxing masterpiece.', 'Featuring the likeness of Mike Tyson as the final boss, it is a game of skill and memory that remains a benchmark for the genre.', NULL);
