INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mouryou Senki Madara (Japan) [En by Aeon Genesis v1.0]', '1990', NaN, 'Konami', '1', NaN, 'Action RPG', 'Defeat supernatural enemies', 'English-translated RPG', 'This English version of Madara delivers its story-heavy action RPG experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mr. Gimmick (Europe)', '1993', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action.', 'Rescue your owner from a toy world using star magic.', 'A late-era technical masterpiece by Sunsoft.', 'Featuring advanced physics and one of the best soundtracks on the NES, players use a star that bounces and acts as both a weapon and a platform.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ms. Pac-Man - Cleaner Map Graphics', '2010', NaN, 'Fan-made', '1-2', NaN, 'Maze / Arcade.', 'Eat all dots while avoiding ghosts with improved art.', 'A graphical hack that polishes the tile-sets of the classic.', 'This version cleans up the maze borders and fruit icons to provide a more modern and crisp visual experience on the 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ms. Pac-Man - Original Title Screen', '2010', NaN, 'Fan-made', '1-2', NaN, 'Maze / Arcade.', 'Clear the mazes in this arcade-accurate version.', 'A hack that restores the original arcade title screen.', 'It replaces the modified NES title screens with the authentic arcade layout, catering to purists who want the 1982 experience at home.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ms. Pac-Man - Turbo', '2010', NaN, 'Fan-made', '1-2', NaN, 'Maze / Arcade.', 'Clear mazes at high speed to test your reflexes.', 'A Turbo hack that increases movement speed significantly.', 'Perfect for veterans, this version ramps up the velocity of both Ms. Pac-Man and the ghosts, turning the game into a frantic test of skill.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ms. Pac-Man (USA)', '1993', NaN, 'Namco', '1-2', NaN, 'Maze / Arcade.', 'Navigate four different mazes and outsmart the ghosts.', 'The official Namco/Tengen release for North America.', 'Featuring different maze layouts than the original Pac-Man and moving fruit bonuses, it''s often considered superior to its predecessor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ms. Pac-Man (USA) (Unl)', '1990', NaN, 'Tengen', '1-2', NaN, 'Maze / Arcade.', 'Navigate mazes in the unlicensed black cartridge version.', 'The Tengen unlicensed release of the arcade classic.', 'While identical in gameplay to the licensed one, this version was sold outside Nintendo’s approval during the legal battles between Atari and Nintendo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Ms. Pac-Man (USA) [Hack by Dave Augusta+Googie v1.0] (~Mr. Pac-Man)', '2010', NaN, 'Fan-made', '1-2', NaN, 'Maze / Arcade.', 'Play as a male version of Pac-Man in the sequel''s mazes.', 'A character swap hack for Ms. Pac-Man.', 'It replaces the female protagonist with the original Pac-Man (bow-less) while keeping the improved maze layouts and mechanics of the second game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Muppet Adventure - Chaos at the Carnival (USA)', '1990', NaN, 'Hi Tech Expressions', '1', NaN, 'Mini-games / Action.', 'Rescue Miss Piggy by winning various carnival games.', 'A collection of Muppet-themed challenges.', 'Players control different Muppets in stages like river rafting, bumper cars, and a funhouse, all aimed at a younger 8-bit audience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Musashi no Bouken (Japan)', '1990', NaN, 'Taito', '1', NaN, 'Turn-based RPG.', 'Travel ancient Japan as a young monk to defeat evil.', 'A traditional Dragon Quest-style RPG with folklore themes.', 'Known for its charming setting, players level up, buy equipment, and fight mythological Japanese monsters in strategic turn-based combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Musashi no Bouken (Japan) [En by Gaijin+MadHacker v0.98] (~Adventures of Musashi, The)', '1990', NaN, 'Taito', '1', NaN, 'Turn-based RPG.', 'Defeat the ancient evil with fully translated text.', 'The English fan translation of Musashi no Bouken.', 'This patch is essential for Western players to enjoy the story, item descriptions, and traditional Japanese humor of this hidden RPG gem.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Musashi no Ken - Tadaima Shugyou Chuu (Japan)', '1990', NaN, 'Taito', '1', NaN, 'Side-scrolling action.', 'Train in Kendo to win the national championship.', 'An action game based on the famous Kendo manga/anime.', 'It features fast-paced platforming levels where you fight with a bamboo sword, followed by 1v1 Kendo matches against rival students.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mutant Virus, The - Crisis in a Computer World (USA)', '1992', NaN, 'American Video Entertainment', '1', NaN, 'Action / Shooter.', 'Disinfect a giant computer system from a viral outbreak.', 'A unique 360-degree shooter with inertia-based movement.', 'Players pilot a probe inside a computer, shooting virus cells that multiply in real-time. It''s known for its high difficulty and unique physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'My Life My Love - Boku no Yume - Watashi no Negai (Japan)', '1992', NaN, 'Coconuts Japan', '1', NaN, 'Life Simulation.', 'Live a full life from birth to old age in a digital world.', 'A fascinating board-game style life simulator.', 'Similar to The Game of Life, players make choices about education, jobs, and marriage, influencing their character''s stats and ultimate happiness.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Mystery Quest (USA)', '1987', NaN, 'Carry Lab', '1', NaN, 'Side-scrolling action.', 'Explore four large castles to find the wizard''s secrets.', 'An exploration-heavy platformer by Taxan.', 'Known for its non-linear design, players must find keys and power-ups to survive surreal environments and defeat guardians in each castle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Nagagutsu wo Haita Neko - Sekai Isshuu 80 Nichi Daibouken (Japan)', '1986', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling action.', 'Travel around the world in 80 days to win a bet.', 'An adventure based on the Toei Animation mascot.', 'This game features levels set in London, America, and even space, with the protagonist using various vehicles to speed through his global journey.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Nakajima Satoru - F-1 Hero (Japan)', '1988', NaN, 'Varie', '1', NaN, 'Sports / Racing.', 'Master the Formula 1 circuit with help from Satoru Nakajima.', 'A professional-grade F1 simulation for Famicom.', 'Endorsed by the first full-time Japanese F1 driver, it features realistic car tuning and actual tracks from the world championship circuit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Nakajima Satoru - F-1 Hero 2 (Japan)', '1991', NaN, 'Varie', '1', NaN, 'Sports / Racing.', 'Win the F1 championship with improved car physics.', 'An advanced sequel to the F1 Hero racing series.', 'It features refined graphics and more complex cockpit views, offering one of the most technical racing experiences available on 8-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Nakayoshi to Issho (English Translation)', '1994', NaN, 'Video System', '1', NaN, 'Adventure / Sim.', 'Interact with characters from the Nakayoshi manga magazine.', 'An English fan translation of the popular Shoujo crossover.', 'This translation makes the dialogue-heavy missions and social interactions accessible to fans of classic manga like Sailor Moon.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Nakayoshi to Issho (Japan)', '1994', NaN, 'Video System', '1', NaN, 'Adventure / Sim.', 'Complete missions in a world filled with Nakayoshi stars.', 'A social simulation game based on the famous girls'' magazine.', 'Players create an avatar and interact with various manga heroines, completing mini-games and fashion-based tasks in a bright 8-bit world.', NULL);
