INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Namcot Mahjong III - Mahjong Tengoku (Japan)', '1991', NaN, 'Namco', '1-4', NaN, 'Mahjong / Strategy.', 'Play Mahjong in a Heavenly themed simulation.', 'The third entry in Namcot''s popular Mahjong series.', 'It offers different playstyles and a story mode where you play against celestial beings, focusing on the pure rules of 4-player Mahjong.', NULL);
