INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Operation Wolf (Europe)', '1987', NaN, 'Taito', '1', NaN, 'First-person shooter.', 'Rescue hostages from enemy territory.', 'The PAL version of the legendary Taito light gun hit.', 'A high-intensity shooter where you must manage your ammo and grenades to survive waves of soldiers, tanks, and helicopters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Operation Wolf (Japan)', '1987', NaN, 'Taito', '1', NaN, 'First-person shooter.', 'Rescue hostages from enemy territory.', 'The Famicom version of the classic arcade rail-shooter.', 'Known for its frantic pace, this version supports the Zapper and is famous for its rescue missions that require precise aim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Operation Wolf (USA) (Rev 0A)', '1987', NaN, 'Taito', '1', NaN, 'First-person shooter.', 'Rescue hostages from enemy territory.', 'The definitive North American light gun experience.', 'This revision ensures the best compatibility with the NES Zapper, offering a challenging port of the arcade''s chaotic military action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Orb 3D (USA)', '1990', NaN, 'Square', '1', NaN, 'Puzzle / Action.', 'Launch an orb into space to clear targets and solve puzzles.', 'A unique 3D-perspective puzzle game.', 'Using a behind-the-orb view, players must time their launches and bounces to hit specific objects in a starry 8-bit void.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Osomatsu Kun (Japan)', '1988', NaN, 'Sega', '1', NaN, 'Side-scrolling action.', 'Help the sextuplets navigate through a wacky world.', 'A quirky platformer based on the classic comedy anime.', 'It features surreal humor, strange power-ups, and a non-linear path through levels filled with iconic characters from the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Otaku no Seiza - An Adventure in the Otaku Galaxy (Japan)', '1991', NaN, 'Namco', '1', NaN, 'Turn-based RPG.', 'Save the Otaku Galaxy from a group of female villains.', 'A humorous and satirical sci-fi RPG.', 'It parodies RPG tropes and otaku culture, featuring a unique setting where the protagonist must navigate a universe obsessed with hobbies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Othello (USA)', '1988', NaN, 'Hal Laboratory', '1', NaN, 'Board Game.', 'Outflank your opponent to cover the board with your color.', 'A polished 8-bit version of the classic strategy game.', 'Featuring multiple difficulty levels and a clean interface, it’s a perfect digital representation of the minute to learn, a lifetime to master game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Outlanders (Japan)', '1987', NaN, 'Square', '1', NaN, 'Action / RPG.', 'Save the Earth from an alien invasion with Princess Kahm.', 'An action-adventure based on the sci-fi manga.', 'It blends top-down exploration with side-scrolling combat, featuring a large world and a story involving intergalactic romance and war.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Over Horizon (Europe)', '1991', NaN, 'Hot B', '1', NaN, 'Side-scrolling shooter.', 'Customize your weapons to destroy the alien threat.', 'One of the most technically impressive shooters on the NES.', 'It features a deep weapon-editing system and the ability to shoot forwards and backwards, with incredible graphics and bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Over Horizon (Japan)', '1991', NaN, 'Hot B', '1', NaN, 'Side-scrolling shooter.', 'Customize your weapons to destroy the alien threat.', 'The original Japanese release of the cult-classic shmup.', 'Known for its atmospheric music and polished gameplay, it remains a favorite for fans of high-quality 8-bit action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Overlord (USA)', '1990', NaN, 'Ackal Soft', '1', NaN, 'Strategy / Sim.', 'Conquer planets and manage your galactic empire.', 'A complex 4X-style strategy game for the NES.', 'Players must balance taxes, population growth, and military production to dominate the star system in this deep 8-bit simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'P.O.W. - Prisoners of War (Europe)', '1989', NaN, 'SNK', '1-2', NaN, 'Side-scrolling beat ''em up.', 'Escape a prisoner of war camp and destroy the enemy base.', 'A gritty and realistic 8-bit brawler.', 'Unlike Double Dragon, it focuses on military combat, allowing players to pick up knives and machine guns to take down the enemy army.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'P.O.W. - Prisoners of War (USA)', '1989', NaN, 'SNK', '1-2', NaN, 'Side-scrolling beat ''em up.', 'Escape a prisoner of war camp and destroy the enemy base.', 'The North American version of the SNK arcade port.', 'It features tough enemies and a leveling system where you gain health and power as you progress through the mission.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'P''radikus Conflict, The (USA) (Unl)', '1990', NaN, 'Sculptured Software', '1', NaN, 'Side-scrolling shooter.', 'Pilot a ship through alien territory to end the war.', 'An unlicensed space shooter by Color Dreams.', 'Featuring multi-directional scrolling and power-ups, it offers a challenging take on the save the galaxy trope with a distinct 8-bit style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Pac-Land (Japan)', '1984', NaN, 'Namco', '1', NaN, 'Side-scrolling platformer.', 'Guide Pac-Man back home through various obstacles.', 'A unique departure from the maze-style Pac-Man games.', 'Based on the arcade game, players jump over fire hydrants and trip hazards while avoiding ghosts in a scrolling 8-bit world.', NULL);
