INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Paperboy (Japan)', '1988', NaN, 'Tengen', '1', NaN, 'Action / Driving.', 'Deliver newspapers while dodging suburban obstacles.', 'The Famicom port of the legendary Atari arcade game.', 'Players ride a bicycle through a neighborhood, aiming to toss papers into mailboxes or doorsteps while avoiding dogs, cars, and breakdancers.', NULL);
