INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Parallel World (Japan)', '1990', NaN, 'Zap Corp', '1', NaN, 'Puzzle / Platformer.', 'Navigate two dimensions to find the exit of each level.', 'A unique and brain-teasing puzzle-platformer.', 'The screen is often split or requires switching between parallel versions of the map to solve spatial puzzles and avoid hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Parallel World (Japan) [En by PentarouZero v1.0]', '1990', NaN, 'Zap Corp', '1', NaN, 'Puzzle / Platformer.', 'Solve the dimensional puzzles with fully translated text.', 'The English fan translation of the Famicom puzzle gem.', 'This patch is vital for understanding the game''s mechanics and the cryptic hints given between levels about the world''s dual nature.', NULL);
