INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Parasol Stars - Rainbow Islands II - The Story of Bubble Bobble III (Europe)', '1991', NaN, 'Taito', '1', NaN, 'Side-scrolling action.', 'Defeat enemies using magical umbrellas to save the planets.', 'The official sequel to Rainbow Islands.', 'Originally a PC Engine title, this NES port was only released in Europe. It features the same addictive bubble-style gameplay but using umbrellas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Parasol Stars - Rainbow Islands II - The Story of Bubble Bobble III (Europe) (Beta)', '1991', NaN, 'Taito', '1', NaN, 'Side-scrolling action.', 'Save the planets in this unfinished development build.', 'A rare prototype of the NES version of Parasol Stars.', 'It shows early level layouts and some differences in enemy behavior, offering a look at how Ocean adapted the game for the 8-bit console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Paris-Dakar Rally Special (Japan)', '1991', NaN, 'Players', '1', NaN, 'Racing / Action.', 'Win the world''s toughest rally through various stages.', 'A bizarre and unique genre-bending racing game.', 'It starts as a top-down racer but includes segments where the driver gets out of the car for side-scrolling platforming action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Parodius (Europe)', '1992', NaN, 'Konami', '1-2', NaN, 'Side-scrolling shooter.', 'Stop the nonsense in this hilarious parody of Gradius.', 'A legendary cute-em-up by Konami.', 'Featuring Vic Viper, a penguin, and a baby, it uses the Gradius power-up system but in a world filled with giant pandas and dancing penguins.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Parodius da! (Japan)', '1990', NaN, 'Konami', '1-2', NaN, 'Side-scrolling shooter.', 'Experience the original Japanese nonsense shooter.', 'The Famicom version of the iconic arcade parody.', 'Known for its incredible music and vibrant graphics, it’s one of the most technically impressive shooters on the entire system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Peek-A-Boo Poker (Asia) (Unl)', '1989', NaN, 'Panesian', '1', NaN, 'Gambling / Adult.', 'Win poker hands to reveal hidden images.', 'An unlicensed adult poker game by Hacker International.', 'It features standard video poker mechanics combined with 8-bit art rewards, typical of the unlicensed Japanese adult market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Peepar Time (Japan)', '1989', NaN, 'Jaleco', '1-2', NaN, 'Puzzle.', 'Rotate tiles to create a path for the character.', 'A creative and colorful logic-based puzzle game.', 'Similar to Pipe Dream, players must think ahead to guide the protagonist through mazes by manipulating the floor tiles in real-time.', NULL);
