INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Pegasus 5 in 1 (Unl)', '1992', NaN, 'Multicart', '1', NaN, 'Multi-game.', 'Play five different unlicensed games on one cart.', 'Another classic multicart for the Pegasus clone system.', 'Features a mix of simple shooters and puzzles, often used as a pack-in for the famous Famicom-clone consoles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Penguin Kun Wars (Japan)', '1990', NaN, 'Magic', '1', NaN, 'Sports / Action.', 'Win the ball-tossing tournament against other animals.', 'A fun and frantic dodgeball style arcade port.', 'Two animals face off across a table, trying to toss all the balls to the opponent''s side before time runs out.', NULL);
