INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Power Punch II (USA)', '1992', NaN, 'Software Creations', '1', NaN, 'Sports / Boxing.', 'Defeat a series of intergalactic boxers to become champion.', 'A sci-fi boxing game originally planned as a Mike Tyson sequel.', 'Following the style of Punch-Out!!, you fight weird aliens in the ring. It''s known for its high difficulty and large character sprites.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Power Rangers III (Unl)', '1995', NaN, 'Fan-made', '1', NaN, 'Side-scrolling action.', 'Stop the evil forces in this unlicensed crossover.', 'A famous pirate bootleg featuring the Power Rangers.', 'Usually a hack of a different game (like Kyoryu Sentai Zyuranger), this unlicensed version was a hit in the 90s clone market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Power Rangers IV (Unl)', '1995', NaN, 'Fan-made', '1', NaN, 'Side-scrolling action.', 'Fight through new levels in this pirate sequel.', 'Another unlicensed entry in the 8-bit Ranger series.', 'This bootleg often features sprites from various games mashed together to create a new Power Rangers adventure for Famicom clones.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Power Soccer (Japan)', '1993', NaN, 'Jaleco', '1', NaN, 'Sports / Soccer.', 'Win the league with an overhead view of the pitch.', 'A solid and fast-paced soccer simulation for Famicom.', 'It offers different team formations and a focus on arcade-style passing and shooting, typical of the early 8-bit sports era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Predator (Australia)', '1990', NaN, 'Sony Imagesoft', '1', NaN, 'Side-scrolling action.', 'Survive the jungle and defeat the cloaked hunter.', 'The Australian release of the movie-based platformer.', 'Players control Dutch, fighting through side-scrolling stages before entering surreal Big Mode battles against the Predator.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Predator (Japan)', '1990', NaN, 'Sony Imagesoft', '1', NaN, 'Side-scrolling action.', 'Survive the jungle and defeat the cloaked hunter.', 'The Japanese Famicom version of the movie tie-in.', 'It features the same mix of standard platforming and the strange Big Mode boss fights that defined this 8-bit adaptation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Predator (USA)', '1990', NaN, 'Sony Imagesoft', '1', NaN, 'Side-scrolling action.', 'Survive the jungle and defeat the cloaked hunter.', 'The North American version of the Arnold classic.', 'Famous for its difficult platforming and pink-heavy color palette, it’s a cult classic for fans of 80s movie games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'President no Sentaku (Japan)', '1988', NaN, 'Square', '1', NaN, 'Simulation / Strategy.', 'Lead a corporation to success through strategic choices.', 'A complex business simulation game (The President''s Choice).', 'Players make executive decisions regarding investments, personnel, and production to grow their company in a competitive 8-bit market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Prince of Persia (Europe)', '1990', NaN, 'Broderbund', '1', NaN, 'Platformer / Puzzle.', 'Rescue the Princess from Jaffar in under 60 minutes.', 'A late-release port with incredible rotoscoped animation.', 'Despite being 8-bit, the movement is incredibly fluid. This European version is highly regarded for its technical polish.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Prince of Persia (France)', '1990', NaN, 'Broderbund', '1', NaN, 'Platformer / Puzzle.', 'Rescue the Princess with localized French text.', 'The French-language edition of the cinematic platformer.', 'All the time-limit warnings and story elements are translated, allowing for a deep immersion into the Arabian nights setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Prince of Persia (Germany)', '1990', NaN, 'Broderbund', '1-2', NaN, 'Platformer / Puzzle.', 'Rescue the Princess with localized German text.', 'The German-language edition of the cinematic platformer.', 'It maintains the legendary difficulty and precision jumping of Jordan Mechner''s classic, fully localized for the German market.', NULL);
