INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Pro Sport Hockey (USA)', '1993', NaN, 'Sculptured Software', '1', NaN, 'Sports / Hockey.', 'Win the cup in this professional hockey simulation.', 'A late-era NES sports game with NHL-style play.', 'It features a fast-paced vertical view of the rink, with solid controls for passing, checking, and shooting.', NULL);
