INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Quattro Arcade (USA) (Unl)', '1992', NaN, 'Codemasters', '1', NaN, 'Arcade / Compilation', 'Score high points', 'An arcade game collection', 'Quattro Arcade bundles four classic-style arcade games with varied gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Quattro Sports (USA) (Unl)', '1992', NaN, 'Codemasters', '1', NaN, 'Sports / Multi-game.', 'Win in Baseball, Soccer, Tennis, and BMX Simulator.', 'A 4-in-1 sports compilation by Codemasters.', 'It offers four distinct unlicensed sports games on one cartridge, focusing on simple arcade mechanics and high-score chasing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Quest of Ki, The (Japan)', '1992', NaN, 'Codemasters', '1', NaN, 'Platform / Puzzle.', 'Climb the 100 floors of the tower to find the Blue Crystal Rod.', 'A challenging prequel to The Tower of Druaga.', 'Players control Ki, who can only jump and float. The game is famous for its high difficulty and unique inertia-based movement.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Quest of Ki, The (Japan) [T-En by Zynk Oxhyde v2.0]', '1988', NaN, 'Namco', '1', NaN, 'Platform / Puzzle.', 'Climb the tower with fully translated English text.', 'The English fan translation of the Famicom-exclusive Ki quest.', 'This patch makes the story intermissions and secret room hints accessible, which is vital for completing the grueling 100 levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Quinty (Japan)', '1988', NaN, 'Namco', '1', NaN, 'Puzzle / Action.', 'Flip floor tiles to defeat enemies and rescue your girlfriend.', 'The debut game from Game Freak (creators of Pokémon).', 'Known in the West as Mendel Palace, it’s a brilliant single-screen puzzle game where you use the environment as a weapon.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.B.I. Baseball (USA)', '1989', NaN, 'Namco', '1-2', NaN, 'Sports / Baseball.', 'Outscore your opponent in a pro-style baseball game.', 'The first NES baseball game to use real player names.', 'Published by Tengen, it features actual stats from the 1986 and 1987 seasons, offering a more realistic experience than Black Box titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.B.I. Baseball (USA) (Unl)', '1988', NaN, 'Tengen', '1', NaN, 'Sports / Baseball.', 'Win the game in the unlicensed black cartridge.', 'The unlicensed version of the R.B.I. hit.', 'Identical to the licensed release but sold in Tengen''s proprietary black shell after their fallout with Nintendo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.B.I. Baseball 2 (USA) (Unl)', '1988', NaN, 'Tengen', '1', NaN, 'Sports / Baseball.', 'Lead your team to victory with updated 1989 rosters.', 'An unlicensed sequel with more teams and stats.', 'It expanded the roster significantly and improved the digitized player portraits, becoming a staple for sports fans on the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.B.I. Baseball 3 (USA) (Unl)', '1989', NaN, 'Tengen', '1', NaN, 'Sports / Baseball.', 'Compete with all division champions from 1983-1990.', 'The ultimate unlicensed 8-bit baseball compilation.', 'It allows players to use historical teams and improved pitching mechanics, representing the peak of the R.B.I. series on the hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.C. Pro-Am (Europe)', '1990', NaN, 'Tengen', '1', NaN, 'Isometric Racing.', 'Win races and collect letters to upgrade your car.', 'A legendary racing game developed by Rare.', 'Players control remote-controlled cars, using missiles and bombs to sabotage rivals while navigating hazard-filled tracks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.C. Pro-Am (Europe) (Rev A)', '1991', NaN, 'Tengen', '1', NaN, 'Isometric Racing.', 'Win races with minor technical fixes.', 'A revised PAL release of the racing classic.', 'This version addresses rare glitches in the upgrade system and ensures better performance on European NES consoles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.C. Pro-Am (USA)', '1988', NaN, 'Rare', '1', NaN, 'Isometric Racing.', 'Win races and collect letters to upgrade your car.', 'The definitive North American isometric racer.', 'Famous for its tight controls and cheat AI, it remains one of the most addictive and well-programmed games on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.C. Pro-Am (USA) (Rev A)', '1988', NaN, 'Rare', '1', NaN, 'Isometric Racing.', 'Win races with minor code optimizations.', 'A revised US release of Rare''s racing hit.', 'This update polishes the sprite-flickering issues that occurred when multiple cars and items were on screen simultaneously.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.C. Pro-Am II (Europe)', '1988', NaN, 'Rare', '1-2', NaN, 'Isometric Racing.', 'Earn money to buy car upgrades and win the tour.', 'A massive sequel with 4-player support and RPG elements.', 'It introduced a shop system to buy better engines and tires, plus significantly more varied track layouts and hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'R.C. Pro-Am II (USA)', '1988', NaN, 'Rare', '1-2', NaN, 'Isometric Racing.', 'Earn money to buy car upgrades and win the tour.', 'The highly sought-after US sequel by Rare.', 'One of the best late-era NES games, featuring 4-player competitive play and deep car customization.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Race America (USA)', '1992', NaN, 'Rare', '1-2', NaN, 'Racing.', 'Win cross-country drag races across the United States.', 'A unique 2-player split-screen drag racing game.', 'Unlike other racers, it focuses on gear shifting and lane changes from a behind-the-car perspective during high-speed duels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Racer Mini Yonku - Japan Cup (Japan)', '1992', NaN, 'Rare', '1-2', NaN, 'Simulation / Racing.', 'Customize and race Mini 4WD battery-powered cars.', 'A racing sim based on the popular Tamiya toy line.', 'Players focus on car assembly and part selection (motors, rollers, tires) rather than direct steering during the races.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Racermate Challenge II (USA) (Unl) (v6.02.002)', '1992', NaN, 'Accolade', '1-2', NaN, 'Sports / Simulation.', 'Compete in indoor cycling races using real bikes.', 'A highly specialized and rare fitness peripheral game.', 'Used with the CompuTrainer system, it allowed users to race against digital avatars in a primitive but effective fitness simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Racket Attack (Europe)', '1992', NaN, 'Asmik', '1', NaN, 'Sports / Tennis.', 'Win the world tennis tournament on various surfaces.', 'A solid and realistic 8-bit tennis simulation.', 'It features 16 different players and emphasizes court positioning and timing for different shot types like lobs and smashes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Racket Attack (USA)', '1993', NaN, 'Aleph', '1', NaN, 'Sports / Tennis.', 'Win the world tennis tournament on various surfaces.', 'The North American release of the pro tennis title.', 'Known for its smooth scrolling and large player sprites, it offers a challenging take on the sport for 8-bit fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rackets & Rivals (Europe)', '1988', NaN, 'Hudson Soft', '1', NaN, 'Sports / Tennis.', 'Outplay your rivals to win the Grand Slam.', 'A late-release European exclusive tennis game.', 'Published by Konami/Palcom, it features vibrant graphics and a more arcade-like feel than other 8-bit tennis sims.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rad Racer (Europe)', '1988', NaN, 'Hudson Soft', '1', NaN, 'Racing.', 'Reach the checkpoints before the time runs out.', 'An iconic high-speed racer developed by Square.', 'Known for its 3D mode and great music, it captures the feel of OutRun with its multiple car choices and varied environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rad Racer (USA)', '1992', NaN, 'Jaleco', '1', NaN, 'Racing.', 'Reach the checkpoints before the time runs out.', 'The definitive US version of the 3D racing hit.', 'It was a major title for the Power Glove and famously included 3D glasses in the original retail box.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rad Racer II (USA)', '1987', NaN, 'Square', '1', NaN, 'Racing.', 'Win high-speed races with improved physics.', 'An exclusive US sequel to the Square racing hit.', 'It features more detailed backgrounds, more aggressive AI, and a spin-out mechanic that made the gameplay more challenging.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rad Racket - Deluxe Tennis II (USA) (Unl)', '1987', NaN, 'Square', '1', NaN, 'Sports / Tennis.', 'Defeat the pros in this unlicensed tennis challenge.', 'An unlicensed tennis title by American Video Entertainment.', 'It offers a basic but functional representation of the sport, typical of the budget-friendly unlicensed market in the US.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Radia Senki - Reimei Hen (Japan)', '1990', NaN, 'Square', '1', NaN, 'Action RPG.', 'Lead a party of heroes to stop the Lemurian Empire.', 'A deep and technically impressive Action RPG.', 'It features real-time party combat and a sprawling story, showing what the Famicom could do at the peak of the RPG era.', NULL);
