INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Road Fighter (Japan)', '1984', NaN, 'Konami', '1', NaN, 'Racing.', 'Reach the finish line before running out of fuel.', 'The original Famicom release of the Konami hit.', 'One of the earliest and most addictive Famicom titles, famous for its simple controls and increasingly chaotic traffic patterns.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Road Runner (USA) (Unl)', '1992', NaN, 'Sunsoft', '1', NaN, 'Action / Racing.', 'Outrun Wile E. Coyote and reach the end of the road.', 'An unlicensed port of the Atari arcade game.', 'Published by Tengen, it features the iconic Looney Tunes duo in a high-speed chase where you must eat birdseed to maintain speed.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'RoadBlasters (Europe)', '1989', NaN, 'Atari Games', '1', NaN, 'Combat Racing.', 'Reach the checkpoints while destroying enemy vehicles.', 'A post-apocalyptic combat racer by Atari.', 'It blends high-speed driving with shooting, featuring a fuel management system and mid-race weapon upgrades delivered by a support plane.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'RoadBlasters (USA)', '1989', NaN, 'Atari Games', '1', NaN, 'Combat Racing.', 'Reach the checkpoints while destroying enemy vehicles.', 'The North American version of the arcade hit.', 'Known for its smooth scrolling and intense action, it’s a faithful port of the coin-op original that tests both driving and shooting skills.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Robin Hood - Prince of Thieves (Europe)', '1991', NaN, 'Ocean', '1', NaN, 'Action RPG.', 'Lead the Merry Men to defeat the Sheriff of Nottingham.', 'An ambitious tie-in to the Kevin Costner movie.', 'It features a mix of top-down exploration, side-scrolling combat, and large-scale battles, offering a surprisingly deep adventure for a movie game.', NULL);
