INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Robin Hood - Prince of Thieves (Spain)', '1991', NaN, 'Ocean', '1', NaN, 'Action RPG.', 'Defeat the Sheriff with localized Spanish text.', 'The Spanish-language edition of the Robin Hood quest.', 'This version allows Spanish-speaking fans to follow the plot and dialogue-based clues of the Sherwood Forest adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Robin Hood - Prince of Thieves (USA)', '1991', NaN, 'Ocean', '1', NaN, 'Action RPG.', 'Lead the Merry Men to defeat the Sheriff of Nottingham.', 'The definitive North American release of the movie title.', 'Features a unique password system and a diverse range of weapons, including bows and staves, to reclaim the throne of England.', NULL);
