INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Robo Warrior (Europe)', '1988', NaN, 'Set', '1', NaN, 'Action / Puzzle.', 'Use bombs to clear paths and find the exit of each world.', 'A spin-off of the Bomberman series (Bomber King).', 'Players control a robot that must strategically use bombs to destroy blocks, manage life-support energy, and fight mechanical bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Robo Warrior (USA)', '1988', NaN, 'Set', '1', NaN, 'Action / Puzzle.', 'Use bombs to clear paths and find the exit of each world.', 'The North American release of the tactical bomb-action game.', 'Famous for its catchy music and high difficulty, it requires careful resource management of missiles and energy tanks to survive.', NULL);
