INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'RoboCop (Europe)', '1988', NaN, 'Ocean', '1', NaN, 'Side-scrolling action.', 'Clean up the streets of Detroit and stop OCP''s plot.', 'The PAL version of the movie-based hit by Data East.', 'You control Murphy through various urban stages, featuring the iconic movie theme and heavy-hitting 8-bit combat.', NULL);
