INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'RoboCop (USA)', '1988', NaN, 'Ocean', '1', NaN, 'Side-scrolling action.', 'Clean up the streets of Detroit and stop OCP''s plot.', 'The definitive North American cyborg action game.', 'Players use Murphy’s iconic Auto-9 pistol to take down thugs and ED-209 in a gritty representation of Old Detroit.', NULL);
