INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'RoboCop 2 (Japan)', '1990', NaN, 'Ocean', '1', NaN, 'Side-scrolling action.', 'Stop the spread of Nuke and defeat RoboCop 2.', 'The Famicom version of the second RoboCop movie.', 'It maintains the high challenge and complex level design of the Ocean-developed sequel, localized for the Japanese market.', NULL);
