INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 2020 New Year''s Hack', '2020', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Stop Dr. Wily in this massive 2020 update.', 'One of the most polished New Year hacks.', 'Includes professional-level stage design and new boss patterns, serving as a tribute to the longevity of the 8-bit Blue Bomber.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 3 - Dr. Wily no Saigo! (Japan)', '1990', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Defeat the 8 Robot Masters and the mysterious Break Man.', 'The original Famicom version of Mega Man 3.', 'Introduced the slide mechanic and Rush the dog. Known for its legendary soundtrack and the inclusion of the Doc Robot stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 3 - Dr. Wily no Saigo! (Japan) [Hack by Rock5easily v20090301] (~Rockman 3 Endless)', '1990', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Survive as long as possible in a never-ending level.', 'A survival-mode hack based on Mega Man 9/10 style.', 'It creates a procedurally generated (randomized) stage where players test their endurance against infinite waves of enemies and hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 3 - Dr. Wily no Saigo! (Japan) [Hack by Small Apple v1.0] (~Rockman 3 Alpha)', '1990', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Experience a modified version of the 3rd adventure.', 'A technical Alpha style overhaul of Rockman 3.', 'Features adjusted weapon physics and rearranged enemy spawns to provide a different flow to the classic 1990 gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 3 Improvement', '1990', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Play Rockman 3 with bug fixes and better performance.', 'A Quality of Life enhancement for the third game.', 'Fixes infamous slowdowns and sprite flickering issues, making it the smoothest way to play the original Famicom title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 3: Showdown Edition', '1990', NaN, 'Capcom', '1', NaN, 'Boss Rush.', 'Fight every boss in the game in a rapid-fire gauntlet.', 'A specialized hack focused entirely on boss fights.', 'Players can jump straight into the action against the Robot Masters and Wily''s machines without navigating through the levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 4 - Aratanaru Yabou!! (Japan)', '1991', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Stop the mysterious Dr. Cossack and his 8 robots.', 'The original Famicom version of Mega Man 4.', 'This entry introduced the New Mega Buster (charge shot), adding a new layer of strategy to the core run-and-gun gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 4 - Aratanaru Yabou!! (Japan) [Hack by Rock5easily v20090810] (~Rockman 4 Endless)', '1991', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Test your skills in an infinite looping challenge.', 'A survival-mode hack for the Rockman 4 engine.', 'Much like the 3rd version, it challenges players to see how many screens they can clear before losing all their lives.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 4 BCAS (Burst Chaser X Air Sliding)', '1991', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Master high-speed movement with air-sliding.', 'A mechanical hack adding Burst Chaser abilities.', 'It allows for extremely fast gameplay, including sliding in mid-air, turning Rockman 4 into a high-octane speedrunner''s dream.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 4: Minus Infinity', '1991', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Experience a total conversion with new bosses and art.', 'Widely considered the king of Rockman hacks.', 'A masterpiece that changes everything: new weapons, branching paths, custom bosses, and music from other franchises. It''s a brand-new game.', NULL);
