INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 5 - Blues no Wana! (Japan) [Hack by Rock5easily v20081215] (~Rockman 5 Endless)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Survive the ultimate infinite gauntlet of robots.', 'An endurance hack for the fifth entry.', 'Players must manage their health and weapons carefully to survive through a variety of randomized platforming challenges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 5 - Blues no Wana! (Japan) [Hack by Rock5easily v20081215] (~Rockman 5 Endless) (No Laser Areas)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Survive the endless mode without lethal laser traps.', 'A modified version of the Endless hack.', 'Removes the controversial instant-death laser sections from the random generation, focusing on pure combat and platforming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 5 - Blues no Wana! (Japan) [Hack by Tar v1.0] (~Rockman 5 - Wily''s Dream Space)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Explore a surreal and difficult new quest.', 'A creative level-hack of Rockman 5.', 'Features completely new stage designs and a dream-like atmosphere, requiring mastery of the charge shot and Rush utilities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 5 - Double Jumper', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Traverse levels with a new double-jump ability.', 'A technical hack that alters movement physics.', 'By giving Rockman the ability to jump a second time in mid-air, it completely changes how players approach the original stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 5 (Darkwing Duck Hack)', '1992', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Play through Rockman 5 as the Terror that Flaps in the Night.', 'A sprite and theme crossover hack.', 'Replaces Rockman with Darkwing Duck, blending Capcom''s platforming with the aesthetic of the Disney Afternoon hero.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 6 - After Tournament', '1993', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Complete a new adventure set after the tournament.', 'A narrative-driven level hack for Rockman 6.', 'Uses the Rush Adaptor mechanics to create brand new challenges in a world where Dr. Wily returns once again.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 6 - Shijou Saidai no Tatakai!! (Japan)', '1993', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Win the World Robot Tournament and defeat Mr. X.', 'The final official Famicom entry in the series.', 'Features the Power and Jet Rush Adaptors, allowing Rockman to fly or punch through blocks without needing a dog-sled.', NULL);
