INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rockman 6 - Unique Harassment v1.2', '1993', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Survive a troll style hack with unexpected traps.', 'A humorous and frustratingly difficult hack.', 'It places traps where you least expect them, designed to surprise even the most experienced Rockman fans.', NULL);
