INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Romancia (Japan) [En by DvD Rev A] (~Dragon Slayer Jr. - Romancia)', '1987', NaN, 'Falcom', '1', NaN, 'Action / RPG.', 'Break the curse with fully translated English text.', 'The fan translation of the Famicom-exclusive Romancia.', 'Essential for understanding the bizarre clues and items required to finish this punishingly difficult and unique RPG.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Roundball - 2-on-2 Challenge (Europe)', '1992', NaN, 'Kemco', '2', NaN, 'Sports / Basketball.', 'Outscore your rivals in street-style basketball.', 'A focused 2-on-2 basketball simulation.', 'It emphasizes tactical positioning and features a behind-the-back camera angle during free throws, offering a solid 8-bit hoop experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Roundball - 2-on-2 Challenge (USA)', '1992', NaN, 'Kemco', '2', NaN, 'Sports / Basketball.', 'Outscore your rivals in street-style basketball.', 'The North American release of the 2-on-2 challenge.', 'Features various teams and allows for high-flying dunks and quick steals in a fast-paced, arcade-style court environment.', NULL);
