INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Royal Blood (Japan)', '1991', NaN, 'Koei', '1', NaN, 'Strategy / RPG.', 'Reclaim the kingdom of Ishmeria from the dark king.', 'Known in the West as Gemfire.', 'A fantasy strategy game by Koei where players use magical jewels and mythical creatures to win tactical turn-based battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'RPG Jinsei Game (Japan)', '1990', NaN, 'Takara', '4', NaN, 'Board Game / RPG.', 'Live a full life and become the most successful hero.', 'A board game sim based on the Game of Life.', 'It adds RPG elements like character classes and monster encounters to the traditional life mechanics of career and family.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rumble Station - 15 in 1 (USA) (Unl)', '1992', NaN, 'Unknown', '1', NaN, 'Multi-game.', 'Play 15 different unlicensed games on one cart.', 'A Color Dreams collection for the late NES market.', 'Includes titles like Baby Boomer and Captain Comic, serving as a budget-friendly way to play several unlicensed action games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rush''n Attack (Europe)', '1987', NaN, 'Konami', '2', NaN, 'Side-scrolling action.', 'Infiltrate enemy territory and destroy their secret weapon.', 'A brutal knife-only action game by Konami.', 'Players must run through military bases, using only a knife and occasional stolen weapons to survive waves of soldiers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rush''n Attack (USA)', '1987', NaN, 'Konami', '2', NaN, 'Side-scrolling action.', 'Infiltrate enemy territory and destroy their secret weapon.', 'The North American version of Green Beret.', 'Famous for its high difficulty and the iconic siren sound effects, it’s a classic test of 8-bit reflexes and timing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rygar (Europe)', '1987', NaN, 'Tecmo', '1', NaN, 'Action / Adventure.', 'Defeat Ligar using the Diskarmor weapon.', 'An ambitious non-linear action-adventure.', 'Players explore a connected world (Metroidvania-style), gaining new abilities to access higher areas in a quest to save the land of Argool.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rygar (USA)', '1987', NaN, 'Tecmo', '1', NaN, 'Action / Adventure.', 'Defeat Ligar using the Diskarmor weapon.', 'A legendary NES adventure with RPG elements.', 'Featuring a unique shield-on-a-chain weapon, it blends platforming with top-down segments and character growth.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Rygar (USA) (Rev A)', '1987', NaN, 'Tecmo', '1', NaN, 'Action / Adventure.', 'Defeat Ligar with minor bug and text fixes.', 'A revised North American release of the classic.', 'This update polishes the transition between the side-scrolling levels and the top-down overhead exploration map.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'S.C.A.T. - Special Cybernetic Attack Team (USA)', '1990', NaN, 'Natsume', '2', NaN, 'Side-scrolling shooter.', 'Stop the alien invasion over New York City.', 'A top-tier shooter known as Action in New York.', 'Players fly with a jetpack and two satellite orbs that can be rotated to shoot in any direction, offering a highly strategic combat system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Sack of Flour V1b by CMU NESdev Team', '1991', NaN, 'CMU NESdev Team', '1', NaN, 'Technical Demo.', 'Test the capabilities of the NES engine.', 'A modern homebrew tech-demo for NES development.', 'Created by the CMU NESdev team, it showcases physics and sprite handling, serving as a tool for modern 8-bit coders.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Saint Seiya - Ougon Densetsu (Japan)', '1987', NaN, 'Bandai', '1', NaN, 'RPG / Action.', 'Progress through the story of the Bronze Knights.', 'The first Knights of the Zodiac game for Famicom.', 'It mixes side-scrolling platforming with turn-based Cosmo battles, covering the early story arcs of the famous anime.', NULL);
