INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Saint Seiya - Ougon Densetsu Kanketsu Hen (Japan) (Beta)', '1988', NaN, 'Bandai', '1', NaN, 'RPG / Strategy.', 'Play an early build of the Sanctuary quest.', 'A rare prototype of the second Saint Seiya game.', 'Contains unfinished battle animations and early music tracks, offering a glimpse into how Bandai developed the anime license.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Saiyuuki World (Japan)', '1988', NaN, 'TechnoSoft', '1', NaN, 'Action / Platformer.', 'Journey to the West to defeat the demon king.', 'A Sunsoft-published reskin of Wonder Boy in Monster Land.', 'It replaces Wonder Boy with Goku (the monkey king) but keeps the deep RPG-lite mechanics of buying armor and spells.', NULL);
