INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'SD Gundam Gaiden - Knight Gundam Monogatari 3 - Densetsu no Kishi Dan (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Turn-based RPG.', 'Lead the legendary knights to the final victory.', 'The third and most ambitious fantasy Gundam RPG.', 'It features large sprites and a complex narrative, representing the peak of 8-bit RPG storytelling for the franchise.', NULL);
