INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Secret Scout in the Temple of Demise (USA) (Unl)', '1991', NaN, 'Color Dreams', '1', NaN, 'Side-scrolling action.', 'Escape the Temple of Demise and find the treasure.', 'An unlicensed action game by Color Dreams.', 'Featuring a protagonist in a jungle setting, it requires precise jumps and combat against various ancient traps and guardians.', NULL);
