INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Seicross (USA)', '1986', NaN, 'Nichibutsu', '2', NaN, 'Racing / Shooter.', 'Ride your hoverbike and rescue survivors.', 'The North American release of the Nichibutsu classic.', 'Known for its high difficulty and the need to manage energy while bumping into rival petra-riders.', NULL);
