INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Spot - The Video Game (USA)', '1991', NaN, 'Nintendo', '1', NaN, 'Board Game / Puzzle.', 'Outmaneuver your opponent to cover the board.', 'The North American release of the 7-Up strategy game.', 'It features fun animations for the Spot characters and multiple difficulty levels for the computer AI.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Spy Hunter (USA)', '1987', NaN, 'Bally Midway', '1', NaN, 'Combat Racing.', 'Destroy enemy vehicles while protecting civilians.', 'A classic overhead arcade port by Bally Midway.', 'Your car can transform into a boat and features upgrades like oil slicks, smoke screens, and missiles delivered by a supply truck.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Spy vs Spy (Europe)', '1988', NaN, 'First Star Software', '2', NaN, 'Strategy / Action.', 'Find the secret items and escape before your rival.', 'A brilliant split-screen trap-laying game.', 'Based on the MAD Magazine comic, players must search a building for loot while setting lethal traps for each other in real-time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Spy vs Spy (Japan)', '1988', NaN, 'First Star Software', '2', NaN, 'Strategy / Action.', 'Outsmart the other spy in this tactical duel.', 'The Famicom version of the iconic comic game.', 'Known for its addictive 2-player mode where players must remember which furniture they''ve booby-trapped.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Spy vs Spy (USA)', '1988', NaN, 'First Star Software', '2', NaN, 'Strategy / Action.', 'Find the items and reach the airport first.', 'The definitive US version of the spy classic.', 'A masterclass in 8-bit competitive play, featuring the White Spy and Black Spy in an endless loop of slapstick violence.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Sqoon (Japan)', '1986', NaN, 'Irem', '1', NaN, 'Side-scrolling shooter.', 'Rescue humans from the undersea invaders.', 'A unique pink submarine shooter by Irem.', 'You must manage your oxygen levels by surfacing or catching fuel, all while shooting aliens and rescuing survivors from the deep.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Sqoon (USA)', '1986', NaN, 'Irem', '1', NaN, 'Side-scrolling shooter.', 'Rescue humans from the undersea invaders.', 'The North American release of the undersea shooter.', 'Famous for its vibrant colors and challenging gameplay that requires both shooting skill and resource management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Square no Tom Sawyer (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Turn-based RPG.', 'Experience the adventures of Tom Sawyer in 8-bit.', 'A rare RPG by Square (before Final Fantasy fame).', 'It features a unique art style that looks like a child''s sketches and focuses on the classic Mark Twain story with RPG combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Squashed (USA) (Proto)', '1994', NaN, 'Open Sesame Games', '1', NaN, 'Puzzle / Action.', 'Survive the crushing walls in this unreleased game.', 'A rare prototype of a game that never made it to market.', 'It features a unique perspective where players must move quickly to avoid being flattened by the environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Stack-Up (World)', '1985', NaN, 'Nintendo', '2', NaN, 'Puzzle.', 'Move colored blocks to match the pattern using R.O.B.', 'One of two games designed for the NES Robot.', 'Players use the controller to send commands to R.O.B., who physically moves discs on his base to solve the in-game puzzle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Stadium Events (Europe)', '1987', NaN, 'Fun Factory', '2', NaN, 'Sports / Racing.', 'Win the track and field events using the Power Pad.', 'The ultra-rare precursor to World Class Track Meet.', 'One of the most expensive games in history. It features four Olympic-style events designed for Nintendo''s floor mat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Stadium Events (USA)', '1987', NaN, 'Fun Factory', '2', NaN, 'Sports / Racing.', 'Win the track and field events using the Power Pad.', 'The rarest licensed North American NES game.', 'Recalled almost immediately to be rebranded as a Nintendo title, making the Bandai branded version a legendary collector''s item.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Stanley - The Search for Dr. Livingston (USA)', '1992', NaN, 'Sculptured Software', '1', NaN, 'Side-scrolling action.', 'Find the missing doctor in the heart of Africa.', 'An adventure game with a heavy focus on exploration.', 'Players navigate through jungles and caves, using various tools and weapons to survive the hazards of the 19th-century wilderness.', NULL);
