INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Star Force (USA)', '1985', NaN, 'Tecmo', '1', NaN, 'Vertical shooter.', 'Destroy the floating fortresses of the enemy fleet.', 'The North American release of the sci-fi shooter.', 'Players must fly through 24 areas, each named after a letter of the Greek alphabet, in an endless cosmic war.', NULL);
