INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Stealth ATF (Europe)', '1989', NaN, 'MicroProse', '1', NaN, 'Combat Flight Sim.', 'Complete stealth missions and destroy enemy targets.', 'A first-person cockpit flight simulator.', 'You pilot a stealth fighter, engaging in dogfights and bombing runs while managing radar and fuel across several global theaters of war.', NULL);
