INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Strange Mario Bros.', '1985', NaN, 'Hack', '2', NaN, 'Platformer.', 'Navigate weird levels in this creative hack.', 'A troll or kaizo style hack of Super Mario Bros.', 'It features invisible blocks, unexpected traps, and surreal level designs intended to challenge even the best Mario players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Strategist (Asia)', '1987', NaN, 'Konami', '2', NaN, 'Strategy / Board.', 'Outsmart the opponent on a tactical grid.', 'An unlicensed strategy game by Sachen.', 'Players must capture enemy territory using a set of rules similar to Go or Othello, featuring minimalist 8-bit graphics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Blaster II Pro (Unl)', '1992', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Defeat all fighters to become the champion.', 'An unlicensed fighting game based on Street Fighter.', 'One of many 8-bit ports of SFII, attempting to replicate the combos and special moves of the arcade on limited hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Blaster V Turbo 20 (Unl)', '1993', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Win the world tournament in this pirate fighter.', 'An unlicensed fighter featuring a mix of characters.', 'Often found on multicarts, it''s known for its glitchy but ambitious attempt at 16-bit style fighting mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Cop (USA)', '1989', NaN, 'Bandai', '1', NaN, 'Action.', 'Pursue and arrest criminals on the city streets.', 'A specialized game for the Power Pad.', 'Players must run in place on the NES floor mat to chase suspects and use the controller to perform arrests and attacks.', NULL);
