INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Fighter 2010 - The Final Fight (USA)', '1990', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Fight through planets to avenge your partner.', 'A futuristic action game loosely tied to Street Fighter.', 'In the US version, you play as Ken from SF in the year 2010, using bionic implants to fight aliens in very difficult levels.', NULL);
