INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Fighter II - The World Warrior (Unl)', '1992', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Defeat the 8 world warriors and the grand masters.', 'An unlicensed bootleg port of Street Fighter II.', 'This version is famous for how much it actually managed to squeeze onto a Famicom cart, including most of the main cast.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Fighter II Pro (Unl)', '1992', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Defeat the 8 world warriors and the grand masters.', 'A slightly improved unlicensed version of SFII.', 'Features better color palettes and slightly more responsive controls than earlier 8-bit pirate fighting games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Fighter III (9 Fighter) (Unl)', '1993', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Battle through a roster of 9 different fighters.', 'An unlicensed 8-bit take on Street Fighter III.', 'While it doesn''t have the Parry system, it attempts to replicate the 16-bit sprites and backgrounds of the later arcade entries.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Fighter IV (Unl)', '1994', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Win the tournament in this modern-styled pirate.', 'An unlicensed game mimicking the SFIV look.', 'A late-era bootleg that uses sprites intended to look like the 3D models of SFIV, but within the constraints of the NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Fighter IV: Enhanced Edition', '1994', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Experience a more polished unlicensed fighter.', 'A fan-hack of the unlicensed SFIV bootleg.', 'This version improves the hit detection and cleans up the graphics, making it one of the more playable 8-bit pirate fighters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Fighter V (20 Peoples) (Unl)', '1995', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Choose from a massive (duplicated) roster to fight.', 'A pirate fighter with a fake high character count.', 'Like many bootlegs, it repeats the same characters with different colors to fill up a 20-slot selection screen.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Fighter Zero 2 ''97 (Unl)', '1997', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Experience the Alpha series on your NES.', 'An unlicensed port of Street Fighter Alpha 2.', 'It features the chibi or younger looks of the characters and tries to include some of the Super Combo mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Gangs (Europe)', '1989', NaN, 'Atlus', '2', NaN, 'Beat ''em up / RPG.', 'Rescue your girlfriend and clean up the city.', 'The European name for River City Ransom.', 'Two high schoolers fight through gangs, eating at restaurants and buying items to boost their stats in this cult classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Street Heroes (Asia) (Unl)', '1992', NaN, 'Unknown', '2', NaN, 'Fighting.', 'Defeat rivals in this unlicensed brawler.', 'A unique unlicensed fighting game by Sachen.', 'Features original characters and its own fighting engine, separate from the many Street Fighter clones of the era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Strider (USA)', '1989', NaN, 'Capcom', '1', NaN, 'Side-scrolling action.', 'Infiltrate the Kazakh Soviet Socialist Republic.', 'An action-adventure different from the arcade version.', 'Unlike the arcade''s linear path, this NES version is more of a Metroidvania where you must find floppy disks to unlock new areas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Study Box (Japan)', '1989', NaN, 'Nintendo', '1', NaN, 'Educational.', 'Learn various subjects using the Study Box add-on.', 'A specialized educational peripheral for Famicom.', 'It used a cassette-tape based system to provide audio instructions alongside the 8-bit graphics for school lessons.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Stunt Kids (USA) (Unl)', '1992', NaN, 'Unknown', '1', NaN, 'Racing / Action.', 'Complete stunt courses without crashing.', 'An unlicensed game by Codemasters.', 'Players drive buggies through obstacle-filled tracks, focusing on jumps and speed to beat the clock in this Quattro series title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Sugoro Quest - Dice no Senshitachi (Japan)', '1991', NaN, 'Victor Interactive', '1', NaN, 'RPG / Board Game.', 'Defeat the monsters using a dice-based battle system.', 'A unique hybrid of a board game and a JRPG.', 'Players move across a map like a board game, but enter turn-based battles where dice rolls determine the strength of your attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Sugoro Quest - Dice no Senshitachi (Japan) [En by AlanMidas v20070221] [Fix by KingMike] (~Sugoro Quest - The Quest of Dice Heroes)', '1991', NaN, 'Victor Interactive', '1', NaN, 'RPG / Board Game.', 'Conquer the quest with fully translated text.', 'The English fan translation of the Famicom original.', 'This patch is crucial to understand the dice mechanics and the different Gods you can summon to help you in battle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Suikoden - Tenmei no Chikai (Japan)', '1992', NaN, 'Koei', '1', NaN, 'Strategy / Sim.', 'Unify China as a leader of the 108 outlaws.', 'Based on the classic Chinese novel Water Margin.', 'A deep strategy game by Koei where you manage a band of heroes, focusing on tactical warfare and province management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Sukeban Deka 3 (Japan)', '1989', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling action.', 'Stop the criminal conspiracy as a yo-yo wielding girl.', 'Based on the famous Delinquent Girl Detective series.', 'You control a high school girl who uses a metal yo-yo as a weapon to fight through waves of thugs and bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Summer Carnival ''92 - Recca (Japan)', '1992', NaN, 'Naxat Soft', '1', NaN, 'Vertical shooter.', 'Survive the most intense bullet hell on the NES.', 'A technical masterpiece developed for a tournament.', 'It features a staggering amount of sprites without slowdown, making it one of the fastest and most difficult shooters ever made.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Summer Carnival ''92 - Recca (Japan) [En by Aeon Genesis v1.0] (~Raging Fire - Recca)', '1992', NaN, 'Naxat Soft', '1', NaN, 'Vertical shooter.', 'Experience the Recca tournament in English.', 'The fan translation of Summer Carnival ''92.', 'While it’s a shooter, the translation helps navigate the menus and the Sound Test mode of this 8-bit engineering marvel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Summer Carnival ''92 - Recca (Japan) [Hack by Sliver X v1.0] (~Recca - Pure)', '1992', NaN, 'Naxat Soft', '1', NaN, 'Shooter / Arcade', 'Survive and score high', 'Pure arcade shooter hack', 'Recca - Pure is a modified version of Summer Carnival ''92 that removes scoring restrictions to focus on raw shooting skill.', NULL);
