INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Chinese 2 - Dragon Kid (Japan)', '1989', NaN, 'Culture Brain', '2', NaN, 'Action / Beat ''em up', 'Defeat enemies', 'Brawler sequel', 'Super Chinese 2 expands the original with more moves, stages, and improved mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Chinese 3 (Japan)', '1990', NaN, 'Culture Brain', '2', NaN, 'Action / RPG.', 'Save the Chinaland kingdom from the alien invasion.', 'The third entry in the Ninja Boy series.', 'It blends top-down RPG exploration with side-scrolling action combat. It features a high level of polish and cooperative gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Contra (Japan)', '1990', NaN, 'Konami', '2', NaN, 'Run and gun.', 'Destroy the alien life forms and their bases.', 'The original Famicom version of the arcade sequel.', 'Known as Super C in the West, this version features more frames of animation and a slightly different difficulty balance than the NES port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Contra II', '1990', NaN, 'Unlicensed', '2', NaN, 'Run and gun.', 'Stop the alien threat in this unlicensed sequel.', 'An unlicensed/pirate sequel to the Contra series.', 'Often a hack of the original games or a completely new (but glitchy) build, it tries to capture the intense 8-bit military action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Dodge Ball (USA)', '1989', NaN, 'Tecmo', '2', NaN, 'Sports / Fighting.', 'Defeat international teams in a lethal dodgeball tour.', 'A cult classic sports game by Technos.', 'Part of the Kunio-kun series, it features super shots that can blast opponents out of the arena, blending sports with combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Dodge Ball (USA) [Hack by Aka v1.0] (4 Player Edition)', '1989', NaN, 'Tecmo', '4', NaN, 'Sports / Fighting.', 'Play dodgeball with up to 4 players simultaneously.', 'A technical hack of the original Super Dodge Ball.', 'This version enables 4-player support, making the bean-ball battles even more chaotic and fun for local multiplayer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Donkey Kong (Unl)', '1994', NaN, 'Unlicensed', '1', NaN, 'Platformer.', 'Rescue the bananas in this unlicensed port.', 'An 8-bit unlicensed version of Donkey Kong Country.', 'A technical marvel for the NES, it attempts to recreate the pre-rendered 16-bit graphics and levels of the SNES classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Dyna''mix Badminton (Japan)', '1989', NaN, 'Metro', '2', NaN, 'Sports / Badminton.', 'Win the world badminton championship.', 'A realistic and fast-paced badminton simulation.', 'It features deep mechanics for smashes and drops, requiring precise timing and positioning to defeat the international AI.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Glove Ball (USA)', '1990', NaN, 'Rare', '2', NaN, 'Puzzle / Action.', 'Navigate through a 3D maze to find the exit.', 'A game specifically designed for the Power Glove.', 'Players use hand gestures to swat a ball and hit targets in a virtual room, attempting to prove the glove''s precision.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Jeopardy! (USA)', '1991', NaN, 'GameTek', '3', NaN, 'Quiz / Board Game.', 'Win the grand prize by answering in the form of a question.', 'A high-stakes version of the classic TV show.', 'Based on the Super Jeopardy! tournament, it features 4-player support and thousands of challenging trivia questions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Kaizo Bros.', '2012', NaN, 'Hack', '1', NaN, 'Platformer.', 'Survive the most punishing Mario levels ever made.', 'An extreme difficulty hack of Super Mario Bros.', 'Designed to be unfair, it requires frame-perfect jumps and knowledge of hidden traps that kill the player instantly.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Luigi Bros. 2', '2015', NaN, 'Hack', '1', NaN, 'Platformer.', 'Save the Dream World as the green brother.', 'A hack of SMB2 featuring Luigi as the lead.', 'It swaps Mario for Luigi, often adjusting the jump height and physics to better represent Luigi''s unique abilities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Luigi Bros. 3 (35th Anniversary)', '2020', NaN, 'Hack', '1', NaN, 'Platformer.', 'Embark on a grand quest to celebrate the anniversary.', 'A celebratory hack of the legendary SMB3.', 'Features custom palettes and Luigi-centric level adjustments to honor the 35th anniversary of the franchise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Luigi Bros. by L___E___T', '2013', NaN, 'Hack', '1', NaN, 'Platformer.', 'Rescue the Princess in this Luigi-themed overhaul.', 'A total conversion hack of Super Mario Bros.', 'Every sprite and many level elements are changed to put Luigi in the spotlight, created by a well-known community hacker.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Luigi Bros. by TheHappyFaceKing', '2014', NaN, 'Hack', '1', NaN, 'Platformer.', 'Experience the Mushroom Kingdom as Luigi.', 'Another creative Green Mario conversion.', 'It focuses on aesthetic changes, giving the classic 1985 game a fresh look centered around Mario''s younger brother.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Luigi Bros. by TheNintendude64', '1985', NaN, 'Nintendo', '1', NaN, 'Platformer.', 'Clear the classic stages with Luigi''s physics.', 'A physics-focused hack of the first Mario game.', 'Adjusts the traction and jump height to feel more like the slippery Luigi from later entries in the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Mario & Sonic 2 (Unl)', '1985', NaN, 'Nintendo', '1', NaN, 'Platformer.', 'Navigate levels featuring both mascot icons.', 'A bizarre unlicensed crossover bootleg.', 'It places Sonic or Mario in worlds that blend elements from both SEGA and Nintendo, often using assets from various 8-bit games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Mario All Stars NES', '1985', NaN, 'Nintendo', '1', NaN, 'Platformer.', 'Play the SNES collection on 8-bit hardware.', 'A demake hack attempting to bring All-Stars to NES.', 'It updates the graphics of the original NES games to look more like the 16-bit remakes, including a level selection menu.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Mario Bros - Another Adventure 2.01', '1985', NaN, 'Nintendo', '1', NaN, 'Platformer.', 'Explore an entirely new set of Mario levels.', 'A high-quality level hack of the original SMB.', 'It features creative level design that feels like an official lost sequel, with increased difficulty and new secrets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Super Mario Bros Health Bar', '1985', NaN, 'Nintendo', '1', NaN, 'Platformer.', 'Survive more than one hit in the Mushroom Kingdom.', 'A mechanical hack adding a life meter to Mario.', 'Instead of dying instantly, Mario has a health bar, allowing for a more forgiving (but still challenging) platforming experience.', NULL);
