INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tao (Japan)', '1989', NaN, 'Sunsoft', '1', NaN, 'RPG.', 'Embark on a journey to save the world.', 'A rare unreleased prototype of a US RPG.', 'Featuring a style similar to Dragon Quest, it was cancelled before release, leaving behind a fully playable but lost 8-bit adventure.', NULL);
