INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Taro''s Quest (USA) (Proto)', '1991', NaN, 'American Softworks', '1', NaN, 'Platformer / Puzzle.', 'Rescue the princesses in this wacky adventure.', 'A surreal game starring Japanese celeb Masashi Tashiro.', 'Players jump and solve puzzles in bizarre worlds, known for its odd humor and unconventional character design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tasac (Asia) (Unl)', '1990', NaN, 'Unknown', '1', NaN, 'Platformer / Puzzle.', 'Complete the quest with a translated title.', 'The English fan translation of the Tashiro Masashi game.', 'While the translation title is a bit cheeky, the patch is solid and allows players to navigate the game''s weird logic and levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tashiro Masashi no Princess ga Ippai (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Fighting / Adventure.', 'Compete in the martial arts tournament.', 'Based on the Kinnikuman (M.U.S.C.L.E.) spin-off.', 'It features a mix of top-down exploration and 2D fighting segments, following the story of the iconic ramen-loving martial artist.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tashiro Masashi no Princess ga Ippai (Japan) [En by Suicidal v1.0] (~Princesstual Orgy)', '1989', NaN, 'Namco', '1', NaN, 'Side-scrolling action.', 'Fight through the post-apocalyptic city.', 'The original Japanese version of Trojan.', 'Developed by Capcom, it features a sword-and-shield combat system in a gritty world filled with mutants and martial artists.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tatakae!! Rahmen Man - Sakuretsu Choujin 102 Gei (Japan)', '1988', NaN, 'Toei Animation', '1', NaN, 'Side-scrolling action.', 'Fight the mutants with minor bug fixes.', 'A revised version of the Capcom classic.', 'This update polishes some of the collision detection during the shield-blocking sequences, improving the gameplay flow.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tatakai no Banka (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Sports / Baseball.', 'Outscore the competition in this pro sim.', 'A cinematic baseball game by Tecmo.', 'Known for its large sprites and close-up action shots during catches and slides, giving it a very TV-like presentation.', NULL);
