INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tecmo Bowl (Japan)', '1987', NaN, 'Tecmo', '2', NaN, 'Sports / Football.', 'Test the early version of the gridiron hit.', 'A rare development build of the NES classic.', 'Contains different UI colors and early player stats, showing how the gameplay was balanced before the final release.', NULL);
