INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Teenage Mutant Ninja Turtles III - The Manhattan Project (USA)', '1991', NaN, 'Konami', '2', NaN, 'Beat ''em up.', 'Rescue Manhattan from being lifted into the sky.', 'The definitive 8-bit TMNT brawler.', 'Often cited as the best Turtles game on the system, featuring refined mechanics, surfboard levels, and iconic boss fights like Slash and Bebop.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tekken 2', '1997', NaN, 'Unlicensed', '2', NaN, 'Fighting.', 'Win the King of Iron Fist Tournament.', 'A surprising unlicensed 8-bit port of the 3D classic.', 'While obviously not 3D, it attempts to translate the Tekken roster and moveset into a 2D fighter with custom NES sprites.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tenchi wo Kurau (Japan)', '1989', NaN, 'Capcom', '1', NaN, 'Turn-based RPG.', 'Conquer ancient China during the Three Kingdoms.', 'Known in the West as Destiny of an Emperor.', 'A deep Capcom RPG where you recruit generals and manage large armies instead of a small party, featuring strategic combat.', NULL);
