INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tenchi wo Kurau II - Shokatsu Koumei Den (Japan) [En by Magic Destiny v1.12] (~Destiny of an Emperor II - The Story of Zhuge Liang)', '1991', NaN, 'Capcom', '1', NaN, 'Turn-based RPG.', 'Experience the epic sequel in English.', 'The fan translation of Tenchi wo Kurau II.', 'Allows Western fans to finally play the legendary sequel with a professional-quality translation of the complex historical plot.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tenkaichi Bushi - Keru Naguuru (Japan)', '1989', NaN, 'Namco', '2', NaN, 'Fighting.', 'Defeat masters to become the ultimate martial artist.', 'A unique chibi style fighting game by Namco.', 'It features a deep move list for its time and allows players to customize their fighter''s skills as they progress through the tournament.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tennis (Europe)', '1984', NaN, 'Nintendo', '2', NaN, 'Sports / Tennis.', 'Outscore your opponent in a set of tennis.', 'Part of the Nintendo Black Box sports series.', 'Mario serves as the umpire in this classic title that defined the basic mechanics for almost every tennis game that followed.', NULL);
