INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Terao no Dosukoi Oozumou (Japan)', '1989', NaN, 'Tecmo', '1', NaN, 'Sports / Sumo.', 'Rise through the ranks to become Yokozuna.', 'A realistic sumo wrestling simulation.', 'Players must manage training and timing in matches, featuring the real-life sumo star Terao and authentic tournament rules.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Terminator 2 - Judgment Day (Europe)', '1991', NaN, 'LJN', '1', NaN, 'Side-scrolling action.', 'Protect John Connor and stop Skynet.', 'A cinematic action game based on the movie.', 'Features a variety of gameplay styles, including motorcycle chases, top-down shooting, and standard side-scrolling combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Terminator 2 - Judgment Day (Japan)', '1991', NaN, 'LJN', '1', NaN, 'Side-scrolling action.', 'Protect John Connor and stop Skynet.', 'The Famicom version of the T2 blockbuster.', 'It follows the movie''s plot closely, using digitized stills from the film to tell the story between the challenging levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Terminator 2 - Judgment Day (USA)', '1991', NaN, 'LJN', '1', NaN, 'Side-scrolling action.', 'Protect John Connor and stop Skynet.', 'The definitive North American movie tie-in.', 'Known for its high difficulty and the iconic T-800 sprite, it''s a solid representation of the 1991 sci-fi classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Terminator 2 - Judgment Day (USA) (Beta)', '1991', NaN, 'LJN', '1', NaN, 'Side-scrolling action.', 'Protect John in this early development build.', 'A prototype featuring unfinished assets.', 'Shows early level designs and different enemy placements that were changed for the final commercial release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Terminator, The (USA, Europe)', '1991', NaN, 'Mindscape', '1', NaN, 'Side-scrolling action.', 'Protect Sarah Connor from the T-800.', 'Based on the original 1984 film.', 'Players control Kyle Reese, fighting through a post-apocalyptic future and modern-day Los Angeles in a race against time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Terra Cresta (Japan)', '1985', NaN, 'Nichibutsu', '2', NaN, 'Vertical shooter.', 'Form a giant robot ship to defeat the Mandler.', 'A unique ship-merging arcade shooter.', 'You collect ship parts that attach to your craft; you can then split them to cover a wider area or stay merged for more power.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Terra Cresta (USA)', '1985', NaN, 'Nichibutsu', '2', NaN, 'Vertical shooter.', 'Destroy the alien forces and their bases.', 'The North American release of the Nichibutsu hit.', 'A fast-paced shooter where power-ups change your firing pattern, requiring strategic use of the formation button.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetrastar - The Fighter (Japan)', '1989', NaN, 'Jaleco', '1', NaN, 'First-person shooter.', 'Defeat the enemy fleet in deep space.', 'A technically impressive pseudo-3D flight sim.', 'It pushes the NES hardware to create a 3D effect as you fly through space corridors and engage in dogfights with enemy ships.', NULL);
