INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetris (Europe)', '1988', NaN, 'Mirrorsoft', '2', NaN, 'Puzzle.', 'Clear lines by fitting falling blocks together.', 'The official Nintendo version for PAL regions.', 'The quintessential puzzle game that became a global phenomenon, featuring the iconic A-Type and B-Type music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetris (Japan)', '1988', NaN, 'Nintendo', '2', NaN, 'Puzzle.', 'Clear lines and achieve the highest score.', 'The original Famicom release by Bullet-Proof Software.', 'Features different controls (using Down to rotate) and a distinct selection of music compared to the Nintendo-developed version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetris (Japan) (Rev A)', '1988', NaN, 'Nintendo', '2', NaN, 'Puzzle.', 'Clear lines with updated mechanics.', 'A revised Japanese release of the BPS version.', 'Includes minor bug fixes and slightly adjusted block randomization to prevent unfair sequences of pieces.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetris (Japan) (Rev B)', '1988', NaN, 'Nintendo', '2', NaN, 'Puzzle.', 'Play the official Tetris with its famous theme.', 'A hack that restores the Classic Tetris music.', 'Replaces the standard tracks with the famous Korobeiniki folk song that players expected from other versions of the game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetris (Title Music Restoration)', '1988', NaN, 'Nintendo', '2', NaN, 'Puzzle.', 'Clear lines and see the rocket launch.', 'The most famous version of Tetris in history.', 'Developed by Nintendo, it’s the competitive standard for the Classic Tetris World Championship today.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetris (USA)', '1989', NaN, 'Nintendo', '2', NaN, 'Puzzle.', 'Play the legendary 2-player mode.', 'The famous unlicensed version by Tengen.', 'Widely considered superior to the Nintendo version for its 2-player co-op and versus modes, which were missing from the official one.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetris (USA) (Unl)', '1989', NaN, 'Atari Games', '2', NaN, 'Puzzle.', 'Match colored blocks to clear the screen.', 'A sequel focusing on color-matching mechanics.', 'Unlike the original, you must align three blocks of the same color to clear them, similar to Dr. Mario but with Tetris pieces.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetris 2 (Europe)', '1993', NaN, 'Nintendo', '2', NaN, 'Puzzle.', 'Match colored blocks to clear the screen.', 'The North American sequel to the puzzle hit.', 'Features a variety of modes, including a puzzle mode where you must clear specific patterns in a limited number of moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tetris 2 (USA)', '1993', NaN, 'Nintendo', '2', NaN, 'Puzzle.', 'Use bombs to clear massive clusters of blocks.', 'A Japan-exclusive 2-in-1 puzzle package.', 'Includes Bombliss, a strategic variant where certain blocks are bombs that explode when a line is cleared, creating chain reactions.', NULL);
