INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Time Lord (Europe)', '1990', NaN, 'Rare', '1', NaN, 'Side-scrolling action.', 'Travel through time to stop the alien invasion.', 'A challenging time-travel adventure.', 'You must find five golden orbs in different historical eras (Medieval, Old West, etc.) before time runs out to stop the alien fleet.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Time Lord (USA)', '1990', NaN, 'Rare', '1', NaN, 'Side-scrolling action.', 'Stop the aliens before they change history.', 'The North American version of Milton Bradley''s hit.', 'Known for its steep difficulty and the pressure of a real-time clock that counts down to the end of the world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Time Zone (Japan)', '1987', NaN, 'Sigma Ent.', '1', NaN, 'Side-scrolling action.', 'Rescue your girlfriend from the time-villains.', 'A cute and colorful time-traveling platformer.', 'As a young boy with a cap, you travel through various eras, from the Stone Age to the Future, using simple but tight jumping mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Time Zone (Japan) [En by KingMike v1.2]', '1987', NaN, 'Sigma Ent.', '1', NaN, 'Side-scrolling action.', 'Save the world with fully translated text.', 'The fan translation of the Famicom-exclusive platformer.', 'Makes the story and era-specific dialogue accessible, revealing a charming adventure often overlooked by Western fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Times of Lore (Japan)', '1988', NaN, 'Origin Systems', '1', NaN, 'Action / RPG.', 'Find the three artifacts to save the kingdom.', 'An 8-bit port of the classic Origin Systems RPG.', 'Featuring an overhead perspective, it blends real-time combat with deep NPC interaction and a large open world to explore.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Times of Lore (USA)', '1988', NaN, 'Origin Systems', '1', NaN, 'Action / RPG.', 'Save the kingdom from the dark forces.', 'The North American release of the fantasy epic.', 'It features a unique icon-based interface for talking and interacting with objects, simplifying the complex PC-style RPG controls for NES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tiny Toon Adventures (Europe)', '1991', NaN, 'Konami', '2', NaN, 'Platformer.', 'Rescue Babs Bunny from Montana Max.', 'A top-tier Konami platformer based on the show.', 'You play as Buster Bunny and can switch between partners (Plucky, Hamton, or Dizzy) to use their unique abilities in each stage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tiny Toon Adventures (Japan)', '1991', NaN, 'Konami', '2', NaN, 'Platformer.', 'Save Babs in this high-quality Famicom quest.', 'The original Japanese release of the Tiny Toon hit.', 'Known for its vibrant graphics and perfect controls, it''s considered one of the most polished licensed games on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tiny Toon Adventures (USA)', '1991', NaN, 'Konami', '2', NaN, 'Platformer.', 'Defeat Montana Max''s henchmen.', 'The definitive US version of the cartoon adventure.', 'A must-play for platformer fans, featuring classic locations from Acme Acres and the signature Konami feel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tiny Toon Adventures 2 - Montana Land he Youkoso (Japan)', '1992', NaN, 'Konami', '2', NaN, 'Mini-game / Action.', 'Enjoy the rides at the Montana Land theme park.', 'The sequel focusing on carnival-style challenges.', 'Each level is a theme park ride, including a roller coaster, log flume, and bumper cars, ending in a showdown with Montana Max.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tiny Toon Adventures 2 - Trouble in Wackyland (Europe)', '1992', NaN, 'Konami', '2', NaN, 'Mini-game / Action.', 'Conquer the rides and save your friends.', 'The European version of Trouble in Wackyland.', 'It maintains the high variety of gameplay styles, from high-speed racing to traditional platforming, all set in a park.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tiny Toon Adventures 2 - Trouble in Wackyland (USA)', '1992', NaN, 'Konami', '2', NaN, 'Mini-game / Action.', 'Survive the hazards of Wackyland.', 'The North American theme park adventure.', 'Famous for its Ticket system where you must earn enough points in the rides to unlock the final castle stage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tiny Toon Adventures 6 (Unl)', '1993', NaN, 'Unlicensed', '2', NaN, 'Platformer.', 'Navigate strange levels in this pirate sequel.', 'An unlicensed Chinese bootleg of Tiny Toons.', 'Often a hack of another game or a custom engine using Tiny Toon sprites, typical of the late 90s Famicom clone market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tiny Toon Adventures Cartoon Workshop (Europe)', '1992', NaN, 'Konami', '1', NaN, 'Creative / Tool.', 'Create your own Tiny Toon animated shorts.', 'A unique animation studio for the NES.', 'Players can choose characters, backgrounds, and music to direct their own cartoon scenes, proving the NES could be used for creativity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Tiny Toon Adventures Cartoon Workshop (USA)', '1992', NaN, 'Konami', '1', NaN, 'Puzzle.', 'Clear the screen in this futuristic logic game.', 'A top-down ball-bouncing puzzle game.', 'Similar to Breakout but with free-roaming movement, you must guide a ball to destroy targets while navigating complex mazes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Titan (Japan)', '1989', NaN, 'Naxat Soft', '1', NaN, 'Vertical shooter.', 'Destroy the enemy fleet in this unreleased gem.', 'A rare prototype of a Capcom shooter.', 'This game was fully finished but cancelled; it features incredible graphics and a unique lock-on system for its time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Titan Warriors (USA) (Proto)', '1993', NaN, 'Homebrew', '2', NaN, 'Adventure / Action.', 'Escape the sinking ship before time runs out.', 'A bizarre unlicensed Chinese game.', 'Based on the 1997 movie, you must navigate the ship, talk to passengers, and find items to survive the maritime disaster.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Titanic (C)', '1991', NaN, 'Unlicensed', '1', NaN, 'Adventure / Action.', 'Survive the sinking with translated dialogue.', 'The English translation of the Titanic bootleg.', 'Clarifies the mission objectives and clues, making this strange piece of pirate history actually playable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Titanic (English Translated)', '1991', NaN, 'Unlicensed', '1', NaN, 'Adventure / FMV.', 'Stop the hacker and save the concert.', 'A bizarre sci-fi adventure starring a real J-Pop band.', 'It features digitized images of the band members and a story about a futuristic world, blending music and menu-based investigation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'TM Network - Live in Power Bowl (Japan)', '1989', NaN, 'ASCII', '1', NaN, 'Light Gun / Shooter.', 'Defend Earth from an alien biological weapon.', 'A high-speed Zapper game set in space.', 'Players must shoot down alien ships and obstacles while flying through the solar system, requiring intense reflexes and accuracy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'To the Earth (Europe)', '1990', NaN, 'Access Software', '1', NaN, 'Light Gun / Shooter.', 'Reach Earth and destroy the enemy spores.', 'The North American Zapper challenge.', 'Known for being one of the most difficult Light Gun games due to the speed and frequency of enemy attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'To the Earth (USA)', '1990', NaN, 'Access Software', '1', NaN, 'Platformer / Action.', 'Rescue your bride and regain your human form.', 'A port of the famous arcade Juju Densetsu.', 'You play as a warrior turned into an ape who shoots energy balls from his mouth, navigating through prehistoric and magical lands.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('NES', 'Toki (USA)', '1991', NaN, 'Taito', '1', NaN, 'Adventure.', 'Travel through time to fix the history of Japan.', 'Based on an anime film by Toei.', 'A menu-driven adventure where you interact with historical figures and solve puzzles to prevent a temporal catastrophe.', NULL);
