INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '96 Zenkoku Koukou Soccer Senshuken (Japan)', '1996', NaN, 'Konami', '2', NaN, '2D soccer simulation with realistic high school tournament rules.', 'Win the All Japan High School Soccer Tournament.', 'Relive the 1996 Japanese high school soccer season on SNES.', '96 Zenkoku Koukou Soccer Senshuken brings authentic high school football to the SNES with deep tournament modes and team management features for sports fans.', NULL);
