INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '100 Rooms of Enemies by Daizo Dee Von', '1993', NaN, 'Homebrew', '1', NaN, 'Hardcore combat-focused platforming in a series of closed arenas.', 'Defeat every single enemy in 100 increasingly difficult rooms.', 'Master intense combat in 100 Rooms of Enemies, a challenging SNES hack.', 'A grueling test of skill, 100 Rooms of Enemies requires players to clear 100 unique stages filled with enemies using precise platforming and combat mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '2020 Super Baseball (Japan)', '1991', NaN, 'Palsoft', '2', NaN, 'Futuristic arcade baseball with power-ups and robotic players.', 'Outscore the opposing team in a high-tech baseball league.', 'Play futuristic 16-bit baseball in 2020 Super Baseball for SNES.', 'Step into the future of sports with 2020 Super Baseball. Featuring cybernetic upgrades and unique stadium rules, it''s a high-octane take on America''s favorite pastime.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '2020 Super Baseball (USA)', '1991', NaN, 'Palsoft', '2', NaN, 'Futuristic arcade baseball with power-ups and robotic players.', 'Outscore the opposing team in a high-tech baseball league.', 'Play futuristic 16-bit baseball in 2020 Super Baseball for SNES.', 'Step into the future of sports with 2020 Super Baseball. Featuring cybernetic upgrades and unique stadium rules, it''s a high-octane take on America''s favorite pastime.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '3 Jigen Kakutou Ballz (Japan)', '1995', NaN, 'Banpresto', '2', NaN, '1-on-1 fighting game using characters made of individual spheres.', 'Defeat all opponents in martial arts combat to prove supremacy.', 'Experience the unique sphere-based combat of Ballz on the SNES.', '3 Jigen Kakutou Ballz features a distinct visual style with fighters composed of balls. Master its physics-based combat system in this eccentric 16-bit fighting game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '3 Ninjas Kick Back (USA)', '1994', NaN, 'Culture Brain', '2', NaN, 'Side-scrolling action platformer based on the martial arts film.', 'Rescue your grandfather by fighting through ninja-infested levels.', 'Join the three brothers in 3 Ninjas Kick Back for SNES action.', 'Based on the hit movie, 3 Ninjas Kick Back lets you play as Rocky, Colt, or Tum-Tum. Use ninja skills and weapons to defeat the ancient Koga and save your mentor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '3000 Leagues in Search of Bowser - Mario Edition (Final)', '2023', NaN, 'ROM Hack', '1', NaN, 'Complex side-scrolling platforming with custom level mechanics.', 'Navigate a massive world to find and defeat Bowser.', 'Embark on an epic quest in 3000 Leagues in Search of Bowser for SNES.', 'This Mario Edition overhaul offers an expansive new world to explore. Navigate through challenging custom levels and hidden paths to stop Bowser''s latest scheme.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '3000 Leagues in Search of Bowser - Touhou Edition (English) (V2.54)', '2023', NaN, 'ROM Hack', '1', NaN, 'Platforming with Touhou-inspired characters and bullet-hell elements.', 'Complete the journey across the world to stop Bowser''s plot.', 'Play a unique Touhou crossover in 3000 Leagues in Search of Bowser.', 'This Touhou Edition hack merges anime-style characters with classic Mario platforming. Experience custom music, graphics, and high-difficulty gameplay on your SNES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '3x3 Eyes - Juuma Houkan (Japan)', '1992', NaN, 'Novia', '1', NaN, 'Turn-based RPG and adventure with supernatural horror themes.', 'Stop a demon invasion and protect the Sanjiyan''s immortality.', 'Explore a dark anime world in 3x3 Eyes - Juuma Houkan for SNES.', 'Based on the 3x3 Eyes manga, this title combines RPG exploration with an atmospheric story. Fight demons and solve puzzles to protect the secret of eternal life.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '3x3 Eyes - Seima Kourinden (Japan)', '1995', NaN, 'Novia', '1', NaN, 'Traditional turn-based JRPG with cinematic narrative sequences.', 'Travel across Asia to recover lost artifacts and protect Pai.', 'Follow the epic story of Yakumo and Pai in 3x3 Eyes for SNES.', 'A faithful RPG adaptation of the 3x3 Eyes series. Manage your party, master spells, and experience a deep storyline filled with ancient mysticism and demon battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '4 Nin Shougi (Japan)', '1995', NaN, 'SETA', '2', NaN, 'Strategic board game simulation of traditional Japanese chess.', 'Outmaneuver the opponent to capture their King.', 'Master the strategy of 4 Nin Shougi on the SNES.', 'Enjoy the classic game of Shogi with up to four players. 4 Nin Shougi provides a challenging AI and various modes for fans of Japanese strategic board games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '46 Okunen Monogatari - Harukanaru Eden e (Japan)', '1992', NaN, 'Almanic', '1', NaN, 'Evolutionary action-RPG where the player evolves through eras.', 'Evolve from a fish to a human to reach the Garden of Eden.', 'Shape your own evolution in 46 Okunen Monogatari for SNES.', 'Known as E.V.O.: Search for Eden, this unique RPG lets you customize your creature''s body as you struggle for survival across millions of years of history.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '7th Saga, The (USA)', '1993', NaN, 'Produce!', '1', NaN, 'Turn-based RPG with a unique radar system and high difficulty.', 'Collect the seven mystical runes to inherit the power of a god.', 'Experience the punishing challenge of The 7th Saga on SNES.', 'Select one of seven heroes and compete against the others in a race for the runes. The 7th Saga is famous for its steep difficulty and innovative combat radar.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '7th Saga, The (USA) [Hack by James Skarzinskas v1.0] (Elnard''s Balance Restauration)', '1993', NaN, 'ROM Hack', '1', NaN, 'Rebalanced turn-based RPG with restored Japanese difficulty stats.', 'Complete the quest for the runes with more fair gameplay.', 'Play the balanced version of The 7th Saga with this SNES hack.', 'This restoration hack adjusts the difficulty curve of The 7th Saga to match the original Japanese version, providing a more balanced and enjoyable RPG experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '7th Saga, The (USA) [Hack by Nati v1.0] (~7th Saga Redux)', '1993', NaN, 'ROM Hack', '1', NaN, 'Overhauled turn-based RPG with new mechanics and character tweaks.', 'Secure the seven runes in this refined version of the classic game.', 'Experience a fresh take on a classic with 7th Saga Redux for SNES.', '7th Saga Redux improves character viability and balance. Enjoy the same epic story with polished gameplay mechanics and updated difficulty scaling.', NULL);
