INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', '90 Minutes - European Prime Goal (Europe) (Beta)', '1992', NaN, 'Taito', '2', NaN, 'Early prototype of the soccer simulation with experimental features.', 'Test the soccer mechanics and win the experimental cup.', 'Explore a piece of gaming history with the 90 Minutes Beta.', 'This beta version of 90 Minutes - European Prime Goal offers a look at the game''s development, featuring early builds of the mechanics and team rosters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'A Journey To Save The Yoshis by Yoshivert99', '2022', NaN, 'Homebrew', '1', NaN, 'Creative platformer featuring custom mechanics for Yoshi.', 'Navigate through custom worlds to rescue the Yoshi clan.', 'Explore a new Yoshi adventure in A Journey To Save The Yoshis.', 'A vibrant and creative hack of Super Mario World starring Yoshi. Use unique power-ups and clever level design to save your friends in this community favorite.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'A Link to the Past: Kaizo Edition', '2021', NaN, 'ROM Hack', '1', NaN, 'Extremely difficult puzzle-platformer built on the Zelda engine.', 'Complete the lethal dungeons and rescue Princess Zelda.', 'Test your limits in A Link to the Past: Kaizo Edition.', 'This is not the Hyrule you remember. Kaizo Edition turns Zelda into a brutal gauntlet of traps and precision puzzles that will challenge the most veteran players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'AAAHH!!! Real Monsters (Europe)', '1995', NaN, 'Realtime Associates', '2', NaN, 'Platformer where players switch between three monsters with unique abilities.', 'Complete the monster scare assignments to pass the Academy exams.', 'Scare humans and solve puzzles in AAAHH!!! Real Monsters for SNES.', 'Based on the Nickelodeon hit, control Ickis, Krumm, and Oblina. Use their combined teamwork and gross-out scares to navigate through trash heaps and human cities in this 16-bit platformer.', NULL);
