INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'ABC Monday Night Football (Japan)', '1993', NaN, 'Data East', '2', NaN, 'Arcade-style American football simulation with high-energy presentation.', 'Win the Super Bowl by leading your team through the Monday Night season.', 'Experience 16-bit gridiron action in ABC Monday Night Football for SNES.', 'Featuring the official ABC license, this football title offers fast-paced gameplay, multiple formations, and the excitement of prime-time sports broadcasting on your Super Nintendo.', NULL);
