INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Accele Brid (Japan)', '1992', NaN, 'Naxat Soft', '1', NaN, 'A futuristic behind-the-back racing game combined with robot combat.', 'Defeat opponents in high-speed races and combat to win the championship.', 'Battle and race in the futuristic world of Accele Brid on SNES.', 'A unique hybrid of racing and shooter. Control a giant mecha through 3D tunnels, upgrading your weapons and speed to overcome rivals in this Japanese cult classic.', NULL);
