INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ace o Nerae! (Japan)', '1993', NaN, 'Taito', '2', NaN, 'Anime-style tennis simulation with story elements and special moves.', 'Rise through the ranks to become a world-class tennis champion.', 'Experience anime-style sports in Ace o Nerae! for the Super Famicom.', 'Based on the famous Aim for the Ace! manga. This tennis game features cinematic shots, dramatic story beats, and deep tennis mechanics that capture the spirit of the series.', NULL);
