INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Acrobat Mission (Japan)', '1992', NaN, 'Ukiyotei', '1', NaN, 'Vertical-scrolling shoot ''em up with a unique weapon-stealing mechanic.', 'Fly through enemy lines and destroy the bio-mechanical invaders.', 'Battle through space in the intense shooter Acrobat Mission on SNES.', 'A classic arcade port featuring a risk-reward system where your ship can cause massive damage when destroyed. Navigate through challenging levels and epic boss fights.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Action Pachio (Japan)', '1994', NaN, 'Namco', '1', NaN, 'Side-scrolling platformer starring a mascot character with high agility.', 'Navigate through colorful levels to stop the corporate villain.', 'Enjoy fast-paced 16-bit platforming with Action Pachio on SNES.', 'A hidden gem from the creators of Umihara Kawase. Play as a small mechanical hero with unique physics, exploring vibrant worlds filled with secrets and tight controls.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'ActRaiser (Europe)', '1993', NaN, 'Quintet', '1', NaN, 'A unique blend of city-building simulation and side-scrolling action.', 'Rebuild civilization as a god and defeat the evil Tanzra.', 'Play the legendary god-sim and action hybrid ActRaiser on SNES.', 'Assume the role of The Master. Alternate between overhead city management to help your followers and intense platforming combat to purge the land of demons.', NULL);
