INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Addams Family Values (Europe) (En,Fr,De)', '1995', NaN, 'Ocean Software', '1', NaN, 'Action-adventure game with an overhead perspective and puzzle elements.', 'Explore the world to find and rescue the kidnapped baby Pubert.', 'Join the spooky family in Addams Family Values for the SNES.', 'Based on the sequel film, play as Uncle Fester in a vast, interconnected world. Use different weapons and items to solve puzzles, talk to family members, and defeat bosses.', NULL);
