INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Adventures of Batman & Robin, The (Europe)', '1995', NaN, 'Clockwork Tortoise', '1', NaN, 'Cinematic action-platformer with high-quality 16-bit graphics and gadgets.', 'Defeat the iconic villains of Gotham City and stop the Joker''s latest plot.', 'Experience the best Batman action in The Adventures of Batman & Robin for SNES.', 'Widely considered one of the best licensed games on the system, this title features incredible visuals and varied levels based on the animated series. Use Batarangs and gadgets to take down Gotham''s worst.', NULL);
