INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Adventures of Kid Kleets, The (USA) (En,Fr,Es)', '1994', NaN, 'Radical Entertainment', '1', NaN, 'Soccer-themed action platformer where the player uses a ball to attack.', 'Defeat enemies and navigate obstacles to win the world soccer trophy.', 'Kick off an adventure in Adventures of Kid Kleets for the SNES.', 'Known in Europe as Soccer Kid, this creative platformer tasks you with using a soccer ball as your primary weapon and tool for movement across various international stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Adventures of Rocky and Bullwinkle and Friends, The (USA)', '1993', NaN, 'Radical Entertainment', '1', NaN, 'Multi-style action game featuring platforming, flying, and mini-games.', 'Stop Boris and Natasha from stealing the world''s artifacts.', 'Enjoy classic cartoon fun in The Adventures of Rocky and Bullwinkle on SNES.', 'Play as the famous moose and squirrel duo. Tackle various levels inspired by the cartoon show, featuring unique gameplay segments for both Rocky and Bullwinkle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Adventures of Tintin, The - Prisoners of the Sun (Europe) (En,Fr,De,Es)', '1996', NaN, 'Infogrames', '1', NaN, 'Side-scrolling action adventure based on the famous Hergé comic series.', 'Rescue Professor Calculus and uncover the secrets of the Sun Temple.', 'Experience the mystery of Tintin: Prisoners of the Sun on SNES.', 'A faithful recreation of the Tintin universe. Help Tintin and Captain Haddock navigate dangerous environments in Peru, solving puzzles and avoiding traps in this atmospheric adventure.', NULL);
