INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aero Fighters (USA)', '1992', NaN, 'Video System', '2', NaN, 'Vertical-scrolling shoot ''em up with multiple selectable pilots and planes.', 'Defeat the alien invasion across various global territories.', 'Take to the skies in Aero Fighters, an intense SNES arcade shooter.', 'Choose from four different nations and pilots, each with unique weapon systems. Engage in fast-paced aerial combat and massive boss battles in this acclaimed SHMUP.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aero the Acro-Bat (Europe)', '1993', NaN, 'Iguana Entertainment', '1', NaN, 'Fast-paced acrobatic platformer featuring a circus bat protagonist.', 'Stop the evil industrialist Edgar Ektor from destroying the circus.', 'Experience circus-themed action in Aero the Acro-Bat for SNES.', 'Play as Aero, using his signature drill attack and gliding abilities. Navigate through circus-inspired levels filled with spikes, cannons, and dangerous stunts.', NULL);
