INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aero the Acro-Bat 2 (Europe)', '1994', NaN, 'Iguana Entertainment', '1', NaN, 'Polished action platformer with improved controls and darker themes.', 'Chase Edgar Ektor to his secret base and stop his evil plans once and for all.', 'Soar higher in Aero the Acro-Bat 2, the refined SNES sequel.', 'The sequel improves on every aspect of the original. Aero returns with new moves and longer levels, featuring some of the most fluid platforming mechanics on the Super Nintendo.', NULL);
