INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Akazukin Chacha (Japan)', '1994', NaN, 'Now Production', '1', NaN, 'Turn-based RPG with magical girl themes and puzzle-solving.', 'Follow Chacha and her friends to defeat the Demon King.', 'Experience the magical world of Akazukin Chacha on SNES.', 'Based on the popular anime, this RPG features a unique battle system and charming story beats. Help Chacha, Riiya, and Shiine use their magical powers to save their world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Akumajou Dracula (Japan)', '1991', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer with gothic horror atmosphere and whip combat.', 'Navigate Dracula''s castle to defeat the Prince of Darkness.', 'Play the legendary Akumajou Dracula (Super Castlevania IV) on SNES.', 'Wield the legendary whip as Simon Belmont. This title features 8-way whipping mechanics, incredible Mode 7 effects, and one of the best soundtracks in the 16-bit era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Akumajou Dracula XX (Japan)', '1995', NaN, 'Konami', '1', NaN, 'Hardcore side-scrolling action platformer with branching paths and hidden secrets.', 'Rescue Maria and Annette and defeat Dracula in his castle.', 'Challenge yourself in Akumajou Dracula XX, a classic SNES horror quest.', 'Known in the West as Castlevania: Dracula X, this title offers intense difficulty, stunning sprite work, and multiple endings based on who you rescue during your journey.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Al Unser Jr.''s Road to the Top (Europe)', '1994', NaN, 'Leland Interactive Media', '1', NaN, 'Racing game featuring go-karts, snowmobiles, IROC cars, and Indy cars.', 'Master four different vehicle types to become the ultimate racing champion.', 'Race to victory in Al Unser Jr.''s Road to the Top for SNES.', 'Progress through different racing disciplines. Start with go-karts and work your way up to professional Indy cars in this varied and challenging racing simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Al Unser Jr.''s Road to the Top (USA)', '1994', NaN, 'Leland Interactive Media', '1', NaN, 'Racing game featuring go-karts, snowmobiles, IROC cars, and Indy cars.', 'Master four different vehicle types to become the ultimate racing champion.', 'Race to victory in Al Unser Jr.''s Road to the Top for SNES.', 'Progress through different racing disciplines. Start with go-karts and work your way up to professional Indy cars in this varied and challenging racing simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aladdin (Europe)', '1993', NaN, 'Capcom', '1', NaN, 'Fast-paced action platformer with fluid animation and sword/apple combat.', 'Navigate Agrabah to win the heart of Jasmine and defeat Jafar.', 'Experience the magic of Disney''s Aladdin, a masterpiece for SNES.', 'Widely praised for its smooth controls and vibrant graphics, help Aladdin navigate the Cave of Wonders and the streets of Agrabah in this definitive 16-bit platformer.', NULL);
