INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aladdin 2000', '2000', NaN, 'Unlicensed', '1', NaN, 'Unknown', 'Unknown', 'Explore the mysterious Aladdin 2000 title for SNES.', 'Likely an unlicensed or pirate port, this title attempts to bring a different version of the Aladdin story to the 16-bit hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Albert Odyssey (Japan)', '1993', NaN, 'Sunsoft', '1', NaN, 'Traditional turn-based RPG with a tactical battle system.', 'Embark on a quest to save the world from an emerging evil force.', 'Dive into the classic JRPG adventure of Albert Odyssey on SNES.', 'Featuring beautiful sprite work and a strategic grid-based combat system, Albert Odyssey is a hidden gem for fans of 16-bit role-playing games and epic stories.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Albert Odyssey 2 - Jashin no Taidou (Japan)', '1994', NaN, 'Sunsoft', '1', NaN, 'Traditional turn-based RPG with a tactical battle system and deeper story.', 'Stop the resurrection of an evil god and restore peace to the land.', 'Continue the epic journey in Albert Odyssey 2 for the SNES.', 'The sequel expands on the tactical combat and narrative of the first game, offering more complex battles and a rich world to explore for JRPG enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Alcahest (Japan)', '1993', NaN, 'HAL Laboratory', '1', NaN, 'Top-down action-adventure game with fast-paced real-time combat.', 'Journey across the land to collect the four elemental swords and defeat the demon.', 'Experience the intense action of Alcahest, a HAL Laboratory classic for SNES.', 'Produced by Satoru Iwata, this game plays like a faster-paced Zelda with more emphasis on combat. Navigate challenging dungeons and defeat massive bosses in this cult classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Alcahest (Japan) [En by FH v1.0Beta]', '1993', NaN, 'HAL Laboratory', '1', NaN, 'Top-down action-adventure game with fast-paced real-time combat.', 'Journey across the land to collect the four elemental swords and defeat the demon.', 'Play the English translation of Alcahest, the SNES action gem.', 'Now fully playable in English, follow the story of Alen as he battles through a high-fantasy world in this incredible real-time action-adventure game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Alfred Chicken (Europe)', '1994', NaN, 'Twilight Games', '1', NaN, 'Side-scrolling platformer starring a quirky chicken with various abilities.', 'Rescue your fellow chickens and defeat the robotic invaders.', 'Join the wacky adventure in Alfred Chicken for the SNES.', 'Play as a brave chicken who can peck, bounce, and find hidden areas. This colorful platformer is filled with puzzles and secret items across multiple themed worlds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Alice no Paint Adventure (Japan)', '1992', NaN, 'HAL Laboratory', '1', NaN, 'Educational digital painting and adventure game based on the classic story.', 'Complete various mini-games and coloring activities in Wonderland.', 'Get creative with Alice no Paint Adventure for the SNES.', 'This unique title combines the Alice in Wonderland story with creative tools, allowing players to paint scenes and interact with characters in an educational setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Alien 3 (Europe)', '1992', NaN, 'Probe Entertainment', '1', NaN, 'Side-scrolling action platformer with exploration and mission-based objectives.', 'Complete tasks like rescuing prisoners and clearing nests on Fiorina 161.', 'Survive the horror of Alien 3, the intense action game for SNES.', 'Unlike other versions, the SNES game features a non-linear mission structure. Use flamethrowers and pulse rifles to navigate the prison planet and survive the Xenomorph threat.', NULL);
