INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'All-American Championship Football (Europe)', '1993', NaN, 'SEGA', '2', NaN, 'American football simulation with league and tournament modes.', 'Win the championship by leading your football team to the top of the league.', 'Experience 16-bit gridiron action in All-American Championship Football.', 'A solid American football title for the SNES featuring various formations, team management, and competitive gameplay for sports enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'All-Stars SMB2 in SMB1 & SMB1 in SMB3', '2021', NaN, 'ROM Hack', '1', NaN, 'Platformer compilation or engine swap featuring classic Mario levels.', 'Navigate through various Mario worlds and defeat Bowser in different styles.', 'Play the unique Mario engine swap All-Stars SMB2 in SMB1.', 'This interesting ROM hack or compilation swaps engines between classic Super Mario games, offering a fresh way to play iconic 8-bit levels with 16-bit graphics and physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Amazing Spider-Man, The - Lethal Foes (Japan)', '1995', NaN, 'Sega', '1', NaN, 'Side-scrolling action platformer featuring Spider-Man''s powers and gadgets.', 'Defeat the Lethal Foes and stop their criminal organization in New York.', 'Swing into action with Spider-Man: Lethal Foes on the SNES.', 'A Japan-exclusive Marvel title featuring high-quality sprite work and cameos from various Marvel heroes and villains. Use web-swinging and wall-crawling to stop the city''s greatest threats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'America Oudan Ultra Quiz (Japan)', '1991', NaN, 'Game Studio', '1', NaN, 'Trivia-based quiz game based on the popular Japanese TV show.', 'Answer questions correctly to travel across America and win the grand prize.', 'Test your knowledge in America Oudan Ultra Quiz for SNES.', 'Experience the high-stakes world of Japanese TV trivia. Compete in various rounds across different US locations in this unique 16-bit quiz simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'American Battle Dome (Japan)', '1992', NaN, 'Takara', '2', NaN, 'Futuristic 4-player pinball battle game with competitive elements.', 'Score the most points and outlast opponents in a high-speed pinball arena.', 'Experience chaotic pinball action in American Battle Dome for SNES.', 'A unique take on pinball where players compete simultaneously on the same board. Fast-paced, colorful, and highly competitive, it''s a great multiplayer gem.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'American Gladiators (USA)', '1993', NaN, 'Sales Curve Interactive', '2', NaN, 'Action-sports simulation based on the hit physical competition TV show.', 'Complete various athletic challenges and defeat the Gladiators in the Eliminator.', 'Become a contender in American Gladiators for the SNES.', 'Featuring classic events like Joust, Assault, and the Wall. Test your timing and reflexes against the show''s iconic athletes in this 16-bit recreation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'American Tail, An - Fievel Goes West (Europe)', '1994', NaN, 'MotiveTime', '1', NaN, 'Side-scrolling platformer with cowboy themes and exploration.', 'Navigate the Wild West and find Fievel''s family while avoiding Cat R. Waul.', 'Join Fievel''s Western adventure in An American Tail for SNES.', 'Based on the animated film, help Fievel jump, climb, and shoot bubble pop guns through various levels inspired by the movie''s desert and town settings.', NULL);
