INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Andre Agassi Tennis (Japan)', '1992', NaN, 'Taito', '2', NaN, 'Tennis simulation with multiple court surfaces and tournament modes.', 'Win the Grand Slam tournaments and become the world''s top-ranked player.', 'Play professional 16-bit tennis in Andre Agassi Tennis for SNES.', 'Featuring the legendary player, this game offers realistic tennis physics, various stroke types, and a deep career mode for fans of the sport.', NULL);
