INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Angelique - Premium Box (Japan)', '1994', NaN, 'Koei', '1', NaN, 'Otomé dating simulation and strategy with fantasy elements.', 'Balance your duties as a candidate for Queen while building relationships.', 'Experience the first Otomé game in Angelique - Premium Box for SNES.', 'A luxury edition of the classic romance sim. Interact with various guardians and manage your planetary development in this pioneering title of the genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Angelique - Voice Fantasy (Japan)', '1995', NaN, 'Koei', '1', NaN, 'Otomé dating simulation enhanced with voice-acting features.', 'Win the favor of the Guardians and become the next Queen of the universe.', 'Enjoy the expanded Angelique - Voice Fantasy experience on SNES.', 'This version utilizes special hardware or techniques to provide voice acting, enhancing the narrative and romance elements of the original Angelique story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Angelique (Japan)', '1994', NaN, 'Koei', '1', NaN, 'The original Otomé dating simulation and planetary management game.', 'Grow your assigned continent and build bonds with the elemental Guardians.', 'Play the original Angelique, the pioneer of Otomé games on SNES.', 'A blend of social simulation and light strategy. Choose your path, interact with characters, and manage resources to prove your worthiness for the throne.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Angelique English', '1994', NaN, 'Koei', '1', NaN, 'Otomé dating simulation and strategy, translated for English speakers.', 'Compete to become the Queen while developing romances in English.', 'Play the English translation of Angelique on the SNES.', 'The classic romance and strategy hybrid is now accessible to a wider audience. Manage your world and your heart in this landmark Japanese title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Animal Buranden - Brutal (Japan)', '1992', NaN, 'Jaleco', '2', NaN, 'Fighting game with anthropomorphic animal characters and brutal moves.', 'Defeat all animal rivals in a tournament of ultimate biological strength.', 'Unleash your wild side in Animal Buranden - Brutal for SNES.', 'A colorful 16-bit fighter featuring diverse animal warriors. Master unique combos and special moves in this high-energy martial arts contest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Animaniacs (Europe)', '1994', NaN, 'Konami', '2', NaN, 'Multi-style action game with platforming, puzzles, and mini-games.', 'Complete various tasks on the movie studio lot to stop Thaddeus Plotz.', 'Join the Warner brothers (and sister) in Animaniacs for SNES.', 'Control Yakko, Wakko, and Dot as they switch between unique abilities to solve puzzles and navigate the Warner Bros. studio in this vibrant licensed title.', NULL);
