INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Another World (Europe)', '1992', NaN, 'Delphine Software', '1', NaN, 'Cinematic action-adventure with rotoscoped animation and logic puzzles.', 'Survive a dangerous alien world and find a way back home.', 'Experience the cinematic masterpiece Another World on SNES.', 'Also known as Out of This World, this game features minimalist storytelling and intense trial-and-error gameplay in a beautifully realized alien landscape.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aoki Densetsu Shoot! (Japan)', '1994', NaN, 'KCE Tokyo', '2', NaN, 'Soccer simulation based on the popular manga and anime series.', 'Lead your team to victory in the national championships using special moves.', 'Play anime-style soccer in Aoki Densetsu Shoot! for SNES.', 'Experience the drama of the Shoot! series. Execute powerful signature shots and follow the narrative of Toshi and his teammates in this 16-bit sports title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Apocalypse II (Europe) (Proto)', '1994', NaN, 'Unknown', '1', NaN, 'Side-scrolling shooter with high-tech weaponry and vehicle segments.', 'Stop a global terrorist threat and prevent a nuclear apocalypse.', 'Play the unreleased prototype Apocalypse II on the SNES.', 'A fast-paced action game that never saw a final release. Features intense shooting mechanics and large-scale explosions in a futuristic setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Appleseed - Prometheus no Shintaku (Japan)', '1994', NaN, 'SEGA', '1', NaN, 'Side-scrolling action-adventure based on the cyberpunk manga.', 'Navigate through high-tech environments to stop a terrorist conspiracy.', 'Enter the world of Appleseed - Prometheus no Shintaku on SNES.', 'Control Deunan Knute in this atmospheric cyberpunk title. Featuring platforming, combat, and mecha segments based on Masamune Shirow''s iconic series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aqutallion (Japan)', '1995', NaN, 'Technosoft', '1', NaN, 'Traditional turn-based JRPG with a focus on elemental magic and adventure.', 'Travel the world to stop an ancient evil from awakening.', 'Explore the magical world of Aqutallion (Tecmo Secret of the Stars) on SNES.', 'Features two separate parties of heroes whose stories eventually intertwine. A classic JRPG experience with unique magic systems and a vast world to explore.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Arabian Nights - Sabaku no Seirei Ou (English v1.0)', '1993', NaN, 'Culture Brain', '1', NaN, 'Turn-based RPG with an Arabian Nights setting and card-based mechanics.', 'Navigate a world of genies and desert mystery to defeat the Spirit King.', 'Play the English translation of Arabian Nights for SNES.', 'A beautifully crafted JRPG featuring a unique day/night system and card combat. Follow the story of a girl and her genie protector in this desert epic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Arabian Nights - Sabaku no Seirei Ou (Japan)', '1993', NaN, 'Culture Brain', '1', NaN, 'Turn-based RPG with an Arabian Nights setting and card-based mechanics.', 'Navigate a world of genies and desert mystery to defeat the Spirit King.', 'Experience the desert mystery of Arabian Nights on SNES.', 'A beautifully crafted JRPG featuring a unique day/night system and card combat. Follow the story of a girl and her genie protector in this desert epic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Araiguma Rascal (Japan)', '1994', NaN, 'Nippon Animation', '1', NaN, 'Action platformer and puzzle game featuring the famous raccoon character.', 'Navigate through beautiful hand-drawn levels to collect items and reach home.', 'Join the cute adventures of Araiguma Rascal on the SNES.', 'Based on the popular anime, this title features charming graphics and relaxing gameplay, perfect for younger players and fans of the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Arcade''s Greatest Hits - The Atari Collection 1 (Europe)', '1995', NaN, 'Digital Eclipse', '2', NaN, 'Compilation of classic arcade games from the Atari era.', 'Achieve high scores in legendary titles like Asteroids, Centipede, and Missile Command.', 'Play the classics with Arcade''s Greatest Hits: Atari Collection 1 on SNES.', 'A perfect preservation of arcade history. Includes pixel-perfect ports of iconic games that defined the early era of video gaming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Arcade''s Greatest Hits - The Atari Collection 1 (USA)', '1995', NaN, 'Digital Eclipse', '2', NaN, 'Compilation of classic arcade games from the Atari era.', 'Achieve high scores in legendary titles like Asteroids, Centipede, and Missile Command.', 'Play the classics with Arcade''s Greatest Hits: Atari Collection 1 on SNES.', 'A perfect preservation of arcade history. Includes pixel-perfect ports of iconic games that defined the early era of video gaming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Arcana (USA)', '1992', NaN, 'HAL Laboratory', '1', NaN, 'First-person dungeon crawler with turn-based card-themed combat.', 'Explore the tower of Galia to defeat the evil empress and restore peace.', 'Master card-based combat in Arcana, a unique SNES RPG.', 'A distinct JRPG that uses cards for its visuals and combat system. Navigate large 3D-style dungeons and manage your party of elemental spirits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Arcus Odyssey (USA) (Proto)', '1992', NaN, 'Wolf Team', '1', NaN, 'Top-down action RPG with multiple playable characters and cooperative play.', 'Defeat the dark wizards and protect the sacred land of Arcus.', 'Experience the action-packed Arcus Odyssey prototype on SNES.', 'Known for its fast-paced combat and diverse character choices. Each hero offers a different gameplay style in this intense fantasy adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Arcus Spirits (Japan)', '1991', NaN, 'Wolf Team', '1', NaN, 'Isometric action-adventure with tactical combat and exploration.', 'Navigate dangerous dungeons and defeat mythological creatures to save the land.', 'Master isometric action in Arcus Spirits for the SNES.', 'A refined version of the Arcus formula, featuring challenging enemies, intricate level designs, and beautiful 16-bit fantasy aesthetics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ardy Lightfoot (Europe)', '1993', NaN, 'Irem', '1', NaN, 'Side-scrolling action platformer with a unique companion mechanic.', 'Find the seven rainbow colored stones to save the world from an evil king.', 'Join the epic adventure of Ardy Lightfoot on the SNES.', 'Ardy is joined by his pal Pec, who can be used as a weapon or a tool. This game features incredibly detailed animation and a charming, story-rich world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ardy Lightfoot (Japan)', '1993', NaN, 'Irem', '1', NaN, 'Side-scrolling platformer with a unique companion-based combat system.', 'Collect the shattered pieces of a rainbow crystal to defeat the evil King Visconti.', 'Join Ardy and his pal Pec in the charming SNES platformer Ardy Lightfoot.', 'Control Ardy and use your creature companion, Pec, as a multi-purpose tool and weapon. Explore a beautifully animated world filled with creative boss fights and diverse environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ardy Lightfoot (Japan) (Beta)', '1993', NaN, 'Irem', '1', NaN, 'Side-scrolling platformer with a unique companion-based combat system.', 'Collect the shattered pieces of a rainbow crystal to defeat the evil King Visconti.', 'Explore the early development of Ardy Lightfoot in this SNES Beta.', 'A pre-release version of Ardy Lightfoot featuring minor differences in level layout and mechanics. Experience the core platforming action as it was during the development phase.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ardy Lightfoot (USA)', '1993', NaN, 'Irem', '1', NaN, 'Side-scrolling platformer with a unique companion-based combat system.', 'Collect the shattered pieces of a rainbow crystal to defeat the evil King Visconti.', 'Join Ardy and his pal Pec in the charming SNES platformer Ardy Lightfoot.', 'Control Ardy and use your creature companion, Pec, as a multi-purpose tool and weapon. Explore a beautifully animated world filled with creative boss fights and diverse environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Area 88 (Japan)', '1991', NaN, 'Capcom', '1', NaN, 'Side-scrolling shoot ''em up with a mercenary pilot theme and upgradeable jets.', 'Complete aerial missions and destroy the enemy base to end the war.', 'Fly intense mercenary missions in Area 88 (UN Squadron) for the SNES.', 'Choose your pilot and customize your jet with various weapons. Navigate through challenging aerial stages and engage in massive boss battles in this acclaimed Capcom shooter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aretha (Japan)', '1993', NaN, 'Japan Art Media', '1', NaN, 'Traditional turn-based RPG with a focus on exploration and magic.', 'Embark on a journey to find the lost treasures of Aretha and save the kingdom.', 'Experience the classic JRPG adventure of Aretha on the SNES.', 'Guide Ariel through a vast fantasy world. Manage your party, master powerful spells, and engage in classic 16-bit turn-based combat to uncover the secrets of the Aretha lineage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aretha II - Ariel no Fushigi na Tabi (Japan)', '1994', NaN, 'Japan Art Media', '1', NaN, 'Traditional turn-based RPG featuring a female protagonist and deeper narrative.', 'Travel across the land to stop an ancient evil from threatening the world of Aretha.', 'Continue the epic RPG journey in Aretha II for the SNES.', 'The sequel expands on the original''s mechanics with improved graphics and a more complex story. Follow Ariel and her companions as they face new challenges in this expansive JRPG.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aretha II - Ariel no Fushigi na Tabi (Japan) (Beta1)', '1994', NaN, 'Japan Art Media', '1', NaN, 'Traditional turn-based RPG featuring a female protagonist and deeper narrative.', 'Travel across the land to stop an ancient evil from threatening the world of Aretha.', 'Explore the development of Aretha II with this SNES Beta version.', 'An early look at the second entry in the Aretha series. Test the combat systems and explore early builds of the game''s fantasy environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Aretha II - Ariel no Fushigi na Tabi (Japan) (Beta2)', '1994', NaN, 'Japan Art Media', '1', NaN, 'Traditional turn-based RPG featuring a female protagonist and deeper narrative.', 'Travel across the land to stop an ancient evil from threatening the world of Aretha.', 'Explore the development of Aretha II with this SNES Beta version.', 'A secondary pre-release build of Aretha II, offering further insights into the game''s development and refined RPG mechanics before the final release.', NULL);
