INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Asahi Shinbun Rensai - Katou Hifumi Kudan Shougi - Shingiryuu (Japan)', '1994', NaN, 'Hect', '2', NaN, 'Traditional Japanese Shogi simulation with multiple difficulty levels.', 'Outsmart the AI or a second player in the strategic game of Japanese chess.', 'Master Shogi strategy in Katou Hifumi Kudan Shougi for SNES.', 'Endorsed by the legendary Shogi player Hifumi Katou, this game offers a deep and challenging simulation of the traditional board game for strategy enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Asameshimae Nyanko (Japan)', '1992', NaN, 'Namco', '1', NaN, 'Quirky board game or puzzle title featuring cat characters.', 'Compete against other players or the AI in feline-themed challenges.', 'Enjoy the quirky feline fun of Asameshimae Nyanko on SNES.', 'A charming and lighthearted Japanese title where players control various cat characters in a series of competitive mini-games and board game segments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ashita no Joe (Japan)', '1992', NaN, 'Wave', '1', NaN, 'Boxing simulation based on the legendary manga and anime series.', 'Train Joe Yabuki and lead him to the world boxing championship.', 'Box your way to the top in Ashita no Joe for the SNES.', 'Experience the story of Joe Yabuki. Use strategic movement and powerful punches to defeat iconic rivals like Rikiishi in this 16-bit boxing tribute.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ashita no Joe (Japan) [En by Vice v0.99] (~Tomorrow''s Joe)', '1992', NaN, 'Wave', '1', NaN, 'Boxing simulation based on the legendary manga and anime series.', 'Train Joe Yabuki and lead him to the world boxing championship.', 'Play Ashita no Joe in English with this SNES fan translation.', 'Now accessible to English-speaking fans, follow Joe''s dramatic journey through the boxing world with fully translated menus and story sequences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Assault Suits Valken (Japan)', '1993', NaN, 'Sammy', '1', NaN, 'Side-scrolling mecha action with destructible environments and jetpack movement.', 'Navigate through space and enemy colonies to stop a global insurrection.', 'Pilot a powerful mecha in the classic Assault Suits Valken for SNES.', 'Known in the West as Cybernator, this original version features incredible mechanical detail, deep weapon systems, and a mature story focused on futuristic warfare.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Assault Suits Valken (Japan) [En by Aeon Genesis v1.0]', '1993', NaN, 'Sammy', '1', NaN, 'Side-scrolling mecha action with destructible environments and jetpack movement.', 'Navigate through space and enemy colonies to stop a global insurrection.', 'Play the English translation of Assault Suits Valken on SNES.', 'This fan translation restores the story elements and names that were altered in the Western release of Cybernator, providing the definitive 16-bit mecha experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Asterix (Europe) (En,Fr,De,Es)', '1993', NaN, 'Infogrames', '2', NaN, 'Side-scrolling action platformer based on the famous French comic series.', 'Navigate through various levels to find a cure for Getafix the druid.', 'Join Asterix in his classic 16-bit platforming adventure on SNES.', 'Explore a colorful world inspired by the comics. Use Asterix''s strength and speed to defeat Roman legions and navigate various European environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Asterix & Obelix (Europe) (En,Fr,De,Es)', '1995', NaN, 'Infogrames', '2', NaN, 'Cooperative action platformer where players control both Asterix and Obelix.', 'Journey across the Roman Empire to prove the Gauls'' supremacy.', 'Team up in the Asterix & Obelix platformer for the SNES.', 'A vibrant and fun multiplayer experience. Use Asterix''s agility or Obelix''s brute force to tackle Romans and reach the end of the Roman-controlled world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Atlas, The - Renaissance Voyager (Japan)', '1994', NaN, 'Koei', '1', NaN, 'Deep historical simulation focused on exploration and cartography.', 'Navigate the globe to map the world and discover new trade routes.', 'Explore and map the world in The Atlas: Renaissance Voyager for SNES.', 'A unique strategy game set during the Age of Discovery. Manage your fleet, hire explorers, and verify the shape of the world based on the reports you receive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Axelay (Europe)', '1992', NaN, 'Konami', '2', NaN, 'Dual-perspective shoot ''em up with both vertical and side-scrolling stages.', 'Protect the solar system from the alien armada of the Illis Empire.', 'Experience the legendary 16-bit shooter Axelay on the SNES.', 'Axelay is a technical marvel on the SNES, utilizing Mode 7 effects for its vertical stages. Choose your weapon loadout strategically to survive intense aerial combat and massive screen-filling bosses.', NULL);
