INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ayrton Senna Racing (Nigel Mansell''s Racing Hack)', '1994', NaN, 'ROM Hack', '1', NaN, 'Formula One racing simulation with realistic physics and track designs.', 'Win the World Championship by mastering high-speed F1 circuits.', 'Race as a legend in the Ayrton Senna Racing hack for SNES.', 'A fan-made modification of Nigel Mansell''s World Championship Racing that pays tribute to Ayrton Senna. Experience refined F1 racing with updated graphics and performance to honor the Brazilian champion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'B.O.B. (Europe)', '1995', NaN, 'Gray Matter', '1', NaN, 'Side-scrolling action platformer with an emphasis on various projectile weapons.', 'Navigate through dangerous alien planets to reach your date on time.', 'Blast through enemies in the sci-fi adventure B.O.B. for SNES.', 'Play as a teenage robot stranded on an asteroid. Use a wide array of specialized guns and gadgets to solve environmental puzzles and defeat waves of hostile aliens in this quirky platformer.', NULL);
