INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bahamut Lagoon (Japan)', '1996', NaN, 'Square', '1', NaN, 'Tactical turn-based RPG featuring dragon breeding and squad-based combat.', 'Lead the resistance to free the kingdom of Orelus from the Granbelos Empire.', 'Master dragon tactics in the epic Bahamut Lagoon for SNES.', 'A Squaresoft masterpiece that combines grid-based strategy with RPG elements. Feed and evolve your dragons to change their abilities and support your human squads in massive, beautiful 16-bit battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bahamut Lagoon (Japan) [En by DeJap+Neill Corlett+Tomato v1.3] (Emulator Edition)', '1996', NaN, 'Square', '1', NaN, 'Tactical turn-based RPG featuring dragon breeding and squad-based combat.', 'Lead the resistance to free the kingdom of Orelus from the Granbelos Empire.', 'Play the English translation of Bahamut Lagoon on your SNES emulator.', 'Experience the full story of Bahamut Lagoon in English. This version is optimized for emulators, ensuring the complex script and tactical menus are perfectly readable for Western players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bahamut Lagoon (Japan) [En by DeJap+Neill Corlett+Tomato v1.3] (Real Hardware Edition)', '1996', NaN, 'Square', '1', NaN, 'Tactical turn-based RPG featuring dragon breeding and squad-based combat.', 'Lead the resistance to free the kingdom of Orelus from the Granbelos Empire.', 'Bahamut Lagoon English translation optimized for real SNES hardware.', 'A specialized version of the fan translation designed to run flawlessly on original consoles and flash carts. Enjoy this deep tactical RPG with its full narrative restored in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Baken Renkinjutsu (Japan)', '1993', NaN, 'NCS', '1', NaN, 'Horse racing simulation and management game.', 'Bet on winning horses and manage your gambling funds to become wealthy.', 'Test your luck in the Japanese horse racing sim Baken Renkinjutsu for SNES.', 'Focusing on the statistical side of horse racing, this title allows players to analyze data, place bets, and experience the tension of the racetrack through a 16-bit interface.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bakukyuu Renpatsu!! Super B-Daman (Japan)', '1995', NaN, 'Takara', '2', NaN, 'Top-down action game based on the popular marble-shooting toy line.', 'Defeat opponents in various B-Daman arenas to win the championship.', 'Battle with marbles in Bakukyuu Renpatsu!! Super B-Daman for SNES.', 'Based on the classic hobby, this game features fast-paced arcade action. Master your aim and firing speed to clear obstacles and knock out rivals in competitive marble-blasting tournaments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bakumatsu Kourinden Oni (Japan)', '1994', NaN, 'Atelier Double', '1', NaN, 'Traditional turn-based RPG set in historical Japan with supernatural elements.', 'Explore a mythological version of the Bakumatsu era to defeat ancient demons.', 'Dive into the supernatural RPG Bakumatsu Kourinden Oni for SNES.', 'Part of the Oni series, this JRPG blends Japanese history with folklore. Manage a party of heroes with unique spiritual abilities to combat monsters in a beautifully rendered 16-bit Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bakutou Dochers - Bumps-jima wa Oosawagi (Japan)', '1993', NaN, 'Compile', '2', NaN, 'Isometric action game with puzzle elements and competitive combat.', 'Navigate island stages and knock opponents off the platform to win.', 'Enjoy chaotic isometric action in Bakutou Dochers for the SNES.', 'A quirky Japanese title where players control round, bouncy characters. Use environmental hazards and character abilities to dominate the arena in this colorful and fast-paced multiplayer-focused game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ball Bullet Gun (Japan)', '1992', NaN, 'Namco', '1', NaN, 'Isometric tactical strategy game focused on airsoft-style military combat.', 'Lead your squad to victory in various tactical skirmish scenarios.', 'Master tactical airsoft combat in Ball Bullet Gun for the SNES.', 'A unique strategy game that simulates airsoft battles. Manage squad positioning, cover, and line-of-sight in detailed isometric environments to outmaneuver the opposing team.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ball Bullet Gun (Japan) [En by Aeon Genesis v1.0]', '1992', NaN, 'Namco', '1', NaN, 'Isometric tactical strategy game focused on airsoft-style military combat.', 'Lead your squad to victory in various tactical skirmish scenarios.', 'Play Ball Bullet Gun in English with this SNES fan translation.', 'Now fully playable for English speakers, this translation opens up the deep tactical mechanics and mission briefings of this unique Japanese military strategy title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ballz 3D (USA)', '1994', NaN, 'PF Magic', '2', 3, '3D perspective-based fighting game with unique ball-shaped characters.', 'Defeat all eccentric opponents to become the 3D fighting champion.', 'Experience the bizarre 3D fighter Ballz 3D on the Super Nintendo.', 'Ballz 3D uses a unique visual style where fighters are made of individual spheres. Utilize the pseudo-3D movement to pull off complex combos and outplay a cast of very strange characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Barbarossa (Japan)', '1993', NaN, 'Koei', '1', NaN, 'Historical grand strategy simulation set during World War II.', 'Lead German forces through the Eastern Front to achieve military dominance.', 'Command armies in the WWII strategy game Barbarossa for SNES.', 'A deep, menu-driven tactical simulation. Manage unit placement, supply lines, and historical maneuvers in this complex recreation of the 1941 invasion of the Soviet Union.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Barbie Super Model (USA)', '1993', NaN, 'Imagineering', '1', NaN, 'Fashion-focused simulation with mini-games involving modeling and photography.', 'Complete various fashion assignments to become a successful supermodel.', 'Live the fashion life in Barbie Super Model for the Super Nintendo.', 'Navigate Barbie through various locations, practicing walking patterns, choosing outfits, and completing mini-games to prepare for the big runway shows and magazine shoots.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Barbie Vacation Adventure (USA) (Proto)', '1994', NaN, 'Imagineering', '1', NaN, 'Adventure game with multiple vacation-themed mini-games and activities.', 'Explore different vacation spots and participate in local activities with Barbie.', 'Join the unreleased Barbie Vacation Adventure on the SNES.', 'A prototype of a family-friendly title featuring various holiday destinations. Participate in beach activities, camping, and more in this rare look at a cancelled Barbie project.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Barkley no Power Dunk (Japan)', '1994', NaN, 'Toei Animation', '2', NaN, 'Arcade-style basketball game featuring the NBA star Charles Barkley.', 'Outscore the opposing team in fast-paced 2-on-2 basketball matches.', 'Hit the court in Barkley no Power Dunk (Shut Up and Jam!) for SNES.', 'The Japanese version of the street basketball hit. Features high-flying dunks, aggressive defense, and the legendary Charles Barkley in an arcade-style hoop experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Barkley Shut Up and Jam! (Europe)', '1994', NaN, 'Accolade', '2', NaN, 'Arcade-style basketball game featuring the NBA star Charles Barkley.', 'Outscore the opposing team in fast-paced 2-on-2 basketball matches.', 'Experience street hoops in Barkley Shut Up and Jam! for the SNES.', 'Forget the rules of professional basketball. This title focuses on the intensity of streetball, featuring big dunks, trash talking, and competitive 2-on-2 action across various urban courts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Barkley Shut Up and Jam! (USA)', '1994', NaN, 'Accolade', '2', NaN, 'Arcade-style basketball game featuring the NBA star Charles Barkley.', 'Outscore the opposing team in fast-paced 2-on-2 basketball matches.', 'Experience street hoops in Barkley Shut Up and Jam! for the SNES.', 'Forget the rules of professional basketball. This title focuses on the intensity of streetball, featuring big dunks, trash talking, and competitive 2-on-2 action across various urban courts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BASS Masters Classic - Pro Edition (Europe)', '1996', NaN, 'Black Pearl Software', '1', NaN, 'Fishing simulation with professional tournament rules and licensed gear.', 'Win the BASS Masters Classic by catching the heaviest bass in each tournament.', 'Experience professional competitive fishing in BASS Masters Classic Pro Edition.', 'The definitive 16-bit fishing experience. Select your equipment, choose your boat, and use professional techniques to find the best spots and catch record-breaking bass in various lake environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BASS Masters Classic - Pro Edition (USA)', '1996', NaN, 'Black Pearl Software', '1', NaN, 'Fishing simulation with professional tournament rules and licensed gear.', 'Win the BASS Masters Classic by catching the heaviest bass in each tournament.', 'Experience professional competitive fishing in BASS Masters Classic Pro Edition.', 'The definitive 16-bit fishing experience. Select your equipment, choose your boat, and use professional techniques to find the best spots and catch record-breaking bass in various lake environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BASS Masters Classic (Japan)', '1995', NaN, 'Black Pearl Software', '1', NaN, 'Fishing simulation with professional tournament rules and licensed gear.', 'Win the BASS Masters Classic by catching the heaviest bass in each tournament.', 'Master the art of bass fishing in the Japanese version of BASS Masters Classic.', 'A detailed sports simulation where you compete in high-stakes fishing tournaments. Features realistic fish behavior and a wide variety of lures and rods to master on the water.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BASS Masters Classic (USA)', '1995', NaN, 'Black Pearl Software', '1', NaN, 'Fishing simulation with professional tournament rules and licensed gear.', 'Win the BASS Masters Classic by catching the heaviest bass in each tournament.', 'Experience professional competitive fishing in BASS Masters Classic for SNES.', 'Navigate your boat across legendary American lakes. Monitor weather conditions and lake depth to track down the biggest fish and climb the professional rankings.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bassin''s Black Bass (USA)', '1994', NaN, 'Hot-B', '1', NaN, 'Detailed fishing game with a focus on realism and seasonal changes.', 'Progress through local tournaments to become the ultimate bass fishing champion.', 'Dive into authentic lake fishing with Bassin''s Black Bass for the SNES.', 'Featuring a top-down view for navigation and a cinematic view for reeling in, this title offers a deep simulation of freshwater fishing, including lure movement and tension management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bastard!! - Ankoku no Hakaishin (Japan)', '1994', NaN, 'Cobra Team', '1', NaN, '3D perspective fighting game with magical combat and anime-style graphics.', 'Defeat the dark wizards and protect the world from the Dark God of Destruction.', 'Experience magical 16-bit combat in Bastard!! - Ankoku no Hakaishin.', 'Based on the hit manga and anime, this game features a unique over-the-shoulder perspective. Unleash massive spells and engage in high-speed aerial battles against iconic dark fantasy villains.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bastard!! - Ankoku no Hakaishin (Japan) [En by DeJap v1.0] (~Bastard!! - Dark God of Destruction)', '1994', NaN, 'Cobra Team', '1', NaN, '3D perspective fighting game with magical combat and anime-style graphics.', 'Defeat the dark wizards and protect the world from the Dark God of Destruction.', 'Play the English translation of Bastard!! Dark God of Destruction on SNES.', 'Now fully playable in English, follow Dark Schneider''s quest to reclaim his power. This fan translation makes the deep magic system and story accessible to Western fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Batman - Revenge of the Joker (USA) (Proto)', '1995', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action platformer based on the comic book style.', 'Navigate through Gotham City to find and defeat the Joker.', 'Explore the rare prototype of Batman: Revenge of the Joker on SNES.', 'A 16-bit upgrade of the NES classic. Use various Batarang types and combat moves to fight through industrial levels and face off against Batman''s greatest rival in this unreleased build.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Batman (USA) (Proto)', '1995', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling action platformer featuring Batman''s gadgets.', 'Defeat thugs and iconic villains to clean up the streets of Gotham.', 'Check out this early Batman Prototype for the Super Nintendo.', 'An early development build showing the core mechanics of what would become a Batman action title. Features early level designs and character movement for testing purposes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Batman Forever (Europe)', '1995', NaN, 'Probe Entertainment', '1', NaN, 'Beat ''em up and platformer hybrid with digitized character sprites.', 'Infiltrate the Arkham Asylum and stop Two-Face and the Riddler''s scheme.', 'Enter the shadows in the Batman Forever video game for SNES.', 'Based on the 1995 film, control Batman or Robin. Use a variety of gadgets and Mortal Kombat-style combat moves to navigate through Gotham''s dark secrets.', NULL);
