INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Clash (Europe)', '1992', NaN, 'Intelligent Systems', '2', NaN, 'First-person light gun shooter utilizing the Super Scope.', 'Pilot a giant mech and destroy enemy robots in a futuristic war.', 'Experience explosive Super Scope action in Battle Clash on SNES.', 'A cinematic rail-shooter where you target specific parts of enemy mechs (STs). Manage your energy and timing to shoot down incoming missiles and dismantle your opponents.', NULL);
