INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Commander - Hachibushuu, Shura no Heihou (Japan)', '1992', NaN, 'Banpresto', '1', NaN, 'Tactical strategy game featuring crossover characters from various franchises.', 'Lead your mecha army to victory in turn-based strategic combat.', 'Master mecha strategy in Battle Commander for the SNES.', 'Featuring characters from Gundam, Mazinger Z, and Kamen Rider. Manage your units across diverse maps, utilizing terrain and unique unit abilities to defeat enemy forces.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Cross (Japan)', '1992', NaN, 'Jaleco', '2', NaN, 'Isometric racing game with miniature cars and hazardous tracks.', 'Win the grand prix by navigating tight corners and avoiding obstacles.', 'Enjoy high-speed isometric racing in Battle Cross for the SNES.', 'A fast-paced racer where up to five players can compete. Use power-ups and master the drifting mechanics to stay ahead on the colorful, chaotic tracks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Dodge Ball - Toukyuu Daigekitotsu! (Japan)', '1991', NaN, 'Technos Japan', '4', NaN, 'Dodgeball simulation featuring popular mecha and anime characters.', 'Defeat the opposing team by knocking out their players with the ball.', 'Play supernatural dodgeball in Battle Dodge Ball for the SNES.', 'Join characters from Ultraman, Gundam, and Kamen Rider in a super-powered dodgeball tournament. Use special moves and strategic passes to dominate the court.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Dodge Ball II (Japan)', '1994', NaN, 'Technos Japan', '4', NaN, 'Sports simulation featuring super-powered dodgeball matches with iconic mecha and anime characters.', 'Eliminate the opposing team''s HP by hitting them with powerful ball attacks.', 'Play super-powered dodgeball with famous heroes in Battle Dodge Ball II for SNES.', 'A sequel to the cult classic, featuring characters from Gundam, Ultraman, and Kamen Rider. Master unique special shots and team formations to dominate the arena in this action-packed sports hybrid.', NULL);
