INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Grand Prix (USA)', '1992', NaN, 'Atlus', '2', NaN, 'Formula One racing simulation with split-screen multiplayer and various team selections.', 'Win the world championship by placing first in a series of global racing circuits.', 'Experience 16-bit F1 racing in the competitive Battle Grand Prix for SNES.', 'A detailed racing game offering various modes, including Grand Prix and versus. Customize your car''s settings and master the tracks to become the ultimate 16-bit racing legend.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Jockey (Japan)', '1994', NaN, 'Philips Media', '1', NaN, 'Side-scrolling horse racing game with action and combat elements.', 'Win the race while using items and physical attacks to hinder opponents.', 'Experience chaotic horse racing action in Battle Jockey for the SNES.', 'A unique Japanese title that blends traditional horse racing with arcade combat. Use power-ups and well-timed attacks to cross the finish line first in this fast-paced competition.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Master - Kyuukyoku no Senshi-tachi (Japan)', '1993', NaN, 'Banpresto', '1', NaN, 'One-on-one fighting game with a diverse roster of warriors and special moves.', 'Defeat all challengers in a martial arts tournament to prove your strength.', 'Master 16-bit martial arts in Battle Master: Kyuukyoku no Senshi-tachi.', 'A high-quality Japanese fighter featuring smooth animation and a deep combo system. Choose your warrior and battle through atmospheric stages to reach the final boss.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Pinball (Japan)', '1995', NaN, 'Banpresto', '1', NaN, 'Themed pinball simulation featuring popular Japanese characters and franchises.', 'Achieve high scores by completing board-specific missions and defeating bosses.', 'Enjoy themed pinball action in Battle Pinball for the Super Famicom.', 'Featuring boards based on Ultraman, Gundam, and more. Use the flippers to trigger special events and battle enemies directly on the pinball table in this crossover hit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Battle Racers (Japan)', '1991', NaN, 'Namco', '2', NaN, 'Combat racing game featuring SD (Super Deformed) characters from famous franchises.', 'Cross the finish line first while using weapons to blast rivals off the track.', 'Race and battle with SD heroes in Battle Racers for the SNES.', 'A fun, competitive racer featuring characters from Ultraman, Kamen Rider, and Gundam. Use unique vehicle abilities and environmental hazards to secure your victory.', NULL);
