INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bill Walsh College Football (USA)', '1993', NaN, 'Electronic Arts', '2', NaN, 'College football simulation featuring authentic teams and formations.', 'Lead your college team to the bowl game victory.', 'Experience the intensity of Bill Walsh College Football on the SNES.', 'A classic American football title focusing on the college game. Features a wide variety of schools, playbooks, and the quest for the national championship.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bing Bing! Bingo (Japan)', '1993', NaN, 'Compile', '2', NaN, 'Bingo-themed party game with various mini-games and anime-style characters.', 'Be the first to complete a bingo pattern and win the tournament.', 'Enjoy competitive bingo fun in Bing Bing! Bingo for the SNES.', 'A quirky Japanese title that turns the classic game of Bingo into a high-energy competition. Featuring colorful characters, multiple game modes, and interactive mini-games to spice up the 16-bit gambling experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bio Metal (Europe)', '1993', NaN, 'Athena', '1', NaN, 'Side-scrolling shoot ''em up with an innovative GAM shield mechanic.', 'Destroy the biological alien invaders to save the human race.', 'Blast through enemies in the intense shooter Bio Metal on SNES.', 'Experience high-speed aerial combat with a twist. Master the orb-based shield system that can both protect your ship and be used as a devastating projectile weapon against alien bio-forms.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bio Metal (Japan)', '1993', NaN, 'Athena', '1', NaN, 'Side-scrolling shoot ''em up with an innovative GAM shield mechanic.', 'Destroy the biological alien invaders to save the human race.', 'Blast through enemies in the intense shooter Bio Metal on SNES.', 'The Japanese version of the sci-fi SHMUP. While the US version featured a Techno soundtrack, the original Japanese release offers a classic 16-bit arcade score to accompany the intense action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bio Metal (USA)', '1993', NaN, 'Athena', '1', NaN, 'Side-scrolling shoot ''em up with an innovative GAM shield mechanic.', 'Destroy the biological alien invaders to save the human race.', 'Blast through enemies in the intense shooter Bio Metal on SNES.', 'Face waves of organic and mechanical threats. Use your rotating energy orbs strategically to navigate through narrow corridors and defeat screen-filling bosses in this technical shooter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishin Densetsu Zoku (Japan)', '1993', NaN, 'Riverhillsoft', '1', NaN, 'Racing and combat hybrid set in a post-apocalyptic or bosozoku rebel world.', 'Win high-stakes street races and defeat rival gang members in combat.', 'Experience rebel street racing in Bishin Densetsu Zoku for SNES.', 'A unique Japanese title that blends top-down racing with side-scrolling fighting. Customize your vehicle and battle your way through rival territories to prove your dominance in the gang world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Janshi Suchie-Pie (Japan)', '1994', NaN, 'Jaleco', '1', NaN, 'Mahjong simulation featuring anime-style female characters and special moves.', 'Defeat various opponents in Mahjong matches to progress through the story.', 'Play anime-style Mahjong in Bishoujo Janshi Suchie-Pie on SNES.', 'Join the Suchie-Pie magical girls in this colorful Mahjong title. Utilize special powers and cheats to win rounds and unlock beautiful 16-bit character art and story sequences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Janshi Suchie-Pie (Japan) (Rev A)', '1994', NaN, 'Jaleco', '1', NaN, 'Mahjong simulation featuring anime-style female characters and special moves.', 'Defeat various opponents in Mahjong matches to progress through the story.', 'Play anime-style Mahjong in Bishoujo Janshi Suchie-Pie on SNES.', 'The revised version of the popular Mahjong title, featuring polished gameplay mechanics and character interactions in a vibrant anime-themed gambling simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon - Another Story (Japan)', '1995', NaN, 'Angel', '1', NaN, 'Turn-based JRPG featuring the iconic Sailor Scouts and a deep narrative.', 'Protect the Silver Crystal and stop a mysterious new threat to the timeline.', 'Experience the epic Sailor Moon RPG: Another Story on the SNES.', 'A massive JRPG that spans across multiple locations from the anime. Form teams with all the Sailor Scouts, use their signature attacks, and experience an original story unique to the SNES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon - Another Story (Japan) [En by FuSoYa v1.0] (~Pretty Soldier Sailor Moon - Another Story)', '1995', NaN, 'Angel', '1', NaN, 'Turn-based JRPG featuring the iconic Sailor Scouts and a deep narrative.', 'Protect the Silver Crystal and stop a mysterious new threat to the timeline.', 'Play the English translation of Sailor Moon: Another Story on SNES.', 'The definitive way for Western fans to experience the Sailor Moon RPG. This fan translation makes the deep story, menu systems, and specialized combat accessible to all English speakers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon - Another Story (T-Eng v2.08)', '1995', NaN, 'Angel', '1', NaN, 'Turn-based JRPG featuring the iconic Sailor Scouts and a deep narrative.', 'Protect the Silver Crystal and stop a mysterious new threat to the timeline.', 'Play the English translation of Sailor Moon: Another Story on SNES.', 'An updated fan translation version featuring refined text and technical fixes. Help the Sailor Scouts face their past and future in this 16-bit masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon (Japan)', '1993', NaN, 'Angel', '2', NaN, 'Side-scrolling beat ''em up featuring the five original Sailor Scouts.', 'Defeat the Dark Kingdom''s minions and stop Queen Beryl.', 'Battle as the Sailor Scouts in Bishoujo Senshi Sailormoon for SNES.', 'A classic brawler where you can play as Moon, Mercury, Mars, Jupiter, or Venus. Use each scout''s unique magic attacks to clear waves of enemies in various urban Tokyo environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon R (Japan)', '1993', NaN, 'Angel', '2', NaN, 'Side-scrolling beat ''em up based on the R season of the anime.', 'Rescue Chibiusa and defeat the Black Moon Clan invaders.', 'Continue the fight in Bishoujo Senshi Sailormoon R for the SNES.', 'The sequel adds more moves and playable characters. Features a fun Chibiusa mode for younger players and improved 16-bit graphics that capture the anime''s aesthetic perfectly.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon R (Japan) [En by FuSoYa v1.0] (~Pretty Soldier Sailor Moon R)', '1993', NaN, 'Angel', '2', NaN, 'Side-scrolling beat ''em up based on the R season of the anime.', 'Rescue Chibiusa and defeat the Black Moon Clan invaders.', 'Play Sailor Moon R in English with this SNES fan translation.', 'Now fully playable in English, follow the scouts as they battle through the R story arc. Experience the full narrative and combat moves of the second 16-bit brawler.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon S - Jougai Rantou! Shuyaku Soudatsusen (Japan)', '1994', NaN, 'Angel', '2', NaN, 'One-on-one fighting game featuring the Sailor Scouts with special moves.', 'Defeat the other scouts to determine who the strongest protector is.', 'Engage in Sailor Moon fighting action in this SNES combat title.', 'A competitive 2D fighter featuring fluid animation and a roster of favorite scouts. Master each character''s signature special attacks in fast-paced 16-bit duels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon S - Kondo wa Puzzle de Oshioki yo! (Japan)', '1995', NaN, 'Angel', '2', NaN, 'Competitive puzzle game featuring falling blocks and Sailor Moon characters.', 'Outplay your opponent by clearing puzzle blocks and triggering attacks.', 'Enjoy Sailor Moon puzzle action in Kondo wa Puzzle de Oshioki yo!', 'A vibrant and addictive puzzle title. Compete against the computer or a friend, using strategic clears to send obstacles to your rival''s board in this anime-themed experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon S - Kurukkurin (Japan)', '1995', NaN, 'Angel', '1', NaN, 'A unique action-puzzle game where players move and rotate characters.', 'Clear the board and achieve high scores in this themed puzzle challenge.', 'Play the quirky Sailor Moon puzzle game Kurukkurin on SNES.', 'Unlike traditional block puzzles, Kurukkurin features a rotating mechanic centered around the characters. It''s a charming and visually bright title for puzzle and anime fans alike.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon Sailor Stars - Fuwa Fuwa Panic 2 (Japan) (ST)', '1996', NaN, 'Angel', '1', NaN, 'Competitive balloon-popping puzzle game with a story mode and multiplayer.', 'Popping more balloons than the opponent to win matches.', 'Experience the high-speed puzzle fun of Fuwa Fuwa Panic 2 for SNES.', 'Based on the Sailor Stars arc, this competitive puzzle game tasks players with clearing their screen of colorful balloons using speed and special power-ups from the scouts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon Super S - Fuwa Fuwa Panic (English)', '1995', NaN, 'Angel', '2', NaN, 'Competitive balloon-popping puzzle game, now accessible in English.', 'Popping more balloons than the opponent to win matches.', 'Play Fuwa Fuwa Panic in English with this SNES fan translation.', 'The first installment of the Fuwa Fuwa series, now translated for Western players. Enjoy the fast-paced balloon-popping gameplay with your favorite Sailor Moon characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon Super S - Fuwa Fuwa Panic (Japan)', '1995', NaN, 'Angel', '2', NaN, 'Competitive balloon-popping puzzle game with a story mode and multiplayer.', 'Popping more balloons than the opponent to win matches.', 'Experience the high-speed puzzle fun of Fuwa Fuwa Panic for SNES.', 'The original Japanese release of the Super S themed puzzle game. Features beautiful 16-bit character sprites and intense competitive gameplay for one or two players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Senshi Sailormoon Super S - Zenin Sanka!! Shuyaku Soudatsusen (Japan)', '1995', NaN, 'Angel', '2', NaN, 'Expanded one-on-one fighting game with more characters and refined moves.', 'Win the tournament and prove your strength as a Sailor Scout.', 'Battle as your favorite scout in Zenin Sanka!! Super S for SNES.', 'The final 2D fighting game in the SNES series, featuring characters from the Super S season. Offers more balanced mechanics and more playable fighters than its predecessors.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bishoujo Wrestler Retsuden - Blizzard Yuki Rannyuu!! (Japan)', '1994', NaN, 'Athena', '2', NaN, 'Female professional wrestling simulation with management elements.', 'Lead your wrestler to the top of the championship through skill and training.', 'Enter the ring in Bishoujo Wrestler Retsuden for the SNES.', 'Focuses on the world of joshi wrestling. Manage your fighter''s training and execute powerful moves in the ring to win the 16-bit championship title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Blackhawk (Europe) (En,Fr,De)', '1992', NaN, 'Atelier Double', '1', NaN, 'Cinematic action platformer featuring cover-based shooting and exploration.', 'Navigate a dark alien world and lead your people to freedom.', 'Survive the brutal world of Blackhawk (Blackthorne) on the SNES.', 'Known as Blackthorne in the US. Play as Kyle Vlaros in this cinematic platformer. Use a shotgun and tactical cover to defeat orc-like enemies and reclaim your throne.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Blackthorne - Fukushuu no Kuroki Kyoku (Japan)', '1994', NaN, 'Blizzard Entertainment', '1', NaN, 'Cinematic action platformer featuring cover-based shooting and exploration.', 'Navigate a dark alien world and lead your people to freedom.', 'Experience the epic revenge story in Blackthorne for the SNES.', 'The Japanese release of the Blizzard classic. Features detailed rotoscoped animation, a mature storyline, and intense tactical combat that was ahead of its time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Blackthorne (USA)', '1994', NaN, 'Blizzard Entertainment', '1', NaN, 'Cinematic action platformer featuring cover-based shooting and exploration.', 'Navigate a dark alien world and lead your people to freedom.', 'Experience the epic revenge story in Blackthorne for the SNES.', 'Master the art of shooting behind your back and utilizing environmental hazards. Blackthorne is a standout title for fans of Prince of Persia style cinematic platforming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Blackthorne (USA) (Beta)', '1994', NaN, 'Blizzard Entertainment', '1', NaN, 'Cinematic action platformer featuring cover-based shooting and exploration.', 'Navigate a dark alien world and lead your people to freedom.', 'Explore the Blackthorne Beta and its development on SNES.', 'A pre-release build of the cinematic shooter. This version allows players to see early level designs and mechanical tweaks before the final 16-bit release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BlaZeon - The Bio-Cyborg Challenge (USA)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling shoot ''em up where the player can hijack and pilot enemy robots.', 'Destroy the bio-mechanical invaders to save humanity.', 'Pilot enemy mechs in the intense shooter BlaZeon for SNES.', 'Featuring a unique morphing system, BlaZeon allows you to capture enemy robots and use their weapon systems as your own. Navigate through 16-bit space environments and defeat massive bio-cyborg bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BlaZeon (Japan)', '1992', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling shoot ''em up where the player can hijack and pilot enemy robots.', 'Destroy the bio-mechanical invaders to save humanity.', 'Pilot enemy mechs in the intense shooter BlaZeon for SNES.', 'Featuring a unique morphing system, BlaZeon allows you to capture enemy robots and use their weapon systems as your own. Navigate through 16-bit space environments and defeat massive bio-cyborg bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Blazing Skies (Europe)', '1993', NaN, 'The Sales Curve', '1', NaN, 'First-person aerial combat simulation set during World War II.', 'Complete various bombing and dogfighting missions across different theaters.', 'Take to the skies in the WWII flight sim Blazing Skies for SNES.', 'Engage in intense dogfights and strategic bombing runs. Blazing Skies offers a detailed 16-bit simulation of classic air combat with various mission objectives and realistic physics for its time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Block Kuzushi (Japan)', '1999', NaN, 'Nintendo', '2', NaN, 'Classic brick-breaking arcade gameplay with power-ups.', 'Clear all the blocks on each stage using a ball and paddle.', 'Enjoy classic arcade fun in Block Kuzushi for the Super Famicom.', 'A straightforward and addictive Arkanoid style game. Use your reflexes to keep the ball in play, collect items, and clear increasingly difficult patterns of blocks in this Japanese 16-bit title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Blue Crystal Rod, The (Japan)', '1994', NaN, 'Namco', '1', NaN, 'Action-adventure with light RPG elements and top-down exploration.', 'Protect the sacred rod and stop the dark forces from awakening.', 'Experience the fantasy adventure of The Blue Crystal Rod on SNES.', 'Part of the Babylonian Castle Saga, this title features charming 16-bit graphics and a focus on story and character interaction. Navigate a magical world to fulfill your destiny.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Blues Brothers, The (Europe)', '1991', NaN, 'Titus', '2', NaN, 'Side-scrolling platformer based on the iconic musical characters.', 'Navigate through the city and escape the law to make it to the big concert.', 'Join the band in The Blues Brothers platformer for the SNES.', 'Play as Jake or Elwood. Dodge the police, jump over obstacles, and collect records across various urban levels inspired by the movie in this fun 16-bit musical adventure.', NULL);
