INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bobby''s World (USA) (Proto)', '1994', NaN, 'High Voltage Software', '1', NaN, 'Side-scrolling action platformer based on the animated series.', 'Navigate through Bobby''s imagination to overcome everyday obstacles.', 'Experience the unreleased Bobby''s World prototype on SNES.', 'A rare look at a cancelled project. Help Bobby navigate through colorful, imaginative worlds based on the popular 90s cartoon, featuring unique platforming challenges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bokujou Monogatari (Japan)', '1996', NaN, 'Pack-In-Video', '1', NaN, 'Pioneering farming and life simulation with social and time management elements.', 'Successfully run a farm while building relationships in the village.', 'Start your farm life in the original Bokujou Monogatari for SNES.', 'Known as Harvest Moon in the West. Plant crops, raise livestock, and get married in this classic 16-bit sim that started the entire farming genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bokujou Monogatari (Japan) (Rev A)', '1996', NaN, 'Pack-In-Video', '1', NaN, 'Pioneering farming and life simulation with social and time management elements.', 'Successfully run a farm while building relationships in the village.', 'Start your farm life in the original Bokujou Monogatari for SNES.', 'The revised Japanese version of the classic farming sim. Experience refined mechanics and seasonal events as you work to build the most prosperous farm in the land.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bomberman B-Daman (Japan)', '1996', NaN, 'Hudson Soft', '2', NaN, 'Top-down puzzle game based on the marble-shooting B-Daman toy line.', 'Clear various grid-based puzzles by strategically shooting marbles.', 'Solve marble puzzles in Bomberman B-Daman for the SNES.', 'A unique crossover that blends Bomberman characters with B-Daman mechanics. Think fast and aim carefully to clear stages in this addictive 16-bit puzzle title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bombuzal (Japan)', '1993', NaN, 'Teeny Weeny Games', '1', NaN, 'Isometric puzzle game focused on detonating explosives strategically.', 'Destroy all bombs on the board without getting caught in the blast.', 'Master explosives in the challenging puzzle game Bombuzal for SNES.', 'Navigate a series of increasingly complex levels. You must figure out the correct sequence to trigger bombs while ensuring you have a safe path to the exit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bonkers - Hollywood Daisakusen! (Japan)', '1994', NaN, 'Tose', '1', NaN, 'Action platformer featuring the erratic bobcat from the Disney series.', 'Solve mysteries in Hollywood and stop the toon villains.', 'Join the wacky fun in Bonkers: Hollywood Daisakusen for SNES.', 'Control Bonkers D. Bobcat in a series of colorful levels. Use your agility and toon gadgets to defeat enemies and solve cases in this 16-bit Disney adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bonkers (USA)', '1994', NaN, 'Tose', '1', NaN, 'Action platformer featuring the erratic bobcat from the Disney series.', 'Solve mysteries in Hollywood and stop the toon villains.', 'Join the wacky fun in Bonkers: Hollywood Daisakusen for SNES.', 'Control Bonkers D. Bobcat in a series of colorful levels. Use your agility and toon gadgets to defeat enemies and solve cases in this 16-bit Disney adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Boogerman - A Pick and Flick Adventure (Europe)', '1994', NaN, 'Interplay Productions', '1', NaN, 'Gross-out themed side-scrolling platformer with unique projectile mechanics.', 'Navigate through a world of filth to defeat the Boogerman and save the day.', 'Play the hilarious Boogerman: A Pick and Flick Adventure on SNES.', 'Use burps, farts, and nose-flicks as weapons. This 16-bit platformer is famous for its gross humor, detailed animation, and creative level design.', NULL);
