INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Boogerman Camera Fix', '2023', NaN, 'ROM Hack', '1', NaN, 'Gross-out themed side-scrolling platformer with unique projectile mechanics.', 'Navigate through a world of filth to defeat the Boogerman and save the day.', 'Experience Boogerman with an improved camera fix on the SNES.', 'A fan-made modification that improves the player''s view and scrolling, making the platforming and gross-out combat much smoother and more enjoyable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bounty Sword (Japan)', '1995', NaN, 'ITL', '1', NaN, 'Tactical turn-based RPG with an isometric view and high-fantasy setting.', 'Lead your mercenary band to victory in a world of war and magic.', 'Master tactical combat in Bounty Sword for the Super Famicom.', 'A deep strategy RPG featuring complex unit management, beautiful sprite art, and a compelling narrative. Strategize your movements and attacks to dominate the 16-bit battlefield.', NULL);
