INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Brain Lord (Japan)', '1994', NaN, 'Produce!', '1', NaN, 'Top-down action RPG with a heavy emphasis on complex puzzle-solving.', 'Explore dangerous towers and dungeons to find the ancient artifacts.', 'Solve the mysteries of Brain Lord, a deep SNES action RPG.', 'Navigate through intricate dungeons filled with traps and puzzles. Manage your Jades (elemental companions) to help you in combat and environmental challenges in this Enix classic.', NULL);
