INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Brandish (Japan)', '1991', NaN, 'Nihon Falcom', '1', NaN, 'Unique overhead dungeon crawler where the entire world rotates around the player.', 'Escape the labyrinth of Bereth y defeating the guardian and solving puzzles.', 'Master the rotating world of Brandish, a unique SNES dungeon RPG.', 'A cult classic known for its innovative perspective. Navigate deadly traps, manage your equipment, and fight monsters in a massive tower where every turn shifts your entire view.', NULL);
