INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Brawl Brothers - Rival Turf! 2 (Europe)', '1994', NaN, 'Jaleco', '2', NaN, 'Belt-scrolling beat ''em up featuring multiple playable characters and combos.', 'Rescue the kidnapped martial arts masters from the criminal syndicate.', 'Fight through the streets in Brawl Brothers, the SNES brawler sequel.', 'Known in Japan as Rival Turf! 2, this game features refined combat, secret characters, and an Angry mode that boosts your power when taking damage.', NULL);
