INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Breath of Fire - Ryuu no Senshi (Japan)', '1993', NaN, 'Capcom', '1', NaN, 'Classic turn-based JRPG featuring a protagonist who can transform into dragons.', 'Lead the Light Dragon Clan to stop the Dark Dragon Empire''s world conquest.', 'Start the epic saga with Breath of Fire on the SNES.', 'Capcom''s flagship RPG series debuts with beautiful sprite art and a deep story. Help Ryu and Nina gather allies and master the power of the dragon to save the world.', NULL);
