INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bronkie the Bronchiasaurus (USA) (En,Es)', '1994', NaN, 'Radium', '1', NaN, 'Educational platformer focused on asthma management and health.', 'Navigate through levels while collecting inhalers and avoiding asthma triggers.', 'Learn and play with Bronkie the Bronchiasaurus on the SNES.', 'Part of a series of educational health games. Control Bronkie, a dinosaur with asthma, and learn about triggers like smoke and dust while completing traditional platforming challenges.', NULL);
