INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS 3-ji no Wide Shou - 98-06 Gatsugou (Japan)', '1998', NaN, 'Nintendo', '1', NaN, 'Digital magazine/lifestyle content broadcasted via the Satellaview.', 'View news, entertainment, and cultural content from June 1998.', 'Discover the rare BS 3-ji no Wide Shou magazine for Satellaview.', 'A fascinating piece of gaming history. This was a magazine style broadcast that provided players with news and interactive content directly to their Super Famicom via satellite.', NULL);
