INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Cheap de Gorgeous Vol. 1 (Japan)', '1997', NaN, 'Nintendo', '1', NaN, 'Quirky digital variety show or mini-game collection for Satellaview.', 'Participate in various interactive segments and enjoy the unique humor.', 'Experience the bizarre BS Cheap de Gorgeous on the SNES.', 'One of the more experimental Satellaview broadcasts. It featured a mix of oddball humor, digital art, and interactive elements designed for the Japanese satellite audience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Chrono Trigger - Character Zukan (Japan)', '1995', NaN, 'Square', '1', NaN, 'Digital encyclopedia focused on the characters of the hit JRPG.', 'Explore the backstories and stats of the Chrono Trigger cast.', 'Discover the BS Chrono Trigger Character Zukan on Satellaview.', 'A must-have for fans of the legendary RPG. This digital guide provided deep lore, character profiles, and artwork that weren''t included in the main game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Chrono Trigger - Jet Bike Special (Japan)', '1995', NaN, 'Square', '1', NaN, 'Racing mini-game based on the famous segment from Chrono Trigger.', 'Defeat Johnny in high-speed jet bike races to earn rewards.', 'Race through time in BS Chrono Trigger: Jet Bike Special for SNES.', 'A standalone expansion of the 2300 AD racing mini-game. Features improved tracks and more competitive AI for fans of the original Chrono Trigger segment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Chrono Trigger - Music Library (Japan)', '1995', NaN, 'Square', '1', NaN, 'Digital music player featuring the iconic soundtrack of the game.', 'Listen to the legendary Yasunori Mitsuda score through your console.', 'Enjoy the BS Chrono Trigger Music Library on the Satellaview.', 'This satellite broadcast allowed players to enjoy the high-quality 16-bit soundtrack of Chrono Trigger in a dedicated jukebox-style interface on their SNES.', NULL);
