INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Koubo Kenshou Magazine (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Interactive digital magazine featuring contests and reader-submitted content.', 'Read the latest news and participate in digital prize draws.', 'Stay updated with the BS Koubo Kenshou Magazine for SNES.', 'A fascinating digital publication delivered via satellite. It allowed Japanese players to interact with the magazine staff and enter competitions directly from their consoles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Let''s Pachinko Nante Gindama 1 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Pachinko simulation with realistic ball physics and machine mechanics.', 'Accumulate the highest number of silver balls through luck and skill.', 'Experience Japanese Pachinko in BS Let''s Pachinko Nante Gindama.', 'The first installment of the satellite Pachinko series. Features authentic machine designs and the addictive gambling gameplay popular in Japanese arcades.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Let''s Pachinko Nante Gindama 2 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Pachinko simulation with realistic ball physics and machine mechanics.', 'Accumulate the highest number of silver balls through luck and skill.', 'Experience Japanese Pachinko in BS Let''s Pachinko Nante Gindama 2.', 'The second volume of the Pachinko series, offering new machine layouts and updated bonus features for digital gambling enthusiasts on the Super Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Let''s Pachinko Nante Gindama 3 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Pachinko simulation with realistic ball physics and machine mechanics.', 'Accumulate the highest number of silver balls through luck and skill.', 'Experience Japanese Pachinko in BS Let''s Pachinko Nante Gindama 3.', 'Volume three of the series. Refine your ball-launching technique and trigger special animations to win big in this 16-bit Pachinko simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Let''s Pachinko Nante Gindama 4 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Pachinko simulation with realistic ball physics and machine mechanics.', 'Accumulate the highest number of silver balls through luck and skill.', 'Experience Japanese Pachinko in BS Let''s Pachinko Nante Gindama 4.', 'The final entry in the satellite Pachinko collection. Features the most advanced machine logic and bonus rounds in the series for the Satellaview system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Lord Monarch (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Strategic board-game RPG hybrid focused on kingdom expansion and combat.', 'Conquer the entire map by managing your troops and defeating rival lords.', 'Master 16-bit strategy in the satellite version of BS Lord Monarch.', 'A fast-paced real-time strategy game. Manage resources, build paths, and send your armies to dominate the continent in this deep Falcom-developed title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Marvelous Camp Arnold Course - Dai-1-shuu (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Action-adventure with puzzle elements, serving as a spin-off to Marvelous.', 'Complete the first week of training at Camp Arnold''s outdoor course.', 'Join the adventure in BS Marvelous Camp Arnold Course - Week 1.', 'A satellite-exclusive expansion of Marvelous: Mouhitotsu no Takarajima. Lead your trio of characters through team-based puzzles and outdoor challenges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Marvelous Camp Arnold Course - Dai-2-shuu (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Action-adventure with puzzle elements, serving as a spin-off to Marvelous.', 'Complete the second week of training and solve new campsite mysteries.', 'Join the adventure in BS Marvelous Camp Arnold Course - Week 2.', 'The story continues with more complex puzzles. Use the unique abilities of Dion, Max, and Jack to navigate the forest and complete Arnold''s tasks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Marvelous Camp Arnold Course - Dai-3-shuu (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Action-adventure with puzzle elements, serving as a spin-off to Marvelous.', 'Overcome the third week''s challenges and discover hidden treasures.', 'Join the adventure in BS Marvelous Camp Arnold Course - Week 3.', 'Week three increases the difficulty with elaborate environmental riddles. Master the character-switching mechanic to progress through the campsite''s secrets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Marvelous Camp Arnold Course - Dai-4-shuu (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Action-adventure with puzzle elements, serving as a spin-off to Marvelous.', 'Finish the final week of Camp Arnold and graduate from the course.', 'The grand finale of BS Marvelous Camp Arnold Course - Week 4.', 'The concluding chapter of the Camp Arnold saga. Solve the final set of puzzles and complete your 16-bit outdoor training in this rare expansion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Marvelous Time Athletic Course - Dai-1-shuu (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Isometric action-adventure focused on speed and obstacle navigation.', 'Clear the first athletic course within the strict time limit.', 'Test your reflexes in BS Marvelous Time Athletic Course - Week 1.', 'A standalone challenge series based on the Marvelous engine. Focuses on pure agility and quick puzzle-solving across a series of treacherous 16-bit courses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Marvelous Time Athletic Course - Dai-2-shuu (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Isometric action-adventure focused on speed and obstacle navigation.', 'Clear the second athletic course within the strict time limit.', 'Test your reflexes in BS Marvelous Time Athletic Course - Week 2.', 'The second week introduces more hazards and tighter timing. Navigate through the isometric world using speed and precision to reach the goal.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Marvelous Time Athletic Course - Dai-3-shuu (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Isometric action-adventure focused on speed and obstacle navigation.', 'Clear the third athletic course within the strict time limit.', 'Test your reflexes in BS Marvelous Time Athletic Course - Week 3.', 'A high-stakes obstacle course that tests your mastery of the game''s movement mechanics. Avoid traps and solve quick puzzles under pressure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Marvelous Time Athletic Course - Dai-4-shuu (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Isometric action-adventure focused on speed and obstacle navigation.', 'Complete the final athletic course and achieve the best time record.', 'The ultimate challenge in BS Marvelous Time Athletic Course - Week 4.', 'The final and most difficult week of the athletic series. Only the fastest players can navigate this complex 16-bit labyrinth before time runs out.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Nichibutsu Mahjong - Renshuu Mahjong - Ichimantou (Japan)', '1996', NaN, 'Nichibutsu', '1', NaN, 'Mahjong simulation with a focus on practice and technical mastery.', 'Win Mahjong matches to earn the Ichimantou rank and improve your skills.', 'Master Mahjong strategy in BS Nichibutsu Mahjong: Renshuu Mahjong.', 'A focused Mahjong title designed for players to practice their hands. Features a clean interface and competitive AI to help you master the traditional Japanese game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Nichibutsu Mahjong - Renshuu Mahjong - Nimantou (Japan)', '1996', NaN, 'Nichibutsu', '1', NaN, 'Mahjong simulation with a focus on practice and technical mastery.', 'Win Mahjong matches to earn the Nimantou rank and improve your skills.', 'Master Mahjong strategy in BS Nichibutsu Mahjong: Renshuu Mahjong.', 'The second level of the Mahjong practice series. Offers tougher opponents and more complex scenarios to test your 16-bit gambling and strategy skills.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Nichibutsu Mahjong (Japan)', '1996', NaN, 'Nichibutsu', '1', NaN, 'Traditional Mahjong simulation with professional rules and tournament play.', 'Win matches against skilled AI opponents to climb the Mahjong rankings.', 'Play professional Mahjong in BS Nichibutsu Mahjong for the Satellaview.', 'A high-quality Mahjong experience featuring detailed 16-bit graphics and a variety of modes. Master the tiles and outsmart your rivals in this satellite-exclusive gambling sim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Nintama Rantarou 2 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Action-platformer based on the popular anime featuring young ninjas.', 'Navigate through obstacle-filled levels to complete ninja training.', 'Join the ninja apprentices in BS Nintama Rantarou 2 for the SNES.', 'Control Rantarou and his friends in this charming 16-bit platformer. Use unique ninja tools and agility to overcome traps and enemies in this satellite broadcast version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Nintendo HP - 5-17 Gou (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Digital Home Page magazine featuring official Nintendo news and tips.', 'Explore the latest 16-bit game updates and official announcements.', 'Check out the BS Nintendo HP digital magazine for Satellaview.', 'An interactive portal that served as Nintendo''s official satellite news channel. Players could browse through game previews, secret codes, and company news directly on their TV.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Nintendo HP - 5-31 Gou (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Digital Home Page magazine featuring official Nintendo news and tips.', 'Explore the latest 16-bit game updates and official announcements.', 'Check out the BS Nintendo HP digital magazine for Satellaview.', 'The late-May edition of Nintendo''s satellite newsletter. Discover historical insights into upcoming Super Famicom releases and official developer interviews from the 90s.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Nintendo Power Magazine 107 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Digital lifestyle and gaming magazine delivered via satellite.', 'Read reviews, tips, and articles from the Nintendo Power 107 broadcast.', 'Explore the BS Nintendo Power Magazine 107 on the Satellaview.', 'A Japanese-exclusive digital magazine. It provided in-depth coverage of the SNES ecosystem, including walkthroughs and high-score rankings for the satellite community.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Panel de Pon - Event ''98 (Japan)', '1998', NaN, 'Nintendo', '2', NaN, 'Competitive match-three puzzle game with a fantasy theme.', 'Defeat opponents by clearing blocks and triggering chain reactions.', 'Experience the rare BS Panel de Pon Event ''98 on the SNES.', 'A special tournament edition of the game known in the West as Tetris Attack. Features exclusive puzzles and competitive modes used during the 1998 satellite event.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Parlor! Parlor! - Dai-2-shuu (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Pachinko and slot simulation featuring authentic machine mechanics.', 'Win the most digital credits by mastering the satellite slot machines.', 'Test your luck in BS Parlor! Parlor! for the Satellaview.', 'Volume two of the popular gambling simulation. Experience realistic 16-bit renditions of Japanese parlor machines with exclusive broadcast-only bonus features.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Pokekame Magazine (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Photography-themed digital magazine or interactive hobbyist content.', 'Learn photography tips and explore galleries of 16-bit images.', 'Discover the world of photography in BS Pokekame Magazine for SNES.', 'A unique Satellaview broadcast dedicated to the Pocket Camera and general photography. It featured community galleries and interactive tutorials for creative players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Radical Dreamers (Japan)', '1996', NaN, 'Square', '1', NaN, 'Text-based visual novel adventure set in the Chrono Trigger universe.', 'Infiltrate Viper Manor to steal the legendary Frozen Flame.', 'Play the legendary Chrono Trigger sequel, Radical Dreamers, on SNES.', 'A atmospheric text-adventure where your choices determine the fate of Serge, Kid, and Magil. This 16-bit classic bridges the gap between Chrono Trigger and Chrono Cross.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Satella Walker 2 - Sate Bou o Sukuidase! (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Adventure and mini-game hybrid featuring the Satellaview mascot.', 'Help Sate Bou on his quest to save the satellite world.', 'Join the mascot adventure in BS Satella Walker 2 for the SNES.', 'A quirky and colorful adventure featuring the faces of the Satellaview service. Explore vibrant environments and complete mini-games to progress through the story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Shanghai - Banri no Choujou (Japan)', '1996', NaN, 'Sunsoft', '1', NaN, 'Classic tile-matching puzzle game with a Chinese architecture theme.', 'Clear all Mahjong tiles from the board by finding matching pairs.', 'Master the Great Wall in BS Shanghai: Banri no Choujou on SNES.', 'A polished 16-bit version of the classic puzzle game. Features beautiful backdrops and challenging tile layouts that require sharp observation and strategy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Shin Onigashima - Dai-1-wa - Kataribe no Koya (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Japanese-style visual novel based on traditional folklore and myths.', 'Follow the narrative path of the storyteller to uncover ancient mysteries.', 'Experience the mythic BS Shin Onigashima on the Satellaview.', 'A remake of the Famicom classic. This first chapter introduces the world and characters in a beautifully illustrated 16-bit adventure inspired by Japanese legends.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Shin Onigashima - Dai-2-wa - Kataribe no Koya (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Japanese-style visual novel based on traditional folklore and myths.', 'Continue the mythic journey and solve environmental puzzles to progress.', 'Experience the mythic BS Shin Onigashima on the Satellaview.', 'The second chapter of the saga. Deepen your understanding of the folklore-driven plot through interactive dialogue and point-and-click exploration.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Shin Onigashima - Dai-3-wa - Kataribe no Koya (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Japanese-style visual novel based on traditional folklore and myths.', 'Uncover the secrets of the storyteller''s hut and the dark spirits.', 'Experience the mythic BS Shin Onigashima on the Satellaview.', 'Part three of the episodic adventure. Features improved 16-bit graphics and a hauntingly beautiful soundtrack that brings Japanese myths to life.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Shin Onigashima - Dai-4-wa - Kataribe no Koya (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Japanese-style visual novel based on traditional folklore and myths.', 'Reach the climax of the story and defeat the demonic forces.', 'The grand finale of BS Shin Onigashima on the Satellaview.', 'The concluding chapter of the Kataribe no Koya arc. Witness the dramatic resolution of the story in this high-quality 16-bit visual novel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Sousa Sentai Wappers - Mission 1 - Sousa Sentai Wappers Kenzan (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Top-down action-strategy game featuring a specialized investigation team.', 'Complete the first mission by infiltrating and clearing the enemy zone.', 'Join the elite squad in BS Sousa Sentai Wappers for the SNES.', 'A unique satellite title where you lead a team of investigators. Use specialized equipment and tactical movement to solve cases and defeat criminals in the first mission.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Sousa Sentai Wappers - Mission 2 - Kikiippatsu Kou Wapper no Maki (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Top-down action-strategy game featuring a specialized investigation team.', 'Stop the criminal syndicate before their plan reaches its final stage.', 'Join the elite squad in BS Sousa Sentai Wappers Mission 2 for SNES.', 'The second mission ups the ante with more complex levels and tougher enemy encounters. Coordinate your team''s abilities to survive this 16-bit tactical challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Sousa Sentai Wappers - Soushuu Hen (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Top-down action-strategy game featuring a specialized investigation team.', 'Complete a series of high-stakes missions to restore peace.', 'Experience the full BS Sousa Sentai Wappers collection on SNES.', 'A compilation broadcast that allowed players to experience the best moments and missions from the Wappers series in one 16-bit package.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Special Tee Shot (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Isometric puzzle-golf game with a focus on physics and obstacles.', 'Get the ball into the hole using the fewest strokes possible.', 'Play the prototype of Kirby''s Dream Course: BS Special Tee Shot.', 'Before it was a Kirby game, it was Tee Shot. Navigate surreal isometric courses filled with traps and moving platforms in this clever 16-bit physics puzzler.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Spriggan Powered - BS Version (Japan)', '1996', NaN, 'Naxat Soft', '1', NaN, 'Side-scrolling shoot ''em up with a focus on elemental weapon systems.', 'Destroy the alien fleet and protect the planet from destruction.', 'Unleash elemental power in BS Spriggan Powered for the SNES.', 'A high-octane SHMUP featuring massive sprites and intense action. This special BS version includes exclusive scoring modes and rearranged level structures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS St. Giga PG - 10 Gatsugou (Japan)', '1996', NaN, 'St.GIGA', '1', NaN, 'Digital scheduling and programming guide for the St. Giga satellite service.', 'Check the broadcast schedule and upcoming game releases for October.', 'Explore the BS St. Giga October programming guide on SNES.', 'A piece of gaming history, this interactive guide allowed players to see when their favorite Soundlink and data games would be broadcasted via satellite.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Super Earth Defense Force (Japan)', '1996', NaN, 'Jaleco', '1', NaN, 'Side-scrolling shoot ''em up with a futuristic military theme.', 'Navigate through space and enemy bases to destroy the core.', 'Experience the intense action of BS Super Earth Defense Force.', 'The satellite version of the classic S.E.D.F. Use a variety of upgradeable weapons and master tight patterns to survive waves of 16-bit mechanical enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Super Famicom Wars - BS Ban (Japan)', '1996', NaN, 'Intelligent Systems', '2', NaN, 'Turn-based strategy game featuring military units and territory control.', 'Outmaneuver the enemy army and capture their headquarters.', 'Master the rare BS Super Famicom Wars on the Satellaview.', 'A specialized version of the classic Nintendo strategy series. Features exclusive maps and scenarios that were only playable during the Japanese satellite broadcasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Super Mahjong Taikai (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Mahjong tournament simulation featuring a grand tournament structure.', 'Win the national Mahjong tournament and become the grand champion.', 'Enter the high-stakes world of BS Super Mahjong Taikai on SNES.', 'A deep simulation of the Japanese game. Features a competitive AI and a progression system that rewards skillful play and strategic tile management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Super Ninja-kun (Japan)', '1996', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action platformer featuring a fast and agile ninja.', 'Defeat the rival ninja clans and save the village from an ancient evil.', 'Enjoy high-speed ninja action in BS Super Ninja-kun for the SNES.', 'Control the cute but deadly Ninja-kun. Use speed, jumping skills, and shurikens to clear vibrant levels and defeat massive 16-bit bosses in this satellite version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Super Tsume Shougi 1000 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Logic-based puzzle game focused on Shogi end-game scenarios.', 'Solve 1000 different Shogi puzzles by finding the checkmate move.', 'Master Japanese chess in BS Super Tsume Shougi 1000 for SNES.', 'A massive collection of Tsume (checkmate) puzzles. This satellite broadcast tested players'' knowledge of Shogi strategy across a huge variety of challenging scenarios.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Super Volley II (Japan)', '1996', NaN, 'Nintendo', '2', NaN, 'Arcade-style volleyball simulation with fast-paced 16-bit action.', 'Win the national volleyball tournament by outscoring rival teams.', 'Experience competitive volleyball in BS Super Volley II for SNES.', 'A streamlined satellite version of the popular sports title. Features smooth animations and responsive controls, allowing players to execute spikes and blocks in intense 16-bit matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Sutte Hakkun - ''98 Event Version (Japan)', '1998', NaN, 'Nintendo', '1', NaN, 'Innovative action-puzzle game where you suck and inject colors to change objects.', 'Solve environmental puzzles to reach the goal in this special event version.', 'Master the unique puzzles of BS Sutte Hakkun on Satellaview.', 'A cult classic puzzle game. Use Hakkun to move colors between objects, altering their physics (gravity, movement) to navigate through creative and challenging 16-bit levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Sutte Hakkun - BS Version 2 10-8 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Innovative action-puzzle game where you suck and inject colors to change objects.', 'Complete the specific puzzle sets featured in the October broadcast.', 'Solve the October puzzles in BS Sutte Hakkun Version 2 for SNES.', 'This satellite broadcast offered exclusive levels not found in the retail version, testing players'' logic with new color-based mechanics and platforming challenges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Sutte Hakkun - BS Version 2 6-3 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Innovative action-puzzle game where you suck and inject colors to change objects.', 'Complete the specific puzzle sets featured in the June broadcast.', 'Solve the June puzzles in BS Sutte Hakkun Version 2 for SNES.', 'Part of the episodic puzzle series. Use Hakkun''s unique abilities to manipulate the environment and find the most efficient path to the end of each stage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Sutte Hakkun - Event Version (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Innovative action-puzzle game where you suck and inject colors to change objects.', 'Compete in special timed puzzle challenges during the satellite event.', 'Test your puzzle skills in the BS Sutte Hakkun Event Version.', 'A rare version of the game used for official Satellaview competitions. Players had to solve complex puzzles under time pressure to achieve high scores and rankings.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Tantei Club - Yuki ni Kieta Kako - Chuuhen (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Detective-themed visual novel adventure with a focus on investigation.', 'Solve the middle chapter of the mystery The Past that Vanished in the Snow.', 'Uncover the truth in BS Tantei Club: Yuki ni Kieta Kako.', 'Part of the Famicom Tantei Club series. This 16-bit remake for Satellaview features beautiful art and a gripping narrative as you investigate a cold case in a snowy village.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Tantei Club - Yuki ni Kieta Kako - Kouhen (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Detective-themed visual novel adventure with a focus on investigation.', 'Reach the dramatic conclusion of the Past that Vanished in the Snow mystery.', 'The grand finale of BS Tantei Club: Yuki ni Kieta Kako on SNES.', 'The concluding chapter of the episodic detective story. Use your deduction skills to identify the culprit and solve the dark secrets of the village in this high-quality visual novel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Tantei Club - Yuki ni Kieta Kako - Zenhen (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Detective-themed visual novel adventure with a focus on investigation.', 'Investigate the initial clues of the mystery The Past that Vanished in the Snow.', 'Start the investigation in BS Tantei Club: Yuki ni Kieta Kako.', 'The opening act of the satellite-exclusive mystery. Interview witnesses and search for clues in a beautifully atmospheric 16-bit rendition of a classic Japanese adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Treasure Conflix (Japan)', '1996', NaN, 'Nintendo', '2', NaN, 'Sci-fi strategy and exploration game with a focus on mercenary combat.', 'Navigate the galaxy to find treasures while surviving ship-to-ship battles.', 'Explore the stars in the rare BS Treasure Conflix on Satellaview.', 'A unique Square-developed title. It blends top-down navigation with Mode 7 combat sequences, offering a deep 16-bit sci-fi experience with RPG and strategy elements.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Waiwai Check 3-7 (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Interactive digital magazine or variety show broadcasted for Satellaview.', 'Explore the news, mini-games, and community content for early March.', 'Check out the quirky BS Waiwai Check on the Satellaview.', 'A variety-style program that featured interactive polls, news segments, and small digital activities for the Japanese Super Famicom satellite audience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Wario no Mori - Futatabi (Japan)', '1996', NaN, 'Nintendo', '2', NaN, 'Action-puzzle game based on the Wario''s Woods engine.', 'Clear the forest of monsters by matching colors and using Wario''s moves.', 'Enjoy the satellite-exclusive BS Wario no Mori: Futatabi.', 'A refined version of the classic puzzle game. Take control of Toad and arrange falling monsters and bombs to clear the grid in this addictive 16-bit competition.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Wizardry V - Saika no Chuushin (Japan)', '1996', NaN, 'Sir-Tech', '1', NaN, 'First-person dungeon crawler RPG with a deep turn-based combat system.', 'Navigate the dangerous depths of the labyrinth to find ancient artifacts.', 'Experience the 16-bit classic BS Wizardry V on the Satellaview.', 'A satellite-exclusive version of the legendary RPG. Manage your party, map out treacherous corridors, and engage in tactical combat against deadly fantasy creatures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Yoshi no Panepon - BS Ban (Japan) (En,Ja)', '1996', NaN, 'Nintendo', '2', NaN, 'Competitive match-three puzzle game featuring Yoshi and friends.', 'Defeat opponents by clearing blocks and creating massive chain reactions.', 'Play the rare BS Yoshi no Panepon on the Satellaview.', 'The satellite version of the puzzle classic (Tetris Attack). Features exclusive levels and characters, offering the same addictive gameplay with unique broadcast-only content.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Yung Hakase no Shinsatsu Shitsu - Dai-1-gou (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Interactive psychological quiz or educational simulation.', 'Participate in Dr. Yung''s diagnosis and learn about mental health.', 'Explore the mind in BS Yung Hakase no Shinsatsu Shitsu for SNES.', 'A bizarre and educational medical title. Players interact with Dr. Yung through quizzes and scenarios to receive a psychological diagnosis in a 16-bit format.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Yung Hakase no Shinsatsu Shitsu - Dai-2-gou (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Interactive psychological quiz or educational simulation.', 'Complete the second round of psychological tests and scenarios.', 'Explore the mind in BS Yung Hakase no Shinsatsu Shitsu 2 for SNES.', 'The follow-up to the first medical broadcast. Features new questions, oddball humor, and deeper psychological profiles for the satellite audience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Zootto Mahjong - Event Version (Japan)', '1998', NaN, 'Nintendo', '1', NaN, 'Competitive Mahjong event with a focus on high-score rankings.', 'Win matches against AI or players to climb the official event leaderboards.', 'Play the competitive BS Zootto Mahjong Event Version.', 'A special tournament-focused version of the Mahjong sim. Players competed durante a live broadcast window to prove their mastery and win digital prizes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'BS Zootto Mahjong - Preview Ban (Japan)', '1998', NaN, 'Nintendo', '1', NaN, 'Mahjong simulation preview featuring core gameplay mechanics.', 'Test the Mahjong systems and experience a sample of the full broadcast.', 'Check out the BS Zootto Mahjong Preview Ban on SNES.', 'A demo version released via satellite to generate interest. It features the basic rules and a few practice matches to get players ready for the full event.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bubsy II', '1994', NaN, 'Accolade', '1', NaN, 'Side-scrolling platformer featuring a fast-moving bobcat with a lot of attitude.', 'Navigate through various themed worlds to defeat the evil Otho.', 'Join the wacky adventure in Bubsy II for the Super Nintendo.', 'Bubsy returns with new gadgets, like a portable hole and a diving suit. Explore levels based on history and music in this fast-paced 16-bit platformer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bubsy in Claws Encounters of the Furred Kind', '1993', NaN, 'Accolade', '1', NaN, 'Side-scrolling platformer featuring a fast-moving bobcat with a lot of attitude.', 'Protect the world''s wool supply from the alien Woolies.', 'Experience the original Bubsy in Claws Encounters of the Furred Kind.', 'Known for its massive levels and high speed. Use Bubsy''s glide ability to explore sprawling stages, collect yarn balls, and avoid hazards in this 16-bit classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bug''s Life, A (World) (Pirate)', '1999', NaN, 'Unknown', '1', NaN, 'Side-scrolling action platformer based on the Pixar movie (bootleg version).', 'Lead Flik through various levels to save the ant colony.', 'Play the rare pirate version of A Bug''s Life on the SNES.', 'An unofficial 16-bit port of the popular movie. Despite being a pirate original, it features unique sprite work and platforming levels that attempt to recreate Flik''s journey.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bugs Bunny - Hachamecha Daibouken (Japan)', '1994', NaN, 'Konami', '1', NaN, 'Action platformer featuring the famous Looney Tunes rabbit.', 'Navigate through various movie-set themed worlds to reach the end.', 'Join the wacky fun in Bugs Bunny: Hachamecha Daibouken for SNES.', 'A colorful Japanese-exclusive platformer where Bugs must outsmart familiar foes. Use his agility and classic cartoon antics to clear stages filled with humor and 16-bit charm.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bugs Bunny in Rabbit Rampage (Europe)', '1994', NaN, 'Viacom New Media', '1', NaN, 'Innovative action platformer where the environment changes based on the story.', 'Escape the animator''s traps and confront the pencil that creates the world.', 'Help Bugs Bunny escape the animator in Rabbit Rampage for SNES.', 'A visually impressive game where the animator''s pencil acts as both an ally and an enemy. Experience varied gameplay styles across levels inspired by classic Looney Tunes shorts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bugs Bunny in Rabbit Rampage (USA)', '1994', NaN, 'Viacom New Media', '1', NaN, 'Innovative action platformer where the environment changes based on the story.', 'Escape the animator''s traps and confront the pencil that creates the world.', 'Help Bugs Bunny escape the animator in Rabbit Rampage for SNES.', 'A visually impressive game where the animator''s pencil acts as both an ally and an enemy. Experience varied gameplay styles across levels inspired by classic Looney Tunes shorts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bulls vs Blazers and the NBA Playoffs (Europe)', '1992', NaN, 'Electronic Arts', '2', NaN, 'Classic basketball simulation featuring the 1992 NBA season.', 'Lead the Bulls, Blazers, or other NBA teams to the championship.', 'Experience 16-bit NBA action in Bulls vs Blazers on the SNES.', 'Featuring real players and signature moves, this EA Sports classic offers realistic (for the time) basketball gameplay, complete with the full NBA playoff structure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bulls vs Blazers and the NBA Playoffs (Europe) (Rev A)', '1992', NaN, 'Electronic Arts', '2', NaN, 'Classic basketball simulation featuring the 1992 NBA season.', 'Lead the Bulls, Blazers, or other NBA teams to the championship.', 'Experience 16-bit NBA action in Bulls vs Blazers on the SNES.', 'The revised European version, featuring minor gameplay balancing and bug fixes to provide a smoother basketball simulation for the Super Nintendo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bulls vs Blazers and the NBA Playoffs (USA)', '1992', NaN, 'Electronic Arts', '2', NaN, 'Classic basketball simulation featuring the 1992 NBA season.', 'Lead the Bulls, Blazers, or other NBA teams to the championship.', 'Experience 16-bit NBA action in Bulls vs Blazers on the SNES.', 'Take command of superstars like Michael Jordan and Clyde Drexler. This title set the foundation for future NBA sims with its attention to team stats and authentic 90s atmosphere.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bulls vs Blazers and the NBA Playoffs (USA) (Rev A)', '1992', NaN, 'Electronic Arts', '2', NaN, 'Classic basketball simulation featuring the 1992 NBA season.', 'Lead the Bulls, Blazers, or other NBA teams to the championship.', 'Experience 16-bit NBA action in Bulls vs Blazers on the SNES.', 'The Revised Edition (Rev A) for the USA market, fixing several statistical errors and improving player AI for a more competitive playoff experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Burai - Hachigyoku no Yuushi Densetsu (Japan)', '1993', NaN, 'Riverhillsoft', '1', NaN, 'Traditional turn-based JRPG with a focus on eight distinct protagonists.', 'Unite the eight heroes of the legend to defeat the dark god.', 'Experience the epic Burai: Hachigyoku no Yuushi Densetsu on SNES.', 'A classic JRPG featuring detailed character portraits and a deep story. Manage your party''s equipment and magic across a vast 16-bit world inspired by Japanese mythology.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bushi Seiryuuden - Futari no Yuusha (Japan)', '1993', NaN, 'Game Arts', '1', NaN, 'Unique hybrid of turn-based RPG and side-scrolling action-puzzle.', 'Lead the warrior and his spirit companion to save the world.', 'Discover the Game Freak gem Bushi Seiryuuden for the SNES.', 'Developed by Game Freak, this title blends tactical movement with platforming. Every action counts as a turn, requiring strategic planning to defeat enemies and navigate levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bust-A-Move (USA)', '1994', NaN, 'Taito', '2', NaN, 'Classic bubble-matching puzzle game featuring the characters from Bubble Bobble.', 'Clear the board of colorful bubbles by matching three or more.', 'Enjoy the addictive puzzle action of Bust-A-Move on the SNES.', 'Known as Puzzle Bobble in Japan, this title features cute dinosaurs Bub and Bob. Use the bubble launcher to create chain reactions and clear levels in this timeless 16-bit puzzler.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Bust-A-Move (USA) [Hack by Dragon Eye Studios v0.50] (~Bust-M-Up)', '1994', NaN, 'ROM Hack', '2', NaN, 'Classic bubble-matching puzzle game with fan-made level modifications.', 'Clear the board using new and rearranged puzzle patterns.', 'Play the Bust-M-Up fan mod of Bust-A-Move on the SNES.', 'A technical hack that introduces new challenges and level layouts to the original game, providing a fresh experience for veteran fans of the 16-bit puzzle classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cacoma Knight (Japan)', '1992', NaN, 'Naxat Soft', '1', NaN, 'Action-puzzle game where you draw lines to capture territory.', 'Reclaim the land of Bizyland by surrounding and defeating enemies.', 'Master the territory puzzles in Cacoma Knight for the SNES.', 'Known as Qix-style gameplay. Move your cursor to draw shapes and capture percentages of the screen while avoiding enemies in this colorful 16-bit Japanese title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cacoma Knight in Bizyland (USA)', '1992', NaN, 'Naxat Soft', '1', NaN, 'Action-puzzle game where you draw lines to capture territory.', 'Reclaim the land of Bizyland by surrounding and defeating enemies.', 'Master the territory puzzles in Cacoma Knight for the SNES.', 'The Western release of the Qix-inspired puzzle game. Features diverse themes and boss battles that require quick reflexes and spatial strategy to clear each stage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cal Ripken Jr. Baseball (Europe)', '1992', NaN, 'Equilibrium', '2', NaN, 'Realistic baseball simulation featuring the legendary Cal Ripken Jr.', 'Win the world series by outplaying professional baseball teams.', 'Play ball with Cal Ripken Jr. Baseball for the Super Nintendo.', 'A detailed sports sim with multiple camera angles and roster management. Master pitching, hitting, and fielding to lead your team to the 16-bit championship.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cal Ripken Jr. Baseball (USA)', '1992', NaN, 'Equilibrium', '2', NaN, 'Realistic baseball simulation featuring the legendary Cal Ripken Jr.', 'Win the world series by outplaying professional baseball teams.', 'Play ball with Cal Ripken Jr. Baseball for the Super Nintendo.', 'A detailed sports sim with multiple camera angles and roster management. Master pitching, hitting, and fielding to lead your team to the 16-bit championship.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cal Ripken Jr. Baseball (USA) (Beta)', '1992', NaN, 'Equilibrium', '2', NaN, 'Realistic baseball simulation featuring the legendary Cal Ripken Jr.', 'Win the world series by outplaying professional baseball teams.', 'Check out the Cal Ripken Jr. Baseball Beta version on SNES.', 'A pre-release build of the baseball sim. See early player stats and mechanical tweaks as they were being developed for the final 16-bit release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'California Games II (Europe) (En,Fr,De)', '1994', NaN, 'Epyx', '4', NaN, 'Extreme sports compilation featuring skateboarding, surfing, and more.', 'Achieve the highest scores across multiple California-themed sports events.', 'Experience extreme sports in California Games II for the SNES.', 'Includes events like hang gliding, jet skiing, and bodyboarding. Master the unique controls for each sport to become the ultimate 16-bit extreme champion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'California Games II (Japan) (En,Ja)', '1994', NaN, 'Epyx', '4', NaN, 'Extreme sports compilation featuring skateboarding, surfing, and more.', 'Achieve the highest scores across multiple California-themed sports events.', 'Experience extreme sports in California Games II for the SNES.', 'The Japanese release of the sports classic. Compete in vibrant 16-bit environments and master various disciplines to secure your spot on the leaderboards.', NULL);
