INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cameltry (Japan)', '1989', NaN, 'Taito', '1', NaN, 'Action-puzzle game where you tilt the environment to guide a ball.', 'Guide the ball to the exit of the maze before time runs out.', 'Roll through mazes in the addictive Cameltry for the SNES.', 'A unique 16-bit title where you rotate the entire level instead of the ball. Navigate complex labyrinths filled with obstacles in this fast-paced arcade port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cannon Fodder (Europe)', '1993', NaN, 'Sensible Software', '2', NaN, 'Squad-based strategy and action game with a dark sense of humor.', 'Lead your soldiers through various war zones to complete objectives.', 'Command your troops in the classic Cannon Fodder for the SNES.', 'A high-stakes strategy game where every soldier has a name. Manage your squad carefully to survive dozens of missions in this challenging 16-bit combat title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cannondale Cup (USA)', '1993', NaN, 'American Softworks', '2', NaN, 'Off-road mountain bike racing simulation with sponsorship elements.', 'Win the Cannondale Cup by outracing rivals on treacherous trails.', 'Race mountain bikes in Cannondale Cup for the Super Nintendo.', 'A unique sports title focusing on downhill and cross-country biking. Manage your stamina and vehicle health to cross the finish line first in this 16-bit racer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Capcom''s MVP Football (USA)', '1991', NaN, 'Capcom', '2', NaN, 'American football simulation featuring realistic plays and player stats.', 'Lead your team to victory in the professional football league.', 'Experience pro football in Capcom''s MVP Football for SNES.', 'Capcom''s take on the gridiron. Features detailed playbooks, smooth 16-bit animations, and a focus on the tactical side of American football.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Capcom''s Soccer Shootout (USA)', '1994', NaN, 'Capcom', '2', NaN, 'Fast-paced arcade soccer simulation with special moves and power-ups.', 'Win the international tournament by outscoring the world''s best teams.', 'Score big goals in Capcom''s Soccer Shootout for the SNES.', 'A fan-favorite soccer game known for its fluid gameplay and indoor soccer mode. Execute powerful shots and tactical plays to win the 16-bit cup.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Capcom''s Soccer Shootout (USA) (Beta)', '1994', NaN, 'Capcom', '2', NaN, 'Fast-paced arcade soccer simulation with special moves and power-ups.', 'Win the international tournament by outscoring the world''s best teams.', 'Explore the Capcom''s Soccer Shootout Beta version on SNES.', 'An early build of the classic soccer title. Features initial team balances and gameplay mechanics used during the development of this 16-bit sports hit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain America and the Avengers (Europe)', '1993', NaN, 'Data East', '2', NaN, 'Side-scrolling beat ''em up featuring the iconic Marvel superhero team.', 'Defeat Red Skull and his army to save the world.', 'Assemble the team in Captain America and the Avengers for SNES.', 'Play as Captain America, Iron Man, Hawkeye, or Vision. Use each hero''s unique projectiles and melee attacks to clear waves of 16-bit comic book villains.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain America and the Avengers (USA)', '1993', NaN, 'Data East', '2', NaN, 'Side-scrolling beat ''em up featuring the iconic Marvel superhero team.', 'Defeat Red Skull and his army to save the world.', 'Assemble the team in Captain America and the Avengers for SNES.', 'Play as Captain America, Iron Man, Hawkeye, or Vision. Use each hero''s unique projectiles and melee attacks to clear waves of 16-bit comic book villains.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain Commando (Europe)', '1992', NaN, 'Capcom', '2', NaN, 'Sci-fi belt-scrolling beat ''em up featuring a diverse team of heroes.', 'Protect the Earth from the Scumocide alien invaders.', 'Battle through the future in Captain Commando for the SNES.', 'Control the Captain, Mack the Knife, Ginzu the Ninja, or Baby Head. A faithful arcade port featuring massive mechs to pilot and intense 16-bit action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain Commando (Japan)', '1992', NaN, 'Capcom', '2', NaN, 'Sci-fi belt-scrolling beat ''em up featuring a diverse team of heroes.', 'Protect the Earth from the Scumocide alien invaders.', 'Battle through the future in Captain Commando for the SNES.', 'The Japanese version of the Capcom classic. Face off against genetically modified criminals in a neon-soaked 16-bit future with cooperative multiplayer action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain Commando (USA)', '1992', NaN, 'Capcom', '2', NaN, 'Sci-fi belt-scrolling beat ''em up featuring a diverse team of heroes.', 'Protect the Earth from the Scumocide alien invaders.', 'Battle through the future in Captain Commando for the SNES.', 'Master the art of the dash-attack and utilize environmental weapons. Captain Commando is a standout title in the SNES brawler library for its creative character designs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain Novolin (USA) (En,Fr,Es)', '1992', NaN, 'Spinnaker Software', '1', NaN, 'Educational platformer focused on diabetes management.', 'Navigate through levels while maintaining blood sugar levels.', 'Learn and play with Captain Novolin on the Super Nintendo.', 'A rare health-focused game. Control the superhero Captain Novolin as he fights sugary enemies and teaches players about diet and insulin management in a 16-bit world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain Tsubasa III - Koutei no Chousen (Japan)', '1992', NaN, 'Tecmo', '2', NaN, 'Cinematic soccer RPG where actions are chosen through a menu system.', 'Win the World Youth Cup by defeating rival teams like Germany.', 'Lead Oliver Atom to victory in Captain Tsubasa III for SNES.', 'Experience the Tecmo Cup style gameplay with high-quality 16-bit animations. Use special shots like the Drive Shot and Tiger Shot to dominate international rivals in this cinematic classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain Tsubasa IV - Pro no Rival-tachi (Japan)', '1993', NaN, 'Tecmo', '2', NaN, 'Cinematic soccer RPG featuring a branching storyline and professional leagues.', 'Navigate Tsubasa''s professional career and overcome new rivals.', 'Experience the pro soccer life in Captain Tsubasa IV on SNES.', 'This entry introduces multiple story paths and a deeper focus on club teams. Manage stamina and strategy to execute spectacular special moves in this 16-bit anime-style simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain Tsubasa J - The Way to World Youth (Japan)', '1994', NaN, 'Tecmo', '2', NaN, 'Fast-paced soccer RPG based on the J series of the popular anime.', 'Lead the next generation of Japanese players to world dominance.', 'Play the high-energy Captain Tsubasa J for the Super Famicom.', 'Featuring updated graphics and a more aggressive pace, this title follows the World Youth arc. Master the new character abilities and team tactics to win the 16-bit championship.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Captain Tsubasa V - Hasha no Shougou Campione (Japan)', '1995', NaN, 'Tecmo', '2', NaN, 'The final 16-bit entry, blending traditional soccer gameplay with RPG menus.', 'Win the Italian league and prove you are the ultimate Campione.', 'Become a soccer legend in Captain Tsubasa V for the SNES.', 'A departure from previous entries, offering more direct control over players while retaining cinematic special moves. Follow Tsubasa''s journey in the Serie A in this polished 16-bit finale.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Caravan Shooting Collection (Japan)', '1995', NaN, 'Namcot', '1', NaN, 'Compilation of classic Hudson Soft arcade shoot ''em ups.', 'Achieve the highest score in 2-minute and 5-minute timed challenges.', 'Play the classic Caravan Shooting Collection on the SNES.', 'Includes the 8-bit hits Star Force, Star Soldier, and Hector ''87. Perfect for score-chasers, this collection features faithful 16-bit ports of legendary competitive shooters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Card Master - Rimusaria no Fuuin (Japan)', '1992', NaN, 'Konami', '1', NaN, 'Turn-based JRPG with a unique card-based battle and magic system.', 'Seal the ancient evil by collecting powerful elemental cards.', 'Master the cards in Card Master: Rimusaria no Fuuin for SNES.', 'Known as Arcana in the West. Navigate first-person dungeons and use a strategic card system for combat, featuring beautiful 16-bit artwork and a deep fantasy narrative.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Carrier Aces (Europe)', '1990', NaN, 'Synergistic Software', '1', NaN, 'Flight combat simulation set during World War II carrier operations.', 'Complete carrier-based missions including dogfights and bombing runs.', 'Take to the skies in the WWII sim Carrier Aces for the SNES.', 'Features a split-screen view for taking off and landing. Pilot various Allied and Axis planes in tactical 16-bit aerial combat across the Pacific theater.', NULL);
