INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Casper (Europe)', '1996', NaN, 'Bit Managers', '1', NaN, 'Action-adventure based on the 1995 film featuring the friendly ghost.', 'Help Casper find his way and protect his friends from Kat''s father.', 'Explore the haunted Whipstaff Manor in Casper for SNES.', 'Use Casper''s ghostly abilities to morph into different objects to solve puzzles. Navigate the detailed 16-bit environments while avoiding the Ghostly Trio in this movie tie-in.', NULL);
