INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Castlevania - Dracula X - Remove final boss room pits', '1995', NaN, 'ROM Hack', '1', NaN, 'Side-scrolling action platformer with a fan-made modification for fairness.', 'Defeat Dracula without falling into the frustrating floor pits.', 'Play the Castlevania: Dracula X Pit-Fix mod on SNES.', 'This hack removes the controversial pits in the final boss room against Dracula, focusing the challenge purely on combat and timing rather than accidental environmental deaths.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Castlevania - Dracula X (USA)', '1995', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer featuring Richter Belmont.', 'Rescue Maria and Annette and defeat Count Dracula.', 'Face the darkness in Castlevania: Dracula X for the SNES.', 'A reimagining of Rondo of Blood. Features intense difficulty, branching paths, and incredible 16-bit graphics and music. Use the whip and sub-weapons to survive the demonic castle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Castlevania - Vampire''s Kiss (Europe)', '1995', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer featuring Richter Belmont.', 'Rescue Maria and Annette and defeat Count Dracula.', 'Experience Vampire''s Kiss, the European Castlevania classic.', 'The PAL version of Dracula X. Battle through gothic stages, master the Item Crash moves, and experience some of the most challenging platforming in the 16-bit era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'CB Chara Wars - Ushinawareta Gag (Japan)', '1992', NaN, 'Bandai', '2', NaN, 'Top-down action game featuring SD (chibi) versions of Go Nagai characters.', 'Stop the lost gag crisis and defeat the bizarre enemies.', 'Join the wacky fight in CB Chara Wars for the Super Famicom.', 'Control iconic characters like Devilman and Mazinger Z in a cute, humorous style. Fight through waves of enemies and bosses in this unique 16-bit crossover adventure.', NULL);
