INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Championship Pool (Europe)', '1993', NaN, 'Bit Managers', '2', NaN, 'Top-down pool and billiards simulation with realistic physics.', 'Win the tournament by clearing the table in various pool disciplines.', 'Master the cue in Championship Pool for the SNES.', 'Includes 8-ball, 9-ball, and snooker. Featuring a precision aiming system and tournament progression, it''s a solid 16-bit simulation for billiards fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Championship Pool (USA)', '1993', NaN, 'Bit Managers', '2', NaN, 'Top-down pool and billiards simulation with realistic physics.', 'Win the tournament by clearing the table in various pool disciplines.', 'Master the cue in Championship Pool for the SNES.', 'Includes 8-ball, 9-ball, and snooker. Featuring a precision aiming system and tournament progression, it''s a solid 16-bit simulation for billiards fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Championship Soccer ''94 (USA) (En,Fr,De,It)', '1994', NaN, 'Sculptured Software', '2', NaN, 'Soccer simulation focusing on speed and arcade-style play.', 'Outscore your opponents in various international leagues.', 'Play fast-paced soccer in Championship Soccer ''94 for SNES.', 'A localized version of Sensible Soccer. Known for its zoomed-out view and tight controls, allowing for tactical 16-bit gameplay and spectacular goals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chaos Engine, The (Europe)', '1994', NaN, 'The Bitmap Brothers', '2', NaN, 'Top-down run-and-gun shooter set in a steampunk world.', 'Navigate through the metal labyrinth and destroy the Chaos Engine.', 'Experience the cult classic The Chaos Engine on SNES.', 'Known as Soldiers of Fortune in the US. Choose two mercenaries with unique skills and fight through Victorian-era levels filled with puzzles and deadly machines.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chaos Seed - Fuusui Kairouki (Japan)', '1996', NaN, 'Neverland', '1', NaN, 'Deep dungeon-crawling RPG with environmental manipulation and Feng Shui.', 'Explore ancient ruins and balance the spiritual energy of the world.', 'Discover the complex RPG Chaos Seed for the Super Famicom.', 'A unique blend of action-RPG and simulation. Build rooms, manage resources, and engage in real-time combat while following a branching narrative in a beautiful 16-bit world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chavez (USA)', '1993', NaN, 'Telegames', '2', NaN, 'Realistic boxing simulation featuring the Mexican champion Julio César Chávez.', 'Climb the rankings and win the world title belt.', 'Step into the ring with Chavez for the Super Nintendo.', 'A Spanish-language localized version of Riddick Bowe Boxing. Features a career mode where you train your fighter and execute tactical combos in 16-bit matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chavez (USA) (Beta)', '1993', NaN, 'Telegames', '2', NaN, 'Realistic boxing simulation featuring the Mexican champion Julio César Chávez.', 'Climb the rankings and win the world title belt.', 'Explore the Chavez Beta and its development on SNES.', 'A pre-release build of the boxing title. Test early AI behaviors and sprite animations used during the creation of this 16-bit sports game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chavez II (USA)', '1994', NaN, 'Telegames', '2', NaN, 'The sequel to the boxing hit, featuring updated rosters and moves.', 'Defend your title against a new generation of boxers.', 'Experience the intense sequel Chavez II on the SNES.', 'Improves on the original with faster gameplay and more detailed fighter sprites. Continue your legacy in the ring and master the sweet science of 16-bit boxing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chessmaster, The (Europe)', '1991', NaN, 'Software Toolworks', '2', NaN, 'Traditional chess simulation with multiple difficulty levels and tutorials.', 'Checkmate the opponent''s king using strategic 16-bit chess moves.', 'Master the board in The Chessmaster for the SNES.', 'A robust chess engine for the Super Nintendo. Featuring various board styles, a dedicated teaching mode, and a range of AI personalities from novice to grandmaster level.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chessmaster, The (Japan)', '1991', NaN, 'Software Toolworks', '2', NaN, 'Traditional chess simulation with multiple difficulty levels and tutorials.', 'Checkmate the opponent''s king using strategic 16-bit chess moves.', 'Master the board in The Chessmaster for the SNES.', 'The Japanese edition of the classic chess title. Offers a clean interface and deep strategic gameplay for fans of the traditional board game on the 16-bit console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chessmaster, The (USA)', '1991', NaN, 'Software Toolworks', '2', NaN, 'Traditional chess simulation with multiple difficulty levels and tutorials.', 'Checkmate the opponent''s king using strategic 16-bit chess moves.', 'Master the board in The Chessmaster for the SNES.', 'Test your tactical skills against the Chessmaster. Analyze your games, solve chess puzzles, and compete against a variety of virtual opponents in this comprehensive simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chester Cheetah - Too Cool to Fool (USA)', '1992', NaN, 'Virgin Games', '1', NaN, 'Side-scrolling platformer featuring the smooth Cheetos mascot.', 'Collect the hidden parts of your scooter and escape the zoo.', 'Join the cool cat in Chester Cheetah: Too Cool to Fool on SNES.', 'A vibrant platformer where Chester uses his cool factor to navigate obstacles. Collect Cheetos snacks for power-ups and avoid the zookeeper''s traps in this 16-bit snack-themed adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chester Cheetah - Wild Wild Quest (USA)', '1992', NaN, 'Virgin Games', '1', NaN, 'Side-scrolling platformer with a map-based progression system.', 'Travel across the USA to reclaim Chester''s stolen map.', 'Go on a journey in Chester Cheetah: Wild Wild Quest for SNES.', 'The sequel features more diverse environments across America. Dash through levels, avoid enemies, and use special items to recover the map pieces in this fast-paced 16-bit platformer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chester Cheetah - Wild Wild Quest (USA) (Beta)', '1992', NaN, 'Virgin Games', '1', NaN, 'Side-scrolling platformer with a map-based progression system.', 'Travel across the USA to reclaim Chester''s stolen map.', 'Explore the Chester Cheetah: Wild Wild Quest Beta on SNES.', 'A pre-release version of the game. See early level designs and mechanical tweaks that were being tested before Chester''s final 16-bit cross-country quest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chibi Maruko-chan - Harikiri 365 Nichi no Maki (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Digital board game based on the popular Chibi Maruko-chan anime.', 'Participate in daily activities and mini-games to win the year-long event.', 'Enjoy family fun in Chibi Maruko-chan: Harikiri 365 Nichi on SNES.', 'Follow Maruko through a full year of seasonal events. Featuring charming 16-bit graphics and voices from the anime, this title focuses on fun, accessible mini-games for all ages.', NULL);
