INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Choplifter III - Rescue Survive (Europe)', '1992', NaN, 'Beam Software', '1', NaN, 'Side-scrolling shooter where you pilot a combat helicopter.', 'Rescue hostages from enemy territory while surviving heavy fire.', 'Save the day in Choplifter III: Rescue Survive for the SNES.', 'The classic arcade series reaches its 16-bit peak. Pilot your chopper through war zones, manage fuel and ammo, and return prisoners to base in intense, multi-layered levels.', NULL);
