INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Choplifter III - Rescue Survive (USA)', '1992', NaN, 'Beam Software', '1', NaN, 'Side-scrolling shooter where you pilot a combat helicopter.', 'Rescue hostages from enemy territory while surviving heavy fire.', 'Save the day in Choplifter III: Rescue Survive for the SNES.', 'Master the delicate controls of the rescue chopper. This entry adds more weapons and specialized gear to help you survive the toughest 16-bit combat missions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Choplifter III - Rescue Survive (USA) (Beta)', '1992', NaN, 'Beam Software', '1', NaN, 'Side-scrolling shooter where you pilot a combat helicopter.', 'Rescue hostages from enemy territory while surviving heavy fire.', 'Check out the Choplifter III Beta version for the SNES.', 'An early build of the helicopter action game. Discover initial mission layouts and difficulty balancing used during the development of this 16-bit rescue classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chou Aniki - Bakuretsu Rantou Hen (Japan)', '1995', NaN, 'Fixer', '2', NaN, 'Bizarre one-on-one fighting game featuring muscular, surreal characters.', 'Defeat the strange warriors of the empire to prove your strength.', 'Experience the madness of Chou Aniki: Bakuretsu Rantou Hen.', 'A cult classic known for its bodybuilding aesthetic and surreal humor. Master the unique moves of Idaten and Benten in this eccentric 16-bit fighter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chou Mahou Tairiku Wozz (Japan)', '1991', NaN, 'Renovation Products', '1', NaN, 'Turn-based JRPG featuring a steampunk meets fantasy world.', 'Stop the invasion of the Wozz world using magic and machines.', 'Explore the unique Chou Mahou Tairiku Wozz on the SNES.', 'Featuring beautiful 16-bit visuals and a vehicle-crafting system. Lead a trio of heroes summoned from Earth to save a magical land in this deep and creative RPG.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chou Mahou Tairiku Wozz (Japan) [En by TransCorp v1.0] (~Magical Land of Wozz, The)', '1991', NaN, 'Renovation Products', '1', NaN, 'Turn-based JRPG featuring a steampunk meets fantasy world.', 'Experience the epic story of Wozz with a full English translation.', 'Play The Magical Land of Wozz in English on the SNES.', 'The definitive fan translation of this hidden gem. Now Western players can enjoy the deep story, humor, and innovative crafting mechanics of this 16-bit RPG masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chou Makai Taisen! Dorabot-chan (Japan)', '1993', NaN, 'Bandai', '1', NaN, 'Side-scrolling action platformer featuring a young dragon boy.', 'Navigate through monster-filled levels to defeat the evil sorcerer.', 'Join the dragon boy in Chou Makai Taisen! Dorabot-chan.', 'A charming Japanese platformer where you use dragon powers to defeat enemies. Features vibrant 16-bit graphics and creative level designs for fans of the genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chou Makaimura (Japan)', '1991', NaN, 'Capcom', '1', NaN, 'Side-scrolling action platformer known for its high difficulty.', 'Rescue Princess Prin-Prin from the demon realm as the knight Arthur.', 'Face the ultimate challenge in Chou Makaimura for the SNES.', 'Known as Super Ghouls ''n Ghosts in the West. Master the double-jump, upgrade your armor, and survive the punishing 16-bit levels to defeat the Emperor Sardius.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Choujikuu Yousai Macross - Scrambled Valkyrie (Japan)', '1993', NaN, 'Zemekis', '1', NaN, 'Horizontal shoot ''em up with transforming mechs and Mode 7 effects.', 'Destroy the Zentradi forces to save the Earth from destruction.', 'Experience Macross: Scrambled Valkyrie, a top-tier SNES shooter.', 'Pilot three different transforming Valkyries (Fighter, Gerwalk, Battroid). Features incredible 16-bit graphics, multiple fire modes, and a soundtrack that captures the spirit of the anime.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Choukou Goukami Xardion (Japan)', '1993', NaN, 'Athena', '1', NaN, 'Side-scrolling action-platformer featuring customizable giant robots.', 'Stop the mechanical threat of Xardion by mastering three unique mechs.', 'Control giant robots in Choukou Goukami Xardion for SNES.', 'Switch between three mechs—Triton, Alunos, and Panthera—each with distinct abilities and leveling systems. A deep and atmospheric 16-bit sci-fi adventure with RPG elements.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Bugfix and Uncensoring', '1995', NaN, 'ROM Hack', '1', NaN, 'Masterpiece turn-based JRPG with technical fixes and restored content.', 'Experience the original vision of the game without bugs or censorship.', 'Play the Uncensored & Bugfixed Chrono Trigger on SNES.', 'This version restores the original Japanese dialogue context (like references to alcohol) and fixes long-standing technical bugs, providing the most pure 16-bit experience possible.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Complete', '1995', NaN, 'ROM Hack', '1', NaN, 'Masterpiece turn-based JRPG featuring a compilation of best fan fixes.', 'Journey through time with the most complete and polished version available.', 'Experience Chrono Trigger Complete, the ultimate fan version.', 'A comprehensive mod that combines bug fixes, script translations, and graphical touch-ups into one definitive 16-bit package for the SNES.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Crimson Echoes (Fan Made Game)', '2004', NaN, 'Fan Made', '1', NaN, 'Epic fan-made sequel featuring a brand new story and world map.', 'Follow the heroes five years after the original game to stop a new threat.', 'Play the legendary fan-sequel Chrono Trigger: Crimson Echoes.', 'A massive project by Kajar Laboratories. Featuring dozens of hours of gameplay, new eras, and deep character development, it bridges the gap between Chrono Trigger and Chrono Cross.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Flames of Eternity RC7C', '2009', NaN, 'Fan Made', '1', NaN, 'Massive fan-made expansion and spiritual successor to Crimson Echoes.', 'Navigate through new timelines and stop a temporal disaster.', 'Experience the epic Flames of Eternity RC7C on the SNES.', 'Building upon the Crimson Echoes foundation, this version polishes the gameplay, adds new music, and completes the ambitious story started by the fan community.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Master Quest', '2002', NaN, 'Fan Made', '1', NaN, 'Enhanced difficulty mod with redesigned dungeons and boss encounters.', 'Test your mastery of the game with more complex and strategic battles.', 'Challenge yourself with Chrono Trigger: Master Quest on SNES.', 'A complete overhaul for veterans. Dungeons feature new layouts and bosses require specific tactics and dual/triple tech management to defeat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Master Quest Jr. version', '2002', NaN, 'Fan Made', '1', NaN, 'A slightly more accessible version of the Master Quest difficulty mod.', 'Enjoy a significant challenge that isn''t as punishing as the full Master Quest.', 'Play Chrono Trigger: Master Quest Jr. for a balanced challenge.', 'Retains the new dungeon designs and AI improvements of the Master Quest but with more forgiving damage values, perfect for a fresh 16-bit experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Music Library (Japan) (BS) [En by Terminus v1.00e]', '1995', NaN, 'Square', '1', NaN, 'Digital music player featuring the iconic soundtrack, now in English.', 'Listen to the legendary Yasunori Mitsuda score with translated menus.', 'Enjoy the BS Chrono Trigger Music Library in English on SNES.', 'The translated version of the rare Satellaview broadcast. It allows players to enjoy the high-quality SNES soundtrack in a dedicated, interactive interface.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Prophet''s Guile', '2008', NaN, 'Fan Made', '1', NaN, 'Story-driven fan expansion focusing on the character Magus.', 'Experience the events of the game from the perspective of the Prophet.', 'Uncover the secrets of Magus in Chrono Trigger: Prophet''s Guile.', 'A standalone side-story created by Kajar Laboratories. Follow Magus during his time in the Kingdom of Zeal as he plots to destroy Lavos from within.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Schala Edition', '2008', NaN, 'ROM Hack', '1', NaN, 'Special edition mod that makes Schala a playable character.', 'Rescue Schala from her fate and include her in your time-traveling party.', 'Play as Schala in the unique Chrono Trigger: Schala Edition.', 'A fan-favorite mod that alters the story to allow Schala to join the team. Includes new dialogue, specialized techs for her, and a modified ending.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger - Start out with Marle', '1995', NaN, 'ROM Hack', '1', NaN, 'Turn-based JRPG with a party-swapping mod to start with different characters.', 'Journey through time to prevent the global apocalypse starting with Marle.', 'Start your journey with Marle in this Chrono Trigger SNES mod.', 'A specialized fan modification that alters the starting party. Experience the early game with Marle’s abilities from the beginning while maintaining the legendary narrative.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger (Japan)', '1995', NaN, 'Square', '1', NaN, 'Masterpiece turn-based JRPG featuring time travel and multiple endings.', 'Travel across different eras to save the future of the planet.', 'Experience the original Chrono Trigger (Japan) on the Super Famicom.', 'The legendary collaboration between Final Fantasy and Dragon Quest creators. Features a seamless battle system and a story that spans from prehistory to the end of time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger (Japan) (Sample)', '1995', NaN, 'Square', '1', NaN, 'Masterpiece turn-based JRPG featuring time travel and multiple endings.', 'Explore a pre-release version of the game used for demonstration.', 'Check out the rare Chrono Trigger Sample version on SNES.', 'A fascinating piece of history. This Japanese sample version contains specific segments used for store displays before the final 16-bit release in 1995.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger (USA)', '1995', NaN, 'Square', '1', NaN, 'Masterpiece turn-based JRPG featuring time travel and multiple endings.', 'Travel across different eras to save the future of the planet.', 'Play the legendary Chrono Trigger (USA) on the Super Nintendo.', 'Widely considered one of the greatest RPGs of all time. Follow Crono and friends through time. Features 13 different endings based on your choices and timing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger (USA) [En by Chrono Compendium v1.01]', '1995', NaN, 'ROM Hack', '1', NaN, 'Masterpiece turn-based JRPG featuring a refined fan-made translation.', 'Experience the epic story with a more accurate and polished script.', 'Play the definitive Chrono Trigger translation by Chrono Compendium.', 'A dedicated fan project that re-translates the script to be more faithful to the creators'' intent, fixing localization errors from the original 1995 release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger (USA) [En by Doctor L v1.01]', '1995', NaN, 'ROM Hack', '1', NaN, 'Masterpiece turn-based JRPG featuring a refined fan-made translation.', 'Experience the epic story with a more accurate and polished script.', 'Enjoy the Doctor L translation of Chrono Trigger for the SNES.', 'A high-quality re-translation effort focusing on natural dialogue and technical fixes, providing a fresh perspective on the classic 16-bit time-travel narrative.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger (USA) [Hack by Kajar Laboratories Demo 2] (~Chrono Trigger - Crimson Echos)', '2004', NaN, 'Fan Made', '1', NaN, 'Epic fan-made sequel featuring a brand new story and world map.', 'Follow the heroes five years after the original game to stop a new threat.', 'Explore the Crimson Echoes Demo by Kajar Laboratories.', 'An early look at the massive fan-sequel project. It showcases the new eras, characters, and improved battle mechanics that define this legendary 16-bit mod.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger (USA) [Hack by Kajar Laboratories v1.0] (~Chrono Trigger - Prophet''s Guile)', '2008', NaN, 'Fan Made', '1', NaN, 'Story-driven fan expansion focusing on the character Magus.', 'Experience the events of the game from the perspective of the Prophet.', 'Uncover the secrets of Magus in Chrono Trigger: Prophet''s Guile.', 'A standalone side-story. Lead Magus through the halls of Zeal as he uses his future knowledge to manipulate events and prepare for his final battle with Lavos.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger (USA) [Hack by Kajar Laboratories v2.1] (~Chrono Trigger Coliseum)', '2008', NaN, 'Fan Made', '1', NaN, 'Combat-focused mod featuring an arena-style gauntlet.', 'Defeat waves of increasingly difficult enemies to earn rare rewards.', 'Test your combat skills in Chrono Trigger Coliseum for SNES.', 'A modification that focuses entirely on the battle system. Face off against every boss and enemy in the game in a challenging, tournament-style 16-bit format.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger 1.01', '1995', NaN, 'Square', '1', NaN, 'Masterpiece turn-based JRPG with minor technical and text fixes.', 'Journey through time to prevent the global apocalypse caused by Lavos.', 'Play the refined Chrono Trigger 1.01 version on the SNES.', 'A minor update to the original release that addresses small bugs and typos, ensuring the smoothest possible 16-bit RPG experience for purists.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger 6-Letter Name', '1995', NaN, 'ROM Hack', '1', NaN, 'Turn-based JRPG mod that allows for longer character naming conventions.', 'Journey through time with custom 6-letter names for your party.', 'Customize your team in Chrono Trigger 6-Letter Name mod.', 'A technical hack that expands the character name limit from 5 to 6 characters, allowing fans to use more accurate names (like Magus) without abbreviations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger Devolution', '1999', NaN, 'ROM Hack', '1', NaN, 'Enhanced version of the original game with restored content and features.', 'Save the world from Lavos with modern quality-of-life improvements.', 'Experience the Chrono Trigger Devolution mod on the SNES.', 'A comprehensive best of version that integrates features from later ports (like the DS version) back into the original 16-bit SNES engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger Impossible', '2000', NaN, 'ROM Hack', '1', NaN, 'Extreme difficulty hack for veteran players seeking a brutal challenge.', 'Survive the journey through time with vastly stronger enemies.', 'Face the ultimate challenge in Chrono Trigger Impossible.', 'Every enemy and boss has been completely redesigned with new AI and higher stats. Only for those who have fully mastered every mechanic of the original game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger Lavos'' Awakening (Hardtype)', '2002', NaN, 'ROM Hack', '1', NaN, 'Hardcore rebalance mod focusing on a darker atmosphere and higher difficulty.', 'Stop Lavos in a world where the stakes and the enemies are higher.', 'Experience the grueling Lavos'' Awakening Hardtype mod.', 'Increases tactical depth. You''ll need to master every dual and triple tech to survive the revamped boss encounters and environmental hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger Platinum', '2003', NaN, 'ROM Hack', '1', NaN, 'Comprehensive overhaul mod with new items, rebalanced techs, and secrets.', 'Explore a familiar world with thousands of mechanical improvements.', 'Play the definitive Chrono Trigger Platinum edition on SNES.', 'A Gold Standard mod that balances the entire game. It buffs underused characters, adds new equipment, and makes the late-game content more engaging.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chrono Trigger plus 2.6', '2006', NaN, 'ROM Hack', '1', NaN, 'Massive expansion mod adding new side quests and lore-friendly content.', 'Experience the classic story with new areas and characters.', 'Explore more of the world in Chrono Trigger plus 2.6.', 'This mod integrates new events, restores cut content from the original development, and adds meaningful side stories that flesh out the 16-bit world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chuck Rock (Europe)', '1991', NaN, 'Core Design', '1', NaN, 'Side-scrolling platformer featuring a caveman with a unique headbutt attack.', 'Rescue your girlfriend from the rival caveman clan.', 'Join the prehistoric fun in Chuck Rock for the Super Nintendo.', 'Control Chuck as he headbutts his way through dinosaurs and prehistoric traps. Use rocks to reach higher platforms and defeat bosses in this classic 16-bit platformer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chuck Rock (USA)', '1991', NaN, 'Core Design', '1', NaN, 'Side-scrolling platformer featuring a caveman with a unique headbutt attack.', 'Rescue your girlfriend from the rival caveman clan.', 'Join the prehistoric fun in Chuck Rock for the Super Nintendo.', 'Control Chuck as he headbutts his way through dinosaurs and prehistoric traps. Use rocks to reach higher platforms and defeat bosses in this classic 16-bit platformer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Chuck Rock (USA) (Beta)', '1991', NaN, 'Core Design', '1', NaN, 'Side-scrolling platformer featuring a caveman with a unique headbutt attack.', 'Rescue your girlfriend from the rival caveman clan.', 'Check out the Chuck Rock Beta and its development on SNES.', 'A pre-release build of the prehistoric platformer. Discover early level layouts and sprite work that were adjusted before the final 16-bit retail release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Circuit USA (Japan)', '1991', NaN, 'Nintendo', '1', NaN, 'Futuristic racing game featuring high-speed circuits across the USA.', 'Win the national racing championship by outperforming rival drivers.', 'Race across America in the fast-paced Circuit USA for SNES.', 'Utilizing Mode 7 effects for a sense of speed, this title challenges players to master various tracks and weather conditions in a competitive 16-bit racing circuit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Civilization - Sekai Shichi Daibunmei (Japan)', '1993', NaN, 'MicroProse', '1', NaN, 'Deep grand strategy and empire-building simulation.', 'Lead your civilization from the Stone Age to the Space Age.', 'Build an empire in the SNES version of Sid Meier''s Civilization.', 'A surprisingly deep port of the PC classic. Manage resources, research technologies, and engage in diplomacy or war to become the dominant power on Earth.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Civilization (USA)', '1994', NaN, 'MicroProse', '1', NaN, 'Deep grand strategy and empire-building simulation.', 'Lead your civilization from the Stone Age to the Space Age.', 'Build an empire in the SNES version of Sid Meier''s Civilization.', 'A surprisingly deep port of the PC classic. Manage resources, research technologies, and engage in diplomacy or war to become the dominant power on Earth.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Civilization (USA) (Beta)', '1994', NaN, 'MicroProse', '1', NaN, 'Deep grand strategy and empire-building simulation.', 'Lead your civilization from the Stone Age to the Space Age.', 'Explore the Civilization Beta version for the Super Nintendo.', 'A pre-release version of the strategy epic. See how the complex UI and mechanics were adapted for the SNES controller during development.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Classic Kong', '1981', NaN, 'Nintendo', '1', NaN, 'Arcade-style platformer inspired by the 1981 classic Donkey Kong.', 'Climb the girders and rescue the girl from the giant ape.', 'Experience the homebrew tribute Classic Kong on the SNES.', 'A faithful recreation of the original arcade gameplay with updated 16-bit graphics. Dodge barrels, climb ladders, and time your jumps to reach the top.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Classic Road (Japan)', '1993', NaN, 'Hect', '1', NaN, 'Realistic horse racing simulation with betting and stable management.', 'Train your horses and win the most prestigious races in Japan.', 'Master the tracks in Classic Road for the Super Famicom.', 'A deep simulation where you manage every aspect of a racehorse''s career. Study the odds, choose your jockey, and aim for the Triple Crown.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Classic Road II (Japan)', '1995', NaN, 'Hect', '1', NaN, 'Realistic horse racing simulation with betting and stable management.', 'Train your horses and win the most prestigious races in Japan.', 'Master the tracks in Classic Road II for the Super Famicom.', 'The sequel expands on the original with more detailed stats, new breeding mechanics, and improved 16-bit visuals for horse racing enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Clay Fighter - Tournament Edition (USA)', '1993', NaN, 'Interplay', '2', NaN, 'One-on-one fighting game featuring stop-motion clay animation.', 'Win the tournament against eccentric clay-based warriors.', 'Fight in the arena with Clay Fighter: Tournament Edition.', 'A specialized version of the first game with improved balance and new stages. Features the same wacky characters like Bad Mr. Frosty and Bonker the Clown.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Clay Fighter (Europe)', '1993', NaN, 'Interplay', '2', NaN, 'One-on-one fighting game featuring stop-motion clay animation.', 'Defeat the other clay fighters to prove you are the best in the land.', 'Experience the wacky Clay Fighter on the Super Nintendo.', 'Famous for its unique Claymation art style and humorous tone. Master absurd special moves in this 16-bit fighter that parodies the genre''s tropes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Clay Fighter (USA)', '1993', NaN, 'Interplay', '2', NaN, 'One-on-one fighting game featuring stop-motion clay animation.', 'Defeat the other clay fighters to prove you are the best in the land.', 'Experience the wacky Clay Fighter on the Super Nintendo.', 'Choose from a cast of bizarre characters and battle across colorful stages. A fun and accessible fighter with a distinct 16-bit visual identity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Clay Fighter 2 - Judgment Clay (Europe)', '1994', NaN, 'Interplay', '2', NaN, 'One-on-one fighting game featuring new characters and gameplay mechanics.', 'Survive the Judgment Clay tournament and defeat the boss.', 'The clay combat continues in Clay Fighter 2 for the SNES.', 'Featuring a new cast and a slightly darker tone. This sequel introduces more complex combos and refined 16-bit clay animation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Clay Fighter 2 - Judgment Clay (USA)', '1994', NaN, 'Interplay', '2', NaN, 'One-on-one fighting game featuring new characters and gameplay mechanics.', 'Survive the Judgment Clay tournament and defeat the boss.', 'The clay combat continues in Clay Fighter 2 for the SNES.', 'Battle with characters like Tiny and Nana Hacklease. This entry focuses on faster gameplay and more punny humor in its 16-bit combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Claymates (Europe)', '1993', NaN, 'Interplay', '1', NaN, 'Puzzle-platformer where you morph into different clay animals.', 'Navigate through the neighborhood to rescue your father.', 'Morph and explore in the unique Claymates for the SNES.', 'A creative title from Interplay. Change into a cat, a fish, or a mouse to solve environmental puzzles and defeat enemies in a vibrant 16-bit world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Claymates (USA)', '1993', NaN, 'Interplay', '1', NaN, 'Puzzle-platformer where you morph into different clay animals.', 'Navigate through the neighborhood to rescue your father.', 'Morph and explore in the unique Claymates for the SNES.', 'Use each animal''s unique abilities (like the cat''s climbing or the fish''s swimming) to uncover secrets and progress through diverse stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Claymates (USA) (Sample)', '1993', NaN, 'Interplay', '1', NaN, 'Puzzle-platformer where you morph into different clay animals.', 'Navigate through the neighborhood to rescue your father.', 'Check out the Claymates Sample version on the SNES.', 'A demonstration build used to showcase the morphing mechanics and the high-quality 16-bit clay graphics before the official release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cliffhanger (Europe)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Action-adventure platformer based on the 1993 Sylvester Stallone film.', 'Rescue your friends and defeat the terrorists on the mountain.', 'Battle through the cold in Cliffhanger for the Super Nintendo.', 'Navigate treacherous mountain slopes, climb cliffs, and engage in hand-to-hand combat in this 16-bit movie tie-in.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cliffhanger (USA)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Action-adventure platformer based on the 1993 Sylvester Stallone film.', 'Rescue your friends and defeat the terrorists on the mountain.', 'Battle through the cold in Cliffhanger for the Super Nintendo.', 'Features both platforming and beat ''em up sections. Survive avalanches and face off against bosses in the rugged 16-bit wilderness.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Clock Tower (Japan)', '1995', NaN, 'Human Entertainment', '1', NaN, 'Survival horror adventure with point-and-click exploration.', 'Escape the Barrows mansion while avoiding the Scissorman.', 'Experience the original survival horror, Clock Tower, on SNES.', 'A cult classic known for its terrifying atmosphere. Hide, solve puzzles, and make life-or-death choices in this 16-bit pioneer of the horror genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Clock Tower (Japan) [En by Aeon Genesis v1.01]', '1995', NaN, 'Human Entertainment', '1', NaN, 'Survival horror adventure with point-and-click exploration.', 'Escape the mansion and uncover the secrets of the Barrows family in English.', 'Play the English translation of Clock Tower on the SNES.', 'The definitive fan translation by Aeon Genesis. Experience the full story and chilling tension of this Japanese horror masterpiece in English for the first time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Clockwerx (Japan)', '1994', NaN, 'T&E Soft', '1', NaN, 'Puzzle game where you rotate clock gears to guide a spark.', 'Connect the gears correctly to reach the exit before time runs out.', 'Solve the mechanical puzzles of Clockwerx for the Super Famicom.', 'A fast-paced test of logic and timing. Navigate through dozens of levels filled with obstacles that require precise gear management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Clue (USA)', '1992', NaN, 'Parker Brothers', '4', NaN, 'Digital board game based on the classic mystery franchise.', 'Solve the murder by deducing the culprit, weapon, and room.', 'Solve the mystery in Clue for the Super Nintendo.', 'A faithful 16-bit adaptation of the board game. Move through the mansion, gather clues, and use the process of elimination to win.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'College Football USA ''97 - The Road to New Orleans (USA)', '1996', NaN, 'EA Sports', '2', NaN, 'American football simulation focusing on the college league.', 'Lead your favorite college team to victory in the Sugar Bowl.', 'Experience college football in College Football USA ''97 on SNES.', 'Part of the EA Sports series. Features real college teams, authentic playbooks, and the quest for the #1 ranking in the 16-bit era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'College Slam (USA)', '1996', NaN, 'Acclaim', '4', NaN, 'Arcade-style 2-on-2 basketball featuring college teams and high-flying dunks.', 'Win the tournament by outscoring rival college teams with power-ups.', 'Experience the madness of College Slam on the Super Nintendo.', 'A college-themed spin-off of NBA Jam. Featuring big-head mode, massive dunks, and the iconic On Fire mechanic across various 16-bit college arenas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Columns (Japan) (NP)', '1990', NaN, 'Sega', '2', NaN, 'Tile-matching puzzle game where you align colored gems vertically or diagonally.', 'Clear columns of jewels to prevent the screen from filling up.', 'Master the classic Sega puzzler Columns on the SNES.', 'A rare Nintendo Power service release. Arrange falling jewels in sets of three to create chain reactions in this addictive 16-bit logic challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Combatribes, The (Japan)', '1990', NaN, 'Technos Japan', '2', NaN, 'Belt-scrolling beat ''em up featuring three distinct brawlers.', 'Defeat the Ground Zero gang and their cybernetic leader.', 'Fight through the streets in The Combatribes for the SNES.', 'A port of the Technos arcade hit. Choose between Bullova, Blitz, or Berzerker and use powerful grab moves to clear waves of 16-bit street thugs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Combatribes, The (USA)', '1990', NaN, 'Technos Japan', '2', NaN, 'Belt-scrolling beat ''em up featuring three distinct brawlers.', 'Defeat the Ground Zero gang and their cybernetic leader.', 'Fight through the streets in The Combatribes for the SNES.', 'Experience the gritty 16-bit action of this arcade port. Utilize unique environmental interactions and massive boss fights to restore order to the city.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Computer Nouryoku Kaiseki - Ultra Baken (Japan)', '1993', NaN, 'Namco', '1', NaN, 'Horse racing analysis and betting simulation software.', 'Use data analysis to predict winning horses in professional races.', 'Analyze the odds in Ultra Baken for the Super Famicom.', 'More of a utility than a game, this title allowed Japanese players to input racing data to calculate winning probabilities for 16-bit horse race betting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Congo the Movie - The Secret of Zinj (USA) (Proto)', '1995', NaN, 'Viacom New Media', '1', NaN, 'First-person action-adventure based on the movie (Unreleased Prototype).', 'Explore the jungle and find the diamond mines of the lost city.', 'Play the unreleased Congo the Movie prototype on SNES.', 'A rare look at a cancelled project. Navigate 3D-style environments from a first-person perspective, solving puzzles and avoiding jungle hazards in this 16-bit movie tie-in.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Congo''s Caper (Europe)', '1994', NaN, 'Data East', '1', NaN, 'Side-scrolling action platformer starring a half-monkey caveman boy.', 'Rescue your girlfriend and defeat the demon lords in a prehistoric world.', 'Join the fun in Congo''s Caper for the Super Nintendo.', 'A spiritual successor to Joe & Mac. Control Congo, use his jumping agility and club to clear stages filled with dinosaurs and 16-bit charm.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Congo''s Caper (USA)', '1994', NaN, 'Data East', '1', NaN, 'Side-scrolling action platformer starring a half-monkey caveman boy.', 'Rescue your girlfriend and defeat the demon lords in a prehistoric world.', 'Join the fun in Congo''s Caper for the Super Nintendo.', 'Explore vibrant prehistoric levels. Collecting three diamonds transforms Congo into a powerful human form, granting new abilities to tackle the toughest 16-bit bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Conker''s High Rule Tail', '1994', NaN, 'Rare', '1', NaN, 'Action-adventure fan mod that replaces Link with Conker the Squirrel.', 'Explore the land of Hyrule with Conker''s unique personality and moves.', 'Play the Zelda crossover Conker''s High Rule Tail on SNES.', 'A creative hack of A Link to the Past. Experience the classic Zelda engine with Conker as the lead, featuring new dialogue and a humorous twist on the legendary 16-bit adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Contra III - The Alien Wars (USA)', '1992', NaN, 'Konami', '2', NaN, 'High-octane run-and-gun shooter featuring Mode 7 boss battles.', 'Defeat the alien invasion and save Earth from total destruction.', 'Experience the legendary Contra III: The Alien Wars on SNES.', 'Widely considered one of the best action games on the system. Dual-wield weapons, hang from ceilings, and survive punishing 16-bit stages with legendary difficulty.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Contra III: The Alien Wars Restoration', '1992', NaN, 'Konami', '2', NaN, 'High-octane run-and-gun shooter with restored Japanese features.', 'Defeat the aliens with infinite continues and restored cheat codes.', 'Play the definitive Contra III Restoration mod on SNES.', 'This hack restores the Probotector style features and original Japanese difficulty options (like infinite continues) to the Western version for the ultimate 16-bit experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Contra Spirits (Japan)', '1992', NaN, 'Konami', '2', NaN, 'High-octane run-and-gun shooter known for its intense difficulty.', 'Save Earth from the alien threat in the original Japanese version.', 'Experience Contra Spirits, the original 16-bit Japanese classic.', 'Features the iconic top-down and side-scrolling stages. Use the bomb mechanic and specialized weapon drops to survive the mechanical alien onslaught.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Conveni Wars Barcode Battler Senki - Super Senshi Shutsugeki seyo! (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'RPG and strategy hybrid featuring barcode-battling mechanics.', 'Defeat rival warriors by utilizing data from commercial barcodes.', 'Experience the unique Barcode Battler Senki on SNES.', 'A specialized Japanese title where players could use a physical peripheral to scan barcodes from real-world products to generate stats and characters for 16-bit battles.', NULL);
