INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cyber Knight (Japan)', '1992', NaN, 'Technos Japan', '1', NaN, 'Sci-fi turn-based RPG with tactical combat and deep ship customization.', 'Explore the galaxy and survive an encounter with a hostile alien race.', 'Discover the deep sci-fi RPG Cyber Knight for the SNES.', 'A unique blend of JRPG exploration and strategic mech combat. Manage your crew and upgrade your Cyber Knight suits to survive the 16-bit depths of space.', NULL);
