INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cybernator (USA)', '1992', NaN, 'NCS', '1', NaN, 'Side-scrolling run-and-gun action featuring a powerful giant mech.', 'Infiltrate enemy bases and destroy the core to stop the war.', 'Pilot the massive mech in Cybernator for the Super Nintendo.', 'Master the use of the shield and boost jets to survive intense firefights. A landmark 16-bit action title with incredible sprite work and physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cybernator (USA) (With Sound Test)', '1992', NaN, 'NCS', '1', NaN, 'Side-scrolling run-and-gun action featuring a powerful giant mech.', 'Infiltrate enemy bases and destroy the core to stop the war.', 'Cyberpower! Play Cybernator with a Sound Test mode on SNES.', 'This specific version includes a Sound Test to enjoy the iconic industrial soundtrack alongside the intense 16-bit mech-action gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cyborg 009 (Japan)', '1991', NaN, 'Riot', '1', NaN, 'Side-scrolling action game based on the legendary sci-fi manga.', 'Stop the Black Ghost organization using the unique powers of nine cyborgs.', 'Join the 00-numbered team in Cyborg 009 for the SNES.', 'Switch between different cyborgs to utilize their specialized abilities (speed, strength, vision) to clear challenging 16-bit stages and bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cyborg 009 (Japan) (Beta)', '1991', NaN, 'Riot', '1', NaN, 'Side-scrolling action game based on the legendary sci-fi manga.', 'Stop the Black Ghost organization using the unique powers of nine cyborgs.', 'Explore the Cyborg 009 Beta version on the Super Nintendo.', 'A pre-release build showing early level designs and character balancing for the 00-team''s 16-bit action-adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Cyborg 009 (Japan) [En by Aeon Genesis v1.0]', '1991', NaN, 'Riot', '1', NaN, 'Side-scrolling action game based on the legendary sci-fi manga.', 'Experience the complete Cyborg 009 story with an English translation.', 'Play the translated Cyborg 009 action game on SNES.', 'The Aeon Genesis translation brings the classic manga''s 16-bit adaptation to life, allowing players to fully understand the team''s fight for justice.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'D-Force (USA)', '1993', NaN, 'Asmik', '2', NaN, 'Vertical shoot ''em up with a unique birds-eye 3D perspective.', 'Destroy the alien invaders across various planetary environments.', 'Blast through the skies in D-Force for the Super Nintendo.', 'Features a layer-switching mechanic that allows you to fly at different altitudes. Battle massive bosses in this experimental 16-bit shooter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daffy Duck - The Marvin Missions (Europe)', '1993', NaN, 'Irem', '1', NaN, 'Run-and-gun platformer starring Daffy Duck in a sci-fi setting.', 'Defeat Marvin the Martian and save the 24th-and-a-half century.', 'Join the wacky action in Daffy Duck: The Marvin Missions.', 'Play as Duck Dodgers! Use a variety of gadgets and weapons to clear Mars of enemies in this colorful and humorous 16-bit Looney Tunes adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daffy Duck - The Marvin Missions (USA)', '1993', NaN, 'Irem', '1', NaN, 'Run-and-gun platformer starring Daffy Duck in a sci-fi setting.', 'Defeat Marvin the Martian and save the 24th-and-a-half century.', 'Join the wacky action in Daffy Duck: The Marvin Missions.', 'Features jetpack mechanics and intense boss fights. Master Daffy''s arsenal to stop Marvin''s galactic plans in this 16-bit classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dai-3-ji Super Robot Taisen (English v2.00)', '1993', NaN, 'Winkysoft', '1', NaN, 'Tactical turn-based RPG featuring iconic mechs from various anime series.', 'Lead your robot army to victory in the third installment of the series.', 'Play the English v2.00 of Super Robot Wars 3 on SNES.', 'A refined translation of the massive crossover RPG. Command Gundams, Mazinger Z, and more in epic 16-bit strategic battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dai-3-ji Super Robot Taisen (Japan)', '1993', NaN, 'Winkysoft', '1', NaN, 'Tactical turn-based RPG featuring iconic mechs from various anime series.', 'Command a crossover army to defeat an intergalactic threat.', 'Experience the classic Dai-3-ji Super Robot Taisen on SNES.', 'The foundational entry of the classic SRW era. Features complex strategy, pilot stats, and iconic 16-bit attack animations for anime fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dai-3-ji Super Robot Taisen (Japan) (Rev B)', '1993', NaN, 'Winkysoft', '1', NaN, 'Tactical turn-based RPG featuring iconic mechs from various anime series.', 'Command a crossover army to defeat an intergalactic threat.', 'Play the updated Rev B version of Super Robot Wars 3.', 'An official Japanese revision that fixed several bugs and balanced unit stats, providing a smoother 16-bit strategic experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dai-3-ji Super Robot Taisen (Japan) [En by Aeon Genesis v1.0] (~Super Robot Wars 3)', '1993', NaN, 'Winkysoft', '1', NaN, 'Tactical turn-based RPG featuring iconic mechs from various anime series.', 'Experience the epic crossover with the Aeon Genesis translation.', 'Super Robot Wars 3 in English: The Aeon Genesis version.', 'The classic fan translation that first opened the world of SRW to Western fans. Lead the Londo Bell squad through intense 16-bit missions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dai-4-ji Super Robot Taisen (Japan)', '1995', NaN, 'Winkysoft', '1', NaN, 'Tactical turn-based RPG featuring the debut of original Banpresto characters.', 'Choose your protagonist and lead the mechs through a massive war.', 'Master the strategy of Dai-4-ji Super Robot Taisen on SNES.', 'Often considered the peak of the 16-bit series. Introduces the Main Character system and features an enormous roster of mechs and branching story paths.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dai-4-ji Super Robot Taisen (Japan) (Rev A)', '1995', NaN, 'Winkysoft', '1', NaN, 'Tactical turn-based RPG featuring the debut of original Banpresto characters.', 'Choose your protagonist and lead the mechs through a massive war.', 'Play the refined Rev A version of Super Robot Wars 4 on SNES.', 'The updated Japanese version with bug fixes and improved unit balance, ensuring the ultimate 16-bit strategy experience for anime and robot fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daibakushou Jinsei Gekijou - Dokidoki Seishun Hen (Japan)', '1994', NaN, 'Taito', '1', NaN, 'Digital board game focused on the ups and downs of teenage life.', 'Navigate high school, find love, and graduate with the best stats.', 'Live your youth in Daibakushou Jinsei Gekijou: Dokidoki Seishun.', 'A humorous Game of Life style title. Spin the wheel to move across the board, making choices about clubs, exams, and romance in this vibrant 16-bit Japanese simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daibakushou Jinsei Gekijou - Ooedo Nikki (Japan)', '1993', NaN, 'Taito', '1', NaN, 'Digital board game set in the Edo period of Japanese history.', 'Build a successful life as a citizen of old Japan.', 'Travel to old Japan in Daibakushou Jinsei Gekijou: Ooedo Nikki.', 'Experience life as a samurai, merchant, or artisan. This historical board game features era-appropriate mini-games and events with a charming 16-bit aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daibakushou Jinsei Gekijou - Zukkoke Salary Man Hen (Japan)', '1995', NaN, 'Taito', '1', NaN, 'Digital board game focused on the daily life of a Japanese salaryman.', 'Climb the corporate ladder while managing your family and finances.', 'Survive the office in Daibakushou Jinsei Gekijou: Zukkoke Salary Man.', 'A satirical take on corporate culture. Navigate the board to balance work life, promotions, and weekend activities in this unique 16-bit social simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daibakushou Jinsei Gekijou (Japan)', '1992', NaN, 'Taito', '1', NaN, 'Digital board game that simulates an entire lifetime.', 'Make the best life choices to end up the most successful player.', 'The ultimate life sim: Daibakushou Jinsei Gekijou on SNES.', 'The foundational entry in the series. Go from childhood to old age, dealing with careers, marriage, and random events in this fun 16-bit multiplayer experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daikaijuu Monogatari (Japan)', '1994', NaN, 'Birthday', '1', NaN, 'Turn-based JRPG featuring a massive cast of unique monsters and heroes.', 'Gather the legendary heroes to stop the resurrection of an ancient evil.', 'Experience the epic Daikaijuu Monogatari on the Super Famicom.', 'A classic RPG known for its large roster of playable characters and detailed sprite work. Explore a vast world and master a traditional 16-bit combat system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daikaijuu Monogatari (Japan) (Rev A)', '1994', NaN, 'Birthday', '1', NaN, 'Turn-based JRPG featuring a massive cast of unique monsters and heroes.', 'Gather the legendary heroes to stop the resurrection of an ancient evil.', 'Experience the epic Daikaijuu Monogatari (Rev A) on SNES.', 'The revised Japanese edition featuring bug fixes and balanced character stats to provide a more polished journey through the world of Shell Monster Story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daikaijuu Monogatari II (Japan)', '1996', NaN, 'Birthday', '1', NaN, 'Turn-based JRPG with advanced mechanics and a real-time day/night cycle.', 'Stop the new threat to the world in this massive sequel.', 'Play the visually stunning Daikaijuu Monogatari II on SNES.', 'One of the most technically advanced RPGs on the system. Featuring an internal clock, beautiful animations, and a deep story that spans two 16-bit cartridges worth of content.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daikoukai Jidai II (Japan)', '1994', NaN, 'Koei', '1', NaN, 'Naval strategy and trading simulation set during the Age of Discovery.', 'Build a fleet, discover new lands, and dominate global trade.', 'Sail the world in the classic Daikoukai Jidai II for SNES.', 'Known as Uncharted Waters: New Horizons in the West. Choose one of six characters and live a life of piracy, trade, or exploration in this deep 16-bit sim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daisenryaku Expert (Japan)', '1992', NaN, 'SystemSoft', '1', NaN, 'Hex-based tactical military strategy game.', 'Conquer enemy territory using modern 16-bit military units.', 'Master the battlefield in Daisenryaku Expert for SNES.', 'A deep simulation of modern warfare. Manage resources, deploy tanks and aircraft, and use terrain to your advantage to outsmart the AI in this strategic classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Daisenryaku Expert WWII - War in Europe (Japan)', '1994', NaN, 'SystemSoft', '1', NaN, 'Hex-based tactical military strategy game set during World War II.', 'Lead your forces to victory in the European theater of WWII.', 'Experience WWII strategy in Daisenryaku Expert WWII on SNES.', 'Command historical units from the 1940s. A detailed and challenging simulation focusing on the tactical maneuvers and resource management of the Great War.', NULL);
