INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Darius Force (Japan)', '1993', NaN, 'Taito', '2', NaN, 'Side-scrolling shoot ''em up with a branching level structure.', 'Navigate through the alien-infested zones to destroy the core.', 'Battle the Belsar fleet in Darius Force for the SNES.', 'Known as Super Nova in the West. This entry features unique ship choices and a non-linear path system, all with the series'' iconic robotic sea-creature bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Darius Twin (Europe)', '1993', NaN, 'Taito', '2', NaN, 'Side-scrolling shoot ''em up with cooperative multiplayer action.', 'Protect the galaxy from the invading Belsar forces.', 'Blast off with Darius Twin, the 16-bit shooter classic.', 'The first Darius game designed specifically for home consoles. Features the trademark robotic fish bosses and a fantastic soundtrack, perfect for two-player 16-bit action.', NULL);
