INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Darius Twin (USA)', '1993', NaN, 'Taito', '2', NaN, 'Side-scrolling shoot ''em up with cooperative multiplayer action.', 'Protect the galaxy from the invading Belsar forces.', 'Blast off with Darius Twin, the 16-bit shooter classic.', 'Master the power-up system and choose your path through the stars. Darius Twin is a cornerstone of the SNES shooter library, offering high replayability.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dark Half (Japan)', '1996', NaN, 'Enix', '1', NaN, 'Unique turn-based RPG where you play as both the hero and the villain.', 'Experience the story from two conflicting perspectives to reveal the truth.', 'Explore the duality of Dark Half on the Super Famicom.', 'A dark and atmospheric Enix RPG. One day you play as the hero saving souls, the next as the demon stealing them. A truly innovative 16-bit narrative experiment.', NULL);
