INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Date Kimiko no Virtual Tennis (Japan)', '1993', NaN, 'Palsoft', '2', NaN, 'Realistic tennis simulation featuring Japanese pro Kimiko Date.', 'Win the international tennis circuit and reach the #1 rank.', 'Play pro tennis in Date Kimiko no Virtual Tennis for SNES.', 'A polished sports title focusing on realism and player positioning. Master various court types and utilize Kimiko Date''s signature playstyle in this 16-bit sim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'David Crane''s Amazing Tennis (Europe)', '1992', NaN, 'Imagineering', '2', NaN, 'Innovative tennis simulation with a unique behind the player 3D view.', 'Win the grand slam tournament through precision and timing.', 'Experience David Crane''s Amazing Tennis on the Super Nintendo.', 'Utilizing advanced scaling techniques, this game offers a groundbreaking perspective for the era. Master the physics-based ball mechanics in this unique 16-bit sports title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'David Crane''s Amazing Tennis (Japan)', '1992', NaN, 'Imagineering', '2', NaN, 'Innovative tennis simulation with a unique behind the player 3D view.', 'Win the grand slam tournament through precision and timing.', 'Experience David Crane''s Amazing Tennis on the Super Nintendo.', 'The Japanese edition of the innovative tennis sim. Practice your serve and volley in a 16-bit environment that pioneered the 3D-camera style for sports games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'David Crane''s Amazing Tennis (USA)', '1992', NaN, 'Imagineering', '2', NaN, 'Innovative tennis simulation with a unique behind the player 3D view.', 'Win the grand slam tournament through precision and timing.', 'Experience David Crane''s Amazing Tennis on the Super Nintendo.', 'Master the various court surfaces and player stats. Features realistic sound effects and a challenging AI that reacts to your 16-bit court strategy.', NULL);
