INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Deae Tonosama - Appare Ichiban (Japan)', '1995', NaN, 'Sunsoft', '1', NaN, 'Bizarre and humorous top-down shooter featuring a duo of lords.', 'Cleanse the land of evil using unique lordly projectiles.', 'Enjoy the wacky action of Deae Tonosama: Appare Ichiban.', 'A cult classic Japanese shooter. Choose between two eccentric characters and fight through surreal levels filled with humor and vibrant 16-bit graphics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dear Boys (Japan)', '1993', NaN, 'Tose', '2', NaN, 'Basketball simulation based on the popular sports manga.', 'Lead your high school team to the national championship.', 'Experience the hoop dreams of Dear Boys on the SNES.', 'A sports title featuring detailed 16-bit sprites and cinematic story sequences. Manage your players'' stamina and execute tactical plays to win the tournament in this manga-inspired basketball sim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Death and Return of Superman, The (Europe)', '1994', NaN, 'Blizzard Entertainment', '2', NaN, 'Side-scrolling beat ''em up featuring multiple versions of Superman.', 'Defeat Doomsday and the cyborg imposters to restore the true Superman.', 'Experience the epic Death and Return of Superman on SNES.', 'Play as Superman, Superboy, Steel, and more. Use incredible powers like flight and super-strength to fight through 16-bit levels based on the iconic DC Comics storyline.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Death and Return of Superman, The (USA)', '1994', NaN, 'Blizzard Entertainment', '2', NaN, 'Side-scrolling beat ''em up featuring multiple versions of Superman.', 'Defeat Doomsday and the cyborg imposters to restore the true Superman.', 'Experience the epic Death and Return of Superman on SNES.', 'A high-stakes brawler with destructible environments. Master each hero''s unique projectiles and melee combos to save Metropolis in this legendary 16-bit action title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Death Brade (Japan)', '1994', NaN, 'Data East', '1', NaN, 'One-on-one fighting game with a mythological and arena combat theme.', 'Defeat the gods and monsters to prove your fighting supremacy.', 'Enter the arena in Death Brade for the Super Famicom.', 'Known as Mutant Fighter in arcades. Choose from creatures like golems or hydras and engage in heavy-hitting combat featuring massive sprites and unique 16-bit grappling mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dekitate High School (Japan)', '1994', NaN, 'Takara', '1', NaN, 'High school life and dating simulation with a focus on education.', 'Balance your studies, clubs, and social life to graduate successfully.', 'Live your school life in Dekitate High School for the SNES.', 'A charming Japanese simulation game. Make daily choices that affect your character''s future, interact with classmates, and experience the nostalgia of 16-bit school days.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Demolition Man (Europe)', '1995', NaN, 'Virgin Interactive', '1', NaN, 'Action-platformer based on the Sylvester Stallone sci-fi movie.', 'Chase down Simon Phoenix across the futuristic city of San Angeles.', 'Fight for the future in Demolition Man for the Super Nintendo.', 'Features both side-scrolling and top-down perspectives. Use a variety of high-tech weapons to neutralize criminals in this explosive 16-bit movie tie-in.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Demolition Man (USA)', '1995', NaN, 'Virgin Interactive', '1', NaN, 'Action-platformer based on the Sylvester Stallone sci-fi movie.', 'Chase down Simon Phoenix across the futuristic city of San Angeles.', 'Fight for the future in Demolition Man for the Super Nintendo.', 'A faithful recreation of the film''s action. Navigate through 16-bit museum and cryo-prison levels, utilizing grenades and rapid-fire weapons to restore order.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Demon''s Blazon - Makaimura Monshou Hen (Japan)', '1994', NaN, 'Capcom', '1', NaN, 'Side-scrolling action-RPG featuring the demon Firebrand.', 'Collect the magical Crests to prevent the ultimate power from falling into evil hands.', 'Discover the dark beauty of Demon''s Blazon on the Super Famicom.', 'The Japanese version of Demon''s Crest. Features gothic 16-bit art, non-linear exploration, and the ability to transform Firebrand into various forms with unique elemental powers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Demon''s Crest (Europe)', '1994', NaN, 'Capcom', '1', NaN, 'Side-scrolling action-RPG featuring the demon Firebrand.', 'Collect the magical Crests to prevent the ultimate power from falling into evil hands.', 'Explore the dark world of Demon''s Crest for the SNES.', 'A spin-off of the Ghouls ''n Ghosts series. Master flight, wall-climbing, and diverse breath attacks to uncover secrets in this atmospheric 16-bit masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Demon''s Crest (USA)', '1994', NaN, 'Capcom', '1', NaN, 'Side-scrolling action-RPG featuring the demon Firebrand.', 'Collect the magical Crests to prevent the ultimate power from falling into evil hands.', 'Explore the dark world of Demon''s Crest for the SNES.', 'One of the most visually impressive games on the system. Use the Mode 7 world map to find hidden bosses and multiple endings in this deep 16-bit adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dennis (Europe)', '1993', NaN, 'Ocean Software', '1', NaN, 'Side-scrolling platformer based on the mischievous comic strip character.', 'Navigate through various neighborhood levels and escape the grumpy Mr. Wilson.', 'Join the trouble in Dennis for the Super Nintendo.', 'Based on the movie and cartoon. Use your slingshot and agility to overcome obstacles and pranks in this colorful and challenging 16-bit platformer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dennis the Menace (USA)', '1993', NaN, 'Ocean Software', '1', NaN, 'Side-scrolling platformer based on the mischievous comic strip character.', 'Navigate through various neighborhood levels and escape the grumpy Mr. Wilson.', 'Join the trouble in Dennis the Menace for the Super Nintendo.', 'Explore oversized 16-bit environments, collect items, and outsmart bullies in this fun movie tie-in that captures the spirit of the classic character.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Densetsu no Ogre Battle - The March of the Black Queen (Japan)', '1993', NaN, 'Quest', '1', NaN, 'Grand-scale tactical RPG with a focus on alignment and reputation.', 'Lead a rebellion to liberate the Zenobian Empire from a tyrant.', 'Master the strategy of Ogre Battle: March of the Black Queen.', 'A unique blend of real-time strategy and RPG. Manage units on a map and engage in auto-battles where your choices influence one of 13 possible 16-bit endings.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Densetsu no Ogre Battle - The March of the Black Queen (Japan) (NP)', '1993', NaN, 'Quest', '1', NaN, 'Grand-scale tactical RPG with a focus on alignment and reputation.', 'Lead a rebellion to liberate the Zenobian Empire from a tyrant.', 'Experience the Nintendo Power version of Ogre Battle on SNES.', 'A later digital release in Japan via the NP service. Features the same deep strategic gameplay and branching narrative that made this 16-bit title a cult classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Derby Jockey - Kishu Ou e no Michi (Japan)', '1994', NaN, 'ASCII', '1', NaN, 'Horse racing simulation focusing on jockey career and stamina management.', 'Climb the ranks of professional racing and win the G1 cup.', 'Ride to victory in Derby Jockey for the Super Famicom.', 'A realistic 16-bit take on horse racing. Balance your speed and positioning during the race while managing your horse''s energy to cross the finish line first.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Derby Jockey - Kishu Ou e no Michi (Japan) (Rev A)', '1994', NaN, 'ASCII', '1', NaN, 'Horse racing simulation focusing on jockey career and stamina management.', 'Climb the ranks of professional racing and win the G1 cup.', 'Ride to victory in Derby Jockey (Rev A) for the SNES.', 'The updated Japanese version with improved AI behavior and minor bug fixes, providing a smoother experience for 16-bit horse racing enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Derby Jockey 2 (Japan)', '1994', NaN, 'ASCII', '1', NaN, 'Enhanced horse racing simulation with new tracks and breeding mechanics.', 'Become the legendary jockey by winning the most prestigious races.', 'Master the turf in Derby Jockey 2 for the Super Famicom.', 'The sequel adds more depth to the jockey career mode, featuring improved 16-bit visuals and more detailed horse stats for a deeper simulation experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Derby Stallion ''96 (Japan)', '1996', NaN, 'ASCII', '1', NaN, 'Deep horse breeding and racing management simulation.', 'Breed the ultimate champion horse and win the national derby.', 'Build your racing empire in Derby Stallion ''96 for SNES.', 'The most popular entry in the series. Manage your stable, study bloodlines, and watch your 16-bit horses compete in realistic, high-stakes racing events.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Derby Stallion ''98 (Japan) (NP)', '1998', NaN, 'ASCII', '1', NaN, 'Deep horse breeding and racing management simulation.', 'Breed the ultimate champion horse and win the national derby.', 'Experience the late-gen Derby Stallion ''98 on the SNES.', 'Released via the Nintendo Power flash service. Features updated rosters and refined management menus for the ultimate 16-bit horse breeding experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Derby Stallion II (Japan)', '1994', NaN, 'ASCII', '1', NaN, 'Horse breeding and management simulation.', 'Train your horses and manage your stable''s finances to reach success.', 'Enter the world of Derby Stallion II on the Super Famicom.', 'Expanding on the original, this sequel introduced more complex breeding combinations and a more detailed 16-bit interface for stable management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Derby Stallion III (Japan)', '1995', NaN, 'ASCII', '1', NaN, 'Horse breeding and management simulation.', 'Dominate the Japanese racing circuit with your superior bloodlines.', 'Train winners in Derby Stallion III for the Super Famicom.', 'The third installment features even more realistic racing physics and a wider variety of tracks, solidifying its place as a 16-bit simulation staple.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Derby Stallion III (Japan) (Rev B)', '1995', NaN, 'ASCII', '1', NaN, 'Horse breeding and management simulation.', 'Dominate the Japanese racing circuit with your superior bloodlines.', 'Play the updated Derby Stallion III (Rev B) on SNES.', 'An official revision that fixed technical glitches in the breeding algorithms, ensuring more accurate 16-bit simulation results for hardcore players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Derby Stallion III (Japan) (Rev D)', '1995', NaN, 'ASCII', '1', NaN, 'Horse breeding and management simulation.', 'Dominate the Japanese racing circuit with your superior bloodlines.', 'Play the polished Derby Stallion III (Rev D) on SNES.', 'The final revision of the third game, offering the most stable and balanced version of this 16-bit horse management classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Desert Fighter - Suna no Arashi Sakusen (Japan)', '1993', NaN, 'Kemco', '2', NaN, 'Isometric air combat shooter set in a desert environment.', 'Complete various military missions using an array of fighter jets.', 'Take flight in Desert Fighter: Suna no Arashi Sakusen.', 'Known as Air Cavalry in some regions. Pilot helicopters and jets in 16-bit missions involving escorting, bombing, and dogfighting across desert sands.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Desert Fighter (Europe)', '1993', NaN, 'Kemco', '2', NaN, 'Isometric air combat shooter set in a desert environment.', 'Complete various military missions using an array of fighter jets.', 'Experience the intense Air Cavalry action in Desert Fighter.', 'Master the controls of advanced military aircraft. This 16-bit flight sim features diverse mission objectives and a focus on tactical air-to-ground combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Desert Fighter (Europe) (Beta)', '1993', NaN, 'Kemco', '2', NaN, 'Isometric air combat shooter set in a desert environment.', 'Complete various military missions using an array of fighter jets.', 'Explore the Desert Fighter Beta version for the SNES.', 'A pre-release build featuring early mission designs and flight physics as they were being developed for the final 16-bit retail release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Desert Strike - Return to the Gulf (Europe)', '1992', NaN, 'EA', '2', NaN, 'Isometric helicopter action-strategy game based on the Gulf War.', 'Complete multiple objectives per mission to destabilize the enemy.', 'Pilot the Apache in Desert Strike: Return to the Gulf on SNES.', 'A classic EA title. Manage fuel, armor, and ammunition while rescuing hostages and destroying key targets in a challenging 16-bit tactical environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Desert Strike - Return to the Gulf (USA)', '1992', NaN, 'EA', '2', NaN, 'Isometric helicopter action-strategy game based on the Gulf War.', 'Complete multiple objectives per mission to destabilize the enemy.', 'Pilot the Apache in Desert Strike: Return to the Gulf on SNES.', 'Navigate large open maps and use strategy to prioritize targets. One of the most successful 16-bit action games, known for its deep gameplay and smooth controls.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Desert Strike - Wangan Sakusen (Japan)', '1992', NaN, 'EA', '2', NaN, 'Isometric helicopter action-strategy game based on the Gulf War.', 'Complete multiple objectives per mission to destabilize the enemy.', 'Experience the Japanese version, Desert Strike: Wangan Sakusen.', 'The localized release of the hit helicopter sim. Battle through the dunes and urban areas in a high-stakes 16-bit campaign inspired by real-world events.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Destructive (Japan)', '1994', NaN, 'KSS', '1', NaN, 'Action-puzzle game or shooter with a focus on destruction.', 'Destroy target objects and enemies within the time limit.', 'Unleash chaos in the rare Japanese title Destructive for SNES.', 'A fast-paced 16-bit experience where the goal is to cause as much environmental damage as possible, featuring unique weapon systems and challenging arcade-style levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Devil''s Course (Japan)', '1992', NaN, 'IGS', '1', NaN, 'Realistic golf simulation featuring the fictional and challenging Devil''s Course.', 'Finish each hole under par while navigating treacherous terrain.', 'Conquer the infernal greens in Devil''s Course for the SNES.', 'Known in the West as True Golf Classics: Wicked 18. This 16-bit sim features surreal, fantasy-themed holes with steep cliffs and lava pits that test even the best digital golfers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Devil''s Course (Japan) (Sample)', '1992', NaN, 'IGS', '1', NaN, 'Realistic golf simulation featuring the fictional and challenging Devil''s Course.', 'Experience a pre-release segment of the challenging golf sim.', 'Explore the Devil''s Course Sample version on the Super Famicom.', 'A rare promotional version used in Japanese stores. It features a selection of the most difficult 16-bit holes to showcase the game''s unique environmental physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dharma Doujou (Japan)', '1994', NaN, 'SETA', '2', NaN, 'Fast-paced tile-matching puzzle game based on Buddhist themes.', 'Match and clear blocks by pushing them into place before time runs out.', 'Solve the rhythmic puzzles of Dharma Doujou on the SNES.', 'A unique Japanese puzzler where you use a hammer to push blocks. Features a distinct art style and increasing speed that requires quick 16-bit reflexes and pattern recognition.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dig & Spike Volleyball (USA)', '1991', NaN, 'Tecmo', '4', NaN, 'Arcade-style volleyball simulation featuring both indoor and beach modes.', 'Win the world championship by mastering spikes, blocks, and serves.', 'Experience 16-bit sports action in Dig & Spike Volleyball.', 'Choose between professional indoor teams or casual beach matches. Features responsive controls and specialized special moves for high-energy 16-bit volleyball gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dimension-Force (Japan)', '1991', NaN, 'Asmik', '1', NaN, 'Vertical shoot ''em up with a unique perspective-shifting mechanic.', 'Destroy alien forces across multiple atmospheric layers.', 'Blast through the skies in Dimension-Force for the SNES.', 'Known as D-Force in the West. This Japanese version highlights the game''s ability to switch between low and high altitudes using Mode 7-style effects in a 16-bit environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dino City (Europe)', '1991', NaN, 'Irem', '1', NaN, 'Side-scrolling platformer based on the movie Adventures in Dino City.', 'Navigate through prehistoric worlds to defeat the evil Rocky and his gang.', 'Explore the colorful world of Dino City for the Super Nintendo.', 'Control a kid riding a dinosaur! Use your dino companion''s strength to smash through obstacles and enemies in this vibrant and charming 16-bit adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dino City (USA)', '1991', NaN, 'Irem', '1', NaN, 'Side-scrolling platformer based on the movie Adventures in Dino City.', 'Navigate through prehistoric worlds to defeat the evil Rocky and his gang.', 'Explore the colorful world of Dino City for the Super Nintendo.', 'A faithful 16-bit platformer featuring multiple playable characters. Master the unique jumping and attacking mechanics to navigate through treacherous jungle and cave levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dino Dini''s Soccer! (Europe) (En,Fr,De)', '1994', NaN, 'Dino Dini', '2', NaN, 'Fast-paced soccer simulation with a top-down perspective.', 'Win the international cup by outplaying rival teams with tight controls.', 'Play the high-speed Dino Dini''s Soccer on the SNES.', 'Created by the legend behind Sensible Soccer. Focuses on high-velocity gameplay and precise passing, offering a deep 16-bit tactical experience for football fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dinowars - Kyouryuu Oukoku e no Daibouken (Japan)', '1990', NaN, 'Jaleco', '1', NaN, 'Action-platformer featuring a boy and his dinosaur friends.', 'Rescue the kingdom from an evil force by mastering elemental powers.', 'Join the adventure in Dinowars: Kyouryuu Oukoku on SNES.', 'A Japanese exclusive that blends platforming with light RPG elements. Switch between different dinosaurs to use their specific 16-bit abilities to solve puzzles and defeat bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dirt Racer (Europe) (En,Fr,De)', '1995', NaN, 'Vision Works', '1', NaN, 'Off-road racing simulation using the Super FX chip for 3D environments.', 'Win the dirt racing circuit by outmaneuvering rivals on bumpy tracks.', 'Experience the 3D speed of Dirt Racer for the Super Nintendo.', 'A rare European release that utilizes the Super FX chip to create 3D terrain. Master the physics of off-road driving in this technically impressive 16-bit racer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dirt Trax FX (Europe)', '1995', NaN, 'Nintendo', '2', NaN, 'High-speed motocross racing featuring 3D tracks and 4-player support.', 'Finish first in the motocross championship across various terrains.', 'Race through 3D mud in Dirt Trax FX for the Super Nintendo.', 'Powered by the Super FX chip, this game features polygons to create realistic hills and jumps. A fast-paced 16-bit experience with a unique radical 90s aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dirt Trax FX (USA)', '1995', NaN, 'Nintendo', '2', NaN, 'High-speed motocross racing featuring 3D tracks and 4-player support.', 'Finish first in the motocross championship across various terrains.', 'Race through 3D mud in Dirt Trax FX for the Super Nintendo.', 'Choose from multiple riders and bikes. The FX chip allows for smooth 16-bit 3D perspective changes that were groundbreaking for the time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dixie Kong Country', '1994', NaN, 'Rare', '2', NaN, 'Action-platformer fan modification featuring Dixie Kong in a new quest.', 'Navigate custom levels and defeat enemies using Dixie''s unique hover.', 'Play the fan-made Dixie Kong Country on the Super Nintendo.', 'A creative hack that focuses on Dixie Kong''s gameplay mechanics. Experience new challenges and level layouts in the classic 16-bit Donkey Kong Country engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Do-Re-Mi Fantasy - Milon no Dokidoki Daibouken (Japan)', '1996', NaN, 'Hudson Soft', '1', NaN, 'Charming side-scrolling platformer with musical and fantasy themes.', 'Restore music to the world by collecting the magical instruments.', 'Discover the hidden gem Do-Re-Mi Fantasy for the SNES.', 'One of the most beautiful platformers on the system. Play as Milon, using bubbles to trap enemies in a world filled with 16-bit color and incredible sound design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Do-Re-Mi Fantasy - Milon no Dokidoki Daibouken (Japan) [En by Gaijin+RPGOne v1.0] (~Do-Re-Mi Fantasy - Milon''s Quest)', '1996', NaN, 'Hudson Soft', '1', NaN, 'Charming side-scrolling platformer with musical and fantasy themes.', 'Experience Milon''s epic quest with a full English translation.', 'Play Do-Re-Mi Fantasy in English on the Super Nintendo.', 'The definitive fan translation. Now you can enjoy the whimsical story and creative dialogue of this 16-bit masterpiece that was originally a Japanese exclusive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dokapon 3-2-1 - Arashi o Yobu Yuujou (Japan)', '1995', NaN, 'Asmik', '4', NaN, 'Hybrid digital board game and turn-based JRPG.', 'Defeat your friends and monsters to become the wealthiest hero.', 'Join the chaotic fun of Dokapon 3-2-1 for the Super Famicom.', 'A cult classic known for destroying friendships. Blend RPG combat with a board game structure, featuring 16-bit humor and competitive sabotage mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dokapon Gaiden - Honoo no Audition (Japan)', '1996', NaN, 'Asmik', '4', NaN, 'Action-focused spin-off of the Dokapon board game series.', 'Win the Flame Audition by outperforming rivals in various challenges.', 'Experience the quirky Dokapon Gaiden on the Super Famicom.', 'A faster-paced take on the series. Features more direct combat and mini-games while maintaining the charming 16-bit art style and competitive spirit of Dokapon.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dokuritsu Sensou - Liberty or Death (Japan)', '1992', NaN, 'Koei', '1', NaN, 'Historical grand strategy simulation set during the American Revolution.', 'Lead either the British or the American forces to victory.', 'Experience the war of independence in Liberty or Death for SNES.', 'A deep Koei simulation. Manage troop movements, political alliances, and budget to win the 16-bit struggle for the future of North America.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dolucky no A.League Soccer (Japan)', '1995', NaN, 'Naxat Soft', '2', NaN, 'Arcade soccer simulation featuring the cat mascot Dolucky.', 'Win the animal world cup with flashy special moves and high energy.', 'Play the colorful Dolucky no A.League Soccer on SNES.', 'Features incredible 16-bit animations and humorous animal characters. Execute magic shots and enjoy the fast-paced, accessible soccer gameplay.', NULL);
