INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dolucky no Puzzle Tour ''94 (Japan)', '1994', NaN, 'Naxat Soft', '2', NaN, 'Falling-block puzzle game featuring characters from the Dolucky series.', 'Win the puzzle world tour by clearing blocks faster than your rivals.', 'Solve the puzzles in Dolucky no Puzzle Tour ''94 for SNES.', 'A polished 16-bit puzzler with a travel theme. Features great music and various difficulty modes, perfect for fans of competitive tile-matching games.', NULL);
