INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donald in Maui Mallard (Europe)', '1996', NaN, 'Eurocom', '1', NaN, 'Action-platformer starring Donald''s Maui Mallard alter ego.', 'Solve the mystery of the missing idol on a tropical island.', 'Experience Maui Mallard''s ninja adventure on the SNES.', 'Known as Cold Shadow in the USA. Master the staff and projectile weapons to navigate through detailed 16-bit environments and defeat exotic bosses.', NULL);
