INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country (USA)', '1994', NaN, 'Rare', '2', NaN, 'Groundbreaking platformer featuring pre-rendered 3D graphics.', 'Recover the stolen banana hoard from King K. Rool.', 'Experience the original Donkey Kong Country on the SNES.', 'One of the best-selling games on the system. Master the buddy system to swap between Kongs and find all the hidden bonus rooms in this 16-bit classic.', NULL);
