INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country (USA) (Rev A)', '1994', NaN, 'Rare', '2', NaN, 'Groundbreaking platformer featuring pre-rendered 3D graphics.', 'Recover the stolen banana hoard from King K. Rool.', 'Play the updated Rev A version of Donkey Kong Country.', 'The first major revision for the USA market, fixing several glitches and minor graphical errors found in the initial 16-bit launch version.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country (USA) (Rev B)', '1994', NaN, 'Rare', '2', NaN, 'Groundbreaking platformer featuring pre-rendered 3D graphics.', 'Recover the stolen banana hoard from King K. Rool.', 'Play the polished Rev B version of Donkey Kong Country.', 'The final official revision of the game, offering the most stable gameplay and addressing rare hardware compatibility issues on the Super Nintendo.', NULL);
