INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (Germany) (En,De)', '1995', NaN, 'Rare', '2', NaN, 'Epic platforming sequel featuring Diddy and Dixie Kong.', 'Rescue Donkey Kong from the clutches of Kaptain K. Rool.', 'Play Donkey Kong Country 2: Diddy''s Kong Quest (Germany).', 'The German localization of the 16-bit masterpiece. Features translated text and the same iconic gameplay that made the Kongs world-famous.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (Germany) (En,De) (Rev A)', '1995', NaN, 'Rare', '2', NaN, 'Epic platforming sequel featuring Diddy and Dixie Kong.', 'Rescue Donkey Kong from the clutches of Kaptain K. Rool.', 'Play the updated German Rev A version of DKC2.', 'The polished German revision, addressing minor text errors and balancing some of the more difficult 16-bit platforming segments for local players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (USA) (En,Fr)', '1995', NaN, 'Rare', '2', NaN, 'Epic platforming sequel featuring Diddy and Dixie Kong.', 'Rescue Donkey Kong from the clutches of Kaptain K. Rool.', 'Experience the definitive DKC2: Diddy''s Kong Quest (USA).', 'Master the teamwork between Diddy and Dixie. Explore Crocodile Isle, collect Kremkoins, and conquer the Lost World in this peak 16-bit platformer.', NULL);
