INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (USA) (En,Fr)_IXKZ HACK-v1-1-beta03', '1995', NaN, 'Rare', '2', NaN, 'Side-scrolling platformer with experimental beta features and tweaks.', 'Rescue Donkey Kong in this modified beta build of DKC2.', 'Explore the DKC2 IXKZ Hack Beta on the Super Nintendo.', 'A technical hack that explores unused assets and experimental physics. A unique way to see the 16-bit mechanics of DKC2 from a different perspective.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 2 - The Adventure Return', '1995', NaN, 'Rare', '2', NaN, 'Comprehensive fan-made sequel with entirely new level designs.', 'Embark on a new journey to save the Kong family.', 'Play the fan-made Donkey Kong Country 2: The Adventure Return.', 'A massive project that offers a fresh experience using the DKC2 engine. Features creative level layouts and a difficulty curve designed for 16-bit veterans.', NULL);
