INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 2 - The Lost Levels', '1995', NaN, 'Rare', '2', NaN, 'Restoration mod featuring levels and assets that were cut or altered.', 'Explore the lost side of Crocodile Isle in this unique mod.', 'Discover the secrets of DKC2: The Lost Levels on SNES.', 'A creative hack that reimagines the game using cut content and new ideas, providing a what-if scenario for the 16-bit platforming classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 2 : Hard As Kongcrete', '1995', NaN, 'Rare', '2', NaN, 'Hardcore difficulty hack with a focus on industrial and solid themes.', 'Conquer the hardest versions of the classic DKC2 stages.', 'Test your skill in DKC2: Hard As Kongcrete for SNES.', 'A brutal modification that replaces the standard levels with industrial-strength challenges. Not for the faint of heart, this is 16-bit platforming at its most intense.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 2 Unveiled', '1995', NaN, 'Rare', '2', NaN, 'Complete level overhaul with new secrets and a revamped difficulty.', 'Uncover the mysteries of Crocodile Isle in this unveiled version.', 'Experience the fresh world of Donkey Kong Country 2 Unveiled.', 'A high-quality hack that keeps the spirit of the original but offers entirely new puzzles and level flow, making the 16-bit classic feel brand new.', NULL);
