INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 3 - Dixie Kong''s Double Trouble! (USA) (En,Fr)', '1996', NaN, 'Rare', '2', NaN, 'The final entry in the original trilogy featuring Dixie and Kiddy Kong.', 'Search for the missing Donkey and Diddy in the Northern Kremisphere.', 'Experience the massive DKC3: Dixie Kong''s Double Trouble.', 'Help the Kongs face off against the mysterious Baron K. Roolenstein. A polished 16-bit finale with some of the most complex secrets in the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 3 - Dixie Kong''s Triple Trouble!', '1996', NaN, 'Rare', '2', NaN, 'High-difficulty hack of the third game with new level layouts.', 'Rescue the Kongs from even more dangerous mechanical traps.', 'Face the trouble in DKC3: Dixie''s Triple Trouble mod.', 'A total conversion of the third game that increases the stakes. Navigate revamped 16-bit levels that require expert knowledge of Dixie and Kiddy.', NULL);
