INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Donkey Kong Country 3 Free Roam & Open World', '1996', NaN, 'Rare', '2', NaN, 'Non-linear exploration mod that opens the entire game map.', 'Explore the Northern Kremisphere in any order you choose.', 'Play DKC3 Free Roam & Open World on the Super Nintendo.', 'A revolutionary hack that removes the linear progression, allowing you to tackle 16-bit levels and collect items in a completely open-ended fashion.', NULL);
