INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Doom (Japan)', '1995', NaN, 'ID Software', '1', NaN, 'First-person shooter featuring a lone marine fighting demonic forces.', 'Survive the Martian moons and defeat the Cyberdemon.', 'Experience the Japanese version of Doom on SNES.', 'The Super Famicom release of the seminal shooter. Despite hardware limits, it delivers the full visceral experience of demon-slaying with iconic 16-bit music and sound effects.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Doom (USA)', '1995', NaN, 'ID Software', '1', NaN, 'First-person shooter featuring a lone marine fighting demonic forces.', 'Survive the Martian moons and defeat the Cyberdemon.', 'Experience the legendary FPS Doom on the SNES.', 'Navigate complex levels, manage your ammo, and utilize the iconic BFG9000. A must-play 16-bit conversion for fans of retro action and technical achievements.', NULL);
