INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Doomsday Warrior (USA)', '1992', NaN, 'Black Pearl', '2', NaN, 'One-on-one fighting game featuring customizable warriors.', 'Win the tournament and defeat the ultimate God of War.', 'Challenge the world in Doomsday Warrior for the SNES.', 'A unique 16-bit fighter where you can improve your character''s stats between matches. Master diverse special moves and conquer the Doomsday challenge.', NULL);
