INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Doraemon 4 - Nobita to Tsuki no Oukoku (Japan)', '1996', NaN, 'Epoch', '1', NaN, 'Action-platformer set in a futuristic Moon Kingdom.', 'Save the lunar civilization by mastering new high-tech gadgets.', 'Explore the Moon in Doraemon 4 for the Super Famicom.', 'The final 16-bit entry in the series, featuring the most refined gameplay and detailed sprites. A must-play for fans of Japanese action-platformers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Doraemon 4 - Nobita to Tsuki no Oukoku (Japan) [En by Sgt. Bow v0.94b] (~Doraemon 4 - In the Moon Kingdom)', '1996', NaN, 'Epoch', '1', NaN, 'Action-platformer set in a futuristic Moon Kingdom.', 'Experience Doraemon''s lunar quest with a full English translation.', 'Play Doraemon 4 in English on the Super Nintendo.', 'A dedicated fan translation that allows Western players to follow the charming story and use the futuristic gadgets correctly in this 16-bit moon adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dossun! Ganseki Battle (Japan)', '1994', NaN, 'Nintendo', '2', NaN, 'Falling-block puzzle game with a combat twist.', 'Defeat your opponents by dropping rocks and creating combos.', 'Battle with puzzles in Dossun! Ganseki Battle for SNES.', 'A unique 16-bit puzzler where your matches translate into attacks. Choose from various fantasy characters and use strategy to out-puzzle your rivals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dossun! Ganseki Battle (Japan) [En by Aeon Genesis v1.0] (~Dossun! Stone Battle)', '1994', NaN, 'Nintendo', '2', NaN, 'Falling-block puzzle game with a combat twist.', 'Experience the unique puzzle-combat with a full English translation.', 'Play Dossun! Stone Battle in English on the SNES.', 'The Aeon Genesis translation brings this hidden puzzle gem to English speakers. Master the stone-dropping mechanics and character specials in this 16-bit battle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Double Dragon V - The Shadow Falls (Europe)', '1995', NaN, 'Leland Interactive', '2', NaN, 'One-on-one fighting game based on the cult animated series.', 'Defeat the Shadow Master and his henchmen to save the city.', 'Fight the shadows in Double Dragon V: The Shadow Falls.', 'A departure from the beat ''em up roots, this entry is a traditional 16-bit fighter. Features a unique cast of characters and a tournament-style progression.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Double Dragon V - The Shadow Falls (USA)', '1995', NaN, 'Leland Interactive', '2', NaN, 'One-on-one fighting game based on the cult animated series.', 'Defeat the Shadow Master and his henchmen to save the city.', 'Fight the shadows in Double Dragon V: The Shadow Falls.', 'Master the special moves and combos of the Lee brothers in a 16-bit fighting tournament setting. Includes a variety of futuristic arenas and colorful villains.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Doukyuusei 2 (Japan) (NP)', '1995', NaN, 'Elf', '1', NaN, 'Visual novel and dating simulation sequel with a school setting.', 'Manage your social life and build relationships with your classmates.', 'Experience the high school drama of Doukyuusei 2 on SNES.', 'A refined 16-bit visual novel with beautiful artwork and multiple story paths. Navigate the complexities of teenage romance in this popular Japanese simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Down the World - Mervil''s Ambition (Japan)', '1992', NaN, 'ITL', '1', NaN, 'Traditional turn-based RPG with a focus on world-building and exploration.', 'Prevent a global catastrophe by fulfilling Mervil''s mysterious ambition.', 'Explore the world of Down the World on the Super Famicom.', 'A visually impressive late-gen RPG. Manage your party, explore detailed 16-bit environments, and engage in tactical battles to save the planet.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Downtown Nekketsu Baseball Monogatari - Yakyuu de Shoubu da! Kunio-kun (Japan)', '1993', NaN, 'Technos Japan', '2', NaN, 'Baseball simulation featuring the cast of the Kunio-kun (River City) series.', 'Win the baseball championship using wacky special moves and items.', 'Play the Kunio-kun baseball classic on the SNES.', 'Not your average sports game! Use hustle moves and unique 16-bit character abilities to score runs in this humorous and competitive Japanese title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon - The Bruce Lee Story (Europe)', '1993', NaN, 'Virgin Interactive', '1', NaN, 'One-on-one fighting game based on the Bruce Lee biopic film.', 'Defeat legendary masters and overcome Lee''s inner demons.', 'Master the dragon in Dragon: The Bruce Lee Story.', 'Experience Bruce Lee''s philosophy in a 16-bit fighter. Features fluid animations and a difficulty level that honors the legendary martial artist''s skill.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon - The Bruce Lee Story (USA)', '1993', NaN, 'Virgin Interactive', '1', NaN, 'One-on-one fighting game based on the Bruce Lee biopic film.', 'Defeat legendary masters and overcome Lee''s inner demons.', 'Master the dragon in Dragon: The Bruce Lee Story.', 'Battle through iconic scenes from the movie. Use speed and precision to overcome larger-than-life opponents in this challenging 16-bit combat title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Chomutujeon (Korea)', '1993', NaN, 'Bandai', '2', NaN, 'Rare Korean-exclusive Dragon Ball Z fighting game.', 'Defeat the Z-fighters in this unique 16-bit tournament.', 'Discover the rare DBZ: Chomutujeon for the SNES.', 'A fascinating piece of regional history. While mechanically simpler than the Butouden series, it offers a unique 16-bit perspective on the DBZ universe for collectors.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Chou Gokuuden - Kakusei Hen (Japan)', '1993', NaN, 'Bandai', '1', NaN, 'Cinematic adventure/fighting hybrid covering the Cell Saga.', 'Relive Gohan and Goku''s growth as they face the Android threat.', 'Play the cinematic DBZ: Chou Gokuuden Kakusei Hen.', 'A unique RPG-style take on DBZ. Focus on timing and story choices to trigger iconic 16-bit anime sequences during the battle against Cell.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Chou Gokuuden - Totsugeki Hen (Japan)', '1994', NaN, 'Bandai', '1', NaN, 'Cinematic adventure/fighting hybrid covering the early Dragon Ball story.', 'Follow Goku''s journey from his first meeting with Bulma.', 'Experience the origins in DBZ: Chou Gokuuden Totsugeki Hen.', 'Focuses on the early humor and action of the series. Use a Rock-Paper-Scissors style 16-bit combat system to relive the classic manga events.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Hyper Dimension (France)', '1996', NaN, 'Bandai', '2', NaN, 'The most advanced 16-bit DBZ fighting game with large sprites.', 'Master the Hyper combat system to defeat the strongest warriors.', 'Play the visually stunning DBZ: Hyper Dimension (France).', 'A masterpiece of 16-bit fighting. Features gorgeous animations, stage transitions, and a deep combat system that pushes the SNES hardware to its limit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Hyper Dimension (Japan)', '1996', NaN, 'Bandai', '2', NaN, 'The most advanced 16-bit DBZ fighting game with large sprites.', 'Master the Hyper combat system to defeat the strongest warriors.', 'Experience the original DBZ: Hyper Dimension (Japan).', 'Considered the definitive DBZ game of the era. Includes a deep story mode covering multiple sagas and the most fluid 16-bit combat mechanics in the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Hyper Dimension (Japan) [En by Unknown v1.0]', '1996', NaN, 'Bandai', '2', NaN, 'The most advanced 16-bit DBZ fighting game with large sprites.', 'Experience the peak of 16-bit DBZ combat with English text.', 'Play the Hyper Dimension English fan translation on SNES.', 'Allows Western fans to fully enjoy the story mode and character interactions in this technically superior 16-bit Dragon Ball Z fighter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - La Legende Saien (France)', '1993', NaN, 'Bandai', '2', NaN, 'Traditional 2D fighter featuring the split-screen Duel mechanic.', 'Defeat the Saiyan invaders and the tyrant Frieza.', 'Experience the classic DBZ: La Legende Saien on SNES.', 'The French version of Super Butouden 2. Famous for its massive arenas and cinematic special moves that take over the entire 16-bit screen.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - La Legende Saien (France) [En by Ginew v20010305] (~Dragon Ball Z - Super Butouden 2) (Incomplete)', '1993', NaN, 'Bandai', '2', NaN, 'Traditional 2D fighter featuring the split-screen Duel mechanic.', 'Battle through the Frieza and Cell sagas with English text.', 'Play the translated DBZ: La Legende Saien on the SNES.', 'An early English translation effort. While incomplete, it helps fans navigate the menus of this iconic 16-bit split-screen fighter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Butouden (France)', '1992', NaN, 'Bandai', '2', NaN, 'The first DBZ fighting game on the system with 13 playable characters.', 'Win the world tournament and defeat the legendary Super Saiyan.', 'Experience the original DBZ: Super Butouden on SNES.', 'Introduced the famous split-screen mechanic. Battle from afar with energy blasts or up close with 16-bit martial arts in this foundational title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Butouden (France) [En by Aeon Genesis v0.98] (~Dragon Ball Z - Super Butouden 1) (Incomplete)', '1992', NaN, 'Bandai', '2', NaN, 'The first DBZ fighting game on the system with 13 playable characters.', 'Experience the first Butouden game with translated menus.', 'Play the DBZ: Super Butouden English translation on SNES.', 'A fan translation that makes the story mode and menu system accessible to English-speaking 16-bit fighting game fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Butouden (Japan)', '1992', NaN, 'Bandai', '2', NaN, 'The first DBZ fighting game on the system with 13 playable characters.', 'Win the world tournament and defeat the legendary Super Saiyan.', 'Experience the original DBZ: Super Butouden (Japan).', 'Relive the excitement of the first Super Famicom DBZ fighter. Master the flying combat and iconic special moves in this 16-bit classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Butouden (Japan) (Sample)', '1992', NaN, 'Bandai', '2', NaN, 'The first DBZ fighting game on the system with 13 playable characters.', 'Explore a pre-release version of the first DBZ fighter.', 'Check out the DBZ: Super Butouden Sample version on SNES.', 'A rare Japanese promotional cartridge. It features limited characters and stages, offering a glimpse into the development of the 16-bit DBZ fighting engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Butouden 2 (Japan)', '1993', NaN, 'Bandai', '2', NaN, 'Widely considered the best of the Butouden trilogy on SNES.', 'Defeat Broly and Bojack in this epic 16-bit fighting game.', 'Master the combat in DBZ: Super Butouden 2 (Japan).', 'Features an incredible story mode with branching paths, improved split-screen mechanics, and a legendary 16-bit soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Butouden 2 (Japan) (Rev A)', '1993', NaN, 'Bandai', '2', NaN, 'Widely considered the best of the Butouden trilogy on SNES.', 'Defeat Broly and Bojack in the refined Rev A version.', 'Play the polished DBZ: Super Butouden 2 (Rev A) on SNES.', 'An updated Japanese version that fixed several bugs and balanced character stats for a more competitive 16-bit fighting experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Butouden 3 (Japan)', '1994', NaN, 'Bandai', '2', NaN, 'Fast-paced fighter focusing on the Buu Saga with a larger roster.', 'Defeat Majin Buu and prove who is the ultimate 16-bit warrior.', 'Blast off in DBZ: Super Butouden 3 (Japan).', 'Removes the story mode to focus on pure arcade action. Features fast gameplay and a high-energy 16-bit tournament mode for Dragon Ball fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Gokuu Den - Kakusei Hen (Japan) [En by Ginew v20010405] (~Dragon Ball Z - The Legend of Goku 2) (Incomplete)', '1994', NaN, 'Bandai', '1', NaN, 'Cinematic adventure/fighting hybrid covering the Cell Saga.', 'Experience Gohan''s transformation into a hero with English text.', 'Play the DBZ: The Legend of Goku 2 English mod on SNES.', 'An incomplete but helpful translation of Kakusei Hen. Relive the dramatic moments of the Cell Games in 16-bit cinematic glory.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Gokuu Den - Totsugeki Hen (Japan) [En by Kakkoii v0.313] (~Dragon Ball Z - The Legend of Goku 1) (Incomplete)', '1994', NaN, 'Bandai', '1', NaN, 'Cinematic adventure/fighting hybrid covering the early Dragon Ball story.', 'Follow young Goku''s adventures with translated English text.', 'Play the DBZ: The Legend of Goku 1 English mod on SNES.', 'An early translation of Totsugeki Hen. Follow the classic story from the beginning with 16-bit sprites and tactical combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Saiya Densetsu (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Strategic turn-based RPG using a card-based battle system.', 'Lead the Z-fighters from the Raditz saga to the final fight with Frieza.', 'Master the cards in DBZ: Super Saiya Densetsu (Japan).', 'A deep JRPG where cards determine your speed, power, and defense. Manage your party''s Ki and explore the 16-bit Dragon Ball world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Saiya Densetsu (Japan) (Rev 1) [En by Klepto v0.96] (~Dragon Ball Z - Legend of the Saiyans) (Incomplete)', '1992', NaN, 'Bandai', '1', NaN, 'Strategic turn-based RPG using a card-based battle system.', 'Experience the Saiyan legend with an early English translation.', 'Play DBZ: Legend of the Saiyans in English on the SNES.', 'An early translation effort by Klepto. While not perfect, it allows fans to navigate the complex 16-bit card-based battle system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Saiya Densetsu (Japan) (Rev 1) [En by Saiya v0.99Final] (~Dragon Ball Z - Legend of the Saiyans)', '1992', NaN, 'Bandai', '1', NaN, 'Strategic turn-based RPG using a card-based battle system.', 'Experience the Saiyan legend with the definitive English translation.', 'The complete DBZ: Legend of the Saiyans translation on SNES.', 'The best way to play this 16-bit RPG. Follow the story of Goku and Vegeta with fully translated dialogue and a perfectly explained card system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Super Saiya Densetsu (Japan) (Rev A)', '1992', NaN, 'Bandai', '1', NaN, 'Strategic turn-based RPG using a card-based battle system.', 'Lead the Z-fighters to victory in the refined Rev A version.', 'Play the polished DBZ: Super Saiya Densetsu (Rev A) on SNES.', 'An official revision that fixed game-breaking bugs and balanced the encounter rates for a better 16-bit RPG experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Ultime Menace (France)', '1994', NaN, 'Bandai', '2', NaN, 'The French release of Super Butouden 3, covering the Majin Buu era.', 'Defeat the ultimate menace in this 16-bit fighting classic.', 'Experience DBZ: Ultime Menace on the Super Nintendo.', 'The official European (French) version. Features the same high-speed combat and iconic DBZ characters in a polished 16-bit format.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Ultime Menace (France) [En by Aeon Genesis v1.0] (~Dragon Ball Z - Super Butouden 3) (Incomplete)', '1994', NaN, 'Bandai', '2', NaN, 'The French release of Super Butouden 3, covering the Majin Buu era.', 'Experience the final Butouden battle with English text.', 'Play the DBZ: Ultime Menace English translation on SNES.', 'An Aeon Genesis project that translates the menus and victory quotes, making this 16-bit brawler fully accessible to Western fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Ball Z - Ultime Menace (France) [En by Saiya+Vice v1.1] (~Dragon Ball Z - Super Butouden 3) (Incomplete)', '1994', NaN, 'Bandai', '2', NaN, 'The French release of Super Butouden 3, covering the Majin Buu era.', 'Experience the final Butouden battle with English text.', 'Play the DBZ: Ultime Menace English translation (Saiya+Vice).', 'Another high-quality translation effort for the third Butouden game, ensuring fans can enjoy the 16-bit tournament action in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Knight 4 (Japan)', '1994', NaN, 'Elf', '1', NaN, 'Tactical turn-based RPG with a focus on adult-oriented storytelling.', 'Lead your army to victory and uncover the secrets of the Dragon Knight.', 'Experience the epic Dragon Knight 4 on the Super Famicom.', 'A deep tactical RPG featuring large-scale battles and a multi-generational story. Manage your units across a grid-based battlefield in this visually detailed 16-bit Japanese classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest I & II (Japan)', '1993', NaN, 'Chunsoft', '1', NaN, 'Remake of the first two legendary JRPGs with updated 16-bit graphics.', 'Defeat the Dragonlord and Hargon to restore peace to Alefgard.', 'Play the Dragon Quest I & II collection on the SNES.', 'A beautiful 16-bit overhaul of the NES originals. Experience the foundations of the JRPG genre with improved music, smoother gameplay, and refined inventory systems.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest I & II (Japan) [En by RPGOne v2.0] (Dragon Quest Version)', '1993', NaN, 'Chunsoft', '1', NaN, 'Remake of the first two legendary JRPGs with a faithful fan translation.', 'Experience the origins of the series with the Quest terminology.', 'Play Dragon Quest I & II in English on the Super Nintendo.', 'The RPGOne translation provides a modern, faithful script. Relive the epic journey of the descendants of Erdrick with beautiful 16-bit sprites and fully translated menus.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest I & II (Japan) [En by RPGOne v2.0] (Dragon Warrior Version)', '1993', NaN, 'Chunsoft', '1', NaN, 'Remake of the first two legendary JRPGs with Dragon Warrior terminology.', 'Defeat the Dragonlord in this nostalgic NES-style translation.', 'Play Dragon Warrior I & II in English on the SNES.', 'A special version of the RPGOne translation that uses the classic 8-bit Western names and terms, bringing 16-bit polish to your childhood memories.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest III - Soshite Densetsu e... (Japan) [En by DaMarsMan v1.0] (~Dragon Quest III - Into the Legend)', '1996', NaN, 'Chunsoft', '1', NaN, 'One of the most ambitious JRPGs ever made, featuring a deep class system.', 'Assemble a party of heroes to defeat the archfiend Baramos.', 'Play the legendary Dragon Quest III remake in English on SNES.', 'The definitive version of a masterpiece. Features a personality system, beautiful 16-bit animations, and a massive world that sets the standard for the entire genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest III - Soshite Densetsu he... (Japan)', '1996', NaN, 'Chunsoft', '1', NaN, 'One of the most ambitious JRPGs ever made, featuring a deep class system.', 'Assemble a party of heroes to defeat the archfiend Baramos.', 'Experience the original Dragon Quest III on Super Famicom.', 'A technical marvel for the system. Build your own party from scratch and explore a world filled with secrets, day/night cycles, and the iconic 16-bit Pachisi board game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest V - Tenkuu no Hanayome (Japan)', '1992', NaN, 'Chunsoft', '1', NaN, 'The first Dragon Quest on SNES, featuring a story that spans generations.', 'Choose a bride and raise a family of heroes to defeat Nimzo.', 'Experience the emotional Dragon Quest V on the SNES.', 'A groundbreaking JRPG where you follow the protagonist from childhood to parenthood. Master the monster-recruitment system in this beautifully written 16-bit epic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest V - Tenkuu no Hanayome (Japan) [En by Byuu+spSpiff v0.91] (~Dragon Quest V - Bride of Heaven)', '1992', NaN, 'Chunsoft', '1', NaN, 'The first Dragon Quest on SNES, featuring a story that spans generations.', 'Experience the Bride of Heaven story with an English translation.', 'Play Dragon Quest V in English on the Super Nintendo.', 'A dedicated fan translation by Byuu and Spiff. Follow the hero''s life-long journey with fully translated dialogue and a refined 16-bit interface.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest V - Tenkuu no Hanayome (Japan) [En by DeJap+Partial v2.01Final] (~Dragon Quest V - Bride of Heaven)', '1992', NaN, 'Chunsoft', '1', NaN, 'The first Dragon Quest on SNES, featuring a story that spans generations.', 'Experience the Bride of Heaven story with an English translation.', 'Enjoy the DeJap translation of Dragon Quest V on SNES.', 'One of the most famous fan translations in the scene. Experience the complete narrative and monster-taming mechanics of this 16-bit masterpiece in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest VI - Maboroshi no Daichi (Japan)', '1995', NaN, 'Chunsoft', '1', NaN, 'The final 16-bit Dragon Quest, featuring a massive dual-world system.', 'Travel between the Dream World and Reality to stop Deathtamoor.', 'Explore two worlds in Dragon Quest VI for the SNES.', 'A visual and technical peak for the series. Features a complex job system and an epic story that weaves through two massive 16-bit world maps.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Quest VI - Maboroshi no Daichi (Japan) [En by NoPrgress v0.90Beta2] (~Dragon Quest VI - Land of Illusion)', '1995', NaN, 'Chunsoft', '1', NaN, 'The final 16-bit Dragon Quest, featuring a massive dual-world system.', 'Uncover the truth of the Land of Illusion with English text.', 'Play the Dragon Quest VI English fan translation on SNES.', 'A monumental translation effort that allows Western players to experience the deep class system and reality-bending story of the final 16-bit DQ title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Slayer - Eiyuu Densetsu (Japan)', '1992', NaN, 'Nihon Falcom', '1', NaN, 'Traditional turn-based RPG and the origin of the Legend of Heroes series.', 'Lead Prince Selios on a quest to reclaim his kingdom.', 'Discover the classic Dragon Slayer: Eiyuu Densetsu on SNES.', 'A foundational JRPG with a focus on party management and exploration. Experience the roots of Falcom’s legendary series with polished 16-bit visuals and music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Slayer - Eiyuu Densetsu (Japan) (Rev A) (NP)', '1992', NaN, 'Nihon Falcom', '1', NaN, 'Traditional turn-based RPG and the origin of the Legend of Heroes series.', 'Lead Prince Selios on a quest to reclaim his kingdom.', 'Play the refined Dragon Slayer (Rev A) on the SNES.', 'The Nintendo Power revision of the classic Falcom RPG. Features minor bug fixes and balanced encounter rates for a more consistent 16-bit adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon Slayer - Eiyuu Densetsu II (Japan)', '1994', NaN, 'Nihon Falcom', '1', NaN, 'The epic sequel featuring a new generation of heroes and a vast world.', 'Defeat the mysterious Emperor and restore the light to the world.', 'Experience the sequel Dragon Slayer II on the Super Famicom.', 'Improves upon the original with more complex tactical battles and a deeper narrative. A must-play for fans of classic 16-bit JRPG progression.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon View (USA)', '1995', NaN, 'Kemco', '1', NaN, 'Action-RPG with a unique hybrid perspective of side-scrolling and 3D.', 'Stop the resurrection of a dark god in the world of Keire.', 'Embark on a quest in Dragon View for the Super Nintendo.', 'A spiritual successor to Drakkhen. Features a 3D overworld and fluid side-scrolling combat, offering a unique and atmospheric 16-bit adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon''s Earth (Japan)', '1993', NaN, 'Technosoft', '1', NaN, 'Real-time strategy game with a focus on resource and unit management.', 'Conquer the dragon-infested lands by building a powerful army.', 'Master the strategy of Dragon''s Earth on the SNES.', 'A rare 16-bit RTS where you manage troops and combat mythical creatures. Features a clean interface and challenging AI for fans of tactical gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon''s Lair (Europe) (Beta)', '1993', NaN, 'Crawfish Interactive', '1', NaN, 'Side-scrolling action platformer based on the famous laserdisc game.', 'Rescue Princess Daphne from the dragon Singe in the wizard''s castle.', 'Test your reflexes in the Dragon''s Lair Beta on SNES.', 'A pre-release version of the challenging platformer. Discover early level designs and timing windows used during the development of this 16-bit cinematic adaptation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon''s Lair (Europe) (En,Fr,De,Es,It,Nl,Sv)', '1993', NaN, 'Crawfish Interactive', '1', NaN, 'Side-scrolling action platformer based on the famous laserdisc game.', 'Rescue Princess Daphne from the dragon Singe in the wizard''s castle.', 'Face the danger of Dragon''s Lair for the Super Nintendo.', 'A reimagining of the arcade classic as a traditional platformer. Navigate a castle full of traps and monsters with high-quality 16-bit animation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon''s Lair (USA)', '1993', NaN, 'Crawfish Interactive', '1', NaN, 'Side-scrolling action platformer based on the famous laserdisc game.', 'Rescue Princess Daphne from the dragon Singe in the wizard''s castle.', 'Face the danger of Dragon''s Lair for the Super Nintendo.', 'Known for its high difficulty and detailed character sprites. Master the precision jumps and weapon usage to survive the 16-bit dragon''s lair.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dragon''s Magic (Japan)', '1991', NaN, 'Ray Force', '1', NaN, 'Falling-block puzzle game with a magical theme.', 'Clear the screen by matching mystical orbs and gems.', 'Solve the puzzles of Dragon''s Magic on the Super Famicom.', 'A colorful and fast-paced 16-bit puzzler. Use special magical abilities to clear the board and compete against challenging AI or a second player.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Drakkhen (Europe)', '1989', NaN, 'Infogrames', '1', NaN, 'Innovative 3D exploration RPG with a unique hybrid perspective.', 'Retrieve the eight dragon tears to save the world of Drakkhen.', 'Experience the surreal world of Drakkhen on the SNES.', 'A cult classic known for its eerie atmosphere and open-world exploration. Manage a party of four through a 3D-rendered landscape in this unique 16-bit adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Drakkhen (Germany)', '1989', NaN, 'Infogrames', '1', NaN, 'Innovative 3D exploration RPG with a unique hybrid perspective.', 'Retrieve the eight dragon tears to save the world of Drakkhen.', 'Experience the surreal world of Drakkhen on the SNES.', 'The German localization of the innovative RPG. Experience the mysterious lore and challenging 3D navigation with fully translated text for the 16-bit console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Drakkhen (Japan)', '1990', NaN, 'Infogrames', '1', NaN, 'Innovative 3D exploration RPG with a unique hybrid perspective.', 'Retrieve the eight dragon tears to save the world of Drakkhen.', 'Explore the Japanese version of Drakkhen on the SNES.', 'The original Japanese release, featuring the same haunting soundtrack and groundbreaking 3D-style overworld that defined this experimental 16-bit title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Drakkhen (USA)', '1989', NaN, 'Infogrames', '1', NaN, 'Innovative 3D exploration RPG with a unique hybrid perspective.', 'Retrieve the eight dragon tears to save the world of Drakkhen.', 'Explore the mysterious world of Drakkhen on the SNES.', 'One of the earliest examples of a 3D world on home consoles. Master the complex UI and survive the strange creatures of the 16-bit night.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dream Basketball - Dunk & Hoop (Japan)', '1994', NaN, 'Human Entertainment', '2', NaN, 'Arcade-style basketball game featuring high-energy dunks.', 'Win the tournament by outscoring rival teams with flashy plays.', 'Hit the court in Dream Basketball: Dunk & Hoop for SNES.', 'A fast-paced 16-bit sports game with a focus on arcade fun. Execute spectacular dunks and master the timing-based shooting system to become the champion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dream Maze - Kigurumi Daibouken (Japan) [En by KingMike v1.0b] (~Dream Maze - The Kigurumi Adventure)', '1994', NaN, 'Naxat Soft', '1', NaN, 'First-person dungeon crawler where characters wear animal costumes.', 'Navigate the Dream Maze to save the world of fantasy.', 'Explore the Dream Maze in English on the Super Nintendo.', 'A quirky 16-bit dungeon crawler translated by KingMike. Use different Kigurumi (animal suits) to gain powers and explore colorful first-person labyrinths.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dream TV (USA)', '1992', NaN, 'Loriciel', '4', NaN, 'Action-puzzle game set inside a surreal television world.', 'Navigate through various channels to find the exit and escape the TV.', 'Escape the nightmare in Dream TV for the Super Nintendo.', 'A unique 16-bit title where you switch between two characters to solve puzzles. Explore diverse stages based on TV genres while avoiding traps and enemies in this surreal adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dream TV (USA) (Beta1)', '1992', NaN, 'Loriciel', '4', NaN, 'Action-puzzle game set inside a surreal television world.', 'Explore the early channel designs and experimental mechanics.', 'Check out the Dream TV Beta 1 version on the SNES.', 'An early development build of the TV-themed puzzle-platformer. Discover initial level layouts and mechanical concepts that were being tested for the 16-bit retail release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dream TV (USA) (Beta2)', '1992', NaN, 'Loriciel', '4', NaN, 'Action-puzzle game set inside a surreal television world.', 'Explore the early channel designs and experimental mechanics.', 'Check out the Dream TV Beta 2 version on the SNES.', 'A later development build featuring refined character controls and more complete stage designs compared to the first beta of this 16-bit puzzler.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Drift King Shutokou Battle ''94 - Tsuchiya Keiichi & Bandou Masaaki (Japan)', '1994', NaN, 'Genki', '1', NaN, 'Street racing simulation featuring the legendary Drift King Keiichi Tsuchiya.', 'Win the Shutokou highway races and become the king of drifting.', 'Experience the drift culture in Drift King Shutokou Battle ''94.', 'A foundational title for fans of Japanese car culture. Master the art of drifting on the Tokyo expressway using Mode 7 16-bit graphics and realistic car physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Drift King Shutokou Battle 2 - Tsuchiya Keiichi & Bandou Masaaki (Japan)', '1995', NaN, 'Genki', '1', NaN, 'Street racing simulation with enhanced tuning and more car models.', 'Defeat the highway racing gangs and maintain your title as Drift King.', 'Master the drift in Drift King Shutokou Battle 2 on SNES.', 'Includes more customization and a deeper career mode. Fine-tune your machine to handle the tightest corners of the 16-bit Japanese highways.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dual Orb - Seirei Tama Densetsu (Japan)', '1992', NaN, 'I''MAX', '1', NaN, 'Traditional turn-based JRPG with a focus on elemental spirits.', 'Journey across the land to collect the powerful Spirit Orbs.', 'Discover the classic RPG Dual Orb on the Super Famicom.', 'A polished 16-bit Japanese exclusive featuring beautiful character portraits and a classic world-saving narrative for fans of the golden age of JRPGs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dual Orb II (Japan)', '1994', NaN, 'I''MAX', '1', NaN, 'Visually stunning turn-based JRPG with cinematic battle animations.', 'Protect the world from an ancient evil alongside a cast of unique heroes.', 'Experience the epic Dual Orb II on the Super Famicom.', 'Known for its incredible 16-bit graphics and dynamic camera angles during combat. A hidden gem with an emotional story and a deep magic system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dual Orb II (Japan) [En by TransCorp v1.5]', '1994', NaN, 'I''MAX', '1', NaN, 'Visually stunning turn-based JRPG with cinematic battle animations.', 'Experience the epic Dual Orb II story with a full English translation.', 'Play Dual Orb II in English on the Super Nintendo.', 'The definitive fan translation by TransCorp. Now Western players can enjoy the cinematic 16-bit combat and deep lore of this Japanese RPG masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Duel, The - Test Drive II (Europe)', '1990', NaN, 'Accolade', '1', NaN, 'First-person driving simulation featuring high-performance sports cars.', 'Outrun the police and your opponent in a high-speed cross-country race.', 'Test your driving skills in The Duel: Test Drive II for SNES.', 'Choose between legendary cars like the Porsche 959 and Ferrari F40. Features realistic cockpit views and challenging 16-bit mountain road navigation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Duel, The - Test Drive II (USA)', '1990', NaN, 'Accolade', '1', NaN, 'First-person driving simulation featuring high-performance sports cars.', 'Outrun the police and your opponent in a high-speed cross-country race.', 'Test your driving skills in The Duel: Test Drive II for SNES.', 'A classic simulation focusing on speed and avoidance. Watch your tachometer and avoid road hazards in this pioneering 16-bit racing title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dun Quest - Majin Fuuin no Densetsu (Japan)', '1995', NaN, 'Pandora Box', '1', NaN, 'First-person dungeon crawler with turn-based combat and riddles.', 'Seal the ancient demon by navigating a perilous labyrinth.', 'Conquer the maze in Dun Quest for the Super Famicom.', 'A traditional blobber style RPG. Manage your party''s resources and map out complex 16-bit floors while battling mythological monsters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dungeon Master (Europe)', '1992', NaN, 'FTL Games', '1', NaN, 'Pioneering first-person dungeon crawler with real-time combat.', 'Navigate the deep dungeon to defeat the evil wizard Lord Chaos.', 'Experience the classic Dungeon Master on the Super Nintendo.', 'A revolutionary RPG that introduced real-time interaction. Manage hunger, thirst, and light while casting spells in a claustrophobic 16-bit environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dungeon Master (Japan)', '1992', NaN, 'FTL Games', '1', NaN, 'Pioneering first-person dungeon crawler with real-time combat.', 'Navigate the deep dungeon to defeat the evil wizard Lord Chaos.', 'Explore the Japanese version of Dungeon Master on SNES.', 'The localized release of the Western RPG hit. Features the same deep mechanics and atmospheric 16-bit dungeon crawling that defined the genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dungeon Master (Japan) (Rev A)', '1992', NaN, 'FTL Games', '1', NaN, 'Pioneering first-person dungeon crawler with real-time combat.', 'Navigate the deep dungeon to defeat the evil wizard Lord Chaos.', 'Play the refined Dungeon Master (Rev A) on the SNES.', 'The updated Japanese revision featuring minor bug fixes and UI improvements for a more stable 16-bit dungeoneering experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dungeon Master (USA)', '1992', NaN, 'FTL Games', '1', NaN, 'Pioneering first-person dungeon crawler with real-time combat.', 'Navigate the deep dungeon to defeat the evil wizard Lord Chaos.', 'Master the spells in Dungeon Master for the Super Nintendo.', 'One of the most immersive RPGs of its time. Master the rune-based magic system and solve environmental puzzles to survive the 16-bit darkness.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dynamaite the Las Vegas (Japan)', '1995', NaN, 'Naxat Soft', '1', NaN, 'Casino simulation featuring various gambling games in Las Vegas.', 'Win big at the tables and become a high-roller in Vegas.', 'High stakes fun in Dynamaite the Las Vegas for SNES.', 'Includes poker, blackjack, and slot machines. Features a vibrant 16-bit casino atmosphere with unique character interactions and gambling challenges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Dynamic Stadium (Japan)', '1993', NaN, 'Electronic Arts', '2', NaN, 'Arcade-style baseball simulation with a focus on dynamic action.', 'Lead your team to victory in a high-energy baseball tournament.', 'Step up to the plate in Dynamic Stadium for the Super Famicom.', 'A fast-paced 16-bit baseball game. Features smooth animations and intuitive controls, making it accessible for both casual and hardcore sports fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'E.V.O. - Search for Eden (USA)', '1995', NaN, 'Almanic', '1', NaN, 'Side-scrolling action-RPG where you guide a creature through evolution.', 'Evolve from a simple fish to a complex mammal to reach Eden.', 'Experience the unique E.V.O. Search for Eden on the SNES.', 'A cult classic by Enix. Earn evolution points to customize your creature’s body parts, adapting to survive different 16-bit prehistoric eras.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Earth Light - Luna Strike (Japan)', '1994', NaN, 'Hudson Soft', '1', NaN, 'Turn-based tactical mecha strategy game set in a futuristic lunar war.', 'Command your unit of mechs to defeat the invading lunar forces.', 'Master the tactics of Earth Light: Luna Strike on SNES.', 'The sequel to Earth Light, featuring refined hex-based combat, improved 16-bit visuals, and a more complex branching mission structure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Earth Light (Japan)', '1994', NaN, 'Hudson Soft', '1', NaN, 'Turn-based tactical mecha strategy game featuring hex-based combat.', 'Defeat enemy forces using a variety of specialized mechs and units.', 'Experience the strategic Earth Light on the Super Famicom.', 'A hidden gem of the strategy genre. Utilize terrain and unit positioning to win intense 16-bit battles in this beautifully animated sci-fi title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound (Mar 27, 1995 prototype)', '1995', NaN, 'Ape Inc.', '1', NaN, 'Legendary modern-day JRPG featuring a boy with psychic powers.', 'Discover a pre-release version of the game with subtle differences.', 'Check out the rare EarthBound Prototype for the SNES.', 'A fascinating look at the localization process. Features minor text variations and early translations of the 16-bit masterpiece known as Mother 2.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound (USA)', '1995', NaN, 'Ape Inc.', '1', NaN, 'Legendary modern-day JRPG known for its quirky humor and charm.', 'Travel the world with your friends to stop the cosmic destroyer Giygas.', 'Experience the cult classic EarthBound on the Super Nintendo.', 'A unique RPG set in a modern world. Fight hippies and street signs, use psychic powers, and enjoy a brilliant 16-bit story about friendship and courage.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound (USA) [Hack by Blue Antoid v2.0] (~JonBound - Dark Future)', '1995', NaN, 'Ape Inc.', '1', NaN, 'Dark and gritty fan-made reimagining of the EarthBound universe.', 'Navigate a post-apocalyptic future to change the fate of the world.', 'Explore the dark EarthBound: JonBound - Dark Future mod.', 'A total conversion hack featuring new graphics, a darker narrative tone, and a revamped 16-bit difficulty for veterans of the original game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound (USA) [Hack by EBGirl v2.5] (~Mother 2.5 - The Giftman Chronicles)', '1995', NaN, 'Ape Inc.', '1', NaN, 'Holiday-themed fan expansion featuring new characters and story.', 'Help Giftman save the holiday season in the world of Mother.', 'Play EarthBound: The Giftman Chronicles on the Super Nintendo.', 'A charming hack that replaces the main cast and adds a festive story, new items, and 16-bit winter-themed environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound (USA) [Hack by Michael Cayer+Tomato v2.0] (New Game Plus Plus)', '1995', NaN, 'Ape Inc.', '1', NaN, 'Enhanced version of the original game with a New Game Plus feature.', 'Relive the journey with your endgame stats and new challenges.', 'Experience EarthBound New Game Plus Plus on the SNES.', 'Allows players to restart the story with their previous levels and equipment. Features rebalanced 16-bit enemies to keep the challenge fresh.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound (USA) [Hack by Mr. Accident v1.1] (~EarthBound - 10th Anniversary Celebration)', '1995', NaN, 'Ape Inc.', '1', NaN, 'Comprehensive mod celebrating the legacy of the series.', 'Experience a refined version of the classic game with new secrets.', 'Celebrate EarthBound with the 10th Anniversary hack.', 'Features numerous quality-of-life improvements, restored Japanese content, and subtle 16-bit graphical touch-ups for the ultimate fan experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound (USA) [Hack by Mr. Tenda v0.908] (~Mr. Saturn in Hat Quest)', '1995', NaN, 'Ape Inc.', '1', NaN, 'Quirky fan-adventure starring the iconic Mr. Saturn.', 'Embark on a small but strange quest as a resident of Saturn Valley.', 'Play as a Mr. Saturn in Hat Quest on the Super Nintendo.', 'A humorous and creative hack that focuses on the weirdest characters in the series. Navigate 16-bit puzzles with the unique perspective of a Mr. Saturn.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound (USA) [Hack by Radiation v1.02] (~Arn''s Winter Quest - Gway Edition)', '1995', NaN, 'Ape Inc.', '1', NaN, 'Atmospheric fan-sequel following Arn on a cold and mysterious journey.', 'Survive the winter and uncover the secrets of a new 16-bit world.', 'Play Arn''s Winter Quest - Gway Edition on the SNES.', 'Created by Radiation (Toby Fox). A legendary hack known for its unique music, somber atmosphere, and innovative use of the 16-bit EarthBound engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound (USA) [Hack by Rofish v0.50] (~EarthBound Battler) (Battle Mode)', '1995', NaN, 'Ape Inc.', '1', NaN, 'Combat-only mod that focuses entirely on the battle system.', 'Defeat waves of enemies in a specialized battle arena.', 'Test your combat skills in EarthBound Battler on the SNES.', 'Skip the exploration and dive straight into the 16-bit turn-based combat. Features a gauntlet of bosses and enemies to challenge your tactical mastery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'EarthBound Randomizer', '1995', NaN, 'Ape Inc.', '1', NaN, 'A procedural generation mod that reshuffles the entire game.', 'Complete the game with randomized items, enemies, and stats.', 'Experience the chaos of the EarthBound Randomizer on SNES.', 'Every playthrough is unique! Items, gift boxes, and enemy encounters are shuffled, forcing players to adapt their 16-bit strategy on the fly.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Earthworm Jim (Europe)', '1994', NaN, 'Shiny Entertainment', '1', NaN, 'Surreal side-scrolling platformer with run-and-gun elements.', 'Rescue Princess What''s-Her-Name from the evil Psy-Crow.', 'Experience the wacky world of Earthworm Jim on SNES.', 'A masterpiece of 16-bit animation. Control Jim, a worm in a super-suit, through bizarre levels like New Junk City. Use your head as a whip and blast enemies with high-tech blasters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Earthworm Jim (Japan)', '1994', NaN, 'Shiny Entertainment', '1', NaN, 'Surreal side-scrolling platformer with run-and-gun elements.', 'Rescue Princess What''s-Her-Name from the evil Psy-Crow.', 'Play the Japanese version of Earthworm Jim on the SNES.', 'The Super Famicom release of the cult classic. Features the same fluid 16-bit animations and eccentric humor that made Jim a global gaming icon in the 90s.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Earthworm Jim (USA)', '1994', NaN, 'Shiny Entertainment', '1', NaN, 'Surreal side-scrolling platformer with run-and-gun elements.', 'Rescue Princess What''s-Her-Name from the evil Psy-Crow.', 'Play the definitive Earthworm Jim on the Super Nintendo.', 'Battle through surreal environments with a groovy soundtrack. Master the helicopter-head spin and the Andy Asteroids racing levels in this peak 16-bit platformer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Earthworm Jim (USA) (GamesMaster Special Edition)', '1994', NaN, 'Shiny Entertainment', '1', NaN, 'Timed score-attack version of the classic platformer.', 'Achieve the highest score in specific levels within a time limit.', 'Play the Earthworm Jim GamesMaster Special Edition.', 'A rare promotional version used for the UK TV show GamesMaster. It features a timer and scoring system, challenging players to speedrun through 16-bit levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Earthworm Jim 2 (Europe)', '1995', NaN, 'Shiny Entertainment', '2', NaN, 'Absurdist side-scrolling platformer with diverse gameplay styles.', 'Rescue the Princess again and defeat the evil Psy-Crow.', 'Groovy! Play Earthworm Jim 2 on the Super Nintendo.', 'More creative and weirder than the first. Features levels ranging from digging through dirt to flying a giant balloon. A visual and musical 16-bit tour de force.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Earthworm Jim 2 (USA)', '1995', NaN, 'Shiny Entertainment', '2', NaN, 'Absurdist side-scrolling platformer with diverse gameplay styles.', 'Rescue the Princess again and defeat the evil Psy-Crow.', 'Groovy! Play Earthworm Jim 2 on the Super Nintendo.', 'Utilize new weapons and Snott the backpack parasite. This sequel pushes the SNES to its limits with incredible 16-bit sprite work and hilarious scenarios.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Earthworm Jim 2 (USA) (Beta)', '1995', NaN, 'Shiny Entertainment', '2', NaN, 'Absurdist side-scrolling platformer with diverse gameplay styles.', 'Rescue the Princess again and defeat the evil Psy-Crow.', 'Explore the Earthworm Jim 2 Beta on the Super Nintendo.', 'A pre-release build featuring early level concepts and music tracks. See how the 16-bit madness was refined before the final release of this iconic sequel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Edono Kiba (Japan)', '1995', NaN, 'Studio Pierrot', '1', NaN, 'Cyberpunk side-scrolling beat ''em up and action game.', 'Defeat the rogue machines and clean up the futuristic streets.', 'Battle in the cyberpunk world of Edono Kiba for SNES.', 'Set in a futuristic Tokyo (Edo). Features large character sprites and fast-paced 16-bit combat. Use your sword to slice through cybernetic enemies in this atmospheric Japanese title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Eek! The Cat (Europe)', '1994', NaN, 'Radium', '1', NaN, 'Puzzle-platformer based on the animated series about a clumsy cat.', 'Protect the clumsy family members from hazards as they walk.', 'Join the misadventures in Eek! The Cat for the SNES.', 'Help Eek clear the path for the Sleepy family. Use Eek''s resilience to take hits and move objects in this colorful and humorous 16-bit adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Eek! The Cat (USA)', '1994', NaN, 'Radium', '1', NaN, 'Puzzle-platformer based on the animated series about a clumsy cat.', 'Protect the clumsy family members from hazards as they walk.', 'Join the misadventures in Eek! The Cat for the SNES.', 'Navigate through levels inspired by the cartoon. A unique 16-bit escort-puzzle game where your patience and timing are tested to the limit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Eien no Filerna (Japan)', '1995', NaN, 'Taito', '1', NaN, 'Traditional turn-based JRPG set in an underwater world.', 'Help Filena reclaim her kingdom and uncover her true identity.', 'Discover the underwater RPG Eien no Filerna on SNES.', 'Based on a novel series. Features a unique world where humans live under the sea. Manage your party and enjoy the classic 16-bit JRPG storytelling and combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Eien no Filerna (Japan) [En by Satsu v0.98] (~Eternal Filena)', '1995', NaN, 'Taito', '1', NaN, 'Traditional turn-based JRPG set in an underwater world.', 'Experience the story of Eternal Filena with an English translation.', 'Play Eternal Filena in English on the Super Nintendo.', 'The fan translation by Satsu brings this hidden gem to the West. Follow Filena''s journey through a 16-bit world filled with political intrigue and ancient magic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Elfaria - The Isle of the Blest (Japan)', '1993', NaN, 'Hudson Soft', '1', NaN, 'Turn-based JRPG with a unique item-based progression system.', 'Stop the world from being drained of its life force.', 'Explore the Isle of the Blest in Elfaria for the SNES.', 'A unique JRPG that replaces traditional leveling with equipment-based growth. Features a beautiful 16-bit world map and strategic turn-based battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Elfaria II - The Quest of the Meld (Japan)', '1994', NaN, 'Hudson Soft', '1', NaN, 'Turn-based JRPG featuring party-based combat and exploration.', 'Solve the mystery of the Meld and save the continent of Elfaria.', 'Experience the sequel Elfaria II on the Super Famicom.', 'Improves upon the original with more refined combat and a deeper narrative. A classic 16-bit JRPG experience for fans of the genre''s golden age.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Elite Soccer (USA)', '1993', NaN, 'Rage Software', '2', NaN, 'Deep soccer simulation with a tactical overhead perspective.', 'Win the world cup by mastering team strategy and precise passing.', 'Experience the pitch in Elite Soccer for the Super Nintendo.', 'Known as World Cup Striker in Europe. Offers a more realistic take on the sport with detailed 16-bit tactics, formation management, and smooth ball physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Elnard (Japan)', '1990', NaN, 'NCS', '1', NaN, 'Traditional turn-based JRPG with a focus on exploration.', 'Discover the secret of the Seven Stones and save the world.', 'Master the cards and combat in Elnard for the SNES.', 'Known as The 7th Saga in the West. This original Japanese version is famous for being more balanced than its punishingly difficult Western counterpart in 16-bit glory.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Emerald Dragon (Japan)', '1995', NaN, 'Glodia', '1', NaN, 'Turn-based JRPG with a focus on dragon lore and cinematic story.', 'Lead a hero and a dragon-girl to prevent a global catastrophe.', 'Experience the epic Emerald Dragon on the Super Famicom.', 'Originally a PC hit, this 16-bit port features a unique tactical combat system where character positioning is key. A beautiful and emotional Japanese RPG.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Emerald Dragon (Japan) [En by TransCorp v1.1]', '1995', NaN, 'Glodia', '1', NaN, 'Turn-based JRPG with a focus on dragon lore and cinematic story.', 'Experience the epic Emerald Dragon story with English text.', 'Play Emerald Dragon in English on the Super Nintendo.', 'The TransCorp translation allows Western fans to enjoy this high-quality JRPG. Experience the deep character development and innovative 16-bit tactical battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Emit Vol. 1 - Toki no Maigo (Japan)', '1994', NaN, 'Koei', '1', NaN, 'Interactive visual novel and language-learning adventure.', 'Solve the mystery of the Lost in Time girl through dialogue.', 'Experience the unique Emit Vol. 1 on the Super Famicom.', 'Part of a series designed to help Japanese players learn English. Features high-quality voice acting (via CD or cart) and a charming 16-bit anime art style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Emit Vol. 2 - Inochigake no Tabi (Japan)', '1994', NaN, 'Koei', '1', NaN, 'Interactive visual novel and language-learning adventure.', 'Navigate the Life-Threatening Journey to uncover the truth.', 'Explore the story in Emit Vol. 2 for the Super Famicom.', 'The second chapter of the adventure. It continues the educational and narrative focus, using 16-bit visuals to tell a compelling sci-fi mystery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Emit Vol. 3 - Watashi ni Sayonara o (Japan)', '1995', NaN, 'Koei', '1', NaN, 'Interactive visual novel and language-learning adventure.', 'Reach the emotional conclusion of the Emit trilogy.', 'Experience the finale in Emit Vol. 3 for the SNES.', 'The final installment of the series. Players must use their deduction skills and linguistic knowledge to solve the final 16-bit temporal puzzle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Emmitt Smith Football (USA)', '1995', NaN, 'Imagineering', '2', NaN, 'American football simulation featuring the legendary Emmitt Smith.', 'Lead your team to the championship using pro playbooks.', 'Hit the gridiron in Emmitt Smith Football for the SNES.', 'Features a Play Editor that allows for deep tactical customization. A solid 16-bit football sim with the endorsement of the Dallas Cowboys star.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Energy Breaker (Japan)', '1994', NaN, 'Taito', '1', NaN, 'Tactical turn-based RPG with isometric perspective and deep story.', 'Solve the mystery of the Energy and stop a looming war.', 'Master the tactical Energy Breaker on the Super Famicom.', 'A late-gen masterpiece. Features beautiful character designs and a grid-based combat system that requires careful planning. One of the most polished 16-bit JRPGs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Epic Tio Kart', '1995', NaN, 'Nakajima Satoru', '4', NaN, 'Mascot-style kart racer featuring the Tio character.', 'Win the tournament by using power-ups and mastering the tracks.', 'Race with friends in the fan-made Epic Tio Kart on SNES.', 'A creative fan-made racing mod using the Super Mario Kart engine. Features new tracks, items, and 16-bit sprites for a fresh racing experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Equinox (Europe)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Isometric action-puzzle game with a dark fantasy setting.', 'Navigate through four elemental castles to rescue the princess.', 'Enter the challenging world of Equinox on the Super Nintendo.', 'The sequel to Solstice. Explore complex 3D-style rooms, solve environmental puzzles, and defeat massive 16-bit bosses in this atmospheric adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Equinox (USA)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Isometric action-puzzle game with a dark fantasy setting.', 'Navigate through four elemental castles to rescue the princess.', 'Enter the challenging world of Equinox on the Super Nintendo.', 'The sequel to Solstice. Explore complex 3D-style rooms, solve environmental puzzles, and defeat massive 16-bit bosses in this atmospheric and difficult adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Equinox (USA) (Beta)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Isometric action-puzzle game with a dark fantasy setting.', 'Navigate through four elemental castles to rescue the princess.', 'Explore the Equinox Beta version on the Super Nintendo.', 'A pre-release build of the isometric classic. Discover early room layouts and subtle changes in the physics engine of this challenging 16-bit puzzle-adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Eric Cantona Football Challenge (Europe) (En,Fr,De,Es,It,Nl,Sv)', '1994', NaN, 'Gremlin Interactive', '2', NaN, 'Arcade-style soccer simulation endorsed by the legendary Eric Cantona.', 'Win the international cup through aggressive and tactical football.', 'Hit the pitch in Eric Cantona Football Challenge on SNES.', 'Known as World Cup Striker in other regions. Features fast-paced 16-bit action, multiple weather conditions, and the ability to execute spectacular special shots.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Esparks - Ijikuu Kara no Raihousha (Japan)', '1994', NaN, 'NCS', '1', NaN, 'Action-RPG with a unique sci-fi and fantasy crossover theme.', 'Travel through time and space to defeat an interdimensional threat.', 'Experience the epic Esparks on the Super Famicom.', 'A Japanese exclusive featuring vibrant 16-bit graphics and a real-time combat system. Manage your party''s abilities to solve puzzles and defeat massive celestial bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'ESPN Baseball Tonight (Europe)', '1994', NaN, 'Sculptured Software', '2', NaN, 'Realistic baseball simulation with full ESPN branding and presentation.', 'Win the World Series by mastering pitching and batting timing.', 'Step up to the plate in ESPN Baseball Tonight on the SNES.', 'Features digitized video sequences and commentary-style presentation. Manage your roster and play through a full 16-bit season with authentic stadium layouts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'ESPN Baseball Tonight (USA)', '1994', NaN, 'Sculptured Software', '2', NaN, 'Realistic baseball simulation with full ESPN branding and presentation.', 'Win the World Series by mastering pitching and batting timing.', 'Step up to the plate in ESPN Baseball Tonight on the SNES.', 'Utilizes the ESPN license to provide a TV-broadcast feel. Master the 16-bit mechanics of the diamond in this detailed and licensed sports simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'ESPN Baseball Tonight (USA) (Beta)', '1994', NaN, 'Sculptured Software', '2', NaN, 'Realistic baseball simulation with full ESPN branding and presentation.', 'Win the World Series by mastering pitching and batting timing.', 'Check out the ESPN Baseball Tonight Beta on SNES.', 'An early development build featuring unfinished assets and testing mechanics for the 16-bit baseball simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'ESPN National Hockey Night (USA)', '1994', NaN, 'Sculptured Software', '2', NaN, 'High-energy ice hockey simulation with ESPN-style broadcast.', 'Win the Stanley Cup by outplaying rival NHL teams.', 'Hit the ice in ESPN National Hockey Night for the SNES.', 'Features multiple camera angles and smooth 16-bit skating physics. Use the playmaker system to execute advanced strategies and score the winning goal.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'ESPN Speedworld (USA)', '1994', NaN, 'Sculptured Software', '2', NaN, 'Stock car racing simulation featuring official ESPN licensing.', 'Win the championship by mastering high-speed oval tracks.', 'Experience the speed of ESPN Speedworld on the Super Nintendo.', 'Manage your fuel, tire wear, and pit stops. A detailed 16-bit racing sim that focuses on the strategy and endurance of professional stock car racing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'ESPN Speedworld (USA) (Beta)', '1994', NaN, 'Sculptured Software', '2', NaN, 'Stock car racing simulation featuring official ESPN licensing.', 'Win the championship by mastering high-speed oval tracks.', 'Explore the ESPN Speedworld Beta version for the SNES.', 'A pre-release version of the racing sim, showing early car physics and track designs for the 16-bit ESPN-licensed experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'ESPN Sunday Night NFL (USA)', '1994', NaN, 'Sculptured Software', '2', NaN, 'American football simulation focusing on the Sunday night broadcast experience.', 'Lead your team to the Super Bowl through tactical play-calling.', 'Play the gridiron classic ESPN Sunday Night NFL on SNES.', 'Features Bill Berman''s commentary style and detailed playbooks. A solid 16-bit football experience with a focus on realism and authentic ESPN branding.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Estpolis Denki (Japan)', '1993', NaN, 'Neverland', '1', NaN, 'Traditional turn-based JRPG with a focus on cinematic storytelling.', 'Stop the Four Sinistrals from destroying the world.', 'Experience the legendary Estpolis Denki (Lufia) on SNES.', 'The original Japanese release of Lufia & The Fortress of Doom. Features a classic 16-bit quest with an emotional narrative and a strategic turn-based combat system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Estpolis Denki II (Japan)', '1995', NaN, 'Neverland', '1', NaN, 'Epic turn-based JRPG featuring the legendary Ancient Cave roguelike mode.', 'Uncover the origin of the Sinistrals in this prequel.', 'Play the masterpiece Estpolis Denki II (Lufia II) on SNES.', 'Widely regarded as one of the best 16-bit RPGs. Features complex puzzles, monster taming, and one of the most emotional stories on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Eurit (USA) (Proto)', '1992', NaN, 'Psygnosis', '1', NaN, 'Abstract action-puzzle game (Unreleased Prototype).', 'Navigate through surreal environments to find the exit.', 'Discover the unreleased prototype Eurit on the SNES.', 'A rare look at a cancelled project. Features experimental 16-bit graphics and unique gameplay mechanics that focused on environmental interaction and logic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Euro Football Champ (Europe)', '1992', NaN, 'Dinamic Software', '2', NaN, 'Arcade-style soccer simulation with a humorous and fast-paced tone.', 'Win the world championship by outscoring every rival nation.', 'Kick off the fun in Euro Football Champ for the SNES.', 'Features large, expressive sprites and exaggerated special moves. A fast and accessible 16-bit football game that focuses on pure arcade excitement.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Europe Sensen (Japan)', '1994', NaN, 'Kemco', '1', NaN, 'Grand-scale WWII tactical strategy simulation set in Europe.', 'Lead the Axis or Allied forces to victory in the European theater.', 'Master the battlefield in Europe Sensen for the Super Famicom.', 'Known as Operation Europe in the West. A deep Koei strategy game focusing on troop management, logistics, and 16-bit tactical planning.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Exertainment Life Fitness Mega Cart (Europe) (Proto)', '1994', NaN, 'LG / Nintendo', '1', NaN, 'Specialized software designed for use with Life Fitness exercise equipment.', 'Engage in virtual workouts while using a compatible exercise bike.', 'Discover the rare Exertainment Mega Cart prototype on SNES.', 'A unique piece of 16-bit history. It allowed users to track their fitness progress and participate in mini-games while exercising on physical gym equipment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Exhaust Heat (Europe)', '1992', NaN, 'Seta', '2', NaN, 'Realistic Formula 1 racing simulation using Mode 7 for 3D effects.', 'Win the F1 world championship by mastering every international circuit.', 'Race at high speeds in Exhaust Heat for the Super Nintendo.', 'Known as F1 ROC: Race of Champions. Features car tuning and realistic handling. Experience the intensity of 16-bit open-wheel racing on global tracks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Exhaust Heat (Japan)', '1992', NaN, 'Seta', '2', NaN, 'Realistic Formula 1 racing simulation using Mode 7 for 3D effects.', 'Win the F1 world championship by mastering every international circuit.', 'Race at high speeds in Exhaust Heat for the Super Nintendo.', 'The Japanese original. Buy parts and upgrade your car as you progress through the season. A technical 16-bit racer that prioritizes simulation over arcade action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Exhaust Heat II - F1 Driver e no Kiseki (Japan)', '1993', NaN, 'Seta', '1', NaN, 'Enhanced F1 simulation featuring improved graphics and career mode.', 'Build a legendary career and become the world''s best F1 driver.', 'Experience the evolution in Exhaust Heat II for the SNES.', 'Known as F1 ROC II. Adds a more detailed career path and refined car physics, offering the ultimate 16-bit Formula 1 experience for hardcore fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Extra Innings (USA)', '1991', NaN, 'Sony Imagesoft', '2', NaN, 'Lighthearted baseball simulation with an emphasis on arcade fun.', 'Win the baseball league by mastering unique character stats.', 'Play the charming Extra Innings for the Super Nintendo.', 'Features a chibi art style and fast-paced gameplay. A fun and accessible 16-bit take on baseball that doesn''t sacrifice depth for its cute visuals.', NULL);
