INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'FIFA ''97 - Gold Edition (USA) (En,Fr,De,Es,It,Sv)', '1996', NaN, 'Electronic Arts', '2', NaN, 'Soccer simulation featuring updated rosters and the Gold Edition polish.', 'Win the international league and reach the top of the FIFA rankings.', 'Kick off with FIFA ''97 Gold Edition on the Super Nintendo.', 'Manage your team and play through a full 16-bit season. Includes various camera angles and digitized sound effects for a realistic match day feel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'FIFA ''98 - Road to World Cup (Europe) (En,Fr,De,Es,It,Sv)', '1997', NaN, 'Electronic Arts', '2', NaN, 'The final FIFA entry on the system, focusing on the World Cup journey.', 'Qualify for and win the 1998 World Cup with your favorite nation.', 'Road to World Cup fun in FIFA ''98 for the SNES.', 'A farewell to the 16-bit era. Features a massive selection of national teams and the classic isometric gameplay that defined the early series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'FIFA International Soccer (Europe)', '1994', NaN, 'Electronic Arts', '2', NaN, 'The game that started it all, featuring an isometric view and crowd chants.', 'Lead your team to the world championship for the first time.', 'Play the original FIFA International Soccer on SNES.', 'A landmark sports title. Features the famous running away from the referee glitch and smooth 16-bit animations that set a new standard for soccer games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'FIFA International Soccer (Japan)', '1994', NaN, 'Electronic Arts', '2', NaN, 'The game that started it all, featuring an isometric view and crowd chants.', 'Lead your team to the world championship for the first time.', 'Experience the Japanese version of FIFA International Soccer.', 'The Super Famicom release of the global hit. Features the same deep 16-bit tactical options and addictive multiplayer that made it a household name.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'FIFA International Soccer (USA)', '1994', NaN, 'Electronic Arts', '2', NaN, 'The game that started it all, featuring an isometric view and crowd chants.', 'Lead your team to the world championship for the first time.', 'Play the original FIFA International Soccer on SNES.', 'Master the corner kicks and bicycle shots. A must-play 16-bit sports classic that captured the excitement of the 1994 World Cup era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'FIFA Soccer ''96 (Europe) (En,Fr,De,Es,It,Sv)', '1996', NaN, 'Electronic Arts', '2', NaN, 'Soccer simulation with real player names and improved physics.', 'Dominate the pitch and win the league in the 1996 edition.', 'Experience the pro action in FIFA Soccer ''96 for SNES.', 'The first entry to feature real players thanks to the FIFPro license. Enjoy more fluid 16-bit passing and a wide array of team management options.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'FIFA Soccer ''96 (USA) (En,Fr,De,Es,It,Sv)', '1996', NaN, 'Electronic Arts', '2', NaN, 'Soccer simulation with real player names and improved physics.', 'Dominate the pitch and win the league in the 1996 edition.', 'Experience the pro action in FIFA Soccer ''96 for SNES.', 'Take your favorite club to the top. This 16-bit version offers a deeper simulation experience with realistic player stats and diverse weather conditions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Fighter''s History - Mizoguchi Kikiippatsu!! (Japan)', '1995', NaN, 'Data East', '2', NaN, 'One-on-one fighting game featuring the legendary Mizoguchi.', 'Win the tournament and prove your martial arts supremacy.', 'Fight for glory in Fighter''s History: Mizoguchi Kikiippatsu!!', 'A Japanese exclusive update. Features faster combat and new special moves in a colorful 16-bit environment that pays tribute to arcade classics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Fighter''s History (Japan)', '1994', NaN, 'Data East', '2', NaN, 'One-on-one fighting game featuring a unique weak point system.', 'Defeat the mysterious Karnov and his elite fighters.', 'Master the system in Fighter''s History for the SNES.', 'A cult classic fighter. Exploit your opponent''s 16-bit weak points to stun them and unleash devastating special moves in this technical arcade port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Fighter''s History (USA) (Beta)', '1994', NaN, 'Data East', '2', NaN, 'One-on-one fighting game featuring a unique weak point system.', 'Defeat the mysterious Karnov and his elite fighters.', 'Check out the Fighter''s History Beta on the SNES.', 'A pre-release version of the game. Explore the 16-bit fighter''s early character balancing and sprite animations before its final retail launch.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Fighter''s History (USA) (Rev A)', '1994', NaN, 'Data East', '2', NaN, 'One-on-one fighting game featuring a unique weak point system.', 'Defeat the mysterious Karnov and his elite fighters.', 'Play the polished Fighter''s History (Rev A) on the SNES.', 'The updated 16-bit revision with minor bug fixes and refined move sets, offering the most stable tournament experience on the Super Nintendo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Fighting Baseball (Japan)', '1994', NaN, 'Namco', '2', NaN, 'Baseball simulation famous for its American player names.', 'Win the baseball league by mastering the diamond.', 'Play the hilarious Fighting Baseball on the Super Famicom.', 'Beyond the famous memes of its fictional players, it''s a solid 16-bit baseball game with smooth controls and a fun arcade feel for sports fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy - Mystic Quest (USA)', '1992', NaN, 'Square', '1', NaN, 'Entry-level JRPG with a focus on action-adventure and simple mechanics.', 'Restore the four crystals to save the world from total destruction.', 'Begin your journey in Final Fantasy: Mystic Quest on SNES.', 'Designed for newcomers to the genre. Features visible enemies on the map and a mix of platforming and turn-based 16-bit combat. A lighthearted and melodic RPG experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy - Mystic Quest (USA) (Rev A)', '1992', NaN, 'Square', '1', NaN, 'Entry-level JRPG with a focus on action-adventure and simple mechanics.', 'Restore the four crystals to save the world from total destruction.', 'Play the polished Rev A of Final Fantasy: Mystic Quest.', 'The updated 16-bit version featuring minor bug fixes and text corrections, ensuring a smooth entry into the world of Final Fantasy for western players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy II (USA)', '1991', NaN, 'Square', '1', NaN, 'Epic turn-based RPG featuring the Active Time Battle system.', 'Lead Cecil the Dark Knight on a quest of redemption and bravery.', 'Experience the legendary Final Fantasy II on the SNES.', 'Actually the western release of FFIV. Follow an emotional story of love and betrayal with a classic 16-bit soundtrack and unforgettable characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy II (USA) (Rev 1) [Bug Fix by Deathlike2 v1.0a] (Yang''s HP Fix)', '1991', NaN, 'Square', '1', NaN, 'Epic turn-based JRPG with a specific technical fix for character stats.', 'Experience the classic story with Yang''s health bug fully fixed.', 'Play the fixed Final Fantasy II (Yang''s HP Fix) on SNES.', 'A technical patch that resolves a notorious glitch where Yang''s HP wouldn''t grow correctly, ensuring a balanced 16-bit party for the endgame.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy II (USA) (Rev 1) [Hack by Dragonsbrethren v1.0] (~Final Fantasy II is Easy Type)', '1991', NaN, 'Square', '1', NaN, 'Epic turn-based JRPG modified to match the easier Japanese edition.', 'Enjoy the story of Cecil with reduced difficulty and simplified items.', 'Experience the Easy Type mod for Final Fantasy II on SNES.', 'This hack restores the Easy Type balance from Japan, making the 16-bit journey more accessible while retaining the epic narrative.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy II (USA) (Rev 1) [Hack by JCE3000GT v1.2] (Hard Type)', '1991', NaN, 'Square', '1', NaN, 'Epic turn-based JRPG with significantly increased difficulty.', 'Survive the most brutal version of Cecil''s journey.', 'Challenge yourself with Final Fantasy II Hard Type on SNES.', 'Designed for veterans. This mod increases enemy stats and AI complexity, forcing players to master 16-bit strategy to survive even basic encounters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy II (USA) (Rev A)', '1991', NaN, 'Square', '1', NaN, 'Epic turn-based JRPG featuring the Active Time Battle system.', 'Lead Cecil the Dark Knight on a quest of redemption and bravery.', 'Play the refined Rev A version of Final Fantasy II on SNES.', 'The final official 16-bit revision for the US market, fixing several minor script errors and rare crashing bugs found in the original release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy II (USA) [Bug Fix by Deathlike2 v1.0a] (Yang''s HP Fix)', '1991', NaN, 'Square', '1', NaN, 'Epic turn-based JRPG with a specific technical fix for character stats.', 'Experience the classic story with Yang''s health bug fully fixed.', 'Play the fixed Final Fantasy II (Yang''s HP Fix) on SNES.', 'A bug-fix mod for the initial US release. It ensures Yang remains a viable 16-bit powerhouse by fixing his hit point calculation errors.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy II (USA) [Hack by JCE3000GT v1.2] (Hard Type)', '1991', NaN, 'Square', '1', NaN, 'Epic turn-based JRPG with significantly increased difficulty.', 'Survive the most brutal version of Cecil''s journey.', 'Challenge yourself with Final Fantasy II Hard Type on SNES.', 'A re-balanced version for the first US release. It removes the hand-holding of the original western localization for a true 16-bit challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA)', '1994', NaN, 'Square', '1', NaN, 'Masterpiece JRPG featuring 14 playable characters and a deep story.', 'Stop the mad jester Kefka from destroying the world of magic.', 'Experience the monumental Final Fantasy III on the SNES.', 'Actually the western release of FFVI. A cinematic 16-bit achievement with a complex plot, an opera scene, and an incredible score by Nobuo Uematsu.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA) (Rev 1) [Hack by JCE3000GT v1.2] (Hard Type)', '1994', NaN, 'Square', '1', NaN, 'Masterpiece JRPG with a focus on extreme tactical challenge.', 'Overcome the hardest bosses in 16-bit history.', 'Play Final Fantasy III Hard Type by JCE3000GT on SNES.', 'Reworks enemy encounters and character growth. This hack demands a deep understanding of the 16-bit Esper system and equipment synergy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA) (Rev 1) [Hack by SageAcrin v1.06] (Evil Type)', '1994', NaN, 'Square', '1', NaN, 'Masterpiece JRPG with a focus on un-fair and brutal combat.', 'Defeat Kefka in his most powerful and aggressive form.', 'Survive the brutal Final Fantasy III Evil Type on SNES.', 'Notorious for its difficulty. Enemies use devastating spells earlier and more frequently, creating a punishing 16-bit experience for hardcore fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA) (Rev 1) [Hack by Zeemis v1.0] (~Final Fantasy - Revelations)', '1994', NaN, 'Square', '1', NaN, 'Total conversion hack that reimagines the story and script.', 'Explore a New Reality with updated dialogue and lore.', 'Discover Final Fantasy: Revelations on the Super Nintendo.', 'A creative script overhaul that attempts to bridge gaps in the 16-bit lore and provide a fresh perspective on the classic War of the Magi.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA) (Rev A)', '1994', NaN, 'Square', '1', NaN, 'Masterpiece JRPG featuring 14 playable characters and a deep story.', 'Stop the mad jester Kefka from destroying the world of magic.', 'Play the polished Rev A of Final Fantasy III on SNES.', 'The updated US release that fixes the famous Sketch Glitch and other minor bugs that could corrupt 16-bit save files.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA) [Hack by JCE3000GT v1.2] (Hard Type)', '1994', NaN, 'Square', '1', NaN, 'Masterpiece JRPG with a focus on extreme tactical challenge.', 'Overcome the hardest bosses in 16-bit history.', 'Play Final Fantasy III Hard Type by JCE3000GT on SNES.', 'A re-balanced version for the first US release, focusing on providing a consistent and fair 16-bit challenge for RPG experts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA) [Hack by MakouEyes v9.08] (~Final Fantasy VI - The Eternal Crystals)', '1994', NaN, 'Square', '1', NaN, 'Massive expansion hack with new content, items, and dungeons.', 'Restore the Eternal Crystals in this expanded 16-bit adventure.', 'Play FFVI: The Eternal Crystals expansion on the SNES.', 'Features new bosses, restored Japanese content, and a revamped magic system. A massive love letter to the 16-bit original with hours of new gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA) [Hack by SageAcrin v1.06] (Evil Type)', '1994', NaN, 'Square', '1', NaN, 'Masterpiece JRPG with a focus on un-fair and brutal combat.', 'Defeat Kefka in his most powerful and aggressive form.', 'Survive the brutal Final Fantasy III Evil Type on SNES.', 'The initial version of the Evil mod, focusing on aggressive enemy AI and punishing 16-bit status effect combinations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA) [Hack by Tzepish v1.2] (~Final Fantasy IV - Enhanced Editon)', '1994', NaN, 'Square', '1', NaN, 'Crossover mod that brings elements of FFIV into the FFVI engine.', 'Experience the story of Cecil with the advanced mechanics of FFVI.', 'Play Final Fantasy IV: Enhanced Edition on the SNES.', 'A unique technical feat that ports the FFIV story into the superior 16-bit engine of FFVI, offering better menus and smoother combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy III (USA) [Hack by Zeemis v1.0] (~Final Fantasy - Revelations)', '1994', NaN, 'Square', '1', NaN, 'Total conversion hack that reimagines the story and script.', 'Explore a New Reality with updated dialogue and lore.', 'Discover Final Fantasy: Revelations on the Super Nintendo.', 'Focuses on a more mature and direct translation style, aiming to provide a director''s cut feel to the 16-bit masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy IV - Easy Type (Japan)', '1991', NaN, 'Square', '1', NaN, 'Simplified version of FFIV designed for younger audiences.', 'Follow Cecil''s journey with easier battles and unique items.', 'Play the rare Final Fantasy IV Easy Type on SNES.', 'A Japanese exclusive that removes many complex status effects and ability commands, offering a breezy 16-bit adventure through the world of Baron.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy IV (Japan)', '1991', NaN, 'Square', '1', NaN, 'The foundational JRPG that introduced the Active Time Battle.', 'Save the world from the Red Wings in the original FFIV.', 'Experience the original Final Fantasy IV (Japan) on SNES.', 'The unfiltered Japanese classic. Features a higher difficulty and more complex mechanics than the initial 16-bit western release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy IV (Japan) (Rev 1) [En by J2e v3.21]', '1991', NaN, 'Square', '1', NaN, 'The foundational JRPG with a faithful fan translation.', 'Experience the original story of Cecil with a modern script.', 'Play Final Fantasy IV in English (J2e) on the SNES.', 'One of the first major fan translations. It restores the 16-bit dialogue and darker story elements that were censored in the official US release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy IV (Japan) (Rev 1) [En by J2e v3.21] [Bug Fix by Deathlike2 v1.0a] (Yang''s HP Fix)', '1991', NaN, 'Square', '1', NaN, 'The foundational JRPG with a faithful fan translation and bug fixes.', 'Play the translated classic with Yang''s stats fully repaired.', 'Play the fixed FFIV J2e translation on the SNES.', 'Combines the famous J2e English script with essential technical patches for a perfect and stable 16-bit RPG experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy IV (Japan) (Rev A)', '1991', NaN, 'Square', '1', NaN, 'The foundational JRPG that introduced the Active Time Battle.', 'Save the world from the Red Wings in the original FFIV.', 'Play the polished Rev A of Final Fantasy IV on SNES.', 'The updated Japanese revision, including minor graphical fixes and stability improvements for the late-game 16-bit lunar dungeons.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy USA - Mystic Quest (Japan)', '1992', NaN, 'Square', '1', NaN, 'Entry-level JRPG with a focus on action-adventure (Japanese version).', 'Restore the four crystals to save the world.', 'Play the Japanese version of Final Fantasy USA on SNES.', 'Interestingly, this is the Japanese release of the American-made game. It features the same 16-bit action-RPG gameplay with translated text.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy V (Japan)', '1992', NaN, 'Square', '1', NaN, 'Deep JRPG featuring the legendary Job System for party customization.', 'Stop the warlock Exdeath from returning the world to the Void.', 'Master the jobs in Final Fantasy V for the Super Famicom.', 'A masterpiece of customization. Mix and match 22 different 16-bit jobs to create the ultimate party in one of the series'' most strategic entries.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1]', '1992', NaN, 'Square', '1', NaN, 'Deep JRPG featuring the legendary Job System with English text.', 'Experience the journey of Butz and friends in English.', 'Play the classic Final Fantasy V translation by RPGe.', 'The legendary fan translation that first brought FFV to the West. Experience the complete 16-bit story and deep job system in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1] [Hack by JCE3000GT v0.947] (Expert Mode)', '1992', NaN, 'Square', '1', NaN, 'Deep JRPG modified for a much higher tactical challenge.', 'Conquer the Void in this brutal Expert Mode for FFV.', 'Challenge the Final Fantasy V Expert Mode on SNES.', 'Specifically designed for those who have mastered the job system. Features 16-bit bosses with new patterns and significantly higher stats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1] [Hack by JCE3000GT v1.0] (Easy Type)', '1992', NaN, 'Square', '1', NaN, 'Deep JRPG modified to be more accessible for new players.', 'Enjoy the job system without the punishing difficulty spikes.', 'Play Final Fantasy V Easy Type in English on SNES.', 'A re-balanced version of the RPGe translation, making the 16-bit grind less intense and the boss fights more forgiving.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1] [Hack by Jorgur v0.50] (~Final Fantasy V Plus)', '1992', NaN, 'Square', '1', NaN, 'Expansion mod that adds quality-of-life features and new secrets.', 'Experience an enhanced version of the classic job system.', 'Play Final Fantasy V Plus on the Super Nintendo.', 'Includes bug fixes, Dash by default, and hidden items. A polished way to experience the 16-bit classic with modern sensibilities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1] [Text Hack by Tzepish v1.01] (~Final Fantasy V Spoof)', '1992', NaN, 'Square', '1', NaN, 'Humorous and satirical re-write of the original game''s script.', 'Save the world in this bizarre and funny parody version of FFV.', 'Laugh with the Final Fantasy V Spoof on the SNES.', 'A joke translation that replaces the epic 16-bit dialogue with 90s internet humor and pop culture references. Pure nostalgic chaos.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy V Tweaks', '1992', NaN, 'Square', '1', NaN, 'Collection of quality-of-life improvements for the original game.', 'Enjoy the definitive way to play FFV with modern fixes.', 'Experience the Final Fantasy V Tweaks mod on SNES.', 'Includes auto-dash, balanced job growth, and color correction. A must-have for players seeking the most comfortable 16-bit FFV experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy VI (Japan)', '1994', NaN, 'Square', '1', NaN, 'The peak of 16-bit JRPGs, featuring a massive cast and steampunk world.', 'Experience the original Japanese masterpiece of FFVI.', 'Play the legendary Final Fantasy VI on the Super Famicom.', 'The unfiltered version of the game that defined the SNES era. Experience the full 16-bit cinematic vision of the War of the Magi.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy VI (Japan) [En by RPGOne v1.2b]', '1994', NaN, 'Square', '1', NaN, 'The peak of 16-bit JRPGs with a faithful, modern translation.', 'Experience the most accurate English script for FFVI.', 'Play Final Fantasy VI English (RPGOne) on the SNES.', 'A highly respected translation that restores character names and nuances lost in the 16-bit era''s official localization.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy VI (Japan) [En by RPGOne v1.2b] [All Bug Fixes]', '1994', NaN, 'Square', '1', NaN, 'The peak of 16-bit JRPGs with a faithful translation and all fixes.', 'Play the most stable and accurate version of FFVI.', 'Experience the definitive FFVI RPGOne (All Fixes) on SNES.', 'The ultimate version. Combines the RPGOne script with patches for every known 16-bit bug, including the Sketch and Evade glitches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fantasy VI Expanded', '1994', NaN, 'Square', '1', NaN, 'A massive content mod that adds new areas and challenges to FFVI.', 'Discover new secrets in the World of Ruin.', 'Explore the Final Fantasy VI Expanded mod on SNES.', 'Adds new Espers, redesigned dungeons, and restored content. It breathes new life into the 16-bit world, offering surprises for long-time fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fight (Europe)', '1991', NaN, 'Capcom', '2', NaN, 'Iconic side-scrolling beat ''em up featuring Mike Haggar and Cody.', 'Rescue Jessica and clean up Metro City from the Mad Gear Gang.', 'Experience the arcade hit Final Fight on the SNES.', 'The game that defined the 16-bit brawler. Choose between the powerful Haggar or the agile Cody to fight through diverse urban environments and iconic bosses.', NULL);
