INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fight (USA)', '1990', NaN, 'Capcom', '2', NaN, 'Iconic side-scrolling beat ''em up featuring Mike Haggar and Cody.', 'Rescue Jessica and clean up Metro City from the Mad Gear Gang.', 'Battle the Mad Gear Gang in Final Fight for the SNES.', 'Master the art of the pile-driver and the flying kick. A foundation of the 16-bit era, known for its intense action and memorable soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fight 2 (Europe)', '1993', NaN, 'Capcom', '2', NaN, 'Beat ''em up sequel featuring three playable characters and a global setting.', 'Travel the world to rescue Guy''s master and fiancée from Retu.', 'Join the global battle in Final Fight 2 on the SNES.', 'Introduces Maki and Carlos alongside Haggar. Features 2-player co-op mode, taking the 16-bit fight to France, Italy, and Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fight 2 (Japan)', '1993', NaN, 'Capcom', '2', NaN, 'Beat ''em up sequel featuring three playable characters and a global setting.', 'Travel the world to rescue Guy''s master and fiancée from Retu.', 'Experience the original Japanese Final Fight 2 on SNES.', 'Enjoy the balanced 16-bit combat and improved character variety. Master each fighter''s unique special moves to dismantle the neo-Mad Gear threat.', NULL);
