INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fight 3 (USA)', '1995', NaN, 'Capcom', '2', NaN, 'Advanced beat ''em up featuring a branching path system and four heroes.', 'Clean up the streets of Metro City from the rising Skull Cross Gang.', 'Experience the intense action of Final Fight 3 on SNES.', 'Utilize the AI partner mode or 2-player co-op. Explore branching 16-bit levels that change based on your choices and performance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fight 3 (USA) (Beta)', '1995', NaN, 'Capcom', '2', NaN, 'Advanced beat ''em up featuring a branching path system and four heroes.', 'Clean up the streets of Metro City from the rising Skull Cross Gang.', 'Explore the Final Fight 3 Beta version on the SNES.', 'A pre-release build showing early combat balancing and environmental assets. A unique look at the development of this 16-bit action masterpiece.', NULL);
