INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Final Fight Guy (USA)', '1992', NaN, 'Capcom', '2', NaN, 'Special edition of the first game where Cody is replaced by Guy.', 'Rescue Jessica from the Mad Gear Gang using Guy''s ninja techniques.', 'Play as the legendary ninja in Final Fight Guy on SNES.', 'Experience the US release of this limited edition. Master Guy''s speed and unique combos to take down the 16-bit bosses of Metro City.', NULL);
