INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Fire Emblem - Monshou no Nazo (Japan) [En by RPGuy96 v0.98] (~Fire Emblem - Mystery of the Emblem)', '1994', NaN, 'Nintendo', '1', NaN, 'Strategic turn-based RPG and remake of the first Famicom title.', 'Follow Marth''s legendary journey with a full English translation.', 'Play Fire Emblem: Mystery of the Emblem in English on SNES.', 'The RPGuy96 translation allows Western fans to fully enjoy the intricate 16-bit political plot and permadeath strategy of Marth''s saga.', NULL);
