INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Gakkou de Atta Kowai Hanashi (Japan)', '1995', NaN, 'Banpresto', '1', NaN, 'Horror-themed visual novel set in a haunted high school.', 'Listen to seven scary stories and survive the night.', 'Experience the terror of Gakkou de Atta Kowai Hanashi on SNES.', 'A masterpiece of 16-bit psychological horror. Use the branching dialogue system to uncover different endings in this atmospheric and chilling Japanese classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Galaxy Robo (Japan)', '1995', NaN, 'Namco', '2', NaN, 'Turn-based tactical strategy game featuring giant mechs.', 'Engage in intergalactic warfare and defeat the enemy robot army.', 'Master the mechs in Galaxy Robo for the Super Famicom.', 'Features detailed mecha designs and hex-based strategy. Command your fleet through deep space in this technically impressive 16-bit tactical simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Galaxy Wars (Japan)', '1993', NaN, 'Imagineer', '2', NaN, 'Fixed-screen shooter based on the classic arcade hit.', 'Defend your ship from waves of incoming space invaders.', 'Blast aliens in Galaxy Wars for the Super Famicom.', 'A modern 16-bit take on the arcade classic. Features updated graphics and faster gameplay while retaining the addictive shoot-and-dodge mechanics of the original.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Gambler Jikochuushinha - Mahjong Kouisen (Japan)', '1992', NaN, 'Nichibutsu', '1', NaN, 'Competitive Mahjong simulation based on a popular manga.', 'Win the tournament by outsmarting eccentric Mahjong masters.', 'Play the tactical Gambler Jikochuushinha on the SNES.', 'A polished 16-bit Mahjong title featuring humorous character interactions and a deep career mode for fans of the traditional Japanese tile game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Gambler Jikochuushinha 2 - Dorapon Quest (Japan)', '1994', NaN, 'Nichibutsu', '1', NaN, 'Mahjong simulation with a unique RPG-style quest mode.', 'Navigate a fantasy board and defeat enemies through Mahjong.', 'Experience the quest in Gambler Jikochuushinha 2 on SNES.', 'A creative blend of 16-bit RPG exploration and Mahjong matches. Use special items to tip the scales in your favor during the high-stakes Dorapon quest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Gambling Hourouki (Japan)', '1993', NaN, 'Nichibutsu', '1', NaN, 'Authentic gambling simulation featuring various Japanese parlor games.', 'Travel the country and win big at different gambling halls.', 'Test your luck in Gambling Hourouki for the Super Famicom.', 'Includes realistic Mahjong and board games. Features a story-driven wandering mode where you manage your 16-bit finances to become a gambling legend.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Game no Tatsujin (Japan)', '1991', NaN, 'Sunsoft', '1', NaN, 'Collection of classic board and card games with a professional polish.', 'Master a variety of traditional games against skilled AI.', 'Enjoy the variety of Game no Tatsujin on the SNES.', 'Includes high-quality versions of Shogi, Go, and Mahjong. A perfect 16-bit compilation for players seeking a refined and relaxing mental challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Game no Tetsujin - The Shanghai (Japan)', '1994', NaN, 'Sunsoft', '2', NaN, 'Polished Mahjong and puzzle compilation focusing on the Shanghai style.', 'Clear the boards of tiles using logic and speed.', 'Master the tiles in Game no Tetsujin: The Shanghai for SNES.', 'Features various tile-matching modes and competitive play. Offers a smooth 16-bit interface and high-fidelity tile designs for a premium puzzle experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Gamera - Gyaos Gekimetsu Sakusen (Japan)', '1995', NaN, 'Sammy', '1', NaN, 'Strategy-action hybrid based on the legendary kaiju Gamera.', 'Defend Japanese cities from the destructive Gyaos invasion.', 'Save Japan in Gamera: Gyaos Gekimetsu Sakusen on SNES.', 'Part tactical simulation, part monster battle. Manage defense forces and command the giant turtle Gamera in 16-bit combat against his aerial arch-nemesis.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganbare Goemon - Yuki Hime Kyuushutsu Emaki (Japan)', '1991', NaN, 'Konami', '2', NaN, 'Action-adventure hybrid with platforming and overhead exploration.', 'Rescue Princess Yuki from the ghost army in feudal Japan.', 'Join the adventure in Ganbare Goemon (The Legend of the Mystical Ninja).', 'A masterpiece of 16-bit charm. Explore vibrant towns, play mini-games, and master the pipe-wielding action in this quirky and colorful Japanese classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganbare Goemon - Yuki Hime Kyuushutsu Emaki (Japan) (Rev B)', '1991', NaN, 'Konami', '2', NaN, 'Action-adventure hybrid with platforming and overhead exploration.', 'Rescue Princess Yuki from the ghost army in feudal Japan.', 'Play the refined Rev B version of Ganbare Goemon on SNES.', 'The most stable 16-bit version of the first Goemon adventure, featuring bug fixes and smoother transitions between the overhead and side-scrolling stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganbare Goemon 2 - Kiteretsu Shougun Magginesu (Japan)', '1993', NaN, 'Konami', '2', NaN, 'Action-platformer sequel with a focus on humor and mecha combat.', 'Stop the evil Shogun and his army of clockwork soldiers.', 'Experience the hilarity of Ganbare Goemon 2 on the SNES.', 'Introduces the giant robot Impact! Enjoy 2-player co-op across 16-bit feudal Japan with improved graphics and even more eccentric mini-games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganbare Goemon 3 - Shishi Juuroku Hyoue no Karakuri Manjigatame (Japan)', '1994', NaN, 'Konami', '2', NaN, 'Action-adventure with an open-world Zelda-style progression.', 'Explore a futuristic Neo-Edo to rescue your friends.', 'Discover the massive world of Ganbare Goemon 3 on SNES.', 'A shift to a more exploratory structure. Switch between four characters with unique abilities to solve 16-bit puzzles and navigate a large, interconnected world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganbare Goemon Kirakira Douchuu - Boku ga Dancer ni Natta Riyuu (Japan)', '1995', NaN, 'Konami', '2', NaN, 'Intergalactic action-platformer featuring bizarre comedy.', 'Travel to distant planets to find the missing Dancer.', 'Blast off in Goemon Kirakira Douchuu for the Super Famicom.', 'Features some of the best 16-bit graphics on the system. Travel across multiple planets with unique themes in this high-energy and hilarious action epic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganbare Goemon Kirakira Douchuu - Boku ga Dancer ni Natta Riyuu (Japan) (Rev B) (NP)', '1995', NaN, 'Konami', '2', NaN, 'Intergalactic action-platformer featuring bizarre comedy.', 'Travel to distant planets in the refined Rev B revision.', 'Experience the polished Goemon Kirakira Douchuu on SNES.', 'The Nintendo Power revision fixing minor timing issues in the Impact battles. The definitive way to enjoy this 16-bit space-traveling comedy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganbare! Daiku no Gen-san (Japan)', '1991', NaN, 'Irem', '2', NaN, 'Action-platformer featuring the hammer-wielding Gen-san.', 'Stop the evil construction company from taking over the city.', 'Swing the hammer in Ganbare! Daiku no Gen-san on SNES.', 'Based on the arcade classic (Hammerin'' Harry). Features fast-paced 16-bit platforming and massive bosses that require precise timing and powerful hammer strikes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Gangan Gan-chan (Japan)', '1993', NaN, 'Namco', '2', NaN, 'Puzzle-action game where you guide a rolling ball through mazes.', 'Navigate through colorful obstacles to reach the goal.', 'Roll to victory in Gangan Gan-chan for the Super Famicom.', 'A cute and challenging 16-bit puzzler. Use environmental objects and special power-ups to clear paths through increasingly complex and vibrant mazes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganpuru - Gunman''s Proof (Japan)', '1997', NaN, 'Lenar', '1', NaN, 'Action-RPG with a Wild West theme and sci-fi elements.', 'Save the frontier town from alien outlaws and mysterious monsters.', 'Experience the unique Ganpuru: Gunman''s Proof on SNES.', 'A late-gen gem. Plays like The Legend of Zelda with guns. Features fluid 16-bit movement, humorous dialogue, and a world full of secrets to discover.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganpuru - Gunman''s Proof (Japan) [En by Aeon Genesis v1.03]', '1997', NaN, 'Lenar', '1', NaN, 'Action-RPG with a Wild West theme and sci-fi elements.', 'Experience the alien-frontier story with a full English translation.', 'Play Gunman''s Proof in English on the Super Nintendo.', 'The Aeon Genesis translation makes this 16-bit masterpiece accessible. Follow a boy possessed by an alien as he fights to save the West from intergalactic threats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganso Pachi-Slot Nihonichi (Japan)', '1995', NaN, 'Coconuts Japan', '1', NaN, 'Pachi-slot simulation featuring realistic slot machine mechanics.', 'Win the national slot tournament by mastering the reels.', 'Test your luck in Ganso Pachi-Slot Nihonichi on SNES.', 'A detailed 16-bit simulation of Japanese slot parlors. Manage your virtual budget and master the timing of various machines to become the number one player in Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ganso Pachinko Ou (Japan)', '1993', NaN, 'Coconuts Japan', '1', NaN, 'Authentic Pachinko simulation with multiple machine types.', 'Master the physics of the silver balls to hit the jackpot.', 'Play the classic Ganso Pachinko Ou on the Super Famicom.', 'Experience the sights and sounds of a 16-bit Pachinko parlor. Features realistic ball physics and a variety of themed machines to master for high-score payouts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Garou Densetsu - Shukumei no Tatakai (Japan)', '1991', NaN, 'SNK', '2', NaN, 'One-on-one fighting game that launched the legendary SNK series.', 'Defeat Geese Howard and avenge your father in the King of Fighters.', 'Experience the original Garou Densetsu (Fatal Fury) on SNES.', 'The 16-bit home version of the arcade hit. Introduces the unique two-plane system where fighters can jump between foreground and background to dodge attacks.', NULL);
