INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Garou Densetsu 2 - Aratanaru Tatakai (Japan)', '1992', NaN, 'SNK', '2', NaN, 'Fighting game sequel with a larger roster and faster combat.', 'Defeat the new threat, Wolfgang Krauser, across the globe.', 'Master the 16-bit battle in Garou Densetsu 2 on SNES.', 'Significant improvement over the first game. Introduces iconic characters like Mai Shiranui and Kim Kaphwan with fluid animations and devastating special moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Garou Densetsu 2 - Aratanaru Tatakai (Japan) (Rev A)', '1992', NaN, 'SNK', '2', NaN, 'Fighting game sequel with a larger roster and faster combat.', 'Defeat the new threat, Wolfgang Krauser, across the globe.', 'Play the refined Garou Densetsu 2 (Rev A) on SNES.', 'The updated 16-bit revision that balances character damage and fixes rare sprite glitches, offering the most stable tournament experience of the sequel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Garou Densetsu Special (Japan)', '1993', NaN, 'SNK', '2', NaN, 'The ultimate 16-bit update to the Fatal Fury series.', 'Win the Dream Match against a massive roster of SNK legends.', 'Experience the epic Garou Densetsu Special on SNES.', 'Features the return of classic characters and a much faster gameplay speed. Master the 16-bit combos and hidden desperation moves in this fighter.', NULL);
