INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Gdleen (Japan) (Rev A)', '1994', NaN, 'ASCII', '1', NaN, 'Traditional turn-based JRPG set in a sci-fi and fantasy world.', 'Explore the alien planet of Gdleen and stop an interstellar war.', 'Play the polished Gdleen (Rev A) on the Super Famicom.', 'The updated revision featuring minor text fixes and balanced encounter rates for a more consistent 16-bit role-playing experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Gegege no Kitarou - Fukkatsu! Tenma Daiou (Japan)', '1994', NaN, 'TOSE', '1', NaN, 'Side-scrolling action-platformer based on the famous youkai anime.', 'Defeat the Great Demon King and his army of supernatural monsters.', 'Join Kitarou in Fukkatsu! Tenma Daiou for the SNES.', 'Utilize Kitarou''s unique youkai powers, like his needle hair and wooden clogs, to fight through eerie and beautiful 16-bit Japanese landscapes.', NULL);
