INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Gekisou Sentai Car Ranger - Zenkai! Racer Senshi (Japan) (ST)', '1996', NaN, 'Banpresto', '2', NaN, 'Futuristic mecha-racing game using the Sufami Turbo accessory.', 'Win the high-speed mecha races and protect the galaxy.', 'Race for glory in Gekisou Sentai Car Ranger for SNES.', 'A unique 16-bit racing title based on the Sentai series. Customize your vehicle and use special abilities to outpace rival mechs on sci-fi tracks.', NULL);
