INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'George Foreman''s KO Boxing (Europe)', '1992', NaN, 'Acclaim', '2', NaN, 'Arcade-style boxing game with large character sprites.', 'Defeat a series of eccentric boxers to claim the world title.', 'Hit the ring in George Foreman''s KO Boxing on the SNES.', 'A fun and accessible 16-bit boxing game. Focuses on timing your punches and dodges while managing your stamina against large, colorful opponents.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'George Foreman''s KO Boxing (USA)', '1992', NaN, 'Acclaim', '2', NaN, 'Arcade-style boxing game with large character sprites.', 'Defeat a series of eccentric boxers to claim the world title.', 'Hit the ring in George Foreman''s KO Boxing on the SNES.', 'Master the patterns of each rival boxer. A classic 16-bit sports title that emphasizes arcade action over complex simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'George Foreman''s KO Boxing (USA) (Doritos Promo)', '1992', NaN, 'Acclaim', '2', NaN, 'Arcade-style boxing game with a unique snack-brand promotion.', 'Win the championship in this special promotional version.', 'Play the rare Doritos Promo version of KO Boxing on SNES.', 'A unique promotional release featuring Doritos branding within the game. A rare 16-bit curiosity for collectors of licensed sports titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'George Foreman''s KO Boxing (USA) (Rev A)', '1992', NaN, 'Acclaim', '2', NaN, 'Arcade-style boxing game with large character sprites.', 'Defeat a series of eccentric boxers in the refined Rev A version.', 'Play the polished George Foreman''s KO Boxing on SNES.', 'The updated 16-bit revision featuring minor bug fixes and improved hit detection for a more consistent and fair boxing experience.', NULL);
