INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harley''s Humongous Adventure (Europe)', '1994', NaN, 'Hi Tech Expressions', '1', NaN, 'Action-platformer where you play as a tiny hero in a giant world.', 'Navigate through a massive house and retrieve your shrinking machine.', 'Join Harley''s Humongous Adventure on the Super Nintendo.', 'Explore oversized 16-bit environments like kitchens and playrooms. Use chemical weapons and gadgets to fight household pests in this creative platformer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harley''s Humongous Adventure (USA)', '1994', NaN, 'Hi Tech Expressions', '1', NaN, 'Action-platformer where you play as a tiny hero in a giant world.', 'Navigate through a massive house and retrieve your shrinking machine.', 'Join Harley''s Humongous Adventure on the Super Nintendo.', 'Master the use of the jetpack and grappling hook. A colorful 16-bit adventure that makes everyday objects feel like massive obstacles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harley''s Humongous Adventure (USA) (Beta)', '1994', NaN, 'Hi Tech Expressions', '1', NaN, 'Action-platformer where you play as a tiny hero in a giant world.', 'Test early physics and giant-sized level designs.', 'Check out Harley''s Humongous Adventure Beta on the SNES.', 'A pre-release version of the game. Discover early sprite work and how the 16-bit miniature scale was refined during the game''s development.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harukanaru Augusta (Japan)', '1991', NaN, 'T&E Soft', '2', NaN, 'Realistic golf simulation featuring the famous Augusta National course.', 'Master the fairways and win the prestigious Masters tournament.', 'Tee off in Harukanaru Augusta on the Super Famicom.', 'One of the first 16-bit golf games to feature digitized landscapes. Offers a slow-paced, technical simulation of professional golf with realistic wind and terrain.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harukanaru Augusta (Japan) (Rev B)', '1991', NaN, 'T&E Soft', '2', NaN, 'Realistic golf simulation featuring the famous Augusta National course.', 'Master the fairways in this refined 16-bit revision.', 'Play the polished Harukanaru Augusta (Rev B) on the SNES.', 'An updated Japanese version featuring improved ball physics and refined camera angles for a more accurate professional golfing experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harukanaru Augusta 2 - Masters (Japan)', '1992', NaN, 'T&E Soft', '2', NaN, 'Advanced golf simulation sequel with updated Masters content.', 'Compete against professional golfers on legendary courses.', 'Experience Harukanaru Augusta 2: Masters on the SNES.', 'Features improved 16-bit digitized graphics and more complex green reading. A deep simulation for players who enjoy the technical side of golf.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harukanaru Augusta 3 - Masters New (Japan)', '1993', NaN, 'T&E Soft', '2', NaN, 'The most advanced entry in the 16-bit Augusta golf series.', 'Claim the Green Jacket by mastering the world''s toughest greens.', 'Play the definitive Harukanaru Augusta 3 on Super Famicom.', 'Pushes the SNES hardware to provide detailed digitized courses and professional-grade 16-bit golf mechanics, including advanced swing controls.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harukanaru Augusta 3 - Masters New (Japan) (Rev A)', '1993', NaN, 'T&E Soft', '2', NaN, 'The most advanced entry in the 16-bit Augusta golf series.', 'Claim the Green Jacket in this refined Rev A version.', 'Play Harukanaru Augusta 3 (Rev A) on the Super Famicom.', 'The final 16-bit revision of the series, fixing minor data glitches and improving the AI of rival professional golfers for a fairer tournament.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harvest Moon (Europe)', '1994', NaN, 'Amccus', '1', NaN, 'Revolutionary farming simulation and life-management game.', 'Restore your grandfather''s farm while building relationships.', 'Start your farm life in Harvest Moon for the Super Nintendo.', 'The game that defined the genre. Manage your 16-bit crops, livestock, and schedule while trying to win the heart of a local villager in this cozy classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harvest Moon (Germany)', '1994', NaN, 'Amccus', '1', NaN, 'Revolutionary farming simulation and life-management game.', 'Restore your farm in the localized German version.', 'Spielen Sie Harvest Moon auf Deutsch für das SNES.', 'The complete 16-bit farming experience with fully localized German text. Manage your farm and social life in this beloved simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harvest Moon (Spanish)', '1994', NaN, 'Amccus', '1', NaN, 'Revolutionary farming simulation and life-management game.', 'Restore your farm in the localized Spanish version.', 'Juega a Harvest Moon en español para la Super Nintendo.', 'The 16-bit farming classic translated into Spanish. Clear the land, plant your crops, and build a legacy in your local language.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Harvest Moon (USA)', '1994', NaN, 'Amccus', '1', NaN, 'Revolutionary farming simulation and life-management game.', 'Restore your grandfather''s farm while building relationships.', 'Start your farm life in Harvest Moon for the Super Nintendo.', 'Clear the fields, raise cows, and get married. A deep and rewarding 16-bit experience that rewards patience and careful planning.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hashire Hebereke (Japan)', '1994', NaN, 'Sunsoft', '4', NaN, 'Isometric racing game featuring characters from the Hebereke series.', 'Win the race by using items and unique character abilities.', 'Race for glory in Hashire Hebereke for the Super Famicom.', 'A fast-paced 16-bit foot racer. Choose your favorite quirky character and navigate hazard-filled tracks in this colorful and chaotic Japanese exclusive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hat Trick Hero (Japan)', '1992', NaN, 'Taito', '2', NaN, 'Arcade soccer simulation featuring large sprites and special moves.', 'Win the world cup and use super shots to defeat rivals.', 'Kick off the action in Hat Trick Hero on the Super Famicom.', 'Known as Super Soccer Champ. A 16-bit football game that focuses on aggressive play and spectacular special moves rather than strict simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hat Trick Hero 2 (Japan)', '1994', NaN, 'Taito', '2', NaN, 'Enhanced soccer sequel with more teams and refined controls.', 'Lead your nation to victory in the ultimate 16-bit tournament.', 'Experience the high-energy Hat Trick Hero 2 on SNES.', 'Features improved 16-bit animations and the ability to perform even more outrageous special shots. A fun, arcade-style take on the world''s favorite sport.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hatayama Hatch no Pro Yakyuu News! - Jitsumei Ban (Japan)', '1993', NaN, 'Namco', '2', NaN, 'Baseball management and simulation based on the Pro Yakyuu News.', 'Manage your team and play through a realistic 16-bit season.', 'Step up to the plate in Hatayama Hatch no Pro Yakyuu News.', 'Features real player names and a TV-broadcast style presentation. Combines 16-bit on-field action with deep management and statistical tracking.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hayazashi Nidan Morita Shougi (Japan)', '1991', NaN, 'Sega', '2', NaN, 'Traditional Shogi simulation featuring an advanced AI chip.', 'Defeat professional-grade AI in this technical Shogi sim.', 'Master Shogi in Hayazashi Nidan Morita Shougi on SNES.', 'Utilizes a special internal chip to provide a faster and more intelligent 16-bit opponent, making it a favorite for serious Shogi players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hayazashi Nidan Morita Shougi 2 (Japan)', '1993', NaN, 'Sega', '2', NaN, 'Advanced Shogi sequel with even more powerful processing.', 'Challenge the ultimate digital Shogi master on your SNES.', 'Experience the elite Hayazashi Nidan Morita Shougi 2.', 'Uses the ST010 chip for world-class 16-bit AI calculations. Offers a professional Shogi experience that was groundbreaking for home consoles at the time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Head-On Soccer (USA)', '1994', NaN, 'U.S. Gold', '2', NaN, 'Fast-paced soccer game with a focus on arcade fun and speed.', 'Score goals and win the tournament in this high-speed sim.', 'Play the energetic Head-On Soccer for the Super Nintendo.', 'Known as Fever Pitch Soccer in Europe. Features 16-bit players with individual stats and a variety of power-ups to tip the scales in your favor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heartthrob Memorial: Under the Tree of Legends', '1996', NaN, 'Konami', '1', NaN, 'The foundational dating simulation game (Fan Translation title).', 'Win the heart of your dream girl before graduation day.', 'Experience Heartthrob Memorial (Tokimeki Memorial) on SNES.', 'The game that popularized the dating sim genre. Balance your 16-bit school grades, fitness, and social life to find true love under the legendary tree.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hebereke no Oishii Puzzle wa Irimasenka (Japan)', '1994', NaN, 'Sunsoft', '2', NaN, 'Competitive puzzle game featuring the quirky Hebereke cast.', 'Clear your board by matching colored blocks and sabotaging rivals.', 'Solve the puzzles in Hebereke no Oishii Puzzle on SNES.', 'A charming 16-bit tile-matching game. Use character-specific special moves to overwhelm your opponent in this colorful Japanese exclusive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hebereke no Popoon (Japan)', '1992', NaN, 'Sunsoft', '2', NaN, 'Fast-paced falling-block puzzle game with a humorous theme.', 'Defeat rivals in head-to-head 16-bit puzzle battles.', 'Join the fun in Hebereke no Popoon for the Super Famicom.', 'A frantic and cute 16-bit puzzler. Match heads to clear your screen and send garbage to your opponent in this high-energy arcade experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hebereke''s Popoitto (Europe)', '1995', NaN, 'Sunsoft', '2', NaN, 'Falling-block puzzle game localized for the European market.', 'Match the character heads to clear the board and win.', 'Play the quirky Hebereke''s Popoitto on the SNES.', 'The PAL version of the puzzle classic. Features the same addictive 16-bit gameplay and surreal humor that made the series a cult favorite in Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hebereke''s Popoon (Europe)', '1995', NaN, 'Sunsoft', '2', NaN, 'Falling-block puzzle game localized for the European market.', 'Match the character heads to clear the board and win.', 'Play the quirky Hebereke''s Popoon on the SNES.', 'A colorful 16-bit puzzle challenge for one or two players. Master the chain reactions to become the ultimate master of the Popoon world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heian Fuuunden (Japan)', '1992', NaN, 'Nichibutsu', '1', NaN, 'Tactical turn-based RPG set in a unique fantasy world.', 'Lead your army to restore peace to the land of Heian.', 'Experience the strategic Heian Fuuunden on the Super Famicom.', 'Features beautiful 16-bit art and a deep tactical combat system. Manage your units across diverse maps in a story inspired by Japanese history and mythology.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heisei Gunjin Shougi (Japan)', '1993', NaN, 'ASCII', '2', NaN, 'Strategy board game based on traditional military Shogi.', 'Outmaneuver your opponent and capture their flag or commander.', 'Play the tactical Heisei Gunjin Shougi on the Super Famicom.', 'A modern 16-bit take on the classic Military Shogi. Use hidden unit types and strategic movement to outsmart the AI or a friend in this tense game of logic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heisei Inu Monogatari Bow - Pop''n Smash!! (Japan)', '1994', NaN, 'Sunsoft', '2', NaN, 'Arcade-style air hockey/tennis game featuring the dog Bow.', 'Score points by smashing the puck past your opponent.', 'Join the fun in Bow: Pop''n Smash for the Super Famicom.', 'Based on the popular anime. Features fast-paced 16-bit arcade action with special power-ups and vibrant, humorous character animations in every match.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heisei Shin Onigashima - Kouhen (Japan)', '1992', NaN, 'Nintendo', '1', NaN, 'Cinematic visual novel and adventure game (The Conclusion).', 'Solve the mystery of the Oni island in this final chapter.', 'Complete the epic Heisei Shin Onigashima on the SNES.', 'The second half of Nintendo''s legendary adventure remake. Features beautiful 16-bit illustrations and a deep branching narrative based on Japanese folklore.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heisei Shin Onigashima - Zenhen (Japan)', '1992', NaN, 'Nintendo', '1', NaN, 'Cinematic visual novel and adventure game (The Beginning).', 'Embark on a mythical journey to uncover your true destiny.', 'Experience the first part of Heisei Shin Onigashima on SNES.', 'The opening chapter of this 16-bit masterpiece. Navigate through dialogue choices and environmental puzzles in a beautifully told fairy tale world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heiwa Pachinko World (Japan)', '1995', NaN, 'ASCII', '1', NaN, 'Authentic Pachinko simulation featuring real parlor machines.', 'Win the jackpot and manage your virtual parlor winnings.', 'Test your luck in Heiwa Pachinko World for the Super Famicom.', 'A realistic 16-bit recreation of Heiwa''s famous Pachinko machines. Features accurate ball physics and multiple themed tables to master.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heiwa Pachinko World 2 (Japan)', '1995', NaN, 'ASCII', '1', NaN, 'Authentic Pachinko simulation with updated machine types.', 'Master the latest digital Pachinko machines to win big.', 'Experience Heiwa Pachinko World 2 on the Super Famicom.', 'An improved sequel featuring more detailed 16-bit machine graphics and a wider variety of gameplay modes, including a story-driven career path.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heiwa Pachinko World 3 (Japan)', '1996', NaN, 'ASCII', '1', NaN, 'The final entry in the Heiwa Pachinko trilogy.', 'Collect the most silver balls across multiple professional machines.', 'Play the definitive Heiwa Pachinko World 3 on the SNES.', 'The most advanced 16-bit Pachinko simulation in the series. Features high-fidelity sound effects and the most accurate ball trajectories on the console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Heiwa Parlor! Mini 8 - Pachinko Jikki Simulation Game (Japan)', '1996', NaN, 'Heiwa', '1', NaN, 'Compact Pachinko simulation featuring a collection of mini-games.', 'Master eight different classic Pachinko machines.', 'Enjoy variety in Heiwa Parlor! Mini 8 for the Super Famicom.', 'A specialized 16-bit simulation focusing on eight legendary machines. Offers a quick-play experience for fans who want variety and realistic parlor mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hello! Pac-Man (Japan)', '1994', NaN, 'Namco', '2', NaN, 'Experimental side-scrolling adventure with indirect control.', 'Guide Pac-Man through his world by using a slingshot.', 'Play the unique Hello! Pac-Man on the Super Famicom.', 'Known in the West as Pac-Man 2: The New Adventures. A 16-bit point-and-click hybrid where you influence Pac-Man''s mood and actions to solve puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Herakles no Eikou III - Kamigami no Chinmoku (Japan)', '1992', NaN, 'Data East', '1', NaN, 'Epic turn-based RPG set in an ancient world of Greek myth.', 'Search for your lost immortality and solve the silence of the gods.', 'Experience the legendary Glory of Heracles III on SNES.', 'A masterpiece of 16-bit storytelling. Follow a protagonist who cannot die in a world filled with gods, tragedy, and deep philosophical themes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Herakles no Eikou III - Kamigami no Chinmoku (Japan) [En by Kojiro v0.95Beta1] (~Glory of Heracles III, The - Silence of the Gods)', '1992', NaN, 'Data East', '1', NaN, 'Epic turn-based RPG with a full English fan translation.', 'Experience the immortal hero''s journey with English text.', 'Play Glory of Heracles III in English on the Super Nintendo.', 'The Kojiro translation allows Western fans to enjoy one of the best 16-bit RPG scripts, full of mystery and mythological intrigue.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Herakles no Eikou IV - Kamigami Kara no Okurimono (Japan)', '1994', NaN, 'Data East', '1', NaN, 'Advanced turn-based RPG featuring a spirit system and party swapping.', 'Prevent a global catastrophe by aiding the gods of Olympus.', 'Embark on the journey in Glory of Heracles IV on SNES.', 'The final 16-bit entry. Features incredible graphics and the unique ability to transfer the hero''s soul into different bodies to solve puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hero Senki - Project Olympus (Japan)', '1992', NaN, 'Banpresto', '1', NaN, 'Tactical RPG crossover featuring iconic Japanese heroes.', 'Lead Gundam, Ultraman, and Kamen Rider to save Project Olympus.', 'Join the heroes in Hero Senki for the Super Famicom.', 'A precursor to the Super Robot Wars series. Features turn-based 16-bit combat with beautifully animated special attacks from legendary hero franchises.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hi no Ouji Yamato Takeru (Japan)', '1993', NaN, 'Hot-B', '1', NaN, 'Action-RPG based on the ancient Japanese legend of Yamato Takeru.', 'Defeat the Orochi clan and reclaim your rightful throne.', 'Explore the mythical Hi no Ouji Yamato Takeru on SNES.', 'A visually distinct 16-bit RPG. Navigate through ancient Japan, using magical artifacts and sword skills to overcome mythological beasts and dark sorcery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Higashio Osamu Kanshuu - Super Pro Yakyuu Stadium (Japan)', '1993', NaN, 'Namco', '2', NaN, 'Baseball simulation with a focus on coaching and strategy.', 'Lead your pro team to victory through expert management.', 'Master the diamond in Super Pro Yakyuu Stadium on SNES.', 'Endorsed by pitching legend Osamu Higashio. Features detailed 16-bit player stats and a more strategic, simulation-heavy approach to the sport.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hiouden - Mamono-tachi Tono Chikai (Japan)', '1992', NaN, 'Taito', '1', NaN, 'Real-time tactical RPG with a focus on monster commanding.', 'Lead the Scarlet King''s army to reclaim his lost kingdom.', 'Command the spirits in Hiouden on the Super Famicom.', 'A unique 16-bit title from Wolf Team. Use a cursor-based interface to command your party in real-time battles against humans and demons alike.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hiouden - Mamono-tachi Tono Chikai (Japan) [En by Aeon Genesis v1.0] (~Hiouden - Legend of the Scarlet King - The Demonic Oath)', '1992', NaN, 'Taito', '1', NaN, 'Real-time tactical RPG with a full English fan translation.', 'Experience the Legend of the Scarlet King with English text.', 'Play Hiouden in English on the Super Nintendo.', 'The Aeon Genesis translation opens this complex 16-bit strategy game to the West. Manage your troops and unleash powerful spells in a dark fantasy setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hiryuu no Ken S - Golden Fighter (Japan)', '1992', NaN, 'Culture Brain', '2', NaN, 'Martial arts fighting game with a unique RPG-style story mode.', 'Win the tournament and master the secret Hiryuu techniques.', 'Battle for glory in Hiryuu no Ken S (Flying Dragon) on SNES.', 'A hybrid of 16-bit fighting and RPG elements. Features a clash system where you must predict your opponent''s next move to counter effectively.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hiryuu no Ken S - Hyper Version (Japan)', '1993', NaN, 'Culture Brain', '2', NaN, 'Enhanced fighting game with faster speed and new characters.', 'Defeat the ultimate grandmasters in this Hyper tournament.', 'Experience the fast-paced Hiryuu no Ken S Hyper on SNES.', 'The definitive version of the fighter. Features improved 16-bit animations and a re-balanced roster for a more competitive arcade-style experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hissatsu Pachinko Collection (Japan)', '1994', NaN, 'Sunsoft', '1', NaN, 'Comprehensive Pachinko collection with a focus on variety.', 'Unlock and master a diverse set of professional machines.', 'Play Hissatsu Pachinko Collection on the Super Famicom.', 'A high-quality 16-bit simulation of Sunsoft''s famous Pachinko lineup. Features realistic parlor atmosphere and multiple difficulty levels for enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Hissatsu Pachinko Collection 2 (Japan)', '1995', NaN, 'Sunsoft', '1', NaN, 'Pachinko sequel featuring modernized digital machines.', 'Win the jackpot across a new set of themed machines.', 'Experience Hissatsu Pachinko Collection 2 on the SNES.', 'Features more complex machine logic and improved 16-bit visual effects. A must-play for fans of authentic digital gambling simulations.', NULL);
