INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Joe & Mac 2 - Lost in the Tropics (USA) (Beta)', '1994', NaN, 'Data East', '2', NaN, 'Adventure-platformer with RPG elements and world-map exploration.', 'Explore early tropical levels and new RPG mechanics.', 'Check out Joe & Mac 2: Lost in the Tropics Beta on SNES.', 'A pre-release version of the 16-bit sequel. Witness the early implementation of the world map and the evolution of the iconic caveman sprites.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Joe & Mac 3 - Lost in the Tropics (Europe) (En,Fr,De)', '1995', NaN, 'Data East', '2', NaN, 'Adventure-platformer with RPG elements, known as Joe & Mac 2 in USA.', 'Recover the stolen crown in the localized European version.', 'Play the epic Joe & Mac 3 on the Super Nintendo.', 'The European release of the sequel (marketed as the 3rd entry). Features multilingual support and the same polished 16-bit prehistoric exploration and combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Joe & Mac 3 - Lost in the Tropics (Europe) (En,Fr,De) (Beta)', '1995', NaN, 'Data East', '2', NaN, 'Adventure-platformer with RPG elements, known as Joe & Mac 2 in USA.', 'Test the localized European build and tropical stages.', 'Check out the Joe & Mac 3 (Beta) version on the SNES.', 'An early 16-bit European development build. Features preliminary translations and level balancing for the final multilingual release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'John Madden Football ''93 (Europe)', '1992', NaN, 'Park Place Productions', '2', NaN, 'Realistic American football simulation with updated 1993 rosters.', 'Lead your team to the Super Bowl with Madden''s expert strategy.', 'Kick off the action in John Madden Football ''93 on SNES.', 'The definitive early 16-bit football sim. Features improved animations, more plays, and the signature Madden style that revolutionized sports gaming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'John Madden Football ''93 (USA)', '1992', NaN, 'Park Place Productions', '2', NaN, 'Realistic American football simulation with updated 1993 rosters.', 'Win the championship in the premier 16-bit football sim.', 'Experience John Madden Football ''93 on the Super Nintendo.', 'Features realistic field conditions and detailed playbooks. A benchmark 16-bit sports title that rewards tactical planning and quick reflexes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'John Madden Football ''93 (USA) (Rev A)', '1992', NaN, 'Park Place Productions', '2', NaN, 'Realistic American football simulation with updated 1993 rosters.', 'Win the league in this refined 16-bit revision.', 'Play the polished John Madden Football ''93 (Rev A) on SNES.', 'An updated Japanese revision that improves player AI and fixes minor 16-bit logic errors for a more consistent professional football experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'John Madden Football (USA)', '1990', NaN, 'Park Place Productions', '2', NaN, 'The foundational entry of the legendary football simulation series.', 'Master the gridiron and win the first Madden championship.', 'Play the original John Madden Football on the Super Nintendo.', 'The game that started the 16-bit football revolution. Introduces deep tactical playcalling and the iconic perspective that defined the series for years.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'JoJo no Kimyou na Bouken (Japan)', '1993', NaN, 'Cobra Team', '2', NaN, 'Turn-based RPG based on the iconic Stardust Crusaders arc.', 'Travel to Egypt to defeat DIO and save Jotaro''s mother.', 'Join the adventure in JoJo no Kimyou na Bouken on SNES.', 'A unique 16-bit JRPG featuring the Stand combat system. Explore beautifully drawn locations and battle iconic villains in a story faithful to the legendary manga.', NULL);
