INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'JRA PAT (Japan) (TJAJ)', '1995', NaN, 'Naxat Soft', '1', NaN, 'Foundational horse racing data utility for the Japan Racing Assoc.', 'Track professional horse data and simulate race outcomes.', 'Experience the original JRA PAT on the Super Famicom.', 'The initial version of the data-heavy 16-bit racing sim. Offers a comprehensive look at the statistics and breeding records of the JRA era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'JRA PAT (Japan) (TJBJ)', '1995', NaN, 'Naxat Soft', '1', NaN, 'Updated horse racing data utility with refined interface and data.', 'Improve your betting strategy with the latest JRA statistics.', 'Try JRA PAT (TJBJ) for the Super Famicom.', 'A revised 16-bit utility featuring minor data updates and improved navigation for a more efficient race-tracking experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Judge Dredd (Europe)', '1995', NaN, 'Probe Software', '1', NaN, 'Side-scrolling action shooter based on the cult classic film.', 'Clean up the streets of Mega-City One as the law.', 'I am the law in Judge Dredd for the Super Nintendo.', 'Blast through criminal gangs in a gritty 16-bit world. Use your Lawgiver pistol with multiple ammo types to defeat the Dark Judges and restore order.', NULL);
