INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'JWP Joshi Pro Wrestling - Pure Wrestle Queens (Japan)', '1994', NaN, 'JWP', '2', NaN, 'All-female professional wrestling simulation with RPG elements.', 'Win the JWP championship and lead your wrestler to the top.', 'Enter the ring in Pure Wrestle Queens for the Super Famicom.', 'Features real-life wrestlers from the JWP promotion. A technical 16-bit wrestling game that balances ring action with management and character growth.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'K.H. Rummenigge''s Player Manager (Germany)', '1994', NaN, 'Software 2000', '1', NaN, 'In-depth soccer management simulation for the German market.', 'Lead your team to the Bundesliga title through expert coaching.', 'Master the pitch in Player Manager for the Super Nintendo.', 'Endorsed by Karl-Heinz Rummenigge. Features deep 16-bit management menus, player transfers, and a tactical simulation of professional football.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'K.H. Rummenigge''s Player Manager (Germany) (Sample)', '1994', NaN, 'Software 2000', '1', NaN, 'In-depth soccer management simulation for the German market.', 'Explore the early management menus and database.', 'Check out the Player Manager Sample on the SNES.', 'A rare look at the game''s production. Witness the development of the 16-bit management engine and the player statistical tracking system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kablooey (USA)', '1991', NaN, 'Kemco', '1', NaN, 'Puzzle game where you must clear mines and traps.', 'Safely detonate explosives to clear each 16-bit level.', 'Solve the explosive puzzles in Kablooey for the SNES.', 'Known as Bombuzal in other regions. Features a variety of perspectives and increasingly complex logic puzzles that reward careful planning and timing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kabuki Chou Reach Mahjong Tonpuusen (Japan)', '1994', NaN, 'SETA', '1', NaN, 'Traditional Mahjong simulation set in the famous Kabuki district.', 'Defeat the local masters and win the high-stakes tournament.', 'Play Kabuki Chou Reach Mahjong on the Super Famicom.', 'A polished 16-bit Mahjong title featuring realistic AI and a distinct urban atmosphere. Perfect for fans of the traditional Japanese tile game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kabuki Rocks (Japan)', '1994', NaN, 'Atelier Double', '1', NaN, 'Theatrical turn-based RPG with a Kabuki and Rock-and-Roll theme.', 'Stop the evil forces using the power of music and drama.', 'Experience the unique Kabuki Rocks on the Super Famicom.', 'One of the most creative 16-bit JRPGs. Features a rock-inspired soundtrack, theater-themed combat, and a vibrant art style that blends traditional Japan with modern flair.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kachou Shima Kousaku (Japan)', '1995', NaN, 'Kaneko', '1', NaN, 'Digital board game/simulation based on the famous salaryman manga.', 'Climb the corporate ladder and manage your business career.', 'Experience the life of Shima Kousaku on the Super Famicom.', 'A unique 16-bit life sim. Navigate corporate politics, make business decisions, and follow the story of the most famous salaryman in Japanese fiction.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kagakusha Harley no Haran Banjou (Japan)', '1993', NaN, 'ASCII', '1', NaN, 'Action-platformer where you play as a tiny hero in a giant world.', 'Navigate a massive house and retrieve your shrinking machine.', 'Experience Harley no Haran Banjou on the Super Famicom.', 'The Japanese version of Harley''s Humongous Adventure. Use chemical weapons and gadgets to survive 16-bit kitchen and toy room stages from a miniature perspective.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kaite Tsukutte Asoberu Dezaemon (Japan)', '1991', NaN, 'ASCII', '1', NaN, 'Vertical shoot ''em up with a built-in game creation engine.', 'Create your own shooter or play the pre-made sample levels.', 'Build your own shooter in Dezaemon for the Super Famicom.', 'A groundbreaking 16-bit utility. Design your own ships, enemies, and music, or play the included high-quality shmup developed by Athena.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kakinoki Shougi for Super Famicom (Japan)', '1995', NaN, 'ASCII', '2', NaN, 'Traditional Shogi (Japanese Chess) simulation with professional AI.', 'Defeat the Kakinoki AI and master the art of Shogi strategy.', 'Play the technical Kakinoki Shougi on the Super Famicom.', 'A serious 16-bit Shogi simulation. Features multiple analysis tools, difficulty levels, and a clean interface for serious practitioners of the game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kamaitachi no Yoru (Japan)', '1994', NaN, 'Chunsoft', '1', NaN, 'Sound novel/mystery adventure with silhouette-based characters.', 'Solve the murder mystery at a snowy mountain lodge.', 'Experience the legendary Kamaitachi no Yoru on SNES.', 'A masterpiece of 16-bit storytelling. Use logic and intuition to make choices that lead to over 40 different endings in this atmospheric thriller.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kamen Rider (Japan)', '1993', NaN, 'Bandai', '1', NaN, 'Side-scrolling beat ''em up based on the iconic tokusatsu hero.', 'Defeat the Shocker organization and their mutant cyborgs.', 'Fight for justice in Kamen Rider for the Super Famicom.', 'Features intense 16-bit brawling action. Control Rider 1 or Rider 2, master the Rider Kick, and battle classic kaijin bosses from the TV series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kamen Rider SD - Shutsugeki!! Rider Machine (Japan)', '1994', NaN, 'Bandai', '1', NaN, 'Isometric combat racing game featuring SD (Super Deformed) Riders.', 'Race through dangerous tracks and defeat the Shocker minions.', 'Speed away in Kamen Rider SD for the Super Famicom.', 'A unique 16-bit racer. Use combat moves and special items to knock rivals off their bikes while navigating hazard-filled stages across Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Karura Ou (Japan)', '1994', NaN, 'Taito', '1', NaN, 'Side-scrolling action-platformer with a dark mythological theme.', 'Stop the evil sorcerer and restore balance to the world.', 'Discover the intense Karura Ou on the Super Famicom.', 'Known as Skyblazer in the West. Features fluid 16-bit movement, wall-climbing mechanics, and spectacular magical attacks in a vibrant fantasy setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kashiwagi Shigetaka no Top Water Bassing (Japan)', '1994', NaN, 'VAP', '1', NaN, 'Realistic fishing simulation focused on top-water techniques.', 'Catch the biggest prize bass using surface lures and strategy.', 'Master top-water fishing in Kashiwagi Shigetaka on SNES.', 'A specialized 16-bit fishing sim. Focuses on the precise movement of top-water lures to attract bass in beautifully rendered Japanese lake environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kat''s Run - Zen-Nihon K-Car Senshuken (Japan)', '1993', NaN, 'Atlus', '1', NaN, 'Isometric racing game featuring Japanese Kei micro-cars.', 'Win the K-Car championship through tight turns and speed.', 'Race tiny cars in Kat''s Run for the Super Famicom.', 'A quirky 16-bit racer. Choose from a variety of micro-cars with unique handling and race through urban and rural Japanese tracks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Katou Hifumi Kudan - Shougi Club (Japan)', '1995', NaN, 'Nichibutsu', '2', NaN, 'Professional Shogi simulation featuring master Hifumi Katou.', 'Challenge the Legend Hifumi Katou and improve your rank.', 'Play the elite Katou Hifumi Shougi on the Super Famicom.', 'Offers high-level 16-bit AI and detailed tutorials based on Katou''s professional games. Perfect for players looking to study master-level Shogi.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kawa no Nushi Tsuri 2 (Japan)', '1994', NaN, 'Pack-In-Video', '1', NaN, 'RPG-style fishing simulation with open-world exploration.', 'Catch the King of the River and help your family.', 'Experience the charming Kawa no Nushi Tsuri 2 on SNES.', 'Known as Legend of the River King. Blends 16-bit RPG progression with a deep fishing engine. Level up your gear and explore diverse nature maps.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kawasaki Caribbean Challenge (USA)', '1994', NaN, 'Absolute', '1', NaN, 'Multi-sport racing game featuring jet skis and ATVs.', 'Win the Caribbean championship across water and land.', 'Race through paradise in Kawasaki Caribbean Challenge.', 'A fast-paced 16-bit racer that uses Mode 7 for scaling. Switch between different Kawasaki vehicles and master various terrains to claim victory.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kawasaki Superbike Challenge (Europe)', '1995', NaN, 'Lankhor', '1', NaN, 'High-speed motorcycle racing simulation using Mode 7.', 'Win the Superbike world title on authentic international tracks.', 'Feel the speed in Kawasaki Superbike Challenge for SNES.', 'Features a realistic cockpit view and impressive 16-bit scaling. Lean into corners and manage your speed to dominate the professional racing circuit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kawasaki Superbike Challenge (USA)', '1995', NaN, 'Lankhor', '1', NaN, 'High-speed motorcycle racing simulation using Mode 7.', 'Win the Superbike world title on authentic international tracks.', 'Feel the speed in Kawasaki Superbike Challenge for SNES.', 'Navigate through weather changes and challenging curves. A technical 16-bit racer that captures the intensity of professional bike racing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Keeper (Japan)', '1994', NaN, 'KID', '1', NaN, 'Falling-block puzzle game with a unique movement mechanic.', 'Clear the board by pushing and matching colored blocks.', 'Solve the clever puzzles in Keeper for the Super Famicom.', 'A creative 16-bit puzzler. Instead of falling blocks, you move a cursor to slide tiles across the grid, creating chains to clear the stage before time runs out.', NULL);
