INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Keiba Eight Special (Japan) (Rev A)', '1993', NaN, 'Namco', '1', NaN, 'Horse racing data and betting simulation (Refined Version).', 'Analyze race data and win big in this updated simulation.', 'Play the polished Keiba Eight Special (Rev A) on SNES.', 'The updated 16-bit Japanese revision featuring minor data corrections and improved menu navigation for horse racing enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Keiba Eight Special 2 (Japan)', '1994', NaN, 'Namco', '1', NaN, 'Advanced horse racing simulation with updated data and visuals.', 'Become a betting pro with the latest JRA racing statistics.', 'Experience Keiba Eight Special 2 on the Super Famicom.', 'Features a more comprehensive database of horses and jockeys. A deep 16-bit management and betting sim for the serious horse racing fan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ken Griffey Jr. Presents Major League Baseball (USA)', '1994', NaN, 'Rare', '2', NaN, 'Arcade-style baseball simulation with real MLB teams and players.', 'Win the World Series with the help of Ken Griffey Jr.', 'Hit a home run in Ken Griffey Jr. Presents MLB on SNES.', 'Known for its fast gameplay and real feel despite the arcade style. Features a full 16-bit season mode and the iconic swing of The Kid.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ken Griffey Jr.''s Winning Run (USA)', '1996', NaN, 'Rare', '2', NaN, 'High-performance baseball sim with advanced graphics and physics.', 'Claim the pennant in this technically impressive sequel.', 'Experience Ken Griffey Jr.''s Winning Run on the SNES.', 'Developed by Rare. Features ACM rendered 16-bit graphics and incredibly fluid player animations. One of the best-looking and playing sports titles on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kendo Rage (USA)', '1993', NaN, 'Jaleco', '1', NaN, 'Side-scrolling action-platformer with a humorous anime style.', 'Win the Kendo tournament and defeat the school''s monsters.', 'Battle with spirit in Kendo Rage for the Super Nintendo.', 'Control Maki as she uses her magical kendo stick to fight bizarre 16-bit enemies. A colorful and charming adventure with a distinct Japanese flair.', NULL);
