INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kenyuu Densetsu Yaiba (Japan)', '1993', NaN, 'Atelier Double', '1', NaN, 'Action-RPG based on the popular manga by Gosho Aoyama.', 'Defeat the Onimaru clan and master the legendary swords.', 'Join the adventure in Kenyuu Densetsu Yaiba on SNES.', 'A vibrant 16-bit action title. Use Yaiba''s diverse elemental orbs to solve puzzles and defeat enemies in a story full of humor and martial arts.', NULL);
