INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kidou Senshi Z-Gundam - Away to the Newtype (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Tactical strategy game with a focus on Newtype abilities.', 'Guide the AEUG to victory in the Gryps Conflict.', 'Master strategy in Z-Gundam: Away to the Newtype.', 'A deep 16-bit tactical sim. Features an original branching narrative where your strategic choices determine the fate of the Z-Gundam cast.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kidou Soukou Dion (Japan)', '1993', NaN, 'NCS', '1', NaN, 'Vertical-scrolling shoot ''em up featuring a transformable mech.', 'Blast through enemy lines and stop the mechanical threat.', 'Pilot the mech in Kidou Soukou Dion on Super Famicom.', 'Known as Hyperaze. A high-intensity 16-bit shooter where you can transform your craft to adapt to different combat situations and enemy patterns.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kidoukeisatsu Patlabor (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Visual novel and adventure game based on the Patlabor series.', 'Solve crimes and pilot the Labor in this cinematic adventure.', 'Experience Kidoukeisatsu Patlabor on the Super Famicom.', 'Features a deep 16-bit narrative focusing on the Special Vehicle Section 2. Solve mysteries through dialogue and engage in strategic Labor combat sequences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kigurumi Daibouken - Dream Maze (Japan)', '1991', NaN, 'Sigma', '1', NaN, 'Surreal first-person dungeon crawler with a maze theme.', 'Navigate the dream maze and solve its bizarre puzzles.', 'Explore the quirky Kigurumi Daibouken on Super Famicom.', 'A unique 16-bit RPG where characters wear mascot costumes. Features a colorful art style and turn-based combat in a world filled with dreams and humor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kiki Kaikai - Nazo no Kuro Manteau (Japan)', '1992', NaN, 'Taito', '2', NaN, 'Top-down run-and-gun shooter set in ancient Japan.', 'Defeat the Black Mantle and save the seven fortune gods.', 'Play Kiki Kaikai (Pocky & Rocky) on the Super Famicom.', 'A 16-bit masterpiece. Use talismans and magic to fight through waves of yokai in beautiful environments. Features incredible co-op gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kiki Kaikai - Tsukiyo Soushi (Japan)', '1994', NaN, 'Taito', '2', NaN, 'Top-down run-and-gun shooter with improved graphics and modes.', 'Embark on a new quest to save the lunar princess.', 'Experience Kiki Kaikai: Tsukiyo Soushi on Super Famicom.', 'The sequel known as Pocky & Rocky 2. Features refined 16-bit graphics, a variety of AI partners, and even more detailed Japanese folklore-inspired stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kikou Keisatsu Metal Jack (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Side-scrolling action-platformer based on the Metal Jack anime.', 'Defeat the criminal underworld using cybernetic armor.', 'Join the fight in Metal Jack for the Super Famicom.', 'Control the Jackal team in this 16-bit action title. Features armor transformations and intense combat against mechanical and biological threats.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kikuni Masahiko no Jantoushi Doraou (Japan)', '1992', NaN, 'ASCII', '1', NaN, 'Humorous Mahjong simulation featuring quirky characters.', 'Win the tournament in this comedy-focused Mahjong game.', 'Play Jantoushi Doraou on the Super Famicom.', 'Based on the manga by Masahiko Kikuni. Features 16-bit Mahjong strategy mixed with hilarious character reactions and a distinct underground gambling vibe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kikuni Masahiko no Jantoushi Doraou 2 - Kigyou Senshi (Japan)', '1993', NaN, 'ASCII', '1', NaN, 'Professional Mahjong simulation sequel with a corporate theme.', 'Climb the corporate ladder by winning Mahjong matches.', 'Experience Jantoushi Doraou 2 on the Super Famicom.', 'Combines 16-bit Mahjong gameplay with a business management simulation. Defeat rival salarymen to expand your company and reach the top.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Killer Instinct - Eyedol Edition Deluxe', '1995', NaN, 'Rare', '2', NaN, 'Modified version of the fighting classic with boss characters.', 'Control the final boss Eyedol in this deluxe fan edition.', 'Play Killer Instinct: Eyedol Edition on the SNES.', 'A specialized 16-bit mod that allows players to use the final boss and features various balance tweaks for the ultimate competitive experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Killer Instinct (Europe)', '1995', NaN, 'Rare', '2', NaN, 'High-tech fighting game with pre-rendered 3D graphics.', 'Defeat the UltraTech tournament fighters and stop Cinder.', 'Master the combos in Killer Instinct for the SNES.', 'A technical marvel for the 16-bit era. Features the famous Combo system, Ultra finishes, and an incredible soundtrack that pushed the system to its limit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Killer Instinct (USA)', '1995', NaN, 'Rare', '2', NaN, 'High-tech fighting game with pre-rendered 3D graphics.', 'Defeat the UltraTech tournament fighters and stop Cinder.', 'Master the combos in Killer Instinct for the SNES.', 'Experience the definitive 16-bit brawler. Control a roster of diverse characters from Glacius to Jago in high-speed, high-fidelity combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Killer Instinct (USA) (Beta)', '1995', NaN, 'Rare', '2', NaN, 'High-tech fighting game with pre-rendered 3D graphics.', 'Test early character balance and the combo breaker engine.', 'Check out the Killer Instinct Beta on the SNES.', 'A pre-release 16-bit development build. Witness the fine-tuning of the complex combo mechanics and early sprite rendering techniques.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Killer Instinct (USA) (Rev A)', '1995', NaN, 'Rare', '2', NaN, 'High-tech fighting game with pre-rendered 3D graphics.', 'Win the tournament in this refined 16-bit revision.', 'Play the polished Killer Instinct (Rev A) on the SNES.', 'An updated North American revision that fixes minor gameplay glitches and improves the stability of the 16-bit combo system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Killer Instinct MSU-1', '1995', NaN, 'Rare', '2', NaN, 'Enhanced version of the fighter with CD-quality audio.', 'Experience Killer Instinct with a high-fidelity soundtrack.', 'Play Killer Instinct MSU-1 on the Super Nintendo.', 'Utilizes the MSU-1 chip to bring the original arcade''s high-quality music and audio to the 16-bit console for the most immersive experience possible.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kindai Mahjong Special (Japan)', '1993', NaN, 'Namco', '1', NaN, 'Professional Mahjong simulation with updated rules and data.', 'Win the special tournament and prove your strategic skill.', 'Play Kindai Mahjong Special on the Super Famicom.', 'Features realistic AI and a focus on the modern rules of the game. A polished 16-bit title for serious fans of Japanese Mahjong.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'King Arthur & The Knights of Justice (USA)', '1992', NaN, 'LJN', '1', NaN, 'Action-adventure based on the animated series and toys.', 'Lead the Knights of Justice to save King Arthur from Morgana.', 'Join King Arthur & The Knights of Justice on SNES.', 'A top-down 16-bit adventure developed by Enix. Manage your team of knights, solve environmental puzzles, and engage in real-time combat in Camelot.', NULL);
