INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'King Arthur''s World (USA)', '1992', NaN, 'Argonaut', '1', NaN, 'Side-scrolling puzzle-strategy game based on unit management.', 'Conquer enemy kingdoms by strategically deploying your army.', 'Command your troops in King Arthur''s World for the SNES.', 'A unique 16-bit strategy title where you lead knights, archers, and engineers. Navigate through trap-filled levels and use siege engines to destroy enemy fortifications.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'King Arthur''s World (USA) (Beta)', '1992', NaN, 'Argonaut', '1', NaN, 'Side-scrolling puzzle-strategy game based on unit management.', 'Test the early castle-siege levels and unit balancing.', 'Check out the King Arthur''s World (Beta) for the SNES.', 'An early 16-bit development build. Explore initial level designs and mechanical tweaks for the army-command system before the final North American release.', NULL);
