INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'King of Dragons, The (USA)', '1994', NaN, 'Capcom', '2', NaN, 'Fantasy side-scrolling beat ''em up with RPG leveling elements.', 'Defeat the dragon Gildiss and restore peace to the kingdom.', 'Slay the beast in The King of Dragons for the SNES.', 'Master the 16-bit combat and character-specific abilities. Fight through diverse fantasy environments in one of the most polished brawlers on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'King of Rally, The (Japan)', '1994', NaN, 'Atelier Double', '1', NaN, 'Mode 7-based rally racing simulation with a focus on realism.', 'Win the international rally championship across diverse terrains.', 'Feel the mud in The King of Rally for the Super Famicom.', 'A technical 16-bit racer that uses the console''s rotation effects. Navigate sharp turns and changing weather in various global locations to claim the title.', NULL);
