INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'King of the Monsters 2 - The Next Thing (Japan)', '1993', NaN, 'SNK', '2', NaN, 'Beat ''em up sequel featuring massive monsters and alien invaders.', 'Stop the alien threat by fighting through global locations.', 'Battle for Earth in King of the Monsters 2 on SNES.', 'A shift from the first game''s wrestling focus to a 16-bit side-scrolling brawler. Control three giant heroes and defeat bizarre biological mutations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'King of the Monsters 2 (USA)', '1993', NaN, 'SNK', '2', NaN, 'Beat ''em up sequel featuring massive monsters and alien invaders.', 'Save the world from the alien bio-menace.', 'Experience King of the Monsters 2: The Next Thing.', 'Features huge 16-bit sprites and intense boss encounters. A cinematic brawler that scales up the action and destruction on a global level.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kingyo Chuuihou! Tobidase! Game Gakuen (Japan)', '1992', NaN, 'Toho', '1', NaN, 'Mini-game collection based on the popular Goldfish Warning! anime.', 'Win a series of wacky school-themed mini-games and events.', 'Join the fun in Kingyo Chuuihou! on the Super Famicom.', 'A colorful 16-bit party game. Compete against friends or AI in humorous challenges inspired by the surreal and cute world of the hit manga.', NULL);
