INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kirby''s Dream Land 3 (USA)', '1997', NaN, 'HAL Laboratory', '2', NaN, 'Side-scrolling platformer with a hand-drawn colored pencil art style.', 'Defeat Dark Matter and restore peace to Dream Land.', 'Discover the beautiful Kirby''s Dream Land 3 on SNES.', 'One of the most visually unique 16-bit games. Team up with Gooey and animal friends like Rick, Coo, and Kine to solve puzzles and beat bosses.', NULL);
