INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kishin Kourinden Oni (Japan)', '1994', NaN, 'Banpresto', '1', NaN, 'Traditional turn-based RPG with a mythological Oni theme.', 'Lead the Oni warriors to stop a dark demonic uprising.', 'Explore the ancient world of Kishin Kourinden Oni on SNES.', 'Part of the long-running Oni series. Features 16-bit turn-based combat, a world map rooted in Japanese folklore, and a deep character-growth system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kishin Kourinden Oni (Japan) (Beta)', '1994', NaN, 'Banpresto', '1', NaN, 'Traditional turn-based RPG with a mythological Oni theme.', 'Test the early world map and combat balancing.', 'Check out the Kishin Kourinden Oni Beta on SNES.', 'A pre-release 16-bit development build. Witness the early implementation of the mythological narrative and tactical encounter designs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kiteretsu Daihyakka - Choujikuu Sugoroku (Japan)', '1995', NaN, 'Epoch', '4', NaN, 'Digital board game (Sugoroku) based on the classic anime.', 'Race across time and space to reach the goal before your rivals.', 'Play Kiteretsu Daihyakka on the Super Famicom.', 'A charming 16-bit board game featuring Kiteretsu and Korosuke. Use futuristic gadgets to sabotage opponents and navigate through different historical eras in this colorful family game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Knights of the Round (Europe)', '1994', NaN, 'Capcom', '2', NaN, 'Side-scrolling beat ''em up with an RPG-style leveling system.', 'Overthrow the tyrant Garibaldi and claim the Holy Grail.', 'Become a legend in Knights of the Round for the SNES.', 'A 16-bit Capcom masterpiece. Choose between Arthur, Lancelot, or Perceval. As you defeat enemies, your character levels up, visually changing their armor and weapons in real-time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Knights of the Round (Japan)', '1994', NaN, 'Capcom', '2', NaN, 'Side-scrolling beat ''em up with an RPG-style leveling system.', 'Claim the throne in the original Japanese version.', 'Experience Knights of the Round on the Super Famicom.', 'The foundational 16-bit release of the arcade hit. Features horse-mounted combat, satisfying parry mechanics, and some of the best medieval pixel art on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Knights of the Round (USA)', '1994', NaN, 'Capcom', '2', NaN, 'Side-scrolling beat ''em up with an RPG-style leveling system.', 'Lead the Knights to victory and restore order to Britain.', 'Battle through Knights of the Round on the Super Nintendo.', 'Master the strategic blocking system to earn invincibility frames. A polished 16-bit brawler that rewards skill and features epic boss fights against heavily armored rivals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Konpeki no Kantai (Japan)', '1993', NaN, 'SEGA', '1', NaN, 'Deep naval strategy simulation set in an alternate WWII.', 'Command the Imperial Japanese Navy to dominate the Pacific.', 'Master the seas in Konpeki no Kantai on Super Famicom.', 'A complex 16-bit strategy game based on the popular Deep Blue Fleet novels. Manage fleet formations, technological research, and tactical naval engagements.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kouryaku Casino Bar (Japan)', '1996', NaN, 'Namco', '1', NaN, 'Gambling simulation featuring various casino table games.', 'Win the high-stakes tournament and break the casino bank.', 'Test your luck in Kouryaku Casino Bar on Super Famicom.', 'Features realistic 16-bit renditions of Blackjack, Poker, and Roulette. Practice your betting strategies in a detailed virtual casino environment with smooth menu navigation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kouryuu Densetsu Villgust - Kieta Shoujo (Japan)', '1992', NaN, 'TOSE', '1', NaN, 'Turn-based JRPG based on the dark fantasy anime and manga.', 'Lead Murobo and his party to rescue the kidnapped girl.', 'Discover Kouryuu Densetsu Villgust on the Super Famicom.', 'A traditional 16-bit RPG featuring random encounters and turn-based combat. Explore a world filled with mythological creatures and detailed character portraits inspired by the OVA series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kouryuu Densetsu Villgust - Kieta Shoujo (Japan) [En by Magic Destiny v1.0]', '1992', NaN, 'TOSE', '1', NaN, 'Turn-based JRPG with a full English fan translation.', 'Experience the dark fantasy epic with English text.', 'Play Villgust in English on the Super Nintendo.', 'The Magic Destiny translation makes this hidden 16-bit gem accessible. Follow the emotional story of the lost girl through ancient ruins and dangerous dungeons in English.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kouryuu no Mimi (Japan)', '1995', NaN, 'Hudson Soft', '1', NaN, 'Side-scrolling beat ''em up based on the adult action manga.', 'Defeat the rival corporate gangs and reclaim your fortune.', 'Fight for power in Kouryuu no Mimi on Super Famicom.', 'Control Natsume Kiroemon in this stylish 16-bit brawler. Use your magical ear to gain power-ups and unleash devastating attacks against waves of urban thugs and bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kouryuuki (Japan)', '1992', NaN, 'Naxat Soft', '1', NaN, 'Historical strategy simulation set in ancient China.', 'Unify the warring states through diplomacy and conquest.', 'Master the art of war in Kouryuuki on the Super Famicom.', 'A deep Koei-style 16-bit strategy title. Manage your resources, recruit legendary generals, and engage in tactical grid-based battles to claim the imperial throne.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Koushien 2 (Japan)', '1992', NaN, 'Magical Company', '2', NaN, 'Realistic baseball simulation focusing on the high school tournament.', 'Lead your school team to victory at the legendary Koushien.', 'Play the authentic Koushien 2 on the Super Famicom.', 'Features a deep focus on team training and player development. A 16-bit sports sim that captures the intense drama of Japan''s most famous youth baseball event.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Koushien 3 (Japan)', '1994', NaN, 'Magical Company', '2', NaN, 'Sequel to the popular high school baseball simulation.', 'Master the 16-bit diamond and win the national championship.', 'Experience Koushien 3 on the Super Famicom.', 'Introduces updated player stats and improved fielding animations. Manage your roster''s stamina and morale to survive the grueling tournament structure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Koushien 4 (Japan)', '1996', NaN, 'Magical Company', '2', NaN, 'The final entry in the 16-bit Koushien baseball series.', 'Achieve glory at the stadium in this definitive sequel.', 'Play the polished Koushien 4 on the Super Famicom.', 'The most advanced 16-bit entry in the franchise. Features refined pitching mechanics, more detailed stadium crowds, and a comprehensive career mode for your players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kousoku Shikou - Shougi Ou (Japan)', '1995', NaN, 'Naxat Soft', '2', NaN, 'Traditional Shogi (Japanese Chess) simulation with high-speed AI.', 'Defeat the Shogi King through fast and strategic play.', 'Master Shogi in Kousoku Shikou on the Super Famicom.', 'Known for its rapid AI processing power. A technical 16-bit board game that offers a variety of difficulty levels and a helpful analysis mode for learning players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Koutetsu no Kishi (Japan)', '1994', NaN, 'Naxat Soft', '1', NaN, 'Tactical tank combat simulation set during World War II.', 'Lead your panzer division to victory across historical battles.', 'Command the armor in Koutetsu no Kishi on Super Famicom.', 'A detailed 16-bit simulation of tank warfare. Focuses on realistic ballistics, armor thickness, and tactical positioning across various European fronts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Koutetsu no Kishi 2 - Sabaku no Rommel Gundan (Japan)', '1995', NaN, 'Naxat Soft', '1', NaN, 'Tactical tank combat sequel set in the North African theater.', 'Master the desert dunes and outmaneuver Rommel''s forces.', 'Experience Koutetsu no Kishi 2 on the Super Famicom.', 'Shifts the 16-bit action to the African desert. Features new tank models and environmental hazards like sandstorms that affect visibility and movement.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Koutetsu no Kishi 3 - Gekitotsu Europe Sensen (Japan)', '1996', NaN, 'Naxat Soft', '1', NaN, 'The final installment focusing on the late-war European front.', 'Engage in the ultimate armored clash for the future of Europe.', 'Play Koutetsu no Kishi 3 on the Super Famicom.', 'The peak of the 16-bit tank sim series. Features the most advanced armor rosters and complex tactical scenarios, requiring deep knowledge of WWII machinery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Krusty''s Super Fun House (Europe)', '1992', NaN, 'Audiogenic', '2', NaN, 'Puzzle-platformer where you guide mice into traps to clear levels.', 'Help Krusty the Clown rid his fun house of a mouse infestation.', 'Solve the puzzles in Krusty''s Super Fun House on SNES.', 'Control Krusty as you manipulate the environment to lead mice to their doom. A clever 16-bit puzzler with a catchy soundtrack and appearances from Simpsons characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Krusty''s Super Fun House (Europe) (Rev A)', '1992', NaN, 'Audiogenic', '2', NaN, 'Puzzle-platformer with refined mechanics and bug fixes.', 'Clear the fun house in this updated 16-bit version.', 'Play the polished Krusty''s Super Fun House (Rev A).', 'An updated European revision that improves the 16-bit physics and fixes minor stage-glitches, providing a smoother puzzle-solving experience for fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Krusty''s Super Fun House (USA)', '1992', NaN, 'Audiogenic', '2', NaN, 'Puzzle-platformer where you guide mice into traps to clear levels.', 'Help Krusty the Clown rid his fun house of a mouse infestation.', 'Solve the puzzles in Krusty''s Super Fun House on SNES.', 'Navigate through increasingly complex 16-bit levels. Use blocks and stairs to guide the mice while avoiding hazards in this nostalgic licensed classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Krusty''s Super Fun House (USA) (Rev A)', '1992', NaN, 'Audiogenic', '2', NaN, 'Puzzle-platformer with refined mechanics and bug fixes.', 'Clear the fun house in this updated 16-bit version.', 'Play the polished Krusty''s Super Fun House (Rev A) on SNES.', 'The final North American 16-bit revision. Features optimized code for better performance during the game''s more crowded and complex puzzle stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Krusty''s World (Japan)', '1994', NaN, 'Acclaim', '2', NaN, 'Puzzle-platformer where you guide mice into traps to clear levels.', 'Experience the Japanese version of Krusty''s puzzle challenge.', 'Play Krusty''s World on the Super Famicom.', 'The Japanese release of Krusty''s Super Fun House. Features the same addictive 16-bit logic puzzles and colorful graphics that made the game a global hit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kunio no Oden (Japan)', '1994', NaN, 'Technos Japan', '2', NaN, 'Unique puzzle-action game based on the Kunio-kun series.', 'Match Oden ingredients to clear the board and defeat rivals.', 'Solve the tasty Kunio no Oden on the Super Famicom.', 'A Puyo Puyo style 16-bit puzzler with a Japanese twist. Play as Kunio and match various food items to send garbage blocks to your opponent''s screen.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kunio-kun no Dodge Ball dayo Zenin Shuugou! - Tournament Special (Japan)', '1993', NaN, 'Technos Japan', '4', NaN, 'Enhanced dodgeball tournament simulation featuring the Kunio cast.', 'Win the world dodgeball championship using special shots.', 'Hit the court in Kunio''s Dodge Ball: Tournament Special.', 'A high-energy 16-bit sports game. Features flashy special attacks, customizable team stats, and the iconic super-deformed art style of the franchise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kunio-kun no Dodge Ball dayo Zenin Shuugou! (Japan)', '1993', NaN, 'Technos Japan', '4', NaN, 'Fast-paced arcade dodgeball game for up to four players.', 'Eliminate the opposing team with powerful throws and jumps.', 'Experience Kunio-kun no Dodge Ball on the Super Famicom.', 'The definitive 16-bit dodgeball experience. Features diverse stages with environmental hazards and a huge variety of super shots that defy the laws of physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kunio-kun no Dodge Ball dayo Zenin Shuugou! (Japan) [En by Azelistic v1.0] (~Kunio''s Dodge Ball)', '1993', NaN, 'Technos Japan', '4', NaN, 'Fast-paced arcade dodgeball game with a full English translation.', 'Play the ultimate dodgeball tournament with English text.', 'Play Kunio''s Dodge Ball in English on the Super Nintendo.', 'The Azelistic translation makes the team management and special move names accessible. Experience the best 16-bit dodgeball action in your own language.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kuusou Kagaku Sekai Gulliver Boy (Japan)', '1995', NaN, 'Bandai', '1', NaN, 'Hybrid Action-RPG and adventure based on the sci-fi anime.', 'Travel the world and stop the evil empire as Gulliver.', 'Join the epic Gulliver Boy on the Super Famicom.', 'A visually impressive 16-bit RPG. Combines top-down exploration with cinematic combat sequences and a humorous, fast-paced story inspired by the hit series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kuusou Kagaku Sekai Gulliver Boy (Japan) [En by Stealth v0.99]', '1995', NaN, 'Bandai', '1', NaN, 'Hybrid Action-RPG and adventure with an English fan translation.', 'Experience Gulliver''s steampunk adventure with English text.', 'Play Gulliver Boy in English on the Super Nintendo.', 'The Stealth translation allows you to enjoy the witty dialogue and complex sci-fi plot of this late-gen 16-bit masterpiece. A must-play for JRPG fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kyle Petty''s No Fear Racing (USA)', '1995', NaN, 'Video System', '1', NaN, 'Pseudo-3D racing game featuring stock cars and Mode 7.', 'Win the NASCAR championship with Kyle Petty''s guidance.', 'Experience high-speed action in Kyle Petty''s No Fear Racing.', 'A technical 16-bit racer that uses Mode 7 for smooth track rotation. Features a unique car damage system and varied tracks that require precise driving to master the stock car circuit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kyuuyaku Megami Tensei (Eng v1.1)', '1995', NaN, 'Atlus', '1', NaN, 'Remake of the first two Shin Megami Tensei games in English.', 'Survive the demon apocalypse with a full English translation.', 'Play Kyuuyaku Megami Tensei in English on the SNES.', 'Experience the origins of the Megaten series. This 16-bit remake features improved graphics and sound, allowing you to recruit and fuse demons in English for the first time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Kyuuyaku Megami Tensei (Japan)', '1995', NaN, 'Atlus', '1', NaN, 'Remake of the first two Shin Megami Tensei games with updated tech.', 'Recruit demons and save humanity in the original Japanese version.', 'Discover Kyuuyaku Megami Tensei on the Super Famicom.', 'A comprehensive 16-bit compilation of the Famicom classics. Features atmospheric dungeon crawling, a complex demon fusion system, and the dark narrative that defined the franchise.', NULL);
