INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lagoon (Japan)', '1991', NaN, 'Kemco', '1', NaN, 'Action-RPG with a focus on real-time combat and exploration.', 'Defeat the evil Zemer in the original Japanese version.', 'Experience the original Lagoon on the Super Famicom.', 'The foundational 16-bit release. Features impressive boss sprites and an iconic soundtrack that sets the tone for this difficult but rewarding RPG quest.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lagoon (USA)', '1991', NaN, 'Kemco', '1', NaN, 'Action-RPG with a focus on real-time combat and exploration.', 'Defeat the evil Zemer and restore the light to Lagoon.', 'Embark on the quest of Lagoon for the Super Nintendo.', 'Master the short-sword combat and magic system. A nostalgic 16-bit RPG that tests your reflexes and your ability to navigate complex maze-like environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lamborghini - American Challenge (Europe)', '1993', NaN, 'Titus', '2', NaN, 'High-speed arcade racer featuring licensed Lamborghini cars.', 'Win illegal street races across the USA to buy better cars.', 'Race for glory in Lamborghini American Challenge on SNES.', 'A 16-bit racing classic. Use your earnings to upgrade your Diablo, bet on races, and avoid the police in this fast-paced and stylish arcade simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lamborghini - American Challenge (USA)', '1993', NaN, 'Titus', '2', NaN, 'High-speed arcade racer featuring licensed Lamborghini cars.', 'Win illegal street races across the USA to buy better cars.', 'Race for glory in Lamborghini American Challenge on SNES.', 'Features smooth Mode 7 scaling and intense 2-player split-screen action. Master the curves and nitro boosts to become the king of the American streets.', NULL);
