INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Langrisser, Der (Japan) (Rev A)', '1991', NaN, 'NCS', '1', NaN, 'Tactical turn-based JRPG with a focus on branching paths.', 'Lead the army to victory in this refined revision.', 'Play the polished Der Langrisser (Rev A) on SNES.', 'The updated 16-bit Japanese revision featuring minor balance tweaks to unit stats and bug fixes for a smoother tactical experience.', NULL);
