INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Larry Nixon''s Super Bass Fishing (Japan)', '1994', NaN, 'Konami', '1', NaN, 'Realistic bass fishing simulation featuring Larry Nixon.', 'Win professional tournaments by mastering lure and location.', 'Go pro in Larry Nixon''s Super Bass Fishing on SNES.', 'Features a detailed 16-bit underwater view and realistic fish behavior. Navigate your boat and use Nixon''s expert advice to land the biggest bass.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Las Vegas Dream in Golden Paradise (Japan)', '1995', NaN, 'Human', '1', NaN, 'Casino simulation featuring a variety of Las Vegas games.', 'Build your fortune and live the high life in a virtual casino.', 'Bet big in Las Vegas Dream on the Super Famicom.', 'Features 16-bit versions of Blackjack, Slots, and Roulette. Includes a story mode where you manage your wealth and interact with diverse casino characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Laser Suit Powerup V1.7', '—', NaN, '—', '1', NaN, 'Fan-made gameplay modification for Metroid.', 'Explore a modified world with enhanced beam power-ups.', 'Play the Laser Suit Powerup mod for the SNES.', 'A creative 16-bit romhack that alters Samus''s suit and weaponry. Experience new combat dynamics and visual effects in a familiar yet revamped environment.', NULL);
