INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Last Battle, The (Japan)', '1989', NaN, 'Namco', '1', NaN, 'Action-platformer based on the dark fantasy world of Kenpuryu.', 'Defeat the demonic lords and save the kingdom.', 'Discover The Last Battle on the Super Famicom.', 'Known for its gritty atmosphere and large 16-bit sprites. Master your combat skills and explore a dark world filled with formidable enemies and challenging puzzles.', NULL);
