INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Last Bible III (Japan)', '1995', NaN, 'Atlus', '1', NaN, 'Turn-based RPG from the Megami Tensei Gaiden series.', 'Recruit monsters and save the world in the original Japanese version.', 'Experience Last Bible III on the Super Famicom.', 'A late-gen 16-bit JRPG masterpiece. Features beautiful pixel art, an emotional soundtrack, and the trademark demon-negotiation mechanics of the Megaten franchise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lawnmower Man, The (Europe)', '1994', NaN, 'Virgin Interactive', '1', NaN, 'Cyberpunk action-adventure based on the 1992 film.', 'Navigate Virtual Reality and stop the Lawnmower Man.', 'Enter the system in The Lawnmower Man for the SNES.', 'Features a mix of side-scrolling platforming and early 3D-style flying segments. Experience the 16-bit interpretation of cyberspace in this unique movie tie-in.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lawnmower Man, The (USA)', '1994', NaN, 'Virgin Interactive', '1', NaN, 'Cyberpunk action-adventure based on the 1992 film.', 'Navigate Virtual Reality and stop the Lawnmower Man.', 'Enter the system in The Lawnmower Man for the SNES.', 'Master the 16-bit puzzles and high-speed tunnel sequences. A visually ambitious title that pushed the SNES''s scaling and rotation capabilities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lawnmower Man, The (USA) (Beta)', '1994', NaN, 'Virgin Interactive', '1', NaN, 'Cyberpunk action-adventure based on the 1992 film.', 'Test early level designs and VR flight mechanics.', 'Check out The Lawnmower Man (Beta) on the SNES.', 'A pre-release 16-bit development build. Witness the fine-tuning of the pseudo-3D segments and the evolution of the cyberpunk environments before the final launch.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Leading Company (Japan)', '1992', NaN, 'Koei', '1', NaN, 'Business management simulation about running a tech corporation.', 'Build a global electronics empire and bankrupt your rivals.', 'Master the market in Leading Company on Super Famicom.', 'A deep 16-bit strategy game from Koei. Manage R&D, marketing, and manufacturing to stay ahead in the competitive world of technology.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Leading Jockey (Japan)', '1993', NaN, 'Koei', '1', NaN, 'Professional horse racing simulation and jockey career mode.', 'Climb the ranks and win the G1 races as a pro jockey.', 'Experience Leading Jockey on the Super Famicom.', 'Focuses on the skill of riding rather than just betting. Master 16-bit stamina management and positioning to lead your horse to the finish line.', NULL);
