INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Legend (Europe)', '1994', NaN, 'Arc Developments', '2', NaN, 'Fantasy side-scrolling beat ''em up with a gritty medieval tone.', 'Defeat the evil sorcerer and reclaim the magical amulet.', 'Fight through the darkness in Legend for the SNES.', 'Features large, detailed 16-bit sprites and heavy-hitting combat. A cult classic brawler with an atmospheric soundtrack and challenging boss fights.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Legend (USA)', '1994', NaN, 'Arc Developments', '2', NaN, 'Fantasy side-scrolling beat ''em up with a gritty medieval tone.', 'Defeat the evil sorcerer and reclaim the magical amulet.', 'Fight through the darkness in Legend for the SNES.', 'Master your sword skills in this 16-bit medieval epic. Navigate through forests and castles to bring peace to the kingdom of Selece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Legend (USA) (Beta)', '1994', NaN, 'Arc Developments', '2', NaN, 'Fantasy side-scrolling beat ''em up with a gritty medieval tone.', 'Test early combat physics and enemy AI in this prototype.', 'Check out the Legend (Beta) version on the SNES.', 'A rare 16-bit development build. Discover initial character movesets and environmental details for this atmospheric medieval brawler.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Legend of Axem Rangers', '1997', NaN, 'Fans', '2', NaN, 'Fan-made total conversion of Super Mario World.', 'Explore a new world inspired by the Axem Rangers.', 'Play Legend of Axem Rangers on the Super Nintendo.', 'A creative 16-bit romhack featuring new levels, custom music, and a unique story centered around the colorful villain team from Super Mario RPG.', NULL);
