INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Legend of the Mystical Ninja, The (Germany)', '1991', NaN, 'Konami', '2', NaN, 'Action-adventure platformer set in a wacky version of feudal Japan.', 'Rescue the Princess in the localized German version.', 'Spielen Sie Mystical Ninja auf Deutsch für das SNES.', 'The complete 16-bit adventure with localized German text. Experience the charm, the weirdness, and the incredible music of the Goemon series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Legend of the Mystical Ninja, The (USA)', '1991', NaN, 'Konami', '2', NaN, 'Action-adventure platformer set in a wacky version of feudal Japan.', 'Rescue the Princess and stop the Oedo Clan with Kid Goemon.', 'Experience Legend of the Mystical Ninja on SNES.', 'Master the pipe and shuriken attacks. A foundational 16-bit title that perfectly blends platforming, exploration, and RPG elements.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lemmings (Europe)', '1991', NaN, 'Psygnosis', '2', NaN, 'Puzzle-strategy game where you guide green-haired creatures to safety.', 'Save the required number of Lemmings by assigning them tasks.', 'Master the puzzles in Lemmings for the Super Nintendo.', 'A perfect 16-bit port of the PC classic. Use climbers, floaters, and blockers to navigate through increasingly lethal environments filled with traps and pits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lemmings (Japan)', '1991', NaN, 'Psygnosis', '2', NaN, 'Puzzle-strategy game where you guide green-haired creatures to safety.', 'Guide the Lemmings to the exit in the original Japanese version.', 'Play Lemmings on the Super Famicom for brain-teasing fun.', 'Features the same addictive 16-bit logic puzzles and iconic music. A true test of planning and quick thinking across hundreds of levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lemmings (USA)', '1991', NaN, 'Psygnosis', '2', NaN, 'Puzzle-strategy game where you guide green-haired creatures to safety.', 'Save the required number of Lemmings by assigning them tasks.', 'Master the puzzles in Lemmings for the Super Nintendo.', 'Assign roles like builders and diggers in real-time. This 16-bit version offers smooth cursor controls and a password system for its massive campaign.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lemmings (USA) (Rev A)', '1991', NaN, 'Psygnosis', '2', NaN, 'Puzzle-strategy game with refined controls and minor bug fixes.', 'Guide the Lemmings to safety in this updated revision.', 'Play the polished Lemmings (Rev A) on the SNES.', 'An updated 16-bit revision that fixes minor level-glitches and optimizes performance for a smoother experience during complex puzzle solutions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lemmings 2 - The Tribes (Europe)', '1993', NaN, 'Psygnosis', '2', NaN, 'Expanded puzzle-strategy sequel featuring 12 distinct tribes.', 'Save the Lemmings across diverse themed worlds like Egyptian and Space.', 'Experience Lemmings 2: The Tribes on the SNES.', 'Features way more skills than the original. Master the 16-bit mechanics of the Archer, Roper, and Hang Glider tribes in this ambitious and colorful sequel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lemmings 2 - The Tribes (Japan)', '1993', NaN, 'Psygnosis', '2', NaN, 'Expanded puzzle-strategy sequel featuring 12 distinct tribes.', 'Guide the tribes to safety in the original Japanese version.', 'Play Lemmings 2: The Tribes on the Super Famicom.', 'The 16-bit Japanese release featuring unique tribe animations and more complex environmental puzzles that require creative use of the new skill sets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lemmings 2 - The Tribes (USA)', '1993', NaN, 'Psygnosis', '2', NaN, 'Expanded puzzle-strategy sequel featuring 12 distinct tribes.', 'Save the Lemmings across diverse themed worlds like Egyptian and Space.', 'Experience Lemmings 2: The Tribes on the SNES.', 'A massive 16-bit expansion of the formula. Each tribe has its own unique music and aesthetic, offering a fresh take on the classic puzzle-strategy gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lennus - Kodai Kikai no Kioku (Japan)', '1992', NaN, 'Asmik', '1', NaN, 'Turn-based RPG set on the alien planet of Raika.', 'Stop the ancient machine Lennus from destroying the world.', 'Explore the alien Lennus on the Super Famicom.', 'Known as Paladin''s Quest in the West. Features a unique 16-bit pastel art style and a health-based magic system where spells cost HP instead of MP.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lennus II - Fuuin no Shito (Japan)', '1994', NaN, 'Asmik', '1', NaN, 'Ambitious RPG sequel with improved graphics and world-building.', 'Gather the apostles and prevent the world''s destruction.', 'Play the legendary Lennus II on the Super Famicom.', 'One of the most visually striking 16-bit JRPGs. Features a massive world, a refined combat system, and a soundtrack that perfectly captures its alien atmosphere.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lennus II - Fuuin no Shito (Japan) [En by Magic Destiny+Stealth v1.04] (~Lennus II - The Apostles of the Seals)', '1994', NaN, 'Asmik', '1', NaN, 'Ambitious RPG sequel with a full English fan translation.', 'Experience the epic Lennus saga with English text.', 'Play Lennus II in English on the Super Nintendo.', 'The Magic Destiny translation makes this late-gen 16-bit masterpiece fully playable. Explore the bizarre world of Raika and solve the mystery of the Seals.', NULL);
