INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lethal Enforcers (USA)', '1993', NaN, 'Konami', '2', NaN, 'Light-gun arcade shooter set in a gritty urban environment.', 'Eliminate the bank robbers and crime syndicates as a police officer.', 'Take aim in Lethal Enforcers for the Super Nintendo.', 'Master your reload speed and accuracy. A high-stakes 16-bit shooter that rewards quick reflexes and precise aiming with the Justifier peripheral.', NULL);
