INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lethal Weapon (USA)', '1992', NaN, 'Ocean', '1', NaN, 'Side-scrolling action-platformer based on the hit movie series.', 'Stop the criminal cartel as Riggs and Murtaugh.', 'Fight for justice in Lethal Weapon for the SNES.', 'Features digitized character art and a variety of mission objectives. A gritty 16-bit licensed game that captures the buddy cop energy of the movies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Libble Rabble (Japan)', '1989', NaN, 'Namco', '2', NaN, 'Unique puzzle-action game involving a wrapping mechanic.', 'Trap enemies and clear the board by surrounding them with your line.', 'Play the quirky Libble Rabble on the Super Famicom.', 'Created by the designer of Pac-Man. Features a unique 16-bit dual-cursor control scheme where you wrap lines around pegs to capture items and find treasure.', NULL);
