INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Little Magic (Europe) (Proto)', '1993', NaN, 'Altron', '1', NaN, 'Puzzle-adventure game with a focus on magical mechanics (Prototype).', 'Guide the protagonist through a series of environmental puzzles.', 'Check out the Little Magic Prototype for the SNES.', 'A rare look at the European version that never was. Features 16-bit magic-based puzzles where you move objects to reach the exit.', NULL);
