INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Little Master - Nijiiro no Maseki (Japan)', '1994', NaN, 'Tokai Engineering', '1', NaN, 'Tactical turn-based RPG with chibi character designs.', 'Lead the young knight on a quest to recover the magical gems.', 'Play Little Master: Nijiiro no Maseki on Super Famicom.', 'The third entry in the series and the first on 16-bit. Features beautiful pixel art, strategic grid-based combat, and a heartwarming fantasy story.', NULL);
