INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lobo (USA) (Proto)', '1996', NaN, 'Ocean', '1', NaN, 'One-on-one fighting game based on the DC Comics anti-hero.', 'Win the intergalactic tournament as the Main Man.', 'Check out the unreleased Lobo Proto for the SNES.', 'A rare 16-bit prototype. Features the cigar-chomping bounty hunter in a gritty fighter with massive sprites and over-the-top special moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lock On (USA)', '1994', NaN, 'Vic Tokai', '1', NaN, 'Pseudo-3D flight combat simulation using Mode 7.', 'Engage in aerial dogfights and destroy ground targets.', 'Take to the skies in Lock On for the Super Nintendo.', 'Known as Super Air Infernos. Features intense 16-bit cockpit-view combat. Use missiles and cannons to complete missions across diverse 3D-scaling environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lode Runner Twin - Justy to Liberty no Daibouken (Japan)', '1994', NaN, 'Irem', '2', NaN, 'Puzzle-platformer with co-op focus and level editing.', 'Collect all the gold and find the exit without getting caught.', 'Experience Lode Runner Twin on the Super Famicom.', 'A vibrant 16-bit update to the classic formula. Features two-player cooperative play, colorful new environments, and a deep level editor to create your own puzzles.', NULL);
