INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Logos Panic Goaisatsu (Japan)', '1993', NaN, 'Teichiku', '2', NaN, 'Unique word-based puzzle game with a Japanese aesthetic.', 'Link characters and words together to clear the board.', 'Solve the unique Logos Panic on the Super Famicom.', 'A rare 16-bit linguistic puzzler. Challenge your knowledge of Japanese characters and logic in a series of increasingly difficult word-matching stages.', NULL);
