INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Looney Tunes Basketball (Europe)', '1995', NaN, 'Konami', '4', NaN, 'Arcade-style 2-on-2 basketball featuring Looney Tunes characters.', 'Win the tournament in the localized European version.', 'Experience Looney Tunes Basketball on the SNES.', 'The European release of the cartoon sports hit. Features the same addictive 16-bit gameplay, colorful animations, and hilarious character-specific special shots.', NULL);
