INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lost Vikings II, The (Europe) (En,Fr,De)', '1997', NaN, 'Blizzard', '2', NaN, 'Puzzle-platformer sequel with three new viking abilities.', 'Guide the vikings back home through time and space.', 'Play The Lost Vikings II for the Super Nintendo.', 'Erik, Olaf, and Baleog return with 16-bit cybernetic upgrades. Features complex cooperative puzzles that require switching between all three characters to survive.', NULL);
