INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lost Vikings, The (Germany)', '1993', NaN, 'Blizzard', '2', NaN, 'Cooperative puzzle-platformer with localized German text.', 'Guide the vikings to safety in the German version.', 'Spielen Sie The Lost Vikings auf Deutsch für das SNES.', 'The complete 16-bit puzzle-adventure with localized German text. Solve complex logic puzzles using the unique skills of Erik, Baleog, and Olaf.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lost Vikings, The (Spain)', '1993', NaN, 'Blizzard', '2', NaN, 'Cooperative puzzle-platformer with localized Spanish text.', 'Guide the vikings to safety in the Spanish version.', 'Juega a The Lost Vikings en español para el SNES.', 'The complete 16-bit puzzle-adventure with localized Spanish text. One of the most creative and beloved strategy-platformers on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lost Vikings, The (USA)', '1993', NaN, 'Blizzard', '2', NaN, 'Cooperative puzzle-platformer featuring three unique vikings.', 'Use teamwork to navigate dangerous worlds and return home.', 'Join the adventure in The Lost Vikings for the SNES.', 'Master the 16-bit cooperation mechanics. Each level is a complex logic puzzle that tests your ability to coordinate Baleog''s combat, Olaf''s defense, and Erik''s speed.', NULL);
