INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Lothar Matthaus Super Soccer (Germany)', '1994', NaN, 'Capcom', '2', NaN, 'Realistic soccer simulation endorsed by the German legend.', 'Win the international cup in this specialized German sim.', 'Kick off in Lothar Matthaus Super Soccer for SNES.', 'Features deep 16-bit management options and a simulation-focused match engine. Play as or against the famous German captain in various tournament modes.', NULL);
