INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Magic Boy (Europe)', '1993', NaN, 'Naxat Soft', '2', NaN, 'Side-scrolling platformer featuring a young wizard.', 'Clean up the world by capturing monsters in your magic bag.', 'Join the quest in Magic Boy for the Super Nintendo.', 'A colorful 16-bit platformer. Use your magic to shrink enemies and trap them. Travel through diverse worlds, from the sea to the desert, in this polished adventure.', NULL);
