INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Magic Johnson no Super Slam Dunk (Japan)', '1994', NaN, 'NAMCO', '2', NaN, 'Professional basketball simulation featuring Magic Johnson.', 'Win the world championship with expert coaching and play.', 'Experience Super Slam Dunk on the Super Famicom.', 'Features 16-bit Mode 7 court rotation and large, digitized player sprites. A technical sports title that focuses on the fundamentals of professional basketball.', NULL);
