INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Megaman X3 (USA)', '1995', NaN, 'Capcom', '1', NaN, 'Side-scrolling action-platformer and final 16-bit X entry.', 'Defeat the Doppler army and stop Sigma''s viral evolution.', 'Play Mega Man X3 for the Super Nintendo.', 'Master the chip upgrades and the Z-Saber. A deep 16-bit action-adventure that offers the most customization and secret content in the SNES trilogy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Megaman''s Soccer (USA)', '1994', NaN, 'Capcom', '4', NaN, 'Sports-action hybrid featuring characters from the Mega Man series.', 'Win the soccer tournament using special character shots.', 'Kick off in Mega Man''s Soccer for the SNES.', 'A wacky 16-bit sports title. Assemble a team of Robot Masters like Wood Man or Fire Man and use their signature weapons as special soccer moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Melfand Stories (Japan)', '1994', NaN, 'Sting', '1', NaN, 'Side-scrolling beat ''em up with a fantasy setting and multiple paths.', 'Navigate the kingdom and stop the evil uprising as a hero duo.', 'Discover the vibrant Melfand Stories on Super Famicom.', 'A charming 16-bit brawler. Choose from four different characters and enjoy branching paths, beautiful pixel art, and a lighthearted tone rare for the genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Combat - Falcon''s Revenge (Europe)', '1994', NaN, 'Intelligent Systems', '1', NaN, 'First-person mecha light-gun shooter and sequel to Battle Clash.', 'Pilot the Falcon and defeat the battle-suit champions.', 'Take aim in Metal Combat: Falcon''s Revenge on SNES.', 'A 16-bit masterpiece for the Super Scope. Features massive, detailed mechs and a deep tactical shooting system where you target specific weak points on enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Combat - Falcon''s Revenge (USA)', '1994', NaN, 'Intelligent Systems', '1', NaN, 'First-person mecha light-gun shooter and sequel to Battle Clash.', 'Pilot the Falcon and defeat the battle-suit champions.', 'Take aim in Metal Combat: Falcon''s Revenge on SNES.', 'The pinnacle of 16-bit light-gun gaming. Experience intense mecha duels with destructible parts and a cinematic sci-fi story that expands the Battle Clash lore.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Marines (Europe)', '1993', NaN, 'Namco', '1', NaN, 'Real-time strategy game with a focus on base building and defense.', 'Conquer the island chains and destroy the enemy commander.', 'Master strategy in Metal Marines for the SNES.', 'A unique 16-bit RTS. Manage resources to build missile silos and giant robots while defending your base in split-screen tactical warfare.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Marines (USA)', '1993', NaN, 'Namco', '1', NaN, 'Real-time strategy game with a focus on base building and defense.', 'Conquer the island chains and destroy the enemy commander.', 'Master strategy in Metal Marines for the SNES.', 'Features intense 16-bit tactical gameplay. Launch devastating ICBMs and deploy your Metal Marines to seize enemy territory in this high-stakes military sim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Max 2 (Japan)', '1993', NaN, 'Data East', '1', NaN, 'Open-world turn-based RPG in a post-apocalyptic wasteland.', 'Hunt outlaws and customize your tanks to survive the desert.', 'Explore the gritty Metal Max 2 on the Super Famicom.', 'A 16-bit cult classic. Features a non-linear world where you can spend hours customizing your tanks'' engines, cannons, and armor to survive the harsh outlands.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Max Returns (Japan)', '1995', NaN, 'Data East', '1', NaN, 'Remake of the original Famicom RPG with 16-bit technology.', 'Travel the wasteland and become the world''s greatest hunter.', 'Discover Metal Max Returns on the Super Famicom.', 'A massive 16-bit graphical and mechanical overhaul. Features a deep tank-customization system and a quirky, open-ended world filled with bizarre enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Max Returns (Japan) [En by Aeon Genesis v1.0]', '1995', NaN, 'Data East', '1', NaN, 'Remake of the original Famicom RPG with a full English translation.', 'Experience the post-apocalyptic tank RPG with English text.', 'Play Metal Max Returns in English on the SNES.', 'The Aeon Genesis translation makes this 16-bit gem accessible. Hunt bounty targets and build the ultimate garage of tanks in a world that feels like a 16-bit Fallout.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Morph (USA)', '1993', NaN, 'Origin Systems', '1', NaN, 'Side-scrolling action game with mecha-morphing mechanics.', 'Infiltrate the enemy base and transform your suit to adapt.', 'Fight through the levels of Metal Morph on the SNES.', 'A 16-bit action title where you switch between a humanoid walker and a jet-like flyer. Navigate through industrial stages and engage in challenging boss fights.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Slader Glory - Director''s Cut (Japan) (NP)', '2000', NaN, 'HAL Laboratory', '1', NaN, 'Cinematic visual novel and adventure game (Director''s Cut).', 'Solve the space mystery and stop the mechanical threat.', 'Experience Metal Slader Glory on the Super Famicom.', 'Originally an NP (Nintendo Power) flash release. Features some of the best 16-bit pixel art ever created, with cinematic cutscenes and a deep sci-fi narrative.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Metal Warriors (USA)', '1995', NaN, 'LucasArts', '2', NaN, 'Side-scrolling mecha action-platformer with pilot-ejection.', 'Lead the resistance and pilot various mechs in a civil war.', 'Master the mechs in Metal Warriors for the SNES.', 'A 16-bit masterpiece by LucasArts. Eject from your mech to hijack others, master 6 different robot types, and enjoy one of the best multiplayer modes on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Michael Andretti''s IndyCar Challenge (Japan)', '1994', NaN, 'Papyrus Design Group', '1', NaN, 'Mode 7-based open-wheel racing simulation.', 'Win the IndyCar championship across diverse international tracks.', 'Race to the finish in Michael Andretti''s IndyCar Challenge.', 'A technical 16-bit racer that utilizes the SNES''s rotation effects for a smooth cockpit view. Features real-world tracks and professional tuning options for your car.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Michael Andretti''s IndyCar Challenge (USA)', '1994', NaN, 'Papyrus Design Group', '1', NaN, 'Mode 7-based open-wheel racing simulation.', 'Climb the standings and win the season as Michael Andretti.', 'Master the track in Michael Andretti''s IndyCar Challenge.', 'Features a high-speed frame rate and a unique spotter voice system. A realistic 16-bit simulation of professional IndyCar racing with challenging AI and pit-stop strategy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Michael Jordan - Chaos in the Windy City (Europe)', '1994', NaN, 'Beam Software', '1', NaN, 'Side-scrolling action-platformer starring the NBA legend.', 'Rescue your teammates from a subterranean prison using basketballs.', 'Join the action in Michael Jordan: Chaos in the Windy City.', 'Control Jordan in a 16-bit adventure where you use various power-up basketballs (ice, fire, bomb) to defeat enemies and solve environmental puzzles in Chicago.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Michael Jordan - Chaos in the Windy City (USA)', '1994', NaN, 'Beam Software', '1', NaN, 'Side-scrolling action-platformer starring the NBA legend.', 'Rescue your teammates from a subterranean prison using basketballs.', 'Join the action in Michael Jordan: Chaos in the Windy City.', 'Features smooth animations and a massive amount of secret rooms. A creative 16-bit licensed title that blends sports themes with traditional platforming action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mick & Mack as the Global Gladiators (USA) (Proto) [1829]', '1992', NaN, 'Virgin Interactive', '2', NaN, 'Action-platformer with an environmental message (Prototype).', 'Navigate a world of pollution and defeat the toxic slime monsters.', 'Check out the Global Gladiators Prototype on the SNES.', 'A rare 16-bit development build of the McDonald''s licensed game. Features fluid animations and projectile-based combat in a vibrant, message-driven world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mick & Mack as the Global Gladiators (USA) (Proto) [71AB]', '1992', NaN, 'Virgin Interactive', '2', NaN, 'Action-platformer with an environmental message (Prototype).', 'Test early level layouts and sprite physics in this beta build.', 'Explore the Global Gladiators (71AB) Proto on the SNES.', 'An early look at the 16-bit platformer''s development. Witness the fine-tuning of the Goo weapon and the evolution of the slime-filled environmental stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey Mania - The Timeless Adventures of Mickey Mouse (Europe)', '1994', NaN, 'Traveller''s Tales', '1', NaN, 'Cinematic platformer celebrating Mickey''s animation history.', 'Journey through Mickey''s most famous cartoons to defeat Pete.', 'Play the stunning Mickey Mania for the Super Nintendo.', 'A visual masterpiece. Levels are based on Steamboat Willie, The Lonesome Ghosts, and more. Features 16-bit graphics that look like actual hand-drawn cells.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey Mania - The Timeless Adventures of Mickey Mouse (Japan)', '1994', NaN, 'Traveller''s Tales', '1', NaN, 'Cinematic platformer celebrating Mickey''s animation history.', 'Relive Mickey''s classic cartoons in the Japanese version.', 'Experience Mickey Mania on the Super Famicom.', 'The original 16-bit Japanese release. Known for its incredible attention to detail, rotoscoped animations, and challenging levels that replicate the history of Disney.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey Mania - The Timeless Adventures of Mickey Mouse (USA)', '1994', NaN, 'Traveller''s Tales', '1', NaN, 'Cinematic platformer celebrating Mickey''s animation history.', 'Journey through Mickey''s most famous cartoons to defeat Pete.', 'Play the stunning Mickey Mania for the Super Nintendo.', 'Master the 16-bit platforming in The Mad Doctor and The Prince and the Pauper. A nostalgic and technically impressive tribute to the world''s most famous mouse.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey no Magical Adventure (Japan)', '1992', NaN, 'Capcom', '1', NaN, 'Disney platformer featuring an iconic costume-change mechanic.', 'Rescue Pluto and defeat Emperor Pete in the Japanese version.', 'Play Mickey no Magical Adventure on the Super Famicom.', 'The original release of the Capcom classic. Switch between a wizard, fireman, and mountain climber to use 16-bit magical powers and navigate vibrant stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey no Magical Adventure (Japan) (Rev A)', '1992', NaN, 'Capcom', '1', NaN, 'Disney platformer featuring an iconic costume-change mechanic.', 'Save Pluto in this refined Japanese revision.', 'Play the polished Magical Adventure (Rev A) on SNES.', 'An updated 16-bit revision that fixes minor hit-detection bugs and optimizes the costume-switching speed for a more fluid gameplay experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey no Tokyo Disneyland Daibouken (English)', '1994', NaN, 'Capcom', '1', NaN, 'Side-scrolling platformer set in the famous theme park.', 'Explore Tokyo Disneyland and stop Pete''s disruptive scheme.', 'Play Mickey no Tokyo Disneyland Daibouken in English.', 'A fan-translated 16-bit gem. Use a unique balloon mechanic to float, attack, and solve puzzles across meticulously recreated park attractions like Space Mountain.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey no Tokyo Disneyland Daibouken (Japan)', '1994', NaN, 'Capcom', '1', NaN, 'Side-scrolling platformer set in the famous theme park.', 'Navigate through the attractions of Tokyo Disneyland.', 'Experience Mickey no Tokyo Disneyland Daibouken on SNES.', 'A Japan-exclusive 16-bit title with incredible graphics. Use water and gas balloons to traverse levels based on real Disney park locations.', NULL);
