INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey to Minnie - Magical Adventure 2 (Japan)', '1994', NaN, 'Capcom', '2', NaN, 'Cooperative action-platformer featuring Mickey and Minnie.', 'Rescue the children and stop the Great Circus mystery.', 'Play Mickey to Minnie: Magical Adventure 2 on SNES.', 'Known as The Great Circus Mystery in the West. A beautiful 16-bit title featuring 2-player co-op and costumes like the Sweeper and the Safari outfit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey''s Playtown Adventure - A Day of Discovery! (USA) (Proto)', '1994', NaN, 'Disney Interactive', '1', NaN, 'Educational adventure for young children (Prototype).', 'Explore the town and complete simple tasks with Mickey and friends.', 'Check out Mickey''s Playtown Adventure Proto on SNES.', 'A rare 16-bit educational title that was never officially released. Features colorful graphics and mini-games designed to teach basic logic and coordination.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mickey''s Ultimate Challenge (USA)', '1994', NaN, 'Disney Interactive', '1', NaN, 'Puzzle-adventure game featuring various logic challenges.', 'Win the tournament of the castle by solving all the puzzles.', 'Challenge your mind in Mickey''s Ultimate Challenge on SNES.', 'A 16-bit collection of brain-teasers, memory games, and sliding puzzles. Perfect for younger players looking for a non-violent Disney adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Micro Machines (Europe)', '1993', NaN, 'Codemasters', '2', NaN, 'Top-down arcade racer with miniature vehicles.', 'Win the desk-top and garden races in this European hit.', 'Race the tiny cars in Micro Machines for the SNES.', 'A 16-bit classic featuring diverse tracks like breakfast tables and pool tables. Master the handling of tanks, sports cars, and boats in fast-paced matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Micro Machines (USA)', '1993', NaN, 'Codemasters', '2', NaN, 'Top-down arcade racer with miniature vehicles.', 'Outrun your rivals and stay on the screen to win.', 'Play the addictive Micro Machines on the Super Nintendo.', 'Features incredible 16-bit couch multiplayer action. Choose from a roster of quirky characters and survive the household hazards in every race.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Micro Machines 2 - Turbo Tournament (Europe)', '1994', NaN, 'Codemasters', '4', NaN, 'Expanded top-down racer sequel with more vehicles and tracks.', 'Win the Turbo Tournament and claim the miniature trophy.', 'Experience Micro Machines 2 for the Super Nintendo.', 'Features updated 16-bit physics and a massive roster of new vehicles, including hovercrafts and monster trucks. A peak multiplayer experience on the system.', NULL);
