INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mighty Max (Europe)', '1994', NaN, 'WJS Design', '1', NaN, 'Action-platformer based on the popular toy line and cartoon.', 'Defeat Skullmaster by traveling through magical portals.', 'Join the hunt in Mighty Max for the Super Nintendo.', 'Control Max in a 16-bit adventure across diverse dimensions. Use gadgets and help from Norman and Virgil to stop the ultimate evil.', NULL);
