INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mighty Morphin Power Rangers - The Movie (USA)', '1995', NaN, 'Gray Matter', '1', NaN, 'Side-scrolling beat ''em up based on the 1995 feature film.', 'Team up to defeat the Ooze and save the city.', 'Join the action in Power Rangers: The Movie on SNES.', 'Master the 16-bit combat across two planes of action (foreground and background). A fast-paced licensed title with great music and satisfying superhero combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mighty Morphin Power Rangers (Europe)', '1994', NaN, 'Natsume', '1', NaN, 'Side-scrolling action-platformer based on the first season.', 'Defeat Rita Repulsa''s monsters and protect Earth.', 'Become a Ranger in Mighty Morphin Power Rangers on SNES.', 'The classic 16-bit action game. Play as your favorite Ranger, fight Putty Patrollers, and engage in epic boss battles that conclude with a giant Megazord fight.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mighty Morphin Power Rangers (Japan)', '1994', NaN, 'Natsume', '1', NaN, 'Side-scrolling action-platformer based on the first season.', 'Experience the original Japanese release of the Ranger saga.', 'Play Kyuuryuu Sentai Zyuranger style on Super Famicom.', 'The foundational 16-bit release of the Power Rangers hit. Features bright, colorful graphics and a difficulty curve that is perfect for fans of the iconic TV show.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mighty Morphin Power Rangers (USA)', '1994', NaN, 'Natsume', '1', NaN, 'Side-scrolling action-platformer based on the first season.', 'Defeat Rita Repulsa''s monsters and protect Earth.', 'Become a Ranger in Mighty Morphin Power Rangers on SNES.', 'Master each Ranger''s unique weapon. A definitive 16-bit action title that captures the spirit of the show with great sprites and an iconic rock-infused soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Milandra (Japan)', '1997', NaN, 'ASCII', '1', NaN, 'Roguelike-style dungeon crawler with puzzle elements.', 'Navigate the mysterious tower and find the legendary treasure.', 'Explore the dungeons of Milandra on the Super Famicom.', 'A 16-bit tactical RPG where every step counts. Manage your resources and equipment while exploring randomly generated floors filled with traps and dangerous creatures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Militia (Japan)', '1997', NaN, 'ASCII', '1', NaN, 'Tactical grid-based strategy game with a military theme.', 'Deploy your units to capture enemy bases and win the war.', 'Master strategy in Militia on the Super Famicom.', 'A deep 16-bit tactical sim. Manage tanks, infantry, and air support in turn-based battles that require careful positioning and resource management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mini Yonku Let''s & Go!! - Power WGP 2 (Japan)', '1997', NaN, 'Atelier Double', '2', NaN, 'Mini-4WD racing simulation and RPG adventure.', 'Build the ultimate racing car and win the World Grand Prix 2.', 'Race for glory in Mini Yonku Let''s & Go!! on SNES.', 'A 16-bit racing sim based on the popular anime. Customize your car''s motor, tires, and chassis to dominate the high-speed tracks in this technical sequel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mini Yonku Shining Scorpion - Let''s & Go!! (Japan)', '1996', NaN, 'Atelier Double', '2', NaN, 'Mini-4WD racing simulation featuring the Shining Scorpion car.', 'Customize your racer to win the national championships.', 'Experience Mini Yonku Shining Scorpion on Super Famicom.', 'Features deep 16-bit customization options. Balance speed and stability to survive the loops and jumps of professional Mini-4WD racing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Minor fixes for Mortal Kombat II', '1994', NaN, 'Midway', '2', NaN, 'Technical romhack fixing bugs in the original Mortal Kombat II.', 'Enjoy a more balanced and bug-free version of the arcade hit.', 'Play Mortal Kombat II (Minor Fixes) on the SNES.', 'A 16-bit Quality of Life hack that corrects character palettes, fixes move-priority glitches, and polishes the overall gameplay for a smoother experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Miracle Casino Paradise (Japan)', '1994', NaN, 'Marionette', '1', NaN, 'Casino simulation featuring a wide variety of gambling games.', 'Build your fortune and become the king of the virtual casino.', 'Test your luck in Miracle Casino Paradise on Super Famicom.', 'Features 16-bit renditions of Slots, Roulette, and Baccarat. Includes a story mode where you navigate the casino world and build your reputation as a high-roller.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Miracle Girls (Japan)', '1993', NaN, 'Now Production', '1', NaN, 'Puzzle-platformer based on the shoujo anime and manga.', 'Use magical powers to rescue your friends and clear levels.', 'Join the adventure in Miracle Girls on the Super Famicom.', 'A charming 16-bit platformer starring twin sisters Tomomi and Mikage. Use magical candies to transform and overcome obstacles in a colorful, whimsical world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Miracle Girls (Japan) [En by RPGOne v1.0]', '1993', NaN, 'Now Production', '1', NaN, 'Puzzle-platformer with a full English fan translation.', 'Experience the Miracle Girls'' journey with English text.', 'Play Miracle Girls in English on the Super Nintendo.', 'The RPGOne translation makes this 16-bit gem accessible. Follow the lighthearted story and master the sisters'' unique abilities in your own language.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Miracle Piano Teaching System, The (USA)', '1991', NaN, 'The Learning Company', '1', NaN, 'Educational music software for learning the piano.', 'Learn to play real music using the SNES and the Miracle keyboard.', 'Learn piano with The Miracle Piano Teaching System on SNES.', 'A unique 16-bit educational tool. Combined with a special MIDI keyboard, it provides interactive lessons and games to teach rhythm, notes, and music theory.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Miyaji Shachou no Pachinko Fan - Shouri Sengen 2 (Japan)', '1996', NaN, 'KSS', '1', NaN, 'Pachinko simulation featuring diverse machines and themes.', 'Master the art of Pachinko to win big and please the boss.', 'Play Pachinko Fan: Shouri Sengen 2 on Super Famicom.', 'A realistic 16-bit simulation of Japanese Pachinko parlors. Features multiple machines with different payout rates and colorful, animated mini-games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mizuki Shigeru no Youkai Hyakkiyakou (Japan)', '1994', NaN, 'Soft Vision', '1', NaN, 'Traditional board game simulation based on Japanese folklore.', 'Navigate the world of Youkai and collect legendary creatures.', 'Discover Mizuki Shigeru no Youkai Hyakkiyakou on SNES.', 'A 16-bit digital board game based on the art of Shigeru Mizuki. Learn about Japanese mythology while competing against rivals in a colorful, supernatural world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'MLBPA Baseball (USA)', '1994', NaN, 'EA Sports', '2', NaN, 'Realistic baseball simulation featuring MLBPA players.', 'Lead your favorite team to victory with licensed player data.', 'Play MLBPA Baseball on the Super Nintendo.', 'Features the full 1994 MLBPA roster. A solid 16-bit sports title with smooth pitching and batting mechanics and comprehensive seasonal statistics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mohawk & Headphone Jack (Europe)', '1995', NaN, 'Sculptured Software', '1', NaN, 'High-speed 360-degree rotating platformer.', 'Recover your lost CDs and navigate the morphing environments.', 'Experience the trippy Mohawk & Headphone Jack on SNES.', 'A 16-bit technical showcase. The entire world rotates around the character, creating a dizzying and unique platforming experience with a heavy focus on speed and music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mohawk & Headphone Jack (USA)', '1995', NaN, 'Sculptured Software', '1', NaN, 'High-speed 360-degree rotating platformer.', 'Recover your lost CDs and navigate the morphing environments.', 'Experience the trippy Mohawk & Headphone Jack on SNES.', 'Master the 16-bit gravity-defying jumps and transformations. Use power-ups to morph your character and survive the psychedelic, fast-paced levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Moltov Mario World', '2019', NaN, 'Fanmade', '1', NaN, 'Challenging fan-made Super Mario World romhack.', 'Survive a series of punishing levels in this Kaizo-lite quest.', 'Challenge Moltov Mario World on the Super Nintendo.', 'A 16-bit romhack designed for veteran players. Features creative platforming obstacles, custom palettes, and a high difficulty curve that rewards precision.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Momotarou Dentetsu Happy (Japan)', '1996', NaN, 'Hudson Soft', '4', NaN, 'Railway-themed digital board game and business sim.', 'Build the most successful train empire across Japan.', 'Play Momotarou Dentetsu Happy on the Super Famicom.', 'The ultimate 16-bit family board game. Buy properties, manage your finances, and avoid the God of Poverty in this colorful and addictive business simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Monopoly (Japan)', '1992', NaN, 'Tonkin House', '4', NaN, 'The classic property-trading board game for the SNES.', 'Bankrupt your opponents and own the most famous Japanese cities.', 'Play Monopoly on the Super Famicom.', 'A 16-bit digital version of the world''s most famous board game. Features localized Japanese properties and smooth animations for a fun family experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Monopoly (USA)', '1992', NaN, 'Tonkin House', '4', NaN, 'The classic property-trading board game for the SNES.', 'Buy, sell, and trade your way to a total monopoly.', 'Play the classic Monopoly on the Super Nintendo.', 'Features colorful 16-bit graphics and customizable house rules. Play against the AI or up to four friends in this faithful digital adaptation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Monopoly (USA) (Rev A)', '1992', NaN, 'Tonkin House', '4', NaN, 'The classic property-trading board game (Updated Revision).', 'Master the market in this refined 16-bit version.', 'Play Monopoly (Rev A) for the Super Nintendo.', 'An updated 16-bit revision that fixes minor UI bugs and improves the AI''s trading logic for a more competitive and fair gaming experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Monopoly Game 2, The (Japan)', '1995', NaN, 'Tonkin House', '4', NaN, 'Expanded digital board game sequel with more features.', 'Build your real estate empire in this polished sequel.', 'Experience The Monopoly Game 2 on the Super Famicom.', 'Features improved 16-bit graphics and new character avatars. Offers more complex AI and a wider variety of board events for a fresh take on the classic formula.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Monstania (Japan)', '1992', NaN, 'Riverhillsoft', '1', NaN, 'Isometric tactical RPG with a focus on speed and puzzles.', 'Lead Fron and Tia to save the world in this fast-paced epic.', 'Discover the beautiful Monstania on the Super Famicom.', 'A 16-bit tactical gem. Features unique grid-based combat where movement and strategy are key. Known for its gorgeous pixel art and emotional storytelling.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Monstania (Japan) [En by Aeon Genesis v1.03]', '1992', NaN, 'Riverhillsoft', '1', NaN, 'Isometric tactical RPG with a full English fan translation.', 'Experience the story of Monstania with English text.', 'Play Monstania in English on the Super Nintendo.', 'The Aeon Genesis translation makes this 16-bit tactical RPG accessible. Master the strategic combat and enjoy the heartwarming narrative in your own language.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Monster Maker III - Hikari no Majutsushi (Japan)', '1993', NaN, 'Soft Vision', '1', NaN, 'Traditional turn-based JRPG based on the card game series.', 'Stop the dark sorcerer and master the art of monster summoning.', 'Explore Monster Maker III on the Super Famicom.', 'A polished 16-bit RPG featuring a unique card-inspired magic system. Build your party with diverse fantasy races and explore a vibrant world filled with dungeons and secrets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Monster Maker Kids - Ousama ni Naritai (Japan)', '1994', NaN, 'Soft Vision', '1', NaN, 'Strategy-RPG spinoff with a focus on younger audiences.', 'Help the young heroes complete trials to become the new king.', 'Play Monster Maker Kids on the Super Famicom.', 'A charming 16-bit tactical RPG. Features simplified mechanics, bright chibi art style, and engaging turn-based battles perfect for fans of the Monster Maker universe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat - Red Blood and Easy Moves', '1993', NaN, 'Midway', '2', NaN, 'Action-heavy fighting game with restored blood and simplified inputs.', 'Defeat Shang Tsung with maximum gore and easier combos.', 'Play Mortal Kombat: Red Blood Edition on the SNES.', 'A 16-bit fan hack that fixes the sweat censorship of the original SNES port. Restores red blood and fatalities while making special moves easier to execute.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat - Shinken Kourin Densetsu (Japan)', '1993', NaN, 'Midway', '2', NaN, 'One-on-one fighting game with digitized sprites (Japanese release).', 'Win the Shaolin tournament in the official Japanese version.', 'Experience Mortal Kombat on the Super Famicom.', 'The 16-bit Japanese port of the arcade phenomenon. Known for its realistic digitized fighters and the unique sweat effects used to pass local censorship boards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat (Europe)', '1993', NaN, 'Midway', '2', NaN, 'One-on-one fighting game that defined the 90s arcade scene.', 'Defeat the Outworld sorcerer Shang Tsung to save Earthrealm.', 'Play the legendary Mortal Kombat for the SNES.', 'A landmark 16-bit title. Master the moves of Scorpion, Sub-Zero, and Rayden. Features smooth animations and the iconic (though censored) finishing moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat (Europe) (Beta)', '1993', NaN, 'Midway', '2', NaN, 'One-on-one fighting game (Early European build).', 'Test the initial character balancing and move sets.', 'Check out the Mortal Kombat Beta on the SNES.', 'A rare 16-bit development build. Witness the fine-tuning of the projectile speeds and the early implementation of the background stages from the arcade.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat (Europe) (Rev A)', '1993', NaN, 'Midway', '2', NaN, 'One-on-one fighting game (Updated European Revision).', 'Defeat Goro in this polished 16-bit revision.', 'Play Mortal Kombat (Rev A) on the Super Nintendo.', 'An updated 16-bit version that fixes minor graphical glitches and improves the AI behavior for a more consistent challenge compared to the initial release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat (USA)', '1993', NaN, 'Midway', '2', NaN, 'One-on-one fighting game featuring digitized martial artists.', 'Enter the tournament and master the secret Fatality moves.', 'Experience Mortal Kombat on the Super Nintendo.', 'The game that sparked a revolution. While censored for blood, it features superior sound and graphics compared to other 16-bit ports of the era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat 3 - Redux', '1995', NaN, 'Midway', '2', NaN, 'Enhanced fan-made version of the third Mortal Kombat entry.', 'Experience a more arcade-accurate version of MK3.', 'Play Mortal Kombat 3: Redux on the SNES.', 'A 16-bit overhaul that adds missing frames of animation, improves character palettes, and balances the gameplay to feel closer to the Ultimate arcade experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat 3 (Europe)', '1995', NaN, 'Midway', '2', NaN, 'Fast-paced fighting game introducing the Run button and combos.', 'Defeat Shao Kahn''s invasion forces in the European version.', 'Battle in Mortal Kombat 3 for the Super Nintendo.', 'Features a massive roster including Cyrax, Sektor, and Sheeva. This 16-bit port is remarkably faithful to the arcade, including the complex Dial-a-combo system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat 3 (Europe) (Beta)', '1995', NaN, 'Midway', '2', NaN, 'Fast-paced fighting game (Early European build).', 'Explore early stage designs and character combos.', 'Check out the Mortal Kombat 3 Beta on the SNES.', 'A pre-release 16-bit look at the third entry. Witness the evolution of the urban stages and the balancing of the new robotic ninja characters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat 3 (Jul 13, 1995 prototype)', '1995', NaN, 'Midway', '2', NaN, 'Fast-paced fighting game (Rare mid-development build).', 'Test the mechanics from the July 1995 prototype.', 'Explore the MK3 July Prototype on the SNES.', 'An insightful 16-bit development slice. Features unpolished menus, incomplete sound sets, and experimental timing for the newly introduced run mechanic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat 3 (USA)', '1995', NaN, 'Midway', '2', NaN, 'Fast-paced fighting game introducing the Run button and combos.', 'Stop Shao Kahn from merging Earthrealm with Outworld.', 'Experience Mortal Kombat 3 on the Super Nintendo.', 'Master the 16-bit fatalities and the new Animalities. A high-energy fighter that pushed the SNES hardware with large sprites and multi-layered backgrounds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat 3 (USA) (Beta)', '1995', NaN, 'Midway', '2', NaN, 'Fast-paced fighting game (Early North American build).', 'Test the Kombat Kodes and character finishers.', 'Check out the Mortal Kombat 3 Beta on the SNES.', 'A 16-bit development build focused on bug-testing the secret codes and the interactive stage transitions that allowed players to uppercut through ceilings.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat Champion Edition', '1993', NaN, 'Midway', '2', NaN, 'Fan-made best of edition of the Mortal Kombat series.', 'Fight with an expanded roster and unlocked secrets.', 'Play Mortal Kombat: Champion Edition on SNES.', 'A 16-bit fan project that aims to create the ultimate MK experience. Features modified character stats, unlocked sub-bosses, and various gameplay refinements.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat II - Hidden Characters Playable', '1994', NaN, 'Midway', '2', NaN, 'Gameplay modification allowing play as non-selectable fighters.', 'Play as Jade, Smoke, and Noob Saibot in the main game.', 'Play as hidden characters in Mortal Kombat II on SNES.', 'A 16-bit hack that makes the legendary secret opponents fully playable. Features unique move sets for the hidden ninjas within the standard MK2 roster.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat II - Kyuukyoku Shinken (Japan)', '1994', NaN, 'Midway', '2', NaN, 'One-on-one fighting game (Japanese release of the sequel).', 'Defeat Shao Kahn in the official Japanese version.', 'Experience Mortal Kombat II on the Super Famicom.', 'The 16-bit Japanese port. Unlike the first game, this version features full red blood and all the gruesome fatalities that made the sequel an international hit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat II (Europe)', '1994', NaN, 'Midway', '2', NaN, 'One-on-one fighting game widely considered the series'' peak.', 'Travel to Outworld to defeat the emperor Shao Kahn.', 'Play Mortal Kombat II for the Super Nintendo.', 'A 16-bit masterpiece. Features more characters, multi-layered fatalities (Friendships and Babalities), and some of the best digitized graphics on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat II (Europe) (Rev A)', '1994', NaN, 'Midway', '2', NaN, 'One-on-one fighting game (Updated European Revision).', 'Master the Outworld tournament in this refined version.', 'Play Mortal Kombat II (Rev A) on the SNES.', 'An updated 16-bit revision that fixes several infinite combo glitches and polishes the sound effects for a more arcade-perfect experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat II (USA)', '1994', NaN, 'Midway', '2', NaN, 'One-on-one fighting game widely considered the series'' peak.', 'Travel to Outworld to defeat the emperor Shao Kahn.', 'Play Mortal Kombat II for the Super Nintendo.', 'The definitive 16-bit fighting experience for many. Features a rich roster, atmospheric stages, and the perfected Mortal Kombat combat loop.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat II (USA) (Rev A)', '1994', NaN, 'Midway', '2', NaN, 'One-on-one fighting game (Updated North American Revision).', 'Defeat the Kintaro and Shao Kahn in this polished version.', 'Play Mortal Kombat II (Rev A) on the SNES.', 'The final 16-bit US revision. Fixes several stability issues and adjusts the difficulty of the AI opponents to be more challenging and fair.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat II Characters Secrets', '1997', NaN, 'Midway', '1', NaN, 'Technical guide and cheat menu modification for MK2.', 'Quickly access all character fatalities and secret moves.', 'Discover Mortal Kombat II Secrets on the SNES.', 'A 16-bit utility hack that adds an in-game menu or modified screens to help players execute the complex inputs for every character''s hidden moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mortal Kombat Mythologies Gold 2000', '2000', NaN, 'Midway', '1', NaN, 'Unofficial demake or pirate-style fighting game.', 'Battle through a unique 16-bit interpretation of Sub-Zero''s story.', 'Experience MK Mythologies Gold 2000 on the SNES.', 'A rare and bizarre 16-bit pirate title. Attempts to bring the 3D action of Mythologies into a 2D fighting engine, resulting in a unique (if unpolished) gameplay experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mother 2 - Gyiyg no Gyakushuu (Japan)', '1994', NaN, 'Ape Inc. / HAL Laboratory', '1', NaN, 'Modern-day turn-based JRPG with a quirky and emotional story.', 'Lead Ness and his friends to stop the alien threat of Giygas.', 'Experience the legendary Mother 2 on the Super Famicom.', 'The Japanese original of EarthBound. A 16-bit masterpiece known for its psychedelic battle backgrounds, satirical humor, and a heartwarming adventure across a modern world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mother 2 Deluxe 2.0', '2023', NaN, 'Fan Project', '1', NaN, 'Enhanced fan-made overhaul of EarthBound.', 'Play through a rebalanced and expanded version of Ness''s quest.', 'Experience Mother 2 Deluxe 2.0 on the SNES.', 'A massive 16-bit definitive edition mod. Features expanded dialogue, rebalanced difficulty, new items, and bug fixes that enhance the classic EarthBound experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Motoko-chan no Wonder Kitchen (Japan)', '1993', NaN, 'Athena', '1', NaN, 'Educational cooking simulation sponsored by Ajinomoto.', 'Learn real-world cooking tips and trivia with Motoko-chan.', 'Discover Motoko-chan no Wonder Kitchen on the SNES.', 'A rare 16-bit promotional title. Point and click to interact with kitchen appliances and ingredients while learning about the history of food in a cute, animated setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Motteke Oh! Dorobou (Japan)', '1993', NaN, 'Data East', '1', NaN, 'Multiplayer board-game and action hybrid with a thievery theme.', 'Outsmart your rivals and steal the most treasure to win.', 'Play the quirky Motteke Oh! Dorobou on Super Famicom.', 'A fast-paced 16-bit party game. Compete against friends to navigate maps, set traps, and pull off heists in a vibrant and humorous cartoon world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mountain Bike Rally (USA)', '1991', NaN, 'Visual Concepts', '2', NaN, 'Mountain bike racing simulation using Mode 7 for 3D effects.', 'Win the cross-country rally and upgrade your mountain bike.', 'Race the trails in Mountain Bike Rally for the SNES.', 'Also known as Cannondale Cup. Features 16-bit terrain scaling, stamina management, and diverse outdoor tracks ranging from forests to rocky mountains.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mouryou Senki Madara 2 (Japan)', '1994', NaN, 'KONAMI', '1', NaN, 'Top-down turn-based JRPG based on the popular manga/anime.', 'Defeat the demon army and reclaim your stolen body parts.', 'Explore the dark Mouryou Senki Madara 2 on SNES.', 'A visually impressive 16-bit RPG. Features an automated battle system with tactical input and a mature, dark fantasy story accompanied by a stellar soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mr Nutz (Europe) (En,Fr)', '1993', NaN, 'Ocean', '2', NaN, 'Vibrant side-scrolling platformer starring a red squirrel.', 'Stop the evil Yeti from freezing the world.', 'Join the adventure in Mr. Nutz for the Super Nintendo.', 'A polished 16-bit platformer with lush forest and winter backgrounds. Use your tail-spin attack and jump on enemies to save the world from an eternal ice age.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mr Nutz (Japan)', '1993', NaN, 'Ocean', '2', NaN, 'Vibrant side-scrolling platformer starring a red squirrel.', 'Defeat the Yeti in the original Japanese version.', 'Experience Mr. Nutz on the Super Famicom.', 'Known for its incredibly detailed 16-bit pixel art and catchy music. A classic mascot platformer that rewards exploration and precise jumping.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mr Nutz (USA) (En,Fr)', '1993', NaN, 'Ocean', '2', NaN, 'Vibrant side-scrolling platformer starring a red squirrel.', 'Stop the evil Yeti from freezing the world.', 'Join the adventure in Mr. Nutz for the Super Nintendo.', 'Master the 16-bit platforming challenges. Features multiple themed worlds, challenging boss fights, and some of the most colorful graphics of the era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mr Nutz (USA) (En,Fr) (Beta)', '1993', NaN, 'Ocean', '2', NaN, 'Vibrant side-scrolling platformer (Pre-release build).', 'Explore early level designs and squirrel animations.', 'Check out the Mr. Nutz Beta on the Super Nintendo.', 'A rare 16-bit development build. Witness the fine-tuning of the physics and the evolution of the vibrant environmental assets before the final release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mr. Do! (Europe)', '1992', NaN, 'Namco', '2', NaN, 'Arcade-style puzzle game featuring a clown and falling fruits.', 'Clear each level by digging tunnels and dropping apples on enemies.', 'Play the classic Mr. Do! on the Super Nintendo.', 'A faithful 16-bit port of the arcade legend. Use your power ball to defeat monsters and collect all the cherries to advance through increasingly difficult stages.', NULL);
