INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mr. Tuff (Europe) (En,Fr,De,Es,It) (Proto) (1994-12-05)', '1994', NaN, 'Ocean', '2', NaN, 'Action-platformer starring a powerful construction robot (Prototype).', 'Stop the army of rogue robots in this unreleased 16-bit epic.', 'Check out the Mr. Tuff Proto for the Super Nintendo.', 'A high-quality 16-bit prototype. Features large sprites and a variety of gadgets for the protagonist to use in a polished industrial world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mr. Tuff (USA) (En,Fr,De) (Proto) (1994-07-12)', '1994', NaN, 'Ocean', '2', NaN, 'Action-platformer starring a powerful construction robot (Prototype).', 'Test early level layouts and robot physics in this North American build.', 'Explore the Mr. Tuff Beta on the SNES.', 'A pre-release 16-bit look at a game that was nearly finished. Features impressive environmental destruction and smooth robot animations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ms. Pac-Man (Europe)', '1996', NaN, 'Namco', '2', NaN, 'Arcade-perfect maze-chase game featuring the iconic heroine.', 'Eat all the dots while avoiding the four colorful ghosts.', 'Play Ms. Pac-Man for the Super Nintendo.', 'A 16-bit update to the arcade classic. Features multiple maze layouts, improved graphics, and the same addictive gameplay that made the original a legend.', NULL);
