INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ms. Pac-Man (USA)', '1996', NaN, 'Namco', '2', NaN, 'Arcade-perfect maze-chase game featuring the iconic heroine.', 'Eat all the dots while avoiding the four colorful ghosts.', 'Play Ms. Pac-Man for the Super Nintendo.', 'Features the classic Intermission scenes and iconic 16-bit sound effects. A nostalgic and perfectly executed port for fans of the golden age of arcades.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Muhammad Ali Heavyweight Boxing (USA) (Proto)', '1993', NaN, 'Razorsoft', '1', NaN, 'Realistic heavyweight boxing simulation (Prototype).', 'Climb the rankings and win the title as Muhammad Ali.', 'Check out the Muhammad Ali Boxing Proto on SNES.', 'A 16-bit sports prototype featuring large character sprites and a focus on tactical punching. Experience an unreleased take on the Greatest of All Time.', NULL);
