INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mystic Ark (Japan)', '1995', NaN, 'Produce!', '1', NaN, 'Deep turn-based RPG with an emphasis on atmosphere and puzzles.', 'Recover the seven Arks to restore your world and identity.', 'Explore the mysterious Mystic Ark on the Super Famicom.', 'The spiritual successor to The 7th Saga. Features beautiful 16-bit pixel art, a somber tone, and a unique system where you possess statues to build your party.', NULL);
