INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Mystic Ark (Japan) [En by Dynamic Designs v1.0]', '1995', NaN, 'Produce!', '1', NaN, 'Deep turn-based RPG with an alternative English fan translation.', 'Experience the world of Arks with the Dynamic Designs script.', 'Play Mystic Ark in English on the Super Nintendo.', 'An alternative 16-bit translation that offers a different take on the game''s poetic and mysterious dialogue. Perfect for fans of deep, story-driven JRPGs.', NULL);
