INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'NFL Quarterback Club (USA)', '1994', NaN, 'Iguana Entertainment', '2', NaN, 'Professional football simulation and rival to the Madden series.', 'Master the playbook and claim the Super Bowl trophy.', 'Experience NFL Quarterback Club on the Super Nintendo.', 'Known for its impressive 16-bit visuals and the specialized Quarterback Challenge mode. Offers a more arcade-leaning alternative to the Madden series.', NULL);
