INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pac-Man 2 - The New Adventures (Europe)', '1994', NaN, 'Namco', '1', NaN, 'Interactive adventure where you guide an autonomous Pac-Man.', 'Help Pac-Man complete errands while managing his mood.', 'Play Pac-Man 2: The New Adventures on SNES.', 'A unique 16-bit title. Use a slingshot to interact with the environment and influence Pac-Man''s emotions in this colorful, cartoon-like adventure.', NULL);
