INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pac-Man 2 - The New Adventures (Germany)', '1994', NaN, 'Namco', '1', NaN, 'Interactive adventure with localized German text.', 'Help Pac-Man survive his neighborhood in the German version.', 'Spielen Sie Pac-Man 2 auf Deutsch für das SNES.', 'Experience the 16-bit comedy-adventure with localized German dialogue. Direct Pac-Man through various scenarios using your slingshot and wits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pac-Man 2 - The New Adventures (USA)', '1994', NaN, 'Namco', '1', NaN, 'Interactive adventure where you guide an autonomous Pac-Man.', 'Solve the mystery of the Ghost Witch in the USA edition.', 'Experience Pac-Man 2 on the Super Nintendo.', 'Master the 16-bit emotional management. Pac-Man''s reactions change based on how you treat him, leading to hundreds of unique and funny animations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachi-Slot Gambler (Japan)', '1993', NaN, 'Coconuts Japan', '1', NaN, 'Realistic Pachi-Slot gambling simulation.', 'Master the slot machines and build your virtual fortune.', 'Play Pachi-Slot Gambler on the Super Famicom.', 'A detailed 16-bit simulation of Japanese slot parlors. Features multiple machines with unique odds and bonus games for fans of the virtual casino experience.', NULL);
