INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachi-Slot Love Story (Japan)', '1995', NaN, 'Coconuts Japan', '1', NaN, 'Pachi-Slot simulation with a romantic visual novel twist.', 'Win big at the slots to win the heart of your virtual date.', 'Experience Pachi-Slot Love Story on the Super Famicom.', 'Combines 16-bit gambling gameplay with a dating sim. Interact with various characters and use your winnings to advance the romantic storyline.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachi-Slot Monogatari - PAL Kougyou Special (Japan)', '1994', NaN, 'KSS', '1', NaN, 'Pachi-Slot story and simulation featuring PAL Kougyou machines.', 'Experience the life of a professional gambler in this story mode.', 'Play Pachi-Slot Monogatari on the Super Famicom.', 'A 16-bit simulation that provides a narrative context to the gambling action. Includes realistic machine physics and a quest to become the best player.', NULL);
