INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachinko Fan - Shouri Sengen (Japan)', '1992', NaN, 'Irem', '1', NaN, 'Pachinko simulation with a focus on winning strategies.', 'Follow the Declaration of Victory and master the machines.', 'Experience Pachinko Fan: Shouri Sengen on SNES.', 'A technical 16-bit simulation that teaches players how to read the pins and timing of Pachinko machines to maximize their daily winnings.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachinko Maruhi Hisshouhou (Japan)', '1992', NaN, 'Magical Company', '1', NaN, 'Pachinko simulation featuring secret winning techniques.', 'Discover the hidden methods to beat the virtual machines.', 'Play Pachinko Maruhi Hisshouhou on Super Famicom.', 'Features 16-bit guides and tips for mastering popular Pachinko machines. Practice your shots and learn the patterns of the digital reels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachinko Monogatari - Pachi-Slot mo Aru deyo!! (Japan)', '1994', NaN, 'KSS', '1', NaN, 'Pachinko and Pachi-Slot hybrid simulation and adventure.', 'Master both types of gambling machines in this story mode.', 'Play Pachinko Monogatari on the Super Famicom.', 'A 16-bit title that offers a variety of gambling options. Explore the town, visit different parlors, and manage your bankroll across multiple machines.', NULL);
