INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachinko Ren-chan Tengoku - Super CR Special (Japan)', '1995', NaN, 'KSS', '1', NaN, 'Realistic Pachinko simulation focusing on Ren-chan (consecutive win) mechanics.', 'Master the special CR machines to trigger massive winning streaks.', 'Play Pachinko Ren-chan Tengoku on the Super Famicom.', 'A technical 16-bit simulation of high-stakes Pachinko. Features detailed physics for the Super CR series of machines, focusing on the adrenaline-pumping moments of consecutive jackpots.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachinko Tetsujin - Nanaban Shoubu (Japan)', '1995', NaN, 'Soft Machine', '1', NaN, 'Challenge-based Pachinko simulation against seven masters.', 'Defeat the seven iron-men of Pachinko in high-stakes duels.', 'Experience Pachinko Tetsujin on the Super Famicom.', 'A 16-bit gambling sim with a competitive twist. Face off against expert AI opponents across various machines, requiring precise ball control and a bit of digital luck.', NULL);
