INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachio-kun Special (Japan)', '1995', NaN, 'Coconuts Japan', '1', NaN, 'Pachinko adventure starring the series'' round mascot, Pachio-kun.', 'Help Pachio-kun navigate the world of parlors and win big.', 'Join the adventure in Pachio-kun Special on SNES.', 'A 16-bit classic in Japan. Combine light exploration with realistic Pachinko gameplay as the iconic ball-shaped hero visits various themed establishments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachio-kun Special 2 (Japan)', '1996', NaN, 'Coconuts Japan', '1', NaN, 'Pachinko adventure sequel with a focus on world travel.', 'Journey across different lands and master their Pachinko tables.', 'Play Pachio-kun Special 2 on the Super Famicom.', 'Features improved 16-bit graphics and a wider variety of machines. Follow Pachio-kun''s journey in this lighthearted blend of RPG-lite elements and gambling simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pachio-kun Special 3 (Japan)', '1997', NaN, 'Coconuts Japan', '1', NaN, 'The final entry in the 16-bit Pachio-kun Special trilogy.', 'Complete the ultimate Pachinko challenge in this polished finale.', 'Experience Pachio-kun Special 3 on the Super Famicom.', 'The most refined 16-bit entry in the series. Offers the largest selection of machines and a charming story that concludes Pachio-kun''s Super Famicom adventures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pacific Theater of Operations (USA)', '1994', NaN, 'Koei', '1', NaN, 'Grand strategy simulation of WWII naval warfare in the Pacific.', 'Command the Allied or Japanese fleet to naval supremacy.', 'Master history in P.T.O. (Pacific Theater of Operations).', 'A massive 16-bit strategic sim from Koei. Manage ship production, fuel, troop morale, and tactical sea battles in a highly detailed historical setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pacific Theater of Operations II (USA)', '1996', NaN, 'Koei', '1', NaN, 'Advanced grand strategy sequel with improved tactical depth.', 'Lead your navy to victory in this comprehensive WWII sequel.', 'Experience P.T.O. II on the Super Nintendo.', 'Features a much-improved interface and more complex diplomatic options. A 16-bit masterpiece for strategy enthusiasts, covering every aspect of the Pacific war.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Packy & Marlon (USA) (En,Fr,Es)', '1995', NaN, 'Radiation Oncology Center', '2', NaN, 'Educational action-platformer focused on diabetes management.', 'Navigate the summer camp while managing your blood sugar levels.', 'Play the educational Packy & Marlon on the SNES.', 'A unique 16-bit title designed to teach children about health. Collect food and insulin while platforming through diverse levels to keep your character healthy and active.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pagemaster, The (Europe)', '1994', NaN, 'Probe Software', '1', NaN, 'Fantasy action-platformer based on the animated film.', 'Journey through classic literature worlds to defeat Mr. Hyde.', 'Explore the magical worlds of The Pagemaster on SNES.', 'Enter the worlds of Adventure, Fantasy, and Horror. A 16-bit title featuring creative level design and power-ups based on the library-themed source material.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pagemaster, The (USA)', '1994', NaN, 'Probe Software', '1', NaN, 'Fantasy action-platformer based on the animated film.', 'Escape the library and find your way back home.', 'Experience The Pagemaster on the Super Nintendo.', 'Master the 16-bit platforming in levels like The Haunted Mansion and Treasure Island. Features vibrant graphics and a nostalgic soundtrack.', NULL);
