INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Paladin''s Quest (USA)', '1992', NaN, 'Asmik Ace', '1', NaN, 'Unique turn-based RPG with a colorful, alien aesthetic.', 'Restore the world of Lennus by finding the magical spirits.', 'Discover the vibrant Paladin''s Quest on the SNES.', 'Known as Lennus in Japan. Features a unique health-based magic system and a surreal 16-bit art style that stands out from typical fantasy RPGs.', NULL);
