INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Panel de Pon (Japan) [T-En by Zuqkeo v1.0]', '1995', NaN, 'Intelligent Systems', '2', NaN, 'Fast-paced block-matching puzzle game (English translation).', 'Experience the original Fairy-themed puzzle game in English.', 'Play Panel de Pon in English on the Super Nintendo.', 'A 16-bit fan translation that restores the original Japanese characters and story, making the Lip''s Stick world accessible to Western players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Panic in Nakayoshi World (Japan)', '1994', NaN, 'Arc System Works', '1', NaN, 'Action-puzzle game featuring characters from popular Shoujo manga.', 'Clear the stages and save your friends from the panic.', 'Experience Panic in Nakayoshi World on the Super Famicom.', 'A top-down 16-bit brawler and puzzle hybrid. Play as characters from Sailor Moon and other Nakayoshi series in a cute, Bomberman-style arena environment.', NULL);
