INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Parlor! Mini 7 - Pachinko Jikki Simulation Game (Japan)', '1994', NaN, 'Jaleco', '1', NaN, 'Realistic Pachinko simulation featuring real machines.', 'Complete the ultimate parlor challenge in this final Mini entry.', 'Play Parlor! Mini 7 on the Super Famicom.', 'The final 16-bit Mini installment. Features the most polished UI of the series and a selection of the era''s most popular physical Pachinko machines.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Parlor! Parlor! (Japan)', '1995', NaN, 'Jaleco', '1', NaN, 'Advanced Pachinko simulation and parlor management.', 'Climb the ranks of professional players in the city.', 'Discover the world of Parlor! Parlor! on SNES.', 'The main 16-bit series for serious Pachinko fans. Features a larger scope than the Mini versions, with more machines and an immersive parlor atmosphere.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Parlor! Parlor! 2 (Japan)', '1995', NaN, 'Jaleco', '1', NaN, 'Advanced Pachinko simulation and parlor management.', 'Build your fortune across multiple virtual parlors.', 'Play Parlor! Parlor! 2 on the Super Famicom.', 'An expanded 16-bit sequel with improved graphics. Master the nuances of different machine brands and manage your digital bankroll to become a high-roller.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Parlor! Parlor! 3 (Japan)', '1996', NaN, 'Jaleco', '1', NaN, 'Advanced Pachinko simulation and parlor management.', 'Win the tournament and master new machine types.', 'Experience Parlor! Parlor! 3 on the Super Famicom.', 'Features high-quality 16-bit audio and visual recreations of iconic machines. Includes more complex logic for the digital reels and bonus sequences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Parlor! Parlor! 5 (Japan)', '1997', NaN, 'Jaleco', '1', NaN, 'Advanced Pachinko simulation and parlor management.', 'Dominate the latest professional parlor tables.', 'Play Parlor! Parlor! 5 on the Super Famicom.', 'The fifth 16-bit installment in the main series. Focuses on the most modern machines of the mid-90s, featuring complex interactive mini-games on the reels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Parlor! Parlor! IV CR (Japan)', '1997', NaN, 'Jaleco', '1', NaN, 'Pachinko simulation specializing in CR (Card Reader) machines.', 'Master the high-stakes CR machines for massive wins.', 'Play Parlor! Parlor! IV CR on the Super Famicom.', 'A specialized 16-bit sim focused on the CR generation of machines. These offered different winning odds and were a staple of Japanese gambling culture.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Parodius - Non-Sense Fantasy (Europe)', '1991', NaN, 'Konami', '2', NaN, 'Humorous side-scrolling shoot ''em up (Parody of Gradius).', 'Save the world from the bizarre penguin invasion.', 'Experience the wacky Parodius on the Super Nintendo.', 'A 16-bit masterpiece from Konami. Choose from characters like Vic Viper, TwinBee, or a flying octopus in a surreal journey through levels filled with giant pandas and dancing showgirls.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Parodius da! - Shinwa Kara Owarai e (Japan)', '1990', NaN, 'Konami', '2', NaN, 'Humorous side-scrolling shoot ''em up (Japanese version).', 'Fly through the Non-Sense Fantasy in the original release.', 'Play Parodius Da! on the Super Famicom.', 'The foundational 16-bit entry in the comedy SHMUP genre. Master the Bell power-up system and enjoy the frantic, colorful, and hilariously absurd combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Peace Keepers, The (USA)', '1992', NaN, 'Jaleco', '2', NaN, 'Side-scrolling beat ''em up with branching paths and multiple heroes.', 'Stop the terrorist organization and save the world.', 'Fight back in The Peace Keepers for the SNES.', 'Known as Rushing Beat Shura in Japan. A deep 16-bit brawler featuring four playable characters, hidden areas, and a variety of endings based on your choices.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pebble Beach Golf Links (Europe)', '1992', NaN, 'T&E Soft', '4', NaN, 'Professional golf simulation featuring the world-famous course.', 'Master the 18 holes of Pebble Beach to win the championship.', 'Tee off at Pebble Beach Golf Links on the SNES.', 'A 16-bit sports classic featuring digitized photos of the real course. Master the wind, club selection, and green slopes in this highly realistic simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pebble Beach Golf Links (USA)', '1992', NaN, 'T&E Soft', '4', NaN, 'Professional golf simulation featuring the world-famous course.', 'Win the prestigious tournament at Pebble Beach.', 'Experience Pebble Beach Golf Links for the SNES.', 'Features smooth 16-bit ball physics and a variety of modes, including skins and stroke play. A definitive golf experience for the Super Nintendo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pebble Beach no Hatou (Japan)', '1991', NaN, 'T&E Soft', '4', NaN, 'Professional golf simulation (Original Japanese release).', 'Experience the waves and greens of Pebble Beach.', 'Play Pebble Beach no Hatou on the Super Famicom.', 'The foundational 16-bit entry of the series in Japan. Known for its high-quality digitized backgrounds and the technical depth of its swing mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pebble Beach no Hatou New - Tournament Edition (Japan)', '1993', NaN, 'T&E Soft', '4', NaN, 'Professional golf simulation (Enhanced Tournament Edition).', 'Compete in the ultimate tournament on the famous course.', 'Play Pebble Beach no Hatou New on SNES.', 'An updated 16-bit version featuring refined AI for opponents and new tournament structures. Offers the most comprehensive golf challenge in the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'PGA European Tour (Europe)', '1995', NaN, 'EA Sports', '4', NaN, 'Professional golf simulation featuring European courses.', 'Win the European Tour and climb the PGA rankings.', 'Tee off in PGA European Tour for the SNES.', 'A detailed 16-bit sports title featuring real European courses like Wentworth. Master the wind and terrain with authentic PGA players and smooth ball physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'PGA European Tour (USA)', '1995', NaN, 'EA Sports', '4', NaN, 'Professional golf simulation featuring European courses.', 'Become the champion of the European circuit.', 'Experience PGA European Tour on the Super Nintendo.', 'Features multiple play modes including Skins and Match Play. A technical 16-bit simulation that captures the prestige of international professional golf.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'PGA Tour ''96 (Europe)', '1995', NaN, 'EA Sports', '4', NaN, 'Advanced golf simulation with updated 1996 rosters.', 'Master the greens and win the ''96 PGA Championship.', 'Play the polished PGA Tour ''96 on the SNES.', 'Features improved 16-bit digitized graphics and faster UI. Includes real PGA pros and iconic courses with a deep focus on seasonal statistics and player growth.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'PGA Tour ''96 (USA)', '1995', NaN, 'EA Sports', '4', NaN, 'Advanced golf simulation with updated 1996 rosters.', 'Climb the leaderboard in the definitive ''96 edition.', 'Experience PGA Tour ''96 for the Super Nintendo.', 'The North American release of the acclaimed sim. Offers 16-bit precision controls and realistic environmental factors like green speed and wind direction.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'PGA Tour Golf (Europe)', '1991', NaN, 'EA Sports', '4', NaN, 'The foundational entry in the PGA Tour series for SNES.', 'Win the tournament across world-famous golf courses.', 'Play the classic PGA Tour Golf on the SNES.', 'A landmark 16-bit golf game. Introduced the intuitive three-click swing mechanic and features real-world licensed courses with impressive digitized scenery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'PGA Tour Golf (Japan)', '1991', NaN, 'EA Sports', '4', NaN, 'The foundational entry in the PGA Tour series (Japan).', 'Master the fairway in the official Japanese version.', 'Experience PGA Tour Golf on the Super Famicom.', 'The 16-bit Japanese release of the Western hit. Features localized menus and the same deep tactical gameplay that made the series a global success.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'PGA Tour Golf (USA)', '1991', NaN, 'EA Sports', '4', NaN, 'The foundational entry in the PGA Tour series for SNES.', 'Climb the rankings and become a professional golf legend.', 'Play the classic PGA Tour Golf on the SNES.', 'Features a variety of gameplay modes and authentic PGA rules. A 16-bit sports staple known for its realistic approach to the sport.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Phalanx - The Enforce Fighter A-144 (Europe)', '1991', NaN, 'Kemco', '2', NaN, 'Side-scrolling sci-fi shoot ''em up with multiple weapon types.', 'Save the colony of Delia from an alien invasion.', 'Blast through space in Phalanx for the SNES.', 'A technically impressive 16-bit SHMUP. Features large bosses, a flexible power-up system, and smooth scrolling through detailed cavernous and space environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Phalanx - The Enforce Fighter A-144 (Japan)', '1991', NaN, 'Kemco', '2', NaN, 'Side-scrolling sci-fi shoot ''em up (Japanese release).', 'Defeat the alien menace in the original Japanese version.', 'Experience Phalanx on the Super Famicom.', 'The original 16-bit release of the cult classic shooter. Known for its atmospheric soundtrack and challenging stages that reward weapon management.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Phalanx - The Enforce Fighter A-144 (USA)', '1991', NaN, 'Kemco', '2', NaN, 'Side-scrolling sci-fi shoot ''em up (USA release).', 'Protect the universe in this legendary 16-bit shooter.', 'Play the action-packed Phalanx on the SNES.', 'Famous for its bizarre banjo player cover art, but underneath is a high-quality 16-bit shooter with tight controls and creative level design.', NULL);
