INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Phantom 2040 (Europe) (En,Fr,De)', '1995', NaN, 'Viacom', '1', NaN, 'Action-adventure platformer with branching paths and 20+ endings.', 'Stop the Maximum Inc. corporation and save the future.', 'Explore the deep Phantom 2040 on the SNES.', 'A 16-bit masterpiece of non-linear design. Use gadgets like the grappling hook and specialized guns in a massive, interconnected cyberpunk world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Phantom 2040 (USA)', '1995', NaN, 'Viacom', '1', NaN, 'Action-adventure platformer with branching paths and 20+ endings.', 'Find your father and choose your destiny in Metropia.', 'Play the non-linear Phantom 2040 on the SNES.', 'Features incredible world-building and a Metroidvania style of exploration. Your 16-bit choices directly impact the fate of the city and the world.', NULL);
