INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pinball Fantasies (USA)', '1993', NaN, 'Digital Illusions', '1', NaN, 'Advanced pinball simulation with four massive new tables.', 'Master the intricate bonuses of the four 16-bit tables.', 'Play the addictive Pinball Fantasies on the SNES.', 'Features enhanced graphics and more detailed table events. A definitive 16-bit pinball experience with refined ball physics and high-quality sound effects.', NULL);
