INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Pro Yakyuu Star (Japan)', '1995', NaN, 'Banpresto', '2', NaN, 'One-on-one fighting game (Pre-release build).', 'Test the early animation frames and hitboxes of the beasts.', 'Check out the Primal Rage Beta on the SNES.', 'A rare 16-bit development look. Witness the fine-tuning of the dinosaur special moves and the evolution of the detailed, post-apocalyptic stage backgrounds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Project Base 0.8.1', '2021', NaN, 'Homebrew', '1', NaN, 'Action-adventure platformer based on the comic book hero (Prototype).', 'Stop the villains and master your newfound superpowers.', 'Explore the unreleased Prime Proto on the SNES.', 'A rare 16-bit prototype featuring the Ultraverse superhero. Explore non-linear levels and use super-strength to defeat enemies in this unreleased comic book adaptation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Project Base 0.8.4.2', '2023', NaN, 'Homebrew', '1', NaN, 'Cinematic platformer with realistic rotoscoped movement.', 'Escape the dungeon and rescue the Princess in under 60 minutes.', 'Play the definitive Prince of Persia on the SNES.', 'The best 16-bit version of the classic. Features expanded levels, improved graphics, new boss fights, and a beautiful orchestral soundtrack not found in other ports.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Psycho Dream (Japan)', '1992', NaN, 'Riot', '1', NaN, 'Cinematic platformer with realistic rotoscoped movement (Japan).', 'Navigate the Sultan''s palace in the official Japanese release.', 'Experience Prince of Persia on the Super Famicom.', 'The 16-bit Japanese edition featuring the same expanded content and fluid animations that made the SNES version a standout cinematic adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Puggsy', '1993', NaN, 'Traveller''s Tales', '1', NaN, 'Cinematic platformer with realistic rotoscoped movement.', 'Rescue the Princess and defeat Jaffar in this 16-bit epic.', 'Play the classic Prince of Persia on the Super Nintendo.', 'Master the 16-bit sword fighting and environmental puzzles. This version doubles the length of the original game with new traps and secret rooms.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Push-Over (Europe) (En,Fr,De,Es)', '1992', NaN, 'Red Rat Software', '1', NaN, 'Cinematic platformer sequel with enhanced combat and visuals.', 'Discover your true identity and reclaim your kingdom.', 'Experience Prince of Persia 2 on the Super Nintendo.', 'A visually stunning 16-bit sequel. Features more complex combat, diverse environments from deserts to ruins, and a deeper focus on the cinematic narrative.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Push-Over (USA)', '1992', NaN, 'Red Rat Software', '1', NaN, 'Cinematic platformer sequel with enhanced combat and visuals.', 'Uncover the secrets of the past and defeat the Shadow.', 'Play Prince of Persia 2: The Shadow & The Flame on SNES.', 'Master the improved 16-bit platforming and swordplay. A challenging adventure that expands on the mechanics of the first game with larger, more detailed stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Push-Over (USA) (Beta)', '1992', NaN, 'Red Rat Software', '1', NaN, 'Life simulation and breeding game featuring a fantasy setting.', 'Raise your adopted daughter to adulthood and shape her future.', 'Play Princess Maker on the Super Famicom.', 'A landmark 16-bit simulation. Manage your daughter''s education, part-time jobs, and social life to unlock dozens of different endings based on your choices.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Putty Moon (Japan)', '1992', NaN, 'System 3', '1', NaN, 'Turn-based RPG with an all-female cast and tactical combat.', 'Lead your team of warriors to stop an ancient evil.', 'Experience Princess Minerva in English on the SNES.', 'A 16-bit JRPG with a focus on character interactions and equipment management. The fan translation makes this colorful, anime-styled adventure accessible to everyone.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Putty Squad (Europe)', '1994', NaN, 'System 3', '1', NaN, 'Turn-based RPG with an all-female cast and tactical combat.', 'Build your party and save the kingdom in the original release.', 'Play Princess Minerva on the Super Famicom.', 'Features vibrant 16-bit pixel art and a humorous tone. A classic RPG experience that emphasizes party balance and strategic turn-based encounters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Puzzle Bobble - Bust-A-Move (Europe)', '1994', NaN, 'Taito', '2', NaN, 'Fan-made Mario World hack where Princess Peach is the hero.', 'Rescue Mario and save the kingdom with the Cape Feather.', 'Play Princess now hero With Cape on the SNES.', 'A creative 16-bit romhack that swaps the roles. Use Peach''s unique flight mechanics with the Cape to navigate challenging custom-designed Mario World levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Puzzle Bobble (Japan)', '1994', NaN, 'Taito', '2', NaN, 'Fan-made Mario World hack where Princess Peach is the hero.', 'Rescue Mario while using the power of the Super Leaf.', 'Play Princess now hero With Super Leaf on the SNES.', 'A 16-bit modification that introduces the Raccoon suit for Peach. Features custom level design focused on vertical exploration and floating mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Puzzle''n Desu! (Japan)', '1995', NaN, 'Nintendo', '2', NaN, 'Professional American football simulation (1993 rosters).', 'Win the championship in the refined Japanese version.', 'Play Pro Football ''93 on the Super Famicom.', 'Features official 16-bit team logos and updated player stats for the ''93 season. A solid simulation with a focus on tactical play-calling and seasonal tracking.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Q-bert 3 (Japan)', '1993', NaN, 'Realtime Associates', '2', NaN, 'Professional American football simulation.', 'Lead your team to the Super Bowl in this 16-bit sim.', 'Experience Pro Football on the Super Famicom.', 'The foundational 16-bit football title for the Japanese market. Features a comprehensive playbook and realistic player attributes for the early 90s era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Q-bert 3 (USA)', '1993', NaN, 'Realtime Associates', '2', NaN, 'Professional Shogi (Japanese Chess) life simulation.', 'Climb the ranks of the pro Shogi world and become a master.', 'Play Shougi no Hanamichi on the Super Famicom.', 'A unique 16-bit blend of strategy and RPG elements. Manage your career, practice matches, and face legendary opponents in high-stakes Shogi tournaments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'R-Type III - The Third Lightning (Europe)', '1993', NaN, 'Irem', '1', NaN, 'Professional Mahjong simulation with high-level AI.', 'Master the tiles and defeat the professional Mahjong masters.', 'Play Pro Mahjong Kiwame on the Super Famicom.', 'A 16-bit simulation designed for serious players. Features multiple rule sets, detailed statistical tracking, and a challenging tournament mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'R-Type III - The Third Lightning (Europe) (Beta)', '1993', NaN, 'Irem', '1', NaN, 'Professional Mahjong simulation sequel.', 'Win the national tournament in this expanded Mahjong sim.', 'Experience Pro Mahjong Kiwame II on the Super Famicom.', 'Features improved 16-bit graphics and more sophisticated AI. Includes a variety of professional opponents and refined tutorials for mastering advanced strategies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'R-Type III - The Third Lightning (Japan)', '1993', NaN, 'Irem', '1', NaN, 'Professional Mahjong simulation sequel (Updated Revision).', 'Master the tiles in this polished 16-bit revision.', 'Play Pro Mahjong Kiwame II (Rev A) on the SNES.', 'An updated 16-bit revision that optimizes the AI decision speed and fixes minor graphical bugs in the tournament menu screens.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'R-Type III - The Third Lightning (USA)', '1993', NaN, 'Irem', '1', NaN, 'The third installment in the professional Mahjong series.', 'Prove your skill as the ultimate Mahjong professional.', 'Challenge Pro Mahjong Kiwame III on the Super Famicom.', 'The most refined 16-bit entry in the Kiwame series. Features a massive roster of opponents and the most advanced Mahjong engine on the console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Race Drivin'' (Europe)', '1994', NaN, 'Atari Games', '1', NaN, 'Competitive Mahjong simulation focused on high-stakes play.', 'Win the Renka Ban tournament and claim the championship.', 'Play Pro Mahjong Tsuwamono on the Super Famicom.', 'A technical 16-bit Mahjong title that emphasizes competitive play and professional rules. Features a clean interface and challenging AI opponents.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Race Drivin'' (USA)', '1994', NaN, 'Atari Games', '1', NaN, 'Competitive Mahjong simulation with a focus on strategy.', 'Master the professional Mahjong circuit in Japan.', 'Experience Pro Mahjong Tsuwamono on the Super Famicom.', 'A comprehensive 16-bit gambling sim. Includes various modes to test your luck and skill against the computer or friends in authentic Mahjong matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Radiation''s Halloween Hack: Bad Fur Day Edition', '2021', NaN, 'Homebrew', '1', NaN, 'American football simulation featuring quarterback-specific challenges.', 'Win the Super Bowl or dominate the QB skills challenge.', 'Play Pro Quarterback for the Super Nintendo.', 'A 16-bit football title that emphasizes the passing game. Includes a unique training mode to improve your accuracy and a full seasonal play mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Radical Dreamers - Nusume Nai Houseki (Japan) (BS) [En by Demiforce v1.2] [Fix by Radical R] (~Radical Dreamers - Le Tresor Interdit)', '1996', NaN, 'Square', '1', NaN, 'Fast-paced arcade soccer simulation.', 'Win the world cup with smooth passing and powerful shots.', 'Experience Pro Soccer on the Super Famicom.', 'Features a vertical perspective and fluid 16-bit animations. A high-energy sports title that focuses on arcade-style action and quick transitions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Radical Dreamers - Nusume Nai Houseki (Japan) (BS) [En by Demiforce v1.4] (~Radical Dreamers - Le Tresor Interdit)', '1996', NaN, 'Square', '1', NaN, 'Ice hockey simulation with a focus on speed and hard hits.', 'Lead your team to the trophy in this technical hockey sim.', 'Play Pro Sport Hockey for the Super Nintendo.', 'A 16-bit hockey game with a focus on physical play. Features deep customization, realistic penalty calls, and a fast-paced seasonal mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Radical Psycho Machine Racing (Japan)', '1994', NaN, 'Interplay', '2', NaN, 'Isometric combat racing featuring car upgrades and 3D tracks.', 'Win the intergalactic racing season through combat and speed.', 'Play the high-octane RPM Racing on the Super Famicom.', 'The direct predecessor to Rock N'' Roll Racing. Features 16-bit isometric tracks with elevation, car customization, and a robust level editor for creating your own chaotic race circuits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Radical Psycho Machine Racing (USA)', '1994', NaN, 'Interplay', '2', NaN, 'Isometric combat racing with a focus on vehicle customization.', 'Defeat your rivals in this technical 16-bit racer.', 'Experience RPM Racing on the Super Nintendo.', 'A landmark 16-bit title from Silicon & Synapse (Blizzard). Master the terrain-heavy tracks and use prize money to upgrade engines and tires to dominate the season.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Radical Rex (Europe)', '1994', NaN, 'Beam Software', '1', NaN, 'Side-scrolling platformer starring a fire-breathing dinosaur.', 'Save the dinosaur race from extinction on your skateboard.', 'Join the adventure in Radical Rex on the SNES.', 'A vibrant 16-bit platformer. Control Rex as he skateboards, breathes fire, and screams his way through prehistoric levels filled with catchy music and smooth animations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Radical Rex (USA)', '1994', NaN, 'Beam Software', '1', NaN, 'Side-scrolling platformer with a rebellious attitude.', 'Defeat the evil wizard Sethron in this 16-bit quest.', 'Experience Radical Rex for the Super Nintendo.', 'Master the 16-bit skateboarding physics and fire-breathing mechanics. Features large, colorful sprites and diverse prehistoric environments with a cool 90s aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Radical Rex (USA) (Beta)', '1994', NaN, 'Beam Software', '1', NaN, 'Side-scrolling platformer (Pre-release build).', 'Test early level layouts and dinosaur physics.', 'Check out the Radical Rex Beta on the SNES.', 'A rare 16-bit development look. Witness the fine-tuning of the skateboarding controls and the evolution of the jungle-themed backgrounds before the final release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Raiden Densetsu (Japan)', '1991', NaN, 'Seibu Kaihatsu', '2', NaN, 'Vertical-scrolling arcade shooter and port of the legendary Raiden.', 'Defend Earth from an alien invasion with the Raiden supersonic jet.', 'Play the legendary Raiden Densetsu on Super Famicom.', 'A faithful 16-bit port of the arcade icon. Features the classic red and blue weapon power-up system, massive bosses, and intense, screen-filling projectile action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Raiden Trad (USA)', '1991', NaN, 'Seibu Kaihatsu', '2', NaN, 'Vertical-scrolling arcade shooter with high-intensity combat.', 'Achieve the high score in this definitive 16-bit arcade port.', 'Experience Raiden Trad on the Super Nintendo.', 'Known for its perfectly balanced difficulty and responsive controls. Master the 16-bit bullet patterns and use powerful bombs to clear the screen of alien forces.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ramos Rui no World Wide Soccer (Japan)', '1994', NaN, 'Sega', '2', NaN, 'Professional soccer simulation featuring Japanese star Rui Ramos.', 'Win the world cup with expert strategy and passing.', 'Experience World Wide Soccer on the Super Famicom.', 'A polished 16-bit sports title. Features authentic team management, a variety of tactical formations, and smooth animations endorsed by the legendary soccer player.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Rampart (USA)', '1990', NaN, 'Atari Games', '2', NaN, 'Strategy and action hybrid involving castle defense and destruction.', 'Build your fortress and destroy the enemy''s walls.', 'Master the strategic Rampart on the Super Nintendo.', 'A unique 16-bit arcade port. Combine Tetris-style building with intense cannon-fire combat in a race to secure your territory and defeat invading fleets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 - Akanekodan Teki Hihou (Japan)', '1992', NaN, 'Fix', '1', NaN, 'Turn-based RPG based on the popular anime and manga.', 'Find the hidden treasure and solve the mystery of the Red Cat Gang.', 'Explore Ranma 1/2: Akanekodan on Super Famicom.', 'A charming 16-bit RPG featuring the full cast of characters. Experience a story-driven adventure with tactical combat that remains faithful to the humor and heart of the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 - Akanekodan Teki Hihou (Japan) [En by Naruto+Ranma Team v0.99] (~Ranma 1-2 - Treasure of the Red Cat Gang) (Manga Version)', '1992', NaN, 'Fix', '1', NaN, 'Turn-based RPG (English translation - Manga version).', 'Play Ranma''s quest in English with manga-accurate names.', 'Experience Ranma 1/2 RPG in English on the SNES.', 'The Naruto+Ranma Team translation makes this 16-bit gem accessible. Features original manga-style terminology and a deep narrative focused on the series'' iconic martial arts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 - Akanekodan Teki Hihou (Japan) [En by Naruto+Ranma Team v1.0] (~Ranma 1-2 - Treasure of the Red Cat Gang) (Anime Version)', '1992', NaN, 'Fix', '1', NaN, 'Turn-based RPG (English translation - Anime version).', 'Experience the Red Cat Gang mystery with anime-style text.', 'Play Ranma 1/2 RPG in English on the SNES.', 'The v1.0 translation update features localized names familiar to anime fans. Enjoy the 16-bit tactical battles and comedic dialogue in your own language.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 - Bakuretsu Rantou Hen (Japan)', '1992', NaN, 'Atelier Double', '2', NaN, 'One-on-one fighting game with a diverse cast of martial artists.', 'Win the tournament in this fast-paced 16-bit brawler.', 'Experience Ranma 1/2: Bakuretsu Rantou Hen on SNES.', 'Known as Hard Battle in the West. Features fluid 2D fighting, over-the-top special moves, and the ability to transform characters during combat as per the source material.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 - Chougi Ranbu Hen (Japan)', '1992', NaN, 'Atelier Double', '2', NaN, 'Advanced one-on-one fighting game with refined mechanics.', 'Master the ultimate moves and become the champion.', 'Play the polished Chougi Ranbu Hen on Super Famicom.', 'The third and most refined 16-bit fighter in the series. Features larger sprites, improved AI, and a more complex combo system for competitive martial arts action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 - Chounai Gekitou Hen (Japan)', '1993', NaN, 'Atelier Double', '2', NaN, 'The first fighting game in the Ranma 1/2 series for SNES.', 'Defeat your rivals in this foundational anime fighter.', 'Play Chounai Gekitou Hen on the Super Famicom.', 'A classic 16-bit brawler. Features iconic locations from the anime and a simple yet satisfying combat system that captures the frantic energy of Ranma''s world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 - Hard Battle (USA)', '1993', NaN, 'Atelier Double', '2', NaN, 'One-on-one fighting game (Western release).', 'Battle your way to victory in the official USA edition.', 'Experience Ranma 1/2: Hard Battle on the SNES.', 'A standout 16-bit anime fighter. Features localized voices and a balanced roster including Ranma, Ryoga, and Shampoo, each with unique and faithful special attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 - Ougi Jaanken (Japan)', '1993', NaN, 'Game Arts', '2', NaN, 'Puzzle-logic game featuring Jan-Ken-Pon (Rock, Paper, Scissors).', 'Defeat your rivals in this tactical Jan-Ken-Pon tournament.', 'Solve the puzzles in Ranma 1/2: Ougi Jaanken on SNES.', 'A unique 16-bit puzzle title. Use strategy and timing to win high-stakes matches against the series'' cast in a colorful and competitive format.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 (Europe)', '1992', NaN, 'Atelier Double', '2', NaN, 'One-on-one fighting game (European release).', 'Experience the chaotic martial arts in the official European version.', 'Play Ranma 1/2 on the Super Nintendo.', 'The PAL version of the acclaimed anime fighter. Master the jumps and special moves of the Tendo Dojo''s finest in this technically solid 16-bit brawler.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ranma 1-2 (France)', '1992', NaN, 'Atelier Double', '2', NaN, 'One-on-one fighting game (French localization).', 'Defeat the martial arts masters in the French edition.', 'Jouez à Ranma 1/2 sur le Super Nintendo.', 'The localized 16-bit release for French fans. Features the complete roster and balanced gameplay that made the series a cult favorite among fighting game enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Rap Basketball (USA) (Proto)', '1994', NaN, 'Unknown', '2', NaN, 'Hip-hop themed street basketball (Early prototype).', 'Test the early court physics and character sprites.', 'Explore the Rap Basketball Proto on the SNES.', 'A rare 16-bit development look at an unreleased project. Witness the early implementation of the urban aesthetic and the foundation of the 3-on-3 gameplay.', NULL);
