INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Rock n'' Roll Racing (USA)', '1993', NaN, 'Blizzard Entertainment', '4', NaN, 'Isometric combat racing with a heavy metal soundtrack.', 'Dominate the galaxy and leave your rivals in the dust.', 'Play the legendary Rock n'' Roll Racing on the SNES.', 'A definitive 16-bit multiplayer experience. Buy missiles, mines, and turbo boosts to survive the lethal tracks while the Supermouth calls every explosive turn.', NULL);
