INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Romancing SaGa 3 (Japan) [En by Mana Sword v0.30]', '1995', NaN, 'Square / Hack', '1', NaN, 'Polished open-world JRPG (English Translation v0.30).', 'Experience Sa-Ga 3''s complex narrative in English.', 'Play Romancing SaGa 3 English v0.30 on the SNES.', 'A functional 16-bit translation by Mana Sword. Allows players to navigate the menus and understand the core story of the eight heroes as they face the Abyss.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Royal Conquest (Japan)', '1992', NaN, 'Koei', '1', NaN, 'Turn-based strategy and fantasy war simulation.', 'Command your army to reclaim the kingdom in this tactical sim.', 'Experience Royal Conquest on the Super Famicom.', 'A grid-based 16-bit strategy title. Manage units, terrain advantage, and magical abilities in a series of increasingly difficult battles to restore peace to a divided land.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'RPG Tsukuru - Super Dante (Japan)', '1995', NaN, 'ASCII', '1', NaN, 'Creative game-making utility for the SNES.', 'Design and play your own custom 16-bit RPG.', 'Build your dream game with RPG Tsukuru on the SNES.', 'The foundational RPG Maker for home consoles. Use pre-set tiles, characters, and a simplified event system to create your own fantasy adventures directly on your Super Famicom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'RPG Tsukuru - Super Dante (Japan) [En by MageCraft v0.90] (~RPG Maker - Super Dante) (Incomplete)', '1995', NaN, 'ASCII / Hack', '1', NaN, 'Creative game-making utility (English Translation).', 'Create your own 16-bit RPG with English menus.', 'Experience RPG Maker: Super Dante in English on SNES.', 'A 16-bit fan translation that makes the game-creation tools accessible to Western players. Design maps, script dialogue, and create custom combat encounters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'RPG Tsukuru 2 (Japan)', '1996', NaN, 'ASCII', '1', NaN, 'Advanced game-making utility with expanded assets.', 'Create more complex RPGs with new tools and animations.', 'Explore the power of RPG Tsukuru 2 on the Super Famicom.', 'The 16-bit sequel to Super Dante. Features significantly more memory for assets, improved event scripting, and a wider variety of monster and environment designs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Rudra no Hihou (Japan)', '1996', NaN, 'Square', '1', NaN, 'Cinematic JRPG with a unique Mantra magic system.', 'Save the world from destruction in the final 15 days.', 'Experience the stunning Rudra no Hihou on the SNES.', 'One of the most visually impressive 16-bit RPGs. Features three interlocking stories and a magic system where you write your own spells to determine their effects.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Rudra no Hihou (Japan) [En by Aeon Genesis v2.0] (~Treasure of the Rudras)', '1996', NaN, 'Square / Hack', '1', NaN, 'Cinematic JRPG (Full English Translation v2.0).', 'Experience the Treasure of the Rudras in English.', 'Play Rudra no Hihou in English on the Super Nintendo.', 'The definitive 16-bit translation by Aeon Genesis. Fully localized the complex Mantra system and narrative, allowing players to enjoy Square''s late-gen masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ruin Arm (Japan)', '1996', NaN, 'Taito', '1', NaN, 'Fantasy Action-RPG with a focus on weapon switching.', 'Recover the legendary Ruin Arm and stop the dark cult.', 'Explore the world of Ruin Arm on the Super Famicom.', 'A fast-paced 16-bit adventure. Features a unique system where your character''s abilities change based on the weapons equipped, blending exploration with tactical real-time combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Run Saber (Europe)', '1993', NaN, 'Hori Electric', '1', NaN, 'Cyberpunk side-scrolling action-platformer.', 'Stop the evil genetic experiments of Bruhl across the globe.', 'Experience the high-speed Run Saber on the SNES.', 'A frantic 16-bit action game similar to Strider. Choose between Allen or Sheena, using energy blades and acrobatic moves to destroy massive bosses in futuristic settings.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Run Saber (USA)', '1993', NaN, 'Hori Electric', '1', NaN, 'Cyberpunk side-scrolling action-platformer.', 'Defeat the biotechnical menace in the official USA edition.', 'Play the action-packed Run Saber on the Super Nintendo.', 'Features incredible 16-bit fluid animation and a great 2-player co-op mode. Navigate through high-speed levels including a moving jet and a vertical industrial tower.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Rushing Beat (Japan)', '1992', NaN, 'Jaleco', '2', NaN, 'Urban side-scrolling beat ''em up (First in the trilogy).', 'Rescue your sister and clean up the streets of Neo-Cisco.', 'Fight for justice in Rushing Beat on the Super Famicom.', 'Known as Rival Turf in the West. A foundational 16-bit brawler featuring two playable heroes and a gritty urban atmosphere inspired by arcade classics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Rushing Beat Ran - Fukusei Toshi (Japan)', '1992', NaN, 'Jaleco', '2', NaN, 'Urban side-scrolling beat ''em up (Second in the trilogy).', 'Stop the cloning conspiracy in the city of clones.', 'Play the intense Rushing Beat Ran on the Super Famicom.', 'Known as Brawl Brothers in the West. Features an expanded move set and a Fury mode. Explore sprawling 16-bit levels that branch based on your performance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Rushing Beat Shura (Japan)', '1993', NaN, 'Jaleco', '2', NaN, 'The final and most complex entry in the Rushing Beat series.', 'Dismantle the Shura organization in this non-linear brawler.', 'Experience Rushing Beat Shura on the Super Famicom.', 'Known as The Peace Keepers in the West. Features four playable characters, branching paths, and multiple endings, making it one of the deepest 16-bit beat ''em ups.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ryuuki Heidan Danzarb (Japan)', '1993', NaN, 'Konami', '1', NaN, 'Sci-fi JRPG featuring mecha-dragon combat.', 'Lead the Dragon Squadron Danzarb against the alien threat.', 'Experience Ryuuki Heidan Danzarb on the Super Famicom.', 'A unique 16-bit hybrid. Combines traditional JRPG exploration with tactical turn-based battles where your party pilots powerful bio-mechanical dragon units.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ryuuki Heidan Danzarb (Japan) [En by Aeon Genesis v1.0] (~Dragon Squadron Danzarb)', '1993', NaN, 'Konami / Hack', '1', NaN, 'Sci-fi JRPG (Full English Translation v1.0).', 'Experience the Dragon Squadron story in English.', 'Play Danzarb in English on the Super Nintendo.', 'The Aeon Genesis 16-bit fan translation. Brings the complex story of military intrigue and bio-mechanical warfare to English-speaking audiences for the first time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ryuuko no Ken (Japan)', '1992', NaN, 'SNK', '2', NaN, 'One-on-one fighting game featuring huge character sprites.', 'Master the Kyokugenryu Karate and rescue Yuri Sakazaki.', 'Experience Art of Fighting on the Super Famicom.', 'The official 16-bit Japanese release of the Neo-Geo hit. Features the legendary zoom-in effect, large sprites, and a stamina-based spirit meter for special moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ryuuko no Ken 2 (Japan)', '1994', NaN, 'SNK', '2', NaN, 'One-on-one fighting game sequel with refined mechanics.', 'Win the King of Fighters tournament in the official sequel.', 'Play Art of Fighting 2 on the Super Famicom.', 'An improved 16-bit fighter featuring a larger roster, including the younger version of Geese Howard. Features refined combo mechanics and improved graphical detail.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Saibara Rieko no Mahjong Hourouki (Japan)', '1992', NaN, 'Nichibutsu', '1', NaN, 'Traditional Mahjong simulation based on the manga artist''s work.', 'Win the Mahjong circuit featuring Saibara Rieko''s characters.', 'Play Saibara Rieko no Mahjong on the Super Famicom.', 'A 16-bit Mahjong title featuring the unique and humorous art style of Saibara Rieko. Includes a story mode and various professional rules for enthusiasts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Saikousoku Shikou - Shougi Mahjong (Japan)', '1993', NaN, 'Nihon Bussan', '2', NaN, 'Dual-discipline board game simulation (Shogi and Mahjong).', 'Master both traditional Japanese games in one collection.', 'Experience Shougi Mahjong on the Super Famicom.', 'A 16-bit strategic package featuring high-speed AI for both Shogi and Mahjong. Perfect for players looking for a comprehensive mental challenge on one cartridge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Saikyou - Takada Nobuhiko (Japan)', '1993', NaN, 'Hudson Soft', '2', NaN, 'Professional wrestling simulation featuring Nobuhiko Takada.', 'Climb the ranks of the MMA world and become a champion.', 'Experience Saikyou: Takada Nobuhiko on the Super Famicom.', 'A technical 16-bit wrestling game focused on the Strong Style of Nobuhiko Takada. Features a stamina system and realistic grappling mechanics inspired by PRIDE and UWFi.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sailor Moon Fighter S', '1995', NaN, 'Fan Hack', '2', NaN, 'Fan-made fighting game based on the Sailor Moon universe (Hack).', 'Defeat the Negaverse in this enhanced 16-bit fighter.', 'Play Sailor Moon Fighter S on the Super Nintendo.', 'A technical 16-bit modification of the Sailor Moon fighting engine. Includes rebalanced characters, new move priorities, and refined hitboxes for competitive play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sailor Moon Fighter S (Purist Edition)', '1995', NaN, 'Fan Hack', '2', NaN, 'Fan-made fighting game (Balanced Purist Edition Hack).', 'Experience a tournament-ready version of Sailor Moon fighting.', 'Try Sailor Moon Fighter S Purist on the SNES.', 'A specialized 16-bit romhack focused on competitive balance. Removes game-breaking bugs and standardizes damage scaling for a more professional fighting experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sailormoon (France)', '1994', NaN, 'Banpresto', '2', NaN, 'Side-scrolling beat ''em up based on the iconic anime.', 'Save Tokyo from the Dark Kingdom as the Sailor Scouts.', 'Play the official Sailormoon on the Super Nintendo.', 'The 16-bit French release of the classic brawler. Choose from the five original scouts and use their signature magical attacks to defeat waves of enemies and bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sakurai Shouichi no Jankiryuu - Mahjong Hisshouhou (Japan)', '1992', NaN, 'Nichibutsu', '1', NaN, 'Educational Mahjong simulation based on the Jankiryuu style.', 'Learn the winning strategies of the Mahjong master Sakurai.', 'Master Mahjong with Sakurai Shouichi on Super Famicom.', 'A technical 16-bit guide to the Jankiryuu way of play. Features advanced tutorials, strategic analysis, and practice modes endorsed by the legend himself.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Same Game (Japan)', '1992', NaN, 'Hudson Soft', '2', NaN, 'Relaxing and addictive tile-clearing puzzle game.', 'Clear the entire board by matching adjacent identical tiles.', 'Play the classic Same Game on the Super Famicom.', 'A simple yet deep 16-bit puzzle title. Strategic planning is required to clear large clusters of blocks and achieve the elusive perfect clear bonus.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Samurai Shodown (Europe)', '1993', NaN, 'SNK', '2', NaN, 'Weapon-based fighting game with large sprites and zoom effects.', 'Master the blade and defeat the sorcerer Amakusa.', 'Experience the epic Samurai Shodown on the SNES.', 'A faithful 16-bit port of the SNK arcade hit. Features the legendary zoom-in camera, high-damage weapon strikes, and the unique Rage meter system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Samurai Shodown (USA)', '1993', NaN, 'SNK', '2', NaN, 'Weapon-based fighting game with a diverse roster of warriors.', 'Claim your honor in this legendary 16-bit sword fighter.', 'Play the classic Samurai Shodown on the Super Nintendo.', 'Features iconic characters like Haohmaru and Nakoruru. Master the parry mechanics and disarming moves in this high-stakes 16-bit battle for supremacy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Samurai Spirits (Japan)', '1993', NaN, 'SNK', '2', NaN, 'Weapon-based fighting game (Original Japanese release).', 'Experience the authentic spirit of the Samurai in Japan.', 'Play Samurai Spirits on the Super Famicom.', 'The original 16-bit Japanese version of the groundbreaking fighter. Includes full character endings and the atmospheric soundtrack that defined the Edo-period aesthetic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Samurai Spirits (Japan) (Beta)', '1993', NaN, 'SNK', '2', NaN, 'Weapon-based fighting game (Pre-release build).', 'Test the early collision boxes and weapon sprite layers.', 'Check out the Samurai Spirits Beta on the SNES.', 'A rare 16-bit development look. Witness the early implementation of the background scaling and the balancing of the heavy slash damage before the final release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sandro no Daibouken - Valkyrie Tono Deai (Japan)', '1992', NaN, 'NCS / Enix', '1', NaN, 'Action-platformer and prequel to the Valkyrie series.', 'Meet the Valkyrie and embark on a magical 16-bit quest.', 'Experience Sandro no Daibouken on the Super Famicom.', 'Known as Whirlo in Europe. A challenging 16-bit platformer featuring vibrant graphics and complex jumping mechanics. Follow the journey of Sandro as he seeks his destiny.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sangokushi Eiketsuden (Japan)', '1995', NaN, 'Koei', '1', NaN, 'Tactical JRPG based on the Three Kingdoms period.', 'Lead Liu Bei''s forces to unify China through strategy.', 'Experience Sangokushi Eiketsuden on the Super Famicom.', 'A 16-bit strategic RPG from Koei. Focuses on individual character growth and tactical grid-based battles during the legendary historical era of ancient China.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sangokushi III (Hong Kong)', '1993', NaN, 'Koei', '1', NaN, 'Grand strategy simulation (Hong Kong localized version).', 'Conquer the mainland in the official Chinese edition.', 'Play Sangokushi III on the Super Famicom.', 'The 16-bit Hong Kong release of Romance of the Three Kingdoms III. Features localized text and the same deep diplomatic and military simulation of the original.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sangokushi III (Japan)', '1993', NaN, 'Koei', '1', NaN, 'Grand strategy simulation (Original Japanese release).', 'Unify the warring states in this 16-bit strategic epic.', 'Experience Sangokushi III on the Super Famicom.', 'A landmark 16-bit entry for the series in Japan. Manage officers, resources, and large-scale armies in a turn-based quest for total dominance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sangokushi III (Japan) (Rev A)', '1993', NaN, 'Koei', '1', NaN, 'Grand strategy simulation (Updated Revision).', 'Master the refined tactical maps in this 16-bit revision.', 'Play Sangokushi III (Rev A) on the Super Famicom.', 'An updated 16-bit version that fixes minor AI pathfinding bugs and optimizes the seasonal transition events for a more stable grand strategy experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sangokushi IV (Japan)', '1994', NaN, 'Koei', '1', NaN, 'Advanced grand strategy with enhanced siege mechanics.', 'Claim the throne in the most detailed entry of the series.', 'Experience Sangokushi IV on the Super Famicom.', 'Features improved 16-bit graphics and a deeper focus on technological research and naval warfare. A comprehensive simulation of the Three Kingdoms power struggle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sangokushi Seishi - Tenbu Spirits (Japan)', '1995', NaN, 'Koei', '1', NaN, 'Strategy-RPG hybrid with a focus on historical accuracy.', 'Follow the true history of the Han Dynasty''s fall.', 'Experience Tenbu Spirits on the Super Famicom.', 'A unique 16-bit take on the Three Kingdoms story. Blends historical text-based events with tactical combat, emphasizing the personal stories of the legendary generals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sankyo Fever! Fever! (Japan)', '1993', NaN, 'Sankyo', '1', NaN, 'Pachinko simulation featuring the popular Sankyo machines.', 'Master the Fever! machines to trigger virtual jackpots.', 'Play Sankyo Fever! Fever! on the Super Famicom.', 'A technical 16-bit recreation of real Japanese Pachinko tables. Features accurate ball physics and detailed digital representations of the Sankyo brand''s mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sanrio Shanghai (Japan)', '1992', NaN, 'Imagineer', '2', NaN, 'Tile-matching puzzle game featuring Sanrio characters.', 'Solve the Shanghai puzzles with Hello Kitty and friends.', 'Play Sanrio Shanghai on the Super Famicom.', 'A charming 16-bit version of the classic Mahjong Solitaire. Clear the board to unlock cute illustrations and backgrounds featuring the beloved Sanrio cast.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sanrio World Smash Ball! (Japan)', '1993', NaN, 'Game Freak', '2', NaN, 'Fast-paced competitive sports game with Sanrio mascots.', 'Score goals by smashing the ball past your opponent.', 'Play Sanrio World Smash Ball! on the Super Famicom.', 'A frantic 16-bit competitive gem. Choose your character and use power shots in various themed arenas. Widely considered one of the best 2-player games on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sanrio World Smash Ball! (Japan) [En by Suicidal v1.0]', '1993', NaN, 'Game Freak / Hack', '2', NaN, 'Competitive sports game (Full English Translation).', 'Join Hello Kitty in this addictive 16-bit sports title.', 'Play Sanrio World Smash Ball! in English on SNES.', 'The fan translation makes the menus and power-up descriptions accessible. Experience the high-speed Pong-on-steroids gameplay in your own language.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sansara Naga 2 (Japan)', '1993', NaN, 'Asmik Ace', '1', NaN, 'Monster-breeding JRPG with a unique reincarnation system.', 'Raise your dragon and survive the cycle of life and death.', 'Explore the world of Sansara Naga 2 on Super Famicom.', 'A visually striking 16-bit RPG. Features character designs by Tamakichi Sakura and a deep system where you nurture a dragon partner to assist you in turn-based combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sanspo Fishing - Keiryuu Ou (Japan)', '1994', NaN, 'Pack-In-Video', '1', NaN, 'Realistic mountain stream fishing simulation.', 'Catch the legendary King of the Stream in beautiful Japan.', 'Go fishing in Keiryuu Ou on the Super Famicom.', 'A technical 16-bit fishing sim. Master the art of fly-fishing in serene mountain environments, managing lure types and line tension to land the perfect catch.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Satellaview BS-X (Japan) (Rev AB)', '1995', NaN, 'Nintendo', '1', NaN, 'Interactive BIOS and town hub for the Satellaview peripheral.', 'Explore the digital city of Lurendre to download games.', 'Experience the BS-X Satellaview on the Super Famicom.', 'A piece of 16-bit history. This interactive interface allowed Japanese players to walk through a town to access episodic content and games broadcast via satellite.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Saturday Night Slam Masters (Europe)', '1993', NaN, 'Capcom', '2', NaN, 'Wrestling and fighting hybrid with Capcom''s signature style.', 'Become the champion of the BWA and defeat the rival stars.', 'Play Saturday Night Slam Masters on the SNES.', 'A high-energy 16-bit brawler. Features character designs by Tetsuo Hara (Fist of the North Star) and a deep combat system that blends grappling with traditional fighting game moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Saturday Night Slam Masters (USA)', '1993', NaN, 'Capcom', '2', NaN, 'Wrestling and fighting hybrid starring Mike Haggar.', 'Claim the world title in this explosive 16-bit fighter.', 'Experience Saturday Night Slam Masters on the SNES.', 'One of the most unique 16-bit sports-combat titles. Use ropes, turnbuckles, and special moves to knock out opponents in this frantic 2-player competitive classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Scooby-Doo Mystery (USA)', '1995', NaN, 'Sculptured Software', '1', NaN, 'Point-and-click adventure based on the classic cartoon.', 'Solve spooky mysteries with Shaggy and Scooby.', 'Play Scooby-Doo Mystery on the Super Nintendo.', 'A charming 16-bit adventure game. Solve puzzles and find clues in four different cases, featuring the original voice cast''s likeness and the show''s signature humor and art style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD F-1 Grand Prix (Japan)', '1994', NaN, 'Video System', '1', NaN, 'Kart-style racing game with SD anime characters.', 'Win the Grand Prix in these high-speed chibi races.', 'Experience SD F-1 Grand Prix on the Super Famicom.', 'A fast-paced 16-bit racer featuring characters from various anime. Use power-ups and master the drifting mechanics on colorful tracks inspired by professional F1 circuits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD F-1 Grand Prix (Japan) (Sample)', '1994', NaN, 'Video System', '1', NaN, 'Kart-style racing game (Development Sample).', 'Test the early kart physics and track layouts.', 'Check out the SD F-1 Grand Prix Sample on SNES.', 'A rare 16-bit development look. Witness the early implementation of the character selection screen and the tuning of the AI''s racing lines before the final release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam - Power Formation Puzzle (Japan)', '1995', NaN, 'Bandai', '2', NaN, 'Competitive block-matching puzzle game with Gundam themes.', 'Defeat your opponent in the puzzle arena with Mobile Suits.', 'Play SD Gundam: Power Formation Puzzle on SNES.', 'A frantic 16-bit puzzle title. Match colored energy blocks to trigger powerful Gundam attacks and clear your board while hindering your rival in split-screen combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam G-Next (Japan) (Rev 0A)', '1995', NaN, 'Bandai', '1', NaN, 'Grand strategy simulation set in the Gundam universe.', 'Dominate the galaxy through military tactics and research.', 'Master strategy in SD Gundam G-Next on Super Famicom.', 'An advanced 16-bit strategy title. Command vast fleets of Mobile Suits, manage base resources, and engage in tactical grid-based combat across multiple star systems.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam Gaiden - Knight Gundam Monogatari - Ooinaru Isan (Japan)', '1990', NaN, 'Bandai', '1', NaN, 'Turn-based JRPG featuring the Knight Gundam fantasy setting.', 'Lead Knight Gundam on an epic quest to save the kingdom.', 'Explore Knight Gundam Monogatari on the Super Famicom.', 'A unique 16-bit RPG that reimagines Gundam suits as medieval knights. Features traditional turn-based combat, party management, and a rich fantasy world inspired by the SD Gaiden series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam Gaiden - Knight Gundam Monogatari - Ooinaru Isan (Japan) (Rev A)', '1990', NaN, 'Bandai', '1', NaN, 'Turn-based JRPG (Updated Revision).', 'Experience the Knight Gundam saga with refined mechanics.', 'Play Knight Gundam Monogatari (Rev A) on Super Famicom.', 'An updated 16-bit revision that fixes minor script bugs and optimizes the battle transition speeds for a smoother role-playing experience in the Lacroan kingdom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam Gaiden 2 - Entaku no Kishi (Japan)', '1991', NaN, 'Bandai', '1', NaN, 'Turn-based JRPG sequel with the Knights of the Round Table.', 'Unify the knights and defeat the dark forces of Zeon.', 'Experience SD Gundam Gaiden 2 on the Super Famicom.', 'The 16-bit sequel featuring the Entaku no Kishi (Knights of the Round Table) arc. Offers expanded party systems and more detailed battle animations than its predecessor.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam Generation - Axis Senki (Japan) (ST)', '1992', NaN, 'Bandai', '1', NaN, 'Tactical strategy game for the Sufami Turbo (Axis War).', 'Win the Axis conflict using specialized Mobile Suits.', 'Play SD Gundam Generation: Axis Senki on SNES.', 'A specialized 16-bit strategy title for the Sufami Turbo accessory. Focuses on the battles of the Neo Zeon era with compact, tactical gameplay loops.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam Generation - Babylonia Kenkoku Senki (Japan) (ST)', '1992', NaN, 'Bandai', '1', NaN, 'Tactical strategy game for the Sufami Turbo (Babylonia).', 'Establish the Cosmo Babylonia empire through conquest.', 'Experience Babylonia Kenkoku Senki on the SNES.', 'A 16-bit ST release focusing on the Gundam F91 era. Manage your units across various mission maps and engage in quick, turn-based combat scenarios.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam Generation - Colony Kakutouki (Japan) (ST)', '1992', NaN, 'Bandai', '1', NaN, 'Tactical strategy game for the Sufami Turbo (Colony).', 'Fight for colony independence in this tactical sim.', 'Play SD Gundam Generation: Colony Kakutouki on SNES.', 'An ST-specific 16-bit title focusing on Mobile Fighter G Gundam. Features tournament-style combat and strategic unit placement in various space and Earth arenas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam Generation - Gryps Senki (Japan) (ST)', '1992', NaN, 'Bandai', '1', NaN, 'Tactical strategy game for the Sufami Turbo (Gryps).', 'Lead the AEUG or Titans to victory in the Gryps War.', 'Experience Gryps Senki on the Super Famicom.', 'A 16-bit ST entry covering the events of Zeta Gundam. Command iconic Mobile Suits like the Hyaku Shiki and Zeta in tactical skirmishes against the Titans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam Generation - Ichinen Sensouki (Japan) (ST)', '1992', NaN, 'Bandai', '1', NaN, 'Tactical strategy game for the Sufami Turbo (One Year War).', 'Relive the original Gundam conflict in this ST edition.', 'Play SD Gundam Generation: Ichinen Sensouki on SNES.', 'A 16-bit strategy game focusing on the classic 0079 story. Command the White Base crew and defeat the Zeon forces in tactical, grid-based missions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam Generation - Zanscare Senki (Japan) (ST)', '1992', NaN, 'Bandai', '1', NaN, 'Tactical strategy game for the Sufami Turbo (Zanscare).', 'Stop the Zanscare Empire in this high-stakes strategy sim.', 'Experience Zanscare Senki on the Super Famicom.', 'A 16-bit ST release focusing on Victory Gundam. Features advanced unit types and challenging scenarios based on the late-Universal Century conflict.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Gundam GX (Japan)', '1994', NaN, 'Bandai', '2', NaN, 'Advanced tactical strategy with large-scale fleet combat.', 'Conquer the solar system in this deep Gundam sim.', 'Master the galaxy in SD Gundam GX on Super Famicom.', 'A technically impressive 16-bit strategy title. Features hundreds of units, a sophisticated AI, and real-time combat elements during individual unit encounters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Hiryuu no Ken (Japan)', '1993', NaN, 'Culture Brain', '2', NaN, '2D fighting game featuring SD-style martial artists.', 'Win the world tournament using powerful secret techniques.', 'Play SD Hiryuu no Ken on the Super Famicom.', 'A colorful 16-bit fighter. Features a unique target combat system where you must hit specific points on the opponent to trigger massive damage and special moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Kidou Senshi Gundam - V Sakusen Shidou (Japan)', '1992', NaN, 'Bandai', '1', NaN, 'Side-scrolling action-shooter based on the first Gundam series.', 'Destroy the Zeon forces and complete Operation V.', 'Experience SD Gundam: V Sakusen Shidou on SNES.', 'A fast-paced 16-bit action title. Control the RX-78-2 Gundam through various stages based on the original anime, fighting bosses like the Big Zam and Char''s Zaku.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Kidou Senshi Gundam 2 (Japan)', '1991', NaN, 'Bandai', '1', NaN, 'Side-scrolling action-shooter sequel with improved graphics.', 'Master the new Mobile Suits and save the Earth Federation.', 'Play SD Kidou Senshi Gundam 2 on the Super Famicom.', 'An expanded 16-bit sequel featuring more playable suits and smoother animations. Includes iconic levels and mecha from the Zeta and ZZ Gundam eras.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD The Great Battle - Aratanaru Chousen (English v1.0)', '1992', NaN, 'Banpresto', '2', NaN, 'Side-scrolling beat ''em up featuring SD heroes (English).', 'Join Ultraman, Gundam, and Kamen Rider to save the world.', 'Play SD The Great Battle in English on the SNES.', 'A legendary 16-bit crossover. This fan translation allows players to enjoy the first entry of the Compati Hero series, switching between iconic heroes to defeat evil.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD The Great Battle - Aratanaru Chousen (Japan)', '1992', NaN, 'Banpresto', '2', NaN, 'Side-scrolling beat ''em up crossover (Japanese release).', 'Experience the ultimate SD hero alliance in Japan.', 'Play SD The Great Battle on the Super Famicom.', 'A foundational 16-bit brawler. Navigate through diverse levels and use the unique abilities of each hero to overcome platforming challenges and massive boss fights.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Ultra Battle - Seven Densetsu (Japan) (ST)', '1993', NaN, 'Banpresto', '2', NaN, 'Tactical strategy game for the Sufami Turbo (Ultra Seven).', 'Defend Earth from alien kaiju as Ultra Seven.', 'Experience SD Ultra Battle: Seven Densetsu on SNES.', 'A specialized 16-bit ST title. Manage the Ultra Guard''s resources and deploy Ultra Seven to fight giant monsters in tactical, turn-based battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SD Ultra Battle - Ultraman Densetsu (Japan) (ST)', '1993', NaN, 'Banpresto', '2', NaN, 'Tactical strategy game for the Sufami Turbo (Ultraman).', 'Relive the legend of the original Ultraman in this ST sim.', 'Play SD Ultra Battle: Ultraman Densetsu on SNES.', 'A 16-bit strategy title focusing on the classic 1966 series. Defeat iconic monsters like Baltan and Red King using Ultraman''s signature energy attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SeaQuest DSV (Europe)', '1995', NaN, 'Imagineer', '1', NaN, 'Submarine combat and exploration sim based on the TV show.', 'Complete underwater missions and protect the UEO.', 'Dive into SeaQuest DSV for the Super Nintendo.', 'A unique 16-bit simulation. Manage your submarine''s systems while exploring the ocean floor, engaging in tactical combat, and launching remote probes to solve environmental puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SeaQuest DSV (USA)', '1995', NaN, 'Imagineer', '1', NaN, 'Submarine combat and exploration (North American release).', 'Command the SeaQuest through high-stakes ocean missions.', 'Experience SeaQuest DSV on the Super Nintendo.', 'Features impressive 16-bit underwater visuals and diverse mission types including rescue operations, deep-sea exploration, and intense torpedo combat against rival factions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Evermore (Europe)', '1995', NaN, 'Square', '1', NaN, 'Action-RPG with a unique alchemy system and time-travel theme.', 'Find your way home through the four realms of Evermore.', 'Play the cult classic Secret of Evermore on the SNES.', 'The only 16-bit RPG developed by Square USA. Explore prehistoric, antiquity, medieval, and futuristic worlds alongside your shape-shifting dog while mastering powerful alchemy spells.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Evermore (France)', '1995', NaN, 'Square', '1', NaN, 'Action-RPG (French localization).', 'Voyagez à travers Evermore dans cette version française.', 'Jouez à Secret of Evermore en français sur le SNES.', 'The complete 16-bit adventure with full French text. Features atmospheric music by Jeremy Soule and the same deep alchemy system that made the original a fan favorite.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Evermore (Germany)', '1995', NaN, 'Square', '1', NaN, 'Action-RPG (German localization).', 'Erlebe das Abenteuer von Evermore auf Deutsch.', 'Spielen Sie Secret of Evermore auf Deutsch für das SNES.', 'A fully localized 16-bit experience. Guide the hero and his canine companion through diverse eras, solving puzzles and battling bosses in a quest to return to Podunk.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Evermore (Spain)', '1995', NaN, 'Square', '1', NaN, 'Action-RPG (Spanish localization).', 'Explora el mundo de Evermore en español.', 'Disfruta de Secret of Evermore en español para el SNES.', 'One of the few 16-bit RPGs officially translated into Spanish. Experience the witty dialogue and cinematic story of a boy and his dog in this high-quality action-RPG.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Evermore (USA)', '1995', NaN, 'Square', '1', NaN, 'Action-RPG featuring real-time combat and canine partner.', 'Master the elements of alchemy to survive Evermore.', 'Experience the epic Secret of Evermore on the SNES.', 'Features a unique ring-menu system and real-time combat. A technical 16-bit achievement known for its incredible ambient sound design and vast, interconnected world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Evermore (USA) [Hack by FuSoYa v1.02] (2 Player Edition)', '1995', NaN, 'Square', '2', NaN, 'Action-RPG (2-Player Enhancement Hack).', 'Team up with a friend to control both the hero and the dog.', 'Play Secret of Evermore (2-Player) on the SNES.', 'A groundbreaking 16-bit fan modification. This hack allows a second player to take control of the dog, turning the solo adventure into a fully cooperative experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Evermore (USA) [Hack by FuSoYa v1.02] [Hack by Ninakoru v1.0] (Balance Enhancement - 2 Player Edition)', '1995', NaN, 'Square', '2', NaN, 'Action-RPG (Balance & 2-Player Enhancement Hack).', 'Experience a balanced cooperative journey through Evermore.', 'Try the Secret of Evermore Balance/2-Player Hack.', 'A 16-bit overhaul that combines cooperative play with rebalanced alchemy costs and enemy stats, providing a more challenging and fair experience for two players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Evermore (USA) [Hack by Ninakoru v1.0] (Balance Enhancement)', '1995', NaN, 'Square', '1', NaN, 'Action-RPG (Balance Enhancement Hack).', 'Test your skills with refined combat and alchemy mechanics.', 'Play Secret of Evermore (Balance Mod) on the SNES.', 'A technical 16-bit modification that tweaks spell damage and enemy AI. Designed for veterans seeking a fresh challenge in the world of Evermore without altering the story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Mana (Europe)', '1993', NaN, 'Square', '2', NaN, 'Landmark Action-RPG with 3-player cooperative play.', 'Save the Mana Tree and the world from the Empire.', 'Play the legendary Secret of Mana on the SNES.', 'One of the greatest 16-bit RPGs ever made. Features a beautiful watercolor art style, a real-time Ring Command menu, and an iconic soundtrack by Hiroki Kikuta.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Mana (Europe) (Rev 1) [Hack by Masterflow v1.02] (Hard Mode)', '1993', NaN, 'Square', '2', NaN, 'Action-RPG (Hard Mode Fan Modification).', 'Survive the ultimate challenge in this high-difficulty mod.', 'Play Secret of Mana (Hard Mode) on the Super Nintendo.', 'A 16-bit modification that increases enemy HP and aggression. Perfect for players who find the original game too easy and want to test their tactical mastery.', NULL);
