INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Mana (Europe) [Hack by Masterflow v1.02] (Hard Mode)', '1993', NaN, 'Square', '2', NaN, 'Action-RPG (Hard Mode Fan Modification).', 'Survive the ultimate challenge in this high-difficulty mod.', 'Play Secret of Mana (Hard Mode) on the Super Nintendo.', 'A 16-bit modification that increases enemy HP and aggression. Perfect for players who find the original game too easy and want to test their tactical mastery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Mana (France)', '1993', NaN, 'Square', '2', NaN, 'Action-RPG (French localization).', 'Sauvez l''arbre de Mana dans la version française.', 'Jouez à Secret of Mana en français sur le SNES.', 'The complete 16-bit masterpiece localized for French players. Experience the emotional journey of Randi, Primm, and Popoi with full French dialogue and menus.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Mana (France) (Rev A)', '1993', NaN, 'Square', '2', NaN, 'Action-RPG (French Updated Revision).', 'Vivez l''épopée de Mana dans cette version optimisée.', 'Découvrez Secret of Mana (Rev A) sur le SNES.', 'The updated 16-bit French release featuring minor corrections to the script and improved stability for the cooperative multiplayer mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Secret of Mana (Germany)', '1993', NaN, 'Square', '2', NaN, 'Action-RPG (German localization).', 'Rette die Welt von Mana in dieser deutschen Version.', 'Spielen Sie Secret of Mana auf Deutsch für das SNES.', 'A legendary 16-bit localization known for its unique (and sometimes controversial) German script. Experience the classic 3-player action in your own language.', NULL);
