INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Seifuku Densetsu Pretty Fighter (Japan)', '1994', NaN, 'SNK', '2', NaN, 'All-female 2D fighting game with anime aesthetics.', 'Win the tournament and prove your fighting spirit.', 'Play Seifuku Densetsu Pretty Fighter on SNES.', 'A colorful 16-bit fighter featuring high-school girls in diversas outfits. Features large sprites, special move transformations, and a lighthearted, comedic tone.', NULL);
