INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Seiken Densetsu 2 (Japan)', '1993', NaN, 'Square', '2', NaN, 'The original Japanese release of Secret of Mana.', 'Experience the foundational Mana magic in Japan.', 'Play Seiken Densetsu 2 on the Super Famicom.', 'The 16-bit masterpiece that popularized the Ring Command system. Known for its incredible technical use of the SNES hardware to deliver a seamless cooperative adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Seiken Densetsu 3 (Japan)', '1995', NaN, 'Square', '3', NaN, 'Epic Action-RPG with 6 playable characters and branching paths.', 'Choose three heroes and stop the God-Beasts.', 'Experience the stunning Seiken Densetsu 3 on SNES.', 'A 16-bit technical marvel. Features a day/night cycle, a class change system, and three distinct storylines depending on the main protagonist you choose.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Seiken Densetsu 3 (Japan) (Sample)', '1995', NaN, 'Square', '3', NaN, 'Action-RPG (Development Sample).', 'Test the early combat physics and character selection.', 'Check out the Seiken Densetsu 3 Sample on SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character introduction sequences and the tuning of the real-time battle engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Seiken Densetsu 3 (Japan) [En by LNF+Neill Corlett+SoM2Freak v1.01]', '1995', NaN, 'Square', '3', NaN, 'Action-RPG (Full English Translation v1.01).', 'Experience the unreleased Mana sequel in English.', 'Play Seiken Densetsu 3 in English on the SNES.', 'The legendary 16-bit fan translation. Brings the complex story and deep class system of the second Mana game to Western audiences for the first time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Seiken Densetsu 3 (Japan) [En by LNF+Neill Corlett+SoM2Freak v1.01] [Hack by Parlance v1.0] (3 Player Edition)', '1995', NaN, 'Square', '3', NaN, 'Action-RPG (English & 3-Player Enhancement Hack).', 'Play through the epic sequel with two friends in English.', 'Try Seiken Densetsu 3 (3-Player Mode) on SNES.', 'A 16-bit fan modification that unlocks the third player slot, allowing a full party to be controlled by humans. Perfect for the ultimate cooperative RPG session.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Seiken Densetsu 3 (Japan) [En by LNF+Neill Corlett+SoM2Freak v1.01] [Title Hack by Dragonsbrethren v1.0] (~Secret of Mana 2)', '1995', NaN, 'Square', '3', NaN, 'Action-RPG (English Translation with Secret of Mana 2 Title).', 'Play the sequel as if it were officially localized.', 'Experience Secret of Mana 2 (SD3) on the SNES.', 'A 16-bit fan translation that uses the Secret of Mana 2 title branding. Features the complete English script and optimized menus for a professional feel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sengoku Denshou (Japan)', '1993', NaN, 'SNK', '2', NaN, 'Side-scrolling beat ''em up with a supernatural theme.', 'Defeat the dark warriors across feudal and modern Japan.', 'Experience Sengoku Denshou on the Super Famicom.', 'A faithful 16-bit port of the Neo Geo arcade hit. Features the ability to transform into a wolf, a ninja, or a samurai to battle demonic forces across time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sengoku no Hasha - Tenkafubu e no Michi (Japan)', '1990', NaN, 'Koei', '1', NaN, 'Grand strategy simulation set in the Warring States period.', 'Unify Japan as a powerful Daimyo through war and diplomacy.', 'Play Sengoku no Hasha on the Super Famicom.', 'A deep 16-bit historical simulation. Manage your clan''s resources, forge alliances, and engage in tactical grid-based battles to claim the title of Shogun in feudal Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sensible Soccer - International Edition (Europe) (En,Fr,De,It)', '1994', NaN, 'Sensible Software', '2', NaN, 'Fast-paced top-down soccer with international teams.', 'Win the World Championship with agile passing and shooting.', 'Play Sensible Soccer: International Edition on SNES.', 'A 16-bit sports classic known for its zoomed-out perspective and ultra-responsive controls. Features hundreds of teams and a simplified, addictive approach to the beautiful game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sensible Soccer (Europe) (En,Fr,De,It)', '1994', NaN, 'Sensible Software', '2', NaN, 'Fast-paced top-down soccer simulation.', 'Master the curve shots and quick tackles in this 16-bit sim.', 'Experience the original Sensible Soccer on the SNES.', 'The foundational 16-bit entry for the series. Focuses on speed and tactical positioning, offering a pure arcade-style football experience that is easy to learn but hard to master.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sensible Soccer (Europe) (En,Fr,De,It) (Beta)', '1994', NaN, 'Sensible Software', '2', NaN, 'Top-down soccer simulation (Pre-release build).', 'Test the early player physics and ball-curving logic.', 'Check out the Sensible Soccer Beta on the SNES.', 'A rare 16-bit development look. Witness the fine-tuning of the sensitive control scheme and the initial implementation of the tournament menu structures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Septentrion (Japan)', '1993', NaN, 'Human Entertainment', '1', NaN, 'Cinematic survival adventure set on a sinking luxury liner.', 'Escape the ship before it capsizes and save as many survivors as possible.', 'Experience the intense Septentrion on Super Famicom.', 'Known as SOS in the West. Uses 16-bit Mode 7 effects to rotate the entire screen as the ship tilts, creating a terrifying and unique race against time and rising water.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Serizawa Nobuo no Birdie Try (Japan)', '1993', NaN, 'Naxat Soft', '1', NaN, 'Professional golf simulation featuring Nobuo Serizawa.', 'Master the greens and win the professional tournament circuit.', 'Play Serizawa Nobuo no Birdie Try on Super Famicom.', 'A technical 16-bit golf game. Features realistic wind physics, club selection, and detailed courses endorsed by the Japanese pro golfer Nobuo Serizawa.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sgt. Saunders'' Combat! (Japan)', '1993', NaN, 'ASCII', '1', NaN, 'Tactical military strategy based on the 1960s TV show.', 'Lead your squad through WWII missions in occupied France.', 'Play Sgt. Saunders'' Combat! on the Super Famicom.', 'A rare 16-bit tactical sim. Command a squad of soldiers in turn-based combat, managing cover, line-of-sight, and ammunition to complete dangerous objectives.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shadow, The (USA) (Proto) [50A3]', '1994', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling beat ''em up based on the pulp hero (Prototype).', 'Stop the criminal underworld as the mysterious Shadow.', 'Explore The Shadow Prototype on the SNES.', 'A rare 16-bit unreleased brawler. Features impressive character sprites and atmospheric urban levels where you use martial arts and dual pistols to fight crime.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shadow, The (USA) (Proto) [97E7]', '1994', NaN, 'Sunsoft', '1', NaN, 'Side-scrolling beat ''em up (Revised Prototype build).', 'Test the advanced combat moves and unreleased stage layouts.', 'Discover The Shadow (97E7 Proto) on the SNES.', 'An alternate 16-bit development build. Witness the evolution of the combat engine and the cinematic cutscenes based on the 1994 film adaptation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shadowrun (Europe)', '1993', NaN, 'FASA Interactive', '1', NaN, 'Isometric Action-RPG set in a gritty cyberpunk future.', 'Solve the mystery of your own murder in the sprawl of Seattle.', 'Experience the cult classic Shadowrun on the SNES.', 'A 16-bit masterpiece of atmosphere. Features a unique keyword dialogue system, hacking into the Matrix, and tactical real-time combat in a dark urban fantasy setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shadowrun (Germany)', '1993', NaN, 'FASA Interactive', '1', NaN, 'Isometric Action-RPG (German localization).', 'Erkunde die Cyberpunk-Welt von Shadowrun auf Deutsch.', 'Spielen Sie Shadowrun auf Deutsch für das SNES.', 'The complete 16-bit cyberpunk adventure with full German text. Navigate the dangerous streets as Jake Armitage and uncover a conspiracy involving megacorporations and magic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shadowrun (Japan)', '1993', NaN, 'FASA Interactive', '1', NaN, 'Isometric Action-RPG (Japanese release).', 'Experience the dark futuristic Seattle in the Japanese edition.', 'Play Shadowrun on the Super Famicom.', 'The official 16-bit Japanese release of this Western-developed RPG. Retains the gritty tone and deep investigative gameplay that made it a global cult favorite.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shadowrun (Sweden)', '1993', NaN, 'FASA Interactive', '1', NaN, 'Isometric Action-RPG (Swedish localization).', 'Upplev det mörka Shadowrun-äventyret på svenska.', 'Spela Shadowrun på svenska för Super Nintendo.', 'A rare 16-bit localization for the Swedish market. Features the same deep RPG mechanics and atmospheric storytelling translated for Nordic fans of the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shadowrun (USA)', '1993', NaN, 'FASA Interactive', '1', NaN, 'Isometric Action-RPG featuring magic and technology.', 'Master the Matrix and solve the conspiracy in 2050.', 'Experience the legendary Shadowrun on the SNES.', 'Known for its mature story and innovative gameplay. Use your 16-bit decking skills to hack computers and recruit mercenaries to survive the shadows.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shadowrun (USA) (Beta)', '1993', NaN, 'FASA Interactive', '1', NaN, 'Isometric Action-RPG (Pre-release build).', 'Test the early combat hitboxes and dialogue triggers.', 'Check out the Shadowrun Beta on the Super Nintendo.', 'A rare 16-bit development slice. Witness the early implementation of the karma system and the tuning of the real-time combat encounters in the morgue and street levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shanghai - Banri no Choujou (Japan)', '1991', NaN, 'Sunsoft', '2', NaN, 'Advanced Mahjong Solitaire simulation (Great Wall theme).', 'Clear the tile patterns to unlock beautiful Asian landscapes.', 'Play Shanghai: Banri no Choujou on Super Famicom.', 'A polished 16-bit puzzle title. Features multiple difficulty modes, high-quality tile art, and relaxing music, all centered around the theme of the Great Wall of China.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shanghai - Banri no Choujou (Japan) (Rev A)', '1991', NaN, 'Sunsoft', '2', NaN, 'Advanced Mahjong Solitaire (Updated Revision).', 'Master the tile layouts in this refined puzzle edition.', 'Experience Shanghai (Rev A) on the Super Famicom.', 'An updated 16-bit revision that optimizes tile-shuffling algorithms and fixes minor graphical glitches in the background art transitions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shanghai II - Dragon''s Eye (Europe)', '1993', NaN, 'Hot-B', '2', NaN, 'Tile-matching puzzle game with multiple play modes.', 'Match identical tiles to clear the board in various challenges.', 'Play Shanghai II: Dragon''s Eye on the SNES.', 'An expanded 16-bit puzzle experience. Includes the classic Solitaire mode and the unique Dragon''s Eye challenge, featuring vibrant graphics and diverse tile sets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shanghai II - Dragon''s Eye (USA)', '1993', NaN, 'Hot-B', '2', NaN, 'Tile-matching puzzle game with multiple play modes.', 'Master the art of Shanghai in the official North American version.', 'Experience Shanghai II on the Super Nintendo.', 'A meditative 16-bit puzzle classic. Offers a variety of layouts and themes, providing hours of strategic tile-clearing gameplay for fans of the genre.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shanghai III (Japan)', '1994', NaN, 'Hot-B', '2', NaN, 'Competitive and classic Mahjong Solitaire.', 'Clear the tiles faster than your opponent in this 16-bit sim.', 'Play Shanghai III on the Super Famicom.', 'The third 16-bit entry in the series. Features improved animations, more complex tile patterns, and a robust competitive mode to test your speed and pattern recognition.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shaq Fu (Europe)', '1994', NaN, 'Delphine Software', '2', NaN, 'One-on-one fighting game starring basketball legend Shaquille O''Neal.', 'Defeat the interdimensional warriors and save the boy Nezu.', 'Experience the unique Shaq Fu on the SNES.', 'A 16-bit fighter known for its fluid animation and bizarre premise. Travel to the Second World and use Shaq''s martial arts to defeat supernatural foes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shaq Fu (USA)', '1994', NaN, 'Delphine Software', '2', NaN, 'One-on-one fighting game featuring digitized-style animation.', 'Master the Shaq-ido to become the ultimate champion.', 'Play Shaq Fu for the Super Nintendo.', 'Features a story mode and a competitive 2-player mode. A 16-bit curiosity that captures the celebrity-driven gaming trends of the mid-90s.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shaq Fu (USA) (Beta)', '1994', NaN, 'Delphine Software', '2', NaN, 'One-on-one fighting game (Pre-release build).', 'Test the character frame data and special move hitboxes.', 'Check out the Shaq Fu Beta on the SNES.', 'A rare 16-bit development look. Witness the early implementation of the background parallax and the balancing of the character-specific projectile attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shichuusuimeigaku Nyuumon - Shin Tougenkyou (Japan)', '1995', NaN, 'Hect', '1', NaN, 'Fortune-telling and astrology simulation.', 'Predict your destiny using traditional Chinese Four Pillars methods.', 'Explore Shichuusuimeigaku Nyuumon on Super Famicom.', 'A unique 16-bit utility/simulation game. Enter birth data to receive detailed astrological readings and predictions based on ancient Eastern wisdom.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shien - The Blade Chaser (Japan)', '1994', NaN, 'NCS', '1', NaN, 'First-person ninja action game using the SNES Mouse or Pad.', 'Defeat the evil sorcerer and his army as a master ninja.', 'Play Shien: The Blade Chaser on Super Famicom.', 'A rare 16-bit action title where you use on-screen slashes to defeat enemies. Features fast-paced combat and impressive first-person sprites and environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shien''s Revenge (USA)', '1994', NaN, 'NCS', '1', NaN, 'First-person ninja action game (Western release).', 'Avenge your clan in this unique 16-bit first-person slasher.', 'Experience Shien''s Revenge on the Super Nintendo.', 'Compatible with the SNES Mouse for an authentic sword-slashing feel. Navigate through diverse historical stages and defeat massive bosses in tactical combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shien''s Revenge (USA) (Beta)', '1994', NaN, 'NCS', '1', NaN, 'First-person ninja action game (Pre-release build).', 'Test the early slash detection and enemy spawn rates.', 'Check out the Shien''s Revenge Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the projectile-deflection mechanics and the evolution of the first-person level design.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shijou Saikyou League Serie A - Ace Striker (Japan)', '1994', NaN, 'Tose', '2', NaN, 'Soccer simulation featuring the Italian Serie A league.', 'Lead your team to the top of the Italian league standings.', 'Play Serie A: Ace Striker on the Super Famicom.', 'A polished 16-bit soccer title. Features authentic teams from the Italian league, strategic formations, and smooth arcade-style gameplay with a focus on fast-paced scoring.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shijou Saikyou no Quiz Ou Ketteisen Super (Japan)', '1995', NaN, 'Game Studio', '2', NaN, 'Competitive trivia and quiz show simulation.', 'Become the Quiz King by answering hundreds of questions.', 'Play Shijou Saikyou no Quiz Ou on Super Famicom.', 'An engaging 16-bit quiz game. Features a variety of categories, multiple game modes including a TV-style tournament, and challenging AI opponents to test your general knowledge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shiki Eiyuuden - Jinryuu Densetsu (Japan)', '1995', NaN, 'Neverland', '1', NaN, 'Turn-based JRPG set in a mystical world of dragons.', 'Protect the dragon legend and defeat the rising evil.', 'Explore Shiki Eiyuuden on the Super Famicom.', 'A classic 16-bit JRPG with a focus on traditional turn-based combat and narrative world-building. Features detailed sprite work and a party-based system in a high-fantasy setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shimono Masaki no Fishing to Bassing (Japan)', '1994', NaN, 'Pack-In-Video', '1', NaN, 'Realistic bass fishing simulation in Japan.', 'Catch the biggest bass and master the Japanese lakes.', 'Go fishing in Shimono Masaki no Fishing on SNES.', 'A technical 16-bit fishing sim. Manage your lure selection and casting technique based on real-world conditions, endorsed by professional fisherman Masaki Shimono.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Chou Kouki (Japan)', '1992', NaN, 'Face', '1', NaN, 'Turn-based strategy set in ancient China.', 'Unify the warring states in this tactical historical sim.', 'Master strategy in Shin Chou Kouki on Super Famicom.', 'A deep 16-bit simulation from Koei. Manage your territory, recruit legendary generals, and engage in grid-based tactical warfare to conquer the mainland.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Ikkakusenkin (Japan)', '1994', NaN, 'NCS', '1', NaN, 'High-stakes gambling and horse racing simulation.', 'Win a fortune through strategic betting and luck.', 'Experience Shin Ikkakusenkin on the Super Famicom.', 'A detailed 16-bit gambling sim. Navigate the world of Japanese horse racing, analyzing stats and odds to turn a small stake into a massive payday.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Kidou Senki Gundam W - Endless Duel (Japan)', '1996', NaN, 'Natsume', '2', NaN, 'High-speed 2D fighting game featuring Mobile Suits.', 'Win the Gundam Wing tournament with intense combos.', 'Play Gundam Wing: Endless Duel on Super Famicom.', 'Widely considered one of the best 16-bit fighters. Features incredible animations, a technical Vernier dash system, and massive, screen-filling special attacks from the Wing series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Kidou Senki Gundam W - Endless Duel (Japan) [En by Aeon Genesis v1.0] (~Mobile Suit Gundam Wing - Endless Duel)', '1996', NaN, 'Natsume', '2', NaN, 'High-speed 2D fighting game (English Translation).', 'Experience the ultimate Gundam fighter in English.', 'Play Gundam Wing: Endless Duel in English on SNES.', 'The Aeon Genesis 16-bit translation makes this legendary fighter accessible. Master the technical combat and pilot your favorite Mobile Suit in a quest for total dominance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Mahjong (Japan)', '1994', NaN, 'Nichibutsu', '2', NaN, 'Traditional Mahjong simulation with updated rules.', 'Master the tiles and defeat the professional AI masters.', 'Play Shin Mahjong on the Super Famicom.', 'A refined 16-bit Mahjong title. Features multiple game modes, detailed statistics, and a clean interface designed for both casual and professional players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Megami Tensei (Japan)', '1992', NaN, 'Atlus', '1', NaN, 'Dark first-person dungeon-crawling RPG.', 'Navigate a post-apocalyptic Tokyo and recruit demons.', 'Experience the original Shin Megami Tensei on SNES.', 'The landmark 16-bit RPG that birthed the SMT franchise. Master the demon negotiation system and make moral choices that determine the fate of humanity in a dark, urban setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Megami Tensei (Japan) (Rev A)', '1992', NaN, 'Atlus', '1', NaN, 'Dark dungeon-crawling RPG (Updated Revision).', 'Experience the refined classic with bug fixes.', 'Play Shin Megami Tensei (Rev A) on Super Famicom.', 'The optimized 16-bit revision of the first SMT. Includes minor balancing tweaks and fixes for the demon fusion system, ensuring a smoother journey through the occult apocalypse.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Megami Tensei (Japan) [En by Aeon Genesis v1.0]', '1992', NaN, 'Atlus', '1', NaN, 'Dark dungeon-crawling RPG (English Translation).', 'Play the legendary occult RPG in English for the first time.', 'Experience Shin Megami Tensei in English on the SNES.', 'The definitive 16-bit translation by Aeon Genesis. Fully localized the complex demon-fusing mechanics and the deep, philosophical story of the struggle between Law and Chaos.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Megami Tensei if... (English)', '1994', NaN, 'Atlus', '1', NaN, 'Experimental dungeon-crawling RPG (English Translation).', 'Survive the demon-infested school in this SMT spin-off.', 'Play Shin Megami Tensei if... in English on SNES.', 'The 16-bit precursor to the Persona series. This fan translation allows players to navigate a high school trapped in a demon realm, featuring the innovative Guardian system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Megami Tensei if... (Japan)', '1994', NaN, 'Atlus', '1', NaN, 'Experimental dungeon-crawling RPG set in a high school.', 'Escape the demon dimension and defeat the Hazama.', 'Play Shin Megami Tensei if... on the Super Famicom.', 'A unique 16-bit entry in the SMT saga. Focuses on a smaller, more personal scale, introducing mechanics like the Moon phase and specialized character growth paths.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Megami Tensei II (Japan)', '1994', NaN, 'Atlus', '1', NaN, 'First-person dungeon-crawling RPG sequel.', 'Navigate the futuristic Tokyo Millennium and solve the mystery.', 'Experience Shin Megami Tensei II on Super Famicom.', 'A massive 16-bit sequel. Expands on the demon fusion and negotiation systems, featuring a deeper narrative that explores religious and cyberpunk themes in a dystopian world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Megami Tensei II (Japan) [En by Aeon Genesis v1.0]', '1994', NaN, 'Atlus', '1', NaN, 'First-person dungeon-crawling RPG sequel (English).', 'Reclaim your destiny in this translated cyberpunk epic.', 'Play Shin Megami Tensei II in English on the SNES.', 'The Aeon Genesis 16-bit translation allows Western fans to experience the full scale of this massive RPG. Features improved menus and a fully localized script for the complex plot.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Momotarou Densetsu (Japan)', '1993', NaN, 'Hudson Soft', '1', NaN, 'Turn-based JRPG based on Japanese folklore.', 'Lead Momotarou and his animal companions to save Japan.', 'Explore Shin Momotarou Densetsu on Super Famicom.', 'A high-quality 16-bit RPG from Hudson Soft. Features beautiful graphics, a deep turn-based battle system, and a heartwarming story inspired by the classic peach-boy legend.', NULL);
