INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shin Nekketsu Kouha - Kunio-tachi no Banka (Japan)', '1994', NaN, 'Technos Japan', '2', NaN, 'Cinematic side-scrolling beat ''em up (Renegade sequel).', 'Clear your name and defeat the Yakuza in this gritty brawler.', 'Experience Kunio-tachi no Banka on Super Famicom.', 'A mature 16-bit entry in the Nekketsu series. Features a continuous narrative, multiple playable characters like Misako and Kyoko, and intense combat across a dark urban landscape.', NULL);
