INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shinri Game 3, The (Japan)', '1995', NaN, 'Game Studio', '1', NaN, 'Psychological testing and social simulation sequel.', 'Unlock the secrets of your mind in this expanded sim.', 'Experience Shinri Game 3 on the Super Famicom.', 'The third 16-bit installment of the psychological series. Features more in-depth testing scenarios and improved graphics for the magical analytical journeys.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Shinri Game, The - Akuma no Kokoroji (Japan)', '1992', NaN, 'Game Studio', '1', NaN, 'Psychological testing with a darker theme.', 'Analyze your personality with these devilish tests.', 'Try Shinri Game: Akuma no Kokoroji on Super Famicom.', 'A 16-bit social simulation focusing on the darker or more hidden aspects of personality. Perfect for party play and analyzing friends through bizarre scenarios.', NULL);
