INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SimAnt (USA) (Beta)', '1991', NaN, 'Maxis', '1', NaN, 'Strategic life simulation (Pre-release build).', 'Test the early ant AI and colony growth mechanics.', 'Check out the SimAnt Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the scent-trail system and the tuning of the environmental hazards before the final release.', NULL);
