INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SimCity 2000 (Japan)', '1995', NaN, 'Maxis', '1', NaN, 'Advanced city-building (Japanese release).', 'Experience the next generation of city sims in Japan.', 'Play SimCity 2000 on the Super Famicom.', 'The official 16-bit Japanese release of the sequel. Includes a variety of scenarios and deep customization options for managing a modern, high-tech Japanese city.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SimCity 2000 (USA)', '1995', NaN, 'Maxis', '1', NaN, 'Advanced city-building with futuristic technology.', 'Manage a 16-bit world with newspapers and diverse zones.', 'Experience SimCity 2000 for the Super Nintendo.', 'Build mountains, launch space arcologies, and manage the city''s power grid. A technical 16-bit achievement that brings the complex PC simulation to the home console.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SimCity Jr. (Japan)', '1992', NaN, 'Maxis', '1', NaN, 'Simplified city-building for younger audiences.', 'Build a happy town in this accessible 16-bit sim.', 'Experience SimCity Jr. on the Super Famicom.', 'A Japan-exclusive lite version of the classic sim. Features cute graphics, simplified menus, and a more streamlined approach to urban management, perfect for beginners.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SimEarth - The Living Planet (Japan) (Rev 0A)', '1991', NaN, 'Maxis', '1', NaN, 'Global scale life and planet simulation.', 'Manage the Earth''s evolution from a rock to a civilization.', 'Experience SimEarth on the Super Famicom.', 'A deep 16-bit God game from Maxis. Control the atmosphere, plate tectonics, and the evolution of species to ensure the survival of life on your planet.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SimEarth - The Living Planet (USA)', '1991', NaN, 'Maxis', '1', NaN, 'Global scale life and planet simulation (USA release).', 'Guide the evolution of life in this complex 16-bit sim.', 'Play the planet-building SimEarth on the SNES.', 'Features various scenarios including the terraforming of Mars. Manage the 16-bit environment to move from simple organisms to a space-faring civilization.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Simpsons, The - Bart no Fushigi na Yume no Daibouken (Japan)', '1992', NaN, 'Konami', '1', NaN, 'Action-adventure mini-game collection starring Bart Simpson.', 'Collect the lost pages of Bart''s homework in his dreams.', 'Play Bart no Fushigi na Yume on the Super Famicom.', 'The Japanese release of Bart''s Nightmare. Features a variety of gameplay styles, from side-scrolling action as Bartman to Godzilla-style rampages in the city.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Simpsons, The - Bart''s Nightmare (Europe)', '1992', NaN, 'Konami', '1', NaN, 'Action-adventure mini-game collection based on the TV show.', 'Survive the dream world and recover your homework.', 'Experience Bart''s Nightmare for the Super Nintendo.', 'A surreal 16-bit journey. Navigate the dangerous streets of Springfield in Bart''s mind to find portals leading to diverse and challenging mini-games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Simpsons, The - Bart''s Nightmare (USA)', '1992', NaN, 'Konami', '1', NaN, 'Action-adventure mini-game collection with iconic characters.', 'Master the 16-bit dream levels and save Bart''s grades.', 'Play the classic Bart''s Nightmare on the SNES.', 'Features impressive graphics that capture the show''s aesthetic. Battle itchy and scratchy, fly through the clouds, and survive the school corridors in this 90s classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Simulation Pro Yakyuu (Japan)', '1995', NaN, 'Compile', '1', NaN, 'Realistic professional baseball simulation.', 'Win the Japan Series in this technical 16-bit sports sim.', 'Experience Simulation Pro Yakyuu on the Super Famicom.', 'Focuses on the statistical and management side of baseball. Analyze player data and make strategic calls from the dugout to lead your team to victory.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sink or Swim (Europe)', '1993', NaN, 'Bullfrog Productions', '2', NaN, 'Puzzle-platformer where you rescue passengers on a ship.', 'Guide the survivors to safety before the ship sinks.', 'Play the challenging Sink or Swim on the SNES.', 'Similar to Lemmings. Use various items to clear hazards and direct the clueless passengers to the exit across dozens of water-themed 16-bit levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sink or Swim (USA)', '1993', NaN, 'Bullfrog Productions', '2', NaN, 'Puzzle-platformer featuring Kevin the conveyor-belt hero.', 'Save the crew of the SS Lucifer in this 16-bit puzzler.', 'Experience Sink or Swim for the Super Nintendo.', 'Master the environment by manipulating levers, bridges, and valves. A clever logic game that rewards quick thinking and precise timing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ski Paradise with Snowboard (Japan)', '1994', NaN, 'Nichibutsu', '1', NaN, 'Winter sports simulation with skiing and snowboarding.', 'Master the snowy slopes and win the 16-bit tournament.', 'Play Ski Paradise on the Super Famicom.', 'Features both downhill skiing and snowboarding modes. Use the 16-bit Mode 7 effects to navigate realistic mountain tracks and perform stunts for high scores.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Skuljagger - Revolt of the Westicans (USA)', '1992', NaN, 'American Softworks', '1', NaN, 'Action-platformer with a focus on collectible items.', 'Overthrow the evil Captain Whitescar in this 16-bit quest.', 'Experience the adventure of Skuljagger on the SNES.', 'Play as Storm Jaki in a vibrant tropical setting. Use your sword to battle pirates and find the hidden Westican gems to unlock new powers and secret paths.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Skuljagger - Revolt of the Westicans (USA) (Beta)', '1992', NaN, 'American Softworks', '1', NaN, 'Action-platformer (Pre-release build).', 'Test the early sword combat and gem-collecting mechanics.', 'Check out the Skuljagger Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character''s movement physics and the evolution of the jungle and pirate ship level designs.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sky Mission (Japan)', '1993', NaN, 'Naxat Soft', '1', NaN, 'First-person flight combat and exploration.', 'Complete high-stakes missions in a futuristic fighter jet.', 'Fly high in Sky Mission for the Super Famicom.', 'A technical 16-bit flight sim. Use a cockpit view to engage in dogfights and bombing runs across a variety of 3D-style landscapes using the SNES hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Skyblazer (Europe)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Atmospheric action-platformer with magical abilities.', 'Stop the sorcerer Ashura and save your home.', 'Play the epic Skyblazer for the Super Nintendo.', 'Developed by Sony. Features fluid 16-bit combat, wall-climbing, and a variety of elemental powers. A hidden gem known for its great music and tight controls.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Skyblazer (USA)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Atmospheric action-platformer with magical abilities.', 'Master the elemental spells to defeat the dark gods.', 'Experience the classic Skyblazer on the SNES.', 'Navigate through stunning 16-bit levels using acrobatic moves and magical strikes. One of the most polished and visually impressive platformers of the era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Skyblazer (USA) (Beta1)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Action-platformer (Early development build).', 'Test the early wall-climb mechanics and boss patterns.', 'Check out the Skyblazer Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of Sky''s magical meter and the initial implementation of the Mode 7 world map.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Skyblazer (USA) (Beta2)', '1993', NaN, 'Sony Imagesoft', '1', NaN, 'Action-platformer (Revised development build).', 'Explore unreleased stage layouts and enemy placements.', 'Discover the Skyblazer Beta 2 on the SNES.', 'An advanced 16-bit prototype. Features nearly final assets but with different enemy density and specific item locations for testing purposes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Slap Stick (Japan)', '1994', NaN, 'Irem', '1', NaN, 'Quirky turn-based RPG with robot customization.', 'Build and program your own robots to save the world.', 'Explore Slap Stick on the Super Famicom.', 'Known as Robotrek in the West. A unique 16-bit RPG where you create up to three custom robots, managing their stats, weapons, and specialized combat moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Slayers (Japan)', '1994', NaN, 'Banpresto', '1', NaN, 'Tactical JRPG based on the iconic fantasy anime.', 'Join Lina Inverse and her party on a magical 16-bit quest.', 'Experience the legend of Slayers on the Super Famicom.', 'A first-person JRPG that captures the humor and power of the series. Use powerful Dragon Slave spells and interact with the fan-favorite cast in a faithful adaptation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Slayers (Japan) [En by Filler v0.20] (Incomplete)', '1994', NaN, 'Banpresto', '1', NaN, 'Tactical JRPG (English Translation - Incomplete).', 'Experience the world of Lina Inverse with translated text.', 'Play Slayers in English (v0.20) on the SNES.', 'An early-stage 16-bit fan translation. Allows players to experience the opening chapters and basic combat menus of this anime-inspired role-playing adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi - Bangai Hen (Japan) (Unl)', '1994', NaN, 'Unknown', '1', NaN, 'Adult-themed adventure/puzzle (Unlicensed).', 'Navigate the scandalous scenarios as the dominant Hitomi.', 'Explore SM Choukyoushi Hitomi Bangai Hen (Unl).', 'An unlicensed 16-bit title featuring adult-oriented themes and dialogue. Combines simple adventure mechanics with provocative art styles typical of the underground Japanese market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi - Bangai Hen 2 - Maki no Love Love Panic (Japan) (Unl)', '1994', NaN, 'Unknown', '1', NaN, 'Adult-themed puzzle/adventure sequel (Unlicensed).', 'Resolve the Love Love Panic in this adult-themed sequel.', 'Play SM Choukyoushi Hitomi Bangai Hen 2 (Unl).', 'The second unlicensed 16-bit spin-off. Features expanded character interactions and more complex puzzle scenarios centered around its mature-themed narrative.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi - Test Version (Japan) (Unl)', '1994', NaN, 'Unknown', '1', NaN, 'Adult-themed adventure (Test Version - Unlicensed).', 'Test the early dialogue and adult scene triggers.', 'Check the SM Choukyoushi Hitomi Test Build.', 'A rare 16-bit development look at an unlicensed adult title. Witness the initial implementation of the character portraits and menu structures.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi (Japan) (Unl)', '1994', NaN, 'Unknown', '1', NaN, 'Adult-themed adventure and simulation (Unlicensed).', 'Master the dominant arts in this controversial title.', 'Experience SM Choukyoushi Hitomi (Unl) on SNES.', 'The foundational 16-bit unlicensed adult game for the system. Features a mix of text-heavy adventure and simulation elements focused on its specific niche theme.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi Vol. 2 - Trial Version (Japan) (Unl)', '1995', NaN, 'Unknown', '1', NaN, 'Adult-themed adventure sequel (Trial - Unlicensed).', 'Preview the new scenarios in the second volume.', 'Try the SM Choukyoushi Hitomi Vol. 2 Trial.', 'A 16-bit demo version of the second installment. Offers a glimpse into the updated graphics and new character additions before the full unlicensed release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi Vol. 2 (Japan) (Unl)', '1995', NaN, 'Unknown', '1', NaN, 'Adult-themed adventure and simulation (Unlicensed).', 'Expand your influence in this second adult volume.', 'Play SM Choukyoushi Hitomi Vol. 2 (Unl).', 'The direct 16-bit sequel to the unlicensed original. Features more detailed artwork and a longer story path involving various adult-themed challenges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi Vol. 2 Remix (Japan) (Unl)', '1995', NaN, 'Unknown', '1', NaN, 'Adult-themed adventure (Remix Edition - Unlicensed).', 'Experience the enhanced version of the second volume.', 'Play SM Choukyoushi Hitomi Vol. 2 Remix (Unl).', 'An updated 16-bit edition of the second volume. Includes refined color palettes, additional dialogue lines, and slight mechanical tweaks to the unlicensed adult sim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi Vol. 3 - Test Version (Japan) (Unl)', '1996', NaN, 'Unknown', '1', NaN, 'Adult-themed adventure (Vol 3 Test - Unlicensed).', 'Explore the early assets of the third installment.', 'Check the SM Choukyoushi Hitomi Vol. 3 Test.', 'A rare 16-bit development slice of the third volume. Shows the evolution of the series'' visual style and UI design for the underground Japanese market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi Vol. 3 (Japan) (Unl) [0810]', '1996', NaN, 'Unknown', '1', NaN, 'Adult-themed adventure and simulation (Unlicensed).', 'Complete the final chapters of Hitomi''s story.', 'Experience SM Choukyoushi Hitomi Vol. 3 (Unl).', 'The third main 16-bit entry in the unlicensed series. Features the most advanced graphics and complex narrative paths of the trilogy for mature audiences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SM Choukyoushi Hitomi Vol. 3 (Japan) (Unl) [1087]', '1996', NaN, 'Unknown', '1', NaN, 'Adult-themed adventure and simulation (Unlicensed).', 'Experience an alternate build of the third volume.', 'Play SM Choukyoushi Hitomi Vol. 3 (Unl) [1087].', 'A slight variation of the third 16-bit installment. Features the same adult-themed gameplay with minor internal data differences and scenario ordering.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Smart Ball (USA)', '1992', NaN, 'GameTek', '1', NaN, 'Physics-based puzzle platformer with a slime-like ball.', 'Navigate Jerry Bean through obstacles to the goal.', 'Experience the colorful Smart Ball on the SNES.', 'Known as Jerry Boy in Japan. A charming 16-bit platformer where you control a jelly ball that can stick to walls, stretch, and absorb items to solve puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Smash T.V. (Japan)', '1990', NaN, 'Williams Electronics', '2', NaN, 'Ultraviolent top-down arena shooter.', 'Survive the lethal game show and win big prizes.', 'Play the explosive Smash T.V. on the Super Famicom.', 'A frantic 16-bit arcade port. Face waves of enemies in a futuristic game show. Use dual-stick style controls to blast through rooms and collect Big Money!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Smash Tennis (Europe)', '1993', NaN, 'Namco', '2', NaN, 'Fast-paced tennis simulation with diverse characters.', 'Win the international tennis circuit on various surfaces.', 'Play the addictive Smash Tennis on the SNES.', 'Also known as Super Family Tennis. Features a zoomed-out perspective, responsive controls, and a variety of courts including grass, clay, and even a beach.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Smash Tennis (Europe) (Beta)', '1993', NaN, 'Namco', '2', NaN, 'Tennis simulation (Pre-release build).', 'Test the early ball physics and character movements.', 'Check out the Smash Tennis Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the Mode 7 style court rotations and the balancing of the AI''s serving speed.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SMPRGRevolutionV1.1a', '2019', NaN, 'Fan Made', '1', NaN, 'Fan-made Super Mario RPG modification.', 'Experience an overhauled version of the Mario RPG epic.', 'Play the SMPRGRevolution mod on the SNES.', 'A technical 16-bit fan expansion. Features rebalanced stats, new enemy encounters, and specific quality-of-life improvements to the original Square/Nintendo masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Smurfs 2, The (Europe) (En,Fr,De,Es)', '1995', NaN, 'Infogrames', '1', NaN, 'Side-scrolling platformer based on the movie The Smurfs 2.', 'Rescue the Smurfs from Gargamel''s latest trap.', 'Experience The Smurfs 2 on the Super Nintendo.', 'A visually impressive 16-bit platformer featuring large sprites and vibrant colors. Travel across Europe to save your blue friends in this family-friendly adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Smurfs, The (Europe) (En,Fr,De,Es,It)', '1994', NaN, 'Infogrames', '1', NaN, 'Side-scrolling platformer based on the classic comic.', 'Help the Smurfs survive the forest and Gargamel.', 'Play The Smurfs on the Super Nintendo.', 'A challenging 16-bit title with a high level of difficulty. Navigate through the woods, caves, and Gargamel''s castle with fluid animations and faithful art style.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SMW The Crown Tale by bandicoot', '2018', NaN, 'Fan Made', '1', NaN, 'Fan-made Super Mario World expansion hack.', 'Explore the kingdom of the Crown in this Mario adventure.', 'Play SMW: The Crown Tale on the SNES.', 'A high-quality 16-bit fan creation. Features custom music, unique level assets, and a completely new world map designed for veterans of the original Super Mario World.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Snoopy Concert (Japan)', '1995', NaN, 'Game Freak', '1', NaN, 'Multi-genre adventure featuring Snoopy and the Peanuts gang.', 'Help Snoopy complete various tasks in the theme park.', 'Experience Snoopy Concert on the Super Famicom.', 'A charming 16-bit title from Hudson Soft. Switch between different gameplay styles including point-and-click, puzzles, and side-scrolling action to help the Peanuts cast.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Snoopy Concert (Japan) [En by Aeon Genesis v1.0]', '1995', NaN, 'Game Freak', '1', NaN, 'Adventure and puzzle (English Translation).', 'Enjoy Snoopy''s theme park adventure in English.', 'Play Snoopy Concert in English on the SNES.', 'The Aeon Genesis 16-bit translation. Makes this beautiful Peanuts game fully accessible, featuring witty dialogue and clear instructions for the various mini-games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Snow White in Happily Ever After (USA)', '1994', NaN, 'Capcom', '1', NaN, 'Side-scrolling platformer based on the animated film.', 'Rescue the Prince and defeat the evil Queen.', 'Play Snow White in Happily Ever After on SNES.', 'A colorful 16-bit platformer. Choose between various characters to navigate enchanted forests and snowy mountains, featuring smooth controls and family-friendly gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'So 2 Mice Walk Into a Bar... by S.N.N., idol', '2020', NaN, 'Homebrew', '1', NaN, 'Abstract and comedic fan-made SNES demo/mini-game.', 'Witness the surreal humor of two mice in a bar.', 'Check out So 2 Mice Walk Into a Bar on SNES.', 'A short, 16-bit community-made creative project. Showcases custom sprite work and humorous dialogue scripts within the Super Nintendo''s technical framework.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soccer Kid (Europe) (En,Fr,De,Es,It)', '1994', NaN, 'Krisalis Software', '1', NaN, 'Platformer where your primary weapon is a soccer ball.', 'Travel the world and recover the stolen World Cup.', 'Experience the unique Soccer Kid on the SNES.', 'A clever 16-bit platformer. Use your soccer ball to attack enemies, trigger switches, and perform acrobatic jumps. Features large, detailed levels and great physics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soccer Kid (Japan)', '1994', NaN, 'Krisalis Software', '1', NaN, 'Soccer-based platformer (Japanese release).', 'Experience the globe-trotting adventure in Japan.', 'Play Soccer Kid on the Super Famicom.', 'The official 16-bit Japanese release. Retains the creative ball-juggling mechanics and challenging level design that made it a standout title in the European market.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soccer Kid (Japan) (Beta)', '1994', NaN, 'Krisalis Software', '1', NaN, 'Soccer-based platformer (Pre-release build).', 'Test the early ball-handling and collision physics.', 'Check out the Soccer Kid Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the ball''s bounce logic and the initial implementation of the diverse international backgrounds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soccer Shootout (Europe)', '1994', NaN, 'Teque London', '2', NaN, 'Simulation-style soccer game with a focus on realism.', 'Win the European cup with precise passing and tactics.', 'Play Soccer Shootout on the Super Nintendo.', 'A solid 16-bit sports title. Features a variety of modes including indoor soccer, penalty shootouts, and full-season tournaments with a focus on technical play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soldiers of Fortune (USA)', '1993', NaN, 'LucasArts', '2', NaN, 'Top-down run-and-gun action shooter.', 'Blaze through levels and stop the technological menace.', 'Experience Soldiers of Fortune on the SNES.', 'Known as The Chaos Engine in Europe. A gritty 16-bit steampunk shooter featuring two-player co-op, six distinct characters, and highly challenging, maze-like levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Solid Runner (Japan)', '1997', NaN, 'Sting', '1', NaN, 'Cyberpunk dungeon-crawling RPG with turn-based combat.', 'Uncover the conspiracy in the city of Solid.', 'Explore the impressive Solid Runner on Super Famicom.', 'A late-gen 16-bit RPG marvel. Features incredible pre-rendered graphics, a sophisticated sci-fi story, and tactical combat involving specialized mecha-style suits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Solstice II (Japan)', '1993', NaN, 'Imagineering', '1', NaN, 'Isometric action-puzzle and platformer.', 'Navigate the wizard through the complex labyrinth of Solstice.', 'Play the mind-bending Solstice II on the SNES.', 'Known as Equinox in the West. A 16-bit isometric adventure. Solve intricate environmental puzzles and defeat massive bosses in a quest to rescue the wizard Shadax.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Song Master (Japan)', '1992', NaN, 'ASCII', '1', NaN, 'Traditional turn-based JRPG with a focus on music.', 'Embark on a quest to become the ultimate Song Master.', 'Explore the melodic Song Master on the Super Famicom.', 'A rare 16-bit RPG where music plays a central role in the narrative and world-building. Features classic turn-based combat and detailed character sprites in a high-fantasy setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic Blast Man (Europe)', '1992', NaN, 'Taito', '2', NaN, 'Side-scrolling beat ''em up based on the arcade hit.', 'Save the Earth from criminals and aliens as the superhero.', 'Play the explosive Sonic Blast Man on the SNES.', 'A 16-bit brawler featuring a superhero known for his powerful punches. Includes diverse levels ranging from city streets to alien ships, and unique bonus stages from the arcade original.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic Blast Man (Japan)', '1992', NaN, 'Taito', '2', NaN, 'Side-scrolling beat ''em up (Japanese release).', 'Defeat the evil forces in the official Japanese version.', 'Experience Sonic Blast Man on the Super Famicom.', 'The 16-bit debut of the punching hero in Japan. Master his signature moves and tackle challenging bosses in this high-energy action title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic Blast Man (USA)', '1992', NaN, 'Taito', '2', NaN, 'Side-scrolling beat ''em up starring the armored hero.', 'Protect the world from a global terrorist threat.', 'Experience the action-packed Sonic Blast Man on SNES.', 'Features large character sprites and intense 16-bit combat. Use specialized punches to destroy everything from thugs to massive mechanical bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic Blast Man II (Japan)', '1994', NaN, 'Taito', '2', NaN, 'Side-scrolling beat ''em up sequel with multiple characters.', 'Stop the new criminal organization with Sonic Blast Man.', 'Play Sonic Blast Man II on the Super Famicom.', 'An expanded 16-bit sequel. Features three playable characters, each with unique fighting styles and movesets, offering much more variety than the first game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic Blast Man II (USA)', '1994', NaN, 'Taito', '2', NaN, 'Side-scrolling beat ''em up sequel with 2-player co-op.', 'Team up to defeat the intergalactic threats.', 'Experience Sonic Blast Man II on the Super Nintendo.', 'Significant 16-bit improvement over the original. Includes cooperative multiplayer, branching paths, and more fluid combat mechanics for a superior brawling experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic in SMW', '2010', NaN, 'Fan Made', '1', NaN, 'Fan-made hack of Super Mario World featuring Sonic.', 'Navigate the Mushroom Kingdom with Sonic''s speed.', 'Play Sonic in SMW on the Super Nintendo.', 'A creative 16-bit romhack that replaces Mario with Sonic the Hedgehog. Features custom physics to mimic Sonic''s speed and momentum within the classic Mario levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic in Super Mario World', '2010', NaN, 'Fan Made', '1', NaN, 'Fan-made hack of Super Mario World featuring Sonic.', 'Complete Mario''s adventure using Sonic''s abilities.', 'Try Sonic in Super Mario World on the SNES.', 'A 16-bit community project that blends the two mascots. Features Sonic''s signature spin-jump and speed, providing a fresh way to experience the legendary 16-bit platformer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic the Hedgehog - SNES Edition', '2018', NaN, 'Fan Made', '1', NaN, 'Unlicensed port/recreation of the Sega classic.', 'Experience Sonic''s first adventure on a Nintendo console.', 'Check out Sonic the Hedgehog SNES Edition (Unl).', 'A 16-bit unlicensed curiosity. Attempts to recreate the Green Hill Zone experience on the SNES hardware, showcasing fan efforts to cross the console divide.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic the Hedgehog (SNES)', '2018', NaN, 'Fan Made', '1', NaN, 'Unlicensed port/recreation of the Sega classic.', 'Run through the zones in this unofficial 16-bit port.', 'Play Sonic the Hedgehog (Unl) on the SNES.', 'An unofficial 16-bit technical experiment. While lacking the polish of the Sega original, it stands as a fascinating piece of underground gaming history for the Super Nintendo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic the Hedgehog (Unl)', '1994', NaN, 'Unlicensed', '1', NaN, 'Unlicensed port/recreation of the Sega classic.', 'Experience the blue blur on the Super Famicom hardware.', 'Play Sonic the Hedgehog (Unl) on the SNES.', 'Features various attempts at 16-bit parallax scrolling and speed physics on the SNES, created by third-party developers without official Nintendo licensing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic the Hedgehog 2 (hack)', '2005', NaN, 'Fan Made', '1', NaN, 'Fan-made hack of Sonic 4 (Unl) or similar engine.', 'Play an alternate 16-bit Sonic adventure.', 'Experience the Sonic the Hedgehog 2 Hack on SNES.', 'A 16-bit modification of existing unlicensed Sonic games. Tweaks the palettes and level layouts to resemble the second entry of the series on the rival platform.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic the Hedgehog 4 (World) (Unl)', '2019', NaN, 'Fan Made', '1', NaN, 'Unlicensed side-scrolling platformer.', 'Complete a new, unofficial quest as Sonic the Hedgehog.', 'Play Sonic the Hedgehog 4 (Unl) on the SNES.', 'Actually a pirate port of Speedy Gonzales: Los Gatos Bandidos with the main character replaced by Sonic. A bizarre 16-bit historical artifact of the pirate game scene.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sonic Wings (Japan)', '1993', NaN, 'Video System', '2', NaN, 'Vertical-scrolling shoot ''em up (Shmup).', 'Choose your pilot and destroy the global military threat.', 'Experience the intense Sonic Wings on the Super Famicom.', 'Known as Aero Fighters in the West. A top-tier 16-bit shooter featuring diverse planes, fast-paced bullet patterns, and quirky humor across international stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soreyuke Ebisumaru Karakuri Meiro - Kieta Goemon no Nazo!! (Japan)', '1994', NaN, 'Konami', '1', NaN, 'Isometric puzzle-adventure starring Ebisumaru.', 'Solve the maze-like levels to find the missing Goemon.', 'Explore Ebisumaru''s Karakuri Meiro on the SNES.', 'A charming 16-bit spin-off from the Ganbare Goemon series. Use logic and timing to navigate complex traps and puzzles in a vibrant, feudal Japanese setting.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'SOS (USA)', '1994', NaN, 'Human Entertainment', '1', NaN, 'Cinematic survival adventure on a sinking ship.', 'Escape the sinking Lady Crithania and save the survivors.', 'Experience the atmospheric SOS on the Super Nintendo.', 'Uses 16-bit Mode 7 effects to rotate the entire world as the ship capsizes. A tense, non-linear adventure where every second counts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sotsugyou Bangai Hen - Nee Mahjong Shiyo! (Japan)', '1995', NaN, 'Jaleco', '1', NaN, 'Mahjong simulation featuring the cast of Sotsugyou.', 'Play Mahjong with the girls from the Graduation series.', 'Experience Nee Mahjong Shiyo! on the Super Famicom.', 'A 16-bit anime-style Mahjong game. Features voiced dialogue and high-quality character art from the popular Japanese life-simulation franchise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sougou Kakutougi Astral Bout (Japan)', '1992', NaN, 'King Records', '2', NaN, 'Technical MMA-style fighting game (RINGS).', 'Win the Astral Bout tournament using realistic grappling.', 'Play Astral Bout on the Super Famicom.', 'A unique 16-bit fighter focused on realism. Master submissions, strikes, and positioning in this early representation of mixed martial arts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sougou Kakutougi Astral Bout 2 - The Total Fighters (Japan)', '1994', NaN, 'A-Wave', '2', NaN, 'MMA-style fighting game sequel.', 'Defeat the total fighters in this technical 16-bit sim.', 'Experience Astral Bout 2 on the Super Famicom.', 'Features an expanded roster and refined grappling mechanics. A more polished 16-bit combat experience for fans of technical wrestling and martial arts.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sougou Kakutougi Rings - Astral Bout 3 (Japan)', '1995', NaN, 'A-Wave', '2', NaN, 'The final entry in the technical MMA trilogy.', 'Claim the RINGS championship in this advanced fighter.', 'Play Astral Bout 3 on the Super Famicom.', 'The most advanced 16-bit entry in the series. Features significantly improved animations, a deeper career mode, and a refined focus on ground-and-pound tactics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soukou Kihei Votoms - The Battling Road (Japan)', '1991', NaN, 'Takara', '1', NaN, 'Mecha fighting game based on the classic anime.', 'Pilot the Scopedog and survive the Battling arena.', 'Explore Armored Trooper Votoms on the SNES.', 'A technical 16-bit mecha combat game. Features 2D fighting mechanics with specialized robot movement, capturing the gritty atmosphere of the Votoms universe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soul & Sword (Japan)', '1993', NaN, 'Pandora Box', '1', NaN, 'Turn-based JRPG with a tactical equipment system.', 'Uncover the mystery of the Soul & Sword.', 'Experience Soul & Sword on the Super Famicom.', 'A late-gen 16-bit RPG featuring a unique Card system for actions and equipment. Offers a deep narrative and impressive environmental pixel art.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soul Blade (World) (Unl)', '1998', NaN, 'Unlicensed', '2', NaN, 'Unlicensed 2D fighting game (Pirate).', 'Fight through the roster in this unofficial 16-bit brawler.', 'Check out Soul Blade (Unl) on the Super Nintendo.', 'An unlicensed attempt to bring the 32-bit weapons fighter to the SNES. Features simplified 16-bit mechanics and a roster based on the SoulCalibur series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soul Blader (Japan)', '1992', NaN, 'Quintet', '1', NaN, 'The original Japanese release of Soul Blazer.', 'Restore the world''s life by defeating Deathtoll.', 'Play Soul Blader on the Super Famicom.', 'The first entry in Quintet''s Heaven and Earth 16-bit trilogy. Combine action-combat with town-building as you rescue souls to rebuild the world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soul Blazer (Europe)', '1992', NaN, 'Quintet', '1', NaN, 'Action-RPG focused on world restoration.', 'Rebuild the kingdom by clearing monster dens.', 'Experience the magic of Soul Blazer on the SNES.', 'A landmark 16-bit Action-RPG. Features a satisfying gameplay loop where every enemy defeated helps bring life back to the devastated environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soul Blazer (France)', '1992', NaN, 'Quintet', '1', NaN, 'Action-RPG (French localization).', 'Restaurez le monde dans cette version française.', 'Jouez à Soul Blazer en français sur le SNES.', 'The complete 16-bit adventure with full French text. Experience the emotional story and creative dungeon design of this Quintet classic in your own language.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soul Blazer (Germany)', '1992', NaN, 'Quintet', '1', NaN, 'Action-RPG (German localization).', 'Erwecke die Welt zu neuem Leben auf Deutsch.', 'Spielen Sie Soul Blazer auf Deutsch für das SNES.', 'A fully localized 16-bit experience. Battle through themed worlds and master the specialized magic and swordplay required to save humanity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Soul Blazer (USA)', '1992', NaN, 'Quintet', '1', NaN, 'Action-RPG featuring real-time combat and town-building.', 'Defeat the forces of evil and restore the six realms.', 'Play the legendary Soul Blazer on the Super Nintendo.', 'Known for its addictive progression and deep themes. A 16-bit masterpiece that paved the way for Illusion of Gaia and Terranigma.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sound Novel Tsukuru (Japan)', '1996', NaN, 'Hudson Soft', '1', NaN, 'Creative tool for designing visual novels.', 'Write and create your own 16-bit digital stories.', 'Build stories with Sound Novel Tsukuru on SNES.', 'A unique 16-bit utility from Chunsoft. Use various backgrounds, music tracks, and branch-path scripts to create your own suspenseful sound novels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Ace (Europe)', '1994', NaN, 'Eurocom', '1', NaN, 'Action-platformer adaptation of the laserdisc classic.', 'Rescue Kimberly from the evil Commander Borf.', 'Experience the high-stakes Space Ace on the SNES.', 'A 16-bit reimagining of the arcade hit. Unlike the laserdisc original, this is a challenging side-scrolling platformer where Dexter must dodge traps and blast aliens to save the girl.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Ace (Japan)', '1994', NaN, 'Eurocom', '1', NaN, 'Action-platformer adaptation (Japanese release).', 'Navigate the cosmic perils in the official Japanese version.', 'Play Space Ace on the Super Famicom.', 'The official 16-bit Japanese port. Features vibrant graphics and a high level of difficulty as you switch between the agile Dexter and the powerful Ace to defeat Borf''s army.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Ace (USA)', '1994', NaN, 'Eurocom', '1', NaN, 'Action-platformer featuring transforming protagonists.', 'Defeat Borf and return to your adult form as Ace.', 'Play the action-packed Space Ace on the SNES.', 'A unique 16-bit title that blends cinematic timing with traditional platforming. Use your laser pistol and agility to survive treacherous alien worlds in this sci-fi adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Ace (USA) (Beta)', '1994', NaN, 'Eurocom', '1', NaN, 'Action-platformer (Pre-release build).', 'Test the early collision physics and enemy spawns.', 'Check out the Space Ace Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character''s jumping arcs and the evolution of the level layouts before the final release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Bazooka (Japan)', '1992', NaN, 'Kemco', '2', NaN, 'Light gun shooter using the Super Scope.', 'Defeat the alien invaders in this first-person shooter.', 'Experience Space Bazooka on the Super Famicom.', 'Known as Battle Clash in the West. A technical 16-bit masterpiece for the Super Scope, featuring massive mecha bosses and destructible environments in a futuristic tournament.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Football - One on One (USA)', '1992', NaN, 'Argonaut Games', '2', NaN, 'Futuristic sports simulation (One-on-One).', 'Win the intergalactic soccer-style tournament in space.', 'Play Space Football on the Super Nintendo.', 'A unique 16-bit sports game using Mode 7 effects for a first-person perspective. Navigate your craft, steal the ball, and score goals in zero-gravity arenas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Funky B.O.B. (Japan)', '1993', NaN, 'Irem', '1', NaN, 'Action-platformer with a remote-controlled robot.', 'Escape the alien planet using your specialized robot arm.', 'Experience Space Funky B.O.B. on the Super Famicom.', 'Known as B.O.B. in the West. A clever 16-bit platformer where you use various remote gadgets and weapon attachments to navigate industrial alien mazes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Invaders - The Original Game (Europe)', '1997', NaN, 'Taito', '2', NaN, 'Faithful arcade port of the legendary shooter.', 'Defeat the waves of descending aliens for the high score.', 'Play Space Invaders on the Super Nintendo.', 'A 16-bit tribute to the arcade classic. Includes the original black-and-white mode, the cellophane version, and an updated mode with enhanced SNES graphics and sound.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Invaders - The Original Game (Japan)', '1997', NaN, 'Taito', '2', NaN, 'Faithful arcade port (Original Japanese release).', 'Relive the arcade revolution in this 16-bit collection.', 'Experience Space Invaders on the Super Famicom.', 'The definitive 16-bit Japanese edition. Features a Versus mode for two players and multiple visual filters to recreate the 1978 arcade experience perfectly.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Invaders - The Original Game (USA)', '1997', NaN, 'Taito', '2', NaN, 'Faithful arcade port with updated features.', 'Defend Earth in the official North American version.', 'Play the classic Space Invaders on the SNES.', 'Features a competitive two-player mode where clearing lines of invaders sends more to your opponent''s screen. A perfect 16-bit recreation of a gaming legend.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Space Megaforce (USA)', '1993', NaN, 'Compile', '1', NaN, 'Vertical-scrolling shoot ''em up (Shmup).', 'Blast through the alien fleet with an evolving arsenal.', 'Experience the legendary Space Megaforce on SNES.', 'Developed by Compile. Known as Super Aleste in Japan, it is one of the most technical 16-bit shooters, featuring eight weapon types and massive, screen-filling bosses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Spanky''s Quest (Europe)', '1993', NaN, 'Natsume', '1', NaN, 'Puzzle-platformer starring a bubble-blowing monkey.', 'Climb the tower and defeat the evil witch''s minions.', 'Play the charming Spanky''s Quest on the SNES.', 'A unique 16-bit logic game. Bounce bubbles off your head to make them grow, then pop them to turn them into various sports balls that clear enemies from the screen.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Spanky''s Quest (USA)', '1993', NaN, 'Natsume', '1', NaN, 'Puzzle-platformer starring a bubble-blowing monkey.', 'Complete the 16-bit trials to rescue your monkey friends.', 'Experience Spanky''s Quest for the Super Nintendo.', 'Features bright, colorful graphics and addictive gameplay. Master the bubble-bouncing physics across five themed worlds to reach the ultimate boss.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Spark World (Japan)', '1995', NaN, 'Kaneko', '1', NaN, 'Competitive top-down puzzle game (Bomberman style).', 'Defeat your rivals in a maze of explosive sparks.', 'Explore Spark World on the Super Famicom.', 'A 16-bit competitive gem. Similar to Bomberman but with a vehicular theme. Use various power-ups and specialized spark weapons to outmaneuver opponents in 4-player combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sparkster (Europe)', '1994', NaN, 'Minakuchi Engineering', '1', NaN, 'Side-scrolling action starring the rocket-powered opossum.', 'Stop the Gedol Empire and rescue the princess.', 'Experience Sparkster on the Super Nintendo.', 'A 16-bit masterpiece from Konami. Use your jetpack to dash across levels, perform acrobatic sword slashes, and engage in epic, cinematic boss battles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sparkster (Japan)', '1994', NaN, 'Minakuchi Engineering', '1', NaN, 'Side-scrolling action-platformer (Japanese release).', 'Master the rocket-dash in the official Japanese version.', 'Play Sparkster on the Super Famicom.', 'The official 16-bit Japanese edition of the Rocket Knight sequel. Features incredible fluid animation, massive sprites, and some of the best music on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sparkster (USA)', '1994', NaN, 'Minakuchi Engineering', '1', NaN, 'Side-scrolling action with intense jetpack mechanics.', 'Avenge your kingdom in this high-octane 16-bit quest.', 'Play the classic Sparkster on the SNES.', 'Separate from the Genesis version, this SNES entry features unique levels and mechanics. Use your rocket pack for both traversal and powerful drill attacks.', NULL);
