INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Spawn (USA)', '1995', NaN, 'Ukiyotei', '1', NaN, 'Side-scrolling beat ''em up starring the Hellspawn.', 'Reclaim your soul in this cinematic 16-bit brawler.', 'Play the official Spawn game on the SNES.', 'Features complex combat mechanics including defensive blocks and special magical attacks. A challenging 16-bit title that captures the dark aesthetic of Todd McFarlane''s creation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Spectre (Europe)', '1994', NaN, 'Velocity', '1', NaN, '3D-style tank combat using Mode 7 and scaling.', 'Destroy the enemy cyber-tanks in a futuristic arena.', 'Experience the 3D action of Spectre on the SNES.', 'A 16-bit port of the Macintosh classic. Navigate a wireframe-style 3D world, collect flags, and engage in tactical tank warfare in both solo and multiplayer modes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Spectre (USA)', '1994', NaN, 'Velocity', '1', NaN, '3D-style tank combat simulation (USA release).', 'Master the arena in this 16-bit vehicular shooter.', 'Play the futuristic Spectre on the Super Nintendo.', 'Features multiple tank types and a fast-paced Battle mode. A technical 16-bit achievement that provides a unique sense of depth and speed for the era.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Speed Racer (USA)', '1993', NaN, 'Radical Entertainment', '1', NaN, 'Fast-paced racing based on the classic anime.', 'Win the world grand prix with the legendary Mach 5.', 'Race to victory in Speed Racer for the SNES.', 'A high-speed 16-bit racer. Use the Mach 5''s special gadgets, including the rotary saws and jumping jacks, to overcome obstacles and sabotage rival racers.', NULL);
