INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Speedy Gonzales in Los Gatos Bandidos (USA) (Rev A)', '1995', NaN, 'Sunsoft', '1', NaN, 'Fast-paced side-scrolling platformer (Updated Revision).', 'Experience the refined quest in this polished 16-bit version.', 'Play Speedy Gonzales (Rev A) on the SNES.', 'The updated 16-bit retail version. Fixes minor graphical glitches and improves performance during high-speed sequences, offering the most stable official experience.', NULL);
