INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Spider-Man (USA) (Beta)', '1994', NaN, 'Western Technologies', '1', NaN, 'Side-scrolling action-platformer (Pre-release build).', 'Test the web-swinging physics and boss AI.', 'Check out the Spider-Man Beta on the SNES.', 'A rare 16-bit development look at the animated series tie-in. Witness early level layouts and sprite animations before the final balancing of the web-slinging mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Spider-Man & Venom - Maximum Carnage (Europe)', '1994', NaN, 'Software Creations', '1', NaN, 'Side-scrolling beat ''em up based on the comic event.', 'Stop Carnage''s massacre by choosing between Spidey or Venom.', 'Play Spider-Man & Venom: Maximum Carnage on SNES.', 'A 16-bit cult classic. Features a striking art style based on the comics and a brutal difficulty curve. Use various Marvel cameos to clear waves of enemies in NYC.', NULL);
