INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Spindizzy Worlds (USA)', '1993', NaN, 'ASCII Entertainment', '1', NaN, 'Isometric puzzle and exploration (USA release).', 'Solve the cosmic labyrinths in this 16-bit puzzler.', 'Play Spindizzy Worlds for the Super Nintendo.', 'A meditative yet challenging logic game. Use the 16-bit rotation mechanics to find the best path through floating platforms and hazardous traps.', NULL);
