INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Fox - EX', '1993', NaN, 'Nintendo', '1', NaN, 'Fan-made expansion/overhaul of Star Fox (EX).', 'Experience an expanded Lylat System with new features.', 'Play the Star Fox EX mod on the Super Nintendo.', 'An impressive 16-bit fan modification that adds new levels, ships, and features to the original Star Fox engine, pushing the Super FX chip to its limits.', NULL);
