INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Fox (USA) (Super Weekend Competition)', '1993', NaN, 'Nintendo', '1', NaN, '3D rail shooter (Competitive Weekend Version).', 'Achieve the highest score in this rare competition build.', 'Play Star Fox Super Weekend on the SNES.', 'A rare 16-bit historical artifact used in official 1993 Nintendo tournaments. Features a timed, high-score focused version of the game with unique level shortcuts.', NULL);
