INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Fox Exploration Showcase 7.86.3', '2021', NaN, 'Homebrew', '1', NaN, '3D space combat (Exploration Hack 7.86.3).', 'Unlock the hidden debug features of the Lylat System.', 'Explore the Star Fox Exploration Showcase on SNES.', 'A 16-bit technical mod designed to showcase the internal assets of the Star Fox engine. Allows players to fly through unreleased test environments and view hidden object models.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Fox Exploration Showcase 8.48.1', '2022', NaN, 'Homebrew', '1', NaN, '3D space combat (Exploration Hack 8.48.1).', 'Discover hidden 3D assets and technical secrets.', 'Experience Star Fox Exploration Showcase 8 on SNES.', 'An updated 16-bit technical demonstration. Features expanded camera controls and the ability to trigger unused scripted events, pushing the Super FX chip to its limits for research.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Ocean (Japan)', '1996', NaN, 'Tri-Ace', '1', NaN, 'Epic JRPG with real-time combat and voice acting.', 'Travel across planets to stop a galactic biological threat.', 'Experience the stunning Star Ocean on Super Famicom.', 'One of the most advanced 16-bit RPGs. Uses the S-DD1 chip for high-quality compression, featuring pre-rendered backgrounds, voice clips during battle, and a deep crafting system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Ocean (Japan) [En by DeJap v1.0]', '1996', NaN, 'Tri-Ace', '1', NaN, 'Epic JRPG (Full English Translation v1.0).', 'Experience the first Star Ocean in English.', 'Play Star Ocean in English on the Super Nintendo.', 'The legendary 16-bit fan translation by DeJap. Brings the massive sci-fi narrative and complex Private Action character system to Western players for the first time.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Trek - Deep Space Nine - Crossroads of Time (Europe)', '1995', NaN, 'Novotrade', '1', NaN, 'Cinematic action-adventure based on the TV series.', 'Stop a Bajoran terrorist plot as Sisko and the crew.', 'Play Star Trek: DS9 Crossroads of Time on SNES.', 'A multi-genre 16-bit adventure. Combines side-scrolling platforming and combat on alien worlds with tactical dialogue sequences and space-station exploration.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Trek - Deep Space Nine - Crossroads of Time (USA)', '1995', NaN, 'Novotrade', '1', NaN, 'Cinematic action-adventure (USA release).', 'Protect Deep Space Nine in this 16-bit sci-fi quest.', 'Experience Star Trek: DS9 for the Super Nintendo.', 'Features digitized sprites of the show''s cast. Navigate through 16-bit environments inspired by the Alpha Quadrant, solving puzzles and battling the Jem''Hadar.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Trek - Deep Space Nine - Crossroads of Time (USA) (Beta)', '1995', NaN, 'Novotrade', '1', NaN, 'Cinematic action-adventure (Pre-release build).', 'Test the early phaser combat and platforming levels.', 'Check out the Star Trek: DS9 Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character''s movement animations and the evolution of the space station''s hub area.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Trek - Starfleet Academy (Europe)', '1995', NaN, 'Interplay', '1', NaN, 'Space flight simulation and bridge command.', 'Graduate from the Academy and become a Starfleet officer.', 'Experience Star Trek: Starfleet Academy on SNES.', 'A technical 16-bit flight sim. Complete various bridge-command scenarios, managing shields, weapons, and crew while navigating through 3D space environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Trek - Starfleet Academy (Germany)', '1995', NaN, 'Interplay', '1', NaN, 'Space flight simulation (German localization).', 'Bestehe die Prüfungen der Sternenflotte auf Deutsch.', 'Spielen Sie Starfleet Academy auf Deutsch für das SNES.', 'The complete 16-bit simulation localized for German players. Master the bridge controls and diplomatic choices across dozens of challenging training missions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Trek - Starfleet Academy (USA)', '1995', NaN, 'Interplay', '1', NaN, 'Space flight simulation and tactical combat.', 'Master the bridge of a Federation starship in 16-bit.', 'Play Star Trek: Starfleet Academy for the SNES.', 'Includes various mission types from dogfights to diplomatic negotiations. A unique simulation that emphasizes tactical decision-making over pure arcade action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Trek - The Next Generation - Future''s Past (Europe)', '1994', NaN, 'Sculptured Software', '1', NaN, 'Tactical adventure based on the TNG series.', 'Save the Romulan neutral zone as Captain Picard.', 'Play Star Trek: TNG Future''s Past on the SNES.', 'A 16-bit mix of top-down away-team missions and bridge-view space combat. Navigate the Enterprise through the sector and solve the mystery of an ancient civilization.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Star Trek - The Next Generation - Future''s Past (USA)', '1994', NaN, 'Sculptured Software', '1', NaN, 'Tactical adventure and space combat (USA release).', 'Command the Enterprise-D in this 16-bit sci-fi sim.', 'Experience Star Trek: TNG Future''s Past on SNES.', 'Features a non-linear mission structure. Manage ship energy, transport teams to planets for puzzle-solving, and engage in tactical 16-bit battles with Warbirds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stardust Suplex (Japan)', '1995', NaN, 'Human Entertainment', '2', NaN, '2D professional wrestling with anime-style graphics.', 'Win the wrestling championship in this 16-bit fighter.', 'Experience Stardust Suplex on the Super Famicom.', 'A technical 16-bit wrestling game from Varie. Features an all-female cast, fluid animations, and a deep moveset including high-flying maneuvers and submission holds.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stargate (Europe) (En,Fr,De)', '1994', NaN, 'Probe Entertainment', '1', NaN, 'Cinematic action-platformer based on the 1994 film.', 'Travel through the gate and defeat the false god Ra.', 'Play the official Stargate on the Super Nintendo.', 'A visually impressive 16-bit title. Use grenades and machine guns to fight through Abydos, featuring a mix of action, mission objectives, and puzzle-solving.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stargate (Japan)', '1994', NaN, 'Probe Entertainment', '1', NaN, 'Cinematic action-platformer (Japanese release).', 'Experience the sci-fi epic in the Japanese edition.', 'Play Stargate on the Super Famicom.', 'The official 16-bit Japanese port. Features the same cinematic presentation and high level of difficulty, capturing the atmosphere of the movie''s desert world and high-tech temple.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stargate (USA)', '1994', NaN, 'Probe Entertainment', '1', NaN, 'Cinematic action-platformer featuring Daniel and O''Neil.', 'Navigate the 16-bit desert world and free the slaves.', 'Experience the high-stakes Stargate on the SNES.', 'Known for its detailed sprites and faithful adaptation of the film''s plot. Master the 16-bit combat and complete diverse mission goals to find the way back home.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stargate (USA) (Beta)', '1994', NaN, 'Probe Entertainment', '1', NaN, 'Cinematic action-platformer (Pre-release build).', 'Test the early gunplay and Abydos stage layouts.', 'Check out the Stargate Beta on the Super Nintendo.', 'A rare 16-bit development slice. Witness the initial implementation of the cinematic cutscenes and the tuning of the enemy AI behavior before the final release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Starwing (Europe)', '1993', NaN, 'Nintendo', '1', NaN, 'Groundbreaking 3D rail shooter (European release).', 'Defeat Andross in the official European edition.', 'Experience the classic Starwing on the SNES.', 'The PAL version of Star Fox. Named Starwing due to trademark issues in Europe, it features the same revolutionary 16-bit 3D gameplay powered by the Super FX chip.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Starwing (Europe) (Rev A)', '1993', NaN, 'Nintendo', '1', NaN, '3D rail shooter (Updated European Revision).', 'Defeat Andross in the most polished PAL version.', 'Play Starwing (Rev A) on the Super Nintendo.', 'The optimized 16-bit European release. Fixes minor performance issues and localization bugs from the initial launch, providing the smoothest Super FX experience for PAL consoles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Starwing (Europe) (Super Weekend Competition)', '1993', NaN, 'Nintendo', '1', NaN, '3D rail shooter (European Competition Edition).', 'Achieve the top score in this rare 16-bit tournament.', 'Experience the Starwing Super Weekend on SNES.', 'A legendary 16-bit historical artifact. Used in the 1993 European Nintendo competitions, featuring a timed score-attack mode with unique shortcuts and bonus items.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Starwing (Germany)', '1993', NaN, 'Nintendo', '1', NaN, '3D rail shooter (German localization).', 'Rette das Lylat-System in der deutschen Version.', 'Spielen Sie Starwing auf Deutsch für das SNES.', 'The complete 16-bit 3D classic with full German text. Command Fox McCloud''s team through polygonal worlds in this landmark title for the Super Nintendo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Starwing (Germany) (Competition Edition)', '1993', NaN, 'Nintendo', '1', NaN, '3D rail shooter (German Competition Edition).', 'Win the German 16-bit Starwing championship.', 'Experience the Starwing Competition Edition (Germany).', 'A rare promotional 16-bit cartridge used in German gaming events. Features the high-score focused Super Weekend gameplay loop designed for competitive play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stealth (Japan)', '1992', NaN, 'ASCII', '1', NaN, 'Tactical stealth-action and strategy.', 'Infiltrate enemy territory without being detected.', 'Explore the tactical Stealth on Super Famicom.', 'A unique 16-bit strategy title. Focuses on line-of-sight mechanics and careful movement to complete covert missions during a fictional military conflict.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Steel Talons (USA)', '1994', NaN, 'Atari Games', '1', NaN, '3D helicopter combat simulation.', 'Complete dangerous missions in an ATLH helicopter.', 'Experience Steel Talons on the Super Nintendo.', 'A 16-bit port of the Atari arcade hit. Uses polygonal-style graphics to simulate flight and ground-attack missions across various desert and urban environments.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sterling Sharpe End 2 End (USA)', '1995', NaN, 'Midway', '2', NaN, 'Realistic American Football simulation.', 'Lead your team to the championship with Sterling Sharpe.', 'Play Sterling Sharpe End 2 End on the SNES.', 'A technical 16-bit football sim. Features detailed playbooks, smooth field scrolling, and a focus on realistic player stats endorsed by the legendary wide receiver.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Steven Seagal Is The Final Option (USA) (Proto)', '1994', NaN, 'Virgin Interactive', '1', NaN, 'Side-scrolling beat ''em up (Unreleased Prototype).', 'Defeat the underworld as the martial arts master.', 'Explore Steven Seagal Is The Final Option on SNES.', 'A rare 16-bit unreleased brawler. Features digitized sprites of Steven Seagal and a technical combat system focused on aikido throws and joint locks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stone Protectors (Japan) (Proto)', '1994', NaN, 'Eurocom', '2', NaN, 'Side-scrolling beat ''em up (Japanese Prototype).', 'Stop the Zokks in this anime-inspired 16-bit brawler.', 'Check out Stone Protectors on the Super Famicom.', 'A rare 16-bit development look at the Japanese localization. Features vibrant graphics and specialized moves for each of the five gem-powered heroes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stone Protectors (USA)', '1994', NaN, 'Eurocom', '2', NaN, 'Side-scrolling beat ''em up based on the toy line.', 'Recover the Great Crystals and defeat Zok.', 'Play the action-packed Stone Protectors on SNES.', 'A colorful and high-energy 16-bit brawler. Combines traditional beat ''em up gameplay with a variety of special moves and rock-and-roll themes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Combat (Europe)', '1993', NaN, 'Players', '2', NaN, '2D fighting game with futuristic warriors.', 'Defeat the master fighters in this localized 16-bit brawler.', 'Experience Street Combat on the Super Nintendo.', 'The Western version of Ranma 1/2: Chounai Gekitouhen. Replaces the anime characters with generic cybernetic warriors while retaining the original combat mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Combat (USA)', '1993', NaN, 'Players', '2', NaN, '2D fighting game with specialized combatants.', 'Win the underground tournament in this 16-bit fighter.', 'Play Street Combat for the Super Nintendo.', 'Features a variety of fighter types, from robots to martial artists. A unique 16-bit curiosity that showcases how Japanese games were re-skinned for Western markets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Fighter Alpha 2 (Europe)', '1996', NaN, 'Capcom', '2', 2, 'High-speed 2D fighting game (Alpha series).', 'Experience the prequel saga with advanced 16-bit graphics.', 'Play Street Fighter Alpha 2 on the SNES.', 'A technical miracle on 16-bit hardware. Uses the S-DD1 chip to deliver massive sprites and advanced mechanics like Custom Combos and Alpha Counters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Fighter Alpha 2 (USA)', '1996', NaN, 'Capcom', '2', 2, 'High-speed 2D fighting game (USA release).', 'Master the legendary combos in this 16-bit masterpiece.', 'Experience Street Fighter Alpha 2 on the SNES.', 'Features an iconic roster including Ryu, Ken, and Akuma. Brings the deep, technical gameplay of the arcade original to the Super Nintendo with impressive fidelity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Fighter EX Plus Alpha', '1997', NaN, 'Arika', '2', 3, '3D-to-2D fighting game (Unlicensed/Pirate).', 'Fight through the EX roster in this unofficial port.', 'Check out the 16-bit Soul Blade/Street Fighter EX.', 'A bizarre 16-bit unlicensed curiosity. Attempts to translate the 32-bit polygonal fighter into a 2D sprite-based experience on the SNES hardware.', NULL);
