INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Fighter II - The World Warrior (Japan)', '1992', NaN, 'Capcom', '2', 2, 'The foundational 2D fighting game (Japanese release).', 'Challenge the world''s best in the original Japanese port.', 'Play Street Fighter II on the Super Famicom.', 'The massive 16-bit hit that sold millions in Japan. Features the complete arcade roster and the timeless soundtrack that defined the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Fighter II - The World Warrior (USA)', '1992', NaN, 'Capcom', '2', 2, 'The foundational 2D fighting game (USA release).', 'Become the world champion in this 16-bit legend.', 'Experience Street Fighter II for the Super Nintendo.', 'Master the Hadouken and Sonic Boom. This 16-bit port set the standard for all home console fighters to follow, offering near arcade-quality play.', NULL);
