INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Fighter II Turbo - Hyper Fighting (Japan) (Rev 0A)', '1993', NaN, 'Capcom', '2', 2, 'Enhanced 2D fighting game (Japanese Revision).', 'Master the high-speed combat in the revised Japanese port.', 'Play Street Fighter II Turbo on the Super Famicom.', 'The optimized 16-bit Japanese release. Features the Hyper mode for extreme speed and the traditional Turbo mode for competitive balance.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Fighter II Turbo - Hyper Fighting (USA)', '1993', NaN, 'Capcom', '2', 2, 'High-speed 2D fighting game (USA retail).', 'Defeat your rivals at lightning speed in 16-bit.', 'Experience Street Fighter II Turbo on the SNES.', 'Considered by many to be the best fighting game on the system. Master the refined hitboxes and the expanded move lists of the world''s greatest warriors.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Fighter Zero 2 (Japan)', '1996', NaN, 'Capcom', '2', 2, 'High-speed 2D fighting game (Japanese Alpha 2).', 'Experience the prequel lore in the original Japanese version.', 'Play Street Fighter Zero 2 on the Super Famicom.', 'The official 16-bit Japanese release. Features the full Zero roster and cinematic story endings, pushing the SNES hardware to its absolute limit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Hockey ''95 (USA)', '1995', NaN, 'FTL Games', '2', NaN, 'Fast-paced urban sports simulation.', 'Win the street hockey tournament in the city.', 'Play Street Hockey ''95 on the Super Nintendo.', 'A unique 16-bit sports title. Swap traditional ice for asphalt and use a variety of street moves and power-ups to defeat rival teams in various urban arenas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Hockey ''95 (USA) (Beta)', '1995', NaN, 'FTL Games', '2', NaN, 'Urban sports simulation (Pre-release build).', 'Test the early skating physics and puck logic.', 'Check out the Street Hockey ''95 Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character''s rollerblade animations and the tuning of the AI''s defensive behavior.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Racer (Europe)', '1994', NaN, 'Vivid Image', '4', NaN, 'Mode 7 racing game with 8-player local play.', 'Outrace and outfight your rivals in this 16-bit classic.', 'Experience the chaotic Street Racer on the SNES.', 'A technical 16-bit marvel. Similar to Mario Kart but with a focus on combat and a smooth frame rate that supports up to 4 players on a split-screen.', NULL);
