INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Racer (Japan)', '1994', NaN, 'Vivid Image', '4', NaN, 'Mode 7 racing game (Japanese release).', 'Win the world championship in the official Japanese version.', 'Play Street Racer on the Super Famicom.', 'The 16-bit Japanese edition of the hit racer. Features quirky characters, diverse tracks, and the addictive Soccer and Rumble bonus modes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Racer (USA)', '1994', NaN, 'Vivid Image', '4', NaN, 'Mode 7 racing game featuring diverse characters.', 'Use specialized attacks to clear the track and win.', 'Experience Street Racer for the Super Nintendo.', 'Master the unique abilities of characters like Hodja or Surf. A high-energy 16-bit racer that pushes the SNES hardware with impressive scaling and rotation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Street Racer (USA) (Beta)', '1994', NaN, 'Vivid Image', '4', NaN, 'Mode 7 racing game (Pre-release build).', 'Test the early weapon logic and track scaling.', 'Check out the Street Racer Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the character-specific combat moves and the initial implementation of the bonus mini-games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Strike Gunner S.T.G (Japan)', '1991', NaN, 'Athena', '2', NaN, 'Vertical-scrolling shoot ''em up with a weapon-selection system.', 'Defeat the alien invasion using customizable jet fighters.', 'Experience the intense Strike Gunner S.T.G on SNES.', 'A technical 16-bit shooter. Before each stage, choose from a variety of specialized sub-weapons like homing missiles or sonic waves to complement your dual-pilot fire.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Strike Gunner S.T.G (USA)', '1991', NaN, 'Athena', '2', NaN, 'Vertical-scrolling shoot ''em up (USA release).', 'Master the 16-bit skies in this cooperative shooter.', 'Play Strike Gunner S.T.G on the Super Nintendo.', 'Features a robust two-player mode where pilots can link their ships for combined firepower. Battle through diverse environments from high-tech bases to jungle landscapes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Striker (Europe) (En,Fr,De,Es,It,Nl,Sv)', '1994', NaN, 'Rage Software', '2', NaN, 'Fast-paced soccer simulation with Mode 7 effects.', 'Win the World Cup in this agile 16-bit sports sim.', 'Play the classic Striker on the Super Nintendo.', 'Known for its incredible speed and 3D perspective. Features over 40 teams, indoor soccer modes, and highly responsive controls that emphasize quick passing.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Striker (Europe) (En,Fr,De,Es,It,Nl,Sv) (Beta)', '1994', NaN, 'Rage Software', '2', NaN, 'Fast-paced soccer simulation (Pre-release build).', 'Test the early ball physics and Mode 7 rotation.', 'Check out the Striker Beta on the Super Nintendo.', 'A rare 16-bit development look. Witness the fine-tuning of the camera angles and the initial implementation of the penalty shootout mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stunt Race FX (Europe)', '1994', NaN, 'Nintendo', '2', 3, '3D polygonal racing game using the Super FX chip.', 'Win the 16-bit stunt grand prix in a world of polygons.', 'Experience Stunt Race FX on the Super Nintendo.', 'A technical marvel. Use the Super FX chip to race sentient, expressive vehicles across tracks filled with obstacles, jumps, and impressive 3D geometry.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Stunt Race FX (USA)', '1994', NaN, 'Nintendo', '2', 3, '3D polygonal racing game featuring three vehicle types.', 'Master the physics of the F-Type, COUPE, and 4WD.', 'Play the revolutionary Stunt Race FX on SNES.', 'Includes a Stunt Radio Control mode and a challenging battle mode. One of the few 16-bit games to offer a fully 3D racing experience with real-time scaling and rotation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sufami Turbo Add-On Base Cassette (Japan)', '1996', NaN, 'Nintendo', '1', NaN, 'Hardware interface for Bandai''s mini-cartridge system.', 'The base unit required to play Sufami Turbo games.', 'Explore the Sufami Turbo Add-On for Super Famicom.', 'A unique 16-bit peripheral. This base cartridge allowed users to slot in two smaller games at once, enabling data sharing between specific Bandai titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sugoi Hebereke (Japan)', '1994', NaN, 'Sunsoft', '4', NaN, 'Competitive 2D arena fighter with Hebereke characters.', 'Defeat your rivals in this quirky chibi brawler.', 'Play Sugoi Hebereke on the Super Famicom.', 'A fast-paced 4-player fighting game. Features colorful sprites, environmental hazards, and the surreal humor the Sunsoft Ufouria series is known for.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sugoro Quest++ - Dicenics (Japan)', '1993', NaN, 'Technos Japan', '2', NaN, 'RPG and board game hybrid featuring dice-based combat.', 'Defeat the Dark Lord using strategic dice rolls.', 'Explore Sugoro Quest++ Dicenics on SNES.', 'A charming 16-bit hybrid. Navigate a board-game world where encounters are resolved through a unique Dicenics system, blending luck with tactical RPG growth.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sugoroku Ginga Senki (Japan)', '1994', NaN, 'Bottom Up', '2', NaN, 'Sci-fi strategy board game set in outer space.', 'Conquer the galaxy through strategic dice play and trade.', 'Play Sugoroku Ginga Senki on Super Famicom.', 'A deep 16-bit cosmic simulation. Manage a fleet of ships, colonize planets, and outmaneuver rival factions in a high-stakes board game for control of the universe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sunset Riders (Europe)', '1993', NaN, 'Konami', '2', NaN, 'Side-scrolling run-and-gun western action.', 'Hunt down the four outlaws and claim the bounties.', 'Experience Sunset Riders on the Super Nintendo.', 'A pixel-perfect 16-bit arcade port. Choose between Steve, Billy, Bob, or Cormano to blast through the Wild West, featuring iconic boss fights and bonus stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Sunset Riders (USA)', '1993', NaN, 'Konami', '2', NaN, 'Side-scrolling run-and-gun western (USA release).', 'Clean up the frontier in this legendary 16-bit shooter.', 'Play the classic Sunset Riders on the SNES.', 'Features simultaneous 2-player action and vibrant graphics. Ride horses, dodge stampedes, and take down the toughest outlaws in this Konami masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Supapoon (Japan)', '1995', NaN, 'Thinking Rabbit', '2', NaN, 'Gravity-based puzzle game with a cute protagonist.', 'Clear the boards by matching colored slimes.', 'Explore the colorful Supapoon on Super Famicom.', 'A unique 16-bit puzzler. Control a bouncing character to clear blocks while managing gravity and momentum in a series of increasingly difficult levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Supapoon DX (Japan)', '1996', NaN, 'Thinking Rabbit', '2', NaN, 'Enhanced gravity-based puzzle sequel.', 'Master the new block types in this polished puzzle DX.', 'Experience Supapoon DX on the Super Famicom.', 'The refined 16-bit edition. Features improved graphics, more complex level designs, and a robust 2-player competitive mode to test your speed and logic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Mario World', '1990', NaN, 'Nintendo', '2', NaN, 'Bootleg/Unlicensed platformer starring Mario.', 'Navigate the bizarre unlicensed world as a fake Mario.', 'Check out the bootleg Super Mario World on SNES.', 'A 16-bit curiosity. Actually a re-skinned version of other platformers, serving as a fascinating (and often glitchy) artifact of the pirate game era.', NULL);
