INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super 4WD - The Baja (Japan)', '1992', NaN, 'Lenar', '2', NaN, 'Off-road racing simulation based on the Baja 1000.', 'Conquer the desert terrain in your custom 4WD.', 'Experience Super 4WD: The Baja on SNES.', 'A technical 16-bit racer using Mode 7 for terrain simulation. Manage your vehicle''s damage and fuel while navigating through night stages and sand dunes.', NULL);
