INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Adventure Island (USA)', '1992', NaN, 'Hudson Soft', '2', NaN, 'Side-scrolling platformer featuring Master Higgins.', 'Survive the 16-bit hazards of the tropical islands.', 'Experience Super Adventure Island for the SNES.', 'Master the skateboard and stone axe mechanics. A colorful and challenging platformer that showcases high-quality sprite work and catchy melodies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Adventure Island II (Europe)', '1994', NaN, 'Hudson Soft', '2', NaN, 'Action-RPG and exploration platformer.', 'Search the islands to find your missing bride, Tina.', 'Play Super Adventure Island II on the SNES.', 'A massive departure for the series. Features a world map, equippable weapons, and Metroidvania-style exploration across diverse themed islands.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Adventure Island II (USA)', '1994', NaN, 'Hudson Soft', '2', NaN, 'Action-RPG and exploration platformer (USA release).', 'Master the elemental swords in this 16-bit epic.', 'Experience Super Adventure Island II on the SNES.', 'Unlike the first game, this 16-bit entry focuses on puzzle-solving and character growth, offering a much deeper and more atmospheric adventure.', NULL);
