INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Black Bass (Japan)', '1992', NaN, 'Starfish', '1', NaN, 'The original Japanese bass fishing simulation.', 'Catch the legendary black bass in Japanese lakes.', 'Play Super Black Bass on the Super Famicom.', 'The game that started the 16-bit fishing craze. Features a dual-perspective view: top-down for lure placement and underwater for the actual struggle with the fish.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Black Bass (USA)', '1992', NaN, 'Starfish', '1', NaN, 'Realistic bass fishing simulation (USA release).', 'Win the bass tournament circuit in this 16-bit sim.', 'Experience Super Black Bass on the Super Nintendo.', 'Features realistic weather effects and lure physics. Master the fighting mechanic to reel in massive fish without snapping your line.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Black Bass 2 (Japan)', '1993', NaN, 'Starfish', '1', NaN, 'Enhanced bass fishing simulation sequel.', 'Master the new lures and lakes in this 16-bit sequel.', 'Experience Super Black Bass 2 on Super Famicom.', 'Features improved graphics and more responsive fish AI. Includes a wider variety of equipment and a deeper career mode for aspiring 16-bit anglers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Black Bass 3 (Japan)', '1994', NaN, 'Starfish', '1', NaN, 'The most advanced 16-bit bass fishing simulation.', 'Conquer the professional world tour in the final entry.', 'Play Super Black Bass 3 on the Super Famicom.', 'A technical marvel for a fishing game. Features incredible underwater animations, a massive selection of tackle, and highly realistic environmental conditions.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Black Bass 3 (Japan) (Rev A)', '1994', NaN, 'Starfish', '1', NaN, 'Advanced bass fishing (Updated Revision).', 'Experience the refined fishing simulation in Rev A.', 'Play Super Black Bass 3 (Rev A) on Super Famicom.', 'The final 16-bit retail revision. Optimizes the fish behavior algorithms and fixes minor graphical glitches during the lure-retrieval sequences.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super BlueYoshi Kart 1.1', '2019', NaN, 'Fanmade', '4', NaN, 'Fan-made Mario Kart modification featuring Blue Yoshi.', 'Race as Blue Yoshi in this custom 16-bit overhaul.', 'Try Super BlueYoshi Kart on the SNES.', 'A creative 16-bit romhack of Super Mario Kart. Replaces characters and adds custom track palettes for a fresh take on the racing classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super BlueYoshi Kart EXPERT 1.1', '2019', NaN, 'Fanmade', '4', NaN, 'Fan-made Mario Kart (Expert Edition Hack).', 'Test your skills on brutal custom 16-bit tracks.', 'Play BlueYoshi Kart EXPERT on the SNES.', 'A high-difficulty modification of Super Mario Kart. Features redesigned tracks with extreme hazards and tighter turns for veterans seeking a new challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Bomberman - Panic Bomber W (Japan)', '1992', NaN, 'Hudson Soft', '2', NaN, 'Falling-block puzzle game with a Bomberman theme.', 'Match three heads of the same color to clear the board.', 'Experience Super Bomberman: Panic Bomber W on SNES.', 'A unique 16-bit puzzle spin-off. Combine classic falling-block mechanics with the explosive power of Bomberman''s bombs to trigger chain reactions and defeat your opponents.', NULL);
