INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Bomberman (Japan)', '1993', NaN, 'Hudson Soft', '4', NaN, 'Top-down action and multiplayer combat (Original release).', 'Become the ultimate bomber in the Japanese original.', 'Experience Super Bomberman on the Super Famicom.', 'The game that redefined local multiplayer. Master the art of trap-setting and power-up collection in this foundational 16-bit action masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Bomberman (USA)', '1993', NaN, 'Hudson Soft', '4', NaN, 'Top-down maze-based action (USA release).', 'Stop the Diamond Blue forces in this 16-bit classic.', 'Play Super Bomberman for the Super Nintendo.', 'Features a full single-player adventure and the definitive competitive battle mode. Use kick and throw power-ups to dominate the 16-bit arena.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Bomberman 2 - Caravan Event Ban (Japan)', '1994', NaN, 'Hudson Soft', '4', NaN, 'Top-down action (Limited Caravan Event Version).', 'Achieve the highest score in the timed Caravan challenge.', 'Check out Super Bomberman 2 (Caravan Ban) on SNES.', 'A rare 16-bit promotional edition. Features a specialized Score Attack mode used in 1994 Japanese gaming tournaments, focusing on quick clears and point efficiency.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Bomberman 2 (Europe)', '1994', NaN, 'Hudson Soft', '4', NaN, 'Top-down action and puzzle-solving sequel.', 'Defeat the Five Dastardly Bombers to save Earth.', 'Play Super Bomberman 2 on the Super Nintendo.', 'Widely considered the best battle mode in the series. Features unique level hazards, improved AI, and a much more cinematic and varied single-player campaign.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Bomberman 2 (Japan)', '1994', NaN, 'Hudson Soft', '4', NaN, 'Top-down action sequel (Original Japanese release).', 'Master the new bomb types in this 16-bit sequel.', 'Experience Super Bomberman 2 on the Super Famicom.', 'Introduces the ability to pick up and throw bombs. A 16-bit classic that perfected the balance between competitive strategy and chaotic fun.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Bomberman 2 (USA)', '1994', NaN, 'Hudson Soft', '4', NaN, 'Top-down action sequel (USA release).', 'Blast your way through the space stations of the Five Bombers.', 'Play Super Bomberman 2 for the Super Nintendo.', 'Navigate through five massive worlds with unique boss encounters. The 16-bit battle mode features more stages and custom rules than ever before.', NULL);
