INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Bomberman 3 (Japan)', '1995', NaN, 'Hudson Soft', '5', NaN, 'Top-down action with riding mounts (Japanese release).', 'Master the Louie mounts in the original Japanese version.', 'Play Super Bomberman 3 on the Super Famicom.', 'Expanded 16-bit multiplayer fun. Includes a diverse cast of international Bomberman characters and a colorful, globe-trotting single-player adventure.', NULL);
