INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Bomberman 5 (English - Translated)', '1997', NaN, 'Hudson Soft', '5', NaN, 'Top-down action with non-linear progression (English).', 'Complete the final 16-bit saga with full English text.', 'Play Super Bomberman 5 in English on the SNES.', 'The ultimate fan-translated 16-bit experience. Features a non-linear map with multiple endings and the most polished battle mode in the entire SNES library.', NULL);
