INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Copa (Brazil) (Es,Pt)', '1992', NaN, 'U.S. Gold', '2', NaN, 'Soccer simulation localized for the South American market.', 'Win the championship in this 16-bit soccer classic.', 'Play Super Copa in Spanish and Portuguese on SNES.', 'A specialized version of Tony Meola''s Sidekicks. Features localized teams and text, offering a fast-paced 16-bit soccer experience with Mode 7 field effects.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Cup Soccer (Japan)', '1992', NaN, 'Namco', '2', NaN, 'Fast-paced soccer simulation (Japanese release).', 'Master the 16-bit pitch in this polished soccer title.', 'Experience Super Cup Soccer on the Super Famicom.', 'Features smooth animations and intuitive controls. Includes various modes such as exhibition, league, and tournament play with a focus on arcade-style fun.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Daikoukai Jidai (Japan)', '1993', NaN, 'Koei', '1', NaN, 'Naval exploration and trading simulation (Koei).', 'Explore the high seas and build a global trade empire.', 'Play Super Daikoukai Jidai on Super Famicom.', 'Known as Uncharted Waters. A deep 16-bit historical sim. Navigate the globe, trade commodities, and engage in naval combat during the Age of Discovery.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Dany (France)', '1994', NaN, 'Cryo Interactive', '1', NaN, 'Side-scrolling platformer based on the French character.', 'Navigate the 16-bit levels and find the hidden secrets.', 'Experience Super Dany on the Super Famicom.', 'A colorful platformer exclusive to the French market (and Japan). Use various abilities to overcome obstacles and enemies in a whimsical, cartoonish world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Dany (France) (Beta)', '1994', NaN, 'Cryo Interactive', '1', NaN, 'Side-scrolling platformer (French Beta).', 'Test the early platforming physics and enemy AI.', 'Check out the Super Dany Beta on the SNES.', 'A rare 16-bit development slice. Witness the initial implementation of the character''s movement and the early layout of the French-themed stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Dogfight (Japan)', '1993', NaN, 'Namco', '2', NaN, 'Realistic flight combat simulation.', 'Master the dogfight in this technical 16-bit flight sim.', 'Play Super Dogfight on the Super Famicom.', 'Features a cockpit perspective and realistic flight physics. Engaged in intense 1-on-1 aerial duels and complex missions using Mode 7 for 3D-style navigation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Donkey', '1994', NaN, 'Unlicensed', '1', NaN, 'Early development build or hack of Donkey Kong Country.', 'Explore the prototype physics of the Kongs.', 'Check out the Super Donkey build on the SNES.', 'A fascinating 16-bit historical artifact. Shows early asset testing or modifications related to the pre-rendered platforming style of the Donkey Kong series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Donkey Kong (Japan)', '1994', NaN, 'Rare', '2', NaN, 'Groundbreaking pre-rendered side-scrolling platformer.', 'Recover the banana hoard from King K. Rool.', 'Play the legendary Super Donkey Kong on the SNES.', 'The Japanese release of Donkey Kong Country. Revolutionized 16-bit graphics with pre-rendered 3D sprites, featuring perfect controls and an iconic soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Donkey Kong (Japan) (Rev A)', '1994', NaN, 'Rare', '2', NaN, 'Pre-rendered platformer (Updated Revision).', 'Experience the most stable 16-bit Kong adventure.', 'Play Super Donkey Kong (Rev A) on Super Famicom.', 'The refined 16-bit Japanese version. Fixes minor graphical glitches and optimizes loading times for the bonus rooms and transitional cutscenes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Donkey Kong 2 - Dixie & Diddy (Japan)', '1995', NaN, 'Rare', '2', NaN, 'Pre-rendered platformer sequel starring Dixie and Diddy.', 'Rescue Donkey Kong from the clutches of the Kremlings.', 'Play Super Donkey Kong 2 on the Super Famicom.', 'The Japanese release of Diddy''s Kong Quest. Widely considered one of the best 16-bit platformers ever made, featuring complex level design and incredible music.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Donkey Kong 2 - Dixie & Diddy (Japan) (Rev A)', '1995', NaN, 'Rare', '2', NaN, 'Pre-rendered platformer sequel (Updated Revision).', 'Master the 16-bit pirate world in this refined version.', 'Play Super Donkey Kong 2 (Rev A) on SNES.', 'The updated 16-bit retail version in Japan. Fixes specific sound bugs and optimizes the performance during the dense swamp and bramble levels.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Donkey Kong 3 - Nazo no Krems-tou (Japan)', '1996', NaN, 'Rare', '2', NaN, 'The final entry in the 16-bit Kong trilogy.', 'Explore the Northern Kremispher and find the lost Kongs.', 'Play Super Donkey Kong 3 on the Super Famicom.', 'The Japanese release of Dixie Kong''s Double Trouble. Features a more interactive world map, new vehicle mechanics, and stunning late-gen 16-bit visuals.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Donkey Kong 3 - Nazo no Krems-tou (Japan) (Rev A)', '1996', NaN, 'Rare', '2', NaN, 'Pre-rendered platformer (Updated Revision).', 'Achieve 103% completion in the final 16-bit Kong title.', 'Play Super Donkey Kong 3 (Rev A) on SNES.', 'The refined 16-bit final edition. Includes minor balancing tweaks for the mini-games and optimizes the pre-rendered water and lighting effects.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Double Dragon (Europe)', '1992', NaN, 'Technōs Japan', '2', NaN, 'Side-scrolling beat ''em up with technical combat.', 'Defeat the Shadow Warriors using martial arts mastery.', 'Experience Super Double Dragon on the SNES.', 'A deep 16-bit brawler. Unlike other titles in the genre, it features a guard button that allows you to catch enemy punches and perform devastating counter-attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Double Dragon (Europe) (Beta)', '1992', NaN, 'Technōs Japan', '2', NaN, 'Side-scrolling beat ''em up (European Beta).', 'Test the early counter-mechanics and stage flow.', 'Check out the Super Double Dragon Beta on SNES.', 'A rare 16-bit development look. Features a slightly different speed and some unused sprites, showing the evolution of Billy and Jimmy''s combat moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Double Dragon (USA)', '1992', NaN, 'Technōs Japan', '2', NaN, 'Side-scrolling beat ''em up (USA release).', 'Clean up the streets in this technical 16-bit brawler.', 'Play the classic Super Double Dragon on the SNES.', 'Features an adjustable power meter for special attacks and highly detailed backgrounds. A must-play for fans of strategic, methodical beat ''em ups.', NULL);
