INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Double Yakuman II (Japan)', '1994', NaN, 'Namco', '1', NaN, 'Enhanced Mahjong simulation sequel.', 'Master the tiles in this refined 16-bit sequel.', 'Experience Super Double Yakuman II on Super Famicom.', 'Features improved character artwork and more varied game modes, including a story-based tournament path for solo players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Drakkhen (Japan)', '1995', NaN, 'Kemco', '1', NaN, 'Action-RPG with a 3D perspective and open world.', 'Explore the world of Dragon Earth and stop the dark cult.', 'Play Super Drakkhen on the Super Famicom.', 'Known as Dragon View in the West. A unique 16-bit hybrid featuring a first-person world map and side-scrolling action combat in dungeons and towns.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Drift Out - World Rally Championships (Japan)', '1995', NaN, 'Visco', '2', NaN, 'Isometric rally racing simulation.', 'Win the World Rally Championship across global tracks.', 'Play the high-speed Super Drift Out on the SNES.', 'A 16-bit racing gem featuring smooth isometric graphics. Master the art of drifting on snow, dirt, and asphalt with realistic car handling and a wide variety of licensed-style rally vehicles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Dropzone (Europe)', '1994', NaN, 'Eurocom', '2', NaN, 'Fast-paced arena-based shooter.', 'Defend the human colonies from alien invasion in 16-bit.', 'Experience Super Dropzone on the Super Nintendo.', 'A frantic 16-bit update of the arcade classic. Fly in all directions, rescue scientists, and blast alien armadas in this high-intensity intergalactic dogfight.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Dunk Shot (Japan)', '1994', NaN, 'Taito', '2', NaN, 'Basketball simulation with a focus on arcade action.', 'Lead your team to the 16-bit basketball finals.', 'Play Super Dunk Shot on the Super Famicom.', 'Known as Bill Laimbeer''s Combat Basketball in the West, but with a traditional sports theme in Japan. Features responsive controls and a classic top-down perspective for competitive play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Dunk Star (Japan)', '1994', NaN, 'Taito', '2', NaN, 'Competitive basketball simulation.', 'Master the court and become a 16-bit basketball star.', 'Experience Super Dunk Star on the Super Famicom.', 'A polished 16-bit sports title featuring detailed character sprites and a heavy emphasis on timing for shots, rebounds, and defensive steals in a professional league format.', NULL);
