INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Earth Defense Force (Japan)', '1992', NaN, 'Jaleco', '2', NaN, 'Horizontal-scrolling shoot ''em up (Japanese release).', 'Defend the planet in the original Japanese version.', 'Play Super Earth Defense Force on the Super Famicom.', 'Known for its tactical weapon-selection system. Level up your chosen armament through 16-bit stages filled with mechanized enemies and massive environmental hazards.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Earth Defense Force (USA)', '1992', NaN, 'Jaleco', '2', NaN, 'Horizontal-scrolling shoot ''em up (USA release).', 'Master the evolving weapon system in 16-bit.', 'Play the action-packed Super E.D.F. on the SNES.', 'Navigate through six intense levels of aerial combat. Manage your satellite drones to provide offensive cover or defensive shields in this high-stakes sci-fi shooter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super F-1 Hero (Japan)', '1994', NaN, 'Varie', '1', NaN, 'F-1 racing simulation with an arcade feel.', 'Outspeed your rivals and win the 16-bit Grand Prix.', 'Play Super F-1 Hero on the Super Famicom.', 'Features a fast-paced Mode 7 engine. Customize your car''s settings and compete on various international tracks in a quest to become the ultimate formula racing champion.', NULL);
