INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super F1 Circus Limited (Japan)', '1994', NaN, 'Nichibutsu', '1', NaN, 'Limited edition Formula 1 racing simulation.', 'Master the exclusive tracks in this rare 16-bit edition.', 'Check out Super F1 Circus Limited on the SNES.', 'A refined version of the F1 Circus engine featuring specialized balancing and specific track modifications designed for high-level competitive play in the Japanese market.', NULL);
