INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Family Gelaende (Japan) (NP)', '1995', NaN, 'Namco', '4', NaN, 'Skiing and winter sports simulation (Nintendo Power).', 'Conquer the snowy slopes in this 16-bit winter sim.', 'Play Super Family Gelaende on the Super Famicom.', 'A rare ski simulation released via the Nintendo Power service. Master the slaloms and downhill courses using precise 16-bit movement and timing.', NULL);
