INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Famista 4 (Japan)', '1995', NaN, 'Namco', '2', NaN, 'Advanced baseball simulation with realistic stats.', 'Win the Japan series in this technical 16-bit sim.', 'Play Super Famista 4 on the Super Famicom.', 'A significant visual upgrade for the series. Features more realistic player proportions and a refined batting engine that emphasizes timing and pitch placement.', NULL);
