INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling - Queen''s Special (Japan)', '1993', NaN, 'Human Entertainment', '2', NaN, 'Technical women''s wrestling (Joshi Puroresu).', 'Win the Queen''s Special tournament with top female wrestlers.', 'Play Super Fire Pro Wrestling: Queen''s Special on SNES.', 'A technical 16-bit wrestling sim featuring licensed-style female wrestlers. Master the signature grapple and timing system that made the Fire Pro series a cult classic.', NULL);
