INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling (Japan)', '1991', NaN, 'Human Entertainment', '2', NaN, 'Technical 2D wrestling simulation.', 'Master the timing-based grapple system in the series debut.', 'Experience the original Super Fire Pro Wrestling on SNES.', 'The 16-bit foundation of the Fire Pro legend. Replaces button mashing with precise timing, featuring a diverse roster of inspired-by real-world wrestling legends.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling 2 (Japan)', '1992', NaN, 'Human Entertainment', '2', NaN, 'Enhanced technical 2D wrestling sequel.', 'Claim the championship belt in this refined 16-bit sequel.', 'Play Super Fire Pro Wrestling 2 on the Super Famicom.', 'Introduces more wrestlers and refined animations. Features the iconic Edit Mode, allowing players to create their own 16-bit wrestling superstars with custom stats and moves.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling III - Easy Type (Japan)', '1993', NaN, 'Human Entertainment', '2', NaN, 'Technical wrestling (Simplified Easy Type).', 'Enjoy the Fire Pro experience with more accessible controls.', 'Play Fire Pro III: Easy Type on the Super Famicom.', 'A 16-bit variant designed for beginners. Retains the deep moveset but tweaks the timing windows to make the technical grappling easier for new players to master.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling III - Final Bout (Japan)', '1993', NaN, 'Human Entertainment', '2', NaN, 'Advanced technical wrestling simulation.', 'Defeat the world''s best in the Final Bout tournament.', 'Experience Fire Pro III: Final Bout on the Super Famicom.', 'A massive 16-bit upgrade. Features an expanded roster, significantly improved sprites, and more varied match types, including the grueling Gruesome Fighting mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling III - Final Bout (Japan) (Rev A)', '1993', NaN, 'Human Entertainment', '2', NaN, 'Technical wrestling (Updated Revision).', 'Experience the most balanced version of Fire Pro III.', 'Play Fire Pro III (Rev A) on the Super Famicom.', 'The refined 16-bit retail version. Fixes minor AI glitches and optimizes the memory management for the extensive custom wrestler save slots.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling Special (Japan)', '1994', NaN, 'Human Entertainment', '2', NaN, 'Story-driven technical wrestling simulation.', 'Live the tragic life of a pro wrestler in this dark RPG.', 'Experience the epic Fire Pro Special on Super Famicom.', 'Written by Goichi Suda (Suda51). This 16-bit title features a deep, emotional story mode alongside the series'' trademark technical wrestling gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling Special (Japan) (Rev A)', '1994', NaN, 'Human Entertainment', '2', NaN, 'Story-driven wrestling (Updated Revision).', 'Navigate the dark world of pro wrestling in this refined sim.', 'Play Fire Pro Special (Rev A) on the Super Famicom.', 'The optimized 16-bit edition. Includes minor fixes to the branching narrative paths and stabilizes the performance during the massive Battle Royale matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling X (Japan)', '1995', NaN, 'Human Entertainment', '2', NaN, 'Advanced wrestling with a 4-player Multitap.', 'Battle through the technical ranks in this 16-bit classic.', 'Play Super Fire Pro Wrestling X on the Super Famicom.', 'The penultimate SNES entry. Introduces more fluid animations and a massive increase in move variety, supporting up to 4 players for chaotic tag-team action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Fire Pro Wrestling X Premium (Japan)', '1996', NaN, 'Human Entertainment', '2', NaN, 'The ultimate 16-bit wrestling simulation.', 'Master the deepest wrestling game of the 90s.', 'Experience Fire Pro X Premium on the Super Famicom.', 'The definitive version. Features a massive roster of over 80 wrestlers and an incredibly deep Edit Mode. Widely considered one of the greatest 16-bit sports games ever.', NULL);
