INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Formation Soccer ''95 della Serie A (Japan)', '1995', NaN, 'Human Entertainment', '2', NaN, 'Official Serie A Italian league soccer simulation.', 'Master the Italian league with licensed-style teams.', 'Play SFS ''95 della Serie A on the Super Famicom.', 'Focuses exclusively on the Italian Serie A. Includes the era''s superstars and teams, utilizing the series'' trademark 16-bit vertical camera system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Formation Soccer ''96 - World Club Edition (Japan)', '1996', NaN, 'Human Entertainment', '2', NaN, 'Club-focused soccer simulation with global teams.', 'Lead your favorite world club to international glory.', 'Play Super Formation Soccer ''96 on Super Famicom.', 'The final 16-bit entry in the series. Features an enormous roster of club teams from across the world and the most refined version of the vertical gameplay engine.', NULL);
