INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Full Metal (Europe) (It,Sv) (Proto)', '1993', NaN, 'Infogrames', '2', NaN, 'Competitive arena combat (Unreleased Prototype).', 'Battle in high-tech arenas in this rare European proto.', 'Check out Super Full Metal on the Super Nintendo.', 'A rare 16-bit unreleased action title. Features top-down combat mechanics and futuristic environments, offering a glimpse into a cancelled 16-bit project.', NULL);
