INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super High Impact (Japan)', '1991', NaN, 'Acclaim', '2', NaN, 'Aggressive American Football simulation (Japanese release).', 'Crush the competition in this 16-bit arcade-style sim.', 'Play Super High Impact on the Super Famicom.', 'Features bone-crunching hits and over-the-top animations. A 16-bit port of the arcade hit that emphasizes hard-hitting action and high-scoring games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super High Impact (USA)', '1991', NaN, 'Acclaim', '2', NaN, 'Aggressive American Football simulation (USA release).', 'Lead your team to victory with high-impact plays.', 'Experience Super High Impact on the Super Nintendo.', 'Includes a deep playbook and a 16-bit tournament mode. Features digitized sound effects and a fast-paced gameplay style that preceded the Blitz series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super High Impact (USA) (Beta)', '1991', NaN, 'Acclaim', '2', NaN, 'Aggressive American Football (Pre-release build).', 'Test the early collision physics and field scaling.', 'Check out the Super High Impact Beta on the SNES.', 'A rare 16-bit development slice. Witness the initial implementation of the impact animations and the tuning of the AI''s aggressive play-calling behavior.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Hockey ''94 (Japan)', '1994', NaN, 'Taito', '2', NaN, 'Realistic ice hockey simulation (Japanese release).', 'Win the 16-bit hockey championship in Japan.', 'Play Super Hockey ''94 on the Super Famicom.', 'Features smooth skating animations and a technical approach to the sport. Focuses on precise passing and puck control for a more realistic 16-bit hockey experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Hockey (Europe)', '1991', NaN, 'Taito', '2', NaN, 'Arcade-style ice hockey simulation (European release).', 'Compete for the cup in this 16-bit international sim.', 'Experience Super Hockey on the Super Nintendo.', 'Features a variety of international teams and fast-paced gameplay. Master the slap-shot and defensive checking to dominate the 16-bit ice arena.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Hockey (France) (En,Fr)', '1991', NaN, 'Taito', '2', NaN, 'Ice hockey simulation (French localization).', 'Gagnez la coupe dans cette version française.', 'Jouez à Super Hockey en français sur le SNES.', 'The complete 16-bit hockey experience with full French text for menus and options. Compete against the world''s best teams in this agile sports title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Honmei - GI Seiha (Japan)', '1994', NaN, 'Human Entertainment', '2', NaN, 'Horse racing and management simulation.', 'Train and bet on the horses to conquer the GI races.', 'Explore Super Honmei on the Super Famicom.', 'A detailed 16-bit horse racing sim. Manage a stable of thoroughbreds, analyze track conditions, and place strategic bets to build a racing empire in Japan.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Ice Hockey (Europe)', '1992', NaN, 'Taito', '2', NaN, 'Professional-style ice hockey simulation.', 'Master the technical play in this 16-bit hockey sim.', 'Play Super Ice Hockey on the Super Nintendo.', 'Focuses on a more realistic representation of the sport. Includes strategic line changes, diverse rink sizes, and a heavy emphasis on 16-bit team tactics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Igo - Go Ou (Japan)', '1991', NaN, 'Nichibutsu', '2', NaN, 'Traditional board game (Igo/Go simulation).', 'Master the ancient game of Go in this technical 16-bit sim.', 'Experience Super Igo - Go Ou on the Super Famicom.', 'Features a sophisticated AI and various board sizes. A perfect 16-bit tool for both beginners and advanced players to practice the complex strategy of Go.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Indy Champ (Japan)', '1993', NaN, 'Genki', '1', NaN, 'Formula-style open-wheel racing simulation.', 'Win the 16-bit Indy championship across diverse tracks.', 'Play Super Indy Champ on the Super Famicom.', 'Features a fast Mode 7 engine and customizable car settings. Navigate through realistic racing circuits and manage your pit stops to secure the world title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Inindou - Datou Nobunaga (Japan)', '1992', NaN, 'Koei', '1', NaN, 'Top-down Mode 7 go-kart racing.', 'Outpace your opponents on the 16-bit circuit.', 'Play Super Go-Kart Racing on the SNES.', 'A fast-paced 16-bit racer utilizing Mode 7 effects for smooth track rotation. Choose from various quirky drivers and master the tight handling to claim the gold trophy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super International Cricket (Europe)', '1993', NaN, 'Tiertex', '2', NaN, 'Top-down racing (Mirror Mode Hack).', 'Master the tracks in reverse in this mirrored racing challenge.', 'Try Super Go-Kart Racing Mirror Mode on SNES.', 'A creative 16-bit modification that flips every track horizontally. Tests the muscle memory of veteran players by forcing them to navigate the familiar circuits in a mirrored perspective.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super International Cricket (Europe) (Beta)', '1993', NaN, 'Tiertex', '2', NaN, 'Side-scrolling soccer simulation.', 'Win the international cup in this 16-bit soccer sim.', 'Play the classic Super Goal! on the Super Nintendo.', 'Known as European Super Soccer. Features a horizontal field view, smooth 16-bit scrolling, and a variety of national teams with adjustable difficulty for competitive play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super James Pond (USA)', '1993', NaN, 'Millennium', '1', NaN, 'Vertical-perspective soccer simulation.', 'Lead your team to glory in this 16-bit soccer sequel.', 'Experience Super Goal! 2 on the Super Nintendo.', 'The USA release of Super Formation Soccer II. Features an immersive vertical camera angle, improved sprite scaling, and deep tactical options for substitutions and formations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super James Pond (USA) (Beta)', '1993', NaN, 'Millennium', '1', NaN, 'Strategic action and kaiju combat simulation.', 'Navigate the city and defeat enemy monsters as Godzilla.', 'Experience Super Godzilla on the Super Famicom.', 'A unique 16-bit hybrid. Guide Godzilla through a top-down map to manage destruction, leading into intense cinematic 1-on-1 battles against iconic foes like MechaGodzilla.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super James Pond II (Europe)', '1994', NaN, 'Millennium', '1', NaN, 'Strategic action and combat (Updated Revision).', 'Master the monster combat in this refined 16-bit version.', 'Play Super Godzilla (Rev A) on Super Famicom.', 'The optimized 16-bit Japanese release. Fixes minor graphical glitches during the cinematic combat sequences and balances the energy consumption for Godzilla''s special attacks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super James Pond II (Japan)', '1994', NaN, 'Millennium', '1', NaN, 'Strategic action and kaiju combat (USA release).', 'Protect the planet from alien monsters as Godzilla.', 'Play the legendary Super Godzilla on the SNES.', 'Features a unique dual-gameplay system. Manage the blue energy meter to unleash devastating breath attacks in high-stakes 16-bit battles against massive cinematic enemies.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Jangou (Japan)', '1992', NaN, 'Nichibutsu', '2', NaN, 'Traditional board game (Gomoku/Connect Five).', 'Connect five stones in a row to defeat the AI.', 'Play Super Gomoku Narabe - Renju on Super Famicom.', 'A polished 16-bit version of the classic abstract strategy game. Features various difficulty levels and traditional Japanese Renju rules for a meditative and mental challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Jinsei Game (Japan)', '1992', NaN, 'Takara', '4', NaN, 'Traditional board game and strategy study tool.', 'Master the art of Gomoku and Shougi in 16-bit.', 'Explore Super Gomoku Shougi on the Super Famicom.', 'A specialized 16-bit title that combines play with educational segments. Study famous board positions and historical matches to improve your tactical skills.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Jinsei Game (Japan) (Rev A)', '1992', NaN, 'Takara', '4', NaN, 'Puzzle-platformer with falling block mechanics.', 'Guide Gussun to the exit by placing blocks to clear a path.', 'Experience Super Gussun Oyoyo on the Super Famicom.', 'A brilliant 16-bit hybrid of Lemmings and Tetris. Use falling blocks to create stairs and bridges for the automatic-walking heroes while avoiding hazards and rising water.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Jinsei Game 2 (Japan)', '1994', NaN, 'Takara', '4', NaN, 'Puzzle-platformer (Sample/Demo Version).', 'Test the early block physics and character AI.', 'Check out the Super Gussun Oyoyo Sample on SNES.', 'A rare 16-bit development look. Features a selection of initial stages to showcase the unique falling block navigation mechanics and the vibrant character animations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Jinsei Game 3 (Japan)', '1996', NaN, 'Takara', '4', NaN, 'Advanced puzzle-platformer sequel.', 'Rescue your friends in this expanded 16-bit puzzle sequel.', 'Play Super Gussun Oyoyo 2 on the Super Famicom.', 'Significantly improves on the original with more complex level hazards, new block types, and a robust 2-player cooperative mode for dual puzzle-solving action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Junkoid', '2023', NaN, 'Homebrew', '1', NaN, 'Puzzle-platformer sequel (English Translation).', 'Enjoy the Gussun puzzle adventure with full English text.', 'Play Super Gussun Oyoyo 2 in English on SNES.', 'The RPGOne 16-bit fan translation. Fully translates the humorous story segments and level instructions, making this creative puzzle masterpiece accessible to Western players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Keiba (Japan)', '1992', NaN, 'Human Entertainment', '1', NaN, 'High-speed racing and vehicle combat (Japanese release).', 'Chase down criminals in the official Japanese version.', 'Play Super H.Q. - Criminal Chaser on Super Famicom.', 'The 16-bit sequel to the arcade hit Chase H.Q. Features improved scaling, nitro boosts, and intense ramming combat as you take down fugitives on the highway.', NULL);
