INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Mario World - Super Mario Bros. 3 Style Hack', '2020', NaN, 'Homebrew', '1', NaN, 'Hybrid side-scrolling platformer.', 'Enjoy the best of Mario 3 within the Mario World engine.', 'Play the SMB3 Style Hack on the Super Nintendo.', 'A 16-bit masterpiece that brings the world map, items, and visual style of Super Mario Bros. 3 into the fluid 16-bit engine of Super Mario World.', NULL);
