INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Mario World - Theoretical 1989 Playable Demo', '2019', NaN, 'Homebrew', '1', NaN, 'Historical reconstruction (1989 Demo).', 'Play through the hypothetical first build of Mario World.', 'Explore the Theoretical 1989 Demo on the SNES.', 'A 16-bit fan recreation of the earliest known build of SMW. Features prototype-style sprites and level layouts based on historical design documents and sketches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Mario World (U) (Prototype)', '1990', NaN, 'Nintendo', '2', NaN, 'Unreleased development build (Prototype).', 'Discover the unfinished secrets of the 16-bit legend.', 'Play the Super Mario World Prototype on the SNES.', 'An authentic 16-bit historical artifact. Features work-in-progress level designs, different enemy behaviors, and debug tools left in by the original Nintendo developers.', NULL);
