INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Mario World 4-Player', '2022', NaN, 'Homebrew', '4', NaN, 'Multiplayer arena and platforming (4-Player).', 'Play with three friends in the ultimate Mario chaos.', 'Try Super Mario World 4-Player on the SNES.', 'An incredible 16-bit technical feat. Uses specialized code to allow four players to interact simultaneously on a single console, redefining the 16-bit platforming experience.', NULL);
