INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Mario World Random Revolution X V1.0', '2020', NaN, 'Homebrew', '1', NaN, 'Procedural/Randomized platformer (v1.0).', 'Survive a completely randomized 16-bit world.', 'Try SMW: Random Revolution X on the SNES.', 'A high-replayability 16-bit mod. Every time you play, the items, enemies, and even level exits are shuffled, requiring total mastery of the 16-bit physics to survive.', NULL);
