INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Mario+Luigi World Co-op (V4.1)', '2021', NaN, 'Homebrew', '2', NaN, 'Simultaneous 2-player cooperative platformer.', 'Rescue Peach with Mario and Luigi at the same time.', 'Play Super Mario+Luigi World Co-op (V4.1) on SNES.', 'A technical 16-bit breakthrough. Allows two players to play simultaneously on screen. This version fixes desync issues and optimizes sprite handling for a smooth cooperative experience.', NULL);
