INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Momotarou Dentetsu III (Japan) (Rev B)', '1994', NaN, 'Hudson Soft', '4', NaN, 'Strategic board game (Final Revision).', 'Master the ultimate version of the third 16-bit entry.', 'Play Momotarou Dentetsu III (Rev B) on Super Famicom.', 'The definitive 16-bit patch. Includes final bug fixes for the save system and minor text corrections, ensuring the most stable competitive board game play.', NULL);
