INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Nazo Puyo Tsuu - Lulu no Tetsuwan Hanjouki (Japan)', '1996', NaN, 'Compile', '2', NaN, 'Enhanced mission-based puzzle sequel.', 'Master the technical Puyo puzzles in this 16-bit sequel.', 'Play Super Nazo Puyo Tsuu on the Super Famicom.', 'Based on the Puyo Puyo 2 engine. Features refined physics, offsetting mechanics for mission clears, and a significantly larger variety of logic challenges.', NULL);
