INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Off Road (USA)', '1991', NaN, 'Leland Interactive Media', '2', NaN, 'Arena-style off-road racing (USA release).', 'Crush the competition in this 16-bit arcade port.', 'Play Super Off Road for the Super Nintendo.', 'Compete against AI or friends in muddy tracks. A timeless 16-bit racer that focuses on tight turns, explosive speed, and car customization.', NULL);
