INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Professional Baseball (Japan)', '1991', NaN, 'Jaleco', '2', NaN, 'Arcade-style baseball simulation (Jaleco).', 'Hit home runs in this professional 16-bit baseball sim.', 'Play Super Professional Baseball on Super Famicom.', 'Features a clean, accessible interface and fast-paced gameplay. A solid 16-bit sports title that focuses on the core mechanics of batting, pitching, and fielding.', NULL);
