INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Punch-Out!! (Europe)', '1994', NaN, 'Nintendo R&D3', '2', NaN, 'Rhythmic arcade boxing simulation.', 'Defeat the world circuit champions and claim the belt.', 'Play the legendary Super Punch-Out!! on the SNES.', 'A 16-bit masterpiece. Features massive, detailed opponents and a deep system of ducks, dodges, and KO punches. Master the patterns to become the ultimate champion.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Punch-Out!! (Japan) (NP)', '1994', NaN, 'Nintendo R&D3', '2', NaN, 'Rhythmic arcade boxing (Nintendo Power).', 'Master the 16-bit ring in the official Japanese version.', 'Play Super Punch-Out!! on the Super Famicom.', 'Originally released in Japan via the Nintendo Power service. Features the same intense, high-speed boxing action and memorable cast of colorful international opponents.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Punch-Out!! (USA)', '1994', NaN, 'Nintendo R&D3', '2', NaN, 'Rhythmic arcade boxing (USA release).', 'Climb the ranks and defeat Nick Bruiser in 16-bit.', 'Experience Super Punch-Out!! for the SNES.', 'One of the most polished games on the system. Uses the SNES''s power to deliver large, expressive characters and incredibly tight, rewarding gameplay mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Putty (Europe)', '1993', NaN, 'System 3', '2', 2, 'Squishy side-scrolling platformer.', 'Navigate through bizarre worlds as the elastic Putty.', 'Play the unique Super Putty on the Super Nintendo.', 'Features a creative protagonist who can stretch, squash, and absorb enemies. A 16-bit platformer that emphasizes environmental puzzle-solving and fluid character movement.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Putty (USA)', '1993', NaN, 'System 3', '2', 2, 'Squishy side-scrolling platformer (USA release).', 'Rescue the captured Putties in this 16-bit adventure.', 'Experience Super Putty for the Super Nintendo.', 'Guide the blue protagonist through surreal levels. Use your unique shape-shifting abilities to bypass traps and navigate the imaginative 16-bit landscapes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Puyo Puyo (Japan)', '1993', NaN, 'Compile', '2', NaN, 'Falling-block puzzle game (Debut).', 'Chain together Puyos to defeat your opponents.', 'Play the original Super Puyo Puyo on the Super Famicom.', 'The 16-bit phenomenon that started the craze. Features a deep chaining system and a colorful cast of characters. Simple to learn, but incredibly difficult to master.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Puyo Puyo (Japan) (Rev A)', '1993', NaN, 'Compile', '2', NaN, 'Falling-block puzzle (Updated Revision A).', 'Master the chains in this refined 16-bit classic.', 'Play Super Puyo Puyo (Rev A) on the Super Famicom.', 'The updated 16-bit retail version. Fixes minor graphical glitches in the story mode and optimizes the AI''s response time during high-speed matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Puyo Puyo (Japan) (Rev B)', '1993', NaN, 'Compile', '2', NaN, 'Falling-block puzzle (Revision B).', 'Experience the most stable version of the Puyo debut.', 'Play Super Puyo Puyo (Rev B) on the Super Famicom.', 'The final 16-bit retail revision in Japan. Includes all previous bug fixes and ensures the most balanced competitive puzzle experience on the system.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Puyo Puyo 2 (USA, Europe) (Ja)', '1996', NaN, 'Compile', '2', NaN, 'Falling-block puzzle (International/Japanese mix).', 'Challenge the world in this 16-bit puzzle classic.', 'Experience Super Puyo Puyo 2 on the SNES.', 'The international release of the legendary sequel. Introduces the offsetting mechanic, allowing players to counter incoming garbage Puyos, revolutionizing competitive play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Puyo Puyo Tsuu (Japan)', '1994', NaN, 'Compile', '2', NaN, 'Advanced falling-block puzzle sequel.', 'Become the Puyo master in the definitive 16-bit sequel.', 'Play Super Puyo Puyo Tsuu on the Super Famicom.', 'Widely considered the best in the series. Features a branching story path, a massive roster of opponents, and the most refined 16-bit competitive puzzle mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Puyo Puyo Tsuu (Japan) [En by J2e v1.1] (~Super Puyo Puyo 2)', '1994', NaN, 'Compile', '2', NaN, 'Advanced falling-block puzzle (English).', 'Enjoy the ultimate 16-bit Puyo sequel in English.', 'Play Super Puyo Puyo Tsuu in English on the SNES.', 'The J2e 16-bit fan translation. Fully translates the humorous character interactions and menus, making this competitive masterpiece accessible to Western fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Puyo Puyo Tsuu Remix (Japan)', '1995', NaN, 'Compile', '2', NaN, 'Enhanced falling-block puzzle (Remix version).', 'Master the new modes in this 16-bit Puyo expansion.', 'Experience Super Puyo Puyo Tsuu Remix on SNES.', 'An updated version of the sequel. Features a new Expert mode and more 4-player options, offering the most comprehensive 16-bit Puyo Puyo package available.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super R-Type (Europe)', '1991', NaN, 'Irem', '2', NaN, 'Horizontal-scrolling shoot ''em up (Shmup).', 'Defeat the Bydo Empire in this challenging 16-bit shooter.', 'Play the legendary Super R-Type on the SNES.', 'A launch-window classic. Features massive bosses, the iconic Force orb mechanic, and several new levels exclusive to this version of the legendary arcade franchise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super R-Type (Japan)', '1991', NaN, 'Irem', '2', NaN, 'Horizontal-scrolling shoot ''em up (Japanese release).', 'Master the R-9 fighter in the original 16-bit version.', 'Experience Super R-Type on the Super Famicom.', 'Known for its intense difficulty and atmospheric soundtrack. Utilize the beam charging system to clear screens of biomechanical alien threats in this 16-bit masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super R-Type (USA)', '1991', NaN, 'Irem', '2', NaN, 'Horizontal-scrolling shoot ''em up (USA release).', 'Blast through the alien armada in this 16-bit shmup.', 'Play Super R-Type for the Super Nintendo.', 'Features impressive sprite scaling and diverse weaponry. Navigate through hazardous industrial landscapes and organic alien nests to save humanity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super R.B.I. Baseball (USA)', '1989', NaN, 'Tengen', '2', NaN, 'Arcade-style baseball simulation.', 'Hit home runs and win the 16-bit world series.', 'Play Super R.B.I. Baseball on the Super Nintendo.', 'The 16-bit evolution of the classic franchise. Features real MLB players and statistics from the early 90s, with fast-paced gameplay and easy-to-learn controls.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Real Mahjong PIV (Japan)', '1994', NaN, 'Seta', '1', NaN, 'Mahjong simulation with anime-style characters.', 'Win the mahjong tournament to unlock character scenes.', 'Experience Super Real Mahjong PIV on Super Famicom.', 'A polished 16-bit port of the popular arcade series. Features high-quality character art and a competitive AI that challenges even experienced mahjong players.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Real Mahjong PV Paradise - All-Star 4 Nin Uchi (Japan)', '1995', NaN, 'Seta', '1', NaN, 'All-star mahjong simulation with a large roster.', 'Master the tiles against a variety of anime opponents.', 'Play Super Real Mahjong PV Paradise on SNES.', 'The ultimate 16-bit entry in the series. Features a four-player mode and an extensive collection of characters with unique personalities and playstyles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Reimu World Return To Hack', '2019', NaN, 'Fan Developer', '1', 2, 'Fan-made total conversion of Mario World (Touhou).', 'Navigate the Mushroom Kingdom as the shrine maiden Reimu.', 'Explore Super Reimu World Return To Hack on SNES.', 'A creative 16-bit crossover. Replaces Mario with Reimu Hakurei, featuring custom projectiles, unique flight mechanics, and entirely redesigned levels inspired by Touhou Project.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Robot Taisen EX (Japan)', '1994', NaN, 'Banpresto', '1', NaN, 'Turn-based tactical RPG with giant robots.', 'Command a crossover team of mechas to save the Earth.', 'Play Super Robot Taisen EX on the Super Famicom.', 'A deep 16-bit tactical experience. Features iconic robots from various anime series, with branching storylines and impressive combat animations for each unit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Robot Taisen Gaiden - Masou Kishin - The Lord of Elemental (Japan)', '1996', NaN, 'Banpresto', '1', NaN, 'Tactical RPG spin-off (Original Story).', 'Master the elemental mechas in this 16-bit epic.', 'Experience Super Robot Taisen Gaiden on SNES.', 'The first entry to feature the original Lord of Elemental storyline. Boasts some of the best 16-bit sprite work on the system and a sophisticated verticality mechanic in combat.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Royal Blood (Japan)', '1995', NaN, 'Koei', '1', NaN, 'Strategy and fantasy conquest simulation (Koei).', 'Unify the kingdom of Ishmeria through war and magic.', 'Play Super Royal Blood on the Super Famicom.', 'Known as Gemfire in the West. A unique 16-bit hybrid of grand strategy and fantasy, featuring magical advisors and monster units to turn the tide of battle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Rugby (Japan)', '1994', NaN, 'Tonkin House', '2', NaN, 'Realistic rugby simulation (Japanese release).', 'Lead your national team to the 16-bit rugby cup.', 'Experience Super Rugby on the Super Famicom.', 'A rare 16-bit sports title focusing on the intensity of rugby. Features complex tactical formations, realistic set-pieces, and smooth player animations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Sanae World', '2018', NaN, 'Fan Developer', '1', 2, 'Fan-made platformer starring Sanae Kochiya.', 'Explore a new 16-bit world as the miracle worker Sanae.', 'Play the unique Super Sanae World on the SNES.', 'A creative 16-bit ROM hack. Replaces the protagonist with the Touhou character Sanae, featuring custom palettes and redesigned levels that focus on precision platforming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Sangokushi (Japan)', '1992', NaN, 'Koei', '1', NaN, 'Grand strategy set in the Three Kingdoms era.', 'Unify ancient China through diplomacy and warfare.', 'Play Super Sangokushi on the Super Famicom.', 'Koei''s legendary Romance of the Three Kingdoms in 16-bit. Manage hundreds of officers, local economies, and massive armies in a deep historical simulation.', NULL);
