INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Sangokushi II (Japan) (Rev A)', '1994', NaN, 'Koei', '1', NaN, 'Grand strategy sequel (Updated Revision).', 'Experience the most stable version of Sangokushi II.', 'Play Super Sangokushi II (Rev A) on the SNES.', 'The refined 16-bit Japanese release. Fixes minor bugs in the officer management menus and optimizes the AI''s tactical decision-making during sieges.', NULL);
