INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Scope 6 (USA)', '1992', NaN, 'Nintendo R&D1', '1', NaN, 'Light-gun shooter collection (USA release).', 'Blast targets with the iconic 16-bit bazooka.', 'Play Super Scope 6 for the Super Nintendo.', 'Showcases the accuracy of the Super Scope hardware. Includes games ranging from puzzle-based shooting to high-speed interceptor missions against alien ships.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Shadow of the Beast (USA) (Proto)', '1991', NaN, 'Psygnosis', '1', 2, 'Side-scrolling action-adventure (Unreleased Proto).', 'Navigate the dark fantasy world of the Beast.', 'Try the Super Shadow of the Beast Proto on SNES.', 'A rare 16-bit look at a cancelled project. Based on the Amiga classic, featuring atmospheric backgrounds, bizarre creatures, and a notably high difficulty level.', NULL);
