INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Shougi (Japan)', '1992', NaN, 'Nintendo', '2', NaN, 'Traditional Japanese board game (Shougi).', 'Defeat the AI in the ancient game of Japanese chess.', 'Experience Super Shougi on the Super Famicom.', 'A polished 16-bit simulation. Features multiple AI levels and helpful move-prediction tools to help players learn and master the complex strategies of Shougi.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Shougi 2 (Japan)', '1994', NaN, 'Nintendo', '2', NaN, 'Enhanced Shougi simulation sequel.', 'Master the board in this refined 16-bit Shougi sequel.', 'Play Super Shougi 2 on the Super Famicom.', 'Includes improved graphical interfaces and more diverse AI personalities. Offers a more cinematic presentation of the traditional 16-bit tactical matches.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Shougi 3 - Kitaihei (Japan)', '1995', NaN, 'Nintendo', '2', NaN, 'Advanced Shougi simulation with story mode.', 'Win the Shougi championship in this 16-bit finale.', 'Experience Super Shougi 3 on the Super Famicom.', 'Features the most advanced AI in the series. Includes a narrative mode that follows the life of a professional player rising through the ranks of the 16-bit world.', NULL);
