INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Simple Kart 3', '2019', NaN, 'Fan Developer', '4', NaN, 'Final minimalist racing modification entry.', 'Complete the 16-bit Simple racing legacy.', 'Experience Super Simple Kart 3 on the SNES.', 'The final entry in the minimalist hack trilogy. Features the most polished track layouts and a balanced difficulty curve for veteran 16-bit racers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Slam Dunk (USA)', '1994', NaN, 'Virgin Interactive', '2', NaN, 'Arcade-style basketball simulation.', 'Win the championship with high-flying 16-bit dunks.', 'Play Super Slam Dunk on the Super Nintendo.', 'Features an emphasis on spectacular moves and fast-paced action. Includes 16-bit rosters of pro-style teams and an energetic soundtrack to match the court intensity.', NULL);
