INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Slapshot (USA)', '1993', NaN, 'Taito', '2', NaN, 'Arcade-style ice hockey (USA release).', 'Crush the competition on the 16-bit ice rink.', 'Experience Super Slapshot for the Super Nintendo.', 'Master the slap-shot mechanics and defensive positioning. A fun 16-bit sports game that prioritizes action and goal-scoring over strict simulation.', NULL);
