INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Soccer (USA)', '1991', NaN, 'Human Entertainment', '2', NaN, 'Forward-perspective soccer simulation (USA).', 'Lead your national team to 16-bit glory.', 'Experience Super Soccer on the Super Nintendo.', 'The North American release of the Mode 7 classic. Includes diverse national teams and an accessible but deep 16-bit arcade-style football experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Soccer Champ (USA)', '1995', NaN, 'Human Entertainment', '2', NaN, 'Side-scrolling soccer action and strategy.', 'Score the winning goal in this 16-bit soccer sim.', 'Play Super Soccer Champ on the Super Nintendo.', 'Known for its large player sprites and cinematic close-up shots during shots on goal. A fast-paced 16-bit sports title with a heavy emphasis on arcade fun.', NULL);
