INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Turrican (USA)', '1993', NaN, 'Factor 5', '1', 2, 'Action-platformer (USA release).', 'Blast through the mechanized legions in 16-bit.', 'Play Super Turrican for the Super Nintendo.', 'Explore large, non-linear levels and collect powerful weapon upgrades. This 16-bit classic pushes the SNES audio chip to its limits with an iconic soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Turrican 2 (Europe)', '1995', NaN, 'Factor 5', '1', 2, 'High-octane run and gun sequel (Europe).', 'Engage in cinematic 16-bit combat in this epic sequel.', 'Experience Super Turrican 2 on the Super Nintendo.', 'Pushes the SNES to the absolute limit. Features Mode 7 vehicle segments, a grappling hook mechanic, and some of the most impressive 16-bit explosions ever seen.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Turrican 2 (USA)', '1995', NaN, 'Factor 5', '1', 2, 'High-octane run and gun sequel (USA).', 'Defeat the Machine once and for all in 16-bit.', 'Play Super Turrican 2 for the Super Nintendo.', 'A cinematic 16-bit tour de force. Features fast-paced action, incredible sprite work, and specialized levels that feel like a big-budget action movie.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Turrican 2 (USA) (Beta1)', '1995', NaN, 'Factor 5', '1', 2, 'Run and gun sequel (Early Beta 1).', 'Test the initial implementation of the grappling hook.', 'Check out Super Turrican 2 (Beta 1) on the SNES.', 'A rare early 16-bit development build. Features unfinished levels and prototype boss designs, offering a glimpse into the creation of this 16-bit technical marvel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Turrican 2 (USA) (Beta2)', '1995', NaN, 'Factor 5', '1', 2, 'Run and gun sequel (Advanced Beta 2).', 'Explore the refined 16-bit mechanics of the Turrican sequel.', 'Check out Super Turrican 2 (Beta 2) on the SNES.', 'A late-stage 16-bit development build. Includes more polished sound effects and near-final level layouts, showcasing the technical optimization of the Turrican engine.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Ultra Baseball (Japan)', '1994', NaN, 'Culture Brain', '2', NaN, 'Arcade-style baseball with super powers.', 'Hit impossible home runs in this 16-bit sports sim.', 'Experience Super Ultra Baseball on the Super Famicom.', 'Known as Super Baseball Simulator 1.000 in the West. Features traditional baseball gameplay with a twist: specialized Super moves for pitchers and batters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Ultra Baseball 2 (Japan)', '1995', NaN, 'Culture Brain', '2', NaN, 'Enhanced super-powered baseball sequel.', 'Win the series in this expanded 16-bit sports sequel.', 'Play Super Ultra Baseball 2 on the Super Famicom.', 'Features more specialized powers and refined 16-bit graphics. A cult classic sports title that rewards both traditional skill and the strategic use of energy-draining super abilities.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Ultra Baseball 2 (Japan) [En by VX v1.0]', '1995', NaN, 'Culture Brain', '2', NaN, 'Super-powered baseball (English Translation).', 'Enjoy the crazy 16-bit baseball sequel in English.', 'Play Super Ultra Baseball 2 in English on the SNES.', 'The VX 16-bit fan translation. Makes the complex super-move menus and stat screens fully accessible, allowing Western fans to enjoy this unique and chaotic sports sim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Uno (Japan)', '1993', NaN, 'Takara', '2', NaN, 'Digital version of the classic card game.', 'Empty your hand first to win the 16-bit match.', 'Play Super Uno on the Super Famicom.', 'The official 16-bit digital version of the world-famous card game. Features vibrant colors, various AI difficulty levels, and the classic Uno! shout in a charming digital format.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Uno (Japan) (Rev A)', '1993', NaN, 'Takara', '2', NaN, 'Card game simulation (Updated Revision).', 'Master the 16-bit card table in this refined version.', 'Play Super Uno (Rev A) on the Super Famicom.', 'The updated 16-bit retail release. Fixes minor AI logic bugs and optimizes the animation speed for a faster, more fluid card-playing experience.', NULL);
