INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Super Wagan Land (Japan)', '1991', NaN, 'Hudson Soft', '1', 2, 'Platformer with sound-wave combat.', 'Defeat enemies using your voice in this 16-bit classic.', 'Play Super Wagan Land on the Super Famicom.', 'A unique 16-bit platformer where you stun enemies with shout bubbles and engage in mini-game battles like Shiritori (word games) to defeat bosses.', NULL);
