INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Tactics Ogre - Let Us Cling Together (English Patched)', '1995', NaN, 'Riverhillsoft', '1', NaN, 'Isometric tactical RPG (English Patched).', 'Lead your army through a branching political epic.', 'Play Tactics Ogre: Let Us Cling Together in English.', 'The 16-bit masterpiece that defined the genre. Features deep character customization, a mature story with moral choices, and a legendary fan translation for Western players.', NULL);
