INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Teenage Mutant Ninja Turtles - Turtles in Time (Japan)', '1992', NaN, 'Konami', '2', 2, 'Side-scrolling beat ''em up (Japan).', 'Defeat the Foot Clan across 16-bit history.', 'Play TMNT: Turtles in Time on the Super Famicom.', 'The authentic Japanese release of the 16-bit classic. Delivers high-speed action, cooperative gameplay, and memorable boss fights against iconic villains.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Teenage Mutant Ninja Turtles IV - Turtles in Time (Australia)', '1992', NaN, 'Konami', '2', 2, 'Side-scrolling beat ''em up (Australia).', 'Stop Shredder''s time-traveling plot in 16-bit.', 'Experience TMNT IV: Turtles in Time on the SNES.', 'Often cited as the best beat ''em up on the system. Features a vibrant 16-bit palette, responsive controls, and a fantastic soundtrack.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Teenage Mutant Ninja Turtles IV - Turtles in Time (USA)', '1992', NaN, 'Konami', '2', 2, 'Side-scrolling beat ''em up (USA release).', 'Journey from the prehistoric age to 2020 in 16-bit.', 'Play the legendary TMNT IV: Turtles in Time on SNES.', 'A pixel-perfect home translation of the arcade hit. Includes new levels and bosses exclusive to the 16-bit version, making it the definitive way to play.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Teenage Mutant Ninja Turtles IV - Turtles in Time (USA) (Beta)', '1992', NaN, 'Konami', '2', 2, 'Side-scrolling beat ''em up (USA Beta).', 'Explore the early development of the 16-bit Turtle saga.', 'Check out the Turtles in Time Beta on the SNES.', 'A fascinating look at the 16-bit porting process. Features different enemy placements and prototype versions of the iconic 16-bit music tracks.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Teitoku no Ketsudan (Japan)', '1994', NaN, 'Koei', '1', NaN, 'Grand strategy and naval combat (P.T.O.).', 'Command the Pacific fleet in this deep 16-bit sim.', 'Play Teitoku no Ketsudan on the Super Famicom.', 'Koei''s Pacific Theater of Operations. Manage resources, ship production, and tactical naval battles in an accurate 16-bit historical simulation.', NULL);
