INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Teitoku no Ketsudan II (Japan) (Rev A)', '1995', NaN, 'Koei', '1', NaN, 'Advanced strategy sequel (Revision A).', 'Conquer the seas in the most stable 16-bit version.', 'Play Teitoku no Ketsudan II (Rev A) on SNES.', 'The definitive 16-bit Japanese release. Includes final bug fixes for the troop transport logic and optimizes the save data for massive world maps.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Tekichuu Keiba Juku (Japan)', '1994', NaN, 'Asmik', '1', NaN, 'Horse racing and betting simulation.', 'Study the odds and win big on the 16-bit track.', 'Explore Tekichuu Keiba Juku on the Super Famicom.', 'A detailed 16-bit horse racing cram school. Learn how to analyze horse stats, track conditions, and betting patterns to become a 16-bit racing expert.', NULL);
