INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Tetris Battle Gaiden (Japan)', '1993', NaN, 'Bullet-Proof Software', '2', NaN, 'Competitive puzzle with magic powers.', 'Master the character-specific spells in 16-bit.', 'Experience Tetris Battle Gaiden on Super Famicom.', 'A fan-favorite in the 16-bit competitive scene. Collect orbs to trigger powers like shield, shrink, or block-swaps in this high-energy puzzle fighter.', NULL);
