INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'The 12th Annual Vanilla Level Design Contest: Collaboration Hack', '2019', NaN, 'Fan Developer', '1', 2, 'Collaborative SMW level collection (VLDC 12).', 'Play the best vanilla levels from the 16-bit community.', 'Try the VLDC 12 Collaboration Hack on SNES.', 'A massive 16-bit compilation featuring dozens of creative levels that use only original Mario World assets. A testament to 16-bit level design ingenuity.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'The 9th Annual Vanilla Level Design Contest: Collaboration Hack by SMW Central', '2016', NaN, 'Fan Developer', '1', 2, 'Collaborative SMW level collection (VLDC 9).', 'Explore a massive world of 16-bit community creativity.', 'Play the VLDC 9 Collaboration Hack on SNES.', 'A landmark 16-bit ROM hack. Features an enormous overworld connecting levels from the SMW Central design contest, showcasing the best 16-bit platforming.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'The Legend of Zelda - A Link to the Past - Title Skip and Full Hearts', '2014', NaN, 'Fan Developer', '1', NaN, 'Quality of Life modification (Zelda).', 'Start your Zelda adventure with speed and power.', 'Try the Zelda: ALttP Title Skip mod on SNES.', 'A specialized 16-bit tweak. Bypasses the intro cutscenes and grants the player full heart containers from the start for a faster 16-bit gameplay loop.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'The Legend of Zelda Parallel Worlds Remodel', '2016', NaN, 'Fan Developer', '1', NaN, 'Massive world overhaul (Zelda Remodel).', 'Experience a tougher, redesigned 16-bit Hyrule.', 'Play Zelda: Parallel Worlds Remodel on SNES.', 'A fan-favorite 16-bit total conversion. Redesigns the entire world map and all dungeons, offering a much more difficult and fresh 16-bit Zelda challenge.', NULL);
