INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'The Lost Levels Enhanced by Pac', '2018', NaN, 'Fan Developer', '1', 2, 'Enhanced platformer (The Lost Levels).', 'Conquer the hardest 16-bit Mario levels with a twist.', 'Play The Lost Levels Enhanced on the SNES.', 'A 16-bit modification that ports the Famicom classic into the SMW engine. Features updated physics, custom sprites, and several 16-bit quality-of-life fixes.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'The Mysterious Mine (The True Final Version)', '2019', NaN, 'Fan Developer', '1', 2, 'Fan-made total conversion platformer.', 'Reach the True Final Version of this 16-bit quest.', 'Explore The Mysterious Mine on the SNES.', 'A high-quality 16-bit ROM hack of SMW. Features a dark, cave-themed aesthetic, custom power-ups, and intricate puzzle-platforming that challenges 16-bit veterans.', NULL);
