INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Ultraman (Japan)', '1991', NaN, 'Bec', '1', 2, 'One-on-one fighting game (Japan).', 'Defeat the classic kaiju in the 16-bit original.', 'Experience the original Ultraman on Super Famicom.', 'The launch-window 16-bit fighter. Features a unique health system where you must Finish the monster once their bar is depleted to win the round.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Umi no Nushi Tsuri (Japan)', '1994', NaN, 'Pack-In-Video', '1', NaN, 'Open-sea fishing simulation.', 'Catch the kings of the ocean in 16-bit.', 'Play Umi no Nushi Tsuri on the Super Famicom.', 'The ocean-based entry in the Legend of the River King series. Features RPG elements, beautiful 16-bit scenery, and a variety of sea life to master.', NULL);
