INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Umi Tsuri Meijin - Suzuki Hen (Japan)', '1994', NaN, 'Pack-In-Video', '1', NaN, 'Sea fishing simulation (Suzuki Hen).', 'Become a 16-bit sea bass fishing master.', 'Experience Umi Tsuri Meijin on the Super Famicom.', 'A technical 16-bit sim focused on sea bass. Includes realistic equipment options and tidal physics to challenge experienced 16-bit anglers.', NULL);
