INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Umihara Kawase (Japan) [En by Satsu v0.90]', '1994', NaN, 'Miyako Bussan', '1', NaN, 'Physics-based platformer (English Patched).', 'Enjoy Umihara Kawase''s unique world in English.', 'Play Umihara Kawase in English on the SNES.', 'The fan-translated 16-bit version. Makes the menus and end-of-level statistics fully readable, allowing fans to focus on mastering the complex 16-bit swinging mechanics.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Uncharted Waters - New Horizons (USA)', '1994', NaN, 'Koei', '1', NaN, 'Naval exploration and trading RPG.', 'Sail the seven seas and build a 16-bit empire.', 'Play Uncharted Waters: New Horizons on SNES.', 'A massive Koei masterpiece. Choose from six different characters and engage in trading, piracy, and exploration in a sprawling 16-bit world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Uncharted Waters (USA)', '1994', NaN, 'Koei', '1', NaN, 'Naval strategy and trading (Original).', 'Discover the 16-bit world in the first entry.', 'Experience Uncharted Waters on the Super Nintendo.', 'Set the foundation for the series. Manage your fleet, navigate real-world geography, and profit from the age of discovery in 16-bit detail.', NULL);
