INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Universal Soldier (USA) (Proto)', '1992', NaN, 'Probe Entertainment', '1', 2, 'Side-scrolling action (Unreleased Proto).', 'Master the 16-bit cyborg combat in this prototype.', 'Try the Universal Soldier Prototype on the SNES.', 'A rare 16-bit look at a cancelled project. Based on the Turrican engine, featuring high-quality run-and-gun action and detailed cinematic 16-bit sprites.', NULL);
