INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('SNES', 'Urban Strike (USA)', '1994', NaN, 'Electronic Arts', '1', NaN, 'Isometric helicopter combat (USA release).', 'Protect the 16-bit USA from a high-tech threat.', 'Experience Urban Strike for the Super Nintendo.', 'A technical tour de force. Features impressive 16-bit explosions, complex mission objectives, and the most refined vehicle physics of the 16-bit series.', NULL);
