INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYCOLOR', 'Donkey Kong GB - Dinky Kong & Dixie Kong (Japan)', '2000', NaN, 'Rare', '1', NaN, 'Side-scrolling platformer featuring Dinky and Dixie Kong.', 'Find Donkey and Diddy Kong who have gone missing in the Northern Kremisphere.', 'Classic DK platforming sequel.', 'Known as Donkey Kong Land III, this GBC version features refined mechanics. Guide Dixie and Dinky through dangerous stages to solve the mystery of the Lost World.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYCOLOR', 'Doraemon - Aruke Aruke Labyrinth (Japan)', '2000', NaN, 'Epoch', '1', NaN, 'Grid-based puzzle game where players guide Doraemon through mazes.', 'Navigate the labyrinth and collect items to reach the exit.', 'Doraemon-themed puzzle maze.', 'Use Doraemon''s secret gadgets to solve complex mazes in Aruke Aruke Labyrinth. A fun and challenging GBC title for fans of the iconic blue robot cat.', NULL);
