INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', '007 - Everything or Nothing (J)(Rising Sun)', '2004', NaN, 'EA Games', '1', NaN, 'Third-person tactical shooting and gadget-based stealth action.', 'Complete espionage missions to stop a global nanotech threat.', 'Experience the ultimate Bond adventure with high-tech gadgets and intense action.', 'James Bond 007 Everything or Nothing for GBA brings cinematic spy action to your handheld. Master stealth mechanics, use iconic gadgets, and engage in high-stakes combat to thwart a global conspiracy in this top-tier action title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', '2 in 1 - Asterix and Obelix (E)(Rising Sun)', '2004', NaN, 'Atari', '1', NaN, 'Classic side-scrolling platformer with two playable characters.', 'Navigate through Roman-occupied lands to reach the end of each level.', 'Join Asterix and Obelix in this fun-filled, Roman-bashing platforming adventure.', 'Relive the classic comic book adventures in Asterix and Obelix 2-in-1. Featuring vibrant 2D graphics and challenging platforming levels, players must use the unique strengths of both Gauls to defeat Caesar’s armies and explore ancient Europe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', '2 in 1 - Barbie Groovy Games & Secret Agent Barbie (E)(Supplex)', '2004', NaN, 'WayForward Technologies', '1', NaN, 'Collection of mini-games and isometric stealth-platforming levels.', 'Win various casual games and complete secret missions as a top agent.', 'A versatile combo featuring fashion-forward puzzles and exciting spy missions.', 'The Barbie Groovy Games & Secret Agent Barbie bundle offers diverse gameplay for fans. From casual puzzles and board games to stealthy platforming missions, this collection provides hours of entertainment with Barbie in her most iconic roles.', NULL);
