INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', '2 in 1 - Brother Bear & Disney Princess (E)(Independent)', '2005', NaN, 'Disney Interactive', '1', NaN, 'Side-scrolling platformer and puzzle-adventure gameplay.', 'Guide the bears through the wild and complete various princess tales.', 'Embark on a double journey through the Great North and enchanted kingdoms.', 'Disney''s Brother Bear & Disney Princess 2-in-1 brings two hits to one cartridge. Navigate treacherous terrain as Kenai and Koda, then switch to magical princess stories filled with puzzles and exploration.', NULL);
