INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', '2 in 1 - Cartoon Network - Block Party & Cartoon Network - Speedway (U)(Trashman)', '2004', NaN, 'Cartoon Network', '4', NaN, 'Isometric mini-games and top-down arcade racing.', 'Win party challenges and finish first in high-speed cartoon races.', 'Double the fun with Cartoon Network’s best mini-games and racing circuits.', 'Experience Cartoon Network Block Party & Speedway in one pack. Compete in board-game style challenges with your favorite characters, then jump into the driver''s seat for fast-paced racing action across iconic CN locations.', NULL);
