INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', '2 in 1 - Castlevania Double Pack (E)(Rising Sun)', '2006', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania) with exploration.', 'Explore Dracula''s castle and defeat the Lord of Darkness.', 'Two legendary Castlevania masterpieces: Aria of Sorrow and Harmony of Dissonance.', 'The Castlevania Double Pack is a must-have for GBA owners. Featuring two of the best Metroidvania titles ever made, players will explore vast gothic maps, collect souls, and battle iconic monsters in these deep, atmospheric action-RPGs.', NULL);
