INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Animaniacs - Hollywood Hypnotics (Prototype)', '2000', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Stop the hypnotics and save the Hollywood movie studios.', 'Help Yakko, Wakko, and Dot in this unreleased cartoon adventure.', 'Animaniacs - Hollywood Hypnotics is a fascinating prototype that captures the spirit of the show. Navigate the Warner Bros. lot, use character-specific abilities, and stop the hypnotic plan in this rare piece of GBA history.', NULL);
