INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Archer Maclean''s 3D Pool (U)(Rising Sun)', '2002', NaN, 'Archer Maclean', '2', NaN, 'First-person perspective billiards simulation.', 'Clear the table and win professional pool tournaments.', 'A realistic 3D pool experience with impressive physics.', 'Archer Maclean''s 3D Pool for GBA delivers an incredibly immersive billiards simulation. Featuring a unique 3D engine, players can master bank shots, spin, and precision angles in various game modes, from quick practice to intense championship tournaments.', NULL);
