INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Aria of Sorrow Magician Mode', '2003', NaN, 'Independent', '1', NaN, 'Side-scrolling action-RPG (Metroidvania) with magic focus.', 'Defeat the chaos within the castle using advanced magic.', 'A special unlockable mode for the legendary Aria of Sorrow.', 'Aria of Sorrow Magician Mode changes the classic gameplay by giving the player access to all magic spells from the start. Explore Dracula''s castle with a focus on MP management and elemental attacks in this challenging and strategic variant.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Army Men - Operation Green (U)(Menace)', '2001', NaN, '3DO Company', '1', NaN, 'Isometric tactical shooting and combat action.', 'Lead the Green Army to victory against the Tan menace.', 'High-stakes plastic soldier warfare in a variety of environments.', 'Army Men: Operation Green brings the classic toy soldier battles to your handheld. Control your units through five massive environments, use diverse weaponry, and complete tactical objectives to ensure the Green Army''s global dominance.', NULL);
