INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Back to Stone (U)(Rising Sun)', '2001', NaN, 'Spiral House', '1', NaN, 'Isometric action-adventure with combat and puzzles.', 'Reclaim your kingdom from dark forces after being turned to stone.', 'A dark fantasy epic featuring unique isometric combat and exploration.', 'Back to Stone (US Version) delivers a challenging blend of action and strategy. Master the stone-transformation mechanic to navigate complex dungeons and defeat powerful bosses in this atmospheric fantasy adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Backtrack (U)(Mode7)', '2001', NaN, 'Vicarious Visions', '1', NaN, 'First-person shooter (FPS) with corridor exploration.', 'Eliminate the alien threat and find the exit of each lunar base.', 'A retro-style FPS that pushes the GBA hardware with 3D environments.', 'Backtrack brings classic corridor-shooting action to the GBA. Navigate through 12 intense levels on a moon base, utilizing a variety of futuristic weapons to stop an alien invasion in this fast-paced, portable first-person experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Backyard Baseball (U)(Venom)', '2001', NaN, 'Humongous Entertainment', '1', NaN, 'Arcade-style sports simulation with power-ups.', 'Win the Backyard World Series with a team of neighborhood kids.', 'Play baseball with the Backyard Gang and kid versions of MLB pros.', 'Backyard Baseball for GBA captures the fun of sandlot ball. Draft your favorite characters, including Secret Weapon Pablo Sanchez, and use wacky power-ups to hit home runs and dominate the neighborhood leagues.', NULL);
