INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Backyard Hockey (U)(Rising Sun)', '2002', NaN, 'Humongous Entertainment', '1', NaN, 'Arcade-style ice hockey simulation.', 'Outscore your opponents on the ice to win the cup.', 'Fast-paced hockey action with neighborhood kids and NHL stars.', 'Backyard Hockey brings the intensity of the rink to GBA. Features 3-on-3 action, power-ups, and a deep season mode where you can customize your team to become the kings of the neighborhood ice.', NULL);
