INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Black Belt Challenge (E)(Venom)', '2002', NaN, 'Unique Development Studios', '2', NaN, '2D fighting game with various characters.', 'Defeat all challengers to win the Black Belt tournament.', 'A classic handheld brawler with a variety of martial arts styles.', 'Black Belt Challenge for GBA features traditional 1-on-1 fighting action. Choose from a diverse roster of fighters, master their special moves, and climb the ranks of the professional circuit in this portable fighter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Black Black (J)(Nobody)', '2002', NaN, 'Unknown', '1', NaN, 'Dark fantasy RPG and adventure.', 'Navigate a dark world and survive against powerful foes.', 'A mysterious and atmospheric Japanese RPG for GBA.', 'Black Black offers a deep role-playing experience with a focus on atmosphere and story. Explore a beautifully detailed 2D world, manage your party, and engage in tactical combat in this Japanese import.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Black Matrix Zero (J)(Cezar)', '2002', NaN, 'Flight-Plan', '1', NaN, 'Tactical turn-based RPG with grid combat.', 'Lead your rebellion and master the power of the wings.', 'A high-quality tactical RPG with a deep branching storyline.', 'Black Matrix Zero for GBA is a prequel to the cult classic series. Featuring deep character customization and complex grid-based battles, it offers a mature story and a unique dark fantasy setting for strategy fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Blackthorne (E)(Endless Piracy)', '1994', NaN, 'Blizzard Entertainment', '1', NaN, 'Cinematic platformer with combat and puzzles.', 'Reclaim your throne and defeat the Sarlac''s minions.', 'A dark and gritty sci-fi adventure from the creators of Diablo.', 'Blackthorne brings the 16-bit classic to GBA. As Kyle Vlaros, use your shotgun and tactical positioning to clear levels, solve environmental puzzles, and survive the brutal alien world of Tuul in this cinematic action title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Blackthorne (U)(Mode7)', '1994', NaN, 'Blizzard Entertainment', '1', NaN, 'Cinematic platformer with combat and puzzles.', 'Reclaim your throne and defeat the Sarlac''s minions.', 'A dark and gritty sci-fi adventure from the creators of Diablo.', 'The US version of Blackthorne features the same intense, strategic gunplay. Master the cover mechanics and explore the sprawling alien landscapes to avenge your father and reclaim your destiny in this Blizzard classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Blades of Thunder (U)(TrashMan)', '2004', NaN, 'Kemco', '1', NaN, 'Combat flight simulation and aerial dogfighting.', 'Complete high-stakes missions and eliminate enemy aircraft.', 'High-octane helicopter and jet combat for military fans.', 'Blades of Thunder for GBA delivers intense aerial warfare. Pilot a variety of attack helicopters and fighter jets across diverse mission types, featuring impressive sprite-scaling graphics and fast-paced arcade action that pushes your reflexes to the limit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bleach Advance (J)(Caravan)', '2003', NaN, 'DreamFactory', '1', NaN, '2D fighting game with special spirit attacks.', 'Fight through the Gotei 13 and master your Bankai.', 'The first GBA fighting game based on the hit Bleach anime.', 'Bleach Advance brings the early arcs of the series to life. Choose from fan-favorite characters like Ichigo and Rukia, mastering their unique spiritual powers and flash-steps in fast-paced 1-on-1 battles that capture the show''s high-energy spirit.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Blender Bros. (U)(Mode7)', '2002', NaN, 'Hudson Soft', '2', NaN, 'Side-scrolling platformer and action adventure.', 'Save the galaxy from the villainous Zoolians.', 'A fast-paced and colorful platformer with a unique sonic twist.', 'Blender Bros. features fluid movement and clever level design. Use your long ears to glide, spin, and defeat enemies across various planets, offering a polished 2D adventure that fans of classic platformers will love for its charm and challenge.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'BMX Trick Racer (U)(Mode7)', '2003', NaN, 'Trickstar Games', '1', NaN, 'Extreme sports BMX racing and stunt action.', 'Master bike tricks and win the world BMX championship.', 'Perform death-defying stunts and race for the gold.', 'BMX Trick Racer focuses on technical skill and timing. Navigate complex courses, perform grinds and backflips to earn points, and upgrade your bike to become the ultimate freestyle champion in this portable extreme sports title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Board Game Classics (E)(Independent)', '2003', NaN, 'Mass Media', '4', NaN, 'Collection of classic tabletop board games.', 'Outsmart opponents in Checkers, Chess, and Backgammon.', 'A portable digital library of the world''s favorite board games.', 'Board Game Classics for GBA offers a convenient way to play timeless games like Chess and Checkers on the go. Featuring adjustable AI difficulty and faithful rule sets, it’s the perfect companion for casual gamers who enjoy strategic puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Board Game Classics (U)(Trashman)', '2003', NaN, 'Mass Media', '4', NaN, 'Collection of classic tabletop board games.', 'Outsmart opponents in Checkers, Chess, and Backgammon.', 'A portable digital library of the world''s favorite board games.', 'Board Game Classics (US Version) provides a clean interface and smooth gameplay for multiple tabletop staples. Test your wits against the computer or a friend in this comprehensive collection of traditional strategy games.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bobobohbo Bohbobo Ougi 87.5 Bakuretsu Hanage Shinken (J)(Polla)', '2004', NaN, 'Takara', '1', NaN, 'Turn-based RPG and mini-game adventure.', 'Use the Fist of the Nose Hair to defeat the Chrome Dome Empire.', 'A bizarre and hilarious RPG based on the surreal Bobobo anime.', 'Bobobohbo Bohbobo Ougi 87.5 is a treat for fans of Japanese humor. Engage in turn-based battles featuring the most ridiculous attacks imaginable, following the surreal story of Bobobo-bo Bo-bobo in his quest to protect everyone''s hair.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boboboubo Boubobo - 9 Kiwame Senshi Gyagu Yuugou (J)(Rising Sun)', '2005', NaN, 'Takara', '1', NaN, 'Multi-genre adventure and mini-game collection.', 'Assemble the nine warriors to stop the hair-hunters.', 'A wacky mashup of mini-games and bizarre comedy.', '9 Kiwame Senshi Gyagu Yuugou brings the chaotic energy of the Bobobo universe to GBA. Solve puzzles, complete crazy mini-games, and interact with the show''s strange cast of characters in this unique and colorful Japanese title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boboboubo Boubobo - Bakuten Hajike Taisen (J)(Caravan)', '2004', NaN, 'Takara', '1', NaN, 'Grid-based tactical strategy and combat.', 'Defeat the enemy forces using bizarre nose-hair techniques.', 'A strategic take on the Bobobo series with tactical depth.', 'Bakuten Hajike Taisen offers a deeper tactical experience compared to other entries. Manage your team of weird warriors on a grid, utilizing surreal special moves to clear the board in this engaging and funny strategy game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boboboubo Boubobo 2 (J)(Cezar)', '2005', NaN, 'Takara', '1', NaN, 'Turn-based RPG and adventure.', 'Continue the journey to save hair and stop the empire.', 'The high-energy sequel to the surreal Bobobo RPG series.', 'Boboboubo Boubobo 2 expands on the bizarre combat and storytelling of the original. Featuring more characters, evolved battle mechanics, and even weirder jokes, it is the definitive handheld experience for fans of the franchise.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boktai - The Sun is in your Hand (E)(Rising Sun)', '2003', NaN, 'Konami', '1', NaN, 'Isometric action-adventure with a real-time solar sensor.', 'Use the power of the sun to purify vampires and monsters.', 'A groundbreaking vampire-hunting RPG from Hideo Kojima.', 'Boktai: The Sun is in Your Hand is a unique GBA masterpiece. Utilizing a real-life light sensor on the cartridge, players must use actual sunlight to charge their Solar Gun and defeat the undead in this atmospheric stealth-adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boktai - The Sun is in Your Hand (U)(Eurasia)', '2003', NaN, 'Konami', '1', NaN, 'Isometric action-adventure with a real-time solar sensor.', 'Use the power of the sun to purify vampires and monsters.', 'A groundbreaking vampire-hunting RPG from Hideo Kojima.', 'The US version of Boktai features the same innovative sunlight mechanics. Master stealth, solve intricate environmental puzzles, and experience a dark, compelling story that changes based on the time of day and the intensity of the sun.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boktai 2 - Solar Boy Django (E)(Eternity)', '2004', NaN, 'Konami', '1', NaN, 'Isometric action-adventure and RPG with combat.', 'Defeat the Dark Boy and restore light to the world.', 'The epic sequel to the solar-powered vampire hunting saga.', 'Boktai 2: Solar Boy Django introduces new weapons and the ability to forge gear. While still utilizing the solar sensor, this entry focuses more on traditional RPG elements and melee combat, offering a deeper and more versatile gameplay experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boktai 2 - Solar Boy Django (U)(Rising Sun)', '2004', NaN, 'Konami', '1', NaN, 'Isometric action-adventure and RPG with combat.', 'Defeat the Dark Boy and restore light to the world.', 'The epic sequel to the solar-powered vampire hunting saga.', 'Boktai 2 (US Version) continues Django''s journey. Use the solar sensor to charge your weapons and solve puzzles, exploring vast dungeons and battling giant bosses in one of the most technically impressive games on the platform.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boku No Kuwagata 3 (J)(Rising Sun)', '2003', NaN, 'Marvelous Interactive', '1', NaN, 'Beetle breeding and tactical battle simulation.', 'Breed and train the ultimate stag beetle for battle.', 'A deep and charming Japanese beetle-collecting simulation.', 'Boku No Kuwagata 3 lets you experience the life of a beetle trainer. Explore the countryside to find rare specimens, manage their diet and training, and compete in strength-based tournaments in this detailed Japanese hobby sim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boku wa Koukuu Kanseikan (J)(Rapid Fire)', '2003', NaN, 'Spike', '1', NaN, 'Air traffic control simulation and management.', 'Manage flight paths and ensure safe landings and takeoffs.', 'A realistic and challenging Japanese air traffic control sim.', 'Boku wa Koukuu Kanseikan puts you in the control tower of a busy airport. Balance arrival and departure schedules, manage taxiing planes, and prevent collisions in this high-pressure, strategic simulation title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bokujou Monogatari - Mineral Town for Girls (J)(Cezar)', '2003', NaN, 'Marvelous Interactive', '1', NaN, 'Farming simulation and social RPG.', 'Manage a successful farm and find love in Mineral Town.', 'The female-protagonist version of the classic Harvest Moon title.', 'Mineral Town for Girls (Harvest Moon: More Friends of Mineral Town) offers a deep farming experience. Grow crops, raise livestock, and build relationships with the townspeople from a new perspective in this beloved life-sim.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bokujou Monogatari - Mineral Town no Nakama Tachi (J)(Megaroms)', '2003', NaN, 'Marvelous Interactive', '1', NaN, 'Farming simulation and social RPG.', 'Restore your grandfather''s farm to its former glory.', 'The legendary GBA entry in the Harvest Moon farming series.', 'Mineral Town no Nakama Tachi is the definitive farming simulation. Experience the changing seasons, participate in town festivals, and build a lasting legacy in this addictive and heartwarming RPG that defined the genre on handheld.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bokura no Taiyo (J)(Eurasia)', '2003', NaN, 'Konami', '1', NaN, 'Isometric action-adventure with a real-time solar sensor.', 'Use the power of the sun to purify vampires and monsters.', 'The original Japanese release of the innovative solar RPG.', 'Bokura no Taiyo features the same groundbreaking sunlight-based gameplay. Master the Gun Del Sol and navigate complex dungeons filled with traps and undead foes in this Hideo Kojima-produced classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Jetters (English)', '2002', NaN, 'Hudson Soft', '4', NaN, 'Top-down action-adventure and puzzle-solving.', 'Stop the Mujoe and the Hige Hige Bandits.', 'A fan-translated adventure featuring classic Bomberman action.', 'Bomberman Jetters (English Patch) brings the anime-inspired story to western fans. Explore diverse planets, use unique Charaboms to gain abilities, and solve environmental puzzles in this expansive single-player adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Jetters (J)(Eurasia)', '2002', NaN, 'Hudson Soft', '4', NaN, 'Top-down action-adventure and puzzle-solving.', 'Stop the Mujoe and the Hige Hige Bandits.', 'The original Japanese release based on the Jetters anime.', 'Bomberman Jetters for GBA blends classic bomb-dropping gameplay with a deep adventure mode. Travel through various stages, collecting power-ups and battling massive bosses in a vibrant, cartoon-style world.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Jetters Game Collection (J)(Eurasia)', '2003', NaN, 'Hudson Soft', '4', NaN, 'Collection of Bomberman mini-games.', 'Master various arcade challenges and high-score puzzles.', 'A fun-filled collection of Bomberman-themed mini-games.', 'Bomberman Jetters Game Collection offers a variety of quick-play challenges. From racing to logic puzzles, this Japanese title is perfect for short sessions, featuring the charming cast of the Jetters series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Max 2 - Bomberman Version (J)(Hyperion)', '2002', NaN, 'Hudson Soft', '1', NaN, 'Top-down action and creature collection RPG.', 'Defeat the Brain Bomber and stop the shrinking of Earth.', 'A unique Bomberman adventure focusing on the hero himself.', 'Bomberman Max 2 - Bomberman Version allows you to raise and evolve Charaboms to help you in battle. Clear classic bomb-laying stages while navigating a branching world map in this creature-collecting hybrid.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Max 2 - Max Version (J)(Hyperion)', '2002', NaN, 'Hudson Soft', '1', NaN, 'Top-down action and creature collection RPG.', 'Defeat the Brain Bomber and stop the shrinking of Earth.', 'Play as the rival Max in this companion Bomberman title.', 'Bomberman Max 2 - Max Version offers a different perspective on the story. While the core gameplay remains the same, players use Max''s unique skills and different Charaboms to clear stages and defeat the villainous bandits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Max 2 Blue (E)(Megaroms)', '2003', NaN, 'Hudson Soft', '4', NaN, 'Top-down action and creature collection RPG.', 'Rescue the Charaboms and defeat the shadow organization.', 'The European release of the creature-collecting Bomberman hit.', 'Bomberman Max 2 Blue features over 80 Charaboms to collect and train. Navigate through grid-based levels, use strategic bomb placement, and trade creatures with the Red version to complete your collection.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Max 2 Blue Advance (U)(Mode7)', '2003', NaN, 'Hudson Soft', '4', NaN, 'Top-down action and creature collection RPG.', 'Rescue the Charaboms and defeat the shadow organization.', 'The US release of the Blue version featuring Charabom training.', 'Bomberman Max 2 Blue Advance delivers a deep single-player campaign and competitive multiplayer. Master the elemental powers of your Charaboms to overcome obstacles and solve puzzles in this expansive bomb-dropping RPG.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Max 2 Red (E)(Megaroms)', '2003', NaN, 'Hudson Soft', '4', NaN, 'Top-down action and creature collection RPG.', 'Rescue the Charaboms and defeat the shadow organization.', 'The companion Red version with exclusive Charaboms.', 'Bomberman Max 2 Red features a different set of collectable creatures compared to Blue. Players must navigate challenging stages and use their tactical skills to stop the shrinking of their home planet.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Max 2 Red Advance (U)(Mode7)', '2003', NaN, 'Hudson Soft', '4', NaN, 'Top-down action and creature collection RPG.', 'Rescue the Charaboms and defeat the shadow organization.', 'The US release of the Red version featuring Charabom training.', 'Bomberman Max 2 Red Advance is the perfect strategic action game. Level up your creatures, find hidden power-ups, and enjoy classic Bomberman battle modes in this content-rich handheld title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Story (J)(Eurasia)', '2000', NaN, 'Hudson Soft', '4', NaN, 'Action-RPG with exploration and turn-based battles.', 'Embark on a quest to save the world and find the missing bombs.', 'A deep and story-driven RPG take on the Bomberman franchise.', 'Bomberman Story (Japanese Version) focuses on exploration and character interaction. Unlike traditional entries, it features an overhead world map, towns, and a quest system, blending the bomb-dropping action with classic RPG elements.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bomberman Tournament (U)(Mode7)', '2001', NaN, 'Hudson Soft', '4', NaN, 'Action-RPG and tactical combat.', 'Defeat the shadows and win the Bomberman tournament.', 'The localized RPG adventure for the Western market.', 'Bomberman Tournament is a standout title on GBA. Explore a Zelda-like world, collect and battle creatures in a tactical mini-game, and clear dungeons using traditional Bomberman mechanics in this highly polished adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'BookWorm (U)(Rising Sun)', '2003', NaN, 'PopCap Games', '1', NaN, 'Word-building puzzle gameplay.', 'Feed the hungry bookworm by linking letters to form words.', 'A classic and addictive word puzzle game for all ages.', 'BookWorm for GBA brings the hit PC puzzle game to handheld. Help Lex the Bookworm devour letters to create words and clear the board, featuring various game modes that test your vocabulary and speed in a fun, educational environment.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bouken Yuuki Densetsu Plaston Gate (J)(Rising Sun)', '2003', NaN, 'Takara', '1', NaN, 'Creature-collecting RPG and tactical combat.', 'Explore the world of Plust Gate and master your Plaston.', 'A unique Japanese adventure featuring monster collection and battles.', 'Bouken Yuuki Densetsu Plaston Gate offers a deep RPG experience. Travel across vibrant lands, collect mysterious creatures known as Plastons, and engage in strategic turn-based battles to uncover the secrets of the ancient Gate.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bouken Yuuki PlaStar World - Densetsu no Plust Gate EX (J)(Independent)', '2004', NaN, 'Takara', '1', NaN, 'Enhanced creature-collecting RPG.', 'Complete the ultimate collection and save the Plust world.', 'An expanded version of the Japanese monster-battle adventure.', 'Densetsu no Plust Gate EX features new creatures, refined battle mechanics, and additional story content. Master the elemental strengths of your Plastons to become the supreme trainer in this high-quality Japanese GBA import.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bouken Yuuki Plaston GP (J)(Rising Sun)', '2003', NaN, 'Takara', '1', NaN, 'Racing and vehicular combat with creature elements.', 'Win the Plaston GP tournament using unique monster-cars.', 'A high-speed Japanese racer featuring creature-inspired vehicles.', 'Bouken Yuuki Plaston GP combines the thrill of racing with creature combat. Customize your Plaston vehicle, use special abilities to outmaneuver rivals, and master diverse tracks to claim the championship trophy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Bouken-Ou Beet - Busters Road (J)(Caravan)', '2002', NaN, 'Bandai', '1', NaN, 'Action-adventure and monster-hunting RPG.', 'Defeat the Vandel monsters and become a top-tier Buster.', 'Based on the popular manga series, embark on a quest for glory.', 'Bouken-Ou Beet - Busters Road brings the world of Beet the Vandel Buster to GBA. Engage in real-time combat, upgrade your Saiga weapons, and complete dangerous missions to cleanse the world of dark forces.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boukyaku no Senritsu (J)(Independent)', '2003', NaN, 'Independent', '1', NaN, 'Strategy and adventure with mecha elements.', 'Pilot the Icarus and defeat the monsters threatening humanity.', 'A dark and stylish Japanese adventure based on the cult anime.', 'Boukyaku no Senritsu (The Melody of Oblivion) offers a unique blend of narrative exploration and strategic combat. Battle through surreal landscapes and master the powers of the Melody to fulfill your destiny in this atmospheric title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boulder Dash EX (E)(Patience)', '2002', NaN, 'First Star Software', '1', NaN, 'Classic puzzle-action and cave exploration.', 'Collect diamonds and find the exit while avoiding falling rocks.', 'A modern remake of the legendary arcade classic Boulder Dash.', 'Boulder Dash EX revitalizes the retro hit with updated graphics and new gameplay modes. Navigate treacherous underground caves, outsmart enemies, and manage physics-based puzzles to collect every gem and escape alive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boulder Dash EX (J)(Polla)', '2002', NaN, 'First Star Software', '1', NaN, 'Classic puzzle-action and cave exploration.', 'Collect diamonds and find the exit while avoiding falling rocks.', 'The Japanese edition of the updated arcade puzzle classic.', 'Boulder Dash EX (Japanese Version) delivers the same addictive grid-based strategy. Experience the classic puzzle levels and the new world-based adventure mode, perfect for fans of logic and timing-based gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Boulder Dash EX (U)(Mode7)', '2002', NaN, 'First Star Software', '1', NaN, 'Classic puzzle-action and cave exploration.', 'Collect diamonds and find the exit while avoiding falling rocks.', 'A modern remake of the legendary arcade classic Boulder Dash.', 'Boulder Dash EX for GBA offers 2D puzzle-solving at its best. Featuring the classic Dig-and-Drop mechanics, players must navigate dangerous mines and use falling boulders to trap enemies and uncover hidden paths.', NULL);
