INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Card Captor - Sakura Card Friends (J)(Cezar)', '2001', NaN, 'TOSE', '1', NaN, 'Visual novel and social simulation.', 'Help Sakura build friendships and collect Clow Cards.', 'A charming Japanese social adventure based on Cardcaptor Sakura.', 'Card Captor Sakura - Sakura Card Friends lets you experience the daily life of Sakura Kinomoto. Interact with iconic characters, participate in school events, and strengthen your bonds to unlock special story events in this faithful anime adaptation.', NULL);
