INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Alfred Hack', '2003', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Play as Alfred and master his unique alchemical combat.', 'A character-swap hack for the legendary Aria of Sorrow.', 'The Alfred Hack introduces the Alchemist from Circle of the Moon into Aria of Sorrow. Experience a fresh take on the castle exploration with a new move set and projectile-based combat strategy.', NULL);
