INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Circle Of The Moon - Card Mode', '2001', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG with magic card focus.', 'Defeat Dracula using a full deck of magical DSS cards.', 'A special mode for Circle of the Moon focusing on magic.', 'Castlevania - Circle Of The Moon - Card Mode grants the player all Dual Set-up System (DSS) cards from the start. Experiment with powerful elemental combinations and magical summons to conquer the castle in this strategic and high-power variant.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Circle Of The Moon - Hugh Baldwin Hack', '2001', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG with sword combat.', 'Explore the castle as the master swordsman Hugh Baldwin.', 'A character-swap hack featuring Nathan''s rival.', 'In the Hugh Baldwin Hack, play through Circle of the Moon with a completely different combat style. Trade the traditional whip for a fast-paced sword and unique sub-weapons, offering a fresh challenge for veteran vampire hunters.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Circle of the Moon (E)(Eurasia)', '2001', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Slay the undead and seal Dracula within the castle walls.', 'The critically acclaimed debut of Castlevania on the GBA.', 'Castlevania - Circle of the Moon (European Version) features the innovative DSS card system. Explore a dark, atmospheric castle, battle iconic bosses, and master the whip in one of the most challenging and rewarding entries in the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Circle of the Moon (U)(Cezar)', '2001', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Slay the undead and seal Dracula within the castle walls.', 'The critically acclaimed debut of Castlevania on the GBA.', 'Castlevania - Circle of the Moon (US Version) brings gothic horror to your handheld. Combine Action and Attribute cards to create over 80 unique magical effects while navigating a massive, secret-filled map.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Harmony of Dissonance (E)(Eurasia)', '2002', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Hunt for the remains of Dracula in a dual-layered castle.', 'A fast-paced adventure featuring Juste Belmont.', 'Castlevania - Harmony of Dissonance (European Version) focuses on speed and flashy magic. Use the Spell Fusion system to combine sub-weapons with elemental books, creating devastating attacks in a sprawling, interconnected castle.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Harmony of Dissonance (U)(Independent)', '2002', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Hunt for the remains of Dracula in a dual-layered castle.', 'A fast-paced adventure featuring Juste Belmont.', 'Castlevania - Harmony of Dissonance (US Version) stars Juste Belmont on a quest to save his friend Lydie. Explore two versions of the castle simultaneously, featuring vibrant graphics and intense, high-speed action.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Maria of Sorrow - Easy', '2003', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Save the world as Maria Renard with reduced difficulty.', 'A character hack featuring the legendary huntress on Easy mode.', 'Maria of Sorrow - Easy allows players to breeze through the castle using Maria''s unique animal-based attacks. With adjusted damage and higher health, it''s perfect for players who want to focus on exploration and Maria''s story.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Maria of Sorrow - Normal', '2003', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Save the world as Maria Renard with standard difficulty.', 'A character hack featuring the legendary huntress on Normal mode.', 'Maria of Sorrow - Normal replaces Soma Cruz with Maria Renard. Use her owls, cats, and dragons to fight through the castle, offering a completely different mechanical feel to the classic Aria of Sorrow gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - Minuet Of Dawn (J)(Eurasia)', '2003', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Absorb the souls of your enemies to stop the resurrection.', 'The original Japanese release of Aria of Sorrow.', 'Castlevania - Minuet Of Dawn is the Japanese title for the acclaimed third GBA entry. Experience the deep Tactical Soul system and the futuristic setting of 2035 in its original, unedited format.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania - White Night Concerto (J)(Eurasia)', '2003', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Hunt for the remains of Dracula in a dual-layered castle.', 'The original Japanese release of Harmony of Dissonance.', 'Castlevania - White Night Concerto stars Juste Belmont in a quest for the relics of Dracula. Experience the high-speed movement and complex Spell Fusion system of this classic GBA Metroidvania.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania Aria of Sorrow - Recolor by JonataGuitar', '2003', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Absorb souls in a castle with a vibrant new color palette.', 'A visual enhancement hack for Aria of Sorrow.', 'This Recolor hack by JonataGuitar updates the visual style of the game. Featuring improved saturation and color balance, it gives the 2035 setting a fresh, modern look without changing the legendary gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania Aria of Sorrow Kaizo', '2003', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Survive the ultimate challenge in a high-difficulty castle.', 'A brutal Kaizo style difficulty hack for Aria of Sorrow.', 'Castlevania Aria of Sorrow Kaizo is designed for masters of the game. Featuring redesigned rooms, aggressive enemy AI, and pixel-perfect platforming requirements, it is the ultimate test for any vampire hunter.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania Dawn of Symphony (Alucard SOTN Hack)', '2003', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Explore the eclipse as Alucard with his SOTN moveset.', 'A massive hack bringing Alucard from Symphony of the Night.', 'Castlevania Dawn of Symphony transforms the game into a true Alucard experience. Featuring sprites and mechanics directly inspired by the PlayStation classic, it’s the ultimate crossover for series fans.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania Harmony of Dissonance - Recolor by JonataGuitar and sorrow', '2002', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Explore the castle with improved colors and Aria of Sorrow style.', 'A visual and stylistic overhaul for Harmony of Dissonance.', 'This Recolor hack fixes the bright, saturated colors of the original game to match the darker, more gothic tone of Aria of Sorrow, making for a much more atmospheric and visually pleasing experience.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castlevania Harmony of Dissonance Music Overhaul', '2002', NaN, 'Konami', '1', NaN, 'Side-scrolling action-RPG (Metroidvania).', 'Hunt Dracula with an improved and high-quality soundtrack.', 'A technical hack that replaces the original''s MIDI music.', 'Harmony of Dissonance Music Overhaul addresses the game''s biggest criticism by replacing the low-quality sound files with high-fidelity tracks, bringing the audio quality up to the standards of the other GBA entries.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Castleween (E)(Eurasia)', '2004', NaN, 'Independent', '1', NaN, 'Side-scrolling platformer with horror themes.', 'Rescue your friends from the clutches of the evil Bogeyman.', 'A spooky and fun platformer perfect for the Halloween season.', 'Castleween (known as Spirits & Spells in the US) features a charming gothic art style. Switch between Greg and Alicia, each with unique abilities, to navigate treacherous graveyards and haunted houses.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Catwoman (U)(Hyperion)', '2004', NaN, 'EA UK', '1', NaN, 'Third-person action-adventure and stealth.', 'Use your feline agility to pull off a series of high-stakes heists.', 'Play as the iconic anti-heroine in this movie-based adventure.', 'Catwoman for GBA features acrobatic movement and whip-based combat. Master the art of stealth to bypass security, solve environmental puzzles, and experience the thrill of the hunt in Gotham City.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Catz (E)(Rising Sun)', '2003', NaN, 'MTO', '1', NaN, 'Virtual pet simulation and animal care.', 'Raise, train, and play with your favorite breeds of kittens.', 'A cute and relaxing virtual pet game for cat lovers.', 'Catz for GBA allows you to adopt and care for a variety of adorable kittens. Feed them, groom them, and play mini-games to build a bond with your digital feline friends in this charming simulation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Catz (U)(Rising Sun)', '2003', NaN, 'MTO', '1', NaN, 'Virtual pet simulation and animal care.', 'Raise, train, and play with your favorite breeds of kittens.', 'The US version of the popular feline care simulator.', 'Catz (US Version) offers a portable sanctuary for cat enthusiasts. Customize your kittens with accessories and watch them grow as you provide them with a happy and healthy digital home.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Centipede, Breakout, Warlords (E)(Supplex)', '2005', NaN, 'Atari', '4', NaN, 'Arcade compilation of retro classics.', 'Achieve high scores in three legendary Atari arcade hits.', 'A 3-in-1 collection featuring Centipede, Breakout, and Warlords.', 'This Atari collection brings the golden age of arcades to your GBA. Battle insect hordes in Centipede, smash bricks in Breakout, and defend your castle in the frantic multiplayer-classic Warlords.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Centipede, Breakout, Warlords (U)(Trashman)', '2005', NaN, 'Atari', '4', NaN, 'Arcade compilation of retro classics.', 'Achieve high scores in three legendary Atari arcade hits.', 'A 3-in-1 collection featuring Centipede, Breakout, and Warlords.', 'The US version of this classic compilation offers pixel-perfect gameplay. Test your reflexes across three distinct arcade genres, each with multiple difficulty settings and faithful retro sound effects.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chaoji Maliou (C)(WRG)', '2001', NaN, 'Nintendo', '1', NaN, '2D side-scrolling platformer (Mario-style).', 'Save the princess and defeat the turtle kingdom.', 'A Chinese-developed 8-bit style Mario clone for GBA.', 'Chaoji Maliou is a fascinating piece of bootleg history. It offers classic platforming gameplay reminiscent of Super Mario Bros., featuring familiar levels and mechanics adapted for the Game Boy Advance hardware.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chaoji Maliou Shijie (C)(WRG)', '2001', NaN, 'Nintendo', '1', NaN, '2D side-scrolling platformer (Mario-style).', 'Explore the world and defeat the evil King Koopa.', 'A Chinese-developed Mario adventure featuring diverse levels.', 'Chaoji Maliou Shijie (Super Mario World) brings a unique take on the platforming legend. Navigate through various worlds, collect power-ups, and enjoy a retro-style adventure in this unlicensed Chinese release.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Charlie and the Chocolate Factory (E)(Independent)', '2005', NaN, 'High Voltage Software', '1', NaN, 'Action-adventure and mini-game collection.', 'Explore the factory and find the Great Glass Elevator.', 'A whimsical adventure based on the Tim Burton film.', 'Charlie and the Chocolate Factory for GBA lets you play as Charlie Bucket. Work with the Oompa-Loompas to solve puzzles, clean up the factory, and avoid the traps set for the other greedy children.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Charlie and the Chocolate Factory (U)(Trashman)', '2005', NaN, 'High Voltage Software', '1', NaN, 'Action-adventure and mini-game collection.', 'Explore the factory and find the Great Glass Elevator.', 'A whimsical adventure based on the Tim Burton film.', 'The US version of Charlie and the Chocolate Factory features vibrant levels based on the movie''s iconic rooms. Master various mini-games and use clever platforming to prove you are the worthy heir to Wonka’s legacy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Charlotte''s Web (E)(Independent)', '2006', NaN, 'Gravity-I', '1', NaN, 'Side-scrolling adventure and mini-game collection.', 'Help Wilbur the pig win the blue ribbon at the county fair.', 'A heartwarming adventure based on the classic book and movie.', 'Charlotte''s Web for GBA features exploration and teamwork. Play as Wilbur and Templeton the rat to complete missions for Charlotte, solving puzzles and playing mini-games to ensure Wilbur''s safety.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Charlotte''s Web (U)(Rising Sun)', '2006', NaN, 'Gravity-I', '1', NaN, 'Side-scrolling adventure and mini-game collection.', 'Help Wilbur the pig win the blue ribbon at the county fair.', 'A heartwarming adventure based on the classic book and movie.', 'The US version of Charlotte''s Web brings the farm to life. Navigate through beautiful 2D environments, help your animal friends, and experience the timeless story of friendship and bravery on your handheld.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chessmaster (E)(Lightforce)', '2002', NaN, 'Software Toolworks', '2', NaN, 'Strategic board game and chess simulation.', 'Defeat the grandmaster and improve your chess skills.', 'The definitive portable edition of the world''s most famous chess sim.', 'Chessmaster for GBA offers a robust chess engine for all skill levels. Featuring deep tutorials, multiple AI personalities, and a clean interface, it’s the perfect tool for both beginners and seasoned pros to practice on the go.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chessmaster (F)(Patience)', '2002', NaN, 'Software Toolworks', '2', NaN, 'Strategic board game and chess simulation.', 'Defeat the grandmaster and improve your chess skills.', 'The French-localized version of the premier chess simulator.', 'Chessmaster (French Version) provides a comprehensive set of challenges and training modes. Test your tactical wit against a variety of virtual opponents in this polished and intellectual strategy game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chessmaster (G)(Rising Sun)', '2002', NaN, 'Software Toolworks', '2', NaN, 'Strategic board game and chess simulation.', 'Defeat the grandmaster and improve your chess skills.', 'The German-localized version of the premier chess simulator.', 'Chessmaster (German Version) features the same high-quality chess engine. Analyze your moves, learn from past games, and climb the ranks of the professional chess world in this portable strategic masterclass.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'ChessMaster (U)(BatMan)', '2002', NaN, 'Software Toolworks', '2', NaN, 'Strategic board game and chess simulation.', 'Defeat the grandmaster and improve your chess skills.', 'The US version of the comprehensive chess training software.', 'ChessMaster for GBA is a must-have for strategy fans. With over 20 different AI opponents and hundreds of classic match scenarios to analyze, it offers an endless amount of deep, intellectual gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chi Vuol Essere Milionario (I)(Paranoid)', '2000', NaN, 'Sony Computer Entertainment', '1', NaN, 'Trivia-based quiz game.', 'Answer 15 consecutive questions to win the virtual million.', 'The Italian edition of Who Wants to Be a Millionaire?.', 'Chi Vuol Essere Milionario brings the tension of the hit TV show to your GBA. Use your lifelines (50:50, Phone a Friend, Ask the Audience) wisely to navigate through increasingly difficult questions and reach the final prize in this faithful Italian adaptation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chicken Little (J)(sUppLeX)', '2005', NaN, 'Altron', '1', NaN, '2D action platformer and vehicle segments.', 'Help Chicken Little save the town from an alien invasion.', 'Join Chicken Little and friends in this colorful Disney adventure.', 'Chicken Little for GBA features a mix of running, jumping, and specialized vehicle levels. Play as Chicken Little, Runt, or Abby Mallard as you navigate through Oakey Oaks to prove the sky really is falling in this engaging movie-based title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chicken Little (U)(Trashman)', '2005', NaN, 'Altron', '1', NaN, '2D action platformer and vehicle segments.', 'Help Chicken Little save the town from an alien invasion.', 'Join Chicken Little and friends in this colorful Disney adventure.', 'The US version of Chicken Little offers polished handheld platforming. Master various gadgets and dodge obstacles across levels inspired by the film, providing a fun and accessible experience for fans of the Disney/Pixar animation.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chicken Shoot (E)(Rising Sun)', '2005', NaN, 'FrontLine Studios', '1', NaN, 'Point-and-click style shooting gallery.', 'Blast as many chickens as possible to earn high scores.', 'A quirky and fast-paced arcade shooter featuring crazy birds.', 'Chicken Shoot for GBA is a frantic gallery shooter. Use your crosshairs to hunt down mischievous chickens across various farm and village backdrops, featuring humorous animations and addictive, high-score driven gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chicken Shoot (U)(Independent)', '2005', NaN, 'FrontLine Studios', '1', NaN, 'Point-and-click style shooting gallery.', 'Blast as many chickens as possible to earn high scores.', 'A quirky and fast-paced arcade shooter featuring crazy birds.', 'The US version of Chicken Shoot delivers arcade action on the go. Test your reflexes across multiple levels and difficulty settings as you try to stop the poultry takeover in this lighthearted and competitive shooting game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chicken Shoot 2 (E)(Sir VG)', '2006', NaN, 'FrontLine Studios', '1', NaN, 'Point-and-click style shooting gallery.', 'Clear the screen of chickens in new international locations.', 'The high-flying sequel with more levels and better graphics.', 'Chicken Shoot 2 expands the arcade experience with even more chaotic levels. Travel to exotic locations and use various power-ups to clear the screen of feathered foes in this fast-paced and funny handheld sequel.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chicken Shoot 2 (U)(Independent)', '2006', NaN, 'FrontLine Studios', '1', NaN, 'Point-and-click style shooting gallery.', 'Clear the screen of chickens in new international locations.', 'The high-flying sequel with more levels and better graphics.', 'The US version of Chicken Shoot 2 offers refined controls and new challenges. Compete for the highest score as you blast your way through diverse environments filled with hidden secrets and comical chicken animations.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chobits (J)(MUGS)', '2003', NaN, 'Digital Works', '1', NaN, 'Visual novel and social simulation.', 'Build a relationship with the Persocon Chi and teach her about life.', 'A charming Japanese adventure based on the Chobits manga.', 'Chobits for GBA allows fans to experience the world of CLAMP''s famous series. Interact with Chi, participate in daily activities, and make choices that influence her personality and your bond in this beautifully illustrated Japanese title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chocobo Land - Game de Dice (J)(Mugs)', '2002', NaN, 'Squaresoft', '4', NaN, 'Digital board game with RPG elements.', 'Use dice to navigate the board and bankrupt your opponents.', 'A unique Final Fantasy spin-off starring the lovable Chocobo.', 'Chocobo Land - Game de Dice features strategic board-based gameplay. Acquire property, use magical spells, and summon classic Final Fantasy creatures to outmaneuver your rivals and dominate the map in this Japanese-exclusive gem.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Choh Makai-Mura R (J)(Eurasia)', '2002', NaN, 'Capcom', '1', NaN, 'Hardcore side-scrolling action platformer.', 'Defeat the demons and save Princess Prin-Prin once again.', 'An enhanced GBA port of the legendary Super Ghouls ''n Ghosts.', 'Choh Makai-Mura R is the definitive handheld version of the Capcom classic. Featuring new levels and a branching path system, this Japanese release offers the same brutal difficulty and rewarding combat that fans of Arthur''s adventures love.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Choro Q Advance (J)(Eurasia)', '1999', NaN, 'Taito', '1', NaN, 'Miniature car racing and customization.', 'Win races to earn parts and customize your Choro Q car.', 'A fun and deep RPG-style racer with tiny customizable cars.', 'Choro Q Advance (known as Gadget Racers) combines arcade racing with deep customization. Explore the world, compete in various events, and choose from hundreds of parts to build the perfect miniature vehicle for any terrain.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Choro Q Advance 2 (J)(Eurasia)', '2000', NaN, 'Taito', '1', NaN, 'Miniature car racing and customization.', 'Become the champion of the Choro Q world in this expanded sequel.', 'More cars, more parts, and more tracks in this Japanese hit.', 'Choro Q Advance 2 builds upon its predecessor with refined handling and a larger world map. Engage in diverse racing challenges and manage your car''s stats to become the fastest racer in the Choro Q universe.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chu Chu Rocket! (E)(Independent)', '2001', NaN, 'Sonic Team', '4', NaN, 'Puzzle-solving and path management.', 'Guide the mice (ChuChus) to the rockets while avoiding cats.', 'A frantic and addictive puzzle classic from the Dreamcast era.', 'Chu Chu Rocket! for GBA is a perfect port of Sega''s chaotic puzzle hit. Place directional arrows on the floor to lead your mice to safety in both the intense single-player puzzle mode and the frantic 4-player battle mode.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chu Chu Rocket! (J)(Capital)', '2001', NaN, 'Sonic Team', '4', NaN, 'Puzzle-solving and path management.', 'Guide the mice (ChuChus) to the rockets while avoiding cats.', 'The Japanese version of the legendary Sega puzzle game.', 'This Japanese release of Chu Chu Rocket! features hundreds of brain-teasing puzzles. Master the art of tile placement to outsmart the KapuKapu cats and ensure all your mice make it to the escape rockets.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Chu Chu Rocket! (U)(The Corporation)', '2001', NaN, 'Sonic Team', '4', NaN, 'Puzzle-solving and path management.', 'Guide the mice (ChuChus) to the rockets while avoiding cats.', 'The US version of the high-speed mouse-saving puzzle game.', 'Chu Chu Rocket! on the GBA delivers infinite replayability. With a built-in level editor and fast-paced Battle gameplay, it remains one of the most unique and challenging puzzle experiences on the handheld platform.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'CIMA The Enemy (U)(Mode7)', '2003', NaN, 'Neverland', '1', NaN, 'Isometric tactical RPG with squad management.', 'Protect the innocent and lead your team through hostile territory.', 'A deep and strategic RPG featuring the CIMA rescue system.', 'CIMA The Enemy offers a unique take on the RPG genre. Instead of just fighting, you must protect and guide a group of survivors through dangerous dungeons, managing their safety and morale while uncovering a dark alien conspiracy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Cinderella - Magical Dreams (E)(sUppLeX)', '2005', NaN, 'Disney Interactive', '1', NaN, 'Side-scrolling adventure and mini-game collection.', 'Help Cinderella prepare for the ball and find her True Love.', 'A magical Disney adventure featuring the iconic glass slipper.', 'Cinderella - Magical Dreams brings the classic fairy tale to GBA. Explore the chateau, complete tasks for the Fairy Godmother, and avoid the wicked stepmother in a series of beautifully animated platforming levels and puzzles.', NULL);
