INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Cinnamon Fuwafuwa Daisakusen (J)(sUppLeX)', '2004', NaN, 'Sonic Powered', '1', NaN, 'Mini-game collection and social simulation.', 'Complete various fluffy missions to keep everyone happy.', 'More adorable adventures with the Cinnamoroll gang.', 'Cinnamon Fuwafuwa Daisakusen features a variety of casual mini-games themed around the world of Sanrio. Perfect for younger players, it offers a safe and charming environment filled with cute characters and relaxing gameplay.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Cinnamoroll Kokoniiruyo (J)(Rising Sun)', '2003', NaN, 'Interchannel', '1', NaN, 'Social simulation and pet care.', 'Take care of your Cinnamoroll friend and build a lasting bond.', 'A portable virtual friend experience starring Cinnamoroll.', 'Cinnamoroll Kokoniiruyo focuses on the daily interaction with your favorite Sanrio puppy. Feed, play, and talk to Cinnamoroll as you build a friendship that grows over time in this cozy Japanese handheld game.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Classic Nes - Bomberman (U)(Psychosis)', '2004', NaN, 'Hudson Soft', '2', NaN, 'Top-down action and bomb-laying strategy.', 'Defeat all enemies on screen to advance to the next level.', 'The pixel-perfect NES original reborn for the GBA.', 'Classic NES - Bomberman brings the 8-bit classic to your pocket. Relive the simple yet addictive gameplay of laying bombs, finding power-ups, and clearing stages in this faithful recreation of the game that started it all.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Classic NES - Castlevania (U)(BatMan)', '2004', NaN, 'Konami', '1', NaN, 'Side-scrolling action platformer.', 'Enter Dracula''s castle and defeat the Lord of Darkness.', 'The legendary NES original that launched the franchise.', 'Classic NES - Castlevania allows you to experience Simon Belmont''s first quest on the go. Master the whip and sub-weapons to battle through iconic stages and bosses in this challenging and authentic 8-bit port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Classic Nes - Donkey Kong (U)(Hyperion)', '2004', NaN, 'Nintendo', '1', NaN, 'Single-screen platforming and arcade action.', 'Help Mario rescue Pauline from the giant ape.', 'The arcade and NES masterpiece on your handheld.', 'Classic NES - Donkey Kong features all the iconic levels of the original. Dodge barrels, climb ladders, and time your jumps perfectly to reach the top in this definitive port of one of gaming''s most important titles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Classic Nes - Excite Bike (U)(Psychosis)', '2004', NaN, 'Nintendo', '1', NaN, 'Side-scrolling motocross racing.', 'Reach the finish line as fast as possible without overheating.', 'The high-flying NES racing classic on the GBA.', 'Classic NES - Excite Bike brings the thrill of motocross to your handheld. Master the terrain, manage your engine temperature, and create your own tracks in the iconic Design Mode in this pixel-perfect retro port.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Classic Nes - Ice Climber (U)(Hyperion)', '2004', NaN, 'Nintendo', '2', NaN, 'Vertical-scrolling platformer and puzzle action.', 'Scale the mountain and reclaim the stolen vegetables.', 'The cooperative NES classic featuring Popo and Nana.', 'Classic NES - Ice Climber challenges you to reach the summit by breaking through ice ceilings. Avoid falling and dodge pesky creatures in this authentic 8-bit recreation of the vertical-climbing favorite.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Classic NES - Metroid (U)(BatMan)', '2004', NaN, 'Nintendo', '1', NaN, 'Side-scrolling action-adventure (Metroidvania).', 'Navigate Planet Zebes and destroy Mother Brain.', 'The groundbreaking NES adventure that defined a genre.', 'Classic NES - Metroid brings Samus Aran''s original mission to the GBA. Explore a non-linear world, find power-ups like the Morph Ball and Missiles, and experience the atmospheric 8-bit exploration that started the series.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Classic Nes - Pacman (U)(Hyperion)', '2004', NaN, 'Namco', '1', NaN, 'Maze-based arcade action.', 'Eat all the dots while avoiding the four ghosts.', 'The world''s most famous arcade game in the palm of your hand.', 'Classic NES - Pacman is a faithful port of the 8-bit home version. Master the patterns, collect power pellets to turn the tables on Blinky, Pinky, Inky, and Clyde, and chase high scores in this timeless classic.', NULL);
