INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Code Breaker (U)(Independent)', '2000', NaN, 'Codemaster', '1', NaN, 'Game enhancement and cheat utility.', 'Unlock secret features and infinite lives in GBA games.', 'The famous cheat device software for Game Boy Advance.', 'Code Breaker is the essential utility for GBA power users. Access a massive database of cheat codes to unlock hidden levels, infinite health, and secret characters across hundreds of compatible titles on your handheld.', NULL);
