INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Crash Bandicoot Fusion (E)(Rising Sun)', '2004', NaN, 'Vivendi Universal', '1', NaN, 'Isometric adventure and mini-game crossover.', 'Stop the combined threat of Cortex and Ripto.', 'The European version of the Crash and Spyro crossover.', 'Crash Bandicoot Fusion allows players to explore a variety of themed worlds. Connect with the Spyro version of the game to unlock exclusive content and trade cards in this expansive handheld social title.', NULL);
