INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Crash of the Titans (E)(sUppLeX)', '2007', NaN, 'Amaze Entertainment', '1', NaN, 'Action-adventure and brawler with jacking mechanics.', 'Hijack massive Titans to stop Cortex''s latest scheme.', 'A unique reimagining of the Crash series with combat focus.', 'Crash of the Titans for GBA introduces the ability to control powerful mutant enemies. Use their unique strengths to solve puzzles and defeat waves of foes in this high-energy, combat-oriented platformer.', NULL);
