INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Crayon Shin chan - Densetsu wo Yobu Omake no Miyako Shockgaan (J)(Independent)', '2004', NaN, 'Banpresto', '1', NaN, 'Side-scrolling action platformer.', 'Navigate through wacky levels based on the Shin-chan anime.', 'A colorful and hilarious Japanese adventure starring Shin-chan.', 'Shockgaan features the signature humor and art style of the Crayon Shin-chan series. Use various costumes to gain new abilities and overcome bizarre obstacles in this charming Japanese-exclusive title.', NULL);
