INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Crazy Chase (E)(Patience)', '2003', NaN, 'Patience', '1', NaN, 'Isometric obstacle-course runner.', 'Chase the prince and reach the goal before time runs out.', 'A vibrant and quirky isometric racing-action game.', 'Crazy Chase (Kid Klown) features frantic gameplay where you must avoid traps and obstacles in a 2.5D environment. Master the timing of your jumps and dashes to recover the stolen crown in this colorful handheld port of the SNES classic.', NULL);
