INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dora the Explorer - Super Spies (U)(Rising Sun)', '2004', NaN, 'Stainless Games', '1', NaN, 'Educational adventure and stealth-lite.', 'Use spy gadgets to solve mysteries and stop Swiper.', 'A mission-based adventure featuring Dora''s Super Spy team.', 'Dora the Explorer - Super Spies turns learning into a secret mission. Use gadgets like the Spy Glass and Sneaky Boots to navigate levels and complete educational puzzles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dora the Explorer - Super Star Adventures (U)(Rising Sun)', '2003', NaN, 'Stainless Games', '1', NaN, 'Educational adventure and mini-game collection.', 'Collect stars and complete tasks in a magical world.', 'A charming and interactive adventure for Dora fans.', 'Super Star Adventures features various mini-games that focus on memory, logic, and coordination. Help Dora find the special Explorer Stars in this bright and encouraging title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dora the Explorer - Super Star Adventures! (E)(Sir VG)', '2003', NaN, 'Stainless Games', '1', NaN, 'Educational adventure and mini-game collection.', 'Collect stars and complete tasks in a magical world.', 'The European version of the interactive star-hunting quest.', 'This localized version of Super Star Adventures! provides a gentle learning experience. Guide Dora through the Rainforest and beyond while mastering simple, fun challenges.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dora the Explorer - The Search for Pirate Pig''s Treasure (U)(Eurasia)', '2002', NaN, 'Stainless Games', '1', NaN, 'Educational adventure and puzzle platforming.', 'Find the treasure before the Pirate Pig gets there.', 'A fun-filled pirate adventure with Dora and her crew.', 'The Search for Pirate Pig''s Treasure features 2D exploration and simple puzzles. Help Dora navigate the Seven Seas and solve the clues to find the ultimate hidden prize.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Doraemon Board Game (J)(Rapid Fire)', '2001', NaN, 'Epoch', '4', NaN, 'Digital board game.', 'Compete with Doraemon and friends to win the board.', 'A fun, gadget-filled board game starring the robotic cat.', 'Doraemon Board Game features classic tabletop mechanics with a twist. Use Doraemon’s famous secret gadgets to hinder your opponents and navigate the board in this charming Japanese-exclusive title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Doraemon Midori No Wakusei (J)(Perversion)', '2001', NaN, 'Epoch', '1', NaN, 'Action-adventure and RPG.', 'Save the Green Planet from environmental destruction.', 'An eco-friendly adventure featuring Doraemon and Nobita.', 'Doraemon Midori No Wakusei (Green Planet) combines exploration and puzzle-solving. Use gadgets to restore nature and battle enemies in a vibrant world, following an original story based on the beloved anime.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Double Dragon Advance (J)(Rising Sun)', '2003', NaN, 'Million', '2', NaN, 'Side-scrolling beat ''em up.', 'Rescue Marian and defeat the Shadow Warriors.', 'A definitive remake of the legendary arcade brawler.', 'Double Dragon Advance (Japanese version) is widely considered the best entry in the series. It combines moves from the arcade and NES versions, featuring fluid combat, new weapons, and iconic urban stages.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Double Dragon Advance (U)(Mode7)', '2003', NaN, 'Million', '2', NaN, 'Side-scrolling beat ''em up.', 'Rescue Marian and defeat the Shadow Warriors.', 'A definitive remake of the legendary arcade brawler.', 'The US version of Double Dragon Advance offers high-octane martial arts action. Play as Billy or Jimmy Lee, mastering the new combat mechanics and taking down bosses in this polished GBA action masterpiece.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Doubutsu no Shima no Chobi Gurumi (J)(Trashman)', '2003', NaN, 'MTO', '1', NaN, 'Virtual pet and social simulation.', 'Care for cute animals on a peaceful tropical island.', 'A relaxing animal-care simulation for the GBA.', 'Doubutsu no Shima no Chobi Gurumi allows you to interact with adorable creatures. Manage their happiness, feed them, and explore the island in this cozy and visually soft Japanese title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Doubutsu Shima no Chubi Gurumi 2 (J)(Caravan)', '2004', NaN, 'MTO', '1', NaN, 'Virtual pet and social simulation.', 'Expand your island and care for even more exotic animals.', 'The charming sequel to the animal island simulation.', 'Doubutsu Shima no Chubi Gurumi 2 features more animal species and improved interaction mini-games. Build a thriving sanctuary and bond with your digital pets in this heartwarming Japanese exclusive.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Downforce (U)(Mode7)', '2003', NaN, 'BottleRocket', '4', NaN, 'Formula-style racing simulation.', 'Win the world championship across international tracks.', 'A fast-paced arcade racer with a focus on aerodynamics.', 'Downforce for GBA offers high-speed Formula racing. Master the racing line, manage your pit stops, and outmaneuver rivals on realistic circuits in this technically impressive handheld racer.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dr Seuss - Green Eggs and Ham (U)(Mode7)', '2003', NaN, 'NewKidCo', '1', NaN, 'Educational mini-games and platforming.', 'Explore the world of Dr. Seuss and learn to read.', 'A whimsical learning adventure based on the classic book.', 'Dr. Seuss - Green Eggs and Ham features colorful levels and rhyming puzzles. Help Sam-I-Am navigate through various environments while engaging in educational activities perfect for early readers.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dr. Muto (E)(Eurasia)', '2002', NaN, 'Midway San Diego', '1', NaN, '3D-style action platformer and puzzle.', 'Collect the scattered DNA to save your planet.', 'Play as a mad scientist who can morph into different creatures.', 'Dr. Muto features unique transformation mechanics. Change into a spider, mouse, or gorilla to solve environmental puzzles and defeat enemies in this quirky and creative GBA adventure.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dr. Seuss'' - The Cat in the Hat (E)(Rising Sun)', '2003', NaN, 'Magenta Software', '1', NaN, '2D side-scrolling platformer.', 'Clean up the house and find the missing fish.', 'A wacky adventure based on the live-action movie.', 'The Cat in the Hat (Europe) lets you use the Cat''s magical umbrella to navigate through chaotic levels. Bounce, float, and solve puzzles to fix the mess before Mom gets home.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dr. Seuss'' - The Cat in the Hat (U)(Eurasia)', '2003', NaN, 'Magenta Software', '1', NaN, '2D side-scrolling platformer.', 'Clean up the house and find the missing fish.', 'A wacky adventure based on the live-action movie.', 'The US version of The Cat in the Hat features vibrant graphics and varied mini-games. Explore the surreal world of the Cat and Thing One and Thing Two in this family-friendly GBA title.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dr. Sudoku (E)(Rising Sun)', '2005', NaN, 'Zoo Digital', '1', NaN, 'Logic-based puzzle game.', 'Fill the 9x9 grid with numbers following Sudoku rules.', 'A comprehensive Sudoku trainer and puzzle collection.', 'Dr. Sudoku (Europe) features over 600 puzzles ranging from easy to diabolical. Includes a tutorial mode to help beginners master the logic and a puzzle creator for infinite replayability.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dr. Sudoku (U)(Trashman)', '2005', NaN, 'Zoo Digital', '1', NaN, 'Logic-based puzzle game.', 'Fill the 9x9 grid with numbers following Sudoku rules.', 'A comprehensive Sudoku trainer and puzzle collection.', 'The US version of Dr. Sudoku offers a clean, user-friendly interface. Test your mental agility with thousands of combinations and improve your solving speed in this portable logic masterclass.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dragon Ball - Advance Adventure (J)(Rising Sun)', '2004', NaN, 'Dimps', '1', NaN, 'Side-scrolling action and combat.', 'Relive Goku''s journey from the beginning of Dragon Ball.', 'An incredible action-platformer featuring young Goku.', 'Dragon Ball - Advance Adventure covers the search for the Dragon Balls and the Red Ribbon Army saga. Featuring fluid combat, hover-cloud levels, and 1-on-1 tournament battles, it''s a series highlight.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dragon Ball - Advance Adventure (K)(Independent)', '2004', NaN, 'Dimps', '1', NaN, 'Side-scrolling action and combat.', 'Relive Goku''s journey from the beginning of Dragon Ball.', 'The Korean-localized version of Goku''s early adventures.', 'Experience the high-energy combat of Advance Adventure in this Korean release. Master Goku''s Power Pole and Kamehameha to defeat iconic villains like Mercenary Tao and King Piccolo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dragon Ball - Advanced Adventure (U)(Ongaku)', '2004', NaN, 'Dimps', '1', NaN, 'Side-scrolling action and combat.', 'Relive Goku''s journey from the beginning of Dragon Ball.', 'The US version of the acclaimed GBA action-adventure.', 'Dragon Ball: Advanced Adventure (US) is praised for its faithful art style and deep combat system. Unlock dozens of characters for the 1v1 mode and explore vast 2D levels in this handheld classic.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dragon Ball GT - Transformation (U)(Trashman)', '2005', NaN, 'Webfoot Technologies', '1', NaN, 'Side-scrolling beat ''em up and shooter.', 'Battle through the GT timeline to defeat Baby.', 'A multi-genre action game based on the Dragon Ball GT anime.', 'Dragon Ball GT: Transformation lets you control Goku, Pan, and Trunks. Fight through waves of enemies in brawler stages or take to the skies in flight-shooter segments to save the galaxy.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('GAMEBOYADVANCE', 'Dragon Ball Z - Bukuu Tougeki (J)(Eurasia)', '2004', NaN, 'Cavia', '2', 2, '2D aerial fighting game.', 'Win the Budokai tournament with your favorite Z-fighter.', 'A fast-paced fighter known as Supersonic Warriors.', 'Dragon Ball Z - Bukuu Tougeki (Supersonic Warriors) features intense 3-on-3 aerial combat. Experience What If storylines and master devastating ultimate attacks in this high-speed Japanese fighter.', NULL);
