INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'After Burner Complete (Europe)', '1995', NaN, 'Sega AM2', '1', NaN, 'Arcade shooter with fast-paced aerial combat', 'Player must shoot down enemy aircraft and avoid being shot to progress', 'Vuela a la velocidad del sonido en esta conversión perfecta del clásico arcade de SEGA para 32X.', 'After Burner Complete es la versión definitiva del legendario shooter de combate aéreo de SEGA. Gracias a la potencia del 32X, este título ofrece una tasa de frames fluida y colores vibrantes que superan con creces a la versión de Genesis/Mega Drive. Si buscas acción frenética, disparos de misiles y una banda sonora icónica de los salones recreativos, este es un imprescindible en tu colección de 1995.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'After Burner Complete ~ After Burner (Japan, USA)', '1995', NaN, 'Sega AM2', '1', NaN, 'Arcade shooter with fast-paced aerial combat', 'Player must shoot down enemy aircraft and avoid being shot to progress', 'Vuela a la velocidad del sonido en esta conversión perfecta del clásico arcade de SEGA para 32X.', 'After Burner Complete es la versión definitiva del legendario shooter de combate aéreo de SEGA. Gracias a la potencia del 32X, este título ofrece una tasa de frames fluida y colores vibrantes que superan con creces a la versión de Genesis/Mega Drive. Si buscas acción frenética, disparos de misiles y una banda sonora icónica de los salones recreativos, este es un imprescindible en tu colección de 1995.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Amazing Spider-Man, The - Web of Fire (USA)', '1996', NaN, 'Software Creations', '1', NaN, 'Side-scrolling beat ''em up with platforming elements', 'Player controls Spider-Man to fight enemies and complete levels', 'Ayuda a Spider-Man a detener a Hydra en este escaso y valioso título de acción lateral para la 32X.', 'The Amazing Spider-Man: Web of Fire es uno de los juegos más raros y buscados del catálogo de Sega 32X. Desarrollado por BlueSky Software, este plataformas de acción te pone en la piel del trepamuros con animaciones fluidas y niveles detallados. Enfrenta a la organización Hydra y disfruta de uno de los cierres técnicos más potentes de la consola. ¡Una pieza de culto para coleccionistas de Marvel!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Bad Apple!! in Sonic 1 (32X)', '2010', NaN, 'Homebrew / Fan project', '1', NaN, 'Unique remix/mod with rhythm and platform elements', 'Player completes challenges with rhythm timing and puzzle solving', 'El famoso video musical Bad Apple!! recreado de forma increíble dentro del motor de Sonic 1 para 32X.', 'Bad Apple!! in Sonic 1 es una proeza técnica del homebrew moderno para la Sega 32X. Utilizando los chips gemelos de la consola, este port logra reproducir el icónico video musical de Touhou con una fidelidad que parecía imposible en hardware de los 90. Es la demostración perfecta del potencial oculto del sistema, ideal para fans de la escena técnica y las modificaciones de Sonic the Hedgehog.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'BC Racers (USA)', '1994', NaN, 'Core Design', '1–2', NaN, 'Arcade-style racing with prehistoric theme', 'Player races opponents in various tracks, aiming to finish first', 'Carreras prehistóricas llenas de humor y velocidad en el universo de Chuck Rock para 32X.', 'BC Racers lleva las alocadas carreras de la Edad de Piedra al siguiente nivel con el hardware de 32 bits. Diseñado por el legendario Toby Gard, este juego ofrece circuitos coloridos, escalado de objetos suave y una jugabilidad competitiva que mezcla velocidad con combate. ¡Acelera con tus cavernícolas favoritos en una de las mejores experiencias de conducción del periférico de SEGA!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Blackthorne (USA)', '1994', NaN, 'Blizzard Entertainment', '1', NaN, 'Side-scrolling action/platformer', 'Player navigates levels, defeats enemies, and solves puzzles to progress', 'Acción cinemática y disparos en un mundo oscuro de fantasía desarrollado por Blizzard para 32X.', 'Blackthorne (también conocido como Blackhawk) destaca en la 32X por su atmósfera madura y su estilo de plataformas cinematográfico. En este juego de Blizzard Entertainment, controlas a Kyle Vlaros en una misión de venganza con intensos tiroteos y coberturas. La versión de 32X brilla con una paleta de colores expandida y fondos pre-renderizados que le dan un aspecto visual único frente a otras consolas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Brutal Unleashed - Above the Claw (USA)', '1995', NaN, 'GameTek', '1–2', NaN, 'Fighting game with beast-themed characters', 'Player fights opponents in one-on-one combat to win matches', 'Animales antropomórficos se enfrentan en este sangriento y mejorado juego de lucha para 32X.', 'Brutal Unleashed: Above the Claw es la versión potenciada del juego de lucha original, aprovechando el color y sonido del 32X. Con nuevos personajes y movimientos finales, este título ofrece una experiencia de combate bizarra y divertida. Si te gustan los juegos de pelea con un toque diferente y personajes memorables, esta versión Unleashed es la forma definitiva de jugarlo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Chaotix ~ Knuckles'' Chaotix (Japan, USA)', '1995', NaN, 'Sega', '1–2', NaN, 'Platformer with unique tether mechanics', 'Player uses tether to navigate levels and collect items', 'Knuckles protagoniza una aventura única con mecánicas de unión elástica y gráficos vibrantes.', 'Knuckles'' Chaotix es el estandarte de la Sega 32X y una joya técnica del universo Sonic. Con su innovador sistema de compañeros unidos por un anillo, ofrece mecánicas de física únicas y niveles psicodélicos llenos de color. Es un juego obligatorio para entender el legado de Knuckles y disfrutar de una de las mejores bandas sonoras y apartados gráficos de toda la era de 16/32 bits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Cosmic Carnage (Europe)', '1994', NaN, 'Sega', '1–2', NaN, '3D fighting game with sci-fi characters', 'Player fights in arenas to defeat opponents in combat rounds', 'Cruentas batallas espaciales con fatalities y armaduras destructibles en este fighter de 32X.', 'Cosmic Carnage (conocido como Cyber Brawl en Japón) es un juego de lucha 2D que destaca por sus enormes sprites y efectos de escalado. Ambientado en una prisión espacial, permite a los jugadores personalizar sus guerreros con armaduras que se rompen durante el combate. Un título visceral que muestra el potencial del hardware para manejar gráficos grandes y detallados sin ralentizaciones.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Cyber Brawl ~ Cosmic Carnage (Japan, USA)', '1994', NaN, 'Sega', '1–2', NaN, 'Fighting game with futuristic setting', 'Player battles opponents using combos and special moves', 'La versión original japonesa de Cosmic Carnage con personajes humanos y acción de lucha 2D.', 'Cyber Brawl es la edición original de Cosmic Carnage, donde los luchadores mantienen sus diseños humanos y alienígenas originales. Este juego de pelea para 32X es famoso por su zoom dinámico y su jugabilidad arcade. Si buscas experimentar la versión sin censura y con el balance original de dificultad, Cyber Brawl es una pieza fascinante de la historia de SEGA en Japón.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Darxide (Europe) (En,Fr,De,Es)', '1995', NaN, 'Sega', '1', NaN, 'Space shooter with 3D environments', 'Player pilots a ship to destroy enemies and complete missions', 'Un ambicioso shooter espacial en 3D que exprime al máximo los polígonos de la Sega 32X.', 'Darxide es un hito técnico para la 32X, siendo uno de los pocos juegos que utiliza polígonos con texturas de forma intensiva. En este shooter espacial de Frontier Developments, deberás destruir asteroides y naves enemigas para salvar a la humanidad. Por su rareza (solo salió en Europa) y su calidad gráfica, es considerado el santo grial para los entusiastas de los gráficos 3D retro.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Doom (Europe)', '1995', NaN, 'id Software / Sega', '1', NaN, 'Classic FPS with fast-paced shooting and exploration', 'Player navigates levels, defeating enemies and finding keys to progress', 'El rey de los FPS llega a la 32X con una versión fluida y rápida de la masacre en Marte.', 'Doom en Sega 32X fue la puerta de entrada a los shooters en primera persona para muchos usuarios de consola. Esta versión europea ofrece una jugabilidad rápida, respetando el diseño de niveles icónico de id Software. Aunque tiene el famoso borde en pantalla, la velocidad de movimiento y la respuesta de los controles lo convierten en una de las formas más divertidas y nostálgicas de jugar a Doom en hardware original de SEGA.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Doom (Japan, USA)', '1995', NaN, 'id Software / Sega', '1', NaN, 'Classic FPS with fast-paced shooting and exploration', 'Player navigates levels, defeating enemies and finding keys to progress', 'El legendario shooter de id Software optimizado para los chips gemelos de la Sega 32X.', 'Doom para Sega 32X es un hito de los FPS en consolas. Esta versión para los mercados de Japón y USA aprovecha el hardware de 32 bits para ofrecer una experiencia de juego rápida y frenética. Aunque es conocida por su marco en pantalla, la fluidez del movimiento y la acción visceral de derrotar demonios en Marte la convierten en una pieza esencial para cualquier coleccionista de SEGA.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Doom 32X Resurrection v2.2b', '2015*', NaN, 'Homebrew / Fan project', '1', NaN, 'Enhanced/modified FPS version with updated levels', 'Player completes missions by defeating monsters and clearing areas', 'La asombrosa mejora moderna (homebrew) que lleva a Doom en 32X a un nivel técnico superior.', 'Doom 32X Resurrection es un proyecto de fans que redefine lo que el hardware de 32X puede hacer. Esta versión v2.2b corrige errores del original, añade música de alta calidad, pantalla completa y una tasa de frames por segundo muy superior. Es la forma definitiva y moderna de disfrutar el clásico Doom en tu hardware original o mediante emulación, demostrando el verdadero poder de la consola.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'FIFA Soccer ''96 (Europe) (En,Fr,De,Es,It,Sv)', '1995', NaN, 'Extended Play Productions', '1–4', NaN, 'Arcade-style soccer simulation', 'Player controls a soccer team to win matches and tournaments', 'El simulador de fútbol más famoso del mundo debuta con gráficos de 32 bits en el periférico de SEGA.', 'FIFA Soccer ''96 llegó a la 32X europea ofreciendo una mejora visual significativa respecto a la versión de Mega Drive. Con estadios más detallados, animaciones fluidas y todas las licencias oficiales de la época, este título representó el salto del fútbol hacia la era de los 32 bits. Un clásico deportivo imprescindible para los nostálgicos de las ligas europeas de mediados de los 90.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'GameTap, Cup Noodles, and Bitter Tears', '???', NaN, 'GameTap', '?', NaN, 'Unknown / Possibly a niche or promotional title', 'Unknown objective (could be narrative or exploration based)', 'Una curiosa y experimental pieza de software homebrew que explora los límites creativos del 32X.', 'GameTap, Cup Noodles, and Bitter Tears es una demostración técnica y artística dentro de la escena homebrew del 32X. Este tipo de lanzamientos son valorados por la comunidad por su originalidad y por cómo utilizan el hardware de forma no convencional. Es un ejemplo perfecto de la vitalidad actual de la escena de desarrollo independiente para consolas retro de SEGA.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Golden Axe 32X edition', '1994', NaN, 'Sega', '1–2', NaN, 'Side-scrolling hack and slash', 'Player fights enemies through levels to defeat the evil tyrant', 'El clásico arcade de SEGA recibe un tratamiento visual mejorado en esta versión para 32X.', 'Golden Axe 32X edition es una reimaginación del legendario beat ''em up que aprovecha la paleta de colores extendida del hardware. Los jugadores pueden disfrutar de la clásica lucha contra Death Adder con fondos más detallados y efectos visuales que no eran posibles en la Genesis estándar. Es la mezcla perfecta de jugabilidad retro con la potencia adicional de los 32 bits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Golf Magazine 36 Great Holes Starring Fred Couples (Europe)', '1995', NaN, 'Gremlin Interactive', '1–4', NaN, 'Realistic golf simulation', 'Player aims to complete golf courses with as few strokes as possible', 'Simulación de golf profesional con gráficos digitalizados y la firma de Fred Couples.', 'Golf Magazine 36 Great Holes ofrece una experiencia de golf realista para la 32X europea. Gracias al hardware, el juego presenta escalado de objetos suave y texturas detalladas en los campos. Con el asesoramiento del profesional Fred Couples, es uno de los simuladores deportivos más profundos y visualmente atractivos del catálogo del periférico.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Golf Magazine 36 Great Holes Starring Fred Couples (Japan, USA)', '1995', NaN, 'Gremlin Interactive', '1–4', NaN, 'Realistic golf simulation', 'Player aims to complete golf courses with as few strokes as possible', 'El simulador de golf líder de 32X con campos hiperrealistas y jugabilidad profesional.', 'Esta versión para Japón y USA de Golf Magazine 36 Great Holes destaca por su uso de gráficos digitalizados y una interfaz intuitiva. El juego aprovecha los procesadores SH-2 para calcular físicas de tiro precisas, ofreciendo 36 hoyos icónicos y el desafío de jugar como (o contra) Fred Couples en una de las mejores representaciones de este deporte en los 90.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Knuckles'' Chaotix (Europe)', '1995', NaN, 'Sega', '1–2', NaN, 'Platformer with unique tether mechanics', 'Player uses tether to navigate levels and collect items', 'La exclusiva aventura de Knuckles llega a Europa con colores vibrantes y jugabilidad cooperativa.', 'Knuckles'' Chaotix es el título más emblemático de la 32X. En su versión europea, el juego brilla por su innovador sistema de compañeros unidos por elásticos, que permite mecánicas de velocidad únicas. Con gráficos que parecen una caricatura en movimiento y una banda sonora funk inolvidable, es la joya de la corona del catálogo de 32 bits de SEGA.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Knuckles'' Chaotix (Feb 2, 1995 prototype)', '1995', NaN, 'Sega', '1–2', NaN, 'Platformer with unique tether mechanics', 'Player uses tether to navigate levels and collect items', 'Explora el desarrollo de SEGA con este prototipo temprano del juego más famoso de la 32X.', 'El prototipo de Knuckles'' Chaotix (2 de febrero de 1995) es una pieza histórica invaluable. Esta versión permite a los fans y arqueólogos digitales ver mecánicas sin terminar, diferencias gráficas y niveles en estado de desarrollo. Es una mirada fascinante al proceso creativo detrás de uno de los juegos más complejos y coloridos de la historia de SEGA.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Knuckles'' Clackers', '1995', NaN, 'Sega', '1', NaN, 'Clacking ball game where players keep balls in motion', 'Player competes to keep balls bouncing and score points', 'Un divertido mini-juego basado en la física y el universo de Knuckles'' Chaotix.', 'Knuckles'' Clackers es una curiosidad técnica que se centra en las mecánicas de colisión y física de los personajes de Chaotix. Aunque es sencillo en concepto, sirve como una excelente demostración de cómo el 32X maneja múltiples objetos y sprites en pantalla con fluidez. Un complemento ideal para los entusiastas que quieren ver cada rincón de la franquicia de Knuckles.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Kolibri (USA, Europe)', '1995', NaN, 'Sega', '1', NaN, 'Unique hummingbird platformer with shooting mechanics', 'Player navigates levels, defeating enemies and collecting items', 'Un shooter atípico y hermoso donde controlas a un colibrí para salvar la naturaleza.', 'Kolibri es, sin duda, uno de los juegos visualmente más impresionantes de la 32X. Creado por los desarrolladores de Ecco the Dolphin, este shmup te pone al mando de un colibrí en un entorno natural exuberante. Con fondos que parecen pinturas y una atmósfera relajante pero desafiante, es una experiencia única que justifica por sí sola la existencia del periférico.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Metal Head (Europe) (En,Ja)', '1995', NaN, 'Novotrade International', '1', NaN, 'Tactical mech combat game', 'Player pilots a mech to complete missions and defeat enemies', 'Combate de mechas en 3D real con texturas mapeadas en esta potencia técnica para 32X.', 'Metal Head fue la respuesta de SEGA a la demanda de gráficos 3D poligonales. En esta versión europea, pilotas un mecha masivo a través de ciudades detalladas con mapeado de texturas, algo revolucionario para la época en consolas. Es un despliegue de fuerza técnica que muestra de qué eran capaces los procesadores duales del 32X en el género de la simulación de combate.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Metal Head (Japan, USA) (En,Ja)', '1995', NaN, 'Sega', '1', NaN, 'Tactical mech combat game', 'Player pilots a mech to complete missions and defeat enemies', 'Combate de tanques bípedos en 3D real con una potencia gráfica sin precedentes en 32X.', 'Metal Head para los mercados de Japón y USA es un escaparate tecnológico que muestra el poder poligonal del 32X. Pilota un mecha avanzado en misiones de paz urbana con gráficos totalmente texturizados en 3D. Esta versión permite experimentar la visión original de SEGA para el combate de robots, ofreciendo una atmósfera inmersiva y un apartado técnico que desafiaba a las consolas de su tiempo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Mortal Kombat II (Europe)', '1994', NaN, 'Sega', '1–2', NaN, 'Fighting game with special moves and fatalities', 'Player wins matches by defeating opponents in combat', 'La lucha definitiva llega a los 32 bits con una conversión casi perfecta del arcade original.', 'Mortal Kombat II en su versión europea para 32X es, para muchos, la mejor edición doméstica de los 90. Con colores más intensos, sprites más grandes y una banda sonora superior a la de Genesis, ofrece toda la brutalidad de los Fatality con una fidelidad asombrosa. ¡El torneo de Outworld nunca se vio tan bien en una consola de SEGA!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Mortal Kombat II (Japan, USA)', '1994', NaN, 'Midway', '1–2', NaN, 'Fighting game with special moves and fatalities', 'Player wins matches by defeating opponents in combat', 'Sangre, Fatalities y acción fluida en la versión más potente de MKII para el ecosistema SEGA.', 'Disfruta de Mortal Kombat II en tu 32X (USA/Japan) con una calidad que rivaliza con el arcade. Esta versión aprovecha el hardware para mejorar los fondos y la fluidez de los movimientos de Liu Kang, Scorpion y compañía. Es una pieza esencial para los amantes de los juegos de lucha que buscan la experiencia más sangrienta y técnica de la era de los 32 bits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Motocross Championship (Europe)', '1995', NaN, 'Midway', '1–2', NaN, 'Motocross racing game', 'Player races motocross tracks aiming to finish first', 'Carreras de motos llenas de barro y saltos acrobáticos en los circuitos europeos de 32X.', 'Motocross Championship lleva la adrenalina del motor al periférico de SEGA. Con un enfoque en la velocidad y el manejo técnico, esta versión europea destaca por sus circuitos desafiantes y una perspectiva que aprovecha el escalado de objetos del 32X. ¡Enfrenta a tus rivales y domina el podio en esta competencia de motocross retro!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Motocross Championship (USA)', '1995', NaN, 'Sega Technical Institute', '1–2', NaN, 'Motocross racing game', 'Player races motocross tracks aiming to finish first', 'Siente la velocidad y el rugido de los motores en este potente simulador de Motocross para 32X.', 'En Motocross Championship para USA, la experiencia de carreras se vuelve más intensa gracias al hardware de 32 bits. El juego ofrece múltiples cámaras, personalización de motos y una física de saltos mejorada respecto a los 16 bits. Es el título ideal para los fans del deporte extremo que quieren ver de qué era capaz la seta de SEGA.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'NBA Jam - Tournament Edition (World)', '1994', NaN, 'Unknown / Prototype', '1–4', NaN, 'Arcade basketball with exaggerated moves', 'Player wins basketball games by scoring more points than the opponent', '¡He’s on fire! El basket arcade más famoso del mundo llega con mejoras gráficas a la 32X.', 'NBA Jam - Tournament Edition es la versión definitiva del clásico 2 contra 2 para los fans de SEGA. Con jugadores digitalizados más grandes, nuevas leyendas de la NBA y un ritmo de juego frenético, esta edición mundial aprovecha el 32X para eliminar las limitaciones de color de la Mega Drive, ofreciendo un espectáculo visual y sonoro inigualable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'NFL Quarterback Club (World)', '1994', NaN, 'High Voltage Software', '1–4', NaN, 'Football simulation focusing on quarterback play', 'Player leads team to victory by executing plays and scoring touchdowns', 'La simulación de fútbol americano más completa con gráficos realistas y licencias oficiales.', 'NFL Quarterback Club para 32X eleva el estándar de los juegos deportivos. Con una perspectiva de cámara dinámica y sprites detallados, te permite vivir la emoción de la NFL como nunca antes. Esta versión mundial incluye múltiples modos de juego y una jugabilidad profunda que deleitará a los estrategas del emparrillado.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Parasquad ~ Zaxxon''s Motherbase 2000 (Japan, USA)', '1994', NaN, 'Bitmasters', '1', NaN, 'Tactical squad-based shooter with sci-fi elements', 'Player commands a squad to complete missions and defeat enemies', 'El renacimiento de un clásico: disparos isométricos y acción futurista en 3D para 32X.', 'Parasquad (conocido como Zaxxon''s Motherbase 2000) reinventa la mítica saga Zaxxon con gráficos poligonales. Este shooter isométrico te permite saltar sobre naves enemigas para robar sus habilidades, ofreciendo una capa táctica única. Es una joya visual del 32X que mezcla la jugabilidad clásica con la estética vanguardista de mediados de los 90.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Pinocchio 32x (Dec 6, 1995 prototype)', '1995*', NaN, 'Sega', '1', NaN, 'Platformer with Pinocchio-themed story', 'Player navigates levels, avoids obstacles, and solves puzzles', 'Una mirada exclusiva al juego cancelado de Disney: el potencial gráfico de Pinocchio en 32X.', 'El prototipo de Pinocchio (6 de diciembre de 1995) es un tesoro para los entusiastas del software perdido. Aunque nunca llegó a las tiendas, esta versión muestra cómo Disney planeaba usar el 32X para mejorar los colores y planos de scroll de la versión de 16 bits. Una pieza de historia que revela la transición de SEGA hacia los 32 bits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Pitfall - The Mayan Adventure (USA)', '1994', NaN, 'Midway', '1', NaN, 'Classic platformer with exploration and action', 'Player explores jungles, avoids traps, and collects treasures', 'Harry Jr. regresa en una aventura selvática con gráficos mejorados y niveles secretos.', 'Pitfall - The Mayan Adventure en 32X es la versión visualmente más rica de este plataformas clásico. Con una paleta de colores vibrante que hace justicia a la jungla maya y animaciones fluidas estilo película, esta edición de USA es un viaje nostálgico lleno de peligros, lianas y tesoros ocultos que aprovecha el extra de potencia del sistema.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Primal Rage (USA, Europe)', '1995', NaN, 'Midway', '1–2', NaN, 'Fighting game featuring prehistoric creatures', 'Player fights opponents using special moves and combos', 'Dinosaurios y bestias gigantes luchan por el dominio de la Tierra en este violento juego de pelea.', 'Primal Rage traslada la brutalidad de los dioses prehistóricos a la 32X con una fidelidad asombrosa al arcade. Con gráficos stop-motion digitalizados y movimientos finales devastadores, esta versión es superior en color y detalle a cualquier otra de la época. ¡Domina a tus rivales y convierte a la humanidad en tus seguidores en este fighter de culto!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'RBI Baseball ''95 (USA)', '1995', NaN, 'Unknown', '1–4', NaN, 'Baseball simulation with real teams and players', 'Player manages team and plays baseball games aiming to win', 'El clásico del diamante regresa con estadísticas actualizadas y jugabilidad arcade en 32X.', 'RBI Baseball ''95 ofrece a los fans del béisbol una experiencia rápida y accesible. Esta versión para 32X mejora los gráficos de los estadios y los retratos de los jugadores, manteniendo la jugabilidad sencilla que hizo famosa a la serie. Es el título perfecto para disfrutar de un partido rápido con toda la atmósfera de las Grandes Ligas de 1995.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Sangokushi IV (Japan)', '1995', NaN, 'Unknown', '1', NaN, 'Strategy RPG set in historical China', 'Player manages resources and battles in turn-based combat', 'Estrategia profunda y conquista histórica en la versión de 32 bits de Romance of the Three Kingdoms.', 'Sangokushi IV (Romance of the Three Kingdoms IV) para la 32X japonesa es la cúspide de la estrategia histórica de Koei en SEGA. Gracias al hardware superior, esta versión presenta retratos más detallados, una interfaz pulida y tiempos de carga optimizados. Sumérgete en la antigua China y lidera tus ejércitos hacia la unificación en este título esencial para los fans de la simulación táctica.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Shadow Squadron ~ Stellar Assault (USA, Europe)', '1995', NaN, 'Sega AM7', '1', NaN, 'Space combat simulator', 'Player pilots spacecraft to complete missions and destroy enemies', 'Intenso combate espacial en 3D con polígonos fluidos y misiones épicas en el espacio.', 'Shadow Squadron (conocido como Stellar Assault en Europa) es uno de los mejores simuladores de combate espacial de los 90. Aprovechando el motor poligonal de la 32X, ofrece una libertad de movimiento total y batallas contra naves nodrizas gigantescas. Es una demostración perfecta de cómo los procesadores SH-2 podían manejar entornos 3D complejos con una tasa de frames envidiable.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Sonic 1 in Space for the 32x', '1995', NaN, 'Sega AM7', '1', NaN, 'Platformer with Sonic characters in a space setting', 'Player runs and jumps through levels defeating enemies and collecting rings', 'Una reinvención galáctica del primer Sonic, aprovechando el color y la potencia del 32X.', 'Sonic 1 in Space es un hack creativo que transporta los niveles clásicos de Sonic the Hedgehog a entornos espaciales con paletas de colores expandidas. Al ejecutarse en el hardware de 32X, el juego se beneficia de fondos más ricos y efectos visuales que no eran posibles en la consola original, ofreciendo una experiencia fresca y nostálgica para los fans del erizo.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Sonic 4: Cybernetic Outbreak', '1995', NaN, 'Homebrew / Fan project', '1', NaN, 'Platformer featuring Sonic in a new adventure', 'Player completes levels collecting rings and defeating bosses', 'Un ambicioso proyecto homebrew que imagina una secuela futurista de Sonic para 32X.', 'Sonic 4: Cybernetic Outbreak es una de las modificaciones más interesantes de la escena retro. Este título lleva a Sonic a un mundo tecnológico y oscuro, utilizando el potencial gráfico de la 32X para ofrecer nuevos sprites, niveles rediseñados y una banda sonora técnica. Es el ejemplo ideal de cómo la comunidad mantiene viva la llama del 32 bits de SEGA.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Sonic in Chaotix', '1995', NaN, 'Homebrew / Fan project', '1', NaN, 'Platformer spin-off with new gameplay mechanics', 'Player navigates levels using unique partner mechanics and collects items', 'El crossover definitivo: Sonic el Erizo se une al elenco de Knuckles'' Chaotix.', 'Sonic in Chaotix permite a los jugadores experimentar la jugabilidad única de Chaotix controlando al mismísimo Sonic. Este hack integra perfectamente el sprite del erizo en las mecánicas de unión elástica, permitiendo ver cómo se comportaría el icono de SEGA en el mundo colorido y técnicamente avanzado de la 32X. ¡Imprescindible para los completistas de Sonic!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Sonic in Chaotix - Revision 2', '1995', NaN, 'Homebrew / Fan project', '1', NaN, 'Platformer con mecánicas de compañero', 'Player avanza en niveles usando habilidades de pareja para superar obstáculos y enemigos', 'La versión pulida y mejorada del mod que introduce a Sonic en el motor de Chaotix.', 'Sonic in Chaotix - Revision 2 mejora la integración de Sonic en el juego estrella de la 32X. Con correcciones en las animaciones y una física más ajustada, esta revisión ofrece una experiencia más estable y fluida. Es la forma más refinada de jugar a Chaotix con el protagonista original de la saga, aprovechando cada bit de potencia de la consola.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Soulstar X (USA) (Proto)', '1995*', NaN, 'Homebrew / Fan project', '1', NaN, 'Space shooter con desplazamiento en 3D', 'Player controla nave para eliminar oleadas de enemigos y evitar ataques', 'Un prototipo impresionante de shooter espacial que prometía ser un referente gráfico en 32X.', 'Soulstar X es uno de los qué hubiera pasado si... más famosos de SEGA. Este prototipo muestra un shooter con escalado de objetos masivo y gráficos pre-renderizados que empujaban al 32X a sus límites. Explorar este prototipo es descubrir una joya técnica que, aunque no llegó a las tiendas, demostró que el hardware podía competir con la nueva generación.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Space Harrier (Europe)', '1995', NaN, 'Prototype / Unknown', '1', NaN, 'Juego arcade de disparos con desplazamiento rápido', 'Player vuela y dispara a enemigos mientras esquiva obstáculos en niveles verticales', 'El clásico Into the Fantasy Zone de Yu Suzuki llega con una conversión perfecta a la 32X.', 'Space Harrier en su versión europea es un port Arcade Perfect. Gracias a los procesadores duales, la 32X maneja el escalado frenético de objetos y los colores vibrantes del arcade original de 1985 sin despeinarse. Es una experiencia psicodélica y veloz que todo dueño de una 32X debe tener para revivir la gloria de los salones recreativos.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Space Harrier (Japan, USA)', '1995', NaN, 'Sega', '1', NaN, 'Juego arcade de disparos con desplazamiento rápido', 'Player vuela y dispara a enemigos mientras esquiva obstáculos en niveles verticales', 'Disfruta de la acción arcade definitiva con esta versión de lujo de Space Harrier para 32X.', 'La versión para Japón y USA de Space Harrier es testimonio del compromiso de SEGA con sus clásicos. Con una tasa de frames constante y una fidelidad visual asombrosa, esta edición supera a cualquier versión previa de 8 o 16 bits. Vuela sobre dragones y esquiva pilares en uno de los shooters más icónicos de la historia, ahora potenciado por los 32 bits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Spot Goes To Hollywood 32x (Prototype)', '1994*', NaN, 'Sega', '1', NaN, 'Platformer con personaje Spot', 'Player supera niveles con saltos, recogiendo objetos y evitando enemigos', 'La mascota de 7-Up salta a las 3D isométricas en este prototipo avanzado para 32X.', 'Spot Goes To Hollywood en su versión prototipo para 32X ofrece una perspectiva isométrica con gráficos mucho más detallados que la versión de Genesis. Este título muestra niveles inspirados en géneros cinematográficos con efectos de luz y sombras mejorados. Una pieza de colección digital que muestra la transición de las mascotas de los 16 a los 32 bits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Star Trek Starfleet Academy - Starship Bridge Simulator (USA)', '1995', NaN, 'Prototype / Unknown', '1', NaN, 'Simulación de comando de nave espacial', 'Player gestiona diferentes sistemas de la nave para completar misiones', 'Toma el mando del puente de mando y gradúate en la academia más prestigiosa de la galaxia.', 'Star Trek Starfleet Academy - Starship Bridge Simulator es un simulador profundo que pone a prueba tus dotes de mando. En la 32X, el juego ofrece gráficos digitalizados y secuencias de combate espacial que aprovechan la potencia del sistema para crear una atmósfera inmersiva de ciencia ficción. ¡Ideal para los Trekkies que buscan una experiencia táctica!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Star Wars Arcade (Europe)', '1994', NaN, 'Sega', '1', NaN, 'Juego de disparos en el universo Star Wars', 'Player pilota nave espacial para destruir enemigos y completar misiones', '¡Que la Fuerza te acompañe! Pilota un X-Wing en esta impresionante conversión arcade.', 'Star Wars Arcade fue uno de los títulos de lanzamiento que demostró el potencial 3D de la 32X. En esta versión europea, podrás revivir el asalto a la Estrella de la Muerte con polígonos sólidos y una jugabilidad de combate espacial emocionante. Es un título histórico que trajo la experiencia de las máquinas recreativas de SEGA directamente al salón de tu casa.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Star Wars Arcade (Japan)', '1994', NaN, 'LucasArts', '1', NaN, 'Juego de disparos en el universo Star Wars', 'Player pilota nave espacial para destruir enemigos y completar misiones', 'La épica batalla galáctica de SEGA llega a la 32X japonesa con gráficos 3D poligonales.', 'Star Wars Arcade para 32X es una de las conversiones más ambiciosas del hardware. Pilotá un X-Wing o un Y-Wing a través de campos de asteroides y enfrentate a cazas TIE en 3D real. La versión japonesa mantiene la fluidez y la emoción de la recreativa de Model 1, permitiendo a los fans de la saga vivir el asalto a la Estrella de la Muerte con una potencia técnica asombrosa para 1994.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Star Wars Arcade (USA)', '1994', NaN, 'Sega AM3', '1', NaN, 'Juego de disparos en el universo Star Wars', 'Player pilota nave espacial para destruir enemigos y completar misiones', 'Sentí el poder de la Fuerza con este espectacular shooter espacial en 3D para la 32X americana.', 'Star Wars Arcade fue un título de lanzamiento clave que demostró de qué era capaz la seta de SEGA en EE.UU. Con un modo cooperativo único donde un jugador pilota y otro dispara, este juego ofrece polígonos sólidos y una banda sonora icónica. Es una pieza de colección fundamental para cualquier entusiasta de Star Wars y del hardware retro de 32 bits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Stellar Assault (Japan)', '1995', NaN, 'Sega AM3', '1', NaN, 'Disparos en espacio con desplazamiento', 'Player controla nave en niveles de disparos para eliminar enemigos y avanzar', 'El shooter espacial definitivo de 32X con combates cinemáticos y gráficos poligonales.', 'Stellar Assault (conocido como Shadow Squadron en occidente) brilla en su versión japonesa por su jugabilidad técnica y su atmósfera de ciencia ficción. Utilizando los procesadores duales SH-2, ofrece batallas espaciales fluidas y naves enemigas masivas con un estilo visual limpio y futurista. Es considerado uno de los mejores exponentes del catálogo 3D de la consola.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'T-Mek (USA, Europe)', '1994', NaN, 'Sega AM3', '1-2', NaN, 'Disparos vehiculares en arenas', 'Player pilota un tanque futurista para derrotar enemigos en combates vehiculares', 'Combate de tanques futuristas en una arena mortal con acción frenética y efectos 3D.', 'T-Mek traslada la intensidad de la recreativa de Atari a la Sega 32X. En este juego de combate en primera persona, deberás maniobrar tu tanque a través de arenas peligrosas para derrotar a tus oponentes. Gracias a la potencia del 32X, el juego mantiene una velocidad constante y efectos de sonido inmersivos que te transportan directo a una competencia de gladiadores cibernéticos.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Tempo (Dec 29, 1994 prototype)', '1994*', NaN, 'Sega AM3', '1', NaN, 'Platformer rítmico y colorido', 'Player avanza por niveles superando enemigos y obstáculos al ritmo de la música', 'Una mirada exclusiva al desarrollo del juego más musical y colorido de la Sega 32X.', 'El prototipo de Tempo (29 de diciembre de 1994) permite descubrir versiones tempranas de los niveles y mecánicas de este plataformas rítmico. Es una pieza fascinante para historiadores del videojuego, mostrando cómo SEGA buscaba crear una identidad visual vibrante y llena de animaciones fluidas para destacar sobre la Genesis estándar.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Tempo (Japan, USA)', '1995', NaN, 'Atari Games', '1', NaN, 'Platformer rítmico y colorido', 'Player avanza por niveles superando enemigos y obstáculos al ritmo de la música', 'Un estallido de ritmo, color y plataformas en el juego más carismático del sistema 32X.', 'Tempo es pura alegría visual. Encarnando a un saltamontes con mucho estilo, deberás avanzar por niveles llenos de música y enemigos extravagantes. Con una paleta de colores masiva y animaciones que parecen dibujos animados, Tempo es el ejemplo perfecto de cómo el 32X podía potenciar los juegos 2D hasta límites profesionales. ¡Un plataformas único y lleno de ritmo!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Toughman Contest (USA, Europe)', '1995', NaN, 'Sega', '1-2', NaN, 'Simulación de boxeo', 'Player pelea en torneos de boxeo, usando técnicas y defensas para ganar', 'Boxeo visceral y arcade con el estilo rudo del torneo Toughman en tu 32X.', 'Toughman Contest ofrece una experiencia de boxeo en primera persona con sprites grandes y detallados. Esta versión para 32X mejora el color y la fluidez respecto a los 16 bits, permitiéndote sentir cada golpe. Con personajes caricaturescos y una jugabilidad directa, es un título deportivo divertido que captura la esencia de las peleas de bar profesionales de los 90.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Virtua Fighter (Europe)', '1994', NaN, 'Sega', '1-2', NaN, 'Fight game 3D con combos', 'Player pelea uno a uno usando combos y estrategias para ganar torneos', 'La revolución de la lucha 3D llega a Europa con una conversión asombrosamente fiel al arcade.', 'Virtua Fighter en 32X es un milagro técnico. Lograr que los polígonos de la Model 1 se muevan con tal fluidez en una consola doméstica fue un hito. Esta versión europea ofrece toda la profundidad técnica de Akira y compañía, siendo para muchos la versión definitiva para jugar en hardware de SEGA antes de la llegada de la Saturn.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Virtua Fighter (Japan, USA)', '1994', NaN, 'Sega', '1-2', NaN, 'Fight game 3D con combos', 'Player pelea uno a uno usando combos y estrategias para ganar torneos', 'El legendario luchador poligonal de SEGA redefine el género de pelea en la 32X.', 'Disfrutá de la precisión y el realismo de Virtua Fighter en tu 32X (USA/Japan). Este juego eliminó las barreras de los 2D para introducir el combate tridimensional real en el hogar. Con una tasa de frames sólida y controles de respuesta inmediata, sigue siendo una joya del catálogo que demuestra el verdadero propósito del periférico de 32 bits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Virtua Hamster (USA) (Proto)', '1995*', NaN, 'Sega', '1', NaN, 'Aventura con un hámster protagonista', 'Player controla un hámster explorando niveles y superando obstáculos', 'Un prototipo único y bizarro de carreras de hámsters en túneles poligonales 3D.', 'Virtua Hamster es uno de los juegos cancelados más famosos de SEGA. Este prototipo permite ver la idea de manejar a un hámster en un monopatín a través de tubos 3D con texturas. Es una curiosidad técnica invaluable que muestra el espíritu experimental de SEGA durante la transición a la quinta generación de consolas.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Virtua Racing Deluxe (Europe)', '1995', NaN, 'Sega', '1-2', 3, 'Simulación de carreras en 3D', 'Player compite en pistas variadas controlando autos en carreras rápidas', 'La versión definitiva del clásico de carreras con nuevos autos y pistas exclusivas.', 'Virtua Racing Deluxe expande el mito del arcade original. Esta versión europea añade tres tipos de vehículos (Fórmula, Stock y Prototype) y pistas nuevas, aprovechando el 32X para ofrecer polígonos mucho más suaves y coloridos que la versión de Genesis. Es, sin duda, la mejor forma de disfrutar este pionero del 3D en 1994.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Virtua Racing Deluxe (Japan)', '1995', NaN, 'Sega', '1-2', 3, 'Simulación de carreras en 3D', 'Player compite en pistas variadas controlando autos en carreras rápidas', 'Velocidad poligonal de élite en la versión más completa de Virtua Racing para SEGA.', 'Virtua Racing Deluxe en Japón es sinónimo de excelencia técnica. El juego corre con una fluidez envidiable y ofrece un contenido Deluxe que justifica la compra del periférico. Ya sea en modo contrarreloj o compitiendo con los nuevos vehículos, es una demostración magistral de cómo el 32X podía manejar gráficos tridimensionales complejos.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'Virtua Racing Deluxe (USA)', '1995', NaN, 'Midway', '1-2', 3, 'Simulación de carreras en 3D', 'Player compite en pistas variadas controlando autos en carreras rápidas', 'Quemá gomas en 3D real con esta edición mejorada del hit de carreras para 32X.', 'La versión americana de Virtua Racing Deluxe es un imprescindible. Con sus múltiples ángulos de cámara y el añadido de coches de turismo y prototipos, ofrece una rejugabilidad que el arcade no tenía. Es un testimonio de la era dorada de SEGA y su dominio de la tecnología poligonal, adaptada perfectamente al hardware de 32 bits.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'World Series Baseball Starring Deion Sanders (USA)', '1994', NaN, 'Midway', '1-4', NaN, 'Simulación de béisbol', 'Player juega partidos de béisbol, manejando bateo, lanzamiento y defensa', 'Béisbol de alta fidelidad con la estrella Deion Sanders y gráficos de 32 bits.', 'World Series Baseball en 32X lleva el realismo deportivo un paso más allá. Con la imagen de Deion Sanders y estadios renderizados con mayor detalle, esta versión ofrece una jugabilidad profunda y estadísticas completas. La potencia extra del sistema se traduce en animaciones de bateo y lanzamiento mucho más naturales para los fanáticos del diamante.', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'WWF Raw (World)', '1994', NaN, 'Midway', '1-4', NaN, 'Simulación de lucha libre', 'Player controla luchadores y compite en combates de wrestling', 'La lucha libre más famosa del mundo con más luchadores y mejores gráficos en 32X.', 'WWF Raw para 32X es la versión vitaminada del clásico de 16 bits. Con más personajes en pantalla, colores más vivos y movimientos especiales exclusivos, ofrece la experiencia definitiva de la World Wrestling Federation para los fans de SEGA. ¡Subí al ring con Undertaker, Bret Hart o Shawn Michaels y domina el cuadrilátero!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'WWF WrestleMania - The Arcade Game (USA)', '1995', NaN, 'Midway', '1-4', NaN, 'Arcade de lucha libre', 'Player pelea combates arcade con movimientos exagerados y efectos especiales', 'Acción frenética y combos imposibles en este híbrido de lucha libre y juego de pelea.', 'WWF WrestleMania: The Arcade Game en 32X captura la locura del arcade original de Midway. A diferencia de las versiones de 16 bits, aquí los sprites son más grandes y fluidos, manteniendo el ritmo rápido de un juego de lucha tipo Mortal Kombat pero con estrellas de la WWF. ¡Es pura adrenalina arcade en tu consola!', NULL);
INSERT INTO juegos_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('32X', 'X-Men (USA) (Proto)', '1994*', NaN, 'Midway', '1-2', NaN, 'Juego de acción beat ''em up', 'Player controla mutantes X-Men para derrotar enemigos y avanzar niveles', 'Un vistazo exclusivo a lo que pudo ser la aventura de los mutantes en la era 32 bits.', 'El prototipo de X-Men para 32X es una reliquia del software cancelado. Aunque no llegó a terminarse, permite ver cómo SEGA planeaba utilizar la paleta de colores extendida y la capacidad de proceso del sistema para traer a Wolverine y compañía a la nueva generación. Una pieza histórica fascinante para cualquier fan de Marvel y SEGA.', NULL);
